        display: grid;
    }

    .kp-gallery__figure {
        display: grid;
        grid-template-rows: minmax(0, 1fr) minmax(0, auto);
        min-block-size: 0;
        min-inline-size: 0;
    }

    .kp-gallery__picture {
        display: grid;
        place-items: center;
        min-block-size: 0;
        min-inline-size: 0;
        overflow: auto;
        overscroll-behavior: contain;
        touch-action: pan-y pinch-zoom;
    }

    .kp-gallery__image,
    .kp-gallery__video {
        max-inline-size: 100%;
        max-block-size: 100%;
        object-fit: contain;
    }

    .kp-gallery__image {
