    }

    .kp-gallery__text,
    .kp-gallery__meta {
        margin: 0;
        overflow-wrap: anywhere;
    }

    .kp-gallery__meta {
        color: var(--muted-foreground);
        font-size: var(--kp-text-sm, 0.8125rem);
    }

    .kp-gallery__zone {
        position: absolute;
        inset-block: 0;
