    }

    .kp-trace__foot:empty {
        display: none;
    }

    .kp-trace[data-kp-trace-verdict='word'] .kp-steplist--trace .kp-steplist__mark {
        display: none;
    }

    .kp-trace[data-kp-trace-verdict='mark'] .kp-steplist--trace .kp-steplist__time {
