        :is(.kp-trace:not([data-kp-trace-layout]), .kp-trace[data-kp-trace-layout='auto'])
            .kp-steplist--trace
            > .kp-steplist__item
            > .kp-steplist__time {
            grid-area: time;
            align-self: center;
        }

        :is(.kp-trace:not([data-kp-trace-layout]), .kp-trace[data-kp-trace-layout='auto'])
            .kp-steplist--trace
            > .kp-steplist__item
            > .kp-steplist__body {
            grid-area: body;
        }

        :is(.kp-trace:not([data-kp-trace-layout]), .kp-trace[data-kp-trace-layout='auto'])
            .kp-steplist--trace
            > .kp-steplist__item
            + .kp-steplist__item::before {
