    .kp-card--entity > [class^='kp-entity__'] {
        display: flex;
        align-items: center;
        gap: var(--kp-space-sm, 0.5rem);
        min-inline-size: 0;
    }

    .kp-entity-grid[data-kp-density='compact'] > .kp-card--entity,
    .kp-card--entity[data-kp-density='compact'] {
        grid-template-rows: minmax(1.75rem, auto) var(--kp-entity-row, 1.5rem) var(--kp-entity-meters-height) var(--kp-entity-action-row);
    }

    /* No actions in the data: no row for them, and no gap left behind. */
    .kp-card--entity[data-kp-entity-actions='none'] {
        grid-template-rows: minmax(1.75rem, auto) var(--kp-entity-row, 1.5rem) var(--kp-entity-row, 1.5rem) var(--kp-entity-meters-height);
    }

    .kp-entity-grid[data-kp-density='compact'] > .kp-card--entity[data-kp-entity-actions='none'],
    .kp-card--entity[data-kp-density='compact'][data-kp-entity-actions='none'] {
        grid-template-rows: minmax(1.75rem, auto) var(--kp-entity-row, 1.5rem) var(--kp-entity-meters-height);
    }

    .kp-card--entity > .kp-entity__actions[hidden] {
