    }

    .kp-entity__value {
        color: var(--foreground);
        font-variant-numeric: tabular-nums;
    }

    .kp-entity__none {
        color: var(--muted-foreground);
    }

    .kp-entity__flags {
        flex-wrap: nowrap;
    }

    .kp-entity__flag {
        flex: none;
    }

    /* The "+N" opener never shrinks below its text: squeezed in the nowrap flag row it broke "+2" over two lines. */
    .kp-entity__more-flags {
        flex: none;
    }

    .kp-entity__plus {
        white-space: nowrap;
    }

    .kp-entity__meters {
        display: grid !important;
        grid-template-columns: auto minmax(0, 1fr) auto;
        grid-auto-rows: var(--kp-entity-row, 1.5rem);
        column-gap: var(--kp-space-sm, 0.5rem);
        align-items: center;
    }

    .kp-entity__meter {
        grid-column: 1 / -1;
        display: grid;
        grid-template-columns: subgrid;
        align-items: center;
        font-size: var(--kp-text-xs, 0.75rem);
        color: var(--muted-foreground);
    }

    .kp-entity__meter-value {
        font-variant-numeric: tabular-nums;
        text-align: end;
        white-space: nowrap;
    }

    .kp-entity__actions {
        display: grid !important;
        grid-template-columns: repeat(var(--kp-entity-cols, 4), minmax(min-content, 1fr));
        gap: var(--kp-space-sm, 0.5rem);
        align-items: center;
        padding-block-start: var(--kp-entity-actions-gap, var(--kp-space-md, 0.75rem));
    }

    .kp-entity__actions > :is(.kp-button, .kp-menu-button, .kp-reason),
    .kp-entity__tick,
    .kp-entity__star,
    .kp-entity__description > .kp-entity__retry,
    .kp-entity__more-flags {
        position: relative;
        z-index: 1;
    }

    .kp-entity__actions .kp-button,
    .kp-entity__actions .kp-menu-button {
        inline-size: 100%;
    }

    .kp-entity__actions .kp-button {
        overflow-wrap: normal;
    }

    .kp-entity__actions > .kp-entity__retry {
        grid-column: 1 / -1;
    }

    .kp-entity__bone {
        display: block;
        inline-size: 70%;
        block-size: 1rem;
    }

    .kp-card--ghost {
        pointer-events: none;
    }

    /* --- The trend row: a line over the meters' columns --- */
    .kp-entity__trend-line {
        display: flex;
        align-items: center;
