        font-size: 0.8rem;
        line-height: 1.7;
        padding: 1.4rem 1.5rem 1.6rem;
    }

    [data-theme='cyberpunk'] .kp-spec dt {
        color: var(--accent);
        letter-spacing: 0.1em;
    }

    /* The log wears what this register already decided for its other data
 * surface, `.kp-spec` — the same ground, the same edge, the same face
 * [gap-14]. A new component that invents a look of its own is a
 * twenty-third decision nobody made. */
    [data-theme='cyberpunk'] .kp-log {
        background: var(--surface-hero-fg);
        color: var(--surface-hero-primary-foreground);
        border: 0;
        border-radius: 0;
        clip-path: polygon(
            0 0,
            calc(100% - var(--fx-notch, 14px)) 0,
            100% var(--fx-notch, 14px),
            100% 100%,
            var(--fx-notch, 14px) 100%,
            0 calc(100% - var(--fx-notch, 14px))
        );
        font-family: var(--kp-mono);
    }

    [data-theme='cyberpunk'] .kp-log__level {
        --kp-log-level-ink: var(--accent);
        letter-spacing: 0.1em;
    }

    [data-theme='cyberpunk'] .kp-spec dd {
        color: var(--surface-hero-primary-foreground);
    }

    [data-theme='cyberpunk'] .kp-spec__swatch {
        border-color: hsl(from var(--surface-hero-primary-foreground) h s l / 0.25);
    }

    /* The two link modifiers of the strip: the language break and the cta. */
    [data-theme='cyberpunk'] .kp-nav__link--lang {
        border-left: 1px solid hsl(from var(--primary) h s l / 0.35);
    }

    [data-theme='cyberpunk'] .kp-nav__link--cta {
        background: var(--primary);
        color: var(--primary-foreground);
        padding-inline: 1.6rem;
        font-weight: 700;
    }

    [data-theme='cyberpunk'] .kp-nav__links > li:hover > .kp-nav__link--cta,
    [data-theme='cyberpunk'] .kp-nav__links > li:focus-within > .kp-nav__link--cta {
        background: var(--primary-hover);
    }

    /* Select and textarea: the same control. The select keeps the
       package's `appearance: base-select` (KT8: the option list wears the
       theme), so the arrow is the picker icon, in the primary. */
    [data-theme='cyberpunk'] select.kp-field__input::picker-icon {
        color: var(--primary);
    }

    [data-theme='cyberpunk'] .kp-field__input--multiline {
        min-height: 6rem;
        resize: vertical;
    }

    [data-theme='cyberpunk'] .kp-field__check {
        appearance: none;
        inline-size: 1.1rem;
        block-size: 1.1rem;
        margin: 0;
        border: 1px solid var(--primary);
        background: var(--card);
        display: inline-grid;
        place-items: center;
        cursor: pointer;
    }

    [data-theme='cyberpunk'] .kp-field__check:checked::before {
        content: '';
        inline-size: 0.55rem;
        block-size: 0.55rem;
        background: var(--primary);
        clip-path: polygon(0 0, 100% 0, 100% 60%, 60% 100%, 0 100%);
    }

    /* A radio is a round cell with a lit dot, never the checkbox's square:
       one rule above made every check square (the survey of 2026-10-03). */
    [data-theme='cyberpunk'] .kp-field__check[type='radio'] {
        border-radius: 50%;
    }

    [data-theme='cyberpunk'] .kp-field__check[type='radio']:checked::before {
        border-radius: 50%;
    }

    [data-theme='cyberpunk'] .kp-field__check:focus-visible {
        outline: 2px solid var(--focus-ring);
        outline-offset: 2px;
    }

    /* The footer: near-black, mono headings in the primary, links uppercase. */
    [data-theme='cyberpunk'] .kp-footer {
        padding: 3rem clamp(1rem, 4vw, 3rem) 2.5rem;
    }

    [data-theme='cyberpunk'] .kp-footer h4 {
        font-family: var(--kp-mono);
        letter-spacing: 0.16em;
        text-transform: uppercase;
        color: var(--primary);
        margin: 0 0 0.6rem;
    }

    [data-theme='cyberpunk'] .kp-footer ul {
        list-style: none;
        margin: 0;
        padding: 0;
        display: grid;
        gap: 0.35rem;
    }

    [data-theme='cyberpunk'] .kp-footer a {
        font-weight: 500;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        font-size: 0.85rem;
        text-decoration: none;
