        color: var(--muted-foreground);
    }

    /* ── Compatibility with the 4.x register ──────────────────────────── */

    /* Three of the old opt-in classes keep a meaning: a glitch is the new
       slice on hover, a rule is the drawn hairline, a bracket frame is the
       heading's. The flicker, pulse, cell-pop and media classes are gone
       with the theme they belonged to (S39, A1); MIGRATION.md lists them. */
    [data-theme='cyberpunk'] .fx-glitch {
        position: relative;
        display: inline-block;
    }

    [data-theme='cyberpunk'] .fx-glitch::before {
        content: attr(data-kp-text);
        position: absolute;
        inset: 0;
        opacity: 0;
        pointer-events: none;
        color: var(--accent);
    }

    [data-theme='cyberpunk'] .fx-rule {
        display: block;
        height: var(--kp-rule-weight);
        background: linear-gradient(to right, var(--accent) 0 35%, hsl(from var(--accent) h s l / 0.35) 70%, transparent);
    }

    [data-theme='cyberpunk'] .fx-brackets {
        position: relative;
        padding-top: 0.9rem;
        background:
            linear-gradient(var(--primary), var(--primary)) top left / 1.2rem 2px no-repeat,
            linear-gradient(var(--primary), var(--primary)) top left / 2px 0.8rem no-repeat,
            linear-gradient(var(--primary), var(--primary)) top right / 1.2rem 2px no-repeat,
            linear-gradient(var(--primary), var(--primary)) top right / 2px 0.8rem no-repeat;
    }

    [data-theme='cyberpunk'] .fx-notch {
        clip-path: polygon(0 0, 100% 0, 100% calc(100% - var(--fx-notch)), calc(100% - var(--fx-notch)) 100%, 0 100%);
    }

    [data-theme='cyberpunk'] .fx-signal-badge {
        background: var(--fx-signal);
        color: var(--fx-signal-foreground);
        font-family: var(--kp-mono);
        font-size: 0.72rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        padding: 0.15rem 0.5rem;
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching --kp-* knobs are what js/effects.js reads. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] [data-kp-reveal='headline'].is-glitching::before,
        [data-theme='cyberpunk'] [data-kp-reveal='headline']:hover::before {
            animation: kp-slice-1 600ms steps(1, end) 1;
        }

        [data-theme='cyberpunk'] [data-kp-reveal='headline'].is-glitching::after,
        [data-theme='cyberpunk'] [data-kp-reveal='headline']:hover::after {
            animation: kp-slice-2 600ms steps(1, end) 1;
        }

        [data-theme='cyberpunk'] [data-kp-reveal='rule']::after {
            transition: transform var(--kp-rule-draw) steps(4, jump-end);
        }

        [data-theme='cyberpunk'] mark {
            transition: color 360ms steps(3, jump-end) 400ms;
        }

        [data-theme='cyberpunk'] mark::after {
            transition: transform var(--kp-wipe) steps(4, jump-end);
        }

        [data-theme='cyberpunk'] [data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='cyberpunk'] [data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        [data-theme='cyberpunk'] [data-kp-reveal='emphasis'] mark:nth-of-type(4)::after {
            transition-delay: calc(3 * var(--kp-redact-stagger));
        }

        /* The bar arrives by the channel split, as a whole picture (plate and links), and a bar
           that leaves goes as that played backwards (end of this file). */

        [data-theme='cyberpunk'] .kp-nav__links > li:hover > .kp-nav__link[data-kp-text]::before,
        [data-theme='cyberpunk'] .kp-nav__links > li:focus-within > .kp-nav__link[data-kp-text]::before {
            animation: kp-slice-a 320ms steps(2, end) 1;
        }

        /* The bar's dropdown and mega menu open by the channel split and go as it played
           backwards [Kenny: arrival and leave = split]: shown, the split plays; once the pointer
           or the press is gone, `display` is held for 480 ms (a transition) while the same four
           poses play in the other order, and the panel is gone with the last one. The mega
           menu's item is held by the script (`[data-kp-nav-closing]`, js/components.js), which
           waits for a transition on the panel: the hold below is that transition. */
        [data-theme='cyberpunk'] .kp-nav__menu:not(.kp-nav__menu--wide) {
            --kp-cp-hold: 0;
            transition: --kp-cp-hold 480ms linear;
            animation: kp-sig-cyberpunk-split-back 480ms steps(1, end) reverse forwards;
        }

        /* A dropdown the pointer or the focus has left is drawn through its close by the mark the
           script puts on its item (js/components.js: Firefox does not hold `display`). */
        [data-theme='cyberpunk']
            .kp-nav__links
            > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open])
            > .kp-nav__menu:not(.kp-nav__menu--wide) {
            display: block;
        }

        [data-theme='cyberpunk'] .kp-nav__menu--wide {
            --kp-cp-hold: 0;
            transition: --kp-cp-hold 480ms linear;
        }

        [data-theme='cyberpunk']
            :is(
                .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
            ) {
            --kp-cp-hold: 1;
            animation: kp-sig-cyberpunk-split 480ms steps(1, end) backwards;
        }

        [data-theme='cyberpunk']
            .kp-nav__links
            > li[data-kp-nav-closing]:not([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
            > .kp-nav__menu--wide {
            animation: kp-sig-cyberpunk-split-back 480ms steps(1, end) reverse forwards;
        }

        [data-theme='cyberpunk'] .kp-button {
            transition: transform var(--fx-duration) var(--fx-ease);
        }

        [data-theme='cyberpunk'] .kp-field__input {
            transition:
                border-color var(--fx-duration) var(--fx-ease),
                box-shadow var(--fx-duration) var(--fx-ease);
        }

        [data-theme='cyberpunk'] .fx-glitch:hover::before {
            animation: kp-slice-a 320ms steps(2, end) 1;
        }

        [data-theme='cyberpunk'] [data-kp-divider]::before {
            animation: kp-stream-144 8000ms linear infinite;
        }

        [data-theme='cyberpunk'] [data-kp-divider]::after {
            animation: kp-stream-216 8000ms linear infinite;
        }

        [data-theme='cyberpunk'] [data-kp-divider='alt']::before,
        [data-theme='cyberpunk'] [data-kp-divider='alt']::after {
            animation-direction: reverse;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has a row in TIMINGS (js/effects.js) with its
       measured opacity stops; check-motion.mjs holds the two in step and
       reports the rate of every one (S42: reported, never corrected). */
    @media (prefers-reduced-motion: no-preference) {
        @keyframes kp-slice-a {
            0% {
                opacity: 1;
                clip-path: inset(0 0 55% 0);
                transform: translate(-3px, -1px);
            }
            50% {
                opacity: 1;
                clip-path: inset(40% 0 20% 0);
                transform: translate(3px, 1px);
            }
            100% {
                opacity: 0;
                clip-path: inset(0 0 0 0);
                transform: none;
            }
        }

        @keyframes kp-slice-1 {
            0% {
                opacity: 1;
                clip-path: polygon(0 2%, 100% 2%, 100% 9%, 0 9%);
                transform: translate(-6px, 0);
            }
            14% {
                clip-path: polygon(0 31%, 100% 31%, 100% 36%, 0 36%);
                transform: translate(5px, 0);
            }
            28% {
                clip-path: polygon(0 58%, 100% 58%, 100% 63%, 0 63%);
                transform: translate(-4px, 0);
            }
            42% {
                clip-path: polygon(0 12%, 100% 12%, 100% 22%, 0 22%);
                transform: translate(7px, 0);
            }
            56% {
                clip-path: polygon(0 80%, 100% 80%, 100% 84%, 0 84%);
                transform: translate(-5px, 0);
            }
            70% {
                clip-path: polygon(0 44%, 100% 44%, 100% 47%, 0 47%);
                transform: translate(3px, 0);
            }
            84%,
            100% {
                opacity: 0;
                clip-path: polygon(0 0, 0 0, 0 0, 0 0);
                transform: none;
            }
        }

        @keyframes kp-slice-2 {
            0% {
                opacity: 1;
                clip-path: polygon(0 66%, 100% 66%, 100% 72%, 0 72%);
                transform: translate(6px, 0);
            }
            14% {
                clip-path: polygon(0 5%, 100% 5%, 100% 8%, 0 8%);
                transform: translate(-5px, 0);
            }
            28% {
                clip-path: polygon(0 40%, 100% 40%, 100% 49%, 0 49%);
                transform: translate(4px, 0);
            }
            42% {
                clip-path: polygon(0 88%, 100% 88%, 100% 93%, 0 93%);
                transform: translate(-7px, 0);
            }
            56% {
                clip-path: polygon(0 20%, 100% 20%, 100% 24%, 0 24%);
                transform: translate(5px, 0);
            }
            70% {
                clip-path: polygon(0 74%, 100% 74%, 100% 77%, 0 77%);
                transform: translate(-3px, 0);
            }
            84%,
            100% {
                opacity: 0;
                clip-path: polygon(0 0, 0 0, 0 0, 0 0);
                transform: none;
            }
        }

        @keyframes kp-stream-144 {
            from {
                mask-position: 0 0;
            }
            to {
                mask-position: 144px 0;
            }
        }

        @keyframes kp-stream-216 {
            from {
                mask-position: 0 0;
            }
            to {
                mask-position: 216px 0;
            }
        }
    }

    /* Reduced motion: every effect resolves to its rest state at once
       [DI7]. Nothing animates (see the guard above); what the script would
       have revealed is shown: the marks are clear, the rule is drawn. */
    @media (prefers-reduced-motion: reduce) {
        [data-theme='cyberpunk'][data-kp-effects] mark:not(.is-cleared) {
            color: var(--link);
            font-weight: 700;
        }

        [data-theme='cyberpunk'][data-kp-effects] mark:not(.is-cleared)::after,
        [data-theme='cyberpunk'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
            transform: none;
        }
    }

    /* The sector code beside the wordmark [S49, A3]. */
    [data-theme='cyberpunk'] .kp-nav__brand-tag {
        color: var(--accent);
        letter-spacing: 0.2em;
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — the band Kenny corrected on 2026-09-08: every corner cut the same, and the ground signal yellow with the ink in blood red rather than the unreadable white it had. The pair measures 3.21 against the 4.5 floor, reported to him with the change. */
    [data-theme='cyberpunk'] .kp-marquee {
        background: var(--primary);
        color: var(--destructive);
        clip-path: polygon(
            var(--fx-notch-sm) 0,
            calc(100% - var(--fx-notch-sm)) 0,
            100% var(--fx-notch-sm),
            100% calc(100% - var(--fx-notch-sm)),
            calc(100% - var(--fx-notch-sm)) 100%,
            var(--fx-notch-sm) 100%,
            0 calc(100% - var(--fx-notch-sm)),
            0 var(--fx-notch-sm)
        );
        font-family: var(--theme-font-mono);
        text-transform: uppercase;
        letter-spacing: 0.12em;
        --kp-marquee: 18000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='cyberpunk'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='cyberpunk'] .kp-nav__menu--wide .kp-nav__menu-heading {
        background: var(--primary);
        color: var(--primary-foreground);
        font-family: var(--theme-font-mono);
        letter-spacing: 0.14em;
        border-block-end: 0;
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       The bar underlines the page you are on; the column cuts its corner
       off instead. The notch is this theme's whole grammar and it belongs
       on the one row that is different from the others. */
    [data-theme='cyberpunk'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
        --kp-sidenav-list-pad: 0;
        --kp-sidenav-gap: 0;
        border-inline-end: 2px solid var(--border-strong);
    }

    [data-theme='cyberpunk'] .kp-sidenav__title {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.22em;
        text-transform: uppercase;
        color: var(--primary);
    }

    [data-theme='cyberpunk'] .kp-sidenav__link,
    [data-theme='cyberpunk'] .kp-sidenav__category-toggle {
        padding-inline: 1.1rem;
        font-weight: 600;
        border-radius: 0;
    }

    [data-theme='cyberpunk'] .kp-sidenav__link[aria-current='page'] {
        background: var(--primary);
        color: var(--primary-foreground);
        clip-path: polygon(0 0, 100% 0, 100% calc(100% - var(--fx-notch-sm, 8px)), calc(100% - var(--fx-notch-sm, 8px)) 100%, 0 100%);
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       The notch again: the control is cut, and the frame is cut the other
       way, so a picture reads as a panel bolted into the page. */
    [data-theme='cyberpunk'] .kp-to-top {
        clip-path: polygon(0 0, 100% 0, 100% calc(100% - 0.5rem), calc(100% - 0.5rem) 100%, 0 100%);
    }

    [data-theme='cyberpunk'] .kp-media {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        clip-path: polygon(0 0, calc(100% - var(--fx-notch, 14px)) 0, 100% var(--fx-notch, 14px), 100% 100%, 0 100%);
    }

    [data-theme='cyberpunk'] .kp-media-figure > figcaption {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.12em;
        text-transform: uppercase;
        font-size: 0.6875rem;
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='cyberpunk'] .kp-media-figure {
        color: var(--muted-foreground);
        text-align: start;
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): spaced yellow capitals on the dark strip
       with its cut corner, a faint yellow wash under the pointer. The links'
       strip is drawn by the list, so the trigger, which stands outside it on
       the yellow bar, carries its own piece of that strip, drawn behind it
       the way the list draws its own, so the cut never clips the focus ring.
       The link's typeface, case, spacing, shape and pointer answer are
       restated here, because the trigger is a button beside the list rather
       than a link in it. The underline a plain link carries is not: it says
       "this is a link", and the trigger is not one. */
    [data-theme='cyberpunk'] .kp-nav__search .kp-nav__search-trigger {
        position: relative;
        isolation: isolate;
        padding-inline: 1.1rem;
        font-weight: 600;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        border: 0;
        border-radius: 0;
        background: none;
        color: var(--primary);
    }

    [data-theme='cyberpunk'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='cyberpunk'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        background: none;
        color: var(--primary);
    }

    [data-theme='cyberpunk'] .kp-nav__search .kp-nav__search-trigger::before {
        content: '';
        position: absolute;
        inset: 0;
        z-index: -1;
        background: var(--background);
        clip-path: polygon(var(--kp-nav-notch) 0, 100% 0, 100% 62%, calc(100% - 15px) 100%, 0 100%, 0 var(--kp-nav-notch));
    }

    [data-theme='cyberpunk'] .kp-nav__search .kp-nav__search-trigger:hover::before,
    [data-theme='cyberpunk'] .kp-nav__search .kp-nav__search-trigger:focus-visible::before {
        background: linear-gradient(hsl(from var(--primary) h s l / 0.12), hsl(from var(--primary) h s l / 0.12)), var(--background);
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       The prototype as approved: blood red on the void, split and hazard bars in signal yellow. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='cyberpunk'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--destructive) h calc(s * 0.6) 5% / 0.95);
        --kp-alarm-ink: hsl(from var(--destructive) h s max(l, 60));
        --kp-alarm-soft: hsl(from var(--destructive) h calc(s * 0.4) 86);
        --kp-alarm-split: var(--primary);
        --kp-alarm-on-ink: hsl(from var(--destructive) h s 6%);
        --kp-alarm-glow: hsl(from var(--destructive) h s max(l, 45) / 0.5);
        --kp-alarm-halo: hsl(from var(--destructive) h s max(l, 50) / 0.55);
        --kp-alarm-scan: hsl(from var(--destructive) h s max(l, 50) / 0.09);
        --kp-alarm-vignette: hsl(from var(--destructive) h s 2% / 0.7);
        --kp-alarm-stripe: var(--primary);
        --kp-alarm-title-tracking: 0.02em;
    }

    [data-theme='cyberpunk'] .kp-alarm:focus-visible {
        outline: none;
    }

    /* The acknowledge button is the theme's own button, drawn by its three variables: the frame is
       its background colour, the face and the notch line are background layers over it. A
       `background:` shorthand here (what the other registers write) reset those layers' size and
       repeat, so the notch line tiled over the whole face in the page's yellow and hid the label
       [Kenny, 2026-10-12: "Ik kan niet lezen wat er op die knop staat"]. The variables keep the
       layers and their hover, focus and press. Rest: dark label on the alarm's red, 5.3:1;
       hover and focus: the red label on the dark face. */
    [data-theme='cyberpunk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='cyberpunk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='cyberpunk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        --kp-btn-frame: var(--kp-alarm-ink);
        --kp-btn-ground: var(--kp-alarm-ground);
        --kp-btn-face: var(--kp-alarm-ink);
        --kp-btn-fg: var(--kp-alarm-on-ink);
        border-color: var(--kp-alarm-ink);
        text-shadow: none;
    }

    [data-theme='cyberpunk'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        --kp-btn-face: var(--kp-alarm-on-ink);
        --kp-btn-fg: var(--kp-alarm-ink);
    }

    [data-theme='cyberpunk'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='cyberpunk'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    /* The glitch, opted into [scope-98]. Since Kenny's judgement of the pilot
       portraits the package's alarm arrives whole, and the glitch lives here
       alone: "het alarm geeft nog altijd het glitch effect, dat enkel bij
       cyberpunk thuishoort". Cyberpunk's portrait approved its alarm as it
       was, so these rules give back exactly what the package used to draw —
       the scanlines and the sweeping band, the split copies, the letter
       cells' noise glyphs and the caret — and name the package's own
       keyframes (css/components.css: kp-alarm-jitter, kp-alarm-slice-in,
       kp-alarm-slice, kp-alarm-decode-letter, kp-alarm-decode-noise,
       kp-alarm-detail-in, kp-alarm-caret, kp-alarm-march, kp-alarm-sweep) at
       the timings they had. research/alarm-per-theme/ holds the before and
       after. The panel's flicker is this register's own since scope-100,
       below. */

    /* The panel strikes like a failing tube [scope-100]: it catches at 60%,
       sags to 52% with a sideways kick, and snaps to full. Kenny, on the
       package's 0 -> 1 -> 0.3 -> 1 (3.00 flashes a second in reports/di5.md,
       over the 2.5 bar): "Ondieper, en opnieuw kijken". The sag is 0.08 —
       under DI5's 10% step — so both visible jumps go the same way and the
       report reads 1.00 a second; the kick (-0.6%, then 0.8%) carries the
       flicker the dip no longer does. */
    @keyframes kp-alarm-cyberpunk-flicker {
        0% {
            opacity: 0;
        }
        18% {
            opacity: 0.6;
            translate: -0.6% 0;
        }
        30% {
            opacity: 0.52;
            translate: 0.8% 0;
        }
        42% {
            opacity: 1;
            translate: 0 0;
        }
        100% {
            opacity: 1;
        }
    }

    [data-theme='cyberpunk'] .kp-alarm__scan {
        background:
            repeating-linear-gradient(to bottom, var(--kp-alarm-scan) 0 1px, transparent 1px 3px),
            radial-gradient(ellipse at center, transparent 50%, var(--kp-alarm-vignette));
    }

    [data-theme='cyberpunk'] .kp-alarm__scan::after {
        content: '';
    }

    [data-theme='cyberpunk'] .kp-alarm__glyphs::before,
    [data-theme='cyberpunk'] .kp-alarm__glyphs::after {
        content: attr(data-text);
    }

    [data-theme='cyberpunk'] .kp-alarm__char::before {
        content: attr(data-n1);
    }

    [data-theme='cyberpunk'] .kp-alarm__char::after {
        content: attr(data-n2);
    }

    [data-theme='cyberpunk'] .kp-alarm__detail::after {
        display: inline-block;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            animation: kp-alarm-ground-in 180ms ease-out both;
        }

        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__panel {
            animation: kp-alarm-cyberpunk-flicker 600ms steps(1, end) both;
        }

        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__title {
            animation: none;
        }

        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__glyphs {
            animation: kp-alarm-jitter 5000ms 600ms steps(1, end) infinite;
        }

        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__glyphs::before {
            animation:
                kp-alarm-slice-in 600ms steps(1, end) both,
                kp-alarm-slice 5000ms 600ms steps(1, end) infinite;
        }

        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__glyphs::after {
            animation:
                kp-alarm-slice-in 600ms 90ms steps(1, end) both,
                kp-alarm-slice 5000ms 690ms steps(1, end) infinite;
        }

        /* The decode: each letter cell shows one noise glyph for 90 ms, a
           second for 90 ms, then its letter, 35 ms after the cell before
           it. A cell changes three times, ever. */
        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__char {
            animation: kp-alarm-decode-letter calc(var(--i, 0) * 35ms + 180ms) steps(1, end) both;
        }

        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__char::before {
            animation: kp-alarm-decode-noise 90ms calc(var(--i, 0) * 35ms) steps(1, end) forwards;
        }

        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__char::after {
            animation: kp-alarm-decode-noise 90ms calc(var(--i, 0) * 35ms + 90ms) steps(1, end) forwards;
        }

        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__detail {
            animation: kp-alarm-detail-in 300ms 600ms ease-out both;
        }

        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__detail::after {
            animation: kp-alarm-caret 1000ms steps(1, end) infinite;
        }

        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__bars::before,
        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__bars::after {
            animation: kp-alarm-march 1600ms linear infinite;
        }

        [data-theme='cyberpunk'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__scan::after {
            animation: kp-alarm-sweep 6000ms linear infinite;
        }
    }

    /* A submenu item's mark [Kenny, 2026-09-20]: the double slash this register already speaks in. */
    [data-theme='cyberpunk'] .kp-sidenav__submenu .kp-sidenav__link {
        --kp-sidenav-submenu-mark: '//';
    }
}

/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* cyberpunk's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/cyberpunk.css and research/signature-elements/demo.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* ── The approved grammar [scope-143; Kenny, 2026-10-07 23:52, 18 of 18 on
       research/cyberpunk-character; the anchor is the glitch] ─────────────
       What this block draws, once, for every part below it and for the exits:
       the notch in two sizes (14 px on a plate at its dossier corner, 8 px on a
       control, 18 px on the dialog's pair), the holo plate (a yellow rim glowing
       inward, scan lines at 135 degrees), the channel split that opens, closes,
       arrives and leaves a part (four ticks of 120 ms: a yellow copy right and
       up, a cyan copy right and down, 6, 4, 2, 1 px, then the part itself), the
       split edge under the pointer, the target brackets of focus, the closed
       circuit of a press. Hard ticks everywhere: `steps()`, never an ease.
       Colours are tokens only; every copy is the part's own silhouette (a box
       shadow) and the part's own text (a text shadow), so the copies need no
       SVG filter. The clip is the part's own cut, wide around it while a copy
       plays outside its box, so the notch is cut at every frame. */

    /* The clocks. A hover or a focus is four ticks (3, 2, 1, 0 left of the entrance), and its
       leave is the same four the other way round: `t` counts the ticks left, `p` says
       whether the part is pointed, so a pose is a function of the two. */
    /* The mega menu's hold: it changes with the panel's state so a transition runs for as long as
       the close does, and the script that keeps the panel drawn waits for it. */
    @property --kp-cp-hold {
        syntax: '<number>';
        inherits: false;
        initial-value: 0;
    }

    @property --kp-cp-t {
        syntax: '<number>';
        inherits: true;
        initial-value: 4;
    }

    @property --kp-cp-p {
        syntax: '<number>';
        inherits: true;
        initial-value: 0;
    }

    @property --kp-cp-ft {
        syntax: '<number>';
        inherits: true;
        initial-value: 4;
    }

    @property --kp-cp-fp {
        syntax: '<number>';
        inherits: true;
        initial-value: 0;
    }

    /* The lock-on of a target brackets: the inset the brackets close to. */
    @property --kp-cp-lk {
        syntax: '<length>';
        inherits: true;
        initial-value: 3px;
    }

    /* The four bars of the spinner, one height each (a share of its box). */
    @property --kp-cp-h1 {
        syntax: '<percentage>';
        inherits: false;
        initial-value: 56.5%;
    }

    @property --kp-cp-h2 {
        syntax: '<percentage>';
        inherits: false;
        initial-value: 100%;
    }

    @property --kp-cp-h3 {
        syntax: '<percentage>';
        inherits: false;
        initial-value: 30.4%;
    }

    @property --kp-cp-h4 {
        syntax: '<percentage>';
        inherits: false;
        initial-value: 82.6%;
    }

    [data-theme='cyberpunk'] {
        --kp-cp-notch: var(--fx-notch, 14px);
        --kp-cp-notch-sm: var(--fx-notch-sm, 8px);
        --kp-cp-notch-pair: 18px;
        /* The part's own cut, and the same cut with 40 px of room round it: a copy that
           plays outside the box keeps the notch's diagonal and nothing else. */
        --kp-cp-clip-plate: polygon(0 0, calc(100% - var(--kp-cp-notch)) 0, 100% var(--kp-cp-notch), 100% 100%, 0 100%);
        --kp-cp-wide-plate: polygon(
            -40px -40px,
            calc(100% - var(--kp-cp-notch) - 40px) -40px,
            calc(100% + 40px) calc(var(--kp-cp-notch) + 40px),
            calc(100% + 40px) calc(100% + 40px),
            -40px calc(100% + 40px)
        );
        --kp-cp-clip-ctl: polygon(0 0, 100% 0, 100% calc(100% - var(--kp-cp-notch-sm)), calc(100% - var(--kp-cp-notch-sm)) 100%, 0 100%);
        --kp-cp-wide-ctl: polygon(
            -40px -40px,
            calc(100% + 40px) -40px,
            calc(100% + 40px) calc(100% - var(--kp-cp-notch-sm) - 40px),
            calc(100% - var(--kp-cp-notch-sm) - 40px) calc(100% + 40px),
            -40px calc(100% + 40px)
        );
        --kp-cp-clip-pair: polygon(
            0 0,
            calc(100% - var(--kp-cp-notch-pair)) 0,
            100% var(--kp-cp-notch-pair),
            100% 100%,
            var(--kp-cp-notch-pair) 100%,
            0 calc(100% - var(--kp-cp-notch-pair))
        );
        --kp-cp-wide-pair: polygon(
            -40px -40px,
            calc(100% - var(--kp-cp-notch-pair) - 40px) -40px,
            calc(100% + 40px) calc(var(--kp-cp-notch-pair) + 40px),
            calc(100% + 40px) calc(100% + 40px),
            calc(var(--kp-cp-notch-pair) + 40px) calc(100% + 40px),
            -40px calc(100% - var(--kp-cp-notch-pair) - 40px)
        );
        /* The reticle's corners: four 9 px tiles. */
        --kp-cp-corners:
            linear-gradient(var(--foreground) 0 0) 0 0 / 9px 9px no-repeat, linear-gradient(var(--foreground) 0 0) 100% 0 / 9px 9px no-repeat,
            linear-gradient(var(--foreground) 0 0) 0 100% / 9px 9px no-repeat, linear-gradient(var(--foreground) 0 0) 100% 100% / 9px 9px no-repeat;
        /* A box that changes size takes it in whole ticks: eight of 60 ms. */
        --kp-size-ease: steps(8, end);
        /* The accordion and a tree branch take those ticks too (js/motion.js sizeEase()), not
           the entrance's single step. */
        --kp-accordion-size: own;
    }

    /* The two copies, as the part's own silhouette: yellow right and up, cyan right and
       down (the live stutter's 6, 4, 2, 1 px). Every part that is a plate carries them;
       a part without a plate has none and only its text splits. */
    [data-theme='cyberpunk']
        :is(.kp-card, .kp-kpi, .kp-popover, .kp-dialog, .kp-toast, .kp-alert, .kp-tooltip, .kp-datepicker__panel, .kp-combobox__list, .kp-nav__menu) {
        --kp-cp-rest: 0 0 transparent;
        --kp-cp-b0: 6px 4px 0 var(--accent), 6px -4px 0 var(--primary);
        --kp-cp-b1: 4px 3px 0 var(--accent), 4px -3px 0 var(--primary);
        --kp-cp-b2: 2px 2px 0 var(--accent), 2px -2px 0 var(--primary);
        --kp-cp-b3: 1px 1px 0 var(--accent), 1px -1px 0 var(--primary);
    }

    /* Each part's own cut. */
    [data-theme='cyberpunk'] :is(.kp-card, .kp-kpi, .kp-popover, .kp-datepicker__panel, .kp-combobox__list) {
        --kp-cp-clip: var(--kp-cp-clip-plate);
        --kp-cp-wide: var(--kp-cp-wide-plate);
    }

    [data-theme='cyberpunk'] .kp-dialog {
        --kp-cp-clip: var(--kp-cp-clip-pair);
        --kp-cp-wide: var(--kp-cp-wide-pair);
    }

    [data-theme='cyberpunk'] :is(.kp-toast, .kp-alert, .kp-tooltip, .kp-field__input, .kp-badge, .kp-tag) {
        --kp-cp-clip: var(--kp-cp-clip-ctl);
        --kp-cp-wide: var(--kp-cp-wide-ctl);
    }

    [data-theme='cyberpunk'] .kp-button {
        --kp-cp-clip: polygon(0 0, 100% 0, 100% calc(100% - var(--kp-button-notch)), calc(100% - var(--kp-button-notch)) 100%, 0 100%);
        --kp-cp-wide: polygon(
            -40px -40px,
            calc(100% + 40px) -40px,
            calc(100% + 40px) calc(100% - var(--kp-button-notch) - 40px),
            calc(100% - var(--kp-button-notch) - 40px) calc(100% + 40px),
            -40px calc(100% + 40px)
        );
    }

    /* The holo plate [G7]: a card, a key figure and the menu's popover are void plates with
       a yellow rim glowing 10 px inward, scan lines at 135 degrees, the rim running along the
       notch, cut at the dossier corner. A press lights the circuit grid on it. */
    [data-theme='cyberpunk']
        :is(.kp-card, .kp-kpi, .kp-popover, .kp-datepicker__panel, .kp-combobox__list, .kp-accordion__item:not(.kp-accordion__item--bare)) {
        --kp-cp-ground: var(--card);
        --kp-cp-grid-a: 0;
        --kp-cp-rest: inset 0 0 0 1px var(--primary), inset 0 0 10px hsl(from var(--primary) h s l / 0.35);
        --kp-cp-grid:
            repeating-linear-gradient(to bottom, hsl(from var(--primary) h s l / var(--kp-cp-grid-a)) 0 1px, transparent 1px 14px) 0 0 / 100% 100%
                no-repeat,
            repeating-linear-gradient(to right, hsl(from var(--primary) h s l / var(--kp-cp-grid-a)) 0 1px, transparent 1px 14px) 0 0 / 100% 100%
                no-repeat;
        --kp-cp-notch-line: linear-gradient(45deg, transparent calc(50% - 1.5px), var(--primary) calc(50% - 1.5px) 50%, transparent 50%) 100% 0 /
            var(--kp-cp-notch) var(--kp-cp-notch) no-repeat;
        --kp-cp-scan: repeating-linear-gradient(135deg, hsl(from var(--primary) h s l / 0.06) 0 2px, transparent 2px 6px);
        border: 0;
        border-radius: 0;
        background: var(--kp-cp-grid), var(--kp-cp-notch-line), var(--kp-cp-scan), var(--kp-cp-ground);
        box-shadow: var(--kp-cp-rest);
        clip-path: var(--kp-cp-clip);
    }

    [data-theme='cyberpunk'] :is(.kp-popover, .kp-datepicker__panel, .kp-combobox__list) {
        --kp-cp-ground: var(--popover);
    }

    /* A key figure that is a toggle and is on: the rim and a primary wash. */
    [data-theme='cyberpunk'] .kp-kpi--toggle[aria-pressed='true'] {
        --kp-cp-ground: color-mix(in oklab, var(--primary) 9%, var(--card));
        box-shadow: var(--kp-cp-rest);
    }

    /* The machine's voice [G15]: the label is prefixed mono capitals in cyan, the figure the
       condensed display. */
    [data-theme='cyberpunk'] .kp-kpi__label {
        color: var(--accent);
        font-family: var(--kp-mono);
        letter-spacing: 0.14em;
    }

    [data-theme='cyberpunk'] .kp-kpi__label::before {
        content: '/// ';
        opacity: 0.7;
    }

    [data-theme='cyberpunk'] .kp-kpi__value {
        font-family: var(--theme-font-display);
        font-weight: 700;
    }

    /* A warning is locked as a target [Kenny: tone = lock, G13]: four corner brackets, 2 px, in the
       tone's ink (a warning's ink, never its plate; the destructive red) frame a key figure whose
       `data-kp-tone` says so, and a destructive menu entry. They close on it in two twitches (360 ms,
       `steps(1)`) and hold; there is no frame and no hazard band. Drawn as background layers, so
       the part's four pseudo-elements stay for pointing and focus. */
    [data-theme='cyberpunk'] .kp-kpi[data-kp-tone='warning'],
    [data-theme='cyberpunk'] .kp-kpi[data-kp-tone='destructive'],
    [data-theme='cyberpunk'] .kp-menu__item--destructive {
        --kp-cp-tone: var(--destructive);
        --kp-cp-lock:
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) var(--kp-cp-lk) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) var(--kp-cp-lk) / 2px 9px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) var(--kp-cp-lk) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) var(--kp-cp-lk) / 2px 9px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) calc(100% - var(--kp-cp-lk)) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) calc(100% - var(--kp-cp-lk)) / 2px 9px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) calc(100% - var(--kp-cp-lk)) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) calc(100% - var(--kp-cp-lk)) / 2px 9px no-repeat;
    }

    [data-theme='cyberpunk'] .kp-kpi[data-kp-tone='warning'] {
        --kp-cp-tone: var(--warning-foreground);
    }

    [data-theme='cyberpunk'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) {
        background: var(--kp-cp-lock), var(--kp-cp-grid), var(--kp-cp-notch-line), var(--kp-cp-scan), var(--kp-cp-ground);
    }

    [data-theme='cyberpunk'] .kp-menu__item--destructive {
        background-image: var(--kp-cp-lock);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] :is(.kp-kpi[data-kp-tone='warning'], .kp-kpi[data-kp-tone='destructive'], .kp-menu__item--destructive) {
            animation: kp-sig-cyberpunk-lock 360ms steps(1, end);
        }
    }

    /* The tag of the lock: a mono word in the tone's ink, boxed, at the head's end. It is the free
       `::after` of the label (the label's `::before` is the prefix), laid over the tile, so no markup
       is added; a tile narrower than 15 rem has no room for it and drops it. */
    [data-theme='cyberpunk'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) {
        position: relative;
    }

    [data-theme='cyberpunk'] .kp-kpi[data-kp-tone='warning'] .kp-kpi__label::after,
    [data-theme='cyberpunk'] .kp-kpi[data-kp-tone='destructive'] .kp-kpi__label::after {
        position: absolute;
        inset-block-start: 0.45rem;
        inset-inline-end: 1.2rem;
        padding: 0 0.3rem;
        border: 1px solid var(--kp-cp-tone);
        color: var(--kp-cp-tone);
        font-family: var(--kp-mono);
        font-size: 0.6rem;
        font-weight: 700;
        line-height: 1rem;
        letter-spacing: 0.16em;
        pointer-events: none;
    }

    [data-theme='cyberpunk'] .kp-kpi[data-kp-tone='warning'] .kp-kpi__label::after {
        content: 'CAUTION';
        content: 'CAUTION' / '';
    }

    [data-theme='cyberpunk'] .kp-kpi[data-kp-tone='destructive'] .kp-kpi__label::after {
        content: 'TARGET';
        content: 'TARGET' / '';
    }

    @container kp-kpi (max-width: 15rem) {
        [data-theme='cyberpunk'] .kp-kpi[data-kp-tone] .kp-kpi__label::after {
            display: none;
        }
