    @media (prefers-reduced-motion: no-preference) {
        /* In: the pose arrives in four ticks (3, 2, 1, 0 left); out: the same four the
           other way round, and only then does the part count as at rest. */
        [data-theme='cyberpunk']
            :is(
                .kp-button,
                a.kp-kpi,
                .kp-kpi--toggle,
                .kp-card:is(a, button, [tabindex]:not([tabindex='-1']), [role='button'], [role='link']),
                .kp-menu__item
