            transition:
                --kp-cp-t 180ms steps(4, jump-start),
                --kp-cp-p 0s steps(1, end),
                --kp-cp-ft 180ms steps(4, jump-end),
                --kp-cp-fp 0s steps(1, end) 180ms;
        }

        [data-theme='cyberpunk']
            :is(
                .kp-button,
                a.kp-kpi,
                .kp-kpi--toggle,
                .kp-card:is(a, button, [tabindex]:not([tabindex='-1']), [role='button'], [role='link']),
                .kp-menu__item
            ):focus-visible {
            transition:
                --kp-cp-t 180ms steps(4, jump-end),
                --kp-cp-p 0s steps(1, end) 180ms,
                --kp-cp-ft 180ms steps(4, jump-start),
                --kp-cp-fp 0s steps(1, end);
        }

        [data-theme='cyberpunk'] .kp-button:hover:not(:disabled):focus-visible,
        [data-theme='cyberpunk']
            :is(
                a.kp-kpi,
                .kp-kpi--toggle,
                .kp-card:is(a, button, [tabindex]:not([tabindex='-1']), [role='button'], [role='link']),
                .kp-menu__item
            ):hover:focus-visible {
            transition:
                --kp-cp-t 180ms steps(4, jump-start),
                --kp-cp-p 0s steps(1, end),
                --kp-cp-ft 180ms steps(4, jump-start),
                --kp-cp-fp 0s steps(1, end);
        }
    }

    /* ── Pointing answers for every other part [Kenny: the same three for all] ─────────────
       A tab, a link of the bars, a pager, an icon button, an option, a day, a row, a sort head, a field
       answers a pointer with the split edge, a keyboard with the four closing brackets and a press
       with the closed circuit, the way a button and a key figure do. Where a button is cut and draws
       them on its pseudo-elements, a square part draws them as background layers of its own (no part
       listed here has a background image of its own), so no pseudo-element a component already uses is
       touched. The ink of the brackets is the focus ring pair, two channels, DI2. The clocks are the
       ones above. The brackets keep clear of a notch they sit near: the corner inset is half the notch. */

    [data-theme='cyberpunk']
        :where(
            button,
            summary,
            select,
            textarea,
            input:not([type='checkbox'], [type='radio'], [type='range'], [type='hidden'], [type='file'], [type='color']),
            [role='tab'],
            [role='option'],
            [role='treeitem'],
            :is(th, td)[tabindex]:not([tabindex='-1']),
            a.kp-nav__link,
            a.kp-nav__brand,
            a.kp-sidenav__link,
            a.kp-kpi__link,
            .kp-nav a,
            .kp-sidenav a,
            .kp-pagination a,
            .kp-breadcrumb a,
            .kp-footer a,
            .kp-chart__plot,
            .kp-kpi__chart-plot,
            .kp-grid__tile[tabindex],
            .kp-skip-link,
            .kp-field__option,
            .kp-field--check,
            .kp-switch,
            .kp-upload__zone,
