            right calc(var(--kp-cp-ft) * 3px + 2px) bottom calc(var(--kp-cp-ft) * 3px + 2px),
            right calc(var(--kp-cp-ft) * 3px + 2px) bottom calc(var(--kp-cp-ft) * 3px + 2px),
            right bottom,
            0 0,
            0 0;
        background-repeat: no-repeat;
    }

    [data-theme='cyberpunk'] .kp-nav__toggle::after {
        content: '';
