                --kp-cp-t 180ms steps(4, jump-end),
                --kp-cp-p 0s steps(1, end) 180ms,
                --kp-cp-ft 180ms steps(4, jump-end),
                --kp-cp-fp 0s steps(1, end) 180ms;
        }

        [data-theme='cyberpunk']
            :is(
                .kp-nav__link:hover,
                .kp-nav__links > li:hover > .kp-nav__link,
                .kp-nav__brand:hover,
                .kp-pagination :is(a, button):hover:not(:disabled, [aria-disabled='true']),
                .kp-nav__toggle:hover
            ) {
            transition:
                --kp-cp-t 180ms steps(4, jump-start),
                --kp-cp-p 0s steps(1, end),
                --kp-cp-ft 180ms steps(4, jump-end),
                --kp-cp-fp 0s steps(1, end) 180ms;
        }

        [data-theme='cyberpunk'] :is(.kp-nav__link, .kp-nav__brand, .kp-pagination :is(a, button), .kp-nav__toggle):focus-visible {
            transition:
                --kp-cp-t 180ms steps(4, jump-end),
                --kp-cp-p 0s steps(1, end) 180ms,
                --kp-cp-ft 180ms steps(4, jump-start),
                --kp-cp-fp 0s steps(1, end);
