        [data-theme='cyberpunk']
            :is(
                .kp-nav__link:hover,
                .kp-nav__links > li:hover > .kp-nav__link,
                .kp-nav__brand:hover,
                .kp-pagination :is(a, button):hover:not(:disabled, [aria-disabled='true']),
                .kp-nav__toggle:hover
            ):focus-visible {
            transition:
                --kp-cp-t 180ms steps(4, jump-start),
                --kp-cp-p 0s steps(1, end),
                --kp-cp-ft 180ms steps(4, jump-start),
                --kp-cp-fp 0s steps(1, end);
        }
    }

    /* ── F. Every plate is cut at its dossier corner, every control at its end [G6] ─────────
       14 px on a plate, 8 px on a control, a share of its height on a part too small for 8;
       nothing is round (the radio is the one exception, the graph's kind chips another). */
    [data-theme='cyberpunk']
        :is(
            .kp-palette,
            .kp-drawer,
            .kp-accordion__item,
            .kp-upload__zone,
            .kp-upload__file,
            .kp-code-block,
            .kp-footer,
            .kp-form__summary,
            .kp-alarm,
            .kp-timeline,
            .kp-shortcuts,
            .kp-diff,
            .kp-sidenav,
            .kp-tabs__list
        ) {
        --kp-cp-clip: var(--kp-cp-clip-plate);
        --kp-cp-wide: var(--kp-cp-wide-plate);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
    }

    /* The parts that open by the split carry its copies, as the other plates do. */
    [data-theme='cyberpunk'] :is(.kp-palette, .kp-drawer, .kp-alarm, .kp-shortcuts) {
        --kp-cp-b0: 6px 4px 0 var(--accent), 6px -4px 0 var(--primary);
        --kp-cp-b1: 4px 3px 0 var(--accent), 4px -3px 0 var(--primary);
        --kp-cp-b2: 2px 2px 0 var(--accent), 2px -2px 0 var(--primary);
        --kp-cp-b3: 1px 1px 0 var(--accent), 1px -1px 0 var(--primary);
    }

    /* ...and the arrival that goes with them [Kenny, 2026-10-12: "Command palette is hetzelfde, geen
       glitch effect bij open/close?"]. These parts had the shape and the copies' tokens but no
       `animation`: the package default (none for the palette) ran, so the pair meter, which times
       and mirrors whatever runs, passed them. A dialog's entrance is kept by js/motion.js and its
       close plays it backwards, so one declaration is the pair. The drawer is a `.kp-dialog` and
       has the dialog's. The alarm keeps its own approved strike (scope-94, scope-100). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] :is(.kp-palette, .kp-shortcuts) {
            animation: kp-sig-cyberpunk-split 480ms steps(1, end) backwards;
        }
    }

    /* The side navigation's panel plays its copies outside its box while its clock runs, so its
       cut is wide by the same clock: no room round the plate at rest, 40 px while it plays. */
    [data-theme='cyberpunk'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) {
        --kp-cp-e: calc(min(1, var(--kp-sn-t)) * 40px);
        clip-path: polygon(
            calc(-1 * var(--kp-cp-e)) calc(-1 * var(--kp-cp-e)),
            calc(100% - var(--kp-cp-notch) - var(--kp-cp-e)) calc(-1 * var(--kp-cp-e)),
            calc(100% + var(--kp-cp-e)) calc(var(--kp-cp-notch) + var(--kp-cp-e)),
            calc(100% + var(--kp-cp-e)) calc(100% + var(--kp-cp-e)),
            calc(-1 * var(--kp-cp-e)) calc(100% + var(--kp-cp-e))
        );
    }

    [data-theme='cyberpunk']
        :is(.kp-tag, .kp-icon-button, .kp-switch__input, .kp-chart__source, .kp-attention__icon, .kp-combobox__input, .kp-skip-link) {
        --kp-cp-clip: var(--kp-cp-clip-ctl);
        --kp-cp-wide: var(--kp-cp-wide-ctl);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
    }

    [data-theme='cyberpunk'] .kp-tab {
        --kp-cp-clip: var(--kp-cp-clip-ctl-top);
        --kp-cp-wide: var(--kp-cp-wide-ctl-top);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
    }

    [data-theme='cyberpunk'] :is(.kp-datatable__sort-order, .kp-chart__dot, .kp-swatch, .kp-tag__remove) {
        --kp-cp-clip: var(--kp-cp-clip-mini);
        --kp-cp-wide: var(--kp-cp-wide-mini);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
    }

    /* A cut part has no room outside its box for an outline, so its focus is the ring drawn
       inset in two channels, as the button's is. */
    [data-theme='cyberpunk'] :is(.kp-icon-button, .kp-tab, .kp-switch__input, .kp-combobox__input, .kp-skip-link, .kp-chart__source):focus-visible {
        outline: none;
        box-shadow:
            inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 calc(var(--kp-focus-ring-inner-width, 2px) + 2px) var(--focus-ring-contrast);
    }

    /* ── D. Prose is Rajdhani, the machine's names are mono [G15, lesson 18] ────────────────
       The register had put the mono face on whole parts; the words inside them are prose. */
    [data-theme='cyberpunk']
        :is(
            .kp-alarm__detail,
            .kp-field__help,
            .kp-field__error,
            .kp-empty__body,
            .kp-toast__body,
            .kp-palette,
            .kp-palette__option,
            .kp-palette__description,
            .kp-theme-menu__status,
            .kp-cell-truncate,
            .kp-truncate,
            .kp-accordion__summary,
            .kp-shortcuts__row dd,
            .kp-error,
            .kp-media-figure > figcaption
        ) {
        font-family: var(--theme-font-body);
        letter-spacing: 0.02em;
    }

    [data-theme='cyberpunk'] .kp-media-figure > figcaption {
        text-transform: none;
        font-size: 0.8125rem;
    }

    [data-theme='cyberpunk'] .kp-palette__keys {
        font-family: var(--kp-mono);
    }

    [data-theme='cyberpunk'] .kp-field__error::before {
        font-family: var(--kp-mono);
    }

    /* The machine's prefixes [G15]: `//` before a badge, tag, table head, timestamp and a group
       label, `!!` before a failure's badge; tracked as the labels are. */
    [data-theme='cyberpunk']
        :is(
            .kp-badge,
            .kp-tag,
            .kp-table th:not(:has(input)),
            .kp-timestamp,
            .kp-theme-group__label,
            .kp-shortcuts__group-label,
            .kp-alert__label
        )::before {
        content: '// ';
        content: '// ' / '';
        opacity: 0.7;
    }

    [data-theme='cyberpunk'] :is(.kp-badge--destructive, .kp-badge--warning, .kp-badge[data-status='rejected'])::before {
        content: '!! ';
        content: '!! ' / '';
    }

    [data-theme='cyberpunk'] :is(.kp-theme-group__label, .kp-shortcuts__group-label, .kp-alert__label, .kp-progress__label) {
        font-family: var(--kp-mono);
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }

    [data-theme='cyberpunk'] .kp-timestamp {
        letter-spacing: 0.12em;
    }

    /* ── Leftovers of the notch round [Kenny, 2026-10-12] ───────────────────────────────────
       The check, the calendar and date picker days, the date picker's title and the table's search
       field were still rectangles. A control is cut 8 px; a part too small for that (the check, 18 px)
       by a share of its height (`--kp-cp-clip-mini`). The radio and the graph stay round (G6). The
       focus brackets and the split edge are drawn inside the box, so the cut does not take them:
       the corner brackets sit half a cut clear of the diagonal (`--kp-cp-nbr`). A bare accordion
       item has no chrome, so no plate and no cut. */
    [data-theme='cyberpunk'] :is(.kp-calendar__day, .kp-datepicker__day, .kp-datepicker__title, .kp-datatable__search) {
        --kp-cp-clip: var(--kp-cp-clip-ctl);
        --kp-cp-wide: var(--kp-cp-wide-ctl);
        --kp-cp-nbr: calc(var(--kp-cp-notch-sm) + 2px);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
    }

    [data-theme='cyberpunk'] .kp-nav__search-trigger {
        --kp-cp-nbr: calc(var(--kp-cp-notch-sm) + 2px);
    }

    [data-theme='cyberpunk'] :is(.kp-nav__search-trigger, .kp-combobox__clear) {
        --kp-cp-clip: var(--kp-cp-clip-ctl);
        --kp-cp-wide: var(--kp-cp-wide-ctl);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
    }

    /* A colour sample and a legend swatch are small parts: the cut is a share of their height. */
    [data-theme='cyberpunk'] :is(.kp-colorpicker__swatch, .kp-calendar__swatch, .kp-spec__swatch, .kp-datatable__edit, .kp-datatable__pill-edit) {
        --kp-cp-clip: var(--kp-cp-clip-mini);
        --kp-cp-wide: var(--kp-cp-wide-mini);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
    }

    [data-theme='cyberpunk'] .kp-accordion__item--bare {
        clip-path: none;
    }

    /* The item is a plate now: its words keep clear of the rim and the notch. */
    [data-theme='cyberpunk'] .kp-accordion__item:not(.kp-accordion__item--bare) > :is(.kp-accordion__summary, .kp-accordion__body) {
        padding-inline: 1rem;
    }

    [data-theme='cyberpunk'] .kp-field__check:not([type='radio']) {
        --kp-cp-clip: var(--kp-cp-clip-mini);
        --kp-cp-wide: var(--kp-cp-wide-mini);
        border-radius: 0;
        clip-path: var(--kp-cp-clip);
        background-image: linear-gradient(135deg, transparent calc(50% - 1px), var(--primary) calc(50% - 1px));
        background-position: right bottom;
        background-size: 7px 7px;
        background-repeat: no-repeat;
    }

    /* A check on its own is framed inside itself now (the cut would take a frame drawn outside): the
       brackets are 6 px long and close from 4 px, the split edge is a third of the pair's. */
    [data-theme='cyberpunk'] input.kp-field__check:not([type='radio']):not(.kp-field__option *, .kp-field--check *, .kp-menu__item *) {
        --kp-cp-i: calc(var(--kp-cp-ft) * 1px);
        --kp-cp-fa: calc(var(--kp-cp-fp) * 5px);
        --kp-cp-fai: calc(var(--kp-cp-fp) * 3px);
        --kp-cp-nbr: 10px;
        --kp-cp-d: calc(var(--kp-cp-p) * (1px + var(--kp-cp-t) * 0.5px));
    }

    [data-theme='cyberpunk'] input.kp-field__check:not([type='radio']):not(.kp-field__option *, .kp-field--check *, .kp-menu__item *)::after {
        inset: 0;
    }

    /* The check inside a label is framed by the label; its own outline would be cut, so it has none. */
    [data-theme='cyberpunk'] .kp-field__check:not([type='radio']):focus-visible {
        outline: none;
    }
    /* <<cfd-end>> */
}

