}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — cyberpunk: a locked target. The current tab is a yellow notched plate with dark ink, acquired in ticks (never eased), the labels prefixed-mono capitals (G1, G5, G6, G15); a count is a notched yellow-and-black tag. */
    [data-theme='cyberpunk'] .kp-tabbar {
        background: var(--background);
        border-block-start: 1px solid var(--primary);
    }

    [data-theme='cyberpunk'] .kp-tabbar__tab {
        border-radius: 0;
        isolation: isolate;
        font-family: var(--theme-font-mono);
