/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Cyberpunk's own (themes/cyberpunk/CHARACTER.md): every plate is a holo card, the void with a yellow rim glowing
   inward, scan lines at 135 degrees, cut at its dossier corner (G6, G7); pointing lights the 14 px circuit in one tick
   (G8) and a press closes it (G14); a failure is locked as a target, four corner brackets in the red (G13); the machine
   speaks in prefixed mono capitals (G15); waiting is signal loss, the word LOADING deciphered over the dimmed part, once
   per waiting part and never once per cell (the register's osd); a running job is a data stream through its wire (G16).
   Hard ticks everywhere, never an ease. */
@layer kp.signature {
    [data-theme='cyberpunk'] .kp-actions {
        --kp-actions-gap: 0.75rem;
    }
    [data-theme='cyberpunk'] .kp-action {
        --kp-action-radius: 0;
        --kp-action-edge: transparent;
        --kp-action-edge-hover: transparent;
        --kp-action-press: 0 0;
        --kp-action-title-font: var(--kp-mono);
        --kp-action-title-case: uppercase;
        --kp-action-title-tracking: 0.12em;
        --kp-action-title-size: 0.875rem;
        --kp-action-pad: 0.75rem 0.875rem;
        --kp-cp-ground: var(--card);
        --kp-cp-grid-a: 0;
        --kp-cp-lk: 3px;
        --kp-cp-rest: inset 0 0 0 1px var(--primary), inset 0 0 10px hsl(from var(--primary) h s l / 0.35);
        --kp-cp-tile-grid:
            repeating-linear-gradient(to bottom, hsl(from var(--primary) h s l / var(--kp-cp-grid-a)) 0 1px, transparent 1px 14px),
            repeating-linear-gradient(to right, hsl(from var(--primary) h s l / var(--kp-cp-grid-a)) 0 1px, transparent 1px 14px);
        --kp-cp-tile-notch: linear-gradient(45deg, transparent calc(50% - 1.5px), var(--primary) calc(50% - 1.5px) 50%, transparent 50%) 100% 0 /
            var(--kp-cp-notch) var(--kp-cp-notch) no-repeat;
        --kp-cp-tile-scan: repeating-linear-gradient(135deg, hsl(from var(--primary) h s l / 0.06) 0 2px, transparent 2px 6px);
        --kp-cp-tile-lock: linear-gradient(transparent, transparent);
        background: var(--kp-cp-tile-lock), var(--kp-cp-tile-grid), var(--kp-cp-tile-notch), var(--kp-cp-tile-scan), var(--kp-cp-ground);
        box-shadow: var(--kp-cp-rest);
        clip-path: var(--kp-cp-clip-plate);
    }
    [data-theme='cyberpunk'] .kp-action > :not(.kp-action__state) {
        position: relative;
    }
    /* The sentence is the machine's read-out: cyan reads (G5). */
    [data-theme='cyberpunk'] .kp-action__meta {
        color: var(--accent);
        font-family: var(--kp-mono);
        letter-spacing: 0.08em;
    }
    [data-theme='cyberpunk'] .kp-action__meta::before {
        content: '// ';
        opacity: 0.7;
    }
    [data-theme='cyberpunk'] .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        --kp-cp-grid-a: 0.3;
        box-shadow: var(--kp-cp-rest);
    }
    [data-theme='cyberpunk'] .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        --kp-cp-grid-a: 0.6;
        --kp-cp-ground: color-mix(in oklab, var(--primary) 12%, var(--card));
        box-shadow: var(--kp-cp-rest);
    }
    /* Focus: DI2's two channels drawn inset, so the notch never cuts them; the circuit lit as under the pointer. */
    [data-theme='cyberpunk'] .kp-action:focus-visible {
        --kp-cp-grid-a: 0.3;
        outline: none;
        box-shadow:
            inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 calc(var(--kp-focus-ring-inner-width, 2px) + 2px) var(--focus-ring-contrast);
    }
    [data-theme='cyberpunk'] .kp-action:is(:disabled, [aria-disabled='true']) {
        --kp-cp-rest: inset 0 0 0 1px var(--border);
        --kp-cp-ground: var(--muted);
        --kp-cp-tile-notch: linear-gradient(transparent, transparent);
        box-shadow: var(--kp-cp-rest);
    }
    /* Destructive: locked as a target. Four 2 px corner brackets in the red, the title in the red; no side bar. */
    [data-theme='cyberpunk'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) {
        --kp-cp-tone: var(--destructive);
        --kp-cp-rest: inset 0 0 0 1px hsl(from var(--destructive) h s l / 0.55), inset 0 0 10px hsl(from var(--destructive) h s l / 0.3);
        --kp-cp-tile-lock:
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) var(--kp-cp-lk) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) var(--kp-cp-lk) / 2px 9px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) calc(100% - var(--kp-cp-lk)) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) calc(100% - var(--kp-cp-lk)) / 2px 9px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) calc(100% - var(--kp-cp-lk)) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) calc(100% - var(--kp-cp-lk)) / 2px 9px no-repeat;
        --kp-cp-tile-notch: linear-gradient(45deg, transparent calc(50% - 1.5px), var(--destructive) calc(50% - 1.5px) 50%, transparent 50%) 100% 0 /
            var(--kp-cp-notch) var(--kp-cp-notch) no-repeat;
    }
    [data-theme='cyberpunk'] .kp-action--destructive::after {
        display: none;
    }
    [data-theme='cyberpunk'] .kp-action--destructive > .kp-action__title {
        color: var(--destructive);
    }
    [data-theme='cyberpunk'] .kp-action--destructive:is(:disabled, [aria-disabled='true']) > .kp-action__title {
        color: inherit;
    }

    /* Status rows: square read-outs with a hairline; a failed row is locked as a target in the red; the detail is the
       machine's mono. */
    [data-theme='cyberpunk'] .kp-statuslist {
        --kp-statusrow-mark-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-statusrow {
        --kp-statusrow-radius: 0;
        --kp-statusrow-edge: var(--kp-hairline, var(--border));
        --kp-cp-lk: 3px;
        clip-path: var(--kp-cp-clip-ctl);
    }
    [data-theme='cyberpunk'] .kp-statusrow[data-state='failed'] {
        --kp-cp-tone: var(--destructive);
        --kp-statusrow-state-edge: hsl(from var(--destructive) h s l / 0.45);
        background:
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) var(--kp-cp-lk) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) var(--kp-cp-lk) / 2px 9px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) var(--kp-cp-lk) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) calc(100% - var(--kp-cp-lk)) var(--kp-cp-lk) / 2px 9px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) calc(100% - var(--kp-cp-lk)) / 9px 2px no-repeat,
            linear-gradient(var(--kp-cp-tone) 0 0) var(--kp-cp-lk) calc(100% - var(--kp-cp-lk)) / 2px 9px no-repeat,
            var(--card);
    }
    [data-theme='cyberpunk'] .kp-statusrow[data-state='loading'] {
        --kp-statusrow-state-edge: hsl(from var(--accent) h s l / 0.6);
    }
    [data-theme='cyberpunk'] .kp-statusrow__detail {
        font-family: var(--kp-mono);
        letter-spacing: 0.04em;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-statusrow[data-state='failed'] {
            animation: kp-sig-cyberpunk-lock 360ms steps(1, end) 1 both;
        }
    }

    /* Facets: square rows; pointing lights the circuit in the row; the title and the counts are mono read-outs. The
       counts on their way are notched slots whose lock blinks cyan, yellow, cyan in hard ticks. */
    [data-theme='cyberpunk'] .kp-facets {
        --kp-facet-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-facet {
        --kp-facet-hover: hsl(from var(--primary) h s l / 0.08);
    }
    [data-theme='cyberpunk'] .kp-facet:hover {
        background-image:
            repeating-linear-gradient(to bottom, hsl(from var(--primary) h s l / 0.3) 0 1px, transparent 1px 14px),
            repeating-linear-gradient(to right, hsl(from var(--primary) h s l / 0.3) 0 1px, transparent 1px 14px);
    }
    [data-theme='cyberpunk'] :is(.kp-facets__title, .kp-facet__count) {
        font-family: var(--kp-mono);
    }
    [data-theme='cyberpunk'] .kp-facets__title {
        color: var(--accent);
        letter-spacing: 0.14em;
        text-transform: uppercase;
    }
    [data-theme='cyberpunk'] .kp-facets__title::before {
        content: '/// ';
        opacity: 0.7;
    }
    [data-theme='cyberpunk'] .kp-facets[aria-busy='true'] .kp-facet__count {
        border-radius: 0;
        background: var(--sidebar-background);
        box-shadow: inset 0 0 0 1px var(--accent);
        clip-path: var(--kp-cp-clip-ctl);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-facets[aria-busy='true'] .kp-facet__count {
            animation: kp-sig-cyberpunk-blink 1800ms steps(1, end) infinite;
        }
    }

    /* Heat grid and matrix: neon tubes in the void. A cell is a dark tinted ground in its tone's neon edge with a glow
       of the same hue; the pick is a cyan tube; pointing lights the cell's tube (G8). Waiting, the cells dim and one
       word is deciphered over the grid, not one per cell. */
    [data-theme='cyberpunk'] .kp-heat {
        --kp-heat-cell-radius: 0;
        --kp-heat-cell-gap: 2px;
        --kp-heat-gap-y: 6px;
        position: relative;
    }
    [data-theme='cyberpunk'] .kp-matrix {
        --kp-heat-cell-radius: 0;
        --kp-matrix-gap: 4px;
    }
    [data-theme='cyberpunk'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-hover: none;
        --kp-matrix-cell-hover: none;
    }
    [data-theme='cyberpunk']
        .kp-heat__cell:is([data-kp-tone='ok'], [data-kp-tone='warn'], [data-kp-tone='bad'], [data-kp-tone='level']):not([data-kp-share]),
    [data-theme='cyberpunk'] .kp-heat__swatch:is([data-kp-tone='ok'], [data-kp-tone='warn'], [data-kp-tone='bad'], [data-kp-tone='level']) {
        background-color: hsl(from var(--kp-heat-fill) h calc(s * 0.6) 11%);
        background-image: linear-gradient(to top, var(--kp-heat-fill) 0 3px, transparent 3px), var(--kp-heat-pattern);
        border-color: var(--kp-heat-fill);
        box-shadow: 0 0 6px hsl(from var(--kp-heat-fill) h s l / 0.55);
    }
    [data-theme='cyberpunk'] .kp-heat__cell[data-kp-share] {
        background-color: hsl(from var(--muted) h s 8%);
        border-color: hsl(from var(--kp-heat-fill) h s l / 0.7);
    }
    [data-theme='cyberpunk'] .kp-heat__cell:hover:not(.kp-skeleton, [aria-disabled='true']),
    [data-theme='cyberpunk'] .kp-matrix__cell:hover:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
        border-color: var(--primary);
        box-shadow: 0 0 10px hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='cyberpunk'] .kp-heat__cell[data-kp-picked],
    [data-theme='cyberpunk'] .kp-matrix__cell[aria-pressed='true'] {
        outline: 2px solid var(--accent);
        outline-offset: 1px;
        box-shadow: 0 0 10px var(--accent);
    }
    [data-theme='cyberpunk'] :is(.kp-heat__label, .kp-matrix__name, .kp-heat__col, .kp-matrix__col) {
        font-family: var(--kp-mono);
        text-transform: uppercase;
        letter-spacing: 0.06em;
        font-size: var(--kp-text-xs, 0.75rem);
    }
    [data-theme='cyberpunk'] :is(.kp-heat__label-button, .kp-matrix__name) {
        border-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-heat__label-button[aria-pressed='true'] {
        background: hsl(from var(--primary) h s l / 0.14);
        color: var(--primary);
        box-shadow: inset 0 0 0 1px var(--primary);
    }
    /* Waiting: the cells and the names stand dim and wordless; one LOADING is deciphered over the cells' columns. */
    [data-theme='cyberpunk']
        :is(.kp-heat__cell, .kp-matrix__cell, .kp-heat__label-skeleton, .kp-matrix__col--skeleton, .kp-matrix__row--skeleton).kp-skeleton {
        opacity: 0.45;
    }
    [data-theme='cyberpunk']
        :is(.kp-heat__cell, .kp-matrix__cell, .kp-heat__label-skeleton, .kp-matrix__col--skeleton, .kp-matrix__row--skeleton).kp-skeleton::before {
        content: none;
        animation: none;
    }
    [data-theme='cyberpunk'] .kp-heat:has(.kp-heat__cell.kp-skeleton)::after,
    [data-theme='cyberpunk'] .kp-matrix:has(.kp-matrix__cell.kp-skeleton)::after,
    [data-theme='cyberpunk'] .kp-gantt[data-kp-state='loading'] .kp-gantt__plot::after {
        content: var(--kp-loading-word-7, 'LOADING');
        position: absolute;
        inset: 0 0 0 calc(clamp(4.5rem, 26%, var(--kp-heat-label, 8rem)) + var(--kp-heat-gap-x, 0.75rem));
        z-index: 2;
        inline-size: fit-content;
        block-size: fit-content;
        margin: auto;
        padding: 0.25rem 0.625rem;
        background: var(--card);
        box-shadow: inset 0 0 0 1px var(--accent);
        color: var(--foreground);
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.24em;
        line-height: 1.2;
        text-shadow:
            2px -1px 0 var(--accent),
            2px 1px 0 var(--destructive);
        pointer-events: none;
    }
    [data-theme='cyberpunk'] :is(.kp-matrix, .kp-gantt[data-kp-state='loading'] .kp-gantt__plot)::after {
        inset: 0;
    }
    /* Under the busy card (js/busy-card.js: the data table's loading card, centred over the data) the card is the one
       loading picture: the deciphered LOADING gives way to it, never stands beside or on it. */
    [data-theme='cyberpunk'] :is(.kp-heat, .kp-matrix):has(> .kp-datatable__busy-card.kp-datatable__busy-overlay)::after,
    [data-theme='cyberpunk'] .kp-gantt[data-kp-state='loading']:has(.kp-datatable__busy-card) .kp-gantt__plot::after {
        content: none;
        animation: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-heat:has(.kp-heat__cell.kp-skeleton)::after,
        [data-theme='cyberpunk'] .kp-matrix:has(.kp-matrix__cell.kp-skeleton)::after,
        [data-theme='cyberpunk'] .kp-gantt[data-kp-state='loading'] .kp-gantt__plot::after {
            animation:
                kp-sig-cyberpunk-word 1800ms steps(1, end) infinite,
                kp-sig-cyberpunk-word-tear 1800ms steps(1, end) infinite;
        }
    }
    [data-theme='cyberpunk'] .kp-bar-cell {
        --kp-bar-cell-gap: var(--kp-space-sm, 0.5rem);
        font-family: var(--kp-mono);
        font-variant-numeric: tabular-nums;
    }

    /* Week agenda and run timeline: HUD read-outs. One notched corner (cut outwards past the box so the focus ring
       stays whole), a hard 3 px bar on the leading edge in the series' ink, the time in mono; the line for now is the
       primary. A running run is a data stream: the void in a yellow rim with cyan dashes moving through it. */
    [data-theme='cyberpunk'] .kp-week {
        --kp-week-pill-radius: 0;
        --kp-week-now: var(--primary);
    }
    [data-theme='cyberpunk'] .kp-gantt {
        --kp-gantt-state-ground: var(--card);
        --kp-gantt-bar-radius: 0;
        --kp-gantt-now: var(--primary);
    }
    [data-theme='cyberpunk'] :is(.kp-week__pill, .kp-gantt__run) {
        --kp-cp-pill-notch: var(--fx-notch-sm, 8px);
        clip-path: polygon(
            -8px -8px,
            calc(100% + 8px) -8px,
            calc(100% + 8px) calc(100% - var(--kp-cp-pill-notch) - 8px),
            calc(100% - var(--kp-cp-pill-notch) - 8px) calc(100% + 8px),
            -8px calc(100% + 8px)
        );
    }
    /* A bar can be a few pixels wide: its cut is the small one, so a short run stays a bar and not a wedge. */
    [data-theme='cyberpunk'] .kp-gantt__run {
        --kp-cp-pill-notch: 4px;
    }
    [data-theme='cyberpunk'] .kp-week__pill {
        border-color: var(--kp-hairline, var(--border));
        border-inline-start: 3px solid var(--kp-week-ink);
    }
    [data-theme='cyberpunk'] .kp-week__pill:is(button):hover {
        box-shadow:
            0 0 0 1px var(--primary),
            0 0 8px hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='cyberpunk'] :is(.kp-week__time, .kp-week__head, .kp-gantt__tick, .kp-week__axis > span) {
        font-family: var(--kp-mono);
    }
    [data-theme='cyberpunk'] .kp-week__now::before {
        border-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-gantt__run:is(button):hover {
        box-shadow:
            0 0 0 1px var(--primary),
            0 0 8px hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='running'] {
        position: absolute;
        border-color: var(--primary);
        background: var(--card);
        color: var(--foreground);
        box-shadow: inset -3px 0 0 var(--primary);
    }
    [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='running']::after {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline: -144px 0;
        background:
            repeating-linear-gradient(90deg, var(--accent) 0 18px, transparent 18px 36px) 0 30% / 100% 2px no-repeat,
            repeating-linear-gradient(90deg, transparent 0 9px, var(--accent) 9px 15px, transparent 15px 36px) 0 70% / 100% 2px no-repeat;
        opacity: 0.8;
        pointer-events: none;
    }
    [data-theme='cyberpunk'] .kp-gantt__swatch[data-kp-state='running'] {
        border-color: var(--primary);
        background:
            repeating-linear-gradient(90deg, var(--accent) 0 3px, transparent 3px 6px) 0 50% / 100% 2px no-repeat,
            var(--card);
    }
    /* The loading sentence is the machine's voice on a plate of the void, never over a ghost bar's edge. */
    [data-theme='cyberpunk'] .kp-gantt[data-kp-state='loading'] .kp-gantt__state {
        display: none;
    }
    [data-theme='cyberpunk'] .kp-gantt__ghost .kp-skeleton {
        opacity: 0.45;
    }
    [data-theme='cyberpunk'] .kp-gantt__ghost .kp-skeleton::before {
        content: none;
        animation: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='running'] {
            animation: none;
        }
        [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='running']::after {
            animation: kp-sig-cyberpunk-feed 1800ms linear infinite;
        }
    }

    /* A phone's timeline keeps its toolbar on one row: the range steps close in a little in these wide letters. */
    @container kp-gantt (max-width: 22rem) {
        [data-theme='cyberpunk'] .kp-gantt__ranges {
            --kp-seg-item-pad-inline: 0.5rem;
        }
    }

    /* The waiting count's lock blinks: cyan, yellow, cyan, then the void, in hard ticks. */
    @keyframes kp-sig-cyberpunk-blink {
        0% {
            box-shadow: inset 0 0 0 1px var(--accent);
        }

        20% {
            box-shadow: inset 0 0 0 1px var(--primary);
        }

        40% {
            box-shadow: inset 0 0 0 1px var(--accent);
        }

        60%,
        100% {
            box-shadow: inset 0 0 0 1px var(--border);
        }
    }

    /* The stream through a running bar: the dashes move one period of 144 px along it. */
    @keyframes kp-sig-cyberpunk-feed {
        from {
            transform: translateX(0);
        }

        to {
            transform: translateX(144px);
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='cyberpunk'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='cyberpunk'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='cyberpunk'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='cyberpunk'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='cyberpunk'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='cyberpunk'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Cyberpunk's own (themes/cyberpunk/CHARACTER.md): the separator is the neon slash, the yellow leaning with
   the bar's own cut and split into its cyan ghost (the RGB split); lying down in the phone's list it is a short data
   dash on the plate, yellow then a cyan packet, never wider than the plate. A day on the axis takes the RGB split under
   the pointer; pressed it is a lock-on: the yellow ground with its notched corner and the hard yellow foot. A series'
   finished run has the hard 3 px bar on its leading edge, as a week pill does; the facet pattern is notched. */
@layer kp.signature {
    [data-theme='cyberpunk'] .kp-nav__sep {
        inline-size: 2px;
        border-inline-start: 0;
        background: var(--primary);
        box-shadow: -2px 0 0 hsl(from var(--accent) h s l / 0.75);
        transform: skewX(-18deg);
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='cyberpunk'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            inline-size: 3.25rem;
            block-size: 2px;
            margin-inline: var(--kp-space-lg, 1rem) auto;
            border-block-start: 0;
            background: linear-gradient(90deg, var(--primary) 0 68%, transparent 68% 76%, var(--accent) 76% 100%);
            box-shadow: none;
            transform: none;
        }
    }

    [data-theme='cyberpunk'] .kp-gantt__tick:is(button) {
        border-radius: 0;
        text-decoration: none;
    }
    [data-theme='cyberpunk'] .kp-gantt__tick:is(button):hover {
        color: var(--primary);
        text-shadow:
            -1px 0 hsl(from var(--accent) h s l / 0.9),
            1px 0 hsl(from var(--destructive) h s l / 0.9);
    }
    [data-theme='cyberpunk'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: linear-gradient(225deg, transparent 5px, hsl(from var(--primary) h s l / 0.18) 5px);
        color: var(--primary);
        box-shadow: inset 0 -2px 0 var(--primary);
        text-shadow: none;
    }
    [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='ok'][data-kp-series] {
        box-shadow: inset 3px 0 0 var(--kp-gantt-series);
    }
    [data-theme='cyberpunk'] .kp-gantt__run[data-kp-state='ok'][data-kp-series]:hover {
        box-shadow:
            inset 3px 0 0 var(--kp-gantt-series),
            0 0 0 1px var(--primary),
            0 0 8px hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='cyberpunk'] .kp-week__next:not(:has(+ .kp-week__next:not([data-kp-day-start]))) {
        border-block-end-color: var(--kp-hairline, var(--border));
    }
    [data-theme='cyberpunk'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 0;
        clip-path: polygon(0 0, calc(100% - 4px) 0, 100% 4px, 100% 100%, 0 100%);
    }
}

/* ── The kpadopt4 components in cyberpunk's own grammar [kpadopt4] ──
   Cyberpunk is the netrunner's HUD (themes/cyberpunk/CHARACTER.md): the void is the ground, the holo card what stands on
   it, the HUD what the system draws over it. A signal is acquired, never eased: a part that is drawn is torn in sideways
   and jitters home in six ticks of 60 ms, held poses with `steps(1)` (G1, G3, G12); pointing lights the 14 px circuit in
   its own ink in one tick (G8); a press lights it full (G14); a warning is locked as a target, four corner brackets, 2 px,
   in the tone's ink (G13); the machine talks in prefixed mono capitals, figures in the condensed display (G15); a
   control is cut at its end corner, a plate at its dossier corner, never rounded (G6). Yellow acts, cyan reads, red
   alarms. Waiting is the reticle's lock-on the register already lays; the data stream is only for what is transferred. */
@layer kp.signature {
    [data-theme='cyberpunk'] {
        --kp-cp4-tick: 60ms;
        --kp-cp4-grid:
            repeating-linear-gradient(to bottom, hsl(from var(--primary) h s l / 0.3) 0 1px, transparent 1px 14px),
            repeating-linear-gradient(to right, hsl(from var(--primary) h s l / 0.3) 0 1px, transparent 1px 14px);
        --kp-cp4-grid-press:
            repeating-linear-gradient(to bottom, hsl(from var(--primary) h s l / 0.6) 0 1px, transparent 1px 14px),
            repeating-linear-gradient(to right, hsl(from var(--primary) h s l / 0.6) 0 1px, transparent 1px 14px);
        --kp-cp4-scan: repeating-linear-gradient(135deg, hsl(from var(--primary) h s l / 0.06) 0 2px, transparent 2px 6px);
        --kp-cp4-trip: repeating-linear-gradient(90deg, var(--primary) 0 6px, transparent 6px 10px);
        --kp-cp4-n: 8px;
        --kp-cp4-cut: polygon(0 0, 100% 0, 100% calc(100% - var(--kp-cp4-n)), calc(100% - var(--kp-cp4-n)) 100%, 0 100%);
        --kp-cp4-cut-top: polygon(0 0, calc(100% - var(--kp-cp4-n)) 0, 100% var(--kp-cp4-n), 100% 100%, 0 100%);
        --kp-cp4-cut-open: polygon(-12% -40%, 140% -40%, 140% calc(100% - var(--kp-cp4-n)), calc(100% - var(--kp-cp4-n)) 100%, -12% 100%);
        --kp-art-rule: var(--primary);
        --kp-art-line: var(--border-strong);
        --kp-art-ink: var(--accent);
        --kp-art-red: var(--destructive);
        --kp-art-stroke: 1.5px;
    }
    /* Four 2 px corner brackets in the tone, as background layers (set --kp-cp4-tone on the part). */
    [data-theme='cyberpunk'] :is(
            .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure,
            .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure,
            .kp-action-list--lead > li[data-kp-state='failed'],
            .kp-action-list--lead > li[data-kp-state='warn'],
            .kp-kv__row[data-kp-state='error'],
            .kp-formrow[data-kp-state='error'],
            .kp-statusrow[data-state='warn'],
            .kp-timer[data-kp-timer-state='done'],
            .kp-countdown[data-kp-countdown-state='ended'],
            .kp-timer-disc[data-kp-timer-disc-state='ended'] .kp-timer-disc__face,
            .kp-segmented__item[data-kp-segmented-tri='exclude'],
            .kp-dialog__section--danger,
            .kp-pipeline__card[aria-current='true'],
            .kp-secret[data-kp-secret-state='error'] .kp-secret__value
        ) {
        --kp-cp4-b: 2px;
        --kp-cp4-a: 9px;
        --kp-cp4-o: 3px;
        --kp-cp4-lock:
            linear-gradient(var(--kp-cp4-tone) 0 0) var(--kp-cp4-o) var(--kp-cp4-o) / var(--kp-cp4-a) var(--kp-cp4-b) no-repeat,
            linear-gradient(var(--kp-cp4-tone) 0 0) var(--kp-cp4-o) var(--kp-cp4-o) / var(--kp-cp4-b) var(--kp-cp4-a) no-repeat,
            linear-gradient(var(--kp-cp4-tone) 0 0) calc(100% - var(--kp-cp4-o)) var(--kp-cp4-o) / var(--kp-cp4-a) var(--kp-cp4-b) no-repeat,
            linear-gradient(var(--kp-cp4-tone) 0 0) calc(100% - var(--kp-cp4-o)) var(--kp-cp4-o) / var(--kp-cp4-b) var(--kp-cp4-a) no-repeat,
            linear-gradient(var(--kp-cp4-tone) 0 0) var(--kp-cp4-o) calc(100% - var(--kp-cp4-o)) / var(--kp-cp4-a) var(--kp-cp4-b) no-repeat,
            linear-gradient(var(--kp-cp4-tone) 0 0) var(--kp-cp4-o) calc(100% - var(--kp-cp4-o)) / var(--kp-cp4-b) var(--kp-cp4-a) no-repeat,
            linear-gradient(var(--kp-cp4-tone) 0 0) calc(100% - var(--kp-cp4-o)) calc(100% - var(--kp-cp4-o)) / var(--kp-cp4-a) var(--kp-cp4-b) no-repeat,
            linear-gradient(var(--kp-cp4-tone) 0 0) calc(100% - var(--kp-cp4-o)) calc(100% - var(--kp-cp4-o)) / var(--kp-cp4-b) var(--kp-cp4-a) no-repeat;
    }

    /* ── Identity mark: the plate in the name's colour, cut at its end corner; the letters are the machine's mono ── */
    [data-theme='cyberpunk'] .kp-idmark {
        --kp-idmark-radius: 0;
        font-family: var(--kp-mono);
        font-weight: 700;
        letter-spacing: 0.04em;
        clip-path: var(--kp-cp4-cut);
    }
    [data-theme='cyberpunk'] .kp-idmark--round {
        border-radius: 0;
        clip-path: polygon(
            var(--kp-cp4-n) 0,
            100% 0,
            100% calc(100% - var(--kp-cp4-n)),
            calc(100% - var(--kp-cp4-n)) 100%,
            0 100%,
            0 var(--kp-cp4-n)
        );
    }
    [data-theme='cyberpunk'] .kp-idmark--glyph {
        clip-path: var(--kp-cp4-cut-open);
    }
    [data-theme='cyberpunk'] .kp-idmark--glyph::after {
        border-radius: 0;
        box-shadow: none;
    }
    [data-theme='cyberpunk'] .kp-idmark--glyph[data-kp-idmark-glyph='circle']::after {
        border-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-idmark[aria-current]:not([aria-current='false']),
    [data-theme='cyberpunk'] .kp-idmark[data-kp-idmark-selected] {
        clip-path: none;
        box-shadow: none;
        outline: 2px solid var(--primary);
        outline-offset: 2px;
    }
    [data-theme='cyberpunk'] .kp-idmark-group > .kp-idmark {
        box-shadow: none;
    }
    [data-theme='cyberpunk'] .kp-idmark-group__more {
        border-radius: 0;
        font-family: var(--kp-mono);
    }

    /* ── Share bar: the parts are held bars with a 2 px gap; pointing lights the circuit on the part in one tick; the
       threshold is the reticle's tick; the title and the readings are the machine's mono ── */
    [data-theme='cyberpunk'] .kp-stackbar {
        --kp-stackbar-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-stackbar__title {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='cyberpunk'] .kp-stackbar__title::before {
        content: '/// ';
        color: var(--accent);
        opacity: 0.7;
    }
    [data-theme='cyberpunk'] .kp-stackbar__total,
    [data-theme='cyberpunk'] .kp-stackbar__value {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.08em;
        color: var(--accent);
    }
    [data-theme='cyberpunk'] .kp-stackbar__bar {
        background: var(--kp-cp4-scan), var(--muted);
        box-shadow: inset 0 0 0 1px var(--border);
        clip-path: var(--kp-cp4-cut);
    }
    [data-theme='cyberpunk'] .kp-stackbar__seg {
        border-radius: 0;
        outline: 0;
    }
    [data-theme='cyberpunk'] .kp-stackbar__seg[data-kp-stackbar-lit] {
        background-image: var(--kp-cp4-grid-press);
        box-shadow: inset calc(var(--kp-stackbar-gap, 2px) * -1) 0 0 var(--card);
    }
    [data-theme='cyberpunk'] .kp-stackbar__mark {
        inset-block: -2px;
        background: var(--accent);
        box-shadow: 0 0 6px hsl(from var(--accent) h s l / 0.7);
    }
    [data-theme='cyberpunk'] .kp-stackbar__swatch {
        border-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-stackbar__item[data-kp-stackbar-lit] {
        background-image: var(--kp-cp4-grid);
    }
    [data-theme='cyberpunk'] .kp-stackbar__note {
        clip-path: var(--kp-cp-clip-ctl);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-stackbar:not([aria-busy='true']) .kp-stackbar__bar {
            animation: kp-cp4-tear calc(6 * var(--kp-cp4-tick)) steps(1, end) backwards;
        }
    }

    /* ── Bullet rows: the figure is a read-out; a tone locks the figure as a target in its ink ── */
    [data-theme='cyberpunk'] .kp-bullets__figure {
        font-family: var(--kp-mono);
        font-size: 0.8125rem;
        letter-spacing: 0.08em;
        border-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure,
    [data-theme='cyberpunk'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        padding: 0.125em 0.625em;
        background: var(--kp-cp4-lock);
    }
    [data-theme='cyberpunk'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        --kp-cp4-tone: var(--destructive);
        color: var(--destructive);
    }
    [data-theme='cyberpunk'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure {
        --kp-cp4-tone: var(--warning-foreground);
        color: var(--warning-foreground);
    }
    [data-theme='cyberpunk'] .kp-bullets__detail {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.06em;
    }
    [data-theme='cyberpunk'] .kp-bullets__row:has(.kp-bullets__link:is(:hover, :focus-visible)) {
        background-image: var(--kp-cp4-grid);
    }
    [data-theme='cyberpunk'] .kp-bullets__note {
        clip-path: var(--kp-cp-clip-ctl);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-bullets:not([aria-busy='true']) .kp-bullets__row {
            animation: kp-cp4-tear calc(6 * var(--kp-cp4-tick)) steps(1, end) backwards;
        }
        [data-theme='cyberpunk'] .kp-bullets:not([aria-busy='true']) .kp-bullets__row:nth-child(2) {
            animation-delay: var(--kp-cp4-tick);
        }
        [data-theme='cyberpunk'] .kp-bullets:not([aria-busy='true']) .kp-bullets__row:nth-child(3) {
            animation-delay: calc(2 * var(--kp-cp4-tick));
        }
        [data-theme='cyberpunk'] .kp-bullets:not([aria-busy='true']) .kp-bullets__row:nth-child(n + 4) {
            animation-delay: calc(3 * var(--kp-cp4-tick));
        }
    }

    /* ── Key-value grid and form rows: the key is a cyan prefixed label, the failed row is locked as a target ── */
    [data-theme='cyberpunk'] .kp-kv__row > dt,
    [data-theme='cyberpunk'] .kp-formrow__label {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--accent);
    }
    [data-theme='cyberpunk'] .kp-kv__row > dt::before {
        content: '// ';
        opacity: 0.7;
    }
    [data-theme='cyberpunk'] .kp-formrow__label > small {
        text-transform: none;
        letter-spacing: 0.04em;
        color: var(--muted-foreground);
    }
    [data-theme='cyberpunk'] .kp-kv__row[data-kp-state='error'],
    [data-theme='cyberpunk'] .kp-formrow[data-kp-state='error'] {
        --kp-cp4-tone: var(--destructive);
        background: var(--kp-cp4-lock);
    }
    [data-theme='cyberpunk'] .kp-kv__row[data-kp-state='error']::before,
    [data-theme='cyberpunk'] .kp-formrow[data-kp-state='error']::before {
        display: none;
    }
    [data-theme='cyberpunk'] .kp-kv__row[data-kp-changed] > dt::after {
        color: var(--primary);
    }
    [data-theme='cyberpunk'] .kp-formrows--lines > .kp-formrow,
    [data-theme='cyberpunk'] .kp-kv--lines > .kp-kv__row {
        border-image: repeating-linear-gradient(90deg, var(--border-strong) 0 6px, transparent 6px 10px) 1;
    }

    /* ── Code block: a holo plate, its title a cyan prefixed label, the gutter the machine's mono ── */
    [data-theme='cyberpunk'] .kp-code {
        border-radius: 0;
        clip-path: var(--kp-cp-clip-plate);
        background-image: var(--kp-cp4-scan);
    }
    [data-theme='cyberpunk'] .kp-code__title,
    [data-theme='cyberpunk'] .kp-code__meta {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--accent);
    }
    [data-theme='cyberpunk'] .kp-code__title::before {
        content: '/// ';
        opacity: 0.7;
    }
    [data-theme='cyberpunk'] .kp-code__head {
        border-block-end: 1px dashed var(--border-strong);
    }

    /* ── Page header line ── */
    [data-theme='cyberpunk'] .kp-page-header__meta {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--accent);
    }

    /* ── A number that ticks: two neon copies stutter home, 6, 4, 2, 1 px, in four ticks of 120 ms; the figure stays
       sharp on top and never moves ── */
    [data-theme='cyberpunk'] [data-kp-tick] {
        font-family: var(--theme-font-display);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] [data-kp-tick][data-kp-tick-state='running'] {
            animation: kp-cp4-stutter calc(8 * var(--kp-cp4-tick)) steps(1, end);
        }
    }
    @keyframes kp-cp4-stutter {
        0% {
            text-shadow:
                6px -6px 0 var(--primary),
                6px 6px 0 var(--accent);
        }
        25% {
            text-shadow:
                4px -4px 0 var(--primary),
                4px 4px 0 var(--accent);
        }
        50% {
            text-shadow:
                2px -2px 0 var(--primary),
                2px 2px 0 var(--accent);
        }
        75% {
            text-shadow:
                1px -1px 0 var(--primary),
                1px 1px 0 var(--accent);
        }
        100% {
            text-shadow: none;
        }
    }

    /* The tear: a part is displaced sideways and jitters home, each pose held one tick, each offset smaller than the
       last and on the other side. */
    @keyframes kp-cp4-tear {
        0% {
            translate: -12px 0;
        }
        16.667% {
            translate: 8px 0;
        }
        33.333% {
            translate: -5px 0;
        }
        50% {
            translate: 3px 0;
        }
        66.667% {
            translate: -1px 0;
        }
        83.333%,
        100% {
            translate: 0 0;
        }
    }
    /* A line of text is decoded start to end in eight held steps. */
    @keyframes kp-cp4-decode {
        from {
            clip-path: inset(0 100% 0 0);
        }
        to {
            clip-path: inset(0);
        }
    }
}
/* ── end the kpadopt4 data pieces ── */

/* ── The kpadopt4 rows, records and flows in cyberpunk's own grammar [kpadopt4] ──
   A row lights its circuit when pointed at (G8) and is torn in a tick after the row before it (G3, G12); a failed or
   warned part is locked as a target in the tone's ink (G13); a card standing on the board is cut at its dossier corner
   (G6, G7); the chosen card, the current step are held by the reticle in cyan (G16); a group's rule is the tripwire dashes
   (G16); the drawings for an empty state are the system looking at a holo card (G10, G16). */
@layer kp.signature {
    /* ── Rows with a lead ── */
    [data-theme='cyberpunk'] .kp-action-list--lead {
        --kp-action-list-bar: 3px;
        --kp-action-list-next-wash: 0%;
    }
    [data-theme='cyberpunk'] .kp-action-list--lead > li:is(:hover, :focus-within) {
        background-image: var(--kp-cp4-grid);
    }
    [data-theme='cyberpunk'] .kp-action-list--lead > li[data-kp-state='failed'] {
        --kp-cp4-tone: var(--destructive);
        background-image: var(--kp-cp4-lock);
    }
    [data-theme='cyberpunk'] .kp-action-list--lead > li[data-kp-state='warn'] {
        --kp-cp4-tone: var(--warning-foreground);
        background-image: var(--kp-cp4-lock);
    }
    [data-theme='cyberpunk'] .kp-action-list--lead > li[data-kp-state='next'] > .kp-action-list__lead {
        color: var(--accent);
    }
    [data-theme='cyberpunk'] .kp-action-list__when,
    [data-theme='cyberpunk'] .kp-action-list__meta {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.08em;
    }
    [data-theme='cyberpunk'] .kp-action-list__payload {
        border-radius: 0;
        clip-path: var(--kp-cp-clip-ctl);
        font-family: var(--kp-mono);
    }
    [data-theme='cyberpunk'] .kp-action-list > li.kp-action-list__group > :is(h2, h3, h4, h5, h6) {
        font-family: var(--kp-mono);
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--accent);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-action-list--lead > li {
            animation: kp-cp4-tear calc(6 * var(--kp-cp4-tick)) steps(1, end) backwards;
        }
        [data-theme='cyberpunk'] .kp-action-list--lead > li:nth-child(2) {
            animation-delay: var(--kp-cp4-tick);
        }
        [data-theme='cyberpunk'] .kp-action-list--lead > li:nth-child(3) {
            animation-delay: calc(2 * var(--kp-cp4-tick));
        }
        [data-theme='cyberpunk'] .kp-action-list--lead > li:nth-child(4) {
            animation-delay: calc(3 * var(--kp-cp4-tick));
        }
        [data-theme='cyberpunk'] .kp-action-list--lead > li:nth-child(n + 5) {
            animation-delay: calc(4 * var(--kp-cp4-tick));
        }
    }

    /* ── Status rows: the fix is a cyan read-out under the title; a warn row is locked as a target ── */
    [data-theme='cyberpunk'] .kp-statusrow[data-state='warn'] {
        --kp-cp4-tone: var(--warning-foreground);
        --kp-statusrow-state-edge: hsl(from var(--warning-foreground) h s l / 0.5);
        --kp-statusrow-radius: 0;
        clip-path: var(--kp-cp-clip-ctl);
        background-image: var(--kp-cp4-lock);
    }
    [data-theme='cyberpunk'] .kp-statusrow__fix {
        font-family: var(--kp-mono);
        font-size: 0.8125rem;
        letter-spacing: 0.04em;
    }
    [data-theme='cyberpunk'] .kp-statusrow__fix::before {
        content: '> ';
        color: var(--primary);
    }

    /* ── Choices as tiles: a notched slot; pointing lights its circuit, checked it is the holo card (the rim, the glow),
       a press lights the circuit full ── */
    [data-theme='cyberpunk'] .kp-fieldset[data-kp-layout='tiles'] {
        --kp-field-tile-radius: 0;
        --kp-field-tile-ground-checked: color-mix(in oklab, var(--primary) 9%, var(--card));
    }
    [data-theme='cyberpunk'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
        clip-path: var(--kp-cp-clip-ctl);
        background-image: none;
    }
    [data-theme='cyberpunk'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:hover:not(:has(> .kp-field__check:disabled)) {
        background-image: var(--kp-cp4-grid);
        border-color: var(--primary);
    }
    [data-theme='cyberpunk'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:active:not(:has(> .kp-field__check:disabled)) {
        background-image: var(--kp-cp4-grid-press);
    }
    [data-theme='cyberpunk'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:checked) {
        box-shadow:
            inset 0 0 0 1px var(--primary),
            inset 0 0 10px hsl(from var(--primary) h s l / 0.35);
        background-image: var(--kp-cp4-scan);
    }
    [data-theme='cyberpunk'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:focus-visible) {
        clip-path: none;
        outline-offset: -2px;
    }
    [data-theme='cyberpunk'] .kp-field__option-hint {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.04em;
    }

    /* ── A card in four data states ── */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-card[data-kp-state='ready'] > .kp-card__stage > .kp-card__data {
            animation: kp-cp4-tear calc(6 * var(--kp-cp4-tick)) steps(1, end) backwards;
        }
    }

    /* ── Drawings for an empty state: the HUD. The strokes are torn in sideways and jitter home in six held ticks; the
       reduced pose is the drawing standing locked. ── */
    [data-theme='cyberpunk'] .kp-art {
        display: block;
    }
    [data-theme='cyberpunk'] .kp-art > g[data-kp-art-set='hud'] {
        display: inline;
    }
    [data-theme='cyberpunk'] .kp-art path {
        stroke-linecap: square;
    }
    [data-theme='cyberpunk'] .kp-art__rule {
        filter: drop-shadow(0 0 3px hsl(from var(--primary) h s l / 0.6));
    }
    [data-theme='cyberpunk'] .kp-art__red {
        filter: drop-shadow(0 0 3px hsl(from var(--destructive) h s l / 0.6));
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-art {
            animation: kp-cp4-tear calc(6 * var(--kp-cp4-tick)) steps(1, end) backwards;
        }
    }

    /* ── The pipeline: a lane is a plate cut at its dossier corner, its head a prefixed mono label; a card is cut at its
       end corner and lights its circuit; the chosen card is held by the reticle ── */
    [data-theme='cyberpunk'] .kp-pipeline__lane {
        border-radius: 0;
        clip-path: var(--kp-cp-clip-plate);
        background-image: var(--kp-cp4-scan);
    }
    [data-theme='cyberpunk'] .kp-pipeline__head {
        border-radius: 0;
        clip-path: var(--kp-cp-clip-ctl);
    }
    [data-theme='cyberpunk'] .kp-pipeline__name {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='cyberpunk'] .kp-pipeline__name::before {
        content: '/// ';
        opacity: 0.7;
    }
    [data-theme='cyberpunk'] .kp-pipeline__count {
        font-family: var(--theme-font-display);
    }
    [data-theme='cyberpunk'] .kp-pipeline__share,
    [data-theme='cyberpunk'] .kp-pipeline__sub,
    [data-theme='cyberpunk'] .kp-pipeline__meta {
        font-family: var(--kp-mono);
        letter-spacing: 0.06em;
    }
    [data-theme='cyberpunk'] .kp-pipeline__card {
        border-radius: 0;
        clip-path: var(--kp-cp-clip-ctl);
    }
    [data-theme='cyberpunk'] .kp-pipeline__card:hover {
        background-image: var(--kp-cp4-grid);
    }
    [data-theme='cyberpunk'] .kp-pipeline__card[aria-current='true'] {
        --kp-cp4-tone: var(--accent);
        outline: 0;
        border-color: var(--border);
        background-image: var(--kp-cp4-lock);
    }
    [data-theme='cyberpunk'] .kp-pipeline__mark {
        border-radius: 0;
    }
