            inset 0 0 10px hsl(from var(--primary) h s l / 0.35);
    }
    [data-theme='cyberpunk'] .kp-secret {
        --kp-secret-drain: var(--primary);
    }
    [data-theme='cyberpunk'] .kp-secret__drain {
        background: var(--kp-cp4-trip);
        box-shadow: none;
    }
    [data-theme='cyberpunk'] .kp-secret__line {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        color: var(--accent);
    }
    [data-theme='cyberpunk'] .kp-secret[data-kp-secret-state='error'] .kp-secret__value {
        --kp-cp4-tone: var(--destructive);
        background-image: var(--kp-cp4-lock);
    }
    [data-theme='cyberpunk'] .kp-secret[data-kp-secret-state='error'] .kp-secret__words {
        color: var(--destructive);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__text {
            display: inline-block;
            animation: kp-cp4-decode calc(8 * var(--kp-cp4-tick)) steps(8, end) backwards;
        }
    }

    /* ── Dialog in sections, confirmation, typed confirmation ── */
    [data-theme='cyberpunk'] .kp-dialog__heading {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--accent);
