    /* ── Checklist: a row lights its circuit; a ticked item is dimmed and struck; the head is a prefixed label ── */
    [data-theme='cyberpunk'] .kp-checklist__row {
        border-radius: 0;
    }
    [data-theme='cyberpunk'] .kp-checklist__row:hover {
