    /* ── Cook mode ── */
    [data-theme='cyberpunk'] .kp-focus-steps__count,
    [data-theme='cyberpunk'] .kp-focus-steps__amount,
    [data-theme='cyberpunk'] .kp-focus-steps__needs-title {
