        letter-spacing: 0.1em;
    }
    [data-theme='cyberpunk'] .kp-focus-steps__needs-title {
        font-size: 0.75rem;
        text-transform: uppercase;
        color: var(--accent);
    }
    [data-theme='cyberpunk'] .kp-focus-steps__needs {
        border-radius: 0;
