    @media (prefers-reduced-motion: no-preference) {
        [data-theme='cyberpunk'] .kp-focus-steps__step {
            animation: kp-cp4-tear calc(6 * var(--kp-cp4-tick)) steps(1, end) backwards;
        }
    }

    /* ── Wheel: it turns in held ticks (a pose every 100 ms or so), never an ease; the rim is the yellow, the pointer the
       reticle's tick in cyan ── */
    [data-theme='cyberpunk'] .kp-wheel {
        --kp-wheel-ease: steps(40, end);
        --kp-wheel-pointer: var(--accent);
        --kp-wheel-tint: 24%;
    }
    /* The hub carries none of the button's plates, frames or labels on its pseudo-elements: a round disc stays round
       [cook-1017; Kenny 2026-10-17: no square frame round the spin hub in any theme]. */
    [data-theme='cyberpunk'] .kp-wheel__spin.kp-button::before,
    [data-theme='cyberpunk'] .kp-wheel__spin.kp-button::after {
        content: none !important;
    }
    /* No stripes of its own either: the button's two 3 px side bars and its cut-corner wedge (background layers) would
       leave a rectangular nub on the disc's rim; the yellow stays as the colour. */
    [data-theme='cyberpunk'] .kp-wheel__spin.kp-button,
    [data-theme='cyberpunk'] .kp-wheel__spin.kp-button:is(:hover, :active, :focus-visible) {
        --kp-wheel-hub-shadow: none;
        background-image: none !important;
    }
    [data-theme='cyberpunk'] .kp-wheel__rim {
