    [data-theme='cyberpunk'] .kp-countdown[data-kp-countdown-state='ended'] .kp-countdown__status {
        color: var(--destructive);
    }

    /* ── Range picker ── */
    [data-theme='cyberpunk'] .kp-range__label,
    [data-theme='cyberpunk'] .kp-range__bound,
    [data-theme='cyberpunk'] .kp-range__title {
        font-family: var(--kp-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
