        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }

    [data-theme='synthwave'] .kp-theme-menu__status,
    [data-theme='synthwave'] .kp-palette__status,
    [data-theme='synthwave'] .kp-combobox__status {
        font-family: var(--kp-osd);
        letter-spacing: 0.08em;
    }

    /* ── The roots the rules above reach only by their parts ──────────── */

    /* A field, a form, a fieldset of data: the OSD rhythm between rows. */
    [data-theme='synthwave'] .kp-field,
    [data-theme='synthwave'] .kp-form {
        gap: calc(var(--kp-space-xs) * 1.4);
    }

    [data-theme='synthwave'] .kp-form {
        gap: calc(var(--kp-space-lg) * 1.1);
    }

    /* The data pickers and panels: a hairline frame, square. */
    [data-theme='synthwave'] .kp-combobox,
    [data-theme='synthwave'] .kp-datepicker,
    [data-theme='synthwave'] .kp-colorpicker,
    [data-theme='synthwave'] .kp-shortcuts {
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-datatable {
        border: 1px solid var(--kp-hairline);
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-diff {
        background: var(--sidebar-background);
        border: 1px solid var(--kp-hairline);
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-split {
        gap: 0;
    }

    /* ── The scrollbar joins the theme ────────────────────────────────── */

    [data-theme='synthwave'] {
        scrollbar-color: var(--primary) var(--sidebar-background);
    }

    /* ── The demo's own pieces [S46] ──────────────────────────────────── */

    /* The vertical OSD label in the margin: ● REC · SP 0:00:00. */
    [data-theme='synthwave'] .kp-side-note {
        position: absolute;
        right: 1rem;
        top: 3rem;
        writing-mode: vertical-rl;
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.3em;
        color: var(--kp-pink-text);
        z-index: 2;
    }

    /* Laurels: uppercase, each item between two striped bars — the sun's
       stripes, three bands each. */
    [data-theme='synthwave'] .kp-laurels {
        gap: 1.5rem 2.5rem;
        text-transform: uppercase;
        letter-spacing: 0.1em;
        font-size: 0.8rem;
        color: var(--muted-foreground);
    }

    [data-theme='synthwave'] .kp-laurels li {
        position: relative;
        padding-inline: 0.9rem;
        background:
            repeating-linear-gradient(0deg, var(--primary) 0 3px, transparent 3px 6px) left / 4px 100% no-repeat,
            repeating-linear-gradient(0deg, var(--primary) 0 3px, transparent 3px 6px) right / 4px 100% no-repeat;
    }

    [data-theme='synthwave'] .kp-laurels b {
        font-weight: 700;
        font-size: 0.95rem;
        letter-spacing: 0.06em;
        color: var(--kp-core);
        text-shadow: var(--kp-tube-cyan);
    }

    [data-theme='synthwave'] .kp-lede {
        max-width: 34rem;
        font-size: 1.15rem;
        font-weight: 500;
    }

    /* The platforms line: the OSD face, ▶ before every name. */
    [data-theme='synthwave'] .kp-platforms {
        margin-top: 2.4rem;
        gap: 0.4rem 1.6rem;
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    [data-theme='synthwave'] .kp-platforms span::before {
        content: '▶ ';
        color: var(--accent);
    }

    /* The spec sheet: a tape card with the stripe on top. */
    [data-theme='synthwave'] .kp-spec {
        background: var(--card);
        color: var(--foreground);
        padding: 1.4rem 1.5rem 1.6rem;
        border: 1px solid var(--kp-hairline);
        border-top: 4px solid transparent;
        border-image: var(--kp-stripe) 1;
        font-family: var(--kp-mono);
        font-size: 0.8rem;
        line-height: 1.7;
        box-shadow: 0 0 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    [data-theme='synthwave'] .kp-spec dt {
        color: var(--accent);
        letter-spacing: 0.1em;
    }

    /* The log wears what this register already decided for its other data
 * surface, `.kp-spec` — the same ground, the same edge, the same face
 * [gap-14]. A new component that invents a look of its own is a
 * twenty-third decision nobody made. */
    [data-theme='synthwave'] .kp-log {
        background: var(--card);
        color: var(--foreground);
        border: 1px solid var(--kp-hairline);
        font-family: var(--kp-mono);
        box-shadow: 0 0 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    [data-theme='synthwave'] .kp-log__level {
        --kp-log-level-ink: var(--accent);
        letter-spacing: 0.1em;
    }

    [data-theme='synthwave'] .kp-spec__swatch {
        border: 1px solid hsl(from var(--kp-core) h s l / 0.25);
    }

    [data-theme='synthwave'] .kp-spec__font {
        font-family: var(--theme-font-display);
    }

    /* ── The arrival [S45, SW2]: the boot line, then the tube switches on ── */

    /* The overlay js/effects.js builds when the theme answers the arrival
       hook with `boot`: a diegetic line counting up in the OSD face, a
       Skip button, and the CRT switching the overlay off in 550 ms. Once
       per session; never under reduced motion (the module does not build
       it). */
    [data-theme='synthwave'] .kp-boot {
        position: fixed;
        inset: 0;
        z-index: var(--kp-z-boot, 100);
        background: var(--background);
        display: grid;
        place-items: center;
        font-family: var(--kp-osd);
        font-size: clamp(1.1rem, 2.4vw, 1.6rem);
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--accent);
        text-shadow: var(--kp-tube-cyan);
        transform-origin: center;
    }

    [data-theme='synthwave'] .kp-boot__line {
        margin: 0;
        font: inherit;
        white-space: pre-wrap;
        min-width: 20ch;
    }

    [data-theme='synthwave'] .kp-boot__skip {
        position: absolute;
        right: 1.5rem;
        bottom: 1.5rem;
        font: inherit;
        letter-spacing: 0.2em;
        color: var(--kp-pink-text);
        background: none;
        border: 2px solid var(--primary);
        border-radius: var(--radius);
        padding: 0.3rem 0.9rem;
        cursor: pointer;
    }

    [data-theme='synthwave'] .kp-boot.is-off {
        pointer-events: none;
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. The
       durations are literal because check-motion.mjs computes DI5's rate
       from them; the matching --kp-* knobs are what js/effects.js reads. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] [data-kp-reveal='headline'].is-tracking::before {
            animation: kp-tracking 700ms steps(1, end) 1;
        }

        [data-theme='synthwave'] [data-kp-reveal='headline'].is-shine::after {
            animation: kp-shine 1400ms var(--fx-ease) 1;
        }

        [data-theme='synthwave'] [data-kp-reveal='rule']::after {
            transition: transform var(--kp-rule-draw) var(--fx-ease);
        }

        [data-theme='synthwave'][data-kp-effects] mark.is-cleared {
            animation: kp-tube-on 1100ms steps(1, end) 1;
        }

        [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform var(--kp-wipe) var(--fx-ease);
        }

        [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='synthwave'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        [data-theme='synthwave'] .kp-nav__links {
            animation: kp-bar-in 520ms var(--fx-ease) 80ms both;
        }

        [data-theme='synthwave'] .kp-nav__link::after {
            transition: transform var(--fx-duration) var(--fx-ease);
        }

        /* Transform only. No box-shadow transition: the focus ring is a
           shadow layer and must appear at once (AR30). No colour transition
           either: a theme applied after first paint transitions every
           colour, and CI's chromium read a nav link halfway — `oklab(…)`,
           a colour the theme does not own (KT8; flake named, rule 8a,
           run 34175026456). */
        [data-theme='synthwave'] .kp-nav__link,
        [data-theme='synthwave'] .kp-nav__link--cta,
        [data-theme='synthwave'] .kp-button {
            transition: transform var(--fx-duration) var(--fx-ease);
        }

        [data-theme='synthwave'] .kp-button:hover::before {
            animation: kp-sun-cut 360ms steps(3, end) 1;
        }

        [data-theme='synthwave'] .kp-button:hover::after {
            animation: kp-sun-cut 360ms steps(3, end) 1 60ms;
        }

        [data-theme='synthwave'] [data-kp-surface='hero']::after {
            animation: kp-floor-drift 6000ms linear infinite;
        }

        [data-theme='synthwave'] .kp-boot.is-off {
            animation: kp-crt-off 550ms var(--fx-ease) 1 forwards;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js). */
    /* The headline's reveal, its first part: the tube strikes on [G16, motifs =
       meaning: VHS is a still texture and a voice, never a tracking glitch,
       which is cyberpunk's]. The bands that jumped sideways with an RGB fringe
       are gone; the copy of the text in the near-white core lights, dips once
       and goes out in hard steps, and the chrome shine follows. The name and
       the 700 ms stay: js/effects.js waits that long before the shine. */
    @keyframes kp-tracking {
        0% {
            opacity: 0;
        }

        20% {
            opacity: 1;
        }

        34% {
            opacity: 0.35;
        }

        48%,
        72% {
            opacity: 1;
        }

        100% {
            opacity: 0;
        }
    }

    @keyframes kp-shine {
        from {
            background-position: 100% 100%;
        }

        to {
            background-position: 0% 0%;
        }
    }

    @keyframes kp-tube-on {
        0% {
            color: hsl(from var(--foreground) h s l / 0.4);
            text-shadow: none;
        }

        20% {
            color: var(--kp-core);
            text-shadow: var(--kp-tube-pink);
        }

        34% {
            color: hsl(from var(--foreground) h s l / 0.5);
            text-shadow: none;
        }

        50%,
        100% {
            color: var(--kp-core);
            text-shadow: var(--kp-tube-pink);
        }
    }

    @keyframes kp-sun-cut {
        0% {
            opacity: 1;
            transform: translateX(-10%);
        }

        66% {
            opacity: 1;
            transform: translateX(10%);
        }

        100% {
            opacity: 0;
            transform: none;
        }
    }

    @keyframes kp-bar-in {
        0% {
            transform: translateY(10px);
            opacity: 0;
        }

        100% {
            transform: none;
            opacity: 1;
        }
    }

    @keyframes kp-floor-drift {
        to {
            background-position: 0 6vw;
        }
    }

    @keyframes kp-crt-off {
        0% {
            transform: scaleY(1);
            filter: brightness(1);
            opacity: 1;
        }

        60% {
            transform: scaleY(0.006);
            filter: brightness(8);
        }

        100% {
            transform: scaleY(0.006) scaleX(0);
            filter: brightness(50);
            opacity: 0;
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — a neon rule under the band and a glow around the text. */
    [data-theme='synthwave'] .kp-marquee {
        background: linear-gradient(180deg, color-mix(in srgb, var(--primary) 12%, transparent), transparent);
        border-block-end: 2px solid var(--primary);
        text-shadow: 0 0 6px color-mix(in srgb, var(--primary) 60%, transparent);
        --kp-marquee: 26000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='synthwave'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='synthwave'] .kp-nav__menu--wide .kp-nav__menu-heading {
        color: var(--primary);
        text-shadow: 0 0 6px color-mix(in srgb, var(--primary) 60%, transparent);
        border-block-end: 0;
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       The bar lights its current item from underneath. A column has no
       underneath, so the glow moves to the leading edge and becomes the
       tube running down the side of the active row. */
    [data-theme='synthwave'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
        border-inline-end: 1px solid var(--border-strong);
    }

    [data-theme='synthwave'] .kp-sidenav__title {
        letter-spacing: 0.2em;
        text-transform: uppercase;
        color: var(--primary);
    }

    [data-theme='synthwave'] .kp-sidenav__link,
    [data-theme='synthwave'] .kp-sidenav__category-toggle {
        padding-inline: 1.1rem;
        font-weight: 600;
        border-radius: 0;
    }

    [data-theme='synthwave'] .kp-sidenav__link[aria-current='page'] {
        color: var(--kp-core);
        background: none;
        box-shadow:
            inset 0.2rem 0 0 var(--primary),
            inset 0 0 25px hsl(from var(--primary) h s l / 0.18);
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       Both get the tube: a ring of the primary that glows rather than
       merely bounding. */
    [data-theme='synthwave'] .kp-to-top {
        box-shadow: 0 0 12px hsl(from var(--primary) h s l / 0.5);
    }

    [data-theme='synthwave'] .kp-media {
        border: 1px solid var(--primary);
        box-shadow: 0 0 18px hsl(from var(--primary) h s l / 0.28);
    }

    [data-theme='synthwave'] .kp-media-figure > figcaption {
        letter-spacing: 0.14em;
        text-transform: uppercase;
        font-size: 0.6875rem;
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='synthwave'] .kp-media-figure {
        color: var(--primary);
        text-align: start;
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       A layer beats a state: this register's hover background sits in
       kp.register, later than the kp.components rule that says what the
       button looks like while it is held down, so pressing it changed
       nothing. The base layer's own values, put back token for token. */

    [data-theme='synthwave'] .kp-button--primary:active:not(:disabled) {
        background: var(--primary-active);
        border-color: var(--primary-active);
    }

    /* ── Read-only fields [gap-11] ────────────────────────────────────── */

    /* A read-only field is a value on a record, not a box to type in. This
       register sets the field's border and ground in kp.register, which
       beats the read-only look in kp.components, so read-only painted like
       an editable field. The state is answered here, on top of the rest
       look, which stays as it was. */
    [data-theme='synthwave'] .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): widely spaced capitals with room under them
       for the gradient stripe that runs out beneath them, and the core ink
       with a low inner glow, when pointed at. The link's typeface, case,
       spacing, shape and pointer answer are restated here, because the
       trigger is a button beside the list rather than a link in it. The
       underline a plain link carries is not: it says "this is a link", and
       the trigger is not one. */
    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger {
        position: relative;
        padding-inline: 1.1rem;
        font-weight: 600;
        letter-spacing: 0.18em;
        text-transform: uppercase;
        border: 0;
        border-radius: 0;
        background: none;
        color: var(--foreground);
    }

    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        color: var(--kp-core);
        background: none;
        box-shadow: inset 0 -5px 25px hsl(from var(--primary) h s l / 0.15);
    }

    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger::after {
        content: '';
        position: absolute;
        left: 0.6rem;
        right: 0.6rem;
        bottom: 0;
        height: 4px;
        background: var(--kp-stripe);
        transform: scaleX(0);
        transform-origin: left center;
    }

    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger:hover::after,
    [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger:focus-visible::after {
        transform: scaleX(1);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-nav__search .kp-nav__search-trigger::after {
            transition: transform var(--fx-duration) var(--fx-ease);
        }
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       A neon sign in the night: a violet plate from its background, the red headline haloed in the pink of its primary, pink stripes and a pink frame. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='synthwave'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--background) h s 4% / 0.95);
        --kp-alarm-ink: hsl(from var(--destructive) h s max(l, 62));
        --kp-alarm-soft: var(--foreground);
        --kp-alarm-split: var(--primary);
        --kp-alarm-on-ink: hsl(from var(--background) h s 4%);
        --kp-alarm-glow: hsl(from var(--primary) h s l / 0.45);
        --kp-alarm-halo: hsl(from var(--primary) h s l / 0.6);
        --kp-alarm-scan: hsl(from var(--primary) h s l / 0.08);
        --kp-alarm-vignette: hsl(from var(--background) h s 2% / 0.8);
        --kp-alarm-stripe: var(--primary);
        --kp-alarm-frame: 2px solid var(--primary);
    }

    [data-theme='synthwave'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='synthwave'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    /* A submenu item's mark [Kenny, 2026-09-20]: the neon dot it marks its own rows with. */
    [data-theme='synthwave'] .kp-sidenav__submenu .kp-sidenav__link {
        --kp-sidenav-submenu-mark: '●';
    }

    /* ── The OSD names, the chrome counts [G15, type = osd; Kenny,
       2026-10-07 20:41] ─────────────────────────────────────────────────────
       Identifiers, timestamps and the data faces speak in the OSD (VT323);
       KP Tech Mono, the register's data face until now, is cyberpunk's label
       face and leaves synthwave. VT323 stands small on its em, so every
       surface that takes it from `--kp-mono` is sized by its x-height. */
    [data-theme='synthwave'] {
        --kp-mono: var(--kp-osd);
    }

    [data-theme='synthwave']
        :is(
            .kp-id,
            .kp-url,
            .kp-numeric,
            .kp-timestamp,
            .kp-masked,
            .kp-copyable,
            .kp-truncate,
            .kp-cell-break,
            .kp-cell-truncate,
            .kp-diff__line,
            .kp-diff__hunk,
            .kp-tree,
            .kp-colorpicker__value,
            .kp-spec,
            .kp-log
        ) {
        font-size-adjust: 0.5;
    }

    /* ── The VCR's symbols [G13, tone = osd; Kenny, 2026-10-07 23:00] ───────
       A warning is a pause (two tubes), a failure a stop (a square), drawn in
       the part's own ink before its figure or its label: the second channel
       that is not colour. The part's top edge turns to the tone's ink, the
       stripe and the sides that fall from it with it (the tube turns). The
       plate and its ink stay the status pair the package guarantees. ───── */
    [data-theme='synthwave'] .kp-kpi[data-kp-tone='warning'] {
        --kp-stripe-from: var(--warning-foreground);
        --kp-stripe-to: var(--warning-foreground);
    }

    [data-theme='synthwave'] .kp-kpi[data-kp-tone='destructive'] {
        --kp-stripe-from: var(--destructive);
        --kp-stripe-to: var(--destructive);
    }

    [data-theme='synthwave']
        :is(.kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value, .kp-alert--warning, .kp-alert--destructive)::before {
        content: '';
        flex: none;
        align-self: center;
        filter: drop-shadow(0 0 3px currentColor);
    }

    [data-theme='synthwave'] :is(.kp-kpi[data-kp-tone='warning'] .kp-kpi__value, .kp-alert--warning)::before {
        inline-size: 0.5em;
        block-size: 0.6em;
        background: linear-gradient(90deg, currentColor 0 34%, transparent 34% 66%, currentColor 66%);
    }

    [data-theme='synthwave'] :is(.kp-kpi[data-kp-tone='destructive'] .kp-kpi__value, .kp-alert--destructive)::before {
        inline-size: 0.5em;
        block-size: 0.5em;
        background: currentColor;
    }

    [data-theme='synthwave'] :is(.kp-alert--warning, .kp-alert--destructive)::before {
        font-size: 1.1rem;
    }

    /* The focus of a key figure or a menu entry that is a link or a toggle is
       the same two tubes as a button's; hovering turns its tube up [G17: an
       element inside a composite is the theme's own element]. */
    [data-theme='synthwave'] :is(a.kp-kpi, .kp-kpi--toggle):hover {
        border-color: transparent;
        --kp-stripe-from: var(--kp-pink-text);
        --kp-stripe-to: var(--kp-core);
    }

    [data-theme='synthwave'] :is(a.kp-kpi, .kp-kpi--toggle):hover .kp-kpi__value {
        color: var(--kp-core);
        text-shadow: var(--kp-sw-tube-up);
    }

    /* A press charges the part [G14, press = charge; Kenny, 2026-10-07 23:54],
       as it charges a button: the top edge burns near-white (the stripe and
       the sides that fall from it), the bloom gathers above it and the ground
       takes the pressed token; nothing moves. Held for as long as the press
       lasts (`:active`) and, on a toggle, for as long as it is on
       (`aria-pressed='true'`). A toggle that is on says so a second way that
       is not colour [DI2]: the VCR's play symbol before its label and the
       horizon of its floor lit near-white. The focus rails below win while the
       keyboard is on the part. */
    [data-theme='synthwave'] :is(a.kp-kpi, button.kp-kpi--toggle):active,
    [data-theme='synthwave'] button.kp-kpi--toggle[aria-pressed='true'] {
        --kp-stripe-from: var(--kp-core);
        --kp-stripe-to: var(--kp-core);
        background-color: var(--secondary-active);
        box-shadow:
            inset 0 -2px 0 0 hsl(from var(--sidebar-background) h s l / 0.7),
            0 -4px 14px 0 hsl(from var(--primary) h s l / 0.8),
            0 0 40px hsl(from var(--sidebar-background) h s l / 0.6);
    }

    [data-theme='synthwave'] button.kp-kpi--toggle[aria-pressed='true']::after {
        border-block-start-color: var(--kp-core);
        box-shadow:
            0 -2px 12px hsl(from var(--primary) h s l / 0.8),
            0 -1px 3px hsl(from var(--kp-core) h s l / 0.6);
    }

    /* The play symbol stands in the tile's own padding, out of the flow: a
       tile that is pressed keeps the label's line and every sibling's place. */
    [data-theme='synthwave'] button.kp-kpi--toggle[aria-pressed='true'] > .kp-kpi__label::before {
        content: '';
        position: absolute;
        inset-inline-start: 0.2rem;
        margin-block-start: 0.35em;
        inline-size: 0.55em;
        block-size: 0.8em;
        pointer-events: none;
        background:
            linear-gradient(to top right, var(--kp-core) 50%, transparent 50%) 0 0 / 100% 50% no-repeat,
            linear-gradient(to bottom right, var(--kp-core) 50%, transparent 50%) 0 100% / 100% 50% no-repeat;
        filter: drop-shadow(0 0 3px var(--primary));
    }

    [data-theme='synthwave'] :is(a.kp-kpi, .kp-kpi--toggle):focus-visible {
        outline: none;
        box-shadow:
            var(--kp-sw-rails-in),
            0 0 12px 0 hsl(from var(--primary) h s l / 0.6);
    }

    [data-theme='synthwave'] .kp-menu__item:is(:hover, :focus-visible) {
        color: var(--kp-core);
        text-shadow: var(--kp-sw-tube);
    }

    [data-theme='synthwave'] .kp-menu__item:focus-visible {
        outline: none;
        box-shadow: var(--kp-sw-rails-in);
    }

    /* ── Focus is two tubes on every part that takes it [G14, focus = rails;
       DI2; Kenny, 2026-10-07 23:00] ────────────────────────────────────────
       One rule for the rest of the package's focusable parts, so no part is
       left on the global ring (a contrast outline and an inner ring, which is
       the other themes'). `:focus-visible` only: a click leaves nothing
       behind. A part that sits inside a frame, a cell, a row or a scroller
       takes the rails inside it; a link, a mark or a plate takes them outside.
       Forced colours repaint an outline (below), since a box-shadow is not
       drawn there. ──────────────────────────────────────────────────────── */
    [data-theme='synthwave']
        :is(
            .kp-tab,
            .kp-pagination a,
            .kp-pagination button,
            .kp-breadcrumb a,
            .kp-accordion__summary,
            .kp-tree [role='treeitem'],
            .kp-table :is(th, td, button, a),
            .kp-combobox__input,
            .kp-combobox__list [role='option'],
            .kp-combobox button,
            .kp-calendar__day,
            .kp-datepicker__day,
            .kp-chart__source,
            .kp-chart-zoom__reset,
            .kp-chart__release,
            .kp-chart__show-all,
            .kp-chart__plot,
            .kp-kpi__chart-plot,
            .kp-kpi__link,
            .kp-wizard [data-kp-step],
            .kp-grid__tile,
            .kp-sidenav__link,
            .kp-nav__link,
            .kp-nav__menu a,
            .kp-nav__search-trigger,
            .kp-nav__toggle,
            .kp-tag__remove,
            .kp-colorpicker__swatch,
            .kp-split__separator,
            .kp-form__summary,
            .kp-theme-option,
            .kp-palette__input,
            .kp-palette [role='option'],
            .kp-theme-menu__list :is(button, [role='option']),
            .kp-datepicker button,
            .kp-table-wrap,
            .kp-sidenav__category-toggle,
            .kp-nav__disclosure,
            input[type='range'],
            .kp-field__input,
            textarea,
            select,
            summary
        ):focus-visible {
        outline: none;
        box-shadow: var(--kp-sw-rails-in);
    }

    /* A slider paints no inset shadow (its track is the browser's), so its two tubes run outside it
       (Firefox Tab audit, research/all-themes/_audit/tab-paint.mjs: 0 px changed with the inset ones).
       The attribute twice outranks the list above, whose :is() takes its most specific entry. */
    [data-theme='synthwave'] input[type='range'][type='range']:focus-visible {
        box-shadow: var(--kp-sw-rails-out);
    }

    /* The option a list marks as the one the keyboard is on (`aria-activedescendant`
       keeps the focus in the input) takes the same two tubes, while the input
       has the keyboard. */
    [data-theme='synthwave']
        :is(
            .kp-combobox:has(.kp-combobox__input:focus-visible) .kp-combobox__option.is-active,
            .kp-palette:has(.kp-palette__input:focus-visible) .kp-palette__option.is-active
        ) {
        box-shadow: var(--kp-sw-rails-in);
    }

    /* A row that takes the focus rails across its cells, its two ends closing the
       sides. */
    [data-theme='synthwave'] .kp-table tr:focus-visible > :is(th, td) {
        box-shadow:
            inset 0 var(--kp-sw-rail) 0 0 var(--kp-core),
            inset 0 calc(var(--kp-sw-rail) * 2) 0 0 var(--focus-ring-contrast),
            inset 0 calc(var(--kp-sw-rail) * -1) 0 0 var(--kp-core),
            inset 0 calc(var(--kp-sw-rail) * -2) 0 0 var(--focus-ring-contrast);
    }

    [data-theme='synthwave'] .kp-table tr:focus-visible > :first-child {
        box-shadow:
            var(--kp-sw-rails-in),
            inset 1px 0 0 0 var(--focus-ring);
    }

    [data-theme='synthwave'] .kp-table tr:focus-visible > :last-child {
        box-shadow:
            var(--kp-sw-rails-in),
            inset -1px 0 0 0 var(--focus-ring);
    }

    [data-theme='synthwave'] .kp-table tr:focus-visible {
        outline: none;
    }

    /* A link in running text and the small marks stand on their own: the rails
       sit outside them, close, and their own glow stays. */
    [data-theme='synthwave']
        :is(
            a:not(
                .kp-button,
                .kp-kpi,
                .kp-nav__link,
                .kp-nav__menu a,
                .kp-sidenav__link,
                .kp-breadcrumb a,
                .kp-pagination a,
                .kp-table a,
                .kp-menu__item
            ),
            .kp-field__check,
            .kp-switch__input,
            .kp-radio
        ):focus-visible {
        outline: none;
        box-shadow:
            var(--kp-sw-rails-out),
            0 0 12px 0 hsl(from var(--primary) h s l / 0.6);
    }

    /* Whatever else takes the keyboard (a handle, a theme swatch, a custom
       widget with a role) is a part like any other: the same two tubes inside
       it, at almost no specificity, so every rule above and any consumer's own
       wins. The network graph is left as it is (it is no theme's target). */
    :where([data-theme='synthwave'])
        :where(button, [role='button'], [role='tab'], [role='menuitem'], [role='option'], [role='gridcell'], [tabindex]):not(
            .kp-graph *
        ):focus-visible {
        outline: none;
        box-shadow: var(--kp-sw-rails-in);
    }

    @media (forced-colors: active) {
        [data-theme='synthwave'] :focus-visible {
            outline: 2px solid Highlight;
            outline-offset: 2px;
        }
    }
}

/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* synthwave's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/synthwave.css and research/signature-elements/themes/synthwave.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* The link signature is for links in running text; a link in a navigation,
       a menu, a breadcrumb (a nav) or the footer keeps its own component's look
       (scope-93: no link colour in a navigation). */
    /* A shadow or outline the signature draws on a focusable control yields to
       the theme's focus ring while the control has focus (DI2). */
    [data-theme='synthwave'] .kp-progressbar {
        /* The bars fill as they were [loading = combo, Kenny, 2026-10-07 23:54]:
           four beats on the sunrise curve, the head with the fill, the bar
           following the page tube a beat behind (below). */
        --kp-progressbar-duration: calc(4 * var(--kp-sw-beat));
        --kp-progressbar-ease: var(--kp-sw-sun);
        --kp-progressbar-height: calc(1.125rem * var(--kp-progressbar-scale, 1));
        --kp-sw-road: calc(2.25rem * var(--kp-progressbar-scale, 1));
        --kp-sw-void: var(--sidebar-background);
        --kp-sw-core: var(--kp-core, hsl(from var(--foreground) h 20% 98%));
    }

    [data-theme='synthwave'] .kp-progressbar__track {
        border-radius: calc(var(--radius) * var(--kp-progressbar-scale, 1));
        background: var(--kp-sw-void);
    }

    [data-theme='synthwave'] .kp-progressbar__track::before {
        content: '';
        position: absolute;
        inset: 0;
        background:
            linear-gradient(hsl(from var(--border-strong) h s l / 0.5) 0 0) 0 50% / 100% 1px no-repeat,
            repeating-linear-gradient(
                90deg,
                hsl(from var(--border-strong) h s l / 0.38) 0 1px,
                transparent 1px calc(1.5rem * var(--kp-progressbar-scale, 1))
            );
    }

    [data-theme='synthwave'] .kp-progressbar__track::after {
        content: '';
        position: absolute;
        inset: 0;
        z-index: 2;
        border-radius: inherit;
        box-shadow: inset 0 0 0 1px var(--border-strong);
        pointer-events: none;
    }

    [data-theme='synthwave'] .kp-progressbar__fill {
        background:
            linear-gradient(
                to bottom,
                transparent 0 48%,
                var(--kp-sw-void) 48% 54%,
                transparent 54% 64%,
                var(--kp-sw-void) 64% 73%,
                transparent 73% 81%,
                var(--kp-sw-void) 81% 92%,
                transparent 92%
            ),
            linear-gradient(
                90deg,
                var(--kp-sun-bottom, hsl(from var(--primary) calc(h - 34) s l)),
                var(--primary) 45%,
                var(--kp-sun-top, var(--warning-foreground))
            );
        transition-timing-function: var(--kp-sw-sun);
    }

    [data-theme='synthwave'] .kp-progressbar__head {
        inset-inline-start: -2px;
        inline-size: 2px;
        z-index: 1;
        background: var(--kp-sw-core);
        box-shadow:
            0 0 3px hsl(from var(--primary) h s l / 0.9),
            0 0 8px hsl(from var(--primary) h s l / 0.7),
            0 0 16px hsl(from var(--primary) h s l / 0.45);
        transition-timing-function: var(--kp-sw-sun);
    }

    [data-theme='synthwave'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inset-inline-end: 0;
        inline-size: auto;
        overflow: hidden;
        clip-path: none;
        animation: none;
        background: none;
    }

    [data-theme='synthwave'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: calc(-1 * var(--kp-sw-road));
        inline-size: calc(100% + 2 * var(--kp-sw-road));
        background: linear-gradient(
                90deg,
