}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — synthwave: a laser horizon. The current tab lights a neon tube along the top edge and its label glows; a press dips the tube (G8, G14); labels are spaced capitals; a count is a neon ring (G13). */
    [data-theme='synthwave'] .kp-tabbar {
        background: var(--background);
        border-block-start-color: hsl(from var(--foreground) h s l / 0.12);
    }

    [data-theme='synthwave'] .kp-tabbar__tab {
        border-radius: 0;
        letter-spacing: 0.14em;
