        border-radius: 2px;
        box-shadow:
            0 0 6px var(--primary),
            0 0 16px hsl(from var(--primary) h s l / 0.6);
    }

    [data-theme='synthwave'] .kp-tabbar__tab[aria-current]:not([aria-current='false']) .kp-tabbar__label {
