/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Synthwave's own (themes/synthwave/CHARACTER.md): a tile is the tape, square, with the pink to cyan stripe along its
   top and the corners falling in the stripe's colours, never glowing on its rim (G6, G7); pointing turns the tube up in
   one step, the stripe and the title's tube (G8); a press charges it, the top edge burning near-white, and nothing
   moves (the register's press); a failure is the VCR's stop before the title, in the red (the register's tone); waiting
   is the marquee, bulbs
   chasing one in four, start to end, four hard steps a 900 ms loop (G10); what runs is the road, the lane dashes
   racing (G11, G16); the OSD's mono capitals name, the chrome counts (G15). */
@layer kp.signature {
    [data-theme='synthwave'] .kp-actions {
        --kp-actions-gap: 0.75rem;
    }
    [data-theme='synthwave'] .kp-action {
        --kp-action-radius: 0;
        --kp-action-edge: transparent;
        --kp-action-edge-hover: transparent;
        --kp-action-press: 0 0;
        --kp-action-ground-active: var(--secondary-active, var(--card));
        --kp-action-title-font: var(--theme-font-display);
        --kp-action-title-case: uppercase;
        --kp-action-title-tracking: 0.06em;
        --kp-action-title-size: 0.9375rem;
        --kp-stripe: linear-gradient(to right, var(--kp-stripe-from), var(--kp-stripe-to));
        --kp-sw-fall-l: linear-gradient(to bottom, var(--kp-stripe-from), hsl(from var(--kp-stripe-from) h s l / 0.55) 50%, transparent 100%);
        --kp-sw-fall-r: linear-gradient(to bottom, var(--kp-stripe-to), hsl(from var(--kp-stripe-to) h s l / 0.55) 50%, transparent 100%);
        --kp-sw-tile-ground: var(--card);
        border: 1px solid transparent;
        border-block-start: calc(var(--kp-sw-side) + 1px) solid transparent;
        background:
            var(--kp-stripe) 0 0 / 100% var(--kp-sw-side) no-repeat,
            linear-gradient(hsl(from var(--kp-core) h s l / 0.22) 0 0) 0 var(--kp-sw-side) / 100% 1px no-repeat,
            var(--kp-sw-fall-l) 0 0 / 1px 100% no-repeat,
            var(--kp-sw-fall-r) 100% 0 / 1px 100% no-repeat,
            var(--kp-sw-tile-ground);
        background-origin: border-box;
        box-shadow: inset 0 -2px 0 0 hsl(from var(--sidebar-background) h s l / 0.7);
    }
    [data-theme='synthwave'] .kp-action__title {
        color: var(--kp-core);
    }
    [data-theme='synthwave'] .kp-action__meta {
        color: var(--accent);
        font-family: var(--kp-mono);
        font-size-adjust: 0.5;
    }
    /* Pointing turns the tube up in one step, as on a key figure that is a link: the stripe runs pink to the core and
       the title takes the tube. */
    [data-theme='synthwave'] .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        --kp-stripe-from: var(--kp-pink-text);
        --kp-stripe-to: var(--kp-core);
    }
    [data-theme='synthwave']
        .kp-action:is(:hover, :focus-visible):not(:is(:disabled, [aria-disabled='true'], [aria-busy='true']))
        > .kp-action__title {
        text-shadow: var(--kp-sw-tube-up, var(--kp-tube-pink));
    }
    /* A press charges the tile, as it charges a button: the top edge burns near-white, the bloom gathers above it, the
       ground takes the pressed token; nothing moves. */
    [data-theme='synthwave'] .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        --kp-stripe-from: var(--kp-core);
        --kp-stripe-to: var(--kp-core);
        --kp-sw-tile-ground: var(--secondary-active);
        box-shadow:
            inset 0 -2px 0 0 hsl(from var(--sidebar-background) h s l / 0.7),
            0 -4px 14px 0 hsl(from var(--primary) h s l / 0.8);
    }
    [data-theme='synthwave'] .kp-action:is(:disabled, [aria-disabled='true']) {
        --kp-stripe-from: var(--muted-foreground);
        --kp-stripe-to: var(--muted-foreground);
        --kp-sw-tile-ground: var(--muted);
    }
    [data-theme='synthwave'] .kp-action:is(:disabled, [aria-disabled='true']) > .kp-action__title {
        color: inherit;
    }
    /* Destructive: the stripe and the sides in the red and the VCR's stop (a square) before the title, in the red ink;
       the register's tone for a failure. No side bar. */
    [data-theme='synthwave'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) {
        --kp-stripe-from: var(--destructive);
        --kp-stripe-to: var(--destructive);
    }
    [data-theme='synthwave'] .kp-action--destructive::after {
        display: none;
    }
    [data-theme='synthwave'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) > .kp-action__title,
    [data-theme='synthwave'] .kp-statusrow[data-state='failed'] .kp-statusrow__label {
        color: color-mix(in oklab, var(--destructive) 70%, var(--kp-core));
    }
    [data-theme='synthwave'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) > .kp-action__title::before,
    [data-theme='synthwave'] .kp-statusrow[data-state='failed'] .kp-statusrow__label::before {
        content: '';
        display: inline-block;
        inline-size: 0.5em;
        block-size: 0.5em;
        margin-inline-end: 0.5em;
        background: currentColor;
        filter: drop-shadow(0 0 3px currentColor);
        vertical-align: 0.06em;
    }

    /* Status rows: square tape rows with the hairline and a 2 px pink stripe on top; the detail is the OSD. A failed
       row is the red stripe and its name in the red neon; a loading row's stripe is the marquee. */
    [data-theme='synthwave'] .kp-statuslist {
        --kp-statuslist-gap: 0.625rem;
        --kp-statusrow-mark-radius: 2px;
    }
    [data-theme='synthwave'] .kp-statusrow {
        --kp-statusrow-edge: var(--kp-hairline);
        --kp-statusrow-radius: 0;
        --kp-sw-row-stripe: linear-gradient(to right, var(--primary), var(--accent));
        background:
            var(--kp-sw-row-stripe) 0 0 / 100% 2px no-repeat,
            var(--card);
    }
    [data-theme='synthwave'] .kp-statusrow[data-state='failed'] {
        --kp-sw-row-stripe: linear-gradient(var(--destructive), var(--destructive));
        --kp-statusrow-state-edge: var(--kp-hairline);
    }
    [data-theme='synthwave'] .kp-statusrow[data-state='empty'] {
        --kp-sw-row-stripe: linear-gradient(var(--kp-hairline), var(--kp-hairline));
    }
    [data-theme='synthwave'] .kp-statusrow[data-state='loading'] {
        --kp-sw-row-stripe: radial-gradient(circle, var(--kp-core) 0 1.5px, hsl(from var(--primary) h s l / 0.9) 2px, transparent 3px) 0 0 / 40px 4px
            repeat-x;
        background:
            var(--kp-sw-row-stripe),
            radial-gradient(circle, hsl(from var(--primary) h s l / 0.35) 0 1.5px, transparent 2px) 0 0 / 10px 4px repeat-x,
            var(--card);
    }
    [data-theme='synthwave'] .kp-statusrow__detail {
        color: var(--accent);
        font-family: var(--kp-mono);
        font-size-adjust: 0.5;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-statusrow[data-state='loading'] {
            animation: kp-sig-synthwave-chase calc(4 * var(--kp-sw-beat)) steps(4, end) infinite;
        }
    }

    /* Facets: 2 px rows that turn the tube up when pointed at (a pink wash, the name's neon); counts are the chrome. The
       counts on their way are marquee bulbs chasing down the list, one in four lit. */
    [data-theme='synthwave'] .kp-facets {
        --kp-facet-radius: 2px;
    }
    [data-theme='synthwave'] .kp-facet {
        --kp-facet-hover: hsl(from var(--primary) h s l / 0.1);
    }
    [data-theme='synthwave'] .kp-facet:hover .kp-facet__name {
        text-shadow: var(--kp-tube-pink);
    }
    [data-theme='synthwave'] .kp-facets__title {
        color: var(--kp-pink-text);
        font-family: var(--kp-mono);
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='synthwave'] .kp-facets__title::before {
        content: '▶ ';
        color: var(--accent);
    }
    [data-theme='synthwave'] .kp-facet__count {
        font-family: var(--kp-mono);
        font-size-adjust: 0.5;
    }
    [data-theme='synthwave'] .kp-facets[aria-busy='true'] .kp-facet__count {
        border-radius: 2px;
        background: hsl(from var(--primary) h s l / 0.14);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-facets[aria-busy='true'] .kp-facet__count {
            animation: kp-sig-synthwave-bulb calc(4 * var(--kp-sw-beat)) steps(1, end) infinite;
        }
        [data-theme='synthwave'] .kp-facets[aria-busy='true'] li:nth-child(4n + 2) .kp-facet__count {
            animation-delay: calc(-3 * var(--kp-sw-beat));
        }
        [data-theme='synthwave'] .kp-facets[aria-busy='true'] li:nth-child(4n + 3) .kp-facet__count {
            animation-delay: calc(-2 * var(--kp-sw-beat));
        }
        [data-theme='synthwave'] .kp-facets[aria-busy='true'] li:nth-child(4n + 4) .kp-facet__count {
            animation-delay: calc(-1 * var(--kp-sw-beat));
        }
    }

    /* Heat grid and matrix: every cell a tube, 2 px, lit from inside in its tone, its glow the tone's own light; the
       pick a cyan rail pair; pointing turns the tube up (a wider bloom), nothing grows. Waiting, the cells are the
       marquee: one bulb in four lit, the light chasing start to end. */
    [data-theme='synthwave'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-radius: 2px;
        --kp-heat-cell-gap: 3px;
        --kp-heat-cell-hover: none;
        --kp-matrix-cell-hover: none;
    }
    [data-theme='synthwave'] .kp-heat {
        --kp-heat-gap-y: 6px;
    }
    [data-theme='synthwave'] .kp-matrix {
        --kp-matrix-gap: 4px;
    }
    [data-theme='synthwave']
        .kp-heat__cell:is([data-kp-tone='ok'], [data-kp-tone='warn'], [data-kp-tone='bad'], [data-kp-tone='level']):not([data-kp-share]),
    [data-theme='synthwave'] .kp-heat__swatch:is([data-kp-tone='ok'], [data-kp-tone='warn'], [data-kp-tone='bad'], [data-kp-tone='level']) {
        background-image: linear-gradient(to bottom, hsl(from var(--background) h s 100% / 0.45), transparent 55%), var(--kp-heat-pattern);
        box-shadow: 0 0 8px hsl(from var(--kp-heat-fill) h s l / 0.7);
    }
    [data-theme='synthwave'] .kp-heat__cell[data-kp-share] {
        box-shadow: 0 0 6px hsl(from var(--kp-heat-fill) h s l / 0.5);
    }
    [data-theme='synthwave'] .kp-heat__cell:hover:not(.kp-skeleton, [aria-disabled='true']),
    [data-theme='synthwave'] .kp-matrix__cell:hover:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
        box-shadow:
            0 0 4px var(--kp-core),
            0 0 14px hsl(from var(--primary) h s l / 0.8);
    }
    [data-theme='synthwave'] .kp-heat__cell[data-kp-picked] {
        outline: none;
        box-shadow:
            0 -3px 0 -1px var(--accent),
            0 3px 0 -1px var(--accent);
    }
    [data-theme='synthwave'] .kp-matrix__cell[aria-pressed='true'] {
        outline: none;
        box-shadow:
            0 0 0 2px var(--accent),
            0 0 12px var(--accent);
    }
    [data-theme='synthwave'] :is(.kp-heat__col, .kp-matrix__col) {
        font-family: var(--kp-mono);
    }
    [data-theme='synthwave'] .kp-heat__label-button[aria-pressed='true'] {
        background: hsl(from var(--primary) h s l / 0.16);
        color: var(--kp-core);
        text-shadow: var(--kp-tube-pink);
    }
    [data-theme='synthwave'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        border-radius: 2px;
        background: hsl(from var(--primary) h s l / 0.12);
        box-shadow: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
            animation: kp-sig-synthwave-bulb calc(4 * var(--kp-sw-beat)) steps(1, end) infinite;
        }
        [data-theme='synthwave'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton:nth-child(4n + 2) {
            animation-delay: calc(-3 * var(--kp-sw-beat));
        }
        [data-theme='synthwave'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton:nth-child(4n + 3) {
            animation-delay: calc(-2 * var(--kp-sw-beat));
        }
        [data-theme='synthwave'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton:nth-child(4n + 4) {
            animation-delay: calc(-1 * var(--kp-sw-beat));
        }
    }
    [data-theme='synthwave'] .kp-bar-cell {
        --kp-bar-cell-gap: var(--kp-space-sm, 0.5rem);
        font-family: var(--theme-font-display);
        font-variant-numeric: tabular-nums;
    }

    /* Week agenda and run timeline: the arcade floor. Pills are 2 px tape with the series' ink as a stripe along their
       top; the OSD names the days and the axis; the line for now is the laser in pink with its core. A running bar is
       the road: a dark lane in a pink tube with its core dashes racing start to end. */
    [data-theme='synthwave'] .kp-week {
        --kp-week-pill-radius: 2px;
        --kp-week-now: var(--primary);
    }
    [data-theme='synthwave'] .kp-gantt {
        --kp-gantt-state-ground: var(--card);
        --kp-gantt-bar-radius: 2px;
        --kp-gantt-now: var(--primary);
    }
    [data-theme='synthwave'] .kp-week__pill {
        border-color: var(--kp-hairline);
        border-block-start: 2px solid var(--kp-week-ink);
    }
    [data-theme='synthwave'] .kp-week__pill:is(button):hover,
    [data-theme='synthwave'] .kp-gantt__run:is(button):hover {
        box-shadow:
            0 0 0 1px var(--kp-core),
            0 0 12px hsl(from var(--primary) h s l / 0.7);
    }
    [data-theme='synthwave'] .kp-week__pill[data-kp-state='next'] {
        box-shadow:
            0 0 0 1px var(--accent),
            0 0 10px hsl(from var(--accent) h s l / 0.7);
    }
    [data-theme='synthwave'] :is(.kp-week__now, .kp-gantt__now) {
        filter: drop-shadow(0 0 3px var(--primary)) drop-shadow(0 0 8px hsl(from var(--primary) h s l / 0.6));
    }
    [data-theme='synthwave'] .kp-week__now::before {
        background: var(--kp-core);
        box-shadow: 0 0 6px var(--primary);
    }
    [data-theme='synthwave'] :is(.kp-gantt__tick, .kp-week__head) {
        font-family: var(--kp-mono);
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='synthwave'] .kp-week__time {
        color: var(--accent);
        font-family: var(--kp-mono);
    }
    [data-theme='synthwave'] .kp-gantt__run[data-kp-state='running'] {
        border-color: var(--primary);
        background: var(--sidebar-background);
        color: var(--kp-core);
        box-shadow:
            inset -3px 0 0 var(--kp-core),
            0 0 8px hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='synthwave'] .kp-gantt__run[data-kp-state='running']::after {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline: calc(-1 * var(--kp-sw-lane, 1.5rem)) 0;
        background: linear-gradient(90deg, var(--kp-core) 0 0.75rem, transparent 0.75rem) 0 50% / var(--kp-sw-lane, 1.5rem) 2px repeat-x;
        filter: drop-shadow(0 0 2px var(--primary));
        pointer-events: none;
    }
    [data-theme='synthwave'] .kp-gantt__swatch[data-kp-state='running'] {
        border-color: var(--primary);
        background:
            linear-gradient(90deg, var(--kp-core) 0 3px, transparent 3px) 0 50% / 6px 2px repeat-x,
            var(--sidebar-background);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-gantt__run[data-kp-state='running'] {
            animation: none;
        }
        [data-theme='synthwave'] .kp-gantt__run[data-kp-state='running']::after {
            animation: kp-sig-synthwave-lane 600ms linear infinite;
        }
    }

    /* A phone's timeline keeps its toolbar on one row: the range steps close in a little in these wide letters. */
    @container kp-gantt (max-width: 22rem) {
        [data-theme='synthwave'] .kp-gantt__ranges {
            --kp-seg-item-pad-inline: 0.5rem;
        }
    }

    /* One bulb of the marquee: lit for one beat of four, dark for the rest. */
    @keyframes kp-sig-synthwave-bulb {
        0% {
            background-color: hsl(from var(--primary) h s l / 0.9);
            box-shadow:
                0 0 2px var(--kp-core),
                0 0 8px hsl(from var(--primary) h s l / 0.8);
        }

        25%,
        100% {
            background-color: hsl(from var(--primary) h s l / 0.12);
            box-shadow: none;
        }
    }

    /* The bulbs along a row's top edge chase one bulb a step. */
    @keyframes kp-sig-synthwave-chase {
        from {
            background-position:
                0 0,
                0 0,
                0 0;
        }

        to {
            background-position:
                40px 0,
                0 0,
                0 0;
        }
    }

    /* The road's lane dashes race along the running bar. */
    @keyframes kp-sig-synthwave-lane {
        from {
            transform: translateX(0);
        }

        to {
            transform: translateX(var(--kp-sw-lane, 1.5rem));
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='synthwave'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='synthwave'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='synthwave'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='synthwave'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='synthwave'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='synthwave'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Synthwave's own (themes/synthwave/CHARACTER.md): the separator is the horizon stood upright, the pink
   tube with its white core glowing; lying down across the phone's list it is the horizon itself. A day on the axis is
   swept by the laser under the pointer; pressed it is lit in the pink tube with its glow, the date in the core's white.
   A series' finished run glows in its own neon; the upcoming list's day rule is a line of the grid floor; the facet
   pattern glows in its hue. */
@layer kp.signature {
    [data-theme='synthwave'] .kp-nav__sep {
        inline-size: 2px;
        border-inline-start: 0;
        border-radius: 1px;
        background: var(--kp-pink-text, var(--primary));
        box-shadow:
            0 0 6px var(--primary),
            0 0 14px hsl(from var(--primary) h s l / 0.5);
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='synthwave'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            inline-size: auto;
            block-size: 2px;
            border-block-start: 0;
        }
    }

    [data-theme='synthwave'] .kp-gantt__tick:is(button) {
        border-radius: 2px;
        text-decoration: none;
    }
    [data-theme='synthwave'] .kp-gantt__tick:is(button):hover {
        color: var(--kp-core);
        box-shadow: inset 0 -2px 0 var(--primary);
    }
    [data-theme='synthwave'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: hsl(from var(--primary) h s l / 0.18);
        color: var(--kp-core);
        box-shadow:
            inset 0 0 0 1px var(--primary),
            0 0 10px hsl(from var(--primary) h s l / 0.6);
        text-shadow: 0 0 6px var(--primary);
    }
    [data-theme='synthwave'] .kp-gantt__run[data-kp-state='ok'][data-kp-series] {
        box-shadow: 0 0 7px hsl(from var(--kp-gantt-series) h s l / 0.7);
    }
    [data-theme='synthwave'] .kp-gantt__run[data-kp-state='ok'][data-kp-series]:hover {
        box-shadow:
            0 0 0 1px var(--kp-core),
            0 0 12px hsl(from var(--primary) h s l / 0.7);
    }
    [data-theme='synthwave'] .kp-week__next:not(:has(+ .kp-week__next:not([data-kp-day-start]))) {
        border-block-end-color: hsl(from var(--primary) h s l / 0.35);
    }
    [data-theme='synthwave'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 2px;
        box-shadow: 0 0 6px hsl(from var(--kp-facet-swatch-colour, var(--primary)) h s l / 0.7);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-gantt__tick:is(button) {
            transition: box-shadow var(--fx-duration) var(--fx-ease);
        }
    }
}

/* ── The kpadopt4 components in synthwave's own grammar [kpadopt4] ──
   Synthwave is the drive into the sunset (themes/synthwave/CHARACTER.md): the tape stands on the grid floor under its
   own horizon, every light is a neon tube, what arrives rises over its horizon and what leaves sets behind it (G2, G3,
   G12). A part that is drawn rises 0.5 rem from behind its line, uncovered from that line up, on the sunrise curve in
   two beats of 225 ms (G1, G4); light switches in hard steps and is never tweened (G1); pointing turns the tube up in one
   step (G8); a press dips it (G14); a warning is a hollow neon ring before the title or figure, the words glowing in the
   tone's ink (G13); a change draws the laser (G9); labels are the OSD's capitals after a cyan arrow, figures the chrome
   display (G15); square plates carrying the pink to cyan stripe, 2 px controls, never a notch or a pill (G6). */
@layer kp.signature {
    [data-theme='synthwave'] {
        --kp-sw4-beat: var(--kp-sw-beat, 225ms);
        --kp-sw4-stripe: linear-gradient(to right, var(--primary), var(--accent));
        --kp-sw4-horizon: linear-gradient(90deg, transparent, var(--kp-pink-text) 50%, transparent);
        --kp-sw4-sun: linear-gradient(var(--kp-sun-top), var(--kp-sun-bottom));
        --kp-art-rule: var(--primary);
        --kp-art-line: hsl(from var(--kp-pink-text) h s l / 0.35);
        --kp-art-ink: var(--accent);
        --kp-art-red: var(--destructive);
        --kp-art-stroke: 1.5px;
    }

    /* A hollow neon ring before a title or a figure: the near-white core, the bloom in the tone's ink. Set --kp-sw4-tone
       on the part and give it the class's ::before. */
    [data-theme='synthwave'] :is(
            .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure,
            .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure,
            .kp-action-list--lead > li[data-kp-state='failed'] .kp-action-list__title,
            .kp-action-list--lead > li[data-kp-state='warn'] .kp-action-list__title,
            .kp-kv__row[data-kp-state='error'] > dt,
            .kp-formrow[data-kp-state='error'] .kp-formrow__label,
            .kp-statusrow[data-state='warn'] .kp-statusrow__title,
            .kp-timer[data-kp-timer-state='done'] .kp-timer__name,
            .kp-countdown[data-kp-countdown-state='ended'] .kp-countdown__name,
            .kp-segmented__item[data-kp-segmented-tri='exclude'] > .kp-segmented__label
        )::before {
        content: '';
        display: inline-block;
        inline-size: 0.6em;
        block-size: 0.6em;
        margin-inline-end: 0.45em;
        border: 2px solid var(--kp-core);
        border-radius: 50%;
        box-shadow:
            0 0 5px var(--kp-sw4-tone),
            inset 0 0 4px var(--kp-sw4-tone);
        vertical-align: 0.05em;
        box-sizing: border-box;
    }

    /* ── Identity mark: a plate in the name's colour, 2 px corners, the letters in the chrome display; the round mark is
       the neon ring ── */
    [data-theme='synthwave'] .kp-idmark {
        --kp-idmark-radius: 2px;
        font-family: var(--theme-font-display);
        font-weight: 400;
        letter-spacing: 0.04em;
        text-shadow: 0 0 4px hsl(from var(--kp-idmark-c) h s l / 0.7);
    }
    [data-theme='synthwave'] .kp-idmark--round {
        border-width: 2px;
        border-color: var(--kp-core);
        background: color-mix(in oklab, var(--kp-idmark-c) 14%, var(--card));
        box-shadow:
            0 0 6px var(--kp-idmark-c),
            inset 0 0 6px hsl(from var(--kp-idmark-c) h s l / 0.6);
    }
    [data-theme='synthwave'] .kp-idmark--pattern {
        text-shadow: none;
    }
    [data-theme='synthwave'] .kp-idmark--glyph::after {
        border-radius: 0;
        box-shadow: 0 0 5px var(--kp-idmark-c);
    }
    [data-theme='synthwave'] .kp-idmark[aria-current]:not([aria-current='false']),
    [data-theme='synthwave'] .kp-idmark[data-kp-idmark-selected] {
        box-shadow:
            0 0 0 2px var(--card),
            0 0 0 3px var(--kp-core),
            0 0 10px 3px hsl(from var(--primary) h s l / 0.7);
    }
    [data-theme='synthwave'] .kp-idmark-group__more {
        border-radius: 2px;
        font-family: var(--kp-osd);
    }

    /* ── Share bar: the parts are held tubes with the stripe's gap; the part pointed at turns up in one step; the
       threshold is a laser tick; the title is the OSD ── */
    [data-theme='synthwave'] .kp-stackbar {
        --kp-stackbar-radius: 2px;
    }
    [data-theme='synthwave'] .kp-stackbar__title {
        font-family: var(--kp-osd);
        font-size: 1.125rem;
        font-weight: 400;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }
    [data-theme='synthwave'] .kp-stackbar__title::before {
        content: '▶ ';
        color: var(--accent);
    }
    [data-theme='synthwave'] .kp-stackbar__total,
    [data-theme='synthwave'] .kp-stackbar__value {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.08em;
        color: var(--accent);
    }
    [data-theme='synthwave'] .kp-stackbar__bar {
        background: hsl(from var(--sidebar-background) h s l / 0.8);
        box-shadow: inset 0 -1px 0 var(--kp-hairline);
    }
    [data-theme='synthwave'] .kp-stackbar__seg {
        border-radius: 0;
        outline: 0;
    }
    [data-theme='synthwave'] .kp-stackbar__seg[data-kp-stackbar-lit] {
        filter: brightness(1.2) drop-shadow(0 0 5px var(--kp-stackbar-colour, var(--chart-1)));
        box-shadow: inset calc(var(--kp-stackbar-gap, 2px) * -1) 0 0 var(--card);
    }
    [data-theme='synthwave'] .kp-stackbar__mark {
        inset-block: -4px;
        background: var(--kp-core);
        box-shadow:
            0 0 2px var(--sidebar-background),
            0 0 6px var(--primary);
    }
    [data-theme='synthwave'] .kp-stackbar__swatch {
        border-radius: 1px;
        box-shadow: 0 0 5px var(--kp-stackbar-colour, var(--chart-1));
    }
    [data-theme='synthwave'] .kp-stackbar__item[data-kp-stackbar-lit] .kp-stackbar__label {
        text-shadow: var(--kp-tube-pink);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-stackbar:not([aria-busy='true']) .kp-stackbar__bar {
            animation: kp-sw4-rise calc(2 * var(--kp-sw4-beat)) var(--kp-sw-sun) backwards;
        }
    }

    /* ── Bullet rows: the figure is the OSD's read-out; a tone is the neon ring before it, the figure glowing in its ink ── */
    [data-theme='synthwave'] .kp-bullets__figure {
        font-family: var(--kp-osd);
        font-size: 1.125rem;
        font-weight: 400;
        letter-spacing: 0.06em;
        border-radius: 0;
    }
    [data-theme='synthwave'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure,
    [data-theme='synthwave'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        padding-inline: 0;
        background: transparent;
    }
    [data-theme='synthwave'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        --kp-sw4-tone: var(--destructive);
        color: var(--destructive);
        text-shadow: 0 0 6px hsl(from var(--destructive) h s l / 0.6);
    }
    [data-theme='synthwave'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure {
        --kp-sw4-tone: var(--warning-foreground);
        color: var(--warning-foreground);
        text-shadow: 0 0 6px hsl(from var(--warning-foreground) h s l / 0.6);
    }
    [data-theme='synthwave'] .kp-bullets__row:has(.kp-bullets__link:is(:hover, :focus-visible)) .kp-bullets__label {
        text-shadow: var(--kp-tube-pink);
    }
    [data-theme='synthwave'] .kp-bullets__detail {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.06em;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-bullets:not([aria-busy='true']) .kp-bullets__row {
            animation: kp-sw4-rise calc(2 * var(--kp-sw4-beat)) var(--kp-sw-sun) backwards;
        }
        [data-theme='synthwave'] .kp-bullets:not([aria-busy='true']) .kp-bullets__row:nth-child(2) {
            animation-delay: var(--kp-sw4-beat);
        }
        [data-theme='synthwave'] .kp-bullets:not([aria-busy='true']) .kp-bullets__row:nth-child(n + 3) {
            animation-delay: calc(2 * var(--kp-sw4-beat));
        }
    }

    /* ── Key-value grid and form rows: the key is the OSD after a cyan arrow, the failed row takes the neon ring ── */
    [data-theme='synthwave'] .kp-kv__row > dt,
    [data-theme='synthwave'] .kp-formrow__label {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }
    [data-theme='synthwave'] .kp-kv__row > dt::before {
        content: '▶ ';
        color: var(--accent);
    }
    [data-theme='synthwave'] .kp-formrow__label > small {
        font-family: var(--theme-font-body);
        text-transform: none;
        letter-spacing: 0;
        color: var(--muted-foreground);
    }
    [data-theme='synthwave'] .kp-kv__row[data-kp-state='error'] > dt,
    [data-theme='synthwave'] .kp-formrow[data-kp-state='error'] .kp-formrow__label {
        --kp-sw4-tone: var(--destructive);
        color: var(--destructive);
        text-shadow: 0 0 6px hsl(from var(--destructive) h s l / 0.5);
    }
    [data-theme='synthwave'] .kp-kv__row[data-kp-state='error']::before,
    [data-theme='synthwave'] .kp-formrow[data-kp-state='error']::before {
        display: none;
    }
    [data-theme='synthwave'] .kp-kv__row[data-kp-changed] > dt::after {
        color: var(--primary);
        text-shadow: var(--kp-tube-pink);
    }
    [data-theme='synthwave'] .kp-formrows--lines > .kp-formrow,
    [data-theme='synthwave'] .kp-kv--lines > .kp-kv__row {
        border-image: var(--kp-sw4-horizon) 1;
    }

    /* ── Code block: the tape with its stripe, the title the OSD after a cyan arrow ── */
    [data-theme='synthwave'] .kp-code {
        border-radius: 0;
        border-block-start: 3px solid transparent;
        border-image: var(--kp-sw4-stripe) 1;
        border-image-width: 3px 0 0 0;
    }
    [data-theme='synthwave'] .kp-code__title,
    [data-theme='synthwave'] .kp-code__meta {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }
    [data-theme='synthwave'] .kp-code__title::before {
        content: '▶ ';
        color: var(--accent);
    }
    [data-theme='synthwave'] .kp-code__head {
        border-block-end: 1px solid var(--kp-hairline);
    }

    /* ── Page header line ── */
    [data-theme='synthwave'] .kp-page-header__meta {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.08em;
        color: var(--accent);
    }

    /* ── A number that ticks: a laser is drawn under it from its centre outward in one beat, flares, and burns down,
       3 beats once; the figure never moves ── */
    [data-theme='synthwave'] [data-kp-tick] {
        position: relative;
        font-family: var(--theme-font-display);
    }
    [data-theme='synthwave'] [data-kp-tick]::after {
        content: '';
        position: absolute;
        inset-inline: 0;
        inset-block-end: -3px;
        block-size: 2px;
        background: var(--kp-core);
        box-shadow:
            0 0 6px var(--primary),
            0 0 16px hsl(from var(--primary) h s l / 0.9);
        opacity: 0;
        transform: scaleX(0);
        pointer-events: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] [data-kp-tick][data-kp-tick-state='running']::after {
            animation: kp-sig-synthwave-update-laser calc(3 * var(--kp-sw4-beat)) linear;
        }
    }

    /* The rise: what arrives is uncovered from its horizon up while it climbs 0.5 rem, on the sunrise curve. */
    @keyframes kp-sw4-rise {
        from {
            clip-path: inset(100% -2rem -2rem -2rem);
            translate: 0 0.5rem;
        }
        to {
            clip-path: inset(-2rem);
            translate: 0 0;
        }
    }
}
/* ── end the kpadopt4 data pieces ── */

/* ── The kpadopt4 rows, records and flows in synthwave's own grammar [kpadopt4] ──
   Rows and lanes rise over their horizon one beat after the part before (G3, G4); pointing turns the row's tube up (G8);
   a warning is the hollow neon ring before the title (G13); a plate carries the stripe along its top and is square (G6,
   G7); the journey is the drive: the horizon runs between the steps reached, the current step is the striped sun (G16);
   the drawings for an empty state are the horizon, the striped sun and the floor (G16). */
@layer kp.signature {
    /* ── Rows with a lead ── */
    [data-theme='synthwave'] .kp-action-list--lead {
        --kp-action-list-bar: 3px;
        --kp-action-list-next-wash: 0%;
    }
    [data-theme='synthwave'] .kp-action-list--lead > li[data-kp-state='new'],
    [data-theme='synthwave'] .kp-action-list--lead > li[data-kp-state='next'] {
        border-image: linear-gradient(var(--primary), var(--accent)) 1;
        border-image-width: 0 0 0 3px;
    }
    [data-theme='synthwave'] .kp-action-list--lead > li:is(:hover, :focus-within) .kp-action-list__title {
        text-shadow: var(--kp-tube-pink);
    }
    [data-theme='synthwave'] .kp-action-list--lead > li[data-kp-state='failed'] .kp-action-list__title {
        --kp-sw4-tone: var(--destructive);
        color: var(--destructive);
    }
    [data-theme='synthwave'] .kp-action-list--lead > li[data-kp-state='warn'] .kp-action-list__title {
        --kp-sw4-tone: var(--warning-foreground);
        color: var(--warning-foreground);
    }
    [data-theme='synthwave'] .kp-action-list--lead > li[data-kp-state='next'] > .kp-action-list__lead {
        color: var(--primary);
        text-shadow: var(--kp-tube-pink);
    }
    [data-theme='synthwave'] .kp-action-list__when,
    [data-theme='synthwave'] .kp-action-list__meta {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.06em;
    }
    [data-theme='synthwave'] .kp-action-list__payload {
        border-radius: 2px;
        font-family: var(--kp-mono);
    }
    [data-theme='synthwave'] .kp-action-list > li.kp-action-list__group > :is(h2, h3, h4, h5, h6) {
        font-family: var(--kp-osd);
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-action-list--lead > li {
            animation: kp-sw4-rise calc(2 * var(--kp-sw4-beat)) var(--kp-sw-sun) backwards;
        }
        [data-theme='synthwave'] .kp-action-list--lead > li:nth-child(2) {
            animation-delay: var(--kp-sw4-beat);
        }
        [data-theme='synthwave'] .kp-action-list--lead > li:nth-child(3) {
            animation-delay: calc(2 * var(--kp-sw4-beat));
        }
        [data-theme='synthwave'] .kp-action-list--lead > li:nth-child(n + 4) {
            animation-delay: calc(3 * var(--kp-sw4-beat));
        }
    }

    /* ── Status rows ── */
    [data-theme='synthwave'] .kp-statusrow[data-state='warn'] {
        --kp-statusrow-state-edge: hsl(from var(--warning-foreground) h s l / 0.5);
        --kp-sw4-tone: var(--warning-foreground);
        --kp-statusrow-radius: 2px;
    }
    [data-theme='synthwave'] .kp-statusrow[data-state='warn'] .kp-statusrow__title {
        color: var(--warning-foreground);
    }
    [data-theme='synthwave'] .kp-statusrow__fix {
        font-family: var(--theme-font-body);
        padding-inline-start: 0.5rem;
        border-inline-start: 1px solid var(--kp-hairline);
    }

    /* ── Choices as tiles: a tape with its stripe; pointing turns the tube up; checked it is lit pink ── */
    [data-theme='synthwave'] .kp-fieldset[data-kp-layout='tiles'] {
        --kp-field-tile-radius: 2px;
        --kp-field-tile-ground-checked: color-mix(in oklab, var(--primary) 10%, var(--card));
    }
    [data-theme='synthwave'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
        background-image: var(--kp-sw4-stripe);
        background-size: 100% 2px;
        background-repeat: no-repeat;
        background-position: 0 0;
    }
    [data-theme='synthwave'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:hover:not(:has(> .kp-field__check:disabled)) {
        border-color: var(--kp-pink-text);
        box-shadow: 0 0 8px hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='synthwave'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:hover:not(:has(> .kp-field__check:disabled)) .kp-field__option-title {
        text-shadow: var(--kp-tube-pink);
    }
    [data-theme='synthwave'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:active:not(:has(> .kp-field__check:disabled)) {
        box-shadow: none;
    }
    [data-theme='synthwave'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:checked) {
        box-shadow:
            inset 0 0 0 1px var(--primary),
            0 0 10px hsl(from var(--primary) h s l / 0.45);
    }
    [data-theme='synthwave'] .kp-field__option-title {
        font-family: var(--theme-font-body);
    }
    [data-theme='synthwave'] .kp-field__option-hint {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.04em;
    }

    /* ── A card in four data states ── */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-card[data-kp-state='ready'] > .kp-card__stage > .kp-card__data {
            animation: kp-sw4-rise calc(2 * var(--kp-sw4-beat)) var(--kp-sw-sun) backwards;
        }
    }

    /* ── Drawings for an empty state: the horizon. The drawing rises over its own horizon, uncovered from the line up,
       on the sunrise curve in two beats; its tubes glow in their ink. ── */
    [data-theme='synthwave'] .kp-art {
        display: block;
    }
    [data-theme='synthwave'] .kp-art > g[data-kp-art-set='horizon'] {
        display: inline;
    }
    [data-theme='synthwave'] .kp-art path {
        stroke-linecap: round;
        stroke-linejoin: round;
    }
    [data-theme='synthwave'] .kp-art__rule {
        filter: drop-shadow(0 0 3px hsl(from var(--primary) h s l / 0.8));
    }
    [data-theme='synthwave'] .kp-art__ink {
        filter: drop-shadow(0 0 2px hsl(from var(--accent) h s l / 0.6));
    }
    [data-theme='synthwave'] .kp-art__red {
        filter: drop-shadow(0 0 3px hsl(from var(--destructive) h s l / 0.8));
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-art {
            animation: kp-sw4-rise calc(2 * var(--kp-sw4-beat)) var(--kp-sw-sun) backwards;
        }
    }

    /* ── The pipeline: a lane is the tape, square, with the stripe along its top; a card is a plate on it; the chosen card
       turns its tube up and keeps it ── */
    [data-theme='synthwave'] .kp-pipeline__lane {
        border-radius: 0;
        background: var(--kp-sw4-stripe) 0 0 / 100% 3px no-repeat, var(--muted);
    }
    [data-theme='synthwave'] .kp-pipeline__head {
        border-radius: 2px;
    }
    [data-theme='synthwave'] .kp-pipeline__name {
        font-family: var(--kp-osd);
        font-size: 1.125rem;
        font-weight: 400;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }
    [data-theme='synthwave'] .kp-pipeline__name::before {
        content: '▶ ';
        color: var(--accent);
    }
    [data-theme='synthwave'] .kp-pipeline__count {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }
    [data-theme='synthwave'] .kp-pipeline__share,
    [data-theme='synthwave'] .kp-pipeline__sub,
    [data-theme='synthwave'] .kp-pipeline__meta {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.04em;
    }
    [data-theme='synthwave'] .kp-pipeline__card {
        border-radius: 2px;
    }
    [data-theme='synthwave'] .kp-pipeline__card:hover {
        box-shadow: 0 0 8px hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='synthwave'] .kp-pipeline__card:hover .kp-pipeline__title,
    [data-theme='synthwave'] .kp-pipeline__card[aria-current='true'] .kp-pipeline__title {
        text-shadow: var(--kp-tube-pink);
    }
    [data-theme='synthwave'] .kp-pipeline__card[aria-current='true'] {
        outline: 0;
        border-color: var(--kp-core);
        box-shadow:
            0 0 0 1px var(--primary),
            0 0 12px hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='synthwave'] .kp-pipeline__mark {
        border-radius: 2px;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-pipeline:not([aria-busy='true']) .kp-pipeline__lane {
            animation: kp-sw4-rise calc(2 * var(--kp-sw4-beat)) var(--kp-sw-sun) backwards;
        }
        [data-theme='synthwave'] .kp-pipeline:not([aria-busy='true']) .kp-pipeline__lane:nth-child(2) {
            animation-delay: var(--kp-sw4-beat);
        }
        [data-theme='synthwave'] .kp-pipeline:not([aria-busy='true']) .kp-pipeline__lane:nth-child(3) {
            animation-delay: calc(2 * var(--kp-sw4-beat));
        }
        [data-theme='synthwave'] .kp-pipeline:not([aria-busy='true']) .kp-pipeline__lane:nth-child(n + 4) {
            animation-delay: calc(3 * var(--kp-sw4-beat));
        }
    }

    /* ── The journey: the horizon runs between the steps reached, the steps to come are the lane's dashes, the current
       step is the striped sun ── */
    [data-theme='synthwave'] .kp-steplist--journey {
        --kp-journey-rule: 2px;
    }
    [data-theme='synthwave'] .kp-steplist--journey > .kp-steplist__item:is([data-state='done'], [data-state='current'])::before {
