    }
    [data-theme='synthwave'] .kp-steplist__item[data-state='current'] .kp-steplist__mark {
        border-color: transparent;
        background:
            repeating-linear-gradient(to bottom, transparent 0 55%, var(--card) 55% 62%, transparent 62% 70%, var(--card) 70% 78%, transparent 78% 86%, var(--card) 86% 94%, transparent 94%),
            var(--kp-sw4-sun);
        box-shadow: 0 0 10px hsl(from var(--kp-sun-glow) h s l / 0.7);
    }
    [data-theme='synthwave'] .kp-steplist--journey .kp-steplist__title {
        font-family: var(--kp-osd);
        font-size: 1.125rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }
    [data-theme='synthwave'] .kp-steplist--journey .kp-steplist__time {
        font-family: var(--kp-osd);
        font-size: 1rem;
        color: var(--accent);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-steplist--journey > .kp-steplist__item {
            animation: kp-sw4-rise calc(2 * var(--kp-sw4-beat)) var(--kp-sw-sun) backwards;
        }
        [data-theme='synthwave'] .kp-steplist--journey > .kp-steplist__item:nth-child(2) {
            animation-delay: var(--kp-sw4-beat);
        }
        [data-theme='synthwave'] .kp-steplist--journey > .kp-steplist__item:nth-child(3) {
            animation-delay: calc(2 * var(--kp-sw4-beat));
        }
        [data-theme='synthwave'] .kp-steplist--journey > .kp-steplist__item:nth-child(n + 4) {
            animation-delay: calc(3 * var(--kp-sw4-beat));
        }
    }

    /* ── Moments on the run timeline and the dated line ── */
    [data-theme='synthwave'] .kp-gantt__point:hover::before,
    [data-theme='synthwave'] .kp-gantt__point:focus-visible::before {
        box-shadow: 0 0 8px hsl(from var(--primary) h s l / 0.8);
    }
    [data-theme='synthwave'] .kp-gantt__count {
        font-family: var(--kp-osd);
        border-radius: 2px;
    }
    [data-theme='synthwave'] .kp-gantt__zone {
        border-inline-start: 1px solid var(--kp-hairline);
    }
    [data-theme='synthwave'] .kp-gantt__mark {
        box-shadow: 0 0 6px hsl(from var(--primary) h s l / 0.7);
    }
}
/* ── end the kpadopt4 rows and flows ── */

/* ── The kpadopt4 secrets, time, cooking and commands in synthwave's own grammar [kpadopt4] ──
   A secret is a tube that strikes on (G1, G13); what runs out is a laser burning down (G9); a clock is the sun setting:
   the share left is the striped sun, its stripes closing as it sinks, on the face's horizon ring (G11, G16); the wheel is
   the arcade's: marquee bulbs round its rim, a turn on the sunrise curve (G1, G10); a thing that ends or fails has the
   neon ring (G13); a command is the VCR's OSD over the tape (G15). Light switches in hard steps, bodies glide. */
@layer kp.signature {
    /* ── Secret field ── */
    [data-theme='synthwave'] .kp-secret__value {
        border-radius: 2px;
        font-family: var(--kp-mono);
        background: hsl(from var(--sidebar-background) h s l / 0.85);
    }
    [data-theme='synthwave'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__value {
        border-color: var(--kp-pink-text);
        box-shadow: 0 0 8px hsl(from var(--primary) h s l / 0.45);
    }
    [data-theme='synthwave'] .kp-secret {
        --kp-secret-drain: var(--kp-core);
    }
    [data-theme='synthwave'] .kp-secret__drain {
        background: var(--kp-core);
        box-shadow:
            0 0 6px var(--primary),
            0 0 14px hsl(from var(--primary) h s l / 0.8);
    }
    [data-theme='synthwave'] .kp-secret__line {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.08em;
        color: var(--accent);
    }
    [data-theme='synthwave'] .kp-secret[data-kp-secret-state='error'] .kp-secret__words {
        color: var(--destructive);
        text-shadow: 0 0 6px hsl(from var(--destructive) h s l / 0.5);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='synthwave'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__text {
            animation: kp-tube-on calc(4 * var(--kp-sw4-beat)) steps(1, end) backwards;
        }
    }

    /* ── Dialog in sections, confirmation, typed confirmation ── */
    [data-theme='synthwave'] .kp-dialog__heading {
        font-family: var(--kp-osd);
        font-size: 1.125rem;
        font-weight: 400;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        color: var(--kp-pink-text);
    }
    [data-theme='synthwave'] .kp-dialog__heading::before {
        content: '▶ ';
        color: var(--accent);
    }
    [data-theme='synthwave'] .kp-dialog__section:not(:first-child) {
        border-block-start: 1px solid transparent;
        border-image: var(--kp-sw4-horizon) 1;
    }
    [data-theme='synthwave'] .kp-dialog__section--danger {
        border-inline-start: 0;
        border-image: none;
        margin-inline: calc(-1 * var(--kp-dialog-section-inset, 0.5rem));
        padding-inline: var(--kp-dialog-section-inset, 0.5rem);
    }
    [data-theme='synthwave'] .kp-dialog__section--danger > .kp-dialog__heading {
        --kp-sw4-tone: var(--destructive);
        color: var(--destructive);
        text-shadow: 0 0 6px hsl(from var(--destructive) h s l / 0.5);
    }
    [data-theme='synthwave'] .kp-dialog__section--danger > .kp-dialog__heading::before {
        content: '';
        display: inline-block;
        inline-size: 0.6em;
        block-size: 0.6em;
        margin-inline-end: 0.45em;
        border: 2px solid var(--kp-core);
        border-radius: 50%;
        box-shadow:
            0 0 5px var(--destructive),
            inset 0 0 4px var(--destructive);
        box-sizing: border-box;
    }
    [data-theme='synthwave'] .kp-confirm__dependents,
    [data-theme='synthwave'] .kp-type-confirm__loses {
        border-radius: 0;
    }
    [data-theme='synthwave'] .kp-type-confirm__loses {
        border-inline-start-width: 1px;
        border-inline-start-color: var(--border);
        border-block-start: 2px solid var(--destructive);
    }
    [data-theme='synthwave'] .kp-type-confirm__loses-title {
        font-family: var(--kp-osd);
        font-size: 1.125rem;
        font-weight: 400;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--destructive);
    }
    [data-theme='synthwave'] .kp-type-confirm__name {
        border-radius: 2px;
        font-family: var(--kp-osd);
        font-size: 1.125rem;
        color: var(--accent);
        letter-spacing: 0.06em;
    }
    [data-theme='synthwave'] .kp-type-confirm__list,
    [data-theme='synthwave'] .kp-type-confirm__input {
        font-family: var(--kp-mono);
    }
    [data-theme='synthwave'] .kp-type-confirm__status {
        font-family: var(--kp-osd);
        font-size: 1rem;
        letter-spacing: 0.08em;
    }
    [data-theme='synthwave'] .kp-type-confirm[data-kp-matched] .kp-type-confirm__input {
        border-color: var(--accent);
        box-shadow: 0 0 8px hsl(from var(--accent) h s l / 0.5);
