/* ── end the kpadopt4 secrets, time, cooking and commands ── */

/* ── t56: the kpadopt5/6 parts inside synthwave ── */
@layer kp.signature {
    /* A segmented track that outgrows a phone wraps its labels between words instead of scrolling a label under the
       edge: the columns keep the longest word and share the rest. */
    @media (max-width: 30rem) {
        [data-theme='synthwave'] .kp-segmented:not(.kp-segmented--chips):not(.kp-segmented--block) {
            grid-auto-columns: minmax(min-content, 1fr);
        }
        [data-theme='synthwave'] .kp-segmented:not(.kp-segmented--chips) > .kp-segmented__item {
            white-space: normal;
        }
        /* A two-line label breaks into two even lines ("Every" over "1 min"), never a number stranded from its unit
           ("Every 1" over "min"). */
        [data-theme='synthwave'] .kp-segmented:not(.kp-segmented--chips) .kp-segmented__label {
            text-wrap: balance;
        }
        /* A track of five or more segments (a filter with its counts) closes its tracking and padding up so it fits a phone. */
        [data-theme='synthwave'] .kp-segmented:not(.kp-segmented--chips):has(> :nth-child(5)) {
            --kp-seg-item-pad-inline: 0.375rem;
            --kp-seg-tracking: 0.02em;
        }
        [data-theme='synthwave'] .kp-segmented:not(.kp-segmented--chips):has(> :nth-child(5)) {
            --kp-seg-size: 0.6875rem;
        }
    }
    /* The weekday chips are seven equal columns: on a narrow picker the track letters close up so a day keeps room. */
    @container kp-weekdays (max-width: 22rem) {
        [data-theme='synthwave'] .kp-weekdays .kp-weekdays__chips > .kp-segmented__item {
            letter-spacing: 0;
            font-size: 0.6875rem;
        }
    }
}
/* ── end t56 ── */

/* ── t56: the small neon ring keeps its letters off the ring ── */
@layer kp.signature {
    /* The 24 px and 32 px rings leave too little inside their 2 px line for two chrome capitals: the small ring goes to 1 px (its
       glow still draws the neon) and both sizes close their letters up, so the letters stand 4 px clear of the ring. */
    [data-theme='synthwave'] .kp-idmark--sm.kp-idmark--round {
        border-width: 1px;
        font-size: calc(var(--kp-idmark-s) * 0.36);
        letter-spacing: 0;
    }
    [data-theme='synthwave'] .kp-idmark--round:not(.kp-idmark--xs, .kp-idmark--sm, .kp-idmark--lg, .kp-idmark--xl) {
        font-size: calc(var(--kp-idmark-s) * 0.37);
        letter-spacing: 0;
    }
}
/* ── end t56 ── */

/* ── t56: the foot of a code cell ── */
@layer kp.signature {
    /* The "Show all N lines" button of a code cell in a narrow cell is shrunk below its own text by the 0.16em track: the
       track tightens and the padding halves, so the words stand clear of both sides of the button. */
    [data-theme='synthwave'] .kp-code--cell .kp-code__foot .kp-button {
        letter-spacing: 0.06em;
        padding-inline: 0.5rem;
    }
}
/* ── end t56 ── */

/* ── t56: the attention band keeps its grid ── */
@layer kp.signature {
    /* The VCR symbol of a warning or failure (a pause, a stop) is the alert's ::before and so a grid item of its own: in the
       band's three column row it took the icon's column and pushed the icon, the text and the actions one column on, the
       actions under the text. The row gets a column for it. */
    [data-theme='synthwave'] .kp-attention__item:is(.kp-alert--warning, .kp-alert--destructive) {
        grid-template-columns: auto auto minmax(0, 1fr) auto;
    }
    @container kp-attention (max-width: 34rem) {
        [data-theme='synthwave'] .kp-attention__item:is(.kp-alert--warning, .kp-alert--destructive) {
            grid-template-columns: auto auto minmax(0, 1fr);
        }
    }
    /* The question card is a column of rows: the symbol would be a row of its own above the title. It stands in the card's
       top corner instead, where the title's line leaves room for it. */
    [data-theme='synthwave'] .kp-question:is(.kp-alert--warning, .kp-alert--destructive) {
        position: relative;
    }
    [data-theme='synthwave'] .kp-question:is(.kp-alert--warning, .kp-alert--destructive)::before {
        position: absolute;
        inset-block-start: 0.875rem;
        inset-inline-end: 0.875rem;
    }
}
/* ── end t56 ── */

/* ── t56: the gallery tile ── */
@layer kp.signature {
    /* A picture is a lit screen: a pink-to-cyan tube round the edge (the card's stripe), and a glow when pointed at. */
    [data-theme='synthwave'] .kp-gallery__tile:not(.kp-skeleton, [data-kp-state='error']) {
        border-radius: 0;
        border: 1px solid transparent;
        background:
            linear-gradient(var(--muted), var(--muted)) padding-box,
            linear-gradient(135deg, var(--kp-pink-text), var(--kp-core)) border-box;
    }
    [data-theme='synthwave'] .kp-gallery__tile:hover,
    [data-theme='synthwave'] .kp-gallery__tile:focus-within {
        box-shadow: 0 0 14px hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='synthwave'] .kp-gallery__caption {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        border-block-start: 1px solid var(--kp-hairline);
    }
}
/* ── end t56 ── */

/* ── t56: the conversation bubble ── */
@layer kp.signature {
    /* A message is a lit tube: theirs a cyan line down its start edge, yours a pink one down its end edge, both glowing; the
       sender in the display face's spaced capitals. */
    [data-theme='synthwave'] .kp-thread__scroll {
        border-radius: 0;
    }
    [data-theme='synthwave'] .kp-thread__bubble {
        border-radius: 0;
        border-inline-start: 3px solid var(--kp-core);
        box-shadow: -6px 0 14px -6px hsl(from var(--kp-core) h s l / 0.6);
    }
    [data-theme='synthwave'] .kp-thread__item[data-kp-dir='out'] > .kp-thread__bubble {
        border-inline-start-width: 1px;
        border-inline-end: 3px solid var(--primary);
        box-shadow: 6px 0 14px -6px hsl(from var(--primary) h s l / 0.7);
    }
    [data-theme='synthwave'] .kp-thread__sender {
        font-family: var(--theme-font-display);
        font-weight: 400;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        font-size: 0.75rem;
    }
}
/* ── end t56 ── */

/* ── t56: what has to fit a phone ── */
@layer kp.signature {
    /* The tools of a code block (Pretty, Raw, Wrap, Copy) may take a second line instead of leaving the block. */
    [data-theme='synthwave'] .kp-code__tools {
        flex-wrap: wrap;
    }
}
/* ── end t56 ── */

/* ── t56: states ── */
@layer kp.signature {
    /* A solid coral plate (a failed state, an urgent or refused question) carries its buttons as dark keys: the plate's own
       ink as the ground, a near-white tube round it. The pink frame on the coral did not read. */
    [data-theme='synthwave'] .kp-alert--destructive .kp-button:not(.kp-icon-button) {
        --kp-frame: var(--kp-core);
        --kp-glow: transparent;
        --kp-sw-cut-ink: var(--destructive-foreground);
        background: var(--destructive-foreground);
        color: var(--kp-core);
        text-shadow: none;
    }
    [data-theme='synthwave'] .kp-alert--destructive .kp-button:not(.kp-icon-button):hover {
        --kp-frame: var(--kp-pink-text);
        background: hsl(from var(--destructive-foreground) h s calc(l + 6));
    }
    [data-theme='synthwave'] .kp-alert--destructive .kp-button[aria-disabled='true'],
