        --kp-seg-thumb: var(--secondary);
        --kp-seg-thumb-ink: var(--secondary-foreground);
        --kp-seg-thumb-edge: inset 0 0 0 3px var(--border-strong);
        --kp-seg-thumb-lift: 0 0 0 0 transparent;
        --kp-chip-radius: 0;
        --kp-chip-edge: var(--border-strong);
        --kp-chip-on: var(--secondary);
        --kp-chip-on-ink: var(--secondary-foreground);
        --kp-chip-on-edge: var(--border-strong);
