/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Brutalism's own (themes/brutalism/CHARACTER.md): a tile is the slab, white in the 3 px ink line on its 6 px hard
   shadow, square (G6, G7); pointed at it is inverted, ink ground and yellow words, and nothing moves (the tiles' own
   hover pick); a press drives it onto its footprint, the shadow gone (G14); a failure is taped off, hazard stripes along
   its foot (G13); waiting is the lintel hoisted in its well (G10): a heat grid's row of cells is ONE well with one beam,
   not a well in every cell; the voice is Archivo Black shouting, Space Grotesk in bold capitals (G15). */
@layer kp.signature {
    [data-theme='brutalism'] .kp-actions {
        --kp-actions-gap: 1rem;
    }
    [data-theme='brutalism'] .kp-action {
        --kp-action-radius: 0;
        --kp-action-line: var(--kp-line);
        --kp-action-edge: var(--border-strong);
        --kp-action-edge-hover: var(--border-strong);
        --kp-action-ground: var(--card);
        --kp-action-ground-hover: var(--foreground);
        --kp-action-ground-active: var(--secondary-active, var(--secondary));
        --kp-action-shadow: var(--kp-shadow);
        --kp-action-shadow-hover: var(--kp-shadow);
        --kp-action-shadow-active: 0 0 0 0 transparent;
        --kp-action-press: var(--kp-drop) var(--kp-drop);
        --kp-action-title-font: var(--theme-font-display);
        --kp-action-title-case: uppercase;
        --kp-action-title-tracking: -0.01em;
        --kp-action-title-weight: 400;
    }
    [data-theme='brutalism'] .kp-action__meta {
        font-family: var(--theme-font-mono);
    }
    /* Pointed at: inverted; the words and the chevron go yellow on the ink. */
    [data-theme='brutalism'] .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'], :active)) {
        color: var(--secondary);
    }
    [data-theme='brutalism']
        .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'], :active))
        :is(.kp-action__title, .kp-action__text, .kp-action__meta, .kp-action__mark) {
        color: var(--secondary);
    }
    [data-theme='brutalism'] .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        color: var(--kp-plate-ink, var(--secondary-foreground));
    }
    /* Focus: the two-channel ring, the slab lifted off its footprint as under the hand. */
    [data-theme='brutalism'] .kp-action:focus-visible:not(:active) {
        outline: 3px solid var(--focus-ring);
        outline-offset: 3px;
        translate: -2px -2px;
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring-contrast),
            calc(var(--kp-drop) + 2px) calc(var(--kp-drop) + 2px) 0 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-action:is(:disabled, [aria-disabled='true']) {
        border-color: var(--border-strong);
        box-shadow: none;
    }
    /* Destructive: taped off, the hazard stripes along its foot in the red and the ink; the title in the red. */
    [data-theme='brutalism'] .kp-action--destructive {
        --kp-action-tone-edge: var(--border-strong);
        --kp-action-tone-edge-hover: var(--border-strong);
        padding-block-end: calc(0.625rem + 0.5rem);
    }
    [data-theme='brutalism'] .kp-action--destructive::after {
        inset: auto 0 0;
        inline-size: auto;
        block-size: 0.5rem;
        border-radius: 0;
        background: repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px);
    }
    [data-theme='brutalism'] .kp-action--destructive:is(:disabled, [aria-disabled='true'])::after {
        background: repeating-linear-gradient(45deg, var(--muted) 0 6px, var(--border-strong) 6px 12px);
    }
    [data-theme='brutalism'] .kp-action--destructive:not(:hover, :disabled, [aria-disabled='true']) > .kp-action__title {
        color: var(--destructive);
    }

    /* Status rows: slabs on their hard shadow, square marks with a heavy ring; a failed row is taped off along its foot;
       a loading row takes the muted ground. */
    [data-theme='brutalism'] .kp-statuslist {
        --kp-statuslist-gap: 0.75rem;
        --kp-statusrow-mark-radius: 0;
    }
    [data-theme='brutalism'] .kp-statusrow {
        --kp-statusrow-line: var(--kp-line);
        --kp-statusrow-edge: var(--border-strong);
        --kp-statusrow-radius: 0;
        box-shadow: var(--kp-shadow);
    }
    [data-theme='brutalism'] .kp-statusrow__mark {
        border-width: var(--kp-line);
    }
    [data-theme='brutalism'] .kp-statusrow__label {
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-statusrow[data-state='loading'] {
        --kp-statusrow-ground: var(--muted);
    }
    [data-theme='brutalism'] .kp-statusrow[data-state='failed'] {
        --kp-statusrow-state-edge: var(--border-strong);
        padding-block-end: calc(0.5rem + 0.5rem);
        background:
            repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px) 0 100% / 100% 0.5rem no-repeat,
            var(--card);
    }
    [data-theme='brutalism'] .kp-statusrow[data-state='empty'] {
        border-style: dashed;
        box-shadow: none;
    }

    /* Facets: square rows; a row under the hand is the yellow plate in the ink; the title shouts. The counts on their
       way are wells in the ink line, the lintel hoisted in each. */
    [data-theme='brutalism'] .kp-facets {
        --kp-facet-radius: 0;
    }
    [data-theme='brutalism'] .kp-facet {
        --kp-facet-hover: var(--secondary);
    }
    [data-theme='brutalism'] .kp-facet:hover {
        color: var(--secondary-foreground);
        box-shadow: inset 0 0 0 2px var(--border-strong);
    }
    [data-theme='brutalism'] .kp-facets__title {
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-facets[aria-busy='true'] .kp-facet__count {
        box-sizing: border-box;
        border: 2px solid var(--border-strong);
        border-block-end: 0;
        border-radius: 0;
        background-color: var(--card);
        background-image: var(--kp-sig-br-lintel);
        background-size: var(--kp-sig-br-lintel-size);
        background-position-x: 50%, 21%, 79%;
        background-position-y: 100%;
        background-repeat: no-repeat;
        animation: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] .kp-facets[aria-busy='true'] .kp-facet__count {
            animation: kp-sig-brutalism-hoist var(--kp-sig-br-loop) linear infinite backwards;
        }
        [data-theme='brutalism'] .kp-facets[aria-busy='true'] li:nth-child(2n) .kp-facet__count {
            animation-delay: 200ms;
        }
    }

    /* Heat grid and matrix: small slabs framed in ink on a hard shadow; pointing lifts a cell up-left off its
       footprint (the shadow stays on the ground), a press drives it onto it; the pick is the fat frame. Waiting, a heat
       row is one well and one beam hoisted in it; a matrix cell is its own well. */
    [data-theme='brutalism'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-radius: 0;
        --kp-heat-cell-edge: 2px;
        --kp-heat-cell-ink: var(--foreground);
        --kp-heat-cell-gap: 4px;
        --kp-heat-cell-lift: 2px 2px 0 var(--foreground);
        --kp-heat-cell-hover: translate(-1px, -1px);
        --kp-matrix-cell-hover: translate(-2px, -2px);
    }
    [data-theme='brutalism'] .kp-heat {
        --kp-heat-gap-y: 6px;
    }
    [data-theme='brutalism'] .kp-matrix {
        --kp-matrix-gap: 6px;
    }
    @media (max-width: 40rem) {
        [data-theme='brutalism'] .kp-heat {
            --kp-heat-cell-edge: 1px;
            --kp-heat-cell-gap: 2px;
            --kp-heat-cell-lift: 1px 1px 0 var(--foreground);
        }
    }
    [data-theme='brutalism'] .kp-heat__cell:hover:not(.kp-skeleton, [aria-disabled='true']) {
        box-shadow: 3px 3px 0 var(--foreground);
    }
    [data-theme='brutalism'] .kp-heat__cell:active:not(.kp-skeleton, [aria-disabled='true']) {
        transform: translate(2px, 2px);
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-heat__cell:is([data-kp-tone='future'], [data-kp-tone='none'], [data-kp-tone='before']) {
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-heat__cell[data-kp-picked],
    [data-theme='brutalism'] .kp-matrix__cell[aria-pressed='true'] {
        outline: 4px solid var(--foreground);
        outline-offset: 0;
        z-index: 1;
    }
    [data-theme='brutalism'] :is(.kp-heat__label, .kp-matrix__name) {
        text-transform: uppercase;
        font-weight: 700;
        letter-spacing: 0.04em;
    }
    [data-theme='brutalism'] .kp-matrix__cell {
        border: 2px solid var(--foreground);
        box-shadow: 3px 3px 0 var(--foreground);
        color: var(--foreground);
    }
    [data-theme='brutalism'] .kp-matrix__cell:hover:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
        box-shadow: 5px 5px 0 var(--foreground);
    }
    [data-theme='brutalism'] .kp-matrix__cell:is([data-kp-tone='self'], [data-kp-tone='none'], [data-kp-inert]) {
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-heat__label-button[aria-pressed='true'] {
        background: var(--secondary);
        color: var(--secondary-foreground);
        box-shadow: 3px 3px 0 var(--foreground);
    }
    [data-theme='brutalism'] .kp-heat__cell.kp-skeleton {
        visibility: hidden;
    }
    [data-theme='brutalism'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton) {
        box-shadow:
            inset 0 0 0 2px var(--border-strong),
            3px 3px 0 var(--border-strong);
        background-color: var(--card);
        background-image: var(--kp-sig-br-lintel);
        background-size: var(--kp-sig-br-lintel-size);
        background-position-x: 50%, 21%, 79%;
        background-position-y: 100%;
        background-repeat: no-repeat;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton) {
            animation: kp-sig-brutalism-hoist var(--kp-sig-br-loop) linear infinite backwards;
        }
        [data-theme='brutalism'] .kp-heat__row:nth-child(2n) .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton) {
            animation-delay: 200ms;
        }
    }
    /* A phone's timeline keeps its toolbar on one row: the range steps close in, in these wide capitals. */
    @container kp-gantt (max-width: 22rem) {
        [data-theme='brutalism'] .kp-gantt__ranges {
            --kp-seg-item-pad-inline: 0.375rem;
        }
    }
    [data-theme='brutalism'] .kp-bar-cell {
        --kp-bar-cell-gap: var(--kp-space-sm, 0.5rem);
        font-variant-numeric: tabular-nums;
    }

    /* Week agenda and run timeline: black boxes, a 2 px ink frame on a hard shadow, no radius; pointing lifts a pill
       up-left off its footprint, a press drives it in; heavy capitals for the days and the axis. A running run is the
       lavender plate with the yellow tip at its growing head; nothing glides. */
    [data-theme='brutalism'] .kp-week {
        --kp-week-pill-radius: 0;
        --kp-week-now: var(--foreground);
    }
    [data-theme='brutalism'] .kp-gantt {
        --kp-gantt-bar-radius: 0;
        --kp-gantt-row: 2rem;
        --kp-gantt-bar: 1.25rem;
        --kp-gantt-bar-failed: 1.625rem;
        --kp-gantt-now: var(--foreground);
        --kp-gantt-state-ground: var(--card);
    }
    [data-theme='brutalism'] :is(.kp-week__pill, .kp-gantt__run) {
        border: 2px solid var(--foreground);
        box-shadow: 2px 2px 0 var(--foreground);
    }
    [data-theme='brutalism'] :is(.kp-week__pill, .kp-gantt__run):is(button):hover {
        translate: -1px -1px;
        box-shadow: 3px 3px 0 var(--foreground);
    }
    [data-theme='brutalism'] :is(.kp-week__pill, .kp-gantt__run):is(button):active {
        translate: 2px 2px;
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-week__pill[data-kp-state='next'] {
        background: var(--secondary);
        color: var(--secondary-foreground);
    }
    [data-theme='brutalism'] .kp-week__pill:is([data-kp-state='reference'], [data-kp-state='off'], [data-kp-state='skipped']) {
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-week__now::before {
        border-radius: 0;
    }
    [data-theme='brutalism'] :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='running'] {
        --kp-gantt-fill: var(--accent);
        --kp-gantt-ink: var(--accent-foreground);
        background-image: none;
        box-shadow:
            inset -0.5rem 0 0 var(--secondary),
            2px 2px 0 var(--foreground);
    }
    [data-theme='brutalism'] .kp-gantt__run[data-kp-state='running'] {
        animation: none;
    }
    [data-theme='brutalism'] .kp-gantt__run[data-kp-state='queued'] {
        border-style: dashed;
        box-shadow: none;
    }
    [data-theme='brutalism'] :is(.kp-week__col, .kp-gantt__rule) {
        border-inline-start-color: var(--foreground);
    }
    [data-theme='brutalism'] :is(.kp-week__head, .kp-gantt__tick, .kp-gantt__lane) {
        font-weight: 800;
        text-transform: uppercase;
        letter-spacing: 0.05em;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] :is(.kp-week__pill, .kp-gantt__run, .kp-heat__cell, .kp-matrix__cell) {
            transition:
                translate var(--fx-duration) var(--kp-sig-br-fall),
                transform var(--fx-duration) var(--kp-sig-br-fall),
                box-shadow var(--fx-duration) var(--kp-sig-br-fall);
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='brutalism'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='brutalism'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='brutalism'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='brutalism'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='brutalism'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='brutalism'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Brutalism's own (themes/brutalism/CHARACTER.md): the separator is a slab of ink as tall as a link;
   lying down across the phone's list it is the divider's hazard band, the yellow hatch on the ink between two ink
   rules. A day on the axis is kicked: pointing lifts it up-left off its hard shadow inside an ink frame, pressed it is
   driven in, the yellow block in the ink frame (as the current page). The upcoming list's day rule is a 2 px ink line;
   the facet pattern is boxed in ink on a hard shadow. */
@layer kp.signature {
    [data-theme='brutalism'] .kp-nav__sep {
        inline-size: 4px;
        border-inline-start: 0;
        background: var(--foreground);
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='brutalism'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            box-sizing: border-box;
            inline-size: auto;
            block-size: 12px;
            border-block: 2px solid var(--foreground);
            background: var(--kp-hatch), var(--foreground);
        }
    }

    [data-theme='brutalism'] .kp-gantt__tick:is(button) {
        border-radius: 0;
        text-decoration: none;
    }
    [data-theme='brutalism'] .kp-gantt__tick:is(button):hover {
        background: var(--card);
        color: var(--foreground);
        box-shadow:
            inset 0 0 0 2px var(--foreground),
            2px 2px 0 var(--foreground);
        translate: -2px -2px;
    }
    [data-theme='brutalism'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: var(--secondary);
        color: var(--secondary-foreground);
        box-shadow: inset 0 0 0 2px var(--foreground);
        translate: 0 0;
    }
    [data-theme='brutalism'] .kp-week__next {
        border-block-end-width: 2px;
    }
    [data-theme='brutalism'] .kp-week__next:not(:has(+ .kp-week__next:not([data-kp-day-start]))) {
        border-block-end-color: var(--foreground);
    }
    [data-theme='brutalism'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 0;
        box-shadow:
            inset 0 0 0 2px var(--foreground),
            2px 2px 0 var(--foreground);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] .kp-gantt__tick:is(button) {
            transition:
                translate var(--fx-duration) var(--kp-sig-br-fall, var(--fx-ease)),
                box-shadow var(--fx-duration) var(--kp-sig-br-fall, var(--fx-ease));
        }
    }
}

/* ── The kpadopt4 data pieces, in this theme [kpadopt4] ──
   Brutalism's own (themes/brutalism/CHARACTER.md): a mark is paint under black ink in the ink line on its small hard
   shadow, square (G5, G6, G7); a part under the hand is lifted up-left off its footprint while its shadow stays on the
   ground (G8); a warning is taped off, hazard stripes along its foot (G13); a number that changes is slammed onto its
   yellow offset (G9); a bolt is square and has its own small shadow (G16); the voice is Archivo Black shouting and Space
   Grotesk speaking in bold capitals, the machine's words in mono (G15). */
@layer kp.signature {
    /* The identity mark: flat paint, never a tint, the letters in Archivo Black; the round mark is the same square with
       a second frame stamped inside it; the pick is the fat frame. */
    [data-theme='brutalism'] .kp-idmark {
        --kp-idmark-radius: 0;
        border: 2px solid var(--border-strong);
        background: var(--kp-idmark-c);
        box-shadow: 2px 2px 0 var(--border-strong);
        color: var(--border-strong);
        font-family: var(--theme-font-display);
        font-size: calc(var(--kp-idmark-s) * 0.42);
        font-weight: 400;
        letter-spacing: -0.02em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-idmark--xs {
        border-width: 1px;
        box-shadow: 1px 1px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-idmark--round {
        border-radius: 0;
        outline: 2px solid var(--border-strong);
        outline-offset: -5px;
    }
    [data-theme='brutalism'] .kp-idmark--xs.kp-idmark--round {
        outline: 0;
    }
    [data-theme='brutalism'] .kp-idmark--pattern {
        --kp-idmark-ink: var(--border-strong);
    }
    [data-theme='brutalism'] .kp-idmark--glyph::after {
        border-radius: 0;
        background: var(--secondary);
        box-shadow: 0 0 0 1.5px var(--border-strong);
    }
    [data-theme='brutalism'] .kp-idmark--glyph[data-kp-idmark-glyph='circle']::after {
        border-radius: 0;
    }
    [data-theme='brutalism'] .kp-idmark--glyph[data-kp-idmark-glyph='triangle']::after {
        box-shadow: none;
        background: var(--border-strong);
    }
    [data-theme='brutalism'] .kp-idmark[data-kp-idmark-empty] {
        border-style: dashed;
        background: var(--muted);
        box-shadow: none;
        color: var(--border-strong);
    }
    [data-theme='brutalism'] .kp-idmark[aria-current]:not([aria-current='false']),
    [data-theme='brutalism'] .kp-idmark[data-kp-idmark-selected] {
        outline: 4px solid var(--border-strong);
        outline-offset: 1px;
        box-shadow: 2px 2px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-idmark--round[aria-current]:not([aria-current='false']),
    [data-theme='brutalism'] .kp-idmark--round[data-kp-idmark-selected] {
        outline: 4px solid var(--border-strong);
        outline-offset: 1px;
    }
    [data-theme='brutalism'] .kp-idmark-group > .kp-idmark,
    [data-theme='brutalism'] .kp-idmark-group > .kp-idmark-group__more {
        box-shadow: 2px 2px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-idmark-group__more {
        --kp-idmark-radius: 0;
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        color: var(--border-strong);
        font-family: var(--theme-font-display);
    }

    /* The share bar: a rule printed in the ink line on its hard shadow, the parts flat paint set apart by ink, the
       threshold a block standing out of it, the legend's swatches square bolts. */
    [data-theme='brutalism'] .kp-stackbar {
        --kp-stackbar-radius: 0;
        --kp-stackbar-gap: 3px;
    }
    [data-theme='brutalism'] .kp-stackbar__title {
        font-family: var(--theme-font-display);
        font-weight: 400;
        letter-spacing: -0.01em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-stackbar__total {
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-stackbar__bar {
        box-sizing: border-box;
        border: 3px solid var(--border-strong);
        background: var(--card);
        box-shadow: 4px 4px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-stackbar__seg {
        box-shadow: inset calc(var(--kp-stackbar-gap, 3px) * -1) 0 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-stackbar__seg:dir(rtl) {
        box-shadow: inset var(--kp-stackbar-gap, 3px) 0 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-stackbar__seg[data-kp-stackbar-hatch],
    [data-theme='brutalism'] .kp-stackbar__swatch[data-kp-stackbar-hatch] {
        background-image: repeating-linear-gradient(-45deg, transparent 0 3px, var(--border-strong) 3px 5px);
    }
    [data-theme='brutalism'] .kp-stackbar__seg[data-kp-stackbar-lit] {
        translate: -2px -2px;
        box-shadow:
            inset calc(var(--kp-stackbar-gap, 3px) * -1) 0 0 var(--border-strong),
            3px 3px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-stackbar__bar[data-kp-stackbar-full] .kp-stackbar__seg:last-of-type {
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-stackbar__mark {
        inset-block: -0.5rem;
        inline-size: 6px;
        margin-inline-start: -2px;
        background: var(--border-strong);
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-stackbar__bar[data-kp-over]::after {
        content: '\25B6';
        color: var(--destructive);
        text-shadow: 1px 1px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-stackbar__item {
        border-radius: 0;
        border: 2px solid transparent;
    }
    [data-theme='brutalism'] .kp-stackbar__item[data-kp-stackbar-lit] {
        border-color: var(--border-strong);
        background: var(--secondary);
        color: var(--secondary-foreground);
        box-shadow: 3px 3px 0 var(--border-strong);
        translate: -1px -1px;
    }
    [data-theme='brutalism'] .kp-stackbar__item[data-kp-stackbar-lit] .kp-stackbar__value {
        color: inherit;
    }
    [data-theme='brutalism'] .kp-stackbar__swatch {
        box-sizing: border-box;
        border: 2px solid var(--border-strong);
        border-radius: 0;
        box-shadow: 2px 2px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-stackbar__item[data-kp-stackbar-rest] .kp-stackbar__swatch {
        background: var(--card);
        box-shadow: 2px 2px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-stackbar__label {
        font-weight: 700;
        letter-spacing: 0.02em;
    }
    [data-theme='brutalism'] .kp-stackbar__value {
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-stackbar__item[data-kp-stackbar-over] .kp-stackbar__value {
        padding-inline: 0.35em;
        background: var(--destructive);
        color: var(--destructive-foreground);
    }
    [data-theme='brutalism'] .kp-stackbar__note,
    [data-theme='brutalism'] .kp-bullets[data-kp-state='error'] .kp-bullets__note {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: var(--kp-shadow);
        color: var(--foreground);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-stackbar[data-kp-state='error'] .kp-stackbar__note {
        padding-block-end: calc(var(--kp-space-sm, 0.5rem) + 0.5rem);
        background:
            repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px) 0 100% / 100% 0.5rem no-repeat,
            var(--card);
    }

    /* Bullet rows: the row under the hand is lifted off its footprint, yellow, named by its label; a figure's tone is
       paint in the ink line (paper on red). */
    [data-theme='brutalism'] .kp-bullets__row {
        border-radius: 0;
        border: 2px solid transparent;
    }
    [data-theme='brutalism'] .kp-bullets__row:has(.kp-bullets__link:hover) {
        border-color: var(--border-strong);
        background: var(--secondary);
        color: var(--secondary-foreground);
        box-shadow: 4px 4px 0 var(--border-strong);
        translate: -2px -2px;
    }
    [data-theme='brutalism'] .kp-bullets__row:has(.kp-bullets__link:active) {
        translate: 0 0;
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-bullets__row:has(.kp-bullets__link:hover) .kp-bullets__label {
        text-decoration: none;
    }
    [data-theme='brutalism'] .kp-bullets__row:has(.kp-bullets__link:hover) .kp-bullets__detail {
        color: inherit;
    }
    [data-theme='brutalism'] .kp-bullets__label {
        font-weight: 700;
        letter-spacing: 0.02em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-bullets__detail {
        font-family: var(--theme-font-mono);
    }
    [data-theme='brutalism'] .kp-bullets__figure {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }
    [data-theme='brutalism'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure,
    [data-theme='brutalism'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        box-shadow: 2px 2px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure {
        background: var(--warning);
        color: var(--border-strong);
    }

    /* The key-value grid: the keys in bold capitals, the lines ink, a changed row marked by a block, a failed row taped
       off along its foot. */
    [data-theme='brutalism'] .kp-kv__row > dt {
        color: var(--foreground);
        font-size: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-kv__row > dd {
        font-weight: 500;
    }
    [data-theme='brutalism'] .kp-kv--lines > .kp-kv__row {
        border-block-end: 2px solid var(--border-strong);
    }
    [data-theme='brutalism'] .kp-kv {
        --kp-glyph-changed: '\00a0\25A0';
    }
    [data-theme='brutalism'] .kp-kv__row[data-kp-changed] > dt::after {
        color: var(--foreground);
        text-shadow: 1px 1px 0 var(--secondary);
    }
    [data-theme='brutalism'] .kp-kv__row[data-kp-state='error'] {
        padding-block-end: 0.5rem;
        background: repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px) 0 100% / 100% 0.375rem no-repeat;
    }
    [data-theme='brutalism'] .kp-kv__row[data-kp-state='error']::before {
        content: none;
    }

    /* Form rows: the label in bold capitals; a row changed and not saved has the yellow block along its start edge in
       the ink line; a row in error is taped off along that edge. */
    [data-theme='brutalism'] .kp-formrow__label {
        font-size: 0.8125rem;
        font-weight: 700;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-formrow__label > small {
        font-weight: 500;
        letter-spacing: 0;
        text-transform: none;
    }
    [data-theme='brutalism'] .kp-formrow[data-kp-changed]::before,
    [data-theme='brutalism'] .kp-formrow[data-kp-state='error']::before {
        inline-size: 8px;
        inset-inline-start: calc(var(--kp-space-sm, 0.5rem) * -1 - 4px);
        background: var(--secondary);
        box-shadow: 0 0 0 2px var(--border-strong);
    }
    [data-theme='brutalism'] .kp-formrow[data-kp-state='error']::before {
        background: repeating-linear-gradient(45deg, var(--destructive) 0 4px, var(--border-strong) 4px 8px);
    }
    [data-theme='brutalism'] .kp-formrows--lines > .kp-formrow {
        border-block-end: 2px solid var(--border-strong);
    }
    [data-theme='brutalism'] .kp-formrow__lock::before {
        border-radius: 0;
        border-width: 2px;
    }

    /* The code block: a slab with a yellow head like the dialog's band; keys are marked in lavender paint, the second
       sheet; a failed read is taped off. */
    [data-theme='brutalism'] .kp-code {
        --kp-code-key: var(--foreground);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: var(--kp-shadow);
    }
    [data-theme='brutalism'] .kp-code__head {
        border-block-end: var(--kp-line) solid var(--border-strong);
        background: var(--secondary);
        color: var(--secondary-foreground);
    }
    [data-theme='brutalism'] .kp-code__title {
        font-family: var(--theme-font-display);
        font-weight: 400;
        letter-spacing: -0.01em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-code__meta {
        color: inherit;
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-code__body,
    [data-theme='brutalism'] .kp-code__note {
        border-radius: 0;
    }
    [data-theme='brutalism'] .kp-code__key {
        padding-inline: 0.15em;
        background: var(--accent);
        color: var(--accent-foreground, var(--foreground));
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-code__foot {
        border-block-start: 2px solid var(--border-strong);
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-code[data-kp-state='error'] .kp-code__note {
        padding-block-end: calc(var(--kp-space-md, 0.75rem) + 0.5rem);
        background:
            repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px) 0 100% / 100% 0.5rem no-repeat,
            var(--muted);
    }

    /* The header line. */
    [data-theme='brutalism'] .kp-page-header__line > .kp-page-header__title {
        font-family: var(--theme-font-display);
        font-weight: 400;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-page-header__meta {
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }

    /* A number that ticks lands on its yellow offset, 3 px down-right of itself, and the offset is struck off in one cut
       when the count ends (G9). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] [data-kp-tick][data-kp-tick-state='running'] {
            filter: drop-shadow(3px 3px 0 var(--secondary));
        }
    }
}

/* ── The uptime strip, rows, checks, choices, a card's four states and the drawings, in this theme [kpadopt4-rows] ──
   A cell of the strip is a small block of paint in its ink line (up, degraded and down are the statuses' paint and the
   stripes they already carry); pointing lifts it up-left off its footprint (G8). A row says its state in a bar of paint
   along its start edge, a failed one taped off, the next one up the yellow slab (G5, G13). A tile of choices is a
   slab: pointing lifts it, the pick is yellow (G5, G8). Waiting is the lintel hoisted in its well (G10): the strip
   is one well, not a well in every cell. The drawings are set down one after another and stop dead (G1, G3). */
@layer kp.signature {
    [data-theme='brutalism'] .kp-uptime {
        --kp-uptime-cell-radius: 0;
        --kp-uptime-up: var(--success);
        --kp-uptime-degraded: var(--warning);
        --kp-uptime-down: var(--destructive);
    }
    [data-theme='brutalism'] .kp-uptime__title {
        font-family: var(--theme-font-display);
        font-weight: 400;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-uptime__percent {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }
    [data-theme='brutalism'] .kp-uptime__summary {
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-uptime__summary[data-kp-tone='error'] {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        box-shadow: 2px 2px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-uptime__cell:not(.kp-skeleton) {
        border: 0;
        border-radius: 0;
        box-shadow: inset 0 0 0 1px var(--border-strong);
    }
    [data-theme='brutalism'] .kp-uptime__cell[data-kp-tone='none']:not(.kp-skeleton) {
        background: var(--card);
    }
    [data-theme='brutalism'] .kp-uptime__cell:is(:hover, :focus-visible, [aria-expanded='true']):not(.kp-skeleton) {
        translate: -1px 0;
        box-shadow:
            inset 0 0 0 1px var(--border-strong),
            2px 2px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-uptime__axis {
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-uptime__info-title {
        font-family: var(--theme-font-display);
        font-weight: 400;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-uptime__swatch {
        border: 0;
        border-radius: 0;
        box-shadow: inset 0 0 0 1px var(--border-strong);
    }
    [data-theme='brutalism'] .kp-uptime__cell.kp-skeleton {
        visibility: hidden;
    }
    [data-theme='brutalism'] .kp-uptime__track:has(> .kp-skeleton) {
        position: relative;
        box-sizing: border-box;
        box-shadow:
            inset 0 0 0 2px var(--border-strong),
            3px 3px 0 var(--border-strong);
        background-color: var(--card);
        background-image: var(--kp-sig-br-lintel);
        background-size: var(--kp-sig-br-lintel-size);
        background-position-x: 50%, 21%, 79%;
        background-position-y: 100%;
        background-repeat: no-repeat;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] .kp-uptime__track:has(> .kp-skeleton) {
            animation: kp-sig-brutalism-hoist var(--kp-sig-br-loop) linear infinite backwards;
        }
        [data-theme='brutalism'] .kp-uptime__cell {
            transition: none;
        }
    }

    /* Rows with a lead. */
    [data-theme='brutalism'] .kp-action-list--lead {
        --kp-action-list-bar: 8px;
        --kp-action-list-next-wash: 0%;
    }
    [data-theme='brutalism'] .kp-action-list--lead > li {
        border-block-end: 2px solid var(--border-strong);
        border-inline-start-color: transparent;
    }
    [data-theme='brutalism'] .kp-action-list--lead > li[data-kp-state='new'] {
        border-inline-start-color: var(--border-strong);
    }
    [data-theme='brutalism'] .kp-action-list--lead > li[data-kp-state='active'] {
        border-inline-start-color: var(--accent);
        box-shadow: inset 2px 0 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-action-list--lead > li[data-kp-state='warn'] {
        border-inline-start-color: var(--warning);
        box-shadow: inset 2px 0 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-action-list--lead > li[data-kp-state='failed'] {
        background: repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px) 0 0 / 8px 100% no-repeat;
    }
    [data-theme='brutalism'] .kp-action-list--lead > li[data-kp-state='failed']:dir(rtl) {
        background-position: 100% 0;
    }
    [data-theme='brutalism'] .kp-action-list--lead > li[data-kp-state='next'] {
        border-inline-start-color: var(--border-strong);
        background: var(--secondary);
        color: var(--secondary-foreground);
        box-shadow: inset 0 0 0 3px var(--border-strong);
    }
    [data-theme='brutalism']
        .kp-action-list--lead
        > li[data-kp-state='next']
        :is(.kp-action-list__lead, .kp-action-list__text, .kp-action-list__meta) {
        color: inherit;
    }
    [data-theme='brutalism'] .kp-action-list__title {
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-action-list--lead > li:is([data-kp-state='done'], [data-kp-state='past']) .kp-action-list__title {
        font-weight: 500;
    }
    [data-theme='brutalism'] .kp-action-list__meta {
        font-family: var(--theme-font-mono);
        font-weight: 500;
    }
    [data-theme='brutalism'] .kp-action-list__when > :first-child {
        font-family: var(--theme-font-display);
        font-weight: 400;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-action-list > li.kp-action-list__group {
        padding-inline-start: var(--kp-space-sm, 0.5rem);
        border-block-end: var(--kp-line) solid var(--border-strong);
        color: var(--foreground);
        font-family: var(--theme-font-display);
        font-size: 0.875rem;
        font-weight: 400;
        letter-spacing: 0.04em;
    }
    [data-theme='brutalism'] .kp-action-list__payload {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        box-shadow: 3px 3px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-action-list__more > summary {
        color: var(--foreground);
        font-weight: 700;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-action-list__more > summary:hover {
        background: var(--secondary);
        color: var(--secondary-foreground);
    }
    [data-theme='brutalism'] [data-kp-row-keys] > li:focus-visible {
        outline-width: 3px;
        outline-offset: -3px;
    }

    /* A check with a reservation: the mark in warning paint, a band of tape in that paint along the foot. */
    [data-theme='brutalism'] .kp-statusrow[data-state='warn'] {
        --kp-statusrow-state-edge: var(--border-strong);
        padding-block-end: calc(0.5rem + 0.5rem);
        background:
            repeating-linear-gradient(45deg, var(--warning) 0 6px, var(--border-strong) 6px 12px) 0 100% / 100% 0.5rem no-repeat,
            var(--card);
    }
    [data-theme='brutalism'] .kp-statusrow[data-state='warn'] .kp-statusrow__mark {
        border-color: var(--border-strong);
        background: var(--warning);
        color: var(--border-strong);
    }
    [data-theme='brutalism'] .kp-statusrow__fix {
        font-weight: 700;
    }

    /* Choices as tiles: slabs; pointing lifts one up-left off its footprint; the pick is yellow. */
    [data-theme='brutalism'] .kp-fieldset[data-kp-layout='tiles'] {
        --kp-field-tile-radius: 0;
        --kp-field-tiles-gap: 1rem;
    }
    [data-theme='brutalism'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
        border: var(--kp-line) solid var(--border-strong);
        background: var(--card);
        box-shadow: 4px 4px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-field__option-title {
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-field__option-hint {
        font-weight: 500;
    }
    [data-theme='brutalism'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:hover:not(:has(> .kp-field__check:disabled)) {
        border-color: var(--border-strong);
        translate: -2px -2px;
        box-shadow: 6px 6px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:active:not(:has(> .kp-field__check:disabled)) {
        translate: 4px 4px;
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:checked) {
        border-color: var(--border-strong);
        background: var(--secondary);
        color: var(--secondary-foreground);
        box-shadow: 4px 4px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:checked) .kp-field__option-hint {
        color: inherit;
    }
    [data-theme='brutalism'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:disabled) {
        border-style: dashed;
        background: var(--muted);
        box-shadow: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
            transition:
                translate var(--fx-duration) var(--kp-sig-br-fall),
                box-shadow var(--fx-duration) var(--kp-sig-br-fall);
        }
    }

    /* A card in four data states: the failure is taped off along its foot; the data that returns is set down. */
    [data-theme='brutalism'] .kp-card__state-title {
        font-family: var(--theme-font-display);
        font-weight: 400;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-card[data-kp-state='error'] > .kp-card__stage > .kp-card__state .kp-card__failure {
        padding-block-end: calc(var(--kp-space-md, 0.75rem) + 0.5rem);
        background:
            repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px) 0 100% / 100% 0.5rem no-repeat,
            var(--card);
        /* The plate is the white slab; the package's cream destructive-foreground left "why" unreadable on it. */
        color: var(--foreground);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] .kp-card[data-kp-state='ready'] > .kp-card__stage > .kp-card__data {
            animation: kp-sig-brutalism-k4-fall var(--kp-sig-br-time) var(--kp-sig-br-fall) both;
        }
    }
    @keyframes kp-sig-brutalism-k4-fall {
        from {
            translate: -0.75rem -0.75rem;
            opacity: 0;
        }
        1% {
            opacity: 1;
        }
        to {
            translate: 0 0;
            opacity: 1;
        }
    }

    /* The drawings: the slab's set. Heavy strokes, square ends; each is set down from up-left and stops dead, one
       after another, 100 ms apart. */
    [data-theme='brutalism'] .kp-empty[data-kp-art]::before {
        display: none;
    }
    [data-theme='brutalism'] .kp-art {
        display: block;
        --kp-art-stroke: 3px;
        --kp-art-rule: var(--foreground);
        --kp-art-line: var(--foreground);
        --kp-art-ink: var(--foreground);
        --kp-art-red: var(--destructive);
    }
    [data-theme='brutalism'] .kp-art > g[data-kp-art-set='slab'] {
        display: inline;
    }
    [data-theme='brutalism'] .kp-art path {
        stroke-linecap: butt;
        stroke-linejoin: miter;
    }
    [data-theme='brutalism'] .kp-art path.kp-art__line {
        stroke-width: 2px;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] .kp-art path {
            animation: kp-sig-brutalism-art-set var(--kp-sig-br-time) var(--kp-sig-br-fall) both;
            animation-delay: calc(var(--kp-art-i, 0) * 100ms);
        }
    }
    @keyframes kp-sig-brutalism-art-set {
        from {
            translate: -10px -10px;
            opacity: 0;
        }
        1% {
            opacity: 1;
        }
        to {
            translate: 0 0;
            opacity: 1;
        }
    }
}

/* ── Flows and records, in this theme [kpadopt4-flows] ──
   A secret printed on the page is slammed onto its yellow offset when it is shown, and its time runs out in ten hard
   steps of a six-pixel bar (G9, G11, G16); a dialog's sections are ruled off in the ink line, the danger section taped
   off (G13); a moment on the timeline is a square bolt with its own small shadow, a stretch in warning is hazard tape
   (G16); a journey is a path of blocks, the one it stands at lifted off its footprint; the pipeline's lanes and cards
   are slabs, pointing lifts a card up-left off its footprint (G7, G8). */
@layer kp.signature {
    [data-theme='brutalism'] .kp-secret {
        --kp-secret-drain: var(--border-strong);
        --kp-secret-drain-size: 6px;
    }
    [data-theme='brutalism'] .kp-secret__value {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: 3px 3px 0 var(--border-strong);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__value {
        background: var(--accent);
        color: var(--accent-foreground, var(--foreground));
    }
    [data-theme='brutalism'] .kp-secret[data-kp-secret-state='disabled'] .kp-secret__value {
        background: var(--muted);
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-secret__line {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-secret__drain {
        border-radius: 0;
    }
    [data-theme='brutalism'] .kp-secret[data-kp-secret-state='error'] .kp-secret__words {
        padding: 0 0 0.5rem;
        border-inline-start: 0;
        background: repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px) 0 100% / 100% 0.375rem no-repeat;
        font-weight: 700;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism']
            .kp-secret:not([data-kp-secret-ttl='0'], [data-kp-secret-reveal-on='hold'])[data-kp-secret-state='shown']
            .kp-secret__drain {
            animation-timing-function: steps(10, jump-end);
        }
        [data-theme='brutalism'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__text {
            display: inline-block;
            animation: kp-sig-brutalism-secret-slam calc(var(--kp-sig-br-time) + 12 * 100ms) linear both;
        }
    }
    @keyframes kp-sig-brutalism-secret-slam {
        0% {
            translate: -6px -6px;
            filter: drop-shadow(9px 9px 0 var(--border-strong));
            animation-timing-function: var(--kp-sig-br-fall);
        }
        20%,
        99.9% {
            translate: 0 0;
            filter: drop-shadow(3px 3px 0 var(--border-strong));
        }
        100% {
            translate: 0 0;
            filter: none;
        }
    }

    /* The dialog in sections. */
    [data-theme='brutalism'] .kp-dialog__section {
        border-block-start: var(--kp-line) solid var(--border-strong);
    }
    [data-theme='brutalism'] .kp-dialog__section:first-child {
        border-block-start: 0;
    }
    [data-theme='brutalism'] .kp-dialog__heading {
        font-size: 0.8125rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-dialog__note {
        font-weight: 500;
    }
    [data-theme='brutalism'] .kp-dialog__section--danger {
        margin-inline: calc(-1 * var(--kp-dialog-section-inset, 0.5rem));
        padding-inline: var(--kp-dialog-section-inset, 0.5rem);
        padding-block-end: calc(var(--kp-dialog-section-gap, 0.75rem) + 0.5rem);
        border-inline-start: 0;
        background: repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px) 0 100% / 100% 0.5rem no-repeat;
    }
    [data-theme='brutalism'] .kp-dialog__section--danger:last-child {
        padding-block-end: calc(var(--kp-dialog-section-gap, 0.75rem) + 0.5rem);
    }
    [data-theme='brutalism'] .kp-confirm__dependents {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--muted);
        box-shadow: 3px 3px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-confirm__dependents .kp-dialog__heading {
        margin: 0 0 var(--kp-space-xs, 0.25rem);
    }
    [data-theme='brutalism'] .kp-confirm__list {
        font-weight: 700;
    }

    /* Moments and stretches on the timeline. */
    [data-theme='brutalism'] .kp-gantt {
        --kp-gantt-mark-size: 0.75rem;
    }
    [data-theme='brutalism'] :is(.kp-gantt__point, .kp-gantt__mark)::before {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--kp-gantt-mark);
        box-shadow: 1px 1px 0 var(--border-strong);
    }
    [data-theme='brutalism'] :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-shape='diamond']::before {
        border-radius: 0;
    }
    [data-theme='brutalism'] :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-shape='triangle']::before {
        border: 0;
        background: var(--border-strong);
        box-shadow: none;
    }
    [data-theme='brutalism'] :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-shape='ring']::before,
    [data-theme='brutalism'] .kp-gantt__point[data-kp-planned]::before {
        background: var(--card);
    }
    [data-theme='brutalism'] .kp-gantt__point[data-kp-planned][data-kp-shape='triangle']::before {
        background:
            linear-gradient(var(--card), var(--card)) content-box,
            var(--border-strong) border-box;
    }
    [data-theme='brutalism'] .kp-gantt__point:hover::before {
        translate: -1px -1px;
        box-shadow: 3px 3px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-gantt__point:active::before {
        translate: 1px 1px;
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-gantt__zone,
    [data-theme='brutalism'] .kp-gantt__band {
        border-inline: 2px solid var(--border-strong);
        background: repeating-linear-gradient(45deg, hsl(from var(--kp-gantt-mark) h s l / 0.35) 0 4px, transparent 4px 10px);
    }
    [data-theme='brutalism'] .kp-gantt__zone[data-kp-lane-zone] {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--kp-gantt-mark);
    }
    [data-theme='brutalism'] :is(.kp-gantt__zone, .kp-gantt__band)[data-kp-tone='warning'] {
        --kp-gantt-mark: var(--warning);
    }
    [data-theme='brutalism'] :is(.kp-gantt__zone, .kp-gantt__band)[data-kp-tone='warning'][data-kp-lane-zone] {
        background: repeating-linear-gradient(45deg, var(--warning) 0 4px, var(--border-strong) 4px 8px);
    }
    [data-theme='brutalism'] .kp-gantt__count {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        box-shadow: 2px 2px 0 var(--border-strong);
        font-family: var(--theme-font-display);
        font-size: 0.6875rem;
        font-weight: 400;
    }
    [data-theme='brutalism'] .kp-gantt__sub {
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-gantt__lane-link {
        text-decoration-thickness: 3px;
        text-underline-offset: 0.15em;
    }
    [data-theme='brutalism'] .kp-gantt__lane-link:hover {
        background: var(--secondary);
        color: var(--secondary-foreground);
    }

    /* The journey: a path of blocks. */
    [data-theme='brutalism'] .kp-steplist--journey {
        --kp-journey-rule: 4px;
        --kp-steplist-mark: 1.5rem;
        --kp-steplist-mark-radius: 0;
    }
    [data-theme='brutalism'] .kp-steplist--journey > .kp-steplist__item {
        border: 0;
        background: transparent;
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-steplist--journey .kp-steplist__mark {
        border: 3px solid var(--border-strong);
        background-color: var(--card);
        box-shadow: 2px 2px 0 var(--border-strong);
        font-family: var(--theme-font-display);
    }
    [data-theme='brutalism'] .kp-steplist--journey .kp-steplist__title {
        font-size: 0.8125rem;
        font-weight: 700;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-steplist--journey > .kp-steplist__item:not([data-state='current']) .kp-steplist__title {
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-steplist--journey .kp-steplist__time {
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-steplist--journey > .kp-steplist__item + .kp-steplist__item::before {
        background: repeating-linear-gradient(90deg, var(--border-strong) 0 6px, transparent 6px 10px);
    }
    [data-theme='brutalism'] .kp-steplist--journey > .kp-steplist__item:is([data-state='done'], [data-state='current'])::before {
        background: var(--border-strong);
    }
    [data-theme='brutalism'] .kp-steplist--journey > .kp-steplist__item[data-state='failed']::before {
        background: repeating-linear-gradient(45deg, var(--destructive) 0 4px, var(--border-strong) 4px 8px);
    }
    [data-theme='brutalism'] .kp-steplist--journey .kp-steplist__item[data-state='done']:not([data-kp-tone]) .kp-steplist__mark {
        background: var(--border-strong);
        color: var(--card);
    }
    [data-theme='brutalism'] .kp-steplist--journey .kp-steplist__item[data-state='done'][data-kp-tone] .kp-steplist__mark {
        border-color: var(--border-strong);
        background: var(--kp-step-tone);
        color: var(--border-strong);
    }
    [data-theme='brutalism'] .kp-steplist--journey .kp-steplist__item[data-state='current'] .kp-steplist__mark {
        border-color: var(--border-strong);
        background: var(--kp-step-tone, var(--secondary));
        translate: -2px -2px;
        box-shadow: 5px 5px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-steplist--journey .kp-steplist__item[data-state='failed'] .kp-steplist__mark {
        border-color: var(--border-strong);
    }
    @container kp-journey (max-width: 30rem) {
        [data-theme='brutalism'] .kp-steplist--journey > .kp-steplist__item:not(:last-child)::after {
            background: repeating-linear-gradient(180deg, var(--border-strong) 0 6px, transparent 6px 10px);
        }
        [data-theme='brutalism']
            .kp-steplist--journey
            > .kp-steplist__item:has(+ .kp-steplist__item:is([data-state='done'], [data-state='current']))::after {
            background: var(--border-strong);
        }
        [data-theme='brutalism'] .kp-steplist--journey > .kp-steplist__item:has(+ .kp-steplist__item[data-state='failed'])::after {
            background: repeating-linear-gradient(135deg, var(--destructive) 0 4px, var(--border-strong) 4px 8px);
        }
    }

    /* The pipeline. */
    [data-theme='brutalism'] .kp-pipeline {
        --kp-pipeline-gap: 1rem;
    }
    [data-theme='brutalism'] .kp-pipeline__lane {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: 4px 4px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-pipeline__head {
        border: 0;
        border-block-end: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--kp-pipeline-tone);
        color: var(--border-strong);
    }
    [data-theme='brutalism'] .kp-pipeline__name {
        font-family: var(--theme-font-display);
        font-weight: 400;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-pipeline__count {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }
    [data-theme='brutalism'] .kp-pipeline__share {
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-pipeline__card {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: 3px 3px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-pipeline__card:hover {
        border-color: var(--border-strong);
        background: var(--secondary);
        color: var(--secondary-foreground);
        translate: -2px -2px;
        box-shadow: 5px 5px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-pipeline__card:hover :is(.kp-pipeline__sub, .kp-pipeline__meta) {
        color: inherit;
    }
    [data-theme='brutalism'] .kp-pipeline__card:active {
        translate: 3px 3px;
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-pipeline__card[aria-current='true'] {
        border-color: var(--border-strong);
        background: var(--secondary);
        color: var(--secondary-foreground);
        box-shadow:
            inset 0 0 0 2px var(--border-strong),
            3px 3px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-pipeline__card[aria-current='true'] :is(.kp-pipeline__sub, .kp-pipeline__meta) {
        color: inherit;
    }
    [data-theme='brutalism'] .kp-pipeline__card[data-kp-dimmed] {
        border-style: dashed;
        background: transparent;
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-pipeline__title {
        font-weight: 700;
        letter-spacing: 0.02em;
    }
    [data-theme='brutalism'] .kp-pipeline__sub,
    [data-theme='brutalism'] .kp-pipeline__meta {
        font-family: var(--theme-font-mono);
        font-weight: 500;
    }
    [data-theme='brutalism'] .kp-pipeline__mark {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--kp-pipeline-tone, var(--muted));
        box-shadow: 2px 2px 0 var(--border-strong);
        color: var(--border-strong);
        font-family: var(--theme-font-display);
        font-weight: 400;
    }
    [data-theme='brutalism'] .kp-pipeline__state {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: var(--kp-shadow);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-pipeline__state[data-kp-state='error'] {
        padding-block-end: calc(var(--kp-space-sm, 0.5rem) + 0.5rem);
        background:
            repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px) 0 100% / 100% 0.5rem no-repeat,
            var(--card);
    }
    [data-theme='brutalism'] .kp-pipeline__state[data-kp-state='error'] .kp-pipeline__words {
        border-inline-start: 0;
        padding-inline-start: 0;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism'] .kp-pipeline__card {
            transition:
                translate var(--fx-duration) var(--kp-sig-br-fall),
                box-shadow var(--fx-duration) var(--kp-sig-br-fall);
        }
    }
}

/* ── The ideas and the recipe components, in this theme [kpadopt4-ideas, kpadopt4-recipes] ──
   Everything here is a slab or a part of one: a terminal is an ink plate with paper words and a yellow prompt; a time
   left is a disc on its footprint and a digital time a row of blocks, and when the time is out the part is set down
   again, once, on its footprint (G3, G12); a range's pick is the yellow plate; the compare slider's divider is the
   six-pixel bar and its handle a block lifted off its footprint; a wheel turns at a constant speed and stops dead
   (G1: no ease, no settle); an included chip is yellow with a stamped tick, an excluded one is ink with a red cross
   (G5, G16); a step is set down on its footprint (G3). */
@layer kp.signature {
    /* Typed confirmation: the loss list is a slab taped off along its foot; the name is the yellow plate in its box. */
    [data-theme='brutalism'] .kp-type-confirm__loses {
        padding-block-end: calc(var(--kp-space-sm, 0.5rem) + 0.5rem);
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background:
            repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px) 0 100% / 100% 0.5rem no-repeat,
            var(--card);
        box-shadow: 3px 3px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-type-confirm__loses-title {
        font-size: 0.8125rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-type-confirm__list {
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-type-confirm__name {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--secondary);
        color: var(--secondary-foreground);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-type-confirm__input {
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-type-confirm__status {
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }

    /* Command block: the terminal is ink with paper words, the prompt the yellow hand. */
    [data-theme='brutalism'] .kp-command {
        --kp-command-prompt-ink: var(--secondary);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: var(--kp-shadow);
    }
    [data-theme='brutalism'] .kp-command__head {
        border-block-end: var(--kp-line) solid var(--border-strong);
        background: var(--secondary);
        color: var(--secondary-foreground);
    }
    [data-theme='brutalism'] .kp-command__shell {
        font-family: var(--theme-font-display);
        font-weight: 400;
        letter-spacing: -0.01em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-command__code {
        background: var(--foreground);
        color: var(--background);
    }
    [data-theme='brutalism'] .kp-command__code > code {
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-command__where {
        border-block-start: var(--kp-line) solid var(--border-strong);
        color: var(--foreground);
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-command:not([data-kp-command-ready])::before {
        border-block-end: var(--kp-line) solid var(--border-strong);
    }

    /* Visual timer and countdown. */
    [data-theme='brutalism'] .kp-timer-disc {
        --kp-timer-disc-fill: var(--secondary);
        --kp-timer-disc-marks: var(--border-strong);
    }
    [data-theme='brutalism'] .kp-timer-disc__face {
        border: var(--kp-line) solid var(--border-strong);
        background: var(--card);
        box-shadow: var(--kp-shadow);
        transition: none;
    }
    [data-theme='brutalism'] .kp-timer-disc__sector {
        box-shadow: 0 0 0 2px var(--border-strong);
        transition: none;
    }
    [data-theme='brutalism'] .kp-timer-disc__marks {
        inset: 2%;
        background: repeating-conic-gradient(from -1.2deg, var(--border-strong) 0 2.4deg, transparent 2.4deg 30deg);
    }
    [data-theme='brutalism'] .kp-timer-disc__hub {
        inset: 45%;
        border: 3px solid var(--card);
        border-radius: 0;
        background: var(--border-strong);
    }
    [data-theme='brutalism'] .kp-timer-disc[data-kp-timer-disc-state='paused'] .kp-timer-disc__sector {
        opacity: 1;
        --kp-timer-disc-fill: var(--accent);
    }
    [data-theme='brutalism'] .kp-timer-disc[data-kp-timer-disc-state='ended'] .kp-timer-disc__face {
        background: var(--secondary);
        box-shadow: var(--kp-shadow);
    }
    [data-theme='brutalism'] :is(.kp-timer-disc__caption, .kp-countdown__name) {
        font-family: var(--theme-font-display);
        font-weight: 400;
        letter-spacing: -0.01em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] :is(.kp-timer-disc__status, .kp-countdown__status) {
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-countdown {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: var(--kp-shadow);
        transition: none;
    }
    [data-theme='brutalism'] .kp-countdown__time {
        font-weight: 400;
    }
    [data-theme='brutalism'] .kp-countdown__digit {
        background: var(--secondary);
        box-shadow: inset 0 0 0 2px var(--border-strong);
        color: var(--secondary-foreground);
    }
    [data-theme='brutalism'] .kp-countdown[data-kp-countdown-state='paused'] .kp-countdown__digit {
        background: var(--muted);
        color: var(--muted-foreground);
    }
    [data-theme='brutalism'] .kp-countdown[data-kp-countdown-state='ended'] {
        background: var(--foreground);
        color: var(--background);
        box-shadow: var(--kp-shadow);
    }
    [data-theme='brutalism'] .kp-countdown[data-kp-countdown-state='ended'] .kp-countdown__status {
        color: inherit;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='brutalism']
            :is(.kp-timer-disc[data-kp-timer-disc-state='ended'] .kp-timer-disc__face, .kp-countdown[data-kp-countdown-state='ended']) {
            --kp-sig-br-h: var(--kp-sig-br-h-part);
            --kp-sig-br-sh: var(--kp-sig-br-drop);
            animation: kp-sig-brutalism-drop var(--kp-sig-br-time) var(--kp-sig-br-fall) 1;
        }
    }

    /* Range picker. */
    [data-theme='brutalism'] .kp-range__custom[aria-pressed='true'] {
        border-color: var(--border-strong);
        background: var(--secondary);
        color: var(--secondary-foreground);
        box-shadow: inset 0 0 0 2px var(--border-strong);
    }
    [data-theme='brutalism'] .kp-range__label {
        font-family: var(--theme-font-mono);
        font-weight: 700;
    }
    [data-theme='brutalism'] .kp-range__title {
        font-family: var(--theme-font-display);
        font-weight: 400;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-range__panel .kp-field__input[aria-invalid='true'] {
        border-color: var(--destructive);
        box-shadow: inset 0 0 0 2px var(--destructive);
    }

    /* Compare slider. */
    [data-theme='brutalism'] .kp-compare {
        --kp-compare-line: 6px;
        --kp-compare-ink: var(--border-strong);
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        box-shadow: var(--kp-shadow);
    }
    [data-theme='brutalism'] .kp-compare__handle {
        border: var(--kp-line) solid var(--border-strong);
        border-radius: 0;
        background: var(--secondary);
        color: var(--secondary-foreground);
        box-shadow: 4px 4px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-compare__handle:active {
        box-shadow: none;
    }
    [data-theme='brutalism'] .kp-compare__label {
        border: 2px solid var(--border-strong);
        border-radius: 0;
        background: var(--card);
        box-shadow: 3px 3px 0 var(--border-strong);
        font-family: var(--theme-font-display);
        font-weight: 400;
        letter-spacing: 0.04em;
        text-transform: uppercase;
    }
    [data-theme='brutalism'] .kp-compare__failed {
        padding-block-end: calc(var(--kp-space-md, 1rem) + 0.5rem);
        background:
            repeating-linear-gradient(45deg, var(--destructive) 0 6px, var(--border-strong) 6px 12px) 0 100% / 100% 0.5rem no-repeat,
            var(--muted);
        color: var(--foreground);
        font-weight: 700;
    }

    /* Three-way chips. */
    [data-theme='brutalism'] .kp-segmented[data-kp-segmented='tri'] {
        --kp-tri-mark-radius: 0;
        --kp-tri-out-edge: var(--border-strong);
        --kp-tri-out-ground: var(--foreground);
        --kp-tri-out-ink: var(--background);
    }
    [data-theme='brutalism'] .kp-segmented__mark {
        border: 2px solid currentColor;
        font-family: var(--theme-font-display);
        font-weight: 400;
    }
    [data-theme='brutalism'] .kp-segmented--chips > .kp-segmented__item[data-kp-segmented-tri='include'] {
        box-shadow: var(--kp-shadow);
    }
    [data-theme='brutalism'] .kp-segmented--chips > .kp-segmented__item[data-kp-segmented-tri='exclude'] {
        box-shadow: 3px 3px 0 var(--border-strong);
    }
    [data-theme='brutalism'] .kp-segmented__item[data-kp-segmented-tri='exclude'] > .kp-segmented__label {
        text-decoration-color: var(--background);
        text-decoration-thickness: 3px;
    }
