    /* The stamped inner frame is for the big marks; below that the letters need the room (4 px from the line). */
    [data-theme='brutalism'] .kp-idmark--round:not(.kp-idmark--lg, .kp-idmark--xl) {
        outline: 0;
        font-size: calc(var(--kp-idmark-s) * 0.38);
    }
    [data-theme='brutalism'] .kp-idmark--sm.kp-idmark--round {
        border-width: 1px;
        font-size: calc(var(--kp-idmark-s) * 0.36);
    }
    [data-theme='brutalism'] .kp-slider__fields,
    [data-theme='brutalism'] .kp-slider__field-wrap {
