            animation: kp-sig-titanium-ti-cutter var(--kp-sig-ti-panel) var(--kp-sig-ti-ease);
        }

        /* The list is cut open as its own entrance, not as the leave turned around. */
        [data-theme='titanium'] .kp-combobox__list {
            --kp-open: own;
        }

        /* The palette and the shortcuts sheet are dialogs: the dialog's time
           (js/motion.js plays two thirds of it, and its close backwards). */
        [data-theme='titanium'] :is(.kp-palette, .kp-shortcuts) {
            --kp-sig-dur: 240ms;
            animation: kp-sig-titanium-panel-cut var(--kp-sig-dur) var(--kp-sig-ti-ease) backwards;
        }

        [data-theme='titanium'] :is(.kp-palette, .kp-shortcuts)::after {
            animation: kp-sig-titanium-ti-cutter var(--kp-sig-dur) var(--kp-sig-ti-ease);
        }

        /* The tour: the card is cut open; the dim grows out of the target and the
           ring is drawn in on the same cut, and css/components.css takes both back
           on the curve turned round. They came in 160, 250 and 350 ms and went in
           1000. `backwards`, not `both` (lesson 21). */
        [data-theme='titanium'] .kp-tour[open]:not([data-kp-tour-stepping]) {
            animation: kp-sig-titanium-panel-cut var(--kp-sig-ti-panel) var(--kp-sig-ti-ease) backwards;
        }

        [data-theme='titanium'] .kp-tour[open]:not([data-kp-tour-stepping])::after {
            animation: kp-sig-titanium-ti-cutter var(--kp-sig-ti-panel) var(--kp-sig-ti-ease);
        }

        [data-theme='titanium'] [data-kp-tour-target] {
            animation: kp-sig-titanium-tour-ring var(--kp-sig-ti-panel) var(--kp-sig-ti-ease) backwards;
            transition:
                box-shadow var(--kp-sig-ti-panel) var(--kp-sig-ti-ease),
                outline-color var(--kp-sig-ti-panel) var(--kp-sig-ti-ease);
        }

        [data-theme='titanium'] .kp-tour[data-kp-tour-stepping] {
            animation: none;
            transition:
                left var(--kp-sig-ti-panel) var(--kp-sig-ti-ease),
                top var(--kp-sig-ti-panel) var(--kp-sig-ti-ease);
        }

        [data-theme='titanium'] .kp-tour[data-kp-tour-stepping]::after {
            animation: none;
        }

        /* The side navigation slides in the cut's band, with its backdrop: the
           panel ran 60 ms (the contact band, `--fx-duration`) under a 220 ms
           backdrop, so the close was not the open reversed (52 % off). */
        [data-theme='titanium'] .kp-sidenav {
            --kp-sidenav-duration: var(--kp-sig-ti-panel);
        }

        [data-theme='titanium'] .kp-sidenav__backdrop {
            animation-duration: var(--kp-sig-ti-panel);
        }

        /* The backdrop is a shade over the page, not a part that arrives: js/motion.js let it
           arrive as the theme's leave played backwards, which ran the heat colours (gold, violet,
           blue) over the whole frame beside the panel and dropped the shade in at the end
           (review round 1, 2026-10-13: "a splash of colour next to the bar, filling the parent
           element, looked a bit like the loading colours"). It keeps the shade it opens with
           while those marks are on it, so it comes with the panel's slide and goes as that
           backwards (js/sidenav.js), the same animation both ways. */
        [data-theme='titanium'] .kp-sidenav__backdrop:is([data-kp-leaving], [data-kp-arriving]) {
            overflow: visible;
            animation: kp-sidenav-backdrop var(--kp-sig-ti-panel) var(--kp-sidenav-ease, var(--fx-ease, ease)) both;
        }

        [data-theme='titanium'] .kp-sidenav__backdrop:is([data-kp-leaving], [data-kp-arriving])::after {
            content: none;
        }

        /* The calendar's busy layers arrive as the leave played backwards and cool
           away as they go: js/calendar.js marks a layer `[data-kp-leaving]` while
           its state goes (`--kp-calendar-busy-leave: hold`), and the rules below
           keep it drawn through the 400 ms of that leave. They came in by a 60 ms
           fade and vanished at once. */
        [data-theme='titanium'] :is(.kp-calendar__day-busy, .kp-calendar__busy) {
            --kp-calendar-busy-leave: hold;
            transition: none;
        }

        [data-theme='titanium']
            :is(.kp-calendar--busy-days, .kp-calendar--busy-whole:not(:has(> .kp-calendar__grid[aria-busy='true'])))
            .kp-calendar__day[data-kp-tone='loading']
            > .kp-calendar__day-busy:not([data-kp-leaving]),
        [data-theme='titanium'] .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true']) > .kp-calendar__busy:not([data-kp-leaving]) {
            animation: kp-sig-titanium-leave-in 400ms var(--kp-sig-ti-ease) reverse backwards;
        }

        [data-theme='titanium'] .kp-calendar--busy-whole > .kp-calendar__busy {
            position: relative;
        }

        [data-theme='titanium']
            :is(.kp-calendar--busy-days, .kp-calendar--busy-whole:not(:has(> .kp-calendar__grid[aria-busy='true'])))
            .kp-calendar__day[data-kp-tone='loading']
            > .kp-calendar__day-busy:not([data-kp-leaving])::after,
        [data-theme='titanium']
            .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true'])
            > .kp-calendar__busy:not([data-kp-leaving])::after {
            content: '';
            position: absolute;
            inset: 0;
            pointer-events: none;
            z-index: 2;
            background: linear-gradient(110deg, var(--warning-foreground), var(--chart-2), var(--chart-1), var(--chart-3));
            background-size: 300% 100%;
            mix-blend-mode: color;
            opacity: 0;
            animation: kp-sig-titanium-leave-2-in 400ms var(--kp-sig-ti-ease) reverse backwards;
        }

        [data-theme='titanium'] .kp-calendar__day:has(> .kp-calendar__day-busy[data-kp-leaving]) {
            position: relative;
        }

        [data-theme='titanium'] .kp-calendar__day-busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-spinner, 0.75rem);
            position: absolute;
            inset-inline: 0;
            inset-block-end: 0.125rem;
            display: flex;
            justify-content: center;
            line-height: 0;
        }

        [data-theme='titanium'] .kp-calendar--busy-whole > .kp-calendar__busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-busy-spinner, 2.5rem);
            z-index: 1;
            display: grid;
            place-self: center;
            place-items: center;
            padding: var(--kp-space-md, 1rem);
            border-radius: var(--radius, 0.5rem);
            background: var(--card);
            box-shadow: 0 0 0 1px var(--border);
            line-height: 0;
        }

        /* The header: the dropdown and the mega menu are cut open as a menu is and
           cut shut as that played backwards (a second keyframes name, so the close
           restarts); the bar holds the panel through its close. */
        [data-theme='titanium'] .kp-nav__menu:not(.kp-nav__menu--wide) {
            transition: none;
        }

        [data-theme='titanium'] .kp-nav__menu--wide {
            --kp-sig-ti-hold: 0;
            transition: --kp-sig-ti-hold var(--kp-sig-ti-panel) linear;
        }

        [data-theme='titanium']
            :is(
                .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
            ) {
            --kp-sig-ti-hold: 1;
            animation: kp-sig-titanium-panel-cut var(--kp-sig-ti-panel) var(--kp-sig-ti-ease) backwards;
        }

        [data-theme='titanium']
            :is(
                .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
            )::after {
            animation: kp-sig-titanium-ti-cutter var(--kp-sig-ti-panel) var(--kp-sig-ti-ease);
        }

        [data-theme='titanium']
            .kp-nav__links
            > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open])
            > .kp-nav__menu:not(.kp-nav__menu--wide) {
            display: block;
            opacity: 1;
        }

        [data-theme='titanium']
            :is(
                .kp-nav__links > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                .kp-nav__links
                    > li[data-kp-nav-closing]:not([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
                    > .kp-nav__menu--wide
            ) {
            animation: kp-sig-titanium-panel-cut-back var(--kp-sig-ti-panel) var(--kp-sig-ti-ease) reverse forwards;
        }

        [data-theme='titanium']
            :is(
                .kp-nav__links > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                .kp-nav__links
                    > li[data-kp-nav-closing]:not([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
                    > .kp-nav__menu--wide
            )::after {
            animation: kp-sig-titanium-ti-cutter-back var(--kp-sig-ti-panel) var(--kp-sig-ti-ease) reverse forwards;
        }

        /* The phone panel is cut open under the bar the same way (it had no motion). */
        @container kp-nav (max-width: 40rem) {
            [data-theme='titanium'] .kp-nav:has(> .kp-nav__toggle) > .kp-nav__links {
                position: relative;
            }

            [data-theme='titanium'] .kp-nav:has(> .kp-nav__toggle) > .kp-nav__links::after {
                content: '';
                position: absolute;
                inset: 0;
                border-block-end: 2px solid var(--chart-2);
                opacity: 0;
                pointer-events: none;
            }

            [data-theme='titanium'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
                animation: kp-sig-titanium-panel-cut var(--kp-sig-ti-panel) var(--kp-sig-ti-ease) backwards;
            }

            [data-theme='titanium'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links::after {
                animation: kp-sig-titanium-ti-cutter var(--kp-sig-ti-panel) var(--kp-sig-ti-ease);
            }

            [data-theme='titanium'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-closing] > .kp-nav__links {
                animation: kp-sig-titanium-panel-cut-back var(--kp-sig-ti-panel) var(--kp-sig-ti-ease) reverse forwards;
            }

            [data-theme='titanium'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-closing] > .kp-nav__links::after {
                animation: kp-sig-titanium-ti-cutter-back var(--kp-sig-ti-panel) var(--kp-sig-ti-ease) reverse forwards;
            }

            /* Inside the open panel the lists are its own rows: no cut of their own. */
            [data-theme='titanium'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__links > li > .kp-nav__menu.kp-nav__menu {
                animation: none;
                transition: none;
            }

            [data-theme='titanium'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__links > li > .kp-nav__menu.kp-nav__menu::after {
                content: none;
            }
        }
    }

    /* ── The side navigation and the alarm are cut open as titanium's dialog is
       [G3; Kenny, review round 2: "Niet de open/close animatie van dit thema"]:
       uncovered from the top edge down on the theme curve, the cutter line in the
       second oxide (`--chart-2`) running ahead of the cut; the close is that cut
       played backwards. ── */
    [data-theme='titanium'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])::after {
        content: '';
        position: absolute;
        inset: 0;
        border-block-end: 2px solid var(--chart-2);
        opacity: 0;
        pointer-events: none;
    }

    @media (prefers-reduced-motion: no-preference) {
        /* The side navigation that slides over or pushes the page no longer
           slides (the slide was the package's, not the cut): it stands in its
           place from the opening's first frame, is cut open in the panel's band
           (240 ms), is cut shut backwards and only then goes back off screen;
           a pushed page moves with those two frames. */
        [data-theme='titanium'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true'] {
            transition: translate 0s linear;
            animation: kp-sig-titanium-panel-cut var(--kp-sig-ti-panel) var(--kp-sig-ti-ease) backwards;
        }

        [data-theme='titanium'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true']::after {
            animation: kp-sig-titanium-ti-cutter var(--kp-sig-ti-panel) var(--kp-sig-ti-ease);
        }

        [data-theme='titanium'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='false'] {
            transition: translate 0s linear var(--kp-sig-ti-panel);
            animation: kp-sig-titanium-panel-cut-back var(--kp-sig-ti-panel) var(--kp-sig-ti-ease) reverse forwards;
        }

        [data-theme='titanium'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='false']::after {
            animation: kp-sig-titanium-ti-cutter-back var(--kp-sig-ti-panel) var(--kp-sig-ti-ease) reverse forwards;
        }

        [data-theme='titanium'] [data-kp-sidenav-shift='open'] {
            transition:
                margin-inline-start 0s linear,
                margin-inline-end 0s linear,
                padding-inline-start 0s linear,
                padding-inline-end 0s linear;
        }

        [data-theme='titanium'] [data-kp-sidenav-shift='closed'] {
            transition:
                margin-inline-start 0s linear var(--kp-sig-ti-panel),
                margin-inline-end 0s linear var(--kp-sig-ti-panel),
                padding-inline-start 0s linear var(--kp-sig-ti-panel),
                padding-inline-end 0s linear var(--kp-sig-ti-panel);
        }

        /* The alarm: the whole screen cut open from the top on the dialog's
           time, the cutter line drawn by the scan layer's ::after (titanium
           does not sweep the scan). The package's rise, scale and fades of the
           panel, the headline and the reason are retired; js/motion.js keeps
           the cut and plays it backwards to close. */
        [data-theme='titanium'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            animation: kp-sig-titanium-panel-cut var(--kp-sig-dur, 240ms) var(--kp-sig-ti-ease) backwards;
        }

        [data-theme='titanium'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) .kp-alarm__scan::after {
            content: '';
            inset: 0;
            block-size: auto;
            border-block-end: 2px solid var(--chart-2);
            background: none;
            opacity: 0;
            animation: kp-sig-titanium-ti-cutter var(--kp-sig-dur, 240ms) var(--kp-sig-ti-ease);
        }

        [data-theme='titanium'] .kp-alarm:not([data-kp-alarm-motion='still']) :is(.kp-alarm__panel, .kp-alarm__title, .kp-alarm__detail) {
            animation: none;
        }
    }

    /* A panel uncovered from its top edge down; its shadow keeps room at the sides
       and the foot. */
    @keyframes kp-sig-titanium-panel-cut {
        from {
            clip-path: inset(0 -3rem 100% -3rem);
        }

        to {
            clip-path: inset(0 -3rem -3rem -3rem);
        }
    }

    /* The same cut and cutter under second names, for a close that plays them
       backwards and must restart (lesson 8). */
    @keyframes kp-sig-titanium-panel-cut-back {
        from {
            clip-path: inset(0 -3rem 100% -3rem);
        }

        to {
            clip-path: inset(0 -3rem -3rem -3rem);
        }
    }

    @keyframes kp-sig-titanium-ti-cutter-back {
        from {
            opacity: 1;
            transform: translateY(-100%);
        }

        to {
            opacity: 1;
            transform: none;
        }
    }

    @keyframes kp-sig-titanium-tour-ring {
        from {
            outline-color: transparent;
        }
    }

    /* The leave and its heat under second names, for a busy layer that arrives
       and then leaves (an arrival that turns into its leave must restart). */
    @keyframes kp-sig-titanium-leave-in {
        0%,
        70% {
            opacity: 1;
        }

        to {
            opacity: 0;
        }
    }

    @keyframes kp-sig-titanium-leave-2-in {
        from {
            opacity: 0;
            background-position: 100% 0;
        }

        20% {
            opacity: 1;
        }

        to {
            opacity: 1;
            background-position: 0% 0;
        }
    }

    /* Information that updates in place, this theme's way [picked by Kenny on
       research/update-motion, 2026-10-05]. js/update.js writes the new value at
       once and marks the element `[data-kp-updating]` with this register's
       `--kp-update` while the keyframes play, at `--kp-update-duration` on
       `--kp-update-ease` (themeMotion()). The value is never hidden or resized. */
    @media (prefers-reduced-motion: no-preference) {
        /* ── titanium: heat tint. The anodised colours of the leave (gold, violet, blue) run across the value through
           `mix-blend-mode: color` and cool away; the value keeps its lightness, so it stays readable. ── */
        [data-theme='titanium'] {
            --kp-update: anodise;
        }

        [data-theme='titanium'] [data-kp-updating='anodise'] {
            position: relative;
        }

        [data-theme='titanium'] [data-kp-updating='anodise']::before {
            content: '';
            position: absolute;
            inset: 0;
            z-index: 1;
            pointer-events: none;
            background: var(--kp-sig-ti-heat);
            mix-blend-mode: color;
            animation: kp-sig-titanium-update-anodise var(--kp-update-duration) var(--kp-update-ease) both;
        }

        /* A chart changes at its last point: the tint runs over its last part. */
        [data-theme='titanium'] [data-kp-updating='anodise']:has(> svg)::before {
            inset: -0.25rem -0.5rem -0.25rem 72%;
        }

        @keyframes kp-sig-titanium-update-anodise {
            from {
                background-position-x: 100%;
                opacity: 0;
            }

            20% {
                opacity: 1;
            }

            75% {
                opacity: 1;
            }

            to {
                background-position-x: 0%;
                opacity: 0;
            }
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 1, while
       loading 1, how the share arrives 3, when the tone changes 3,
       the mark past the end 3]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='titanium']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='titanium']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='titanium']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='titanium']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='titanium']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='titanium']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='titanium']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='titanium']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── titanium · the heat-tinted groove ────────────────────────── */
    [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.5rem;
        --kp-sig-meter-room: 0.625rem;
        --kp-sig-meter-mo-ink: var(--primary);
        --kp-sig-meter-mo-halo: var(--background);
        border-radius: 0;
        background: var(--muted);
        box-shadow:
            inset 0 1px 0 hsl(from var(--background) h s l / 0.95),
            inset 0 2px 1px hsl(from var(--background) h s l / 0.5),
            inset 0 -1px 0 hsl(from var(--foreground) h s l / 0.2),
            0 0 0 1px var(--border);
    }

    /* The oxide heat grows, fixed by where it stands along the groove: gold,
       bronze, violet, blue. A tone replaces it. */
    [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter)::before {
        inset-block: 1px;
        border-radius: 0;
        background: linear-gradient(90deg, var(--warning-foreground), var(--chart-4) 30%, var(--chart-2) 55%, var(--chart-1) 78%, var(--chart-3)) 0
            0 / calc(100% / clamp(0.01, var(--kp-value, 0), 1)) 100% no-repeat;
    }

    /* The demo set this transition unguarded (DI7); guarded here. At full
       motion the arrival's own transition below replaces it, as it did there. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter)::before {
            transition: inline-size var(--fx-duration, 60ms) var(--kp-sig-ti-ease);
        }
    }

    [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone]::before {
        background: var(--kp-meter-fill-colour);
    }

    /* A milled pointer with two facets. */
    [data-theme='titanium'] .kp-meter__mark {
        inset-block: -2px;
        border-radius: 0;
        background: var(--primary);
        box-shadow: 0 0 0 1px var(--background);
    }

    [data-theme='titanium'] .kp-meter__mark::before {
        content: '';
        position: absolute;
        inset-block-end: calc(100% + 1px);
        inset-inline-start: 50%;
        inline-size: 8px;
        block-size: 5px;
        translate: -50% 0;
        background: linear-gradient(90deg, var(--primary) 50%, var(--primary-active) 50%);
        clip-path: polygon(0 0, 100% 0, 100% 30%, 50% 100%, 0 30%);
    }

    /* A burr of bare bright metal past the end. */
    [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        inset-inline-start: calc(100% + 1px);
        inset-block: 0;
        inline-size: 0.375rem;
        background: linear-gradient(to bottom, var(--primary), var(--primary-active));
        clip-path: polygon(0 0, calc(100% - 3px) 0, 100% 3px, 100% 100%, 0 100%);
    }

    /* ── while loading: option 1 ── */

    /* Measuring is the anodising bath (G10): the whole groove carries the
       oxide film, the heat-tinted groove's own source, drifting start → end. */
    [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        inset-block: 1px;
        inset-inline: 0;
        background: var(--kp-sig-ti-oxide);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            animation: kp-sig-titanium-bath var(--kp-sig-ti-loop) linear infinite;
        }
    }

    /* ── how the share arrives: option 3 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-titanium-meter-grow-o 300ms var(--kp-sig-ti-ease) backwards;
            transition: inline-size 300ms var(--kp-sig-ti-ease);
            transform-origin: 0 50%;
        }
    }

    /* ── when the tone changes: option 3 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter):not([data-kp-loading], [data-kp-tone]) {
            animation: kp-sig-titanium-meter-jolt-o 160ms var(--kp-sig-ti-ease);
        }

        [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']:not([data-kp-loading]) {
            animation: kp-sig-titanium-meter-jolt-w 160ms var(--kp-sig-ti-ease);
        }

        [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']:not([data-kp-loading]) {
            animation: kp-sig-titanium-meter-jolt-d 160ms var(--kp-sig-ti-ease);
        }
    }

    /* ── the mark past the end: option 3 ── */

    [data-theme='titanium'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '▸';
    }

    [data-theme='titanium'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
        rotate: 24deg;
        transform-origin: 50% 100%;
    }

    [data-theme='titanium'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        rotate: -24deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='titanium'] .kp-meter__mark {
            transition:
                inset-inline-start 300ms var(--kp-sig-ti-ease),
                rotate 300ms var(--kp-sig-ti-ease);
        }
    }

    @keyframes kp-sig-titanium-meter-grow-o {
        0% {
            scale: 0 1;
        }

        100% {
            scale: 1 1;
        }
    }

    @keyframes kp-sig-titanium-meter-jolt-d {
        0% {
            translate: 0 0;
        }

        20% {
            translate: -2px 0;
        }

        40% {
            translate: 2px 0;
        }

        60% {
            translate: -1px 0;
        }

        80% {
            translate: 1px 0;
        }

        100% {
            translate: 0 0;
        }
    }

    @keyframes kp-sig-titanium-meter-jolt-o {
        0% {
            translate: 0 0;
        }

        20% {
            translate: -2px 0;
        }

        40% {
            translate: 2px 0;
        }

        60% {
            translate: -1px 0;
        }

        80% {
            translate: 1px 0;
        }

        100% {
            translate: 0 0;
        }
    }

    @keyframes kp-sig-titanium-meter-jolt-w {
        0% {
            translate: 0 0;
        }

        20% {
            translate: -2px 0;
        }

        40% {
            translate: 2px 0;
        }

        60% {
            translate: -1px 0;
        }

        80% {
            translate: 1px 0;
        }

        100% {
            translate: 0 0;
        }
    }

    /* ── Loading is the anodising bath [themes/titanium/CHARACTER.md G10;
       Kenny on research/titanium-loading, 2026-10-07 00:54: the bath for
       every loading element but the network graph]. The oxide ramp washed
       32% into the part's own plate, drifting start → end at a constant
       feed, one period (--kp-sig-ti-loop) for every carrier, rows of parts
       a beat apart. The skeleton, the progress bar and the meter carry it
       above; the spinner is the facing cut (decided 2026-10-07 01:33), its own
       picture: the oxide the tool tip leaves on a turning face.
       Standing still (reduced motion) the wash stays, still. ── */
    [data-theme='titanium'] .kp-datatable__busy-panel {
        background: var(--kp-sig-ti-bath), var(--card);
    }

    [data-theme='titanium'] .kp-datatable[aria-busy='true'] .kp-table tbody tr:not([data-kp-skeleton-row]) {
        background: var(--kp-sig-ti-bath), var(--card);
    }

    [data-theme='titanium'] .kp-datatable[aria-busy='true'] .kp-table tbody tr:not([data-kp-skeleton-row]) > td {
        background: transparent;
    }

    [data-theme='titanium'] .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading] {
        background: var(--kp-sig-ti-bath), var(--popover);
    }

    [data-theme='titanium'] .kp-button[aria-busy='true'] {
        background: var(--kp-sig-ti-bath), var(--card);
        color: var(--foreground);
    }

    [data-theme='titanium'] .kp-calendar--busy-whole > .kp-calendar__busy {
        background: var(--kp-sig-ti-bath), var(--card);
    }

    [data-theme='titanium'] .kp-chart__state[data-kp-state='loading'] {
        background: var(--kp-sig-ti-bath), var(--card);
    }

    /* A busy card (a region the package dims while it waits): its face too. */
    [data-theme='titanium'] .kp-card[aria-busy='true'] {
        background: var(--kp-sig-ti-bath), var(--card);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='titanium'] .kp-datatable__busy-panel,
        [data-theme='titanium'] .kp-datatable[aria-busy='true'] .kp-table tbody tr:not([data-kp-skeleton-row]),
        [data-theme='titanium'] .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading],
        [data-theme='titanium'] .kp-button[aria-busy='true'],
        [data-theme='titanium'] .kp-calendar--busy-whole > .kp-calendar__busy,
        [data-theme='titanium'] .kp-chart__state[data-kp-state='loading'],
        [data-theme='titanium'] .kp-card[aria-busy='true'] {
            animation: kp-sig-titanium-bath var(--kp-sig-ti-loop) linear infinite;
        }

        [data-theme='titanium'] .kp-datatable:is([aria-busy='true'], :has(> .kp-datatable__busy-overlay)) .kp-table tbody tr:nth-child(2) {
            animation-delay: -440ms;
        }

        [data-theme='titanium'] .kp-datatable:is([aria-busy='true'], :has(> .kp-datatable__busy-overlay)) .kp-table tbody tr:nth-child(3) {
            animation-delay: -880ms;
        }

        [data-theme='titanium'] .kp-datatable:is([aria-busy='true'], :has(> .kp-datatable__busy-overlay)) .kp-table tbody tr:nth-child(4) {
            animation-delay: -1320ms;
        }
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — titanium: machined metal. The current tab is a chamfered accent plate (top-start and bottom-end cut) with a bright tool edge along its top, fed in from the start and slowing as it lands; counts in the mono (G2, G7, G8). */
    [data-theme='titanium'] .kp-tabbar {
        box-shadow: inset 0 1px 0 hsl(from var(--foreground) h s l / 0.1);
    }

    [data-theme='titanium'] .kp-tabbar__tab {
        border-radius: 0;
        isolation: isolate;
    }

    [data-theme='titanium'] .kp-tabbar__tab::before {
        inset: 0;
        block-size: auto;
        z-index: -1;
        background: var(--accent);
        box-shadow: inset 0 1px 0 hsl(from var(--foreground) h s l / 0.45);
        clip-path: polygon(
            var(--fx-notch) 0,
            100% 0,
            100% calc(100% - var(--fx-notch)),
            calc(100% - var(--fx-notch)) 100%,
            0 100%,
            0 var(--fx-notch)
        );
        transform-origin: 0 50%;
    }

    [data-theme='titanium'] .kp-tabbar__tab:dir(rtl)::before {
