/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Titanium's own (themes/titanium/CHARACTER.md): a tile is a machined plate, square with the register's chamfer pair
   (top-start and bottom-end), the bright tool edge along its top (G7, G8); every contact is instant and linear, metal
   does not ease (G1, G4): pointing turns the tool edge to bare bright metal, a press drops the plate 1 px; a pick is
   bright metal, a running process blue oxide (G6); waiting is the anodising bath, the oxide ramp drifting start to end
   in every waiting part (G10); Martian Mono for labels and counts (G8). */
@layer kp.signature {
    [data-theme='titanium'] .kp-actions {
        --kp-actions-gap: 0.625rem;
    }
    [data-theme='titanium'] .kp-action {
        --kp-sig-ti-c: 0.5rem;
        --kp-action-radius: 0;
        --kp-action-edge: var(--border-strong);
        --kp-action-edge-hover: var(--border-strong);
        --kp-action-shadow: inset 0 2px 0 hsl(from var(--foreground) h s l / 0.22);
        --kp-action-shadow-hover: inset 0 2px 0 var(--primary);
        --kp-action-shadow-active: inset 0 2px 0 var(--primary), inset 0 1px 3px hsl(from var(--background) h s l / 0.6);
        --kp-action-ground-active: var(--muted);
        --kp-action-press: 0 1px;
        --kp-action-title-weight: 700;
        background:
            repeating-linear-gradient(90deg, hsl(from var(--foreground) h s l / 0.035) 0 1px, transparent 1px 3px),
            var(--kp-action-ground, var(--card));
        clip-path: polygon(
            calc(var(--kp-sig-ti-c) + 8px) -8px,
            calc(100% + 8px) -8px,
            calc(100% + 8px) calc(100% - var(--kp-sig-ti-c) - 8px),
            calc(100% - var(--kp-sig-ti-c) - 8px) calc(100% + 8px),
            -8px calc(100% + 8px),
            -8px calc(var(--kp-sig-ti-c) + 8px)
        );
    }
    [data-theme='titanium'] .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        background: repeating-linear-gradient(90deg, hsl(from var(--foreground) h s l / 0.05) 0 1px, transparent 1px 3px), var(--card);
    }
    [data-theme='titanium'] .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        background: var(--muted);
    }
    [data-theme='titanium'] .kp-action:is(:disabled, [aria-disabled='true']) {
        background: var(--muted);
    }
    /* Focus: DI2's two channels drawn inside the plate, and carried across the two cut corners on the chamfer's own
       diagonal, so the ring is whole and chamfered. */
    [data-theme='titanium'] :is(.kp-action, .kp-week__pill, .kp-gantt__run):focus-visible {
        outline: none;
        box-shadow:
            inset 0 0 0 2px var(--focus-ring),
            inset 0 0 0 4px var(--focus-ring-contrast);
        background-image:
            linear-gradient(
                135deg,
                transparent calc(var(--kp-sig-ti-c) * 0.7071),
                var(--focus-ring) 0 calc(var(--kp-sig-ti-c) * 0.7071 + 2px),
                var(--focus-ring-contrast) 0 calc(var(--kp-sig-ti-c) * 0.7071 + 4px),
                transparent 0
            ),
            linear-gradient(
                315deg,
                transparent calc(var(--kp-sig-ti-c) * 0.7071),
                var(--focus-ring) 0 calc(var(--kp-sig-ti-c) * 0.7071 + 2px),
                var(--focus-ring-contrast) 0 calc(var(--kp-sig-ti-c) * 0.7071 + 4px),
                transparent 0
            );
        background-size:
            calc(var(--kp-sig-ti-c) * 2 + 8px) calc(var(--kp-sig-ti-c) * 2 + 8px),
            calc(var(--kp-sig-ti-c) * 2 + 8px) calc(var(--kp-sig-ti-c) * 2 + 8px);
        background-position:
            0 0,
            100% 100%;
        background-repeat: no-repeat;
