    [data-theme='titanium'] .kp-action__meta {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.04em;
    }
    /* Destructive: the tool edge in the red's bronze heat along its top and the title in the red; no side bar. */
    [data-theme='titanium'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) {
        --kp-action-tone-edge: var(--border-strong);
        --kp-action-tone-edge-hover: var(--border-strong);
        --kp-action-shadow: inset 0 3px 0 var(--destructive);
        --kp-action-shadow-hover: inset 0 3px 0 var(--destructive), inset 0 4px 0 var(--primary);
        --kp-action-shadow-active: inset 0 3px 0 var(--destructive), inset 0 1px 3px hsl(from var(--background) h s l / 0.6);
    }
    [data-theme='titanium'] .kp-action--destructive::after {
