            radial-gradient(circle, var(--kp-sig-pa-pass-c) 1.3px, transparent 1.7px) 2px 2px / 6px 6px;
        mask: radial-gradient(circle closest-side, black 0 calc(100% - 1px), transparent 100%);
    }

    [data-theme='pastel'] :is(.kp-empty, :where(.kp-checklist__empty:not([data-kp-checklist-failed])))::after {
        content: '';
        position: absolute;
        inset-block-end: 0;
        inset-inline-end: 0;
        inline-size: var(--kp-sig-pa-lip);
        block-size: var(--kp-sig-pa-lip);
        box-sizing: border-box;
        border: 1px solid var(--border-strong);
        border-block-end: 0;
        border-inline-end: 0;
        border-radius: 0;
        border-start-start-radius: var(--kp-sig-pa-r-plate);
        background: linear-gradient(
            calc(135deg - 90deg * (1 - var(--kp-sig-pa-dir))),
            var(--muted) calc(50% - 1px),
            hsl(from var(--border-strong) h s l / 0.7) calc(50% - 1px) 50%,
            transparent 50%
        );
        box-shadow: none;
    }

    [data-theme='pastel'] .kp-empty__title {
        margin: 0 0 0.25rem;
        color: var(--foreground);
        font-weight: 700;
    }

    [data-theme='pastel'] .kp-empty__body {
        margin: 0;
    }

    /* A link in running text: a mint plate grows in behind its words, start
       to end, on the landing in the contact time; a link in a navigation, a
       menu, a breadcrumb or the footer keeps its own component's look
       (scope-93). */
    [data-theme='pastel'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a) {
        position: relative;
        isolation: isolate;
        text-decoration-color: var(--primary);
        text-decoration-thickness: 2px;
        text-underline-offset: 0.22em;
    }

    [data-theme='pastel'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a)::before {
        content: '';
        position: absolute;
        z-index: -1;
        inset: -0.05em -0.25em;
        border-radius: 0.4em;
        background: var(--accent);
        transform: scaleX(0);
        transform-origin: calc(50% - 50% * var(--kp-sig-pa-dir)) 50%;
    }

    [data-theme='pastel']
        a:not(
            [class],
            :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-breadcrumb, .kp-sidenav, .kp-footer) a
        ):hover::before {
        transform: none;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel']
            a:not(
                [class],
                :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-breadcrumb, .kp-sidenav, .kp-footer) a
            )::before {
            transition: transform var(--fx-duration) var(--kp-sig-pa-land);
        }
    }
    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 1, while
       loading 1, how the share arrives 3, when the tone changes 1,
       the mark past the end 2]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='pastel']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='pastel']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='pastel']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='pastel']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='pastel']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='pastel']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='pastel']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='pastel']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── pastel · washi tape ──────────────────────────────────────── */
    [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.625rem;
        --kp-sig-meter-room: 0.75rem;
        --kp-sig-meter-mo-ink: var(--primary);
        border-radius: 999px;
        background:
            radial-gradient(circle, hsl(from var(--border-strong) h s l / 0.4) 0 0.75px, transparent 1.25px) 0 0 / 4px 4px,
            var(--muted);
        box-shadow: inset 0 0 0 1px hsl(from var(--border-strong) h s l / 0.5);
    }

    /* Plum tape with white stripes, the sky second pass off register under
       it, the far end torn. */
    [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)::before {
        inset-block: 1px;
        border-radius: 999px 0 0 999px;
        background:
            repeating-linear-gradient(-45deg, hsl(from var(--card) h s l / 0.3) 0 2px, transparent 2px 5px) 0 0 / calc(100% - 2px) calc(100% - 2px)
                no-repeat,
            linear-gradient(var(--kp-meter-fill-colour), var(--kp-meter-fill-colour)) 0 0 / calc(100% - 2px) calc(100% - 2px) no-repeat,
            var(--fx-overprint);
        clip-path: polygon(0 0, calc(100% - 3px) 0, 100% 20%, calc(100% - 3px) 40%, 100% 60%, calc(100% - 3px) 80%, 100% 100%, 0 100%);
    }

    /* A round sticker on a pin. */
    [data-theme='pastel'] .kp-meter__mark {
        inset-block: -2px;
        border-radius: 1px;
        background: var(--foreground);
        box-shadow: 0 0 0 1px var(--card);
    }

    [data-theme='pastel'] .kp-meter__mark::before {
        content: '';
        position: absolute;
        inset-block-end: calc(100% - 1px);
        inset-inline-start: 50%;
        inline-size: 9px;
        block-size: 9px;
        translate: -50% 0;
        border-radius: 50%;
        background: var(--card);
        box-shadow:
            inset 0 0 0 2px var(--primary),
            1px 1px 0 var(--primary);
    }

    /* The tape runs over and its corner curls. */
    [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        inset-inline-start: calc(100% + 1px);
        inset-block: 1px;
        inline-size: 0.5rem;
        background: linear-gradient(225deg, transparent 0 32%, var(--fx-overprint) 32% 50%, var(--kp-meter-fill-colour) 50%);
    }

    /* ── while loading: everything becomes caterpillar (G10, section 10) ── */

    /* The track is the caterpillar's row: the pieces (js/loading-pieces.js)
       or, without the script, the still row of pom-poms. */
    [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: visible;
        background: none;
        box-shadow: none;
    }

    [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::before {
        content: none;
    }

    /* ── how the share arrives: stuck on (G2, proposal-4) ── */

    /* The share is stuck on from its start corner on the landing (the tape
       carries its own sky pass), and a new share is laid on the same curve
       in a pass's time. A tone change lays it again in the new colour,
       under a second name so it starts over. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)::before {
            transform-origin: var(--kp-sig-pa-corner);
            animation: kp-sig-pastel-meter-stuck-o var(--kp-sig-pa-window) var(--kp-sig-pa-land) backwards;
            transition: inline-size 440ms var(--kp-sig-pa-land);
        }

        [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']::before {
            animation-name: kp-sig-pastel-meter-stuck-w;
        }

        [data-theme='pastel'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']::before {
            animation-name: kp-sig-pastel-meter-stuck-d;
        }
    }

    /* ── the mark past the end: option 2, without the heart (G18) ── */

    [data-theme='pastel'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
        rotate: 24deg;
        transform-origin: 50% 100%;
    }

    [data-theme='pastel'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        rotate: -24deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-meter__mark {
            transition:
                inset-inline-start 440ms var(--kp-sig-pa-land),
                rotate 440ms var(--kp-sig-pa-land);
        }
    }

    @keyframes kp-sig-pastel-meter-stuck-o {
        0%,
        21.4286% {
            rotate: calc(-9deg * var(--kp-sig-pa-turn, var(--kp-sig-pa-dir, 1)));
            translate: 0 -8px;
            opacity: 0;
        }
    }

    @keyframes kp-sig-pastel-meter-stuck-w {
        0%,
        21.4286% {
            rotate: calc(-9deg * var(--kp-sig-pa-turn, var(--kp-sig-pa-dir, 1)));
            translate: 0 -8px;
            opacity: 0;
        }
    }

    @keyframes kp-sig-pastel-meter-stuck-d {
        0%,
        21.4286% {
            rotate: calc(-9deg * var(--kp-sig-pa-turn, var(--kp-sig-pa-dir, 1)));
            translate: 0 -8px;
            opacity: 0;
        }
    }

    /* ── 13 · Closes that are their opens reversed: the package's hooks ── */

    /* A tree branch's children glide shut as they glided open (js/motion.js
       glideGroup(), lesson 26): the group is kept drawn while it shuts. */
    [data-theme='pastel'] .kp-tree [role='treeitem'][aria-expanded='false'] > [role='group'][data-kp-group-folding],
    [data-theme='pastel'] .kp-tree [role='treeitem'][aria-expanded='false'] + [role='group'][data-kp-group-folding] {
        display: block;
    }

    /* One loading picture: while the busy table's layer stands over the rows,
       the status line's small spinner stays out, so it holds back no arrival
       of the layer and needs no leave of its own (lesson 23). */
    [data-theme='pastel'] .kp-datatable:has(> .kp-datatable__busy-overlay) .kp-datatable__status > .kp-spinner {
        display: none;
    }

    /* The tour (lessons 11, 21, 22): the page's dim and the target's ring
       come on the landing in its 560 ms and go in the same time on the
       landing turned around, shrinking back into the target; the ring is
       drawn in from transparent, `backwards` so the close's transition can
       take it back. */
    [data-theme='pastel'] {
        --kp-tour-dim-close: 0 0 0 0 transparent;
        --kp-tour-dim-time: var(--kp-sig-pa-window);
        --kp-tour-dim-close-ease: var(--kp-sig-pa-land-back);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] [data-kp-tour-target] {
            outline-style: dashed;
            animation: kp-sig-pastel-tour-ring var(--kp-sig-pa-window) var(--kp-sig-pa-land) backwards;
            transition:
                box-shadow var(--kp-sig-pa-window) var(--kp-sig-pa-land),
                outline-color var(--kp-sig-pa-window) var(--kp-sig-pa-land);
        }
    }

    @keyframes kp-sig-pastel-tour-ring {
        from {
            outline-color: transparent;
        }
    }

    @media (prefers-reduced-motion: reduce) {
        [data-theme='pastel'] {
            --kp-nav-close-time: 0ms;
        }
    }
}
/* ── End of the signature ── */

/* The words of a part that draws its own plate and pass (the signature
   layer, section 4) fade with its plate on `--kp-sig-pa-ink`. In kp.base, so
   a component's own opacity for one of its parts (a disabled control) still
   wins and that part keeps its own look. */
@layer kp.base {
    [data-theme='pastel']
        :is(
            .kp-toast,
            .kp-alert,
            .kp-tour,
            .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']),
            .kp-datatable__busy-panel,
            .kp-calendar__busy
        )
        > *,
    [data-theme='pastel'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > * {
        opacity: clamp(0, var(--kp-sig-pa-ink), 1);
    }
}

/* ── Segmented control, list toolbar, key line [kpadopt-controls] ── */
@layer kp.signature {
    [data-theme='pastel'] .kp-segmented {
        --kp-seg-radius: var(--kp-sig-pa-r-ctl, 0.85rem);
        --kp-seg-pad: 4px;
        --kp-seg-track: var(--secondary);
        --kp-seg-thumb: var(--primary);
        --kp-seg-thumb-ink: var(--primary-foreground);
        --kp-seg-thumb-edge: 0 0 0 0 transparent;
        --kp-seg-thumb-lift: 0 3px 0 var(--kp-sig-pa-peel, hsl(from var(--primary) h s calc(l * 0.55)));
        --kp-chip-radius: var(--kp-sig-pa-r-ctl, 0.85rem);
        --kp-chip-on: var(--primary);
        --kp-chip-on-ink: var(--primary-foreground);
    }
    [data-theme='pastel'] .kp-toolbar {
        --kp-toolbar-group-gap: 1.125rem;
    }
    [data-theme='pastel'] .kp-toolbar__label {
        letter-spacing: 0.05em;
    }
    [data-theme='pastel'] .kp-keys {
        --kp-keys-gap: 1rem;
    }
    [data-theme='pastel'] .kp-kbd {
        --kp-kbd-radius: 0.5rem;
        --kp-kbd-edge: var(--border-strong);
        --kp-kbd-ground: var(--card);
        --kp-kbd-foot: 3px;
    }
    /* Washi tape: the track's edge is the dashed cut of a tape, not a rule. */
    [data-theme='pastel'] .kp-segmented:not(.kp-segmented--chips) {
        border-style: dashed;
    }
    [data-theme='pastel'] .kp-segmented--chips > .kp-segmented__item[aria-pressed='true'] {
        box-shadow: 0 3px 0 var(--kp-sig-pa-peel, hsl(from var(--primary) h s calc(l * 0.55)));
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — pastel: a sheet with washi tape. The current tab is a strip of washi tape stuck on the bar's top edge, a hair off true, with one soft overshoot; pointing lifts the tab, a press sticks it down; a count is a sticker (G3, G10, G14, G16). */
    [data-theme='pastel'] .kp-tabbar {
        border-block-start: 2px dashed var(--border-strong);
    }

    [data-theme='pastel'] .kp-tabbar__tab {
        border-radius: var(--radius);
    }

    [data-theme='pastel'] .kp-tabbar__tab::before {
        inset-inline: 0.75rem;
        inset-block-start: calc(-1 * var(--kp-tabbar-pad, 0.25rem) - 0.4rem);
        block-size: 0.7rem;
        border-radius: 2px;
        background: repeating-linear-gradient(-45deg, hsl(from var(--primary) h s l / 0.85) 0 5px, hsl(from var(--primary) h s l / 0.55) 5px 10px);
        rotate: -1.5deg;
        scale: 0 1;
    }

    [data-theme='pastel'] .kp-tabbar__tab[aria-current]:not([aria-current='false'])::before {
        scale: 1 1;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-tabbar__tab {
            transition:
                color var(--fx-duration) var(--fx-ease),
                translate var(--fx-duration) var(--fx-ease);
        }

        [data-theme='pastel'] .kp-tabbar__tab:hover {
            translate: 0 -2px;
        }
    }

    [data-theme='pastel'] .kp-tabbar__tab:active {
        translate: 0 0;
    }

    [data-theme='pastel'] .kp-tabbar__badge {
        rotate: 6deg;
        border: 2px solid var(--card);
    }
}

/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Pastel's own (themes/pastel/CHARACTER.md): a tile is a sticker on its flat plum peel, a plate's round corner (G6, G7);
   pointing lifts it 2 px on its peel and curls its top-end corner into a fold of its back (G14); a press sticks it down
   flat (G16); focus is the dashed plum line alone (G15); a tone is a sticker on its own plate with its own peel, never an
   edge (G8); what waits becomes the pom-pom caterpillar (G10, b-bug-6): a heat grid's row of cells is one caterpillar
   (js/loading-pieces.js), the matrix and the counts are pom-poms whose hump runs through them; what runs is washi tape,
   its stripes drifting start to end. Every motion on the landing curve. */
@layer kp.signature {
    [data-theme='pastel'] .kp-actions {
        --kp-actions-gap: 0.875rem;
    }
    [data-theme='pastel'] .kp-action {
        --kp-action-radius: var(--kp-sig-pa-r-plate);
        --kp-action-edge: var(--border-strong);
        --kp-action-edge-hover: var(--border-strong);
        --kp-action-shadow: 0 3px 0 var(--kp-sig-pa-peel);
        --kp-action-shadow-hover: 0 5px 0 var(--kp-sig-pa-peel);
        --kp-action-shadow-active: 0 0 0 var(--kp-sig-pa-peel);
        --kp-action-ground-active: var(--card);
        --kp-action-lift: 0 -2px;
        --kp-action-press: 0 3px;
        --kp-action-title-weight: 700;
    }
    /* The fold: the ground where the corner lifted off, the sticker's back below the crease (the key figure's). */
    [data-theme='pastel'] .kp-action::after,
    [data-theme='pastel'] .kp-action--destructive::after {
        content: '';
        position: absolute;
        z-index: 1;
        inset: -1px -1px auto auto;
        inset-block: -1px auto;
        inset-inline: auto -1px;
        inline-size: 0.85rem;
        block-size: 0.85rem;
        border-radius: 0;
        border-start-end-radius: var(--kp-sig-pa-r-plate);
        border-end-start-radius: 0.4rem;
        background: linear-gradient(calc(225deg - 90deg * (1 - var(--kp-sig-pa-dir))), var(--kp-sig-pa-ground) 0 50%, var(--muted) 50% 100%);
        box-shadow: calc(-1px * var(--kp-sig-pa-dir)) 1px 0 hsl(from var(--border-strong) h s l / 0.7);
        scale: 0;
        transform-origin: calc(50% + 50% * var(--kp-sig-pa-dir)) 0;
        pointer-events: none;
    }
    [data-theme='pastel'] .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'], :active))::after {
        scale: 1;
    }
    [data-theme='pastel'] .kp-action:focus-visible {
        outline: 2px dashed var(--ring);
        outline-offset: 3px;
        box-shadow: var(--kp-action-shadow);
    }
    [data-theme='pastel'] .kp-action:is(:disabled, [aria-disabled='true']) {
        box-shadow: 0 3px 0 var(--border);
    }
    /* Destructive: a tone is a sticker. The title stands on the red's own plate with its own flat peel. */
    [data-theme='pastel'] .kp-action--destructive {
        --kp-action-tone-edge: var(--border-strong);
        --kp-action-tone-edge-hover: var(--border-strong);
    }
    [data-theme='pastel'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) > .kp-action__title {
        justify-self: start;
        padding: 0.05rem 0.5rem;
        border-radius: var(--kp-sig-pa-r-ctl);
        background: var(--destructive);
        color: var(--destructive-foreground);
        box-shadow: 0 2px 0 hsl(from var(--destructive) h s calc(l * 0.6));
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-action {
            transition:
                translate var(--fx-duration) var(--kp-sig-pa-land),
                box-shadow var(--fx-duration) var(--kp-sig-pa-land),
                background-color var(--fx-duration) ease,
                border-color var(--fx-duration) ease;
        }
        [data-theme='pastel'] .kp-action::after {
            transition: scale var(--fx-duration) var(--kp-sig-pa-land);
        }
    }

    /* Status rows: white paper with its sky pass off register beside it, a control's corner. A failed row's reason is
       a sticker on the red's plate; an empty row is a dashed outline with no pass. Marks stand upright. */
    [data-theme='pastel'] .kp-statuslist {
        --kp-statuslist-gap: 0.75rem;
    }
    [data-theme='pastel'] .kp-statusrow {
        --kp-statusrow-radius: var(--kp-sig-pa-r-ctl);
        --kp-statusrow-edge: var(--border-strong);
        box-shadow: calc(4px * var(--kp-sig-pa-dir)) 4px 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-statusrow[data-state='failed'] {
        --kp-statusrow-state-edge: var(--border-strong);
    }
    [data-theme='pastel'] .kp-statusrow[data-state='failed'] .kp-statusrow__detail {
        justify-self: start;
        margin-block-start: 0.2rem;
        padding: 0 0.45rem;
        border-radius: var(--kp-sig-pa-r-ctl);
        background: var(--destructive);
        color: var(--destructive-foreground);
        box-shadow: 0 2px 0 hsl(from var(--destructive) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-statusrow[data-state='empty'] {
        border-style: dashed;
        box-shadow: none;
    }

    /* Facets: entries of a list, a menu entry's corner and its mint wash. The counts on their way are pom-poms of
       the caterpillar standing in their column, the hump running down the list. */
    [data-theme='pastel'] .kp-facets {
        --kp-facet-radius: calc(var(--kp-sig-pa-r-ctl) * 0.8);
    }
    [data-theme='pastel'] .kp-facet {
        --kp-facet-hover: var(--accent);
    }
    [data-theme='pastel'] .kp-facet:hover {
        color: var(--accent-foreground);
    }
    [data-theme='pastel'] .kp-facets[aria-busy='true'] .kp-facet__count {
        border-radius: 0;
        background:
            radial-gradient(circle closest-side, var(--accent) 0 calc(100% - 0.5px), transparent 100%) 100% 50% / 1.1em 1.1em no-repeat,
            radial-gradient(circle, var(--kp-sig-pa-tape-stripe) 0.6px, transparent 1.1px) 0 0 / 3px 3px;
        -webkit-mask: radial-gradient(circle closest-side, var(--foreground) 0 calc(100% - 0.5px), transparent 100%) 100% 50% / 1.1em 1.1em no-repeat;
        mask: radial-gradient(circle closest-side, var(--foreground) 0 calc(100% - 0.5px), transparent 100%) 100% 50% / 1.1em 1.1em no-repeat;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-facets[aria-busy='true'] .kp-facet__count {
            animation: kp-sig-pastel-bug-rise calc(var(--kp-sig-pa-loop) / 2) ease-in-out infinite;
        }
        [data-theme='pastel'] .kp-facets[aria-busy='true'] li:nth-child(2) .kp-facet__count {
            animation-delay: 140ms;
        }
        [data-theme='pastel'] .kp-facets[aria-busy='true'] li:nth-child(3) .kp-facet__count {
            animation-delay: 280ms;
        }
        [data-theme='pastel'] .kp-facets[aria-busy='true'] li:nth-child(4) .kp-facet__count {
            animation-delay: 420ms;
        }
        [data-theme='pastel'] .kp-facets[aria-busy='true'] li:nth-child(n + 5) .kp-facet__count {
            animation-delay: 560ms;
        }
    }

    /* Heat grid and matrix: small stickers with a flat pass; pointing lifts a cell 2 px, a press sticks it down; the
       pin is the dashed plum line. Waiting: a heat row is one caterpillar (its cells give their place to it), a matrix
       cell is a pom-pom, the hump running along the row to the head at its end. */
    [data-theme='pastel'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-radius: 6px;
        --kp-heat-cell-gap: 4px;
        --kp-heat-cell-lift: calc(1.5px * var(--kp-sig-pa-dir)) 1.5px 0 var(--kp-sig-pa-pass-c);
        --kp-heat-cell-hover: translateY(-2px);
        --kp-matrix-cell-hover: translateY(-2px);
    }
    [data-theme='pastel'] .kp-matrix {
        --kp-heat-cell-radius: calc(var(--kp-sig-pa-r-ctl) * 0.7);
        --kp-matrix-gap: 5px;
    }
    [data-theme='pastel'] .kp-heat {
        --kp-heat-gap-y: 6px;
    }
    [data-theme='pastel'] .kp-heat__cell:active:not(.kp-skeleton, [aria-disabled='true']),
    [data-theme='pastel'] .kp-matrix__cell:active:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
        transform: translateY(1.5px);
        box-shadow: none;
    }
    [data-theme='pastel'] .kp-heat__cell[data-kp-picked],
    [data-theme='pastel'] .kp-matrix__cell[aria-pressed='true'] {
        outline: 2px dashed var(--primary);
        outline-offset: 2px;
    }
    [data-theme='pastel'] :is(.kp-heat__label-button, .kp-matrix__name) {
        border-radius: var(--kp-sig-pa-r-chip);
    }
    [data-theme='pastel'] .kp-heat__label-button[aria-pressed='true'] {
        background: var(--accent);
        color: var(--accent-foreground);
    }
    [data-theme='pastel'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton) {
        position: relative;
    }
    [data-theme='pastel'] .kp-heat__cells[data-kp-pieces] > .kp-heat__cell.kp-skeleton {
        visibility: hidden;
    }
    [data-theme='pastel'] .kp-heat__cell.kp-skeleton {
        border-radius: 6px;
        box-shadow: none;
    }
    [data-theme='pastel'] .kp-matrix__cell.kp-skeleton {
        border: 0;
        border-radius: 0;
        box-shadow: none;
        background:
            radial-gradient(circle, var(--kp-sig-pa-tape-stripe) 0.6px, transparent 1.1px) 0 0 / 3px 3px,
            var(--accent);
        -webkit-mask: radial-gradient(circle closest-side, var(--foreground) 0 calc(100% - 0.5px), transparent 100%) 50% 50% / 2.2rem 2.2rem no-repeat;
        mask: radial-gradient(circle closest-side, var(--foreground) 0 calc(100% - 0.5px), transparent 100%) 50% 50% / 2.2rem 2.2rem no-repeat;
    }
    /* The head: plum with two paper eyes looking along the row. */
    [data-theme='pastel'] .kp-matrix__line > .kp-matrix__cell.kp-skeleton:last-child {
        background:
            radial-gradient(circle at calc(50% + 0.3rem * var(--kp-sig-pa-dir)) 42%, var(--primary) 0 0.12rem, transparent 0.16rem),
            radial-gradient(circle at calc(50% + 0.75rem * var(--kp-sig-pa-dir)) 42%, var(--primary) 0 0.12rem, transparent 0.16rem),
            radial-gradient(circle at calc(50% + 0.3rem * var(--kp-sig-pa-dir)) 42%, var(--card) 0 0.3rem, transparent 0.34rem),
            radial-gradient(circle at calc(50% + 0.75rem * var(--kp-sig-pa-dir)) 42%, var(--card) 0 0.3rem, transparent 0.34rem), var(--primary);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-matrix__cell.kp-skeleton {
            animation: kp-sig-pastel-bug-rise calc(var(--kp-sig-pa-loop) / 2) ease-in-out infinite;
        }
        [data-theme='pastel'] .kp-matrix__cell.kp-skeleton:nth-child(3) {
            animation-delay: 140ms;
        }
        [data-theme='pastel'] .kp-matrix__cell.kp-skeleton:nth-child(4) {
            animation-delay: 280ms;
        }
        [data-theme='pastel'] .kp-matrix__cell.kp-skeleton:nth-child(5) {
            animation-delay: 420ms;
        }
        [data-theme='pastel'] .kp-matrix__cell.kp-skeleton:nth-child(6) {
            animation-delay: 560ms;
        }
        [data-theme='pastel'] .kp-matrix__cell.kp-skeleton:nth-child(n + 7) {
            animation-delay: 700ms;
        }
        [data-theme='pastel'] :is(.kp-heat__cell, .kp-matrix__cell) {
            transition:
                transform var(--fx-duration) var(--kp-sig-pa-land),
                box-shadow var(--fx-duration) var(--kp-sig-pa-land);
        }
    }
    [data-theme='pastel'] .kp-bar-cell {
        --kp-bar-cell-gap: 0.625rem;
        font-variant-numeric: tabular-nums;
    }
    /* The figure's ghost is one pom-pom row the height of the figure's line: no skeleton gap, so a row that waits is as
       tall as the row it waits for. */
    [data-theme='pastel'] .kp-bar-cell__ghost.kp-skeleton {
        margin-block: 0;
        block-size: var(--kp-bar-cell-ghost-height, 0.625rem);
    }

    /* Week agenda and run timeline: pill stickers with a flat plum peel 2 px under them; pointing lifts a pill on its
       peel, a press sticks it down; the next run has a plum ring; the line for now is plum with a pearl at its head. A
       running run is washi tape, its stripes drifting start to end; a queued one a dashed pill. */
    [data-theme='pastel'] .kp-week {
        --kp-week-pill-radius: var(--kp-sig-pa-r-chip);
        --kp-week-now: var(--primary);
    }
    [data-theme='pastel'] .kp-gantt {
        --kp-gantt-state-ground: var(--card);
        --kp-gantt-bar-radius: var(--kp-sig-pa-r-chip);
        --kp-gantt-now: var(--primary);
    }
    [data-theme='pastel'] .kp-week__pill {
        padding-inline: 0.625rem;
        box-shadow: 0 2px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-week__pill:is(button):hover {
        translate: 0 -2px;
        box-shadow: 0 4px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-week__pill:is(button):active {
        translate: 0 2px;
        box-shadow: 0 0 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-week__pill[data-kp-state='next'] {
        box-shadow:
            0 0 0 2px var(--primary),
            0 3px 0 1px var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-week__pill:is([data-kp-state='off'], [data-kp-state='skipped'], [data-kp-state='reference']) {
        box-shadow: none;
    }
    [data-theme='pastel'] .kp-week__pill:focus-visible {
        outline-offset: 1px;
    }
    [data-theme='pastel'] .kp-gantt__label {
        padding-inline: 0.625rem;
    }
    [data-theme='pastel'] .kp-gantt__run:is(button):hover {
        translate: 0 -1px;
        box-shadow: 0 2px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-gantt__run[data-kp-state='queued'] {
        border-style: dashed;
        border-width: 1.5px;
    }
    [data-theme='pastel'] :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='running'] {
        border-color: var(--kp-sig-pa-peel);
        background: var(--kp-sig-pa-tape-bg);
        color: var(--accent-foreground);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-gantt__run[data-kp-state='running'] {
            animation: kp-sig-pastel-tape-drift 600ms linear infinite;
        }
        [data-theme='pastel'] :is(.kp-week__pill, .kp-gantt__run) {
            transition:
                translate var(--fx-duration) var(--kp-sig-pa-land),
                box-shadow var(--fx-duration) var(--kp-sig-pa-land);
        }
    }

    /* The tape's stripes drift one stripe start to end. */
    @keyframes kp-sig-pastel-tape-drift {
        from {
            background-position:
                0 0,
                0 0;
        }

        to {
            background-position:
                12px 0,
                0 0;
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='pastel'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='pastel'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='pastel'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='pastel'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='pastel'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='pastel'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Pastel's own (themes/pastel/CHARACTER.md): the separator is the divider's row of plum beads, stood upright,
   and lying down across the phone's list as a dotted bead line. A day on the axis is a sticker: pointing lifts it on
   its plum peel, pressed it is stuck down, the pink chip in a plum ring (G5). A series' finished run stands on a peel of
   its own colour; the upcoming list's day rule is the beads; the facet pattern is a rounded sticker on a little peel. */
@layer kp.signature {
    [data-theme='pastel'] .kp-nav__sep {
        inline-size: 4px;
        border-inline-start: 0;
        background: radial-gradient(circle, var(--primary) 0 1.5px, transparent 2px) center / 4px 7px repeat-y;
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='pastel'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            inline-size: auto;
            block-size: 4px;
            border-block-start: 0;
            background: radial-gradient(circle, var(--primary) 0 1.5px, transparent 2px) center / 7px 4px repeat-x;
        }
    }

    [data-theme='pastel'] .kp-gantt__tick:is(button) {
        border-radius: var(--kp-sig-pa-r-chip, 999px);
        text-decoration: none;
    }
    [data-theme='pastel'] .kp-gantt__tick:is(button):hover {
        background: var(--card);
        color: var(--foreground);
        box-shadow:
            inset 0 0 0 1px var(--border),
            0 2px 0 var(--kp-sig-pa-peel);
        translate: 0 -1px;
    }
    [data-theme='pastel'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: color-mix(in oklab, var(--primary) 18%, var(--card));
        color: var(--primary);
        box-shadow: inset 0 0 0 1.5px var(--primary);
        translate: 0 0;
    }
    [data-theme='pastel'] .kp-gantt__run[data-kp-state='ok'][data-kp-series] {
        box-shadow: 0 2px 0 hsl(from var(--kp-gantt-series) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-week__next:not(:has(+ .kp-week__next:not([data-kp-day-start]))) {
        border-block-end-style: dotted;
        border-block-end-width: 2px;
        border-block-end-color: hsl(from var(--primary) h s l / 0.55);
    }
    [data-theme='pastel'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 5px;
        box-shadow: 0 1.5px 0 hsl(from var(--kp-facet-swatch-colour, var(--primary)) h s calc(l * 0.6));
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-gantt__tick:is(button) {
            transition:
                translate var(--fx-duration) var(--kp-sig-pa-land, var(--fx-ease)),
                box-shadow var(--fx-duration) var(--kp-sig-pa-land, var(--fx-ease));
        }
    }
}

/* ── The fourth adoption round in this theme [kpadopt4]: data pieces ──
   Pastel's own (themes/pastel/CHARACTER.md): a mark, a plate or a part is a sticker or a taped-in note. A mark stands on
   its flat peel, a figure that says a tone is a sticker on the tone's plate with its own peel (G8), what is pointed at
   lifts on its peel (G14), a live number wobbles round its foot (G9), a ruled line is a thread of pearls (G18), and a
   plate that is stuck to the page carries one strip of washi tape (G7). The part that is held in the hand carries none.
   Every colour is a token; every motion sits under no-preference and lands on the soft landing (G1). */
@layer kp.signature {
    /* Identity mark: a sticker, its flat peel under it in its own darker colour; the current one in a list is ringed by
       the dashed plum line, kept off its neighbours by the paper's edge; a group of marks is stuck down overlapping. */
    [data-theme='pastel'] .kp-idmark {
        box-shadow: 0 calc(var(--kp-idmark-s) * 0.05) 0 hsl(from var(--kp-idmark-c) h s calc(l * 0.6));
        font-weight: 700;
    }
    [data-theme='pastel'] .kp-idmark:is(.kp-skeleton, [data-kp-idmark-empty]) {
        box-shadow: none;
    }
    [data-theme='pastel'] .kp-idmark[aria-current]:not([aria-current='false']),
    [data-theme='pastel'] .kp-idmark[data-kp-idmark-selected] {
        outline: 2px dashed var(--primary);
        outline-offset: 3px;
        box-shadow: 0 calc(var(--kp-idmark-s) * 0.05) 0 hsl(from var(--kp-idmark-c) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-idmark-group > :is(.kp-idmark, .kp-idmark-group__more) {
        box-shadow: 0 0 0 2px var(--card);
    }
    [data-theme='pastel'] .kp-idmark-group__more {
        border-radius: var(--kp-idmark-radius, min(var(--radius, 1rem), calc(var(--kp-idmark-s) * 0.28)));
        font-weight: 700;
    }
    [data-theme='pastel'] .kp-idmark--glyph::after {
        border-radius: 3px;
    }
    [data-theme='pastel'] .kp-idmark--glyph[data-kp-idmark-glyph='circle']::after {
        border-radius: 50%;
    }

    /* Share bar: one pill with its sky pass beside it; the part pointed at lifts out of the bar on its own peel and its
       legend row takes the mint wash; the threshold is a pearl on its thread; a swatch is a pearl. */
    [data-theme='pastel'] .kp-stackbar {
        --kp-stackbar-radius: 999px;
    }
    [data-theme='pastel'] .kp-stackbar:not([aria-busy='true']) .kp-stackbar__bar {
        box-shadow: calc(3px * var(--kp-sig-pa-dir)) 3px 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-stackbar__seg[data-kp-stackbar-lit] {
        border-radius: 999px;
        translate: 0 -2px;
        box-shadow:
            inset calc(var(--kp-stackbar-gap, 2px) * -1) 0 0 var(--card),
            0 3px 0 hsl(from var(--kp-stackbar-colour, var(--chart-1)) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-stackbar__mark {
        inline-size: 2px;
        background: var(--primary);
        box-shadow: none;
    }
    [data-theme='pastel'] .kp-stackbar__mark::before {
        content: '';
        position: absolute;
        inset-block-start: -0.3rem;
        inset-inline-start: 50%;
        inline-size: 0.5rem;
        block-size: 0.5rem;
        translate: calc(-50% * var(--kp-sig-pa-dir)) 0;
        border-radius: 50%;
        background: var(--primary);
        box-shadow: 0 0 0 2px var(--card);
    }
    [data-theme='pastel'] .kp-stackbar__swatch {
        border-radius: 50%;
        box-shadow: 0 1.5px 0 hsl(from var(--kp-stackbar-colour, var(--chart-1)) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-stackbar__item {
        border-radius: var(--kp-sig-pa-r-ctl);
    }
    [data-theme='pastel'] .kp-stackbar__item[data-kp-stackbar-lit] {
        background: var(--accent);
        color: var(--accent-foreground);
    }
    [data-theme='pastel'] .kp-stackbar__item[data-kp-stackbar-lit] .kp-stackbar__value {
        color: inherit;
    }
    [data-theme='pastel'] .kp-stackbar__note {
        border-radius: var(--kp-sig-pa-r-plate);
        border-width: 2px;
    }

    /* Bullet rows: a row that leads somewhere takes the mint wash of a hovered entry on its menu corner; a figure that
       says a tone is a sticker on the tone's plate with its own peel. */
    [data-theme='pastel'] .kp-bullets__row {
        border-radius: var(--kp-sig-pa-r-ctl);
    }
    [data-theme='pastel'] .kp-bullets__row:has(.kp-bullets__link:hover) {
        background: var(--accent);
        color: var(--accent-foreground);
    }
    [data-theme='pastel'] .kp-bullets__row:has(.kp-bullets__link:hover) .kp-bullets__label {
        text-decoration: none;
    }
    [data-theme='pastel'] .kp-bullets__row:has(.kp-bullets__link:hover) .kp-bullets__detail {
        color: inherit;
    }
    [data-theme='pastel'] .kp-bullets__row:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-bullets__figure {
        padding-inline: 0.55em;
        border-radius: var(--kp-sig-pa-r-ctl);
    }
    [data-theme='pastel'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure {
        box-shadow: 0 2px 0 hsl(from var(--warning) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        box-shadow: 0 2px 0 hsl(from var(--destructive) h s calc(l * 0.6));
    }

    /* Key-value grid and form rows: a ruled line is a thread of pearls; a row changed and not saved, or one that could
       not be read, is marked by a pearl in the gap before its label, never a bar. */
    [data-theme='pastel'] :is(.kp-kv--lines > .kp-kv__row, .kp-formrows--lines > .kp-formrow) {
        border-block-end: 2px dotted var(--border-strong);
    }
    [data-theme='pastel'] :is(.kp-kv--lines > .kp-kv__row:last-child, .kp-formrows--lines > .kp-formrow:last-child) {
        border-block-end: 0;
    }
    [data-theme='pastel'] .kp-kv__row[data-kp-state='error']::before,
    [data-theme='pastel'] .kp-formrow[data-kp-changed]::before,
    [data-theme='pastel'] .kp-formrow[data-kp-state='error']::before {
        inset-block: 0.65em auto;
        inset-inline-start: calc(var(--kp-space-sm, 0.5rem) * -1 - 4px);
        inline-size: 8px;
        block-size: 8px;
        border-radius: 50%;
    }
    [data-theme='pastel'] .kp-formrow:is([data-kp-changed], [data-kp-state='error'])::before {
        inset-block-start: 1rem;
    }
    [data-theme='pastel'] .kp-kv__row[data-kp-changed] > dt::after {
        font-size: 1.25em;
        line-height: 0;
    }
    [data-theme='pastel'] .kp-formrow__lock {
        padding-inline: 0.55em;
        border-radius: var(--kp-sig-pa-r-chip);
        background: var(--muted);
    }

    /* Code block: a plate stuck to the page, its sky pass 6 px off register and one strip of washi tape across its top
       start edge; the head is cut from the body by the tape's dashed edge, the keys are plum. */
    [data-theme='pastel'] .kp-code {
        border-radius: var(--kp-sig-pa-r-plate);
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-code::before {
        content: '';
        position: absolute;
        z-index: 2;
        inset-block-start: -0.35rem;
        inset-inline-start: 1.25rem;
        inline-size: 3.5rem;
        block-size: 0.8rem;
        border-radius: 2px;
        background: var(--kp-sig-pa-tape-bg);
        rotate: -2deg;
        pointer-events: none;
    }
    [data-theme='pastel'] :is(.kp-code__head, .kp-code__foot) {
        border-color: var(--border-strong);
        border-style: dashed;
        border-width: 0;
    }
    [data-theme='pastel'] .kp-code__head {
        border-block-end-width: 2px;
        padding-block-start: calc(var(--kp-space-xs, 0.25rem) + 0.25rem);
    }
    [data-theme='pastel'] .kp-code__foot {
        border-block-start-width: 2px;
    }
    [data-theme='pastel'] .kp-code__head {
        border-start-start-radius: inherit;
        border-start-end-radius: inherit;
    }

    /* A live number wobbles once round its foot as it counts (G9), 800 ms, its second pass staying where it is. */
    [data-theme='pastel'] [data-kp-tick] {
        display: inline-block;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] [data-kp-tick][data-kp-tick-state='running'] {
            transform-origin: 50% 100%;
            animation: kp-sig-pastel-update-wobble var(--kp-sig-pa-wobble) ease-out;
        }
    }
}

/* ── Rows, cards and choices [kpadopt4]: tiles, status rows, the action list ── */
@layer kp.signature {
    /* Choice tiles: a sticker on its flat peel; pointing lifts it 2 px on its peel, a press sticks it down flat, the
       chosen one is mint paper with a plum edge and no peel of its own (it is stuck down), focus is the dashed line. */
    [data-theme='pastel'] .kp-fieldset[data-kp-layout='tiles'] {
        --kp-field-tile-radius: var(--kp-sig-pa-r-plate);
        --kp-field-tiles-gap: 0.875rem;
    }
    [data-theme='pastel'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
        border-color: var(--border-strong);
        box-shadow: 0 3px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:hover:not(:has(> .kp-field__check:disabled)) {
        border-color: var(--border-strong);
        translate: 0 -2px;
        box-shadow: 0 5px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:active:not(:has(> .kp-field__check:disabled)) {
        translate: 0 3px;
        box-shadow: 0 0 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:checked) {
        --kp-field-tile-ground-checked: color-mix(in oklab, var(--accent) 55%, var(--card));
        border-color: var(--primary);
        box-shadow: 0 0 0 1px var(--primary);
        translate: 0 3px;
    }
    [data-theme='pastel'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:focus-visible) {
        outline: 2px dashed var(--ring);
        outline-offset: 3px;
    }
    [data-theme='pastel'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:disabled) {
        box-shadow: 0 3px 0 var(--border);
    }
    [data-theme='pastel'] .kp-fieldset[data-kp-layout='tiles'][aria-invalid='true'],
    [data-theme='pastel'] .kp-fieldset[data-kp-layout='tiles'][data-kp-invalid] {
        outline: 2px dashed var(--destructive);
        outline-offset: 4px;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
            transition:
                translate var(--fx-duration) var(--kp-sig-pa-land),
                box-shadow var(--fx-duration) var(--kp-sig-pa-land),
                background-color var(--fx-duration) ease,
                border-color var(--fx-duration) ease;
        }
    }

    /* A check that passes with a reservation: a sticker on the warning's plate with its own peel, as the failed row's
       reason is on the red's. The fix, written out, is a taped-in note: mint paper in a dashed edge. */
    [data-theme='pastel'] .kp-statusrow[data-state='warn'] {
        --kp-statusrow-state-edge: var(--border-strong);
    }
    [data-theme='pastel'] .kp-statusrow[data-state='warn'] .kp-statusrow__mark {
        box-shadow: 0 2px 0 hsl(from var(--warning) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-statusrow[data-state='warn'] .kp-statusrow__detail {
        justify-self: start;
        margin-block-start: 0.2rem;
        padding: 0 0.45rem;
        border-radius: var(--kp-sig-pa-r-ctl);
        background: var(--warning);
        color: var(--warning-foreground);
        box-shadow: 0 2px 0 hsl(from var(--warning) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-statusrow__fix {
        padding: 0.25rem 0.7rem;
        border: 2px dashed hsl(from var(--accent-foreground) h s l / 0.45);
        border-radius: var(--kp-sig-pa-r-ctl);
        background: color-mix(in oklab, var(--accent) 45%, var(--card));
        color: var(--foreground);
    }

    /* The action list with a lead: a row is a strip of paper on a rule of pearls; its state is a washi bar on the start
       edge with round ends, the severity dot a pearl; the next one is mint and its date a mint sticker; a group's
       heading is a sentence, not capitals (G17); a payload is a taped-in note. */
    [data-theme='pastel'] .kp-action-list--lead > li {
        border-radius: var(--kp-sig-pa-r-ctl);
    }
    [data-theme='pastel'] .kp-action-list--lead > li:not(.kp-action-list__group) {
        border-inline-start-width: 5px;
        border-start-start-radius: 5px;
        border-end-start-radius: 5px;
    }
    [data-theme='pastel'] .kp-action-list--lead > li[data-kp-state='next'] {
        background: color-mix(in oklab, var(--accent) 38%, transparent);
    }
    [data-theme='pastel'] .kp-action-list--lead > li[data-kp-state='next'] > .kp-action-list__lead .kp-action-list__when {
        padding: 0.2rem 0.6rem;
        border-radius: var(--kp-sig-pa-r-ctl);
        background: var(--accent);
        color: var(--accent-foreground);
        box-shadow: 0 2px 0 hsl(from var(--accent) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-action-list > li.kp-action-list__group {
        font-size: var(--kp-text-sm, 0.8125rem);
        letter-spacing: 0;
        text-transform: none;
    }
    [data-theme='pastel'] .kp-action-list__payload {
        border: 2px dashed var(--border-strong);
        border-radius: var(--kp-sig-pa-r-ctl);
    }
    [data-theme='pastel'] .kp-action-list__more > summary {
        border-radius: var(--kp-sig-pa-r-chip);
    }

    /* A secret: the value is a label taped on (a dashed edge); the time left drains as a strip of washi tape, peeled
       from its end along the line; a failure to read is a sticker on the red's plate. */
    [data-theme='pastel'] .kp-secret {
        --kp-secret-drain-size: 6px;
    }
    [data-theme='pastel'] .kp-secret__value {
        border: 2px dashed var(--border-strong);
        border-radius: var(--kp-sig-pa-r-ctl);
        background: var(--card);
    }
    [data-theme='pastel'] .kp-secret[data-kp-secret-state='disabled'] .kp-secret__value {
        background: var(--muted);
    }
    [data-theme='pastel'] .kp-secret__drain {
        border-radius: 2px;
        background: var(--kp-sig-pa-tape-bg);
        transform-origin: 0 50%;
    }
    [data-theme='pastel'] .kp-secret__drain:dir(rtl) {
        transform-origin: 100% 50%;
    }
    [data-theme='pastel'] .kp-secret[data-kp-secret-state='error'] .kp-secret__words {
        padding: 0 0.55rem;
        border-inline-start: 0;
        border-radius: var(--kp-sig-pa-r-ctl);
        background: var(--destructive);
        color: var(--destructive-foreground);
        box-shadow: 0 2px 0 hsl(from var(--destructive) h s calc(l * 0.6));
    }

    /* A dialog in sections: a section's rule is a thread of pearls; a danger section has a round-ended bar; what still
       depends on the thing is a taped-in note (a dashed edge on paper); the name to type is a marked word on mint. */
    [data-theme='pastel'] .kp-dialog__section {
        border-block-start: 2px dotted var(--border-strong);
    }
    [data-theme='pastel'] .kp-dialog__section:first-child {
        border-block-start: 0;
    }
    [data-theme='pastel'] .kp-dialog__section--danger {
        border-inline-start-width: 5px;
        border-radius: 5px;
    }
    [data-theme='pastel'] :is(.kp-confirm__dependents, .kp-type-confirm__loses) {
        border: 2px dashed var(--border-strong);
        border-radius: var(--kp-sig-pa-r-ctl);
        background: var(--card);
    }
    [data-theme='pastel'] .kp-type-confirm__loses-title {
        justify-self: start;
        padding: 0 0.55rem;
        border-radius: var(--kp-sig-pa-r-ctl);
        background: var(--destructive);
        color: var(--destructive-foreground);
        box-shadow: 0 2px 0 hsl(from var(--destructive) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-type-confirm__name {
        padding: 0 0.4em;
        border-radius: 0.4rem;
        background: var(--accent);
        color: var(--accent-foreground);
    }
    [data-theme='pastel'] .kp-type-confirm__status[data-kp-matched] {
        color: var(--foreground);
        font-weight: 600;
    }
}

/* ── Time and flows [kpadopt4]: moments, the journey, the pipeline, the drawings ── */
@layer kp.signature {
    /* Moments on the run timeline: a moment is a pearl with its flat peel, a planned one a dashed ring; pointing lifts
       it 2 px on a longer peel; a count on a cluster is a sticker; a stretch is washi tape in the tone's own stripes,
       an area across the lanes the dotted edge of a cut-out; the dated line stands on a thread of pearls. */
    [data-theme='pastel'] :is(.kp-gantt__point, .kp-gantt__mark)::before {
        box-shadow: 0 1.5px 0 hsl(from var(--kp-gantt-mark) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-gantt__point[data-kp-planned]::before {
        border-style: dashed;
        box-shadow: none;
    }
    [data-theme='pastel'] .kp-gantt__point:hover::before {
        translate: 0 -2px;
        box-shadow: 0 3.5px 0 hsl(from var(--kp-gantt-mark) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-gantt__count {
        border: 0;
        border-radius: var(--kp-sig-pa-r-chip);
        box-shadow: 0 1.5px 0 var(--kp-sig-pa-peel);
        padding-inline: 0.3125rem;
    }
    [data-theme='pastel'] .kp-gantt__zone {
        border-inline-style: dotted;
        border-inline-width: 2px;
    }
    [data-theme='pastel'] .kp-gantt__zone[data-kp-lane-zone] {
        background: repeating-linear-gradient(
            90deg,
            hsl(from var(--kp-gantt-mark) h s l / 0.7) 0 6px,
            hsl(from var(--kp-gantt-mark) h s l / 0.3) 6px 12px
        );
    }
    [data-theme='pastel'] .kp-gantt--line :is(.kp-gantt__corner, .kp-gantt__axis) {
        border-block-start: 3px dotted var(--border-strong);
    }
    [data-theme='pastel'] .kp-gantt__lane-link {
        text-decoration-style: dotted;
        text-decoration-thickness: 2px;
    }

    /* A journey: the steps are stickers strung on a thread of pearls; a reached step is a plum sticker on its peel, the
       step it stands at a paper sticker with its sky pass off register and the dot of the step's colour. */
    [data-theme='pastel'] .kp-steplist--journey {
        --kp-journey-rule: 4px;
    }
    [data-theme='pastel'] .kp-steplist--journey > .kp-steplist__item + .kp-steplist__item::before {
        background: radial-gradient(circle closest-side, var(--border-strong) 0 1.5px, transparent 2px) 0 50% / 8px 100% repeat-x;
    }
    [data-theme='pastel'] .kp-steplist--journey > .kp-steplist__item:is([data-state='done'], [data-state='current'])::before {
        background: radial-gradient(circle closest-side, var(--kp-step-tone, var(--primary)) 0 1.5px, transparent 2px) 0 50% / 8px 100% repeat-x;
    }
    [data-theme='pastel'] .kp-steplist--journey > .kp-steplist__item[data-state='failed']::before {
        background: repeating-linear-gradient(90deg, var(--destructive) 0 0.375rem, transparent 0.375rem 0.625rem);
    }
    [data-theme='pastel'] .kp-steplist--journey .kp-steplist__mark {
        border-width: 2px;
        box-shadow: 0 2px 0 hsl(from var(--kp-step-tone, var(--border-strong)) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-steplist--journey .kp-steplist__item[data-state='done']:not([data-kp-tone]) .kp-steplist__mark {
        border-color: var(--primary);
        background-color: var(--primary);
        color: var(--primary-foreground);
        box-shadow: 0 2px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-steplist--journey .kp-steplist__item[data-state='current'] .kp-steplist__mark {
        box-shadow: calc(3px * var(--kp-sig-pa-dir)) 3px 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-steplist--journey .kp-steplist__item:is([data-state='skipped'], [data-state='pending'], :not([data-state])) .kp-steplist__mark {
        box-shadow: none;
    }
    @container kp-journey (max-width: 30rem) {
        [data-theme='pastel'] .kp-steplist--journey > .kp-steplist__item:not(:last-child)::after {
            background: radial-gradient(circle closest-side, var(--border-strong) 0 1.5px, transparent 2px) 50% 0 / 100% 8px repeat-y;
        }
        [data-theme='pastel']
            .kp-steplist--journey
            > .kp-steplist__item:has(+ .kp-steplist__item:is([data-state='done'], [data-state='current']))::after {
            background: radial-gradient(circle closest-side, var(--kp-step-tone, var(--primary)) 0 1.5px, transparent 2px) 50% 0 / 100% 8px repeat-y;
        }
    }

    /* The pipeline: a lane is a sheet of paper with its sky pass off register, its head a sticker on the stage's own
       plate and peel; a card is a sticker that lifts 2 px on its peel when pointed at and sticks down when pressed;
       the open one is ringed in plum; a dimmed one is a dashed outline with no pass; the board's sentence is paper. */
    [data-theme='pastel'] .kp-pipeline {
        --kp-pipeline-gap: 1rem;
    }
    [data-theme='pastel'] .kp-pipeline__lane {
        border-color: var(--border-strong);
        border-radius: var(--kp-sig-pa-r-plate);
        background: var(--muted);
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-pipeline__head {
        border-color: transparent;
        border-radius: var(--kp-sig-pa-r-ctl);
        box-shadow: 0 3px 0 hsl(from var(--kp-pipeline-tone) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-pipeline__share {
        font-weight: 600;
    }
    [data-theme='pastel'] .kp-pipeline__card {
        border-color: var(--border-strong);
        border-radius: var(--kp-sig-pa-r-ctl);
        box-shadow: 0 3px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-pipeline__card:is(button, a):hover {
        translate: 0 -2px;
        border-color: var(--border-strong);
        box-shadow: 0 5px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-pipeline__card:is(button, a):active {
        translate: 0 3px;
        box-shadow: 0 0 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-pipeline__card:focus-visible {
        outline: 2px dashed var(--ring);
        outline-offset: 3px;
    }
    [data-theme='pastel'] .kp-pipeline__card[aria-current='true'] {
        border-color: var(--primary);
        box-shadow:
            0 0 0 2px var(--primary),
            0 4px 0 1px var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-pipeline__card[data-kp-dimmed] {
        border-width: 2px;
        box-shadow: none;
    }
    [data-theme='pastel'] .kp-pipeline__mark {
        border-radius: calc(var(--kp-sig-pa-r-ctl) * 0.6);
        box-shadow: 0 2px 0 hsl(from var(--kp-pipeline-tone, var(--muted-foreground)) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-pipeline__state {
        border: 2px dashed var(--border-strong);
        border-radius: var(--kp-sig-pa-r-plate);
    }
    [data-theme='pastel'] .kp-pipeline__state[data-kp-state='error'] .kp-pipeline__words {
        padding: 0 0.55rem;
        border-inline-start: 0;
        border-radius: var(--kp-sig-pa-r-ctl);
        background: var(--destructive);
        color: var(--destructive-foreground);
        box-shadow: 0 2px 0 hsl(from var(--destructive) h s calc(l * 0.6));
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] :is(.kp-pipeline__card, .kp-pipeline__mark) {
            transition:
                translate var(--fx-duration) var(--kp-sig-pa-land),
                box-shadow var(--fx-duration) var(--kp-sig-pa-land);
        }
    }

    /* Drawings for an empty state: the sticker sheet (js/art.js). Each stroke is stuck on in reading order, 60 ms apart
       on the soft landing: the second pass slides in along the misregistration line, the paper swings down from its
       top-start corner, the tape last. The tape is the last stroke of every drawing, mint. Reduced, the drawing is
       stuck on. */
    [data-theme='pastel'] .kp-art {
        display: block;
        --kp-art-stroke: 1.5px;
    }
    [data-theme='pastel'] .kp-art > g[data-kp-art-set='stickers'] {
        display: inline;
    }
    /* The drawing takes the place of the empty state's halftone disc; the fold stays. */
    [data-theme='pastel'] .kp-empty[data-kp-art]::before {
        content: none;
    }
    [data-theme='pastel'] .kp-art path {
        stroke-linecap: round;
        stroke-linejoin: round;
    }
    [data-theme='pastel'] .kp-art__line {
        fill: var(--kp-sig-pa-pass-c);
        stroke: none;
    }
    [data-theme='pastel'] .kp-art__ink {
        fill: var(--card);
        stroke: var(--primary);
    }
    [data-theme='pastel'] .kp-art > g[data-kp-art-set='stickers'] > path:last-child {
        fill: var(--accent);
        stroke: var(--kp-sig-pa-tape-stripe);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-art > g[data-kp-art-set='stickers'] > path {
            transform-box: fill-box;
            transform-origin: 0 0;
            animation: kp-sig-pastel-stuck-in var(--kp-sig-pa-window) var(--kp-sig-pa-land) both;
            animation-delay: calc(var(--kp-art-i, 0) * 60ms);
        }
        [data-theme='pastel'] .kp-art > g[data-kp-art-set='stickers'] > path.kp-art__line {
            animation-name: kp-sig-pastel-pass-in;
        }
    }
}

/* ── The calm components and the seven new ones [kpadopt4]: chips, quantity, checklist, timers, steps, wheel,
   uptime, command, disc, countdown, range, compare ── */
@layer kp.signature {
    /* Three-way chips: the chip that is in is plum on its peel (the chips' own), the one that is out a dashed outline
       with the word struck through and a red sticker for its mark; pointing lifts any of them 2 px. */
    [data-theme='pastel'] .kp-segmented--chips[data-kp-segmented='tri'] > .kp-segmented__item[data-kp-segmented-tri='include'] {
        box-shadow: 0 3px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-segmented--chips[data-kp-segmented='tri'] > .kp-segmented__item[data-kp-segmented-tri='exclude'] {
        border-style: dashed;
        border-width: 2px;
        box-shadow: none;
    }
    [data-theme='pastel'] .kp-segmented__item[data-kp-segmented-tri='exclude'] > .kp-segmented__mark {
        box-shadow: 0 2px 0 hsl(from var(--destructive) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-segmented__mark {
        border-width: 2px;
    }
    @media (hover: hover) {
        [data-theme='pastel'] .kp-segmented--chips[data-kp-segmented='tri']:not([aria-disabled='true']) > .kp-segmented__item:hover {
            box-shadow: 0 5px 0 var(--kp-sig-pa-peel);
            translate: 0 -2px;
        }
        [data-theme='pastel'] .kp-segmented--chips[data-kp-segmented='tri']:not([aria-disabled='true']) > .kp-segmented__item[data-kp-segmented-tri='exclude']:hover {
            box-shadow: none;
        }
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-segmented--chips[data-kp-segmented='tri'] > .kp-segmented__item {
            transition:
                translate var(--fx-duration) var(--kp-sig-pa-land),
                box-shadow var(--fx-duration) var(--kp-sig-pa-land);
        }
    }

    /* Quantity: the steps are pastel's own buttons; the number sits on paper with its sky pass, focus is the dashed line. */
    [data-theme='pastel'] .kp-quantity__field {
        border-radius: var(--kp-sig-pa-r-ctl);
        border-color: var(--border-strong);
        box-shadow: calc(3px * var(--kp-sig-pa-dir)) 3px 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-quantity__field:has(.kp-quantity__input:focus-visible) {
        outline: 2px dashed var(--ring);
        outline-offset: 3px;
        box-shadow: calc(3px * var(--kp-sig-pa-dir)) 3px 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-quantity__input {
        font-weight: 700;
    }

    /* Checklist: a row is lifted onto the mint wash when pointed at; a ticked item is struck through in plum; the rules
       are threads of pearls, the bar's a dashed cut; a finished group's count carries a tick sticker. */
    [data-theme='pastel'] .kp-checklist__bar {
        border-block-end: 2px dashed var(--border-strong);
    }
    [data-theme='pastel'] .kp-checklist__list {
        border-block-start: 2px dotted var(--border-strong);
    }
    [data-theme='pastel'] .kp-checklist__item {
        border-block-end: 2px dotted var(--border-strong);
    }
    [data-theme='pastel'] .kp-checklist__row {
        border-radius: var(--kp-sig-pa-r-ctl);
    }
    @media (hover: hover) {
        [data-theme='pastel'] .kp-checklist__row:hover {
            background: var(--accent);
            color: var(--accent-foreground);
        }
        [data-theme='pastel'] .kp-checklist__row:hover :is(.kp-checklist__detail, .kp-checklist__label) {
            color: inherit;
        }
    }
    [data-theme='pastel'] .kp-checklist__item[data-kp-checklist-checked] .kp-checklist__label {
        text-decoration-color: var(--primary);
        text-decoration-thickness: 2px;
    }
    [data-theme='pastel'] .kp-checklist__group[data-kp-checklist-done] .kp-checklist__count::before {
        display: inline-block;
        padding: 0 0.35em;
        border-radius: var(--kp-sig-pa-r-chip);
        background: var(--success);
        color: var(--success-foreground);
        box-shadow: 0 1.5px 0 hsl(from var(--success) h s calc(l * 0.6));
    }
    [data-theme='pastel'] :is(.kp-checklist__empty, .kp-timers__empty) {
        border: 2px dashed var(--border-strong);
        border-radius: var(--kp-sig-pa-r-plate);
    }
    [data-theme='pastel'] .kp-checklist__empty[data-kp-checklist-failed] {
        border-style: solid;
        border-color: var(--destructive);
    }

    /* Kitchen timers: a card is a plate with its sky pass, a strip of washi tape across its top start edge; a paused
       timer's tape lifts at its end; a finished one wobbles round its foot three times and stays on its plate. */
    [data-theme='pastel'] .kp-timer {
        position: relative;
        border-color: var(--border-strong);
        border-radius: var(--kp-sig-pa-r-plate);
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-timer::before {
        content: '';
        position: absolute;
        inset-block-start: -0.35rem;
        inset-inline-start: 1rem;
        inline-size: 3rem;
        block-size: 0.7rem;
        border-radius: 2px;
        background: var(--kp-sig-pa-tape-bg);
        rotate: -2deg;
        transform-origin: 0 50%;
        pointer-events: none;
    }
    [data-theme='pastel'] .kp-timer[data-kp-timer-state='paused']::before {
        rotate: -14deg;
        translate: 0 -0.05rem;
    }
    [data-theme='pastel'] .kp-timer[data-kp-timer-state='done'] {
        border-color: var(--border-strong);
    }
    [data-theme='pastel'] .kp-timer[data-kp-timer-state='done']::before {
        opacity: 0;
    }
    [data-theme='pastel'] .kp-timer__time {
        color: var(--primary);
    }
    [data-theme='pastel'] .kp-timer[data-kp-timer-state='paused'] .kp-timer__time {
        color: var(--muted-foreground);
    }
    [data-theme='pastel'] .kp-timer[data-kp-timer-state='done'] .kp-timer__time {
        color: inherit;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-timer::before {
            transition: rotate var(--fx-duration) var(--kp-sig-pa-land);
        }
        [data-theme='pastel'] .kp-timer[data-kp-timer-ringing] {
            transform-origin: 50% 100%;
            animation: kp-sig-pastel-update-wobble var(--kp-sig-pa-wobble) ease-out 3;
        }
    }

    /* Cook mode: what the step needs is a note taped in (a dashed edge on paper) under a mint sticker for its title;
       the screen lamp is a pearl; each step arrives stuck on (the package's own arrival). */
    [data-theme='pastel'] .kp-focus-steps__needs {
        padding: var(--kp-space-md, 0.75rem) 1rem;
        border: 2px dashed var(--border-strong);
        border-radius: var(--kp-sig-pa-r-plate);
        background: var(--card);
    }
    [data-theme='pastel'] .kp-focus-steps__needs-title {
        justify-self: start;
        display: inline-block;
        padding: 0 0.6rem;
        border-radius: var(--kp-sig-pa-r-chip);
        background: var(--accent);
        color: var(--accent-foreground);
    }
    [data-theme='pastel'] .kp-focus-steps__count {
        font-weight: 700;
    }
    [data-theme='pastel'] .kp-focus-steps__amount {
        color: var(--primary);
    }
    [data-theme='pastel'] .kp-focus-steps[data-kp-focus-steps-screen='on'] .kp-focus-steps__wake::before {
        box-shadow: 0 1.5px 0 var(--kp-sig-pa-peel);
    }

    /* Wheel: a sticker sheet round, its sky pass off register on the stage; every wedge die-cut with a paper gap, the
       rim plum; it spins on the soft landing and settles back once past its mark; the winner's name wobbles. */
    [data-theme='pastel'] .kp-wheel {
        --kp-wheel-ease: var(--kp-sig-pa-land);
        --kp-wheel-hub-ring: 5px;
    }
    [data-theme='pastel'] .kp-wheel__stage {
        filter: drop-shadow(calc(5px * var(--kp-sig-pa-dir)) 5px 0 var(--kp-sig-pa-pass-c));
    }
    [data-theme='pastel'] .kp-wheel__segment {
        stroke-width: 2.4;
    }
    /* The hub carries none of the button's plates, frames or labels on its pseudo-elements: a round disc stays round
       [cook-1017; Kenny 2026-10-17: no square frame round the spin hub in any theme]. */
    [data-theme='pastel'] .kp-wheel__spin.kp-button::before,
    [data-theme='pastel'] .kp-wheel__spin.kp-button::after {
        content: none !important;
    }
    [data-theme='pastel'] .kp-wheel__spin.kp-button {
        --kp-wheel-hub-shadow: 0 3px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-wheel__rim {
        stroke: var(--primary);
        stroke-width: 2;
    }
    [data-theme='pastel'] .kp-wheel__label {
        font-weight: 600;
    }
    [data-theme='pastel'] .kp-wheel__outcome:not([data-kp-wheel-note]) {
        color: var(--primary);
        font-weight: 700;
    }
    [data-theme='pastel'] .kp-wheel__outcome[data-kp-wheel-note] {
        border: 2px dashed var(--border-strong);
        border-radius: var(--kp-sig-pa-r-ctl);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-wheel[data-kp-wheel-won] .kp-wheel__outcome:not([data-kp-wheel-note]) {
            transform-origin: 50% 100%;
            animation: kp-sig-pastel-update-wobble var(--kp-sig-pa-wobble) ease-out;
        }
    }

    /* Uptime: every period is a small sticker standing on its own peel; the one pointed at grows into the room above,
       its ring the dashed plum line; a failure to read is a sticker on the red's plate. */
    [data-theme='pastel'] .kp-uptime {
        --kp-uptime-cell-radius: 4px;
        --kp-uptime-gap: 3px;
    }
    [data-theme='pastel'] .kp-uptime__cell:not(.kp-skeleton) {
        box-shadow: inset 0 -2px 0 hsl(from var(--kp-uptime-fill) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-uptime__cell:is(:focus-visible, [aria-expanded='true']) {
        outline: 2px dashed var(--ring);
        outline-offset: 2px;
    }
    [data-theme='pastel'] .kp-uptime__percent {
        color: var(--primary);
    }
    [data-theme='pastel'] .kp-uptime__summary[data-kp-tone='error'] {
        border-radius: var(--kp-sig-pa-r-ctl);
        box-shadow: 0 2px 0 hsl(from var(--destructive) h s calc(l * 0.6));
    }
    [data-theme='pastel'] .kp-uptime__swatch {
        border-radius: 3px;
    }

    /* Command: a plate stuck to the page, its sky pass off register and a strip of tape over its top edge; the shell
       is a mint sticker, the prompt plum, the head cut from the line by a dashed edge. */
    [data-theme='pastel'] .kp-command {
        --kp-command-prompt-ink: var(--primary);
        position: relative;
        border-color: var(--border-strong);
        border-radius: var(--kp-sig-pa-r-plate);
        overflow: visible;
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-command::after {
        content: '';
        position: absolute;
        z-index: 2;
        inset-block-start: -0.35rem;
        inset-inline-start: 1.25rem;
        inline-size: 3.25rem;
        block-size: 0.75rem;
        border-radius: 2px;
        background: var(--kp-sig-pa-tape-bg);
        rotate: -2deg;
        pointer-events: none;
    }
    [data-theme='pastel'] .kp-command__head,
    [data-theme='pastel'] .kp-command:not([data-kp-command-ready])::before {
        border-block-end: 2px dashed var(--border-strong);
        border-start-start-radius: inherit;
        border-start-end-radius: inherit;
    }
    [data-theme='pastel'] .kp-command__head {
        padding-block-start: calc(var(--kp-space-xs, 0.25rem) + 0.25rem);
    }
    [data-theme='pastel'] .kp-command__shell {
        padding: 0 0.6rem;
        border-radius: var(--kp-sig-pa-r-chip);
        background: var(--accent);
        color: var(--accent-foreground);
    }
    [data-theme='pastel'] .kp-command__where {
        border-block-start: 2px dashed var(--border-strong);
    }
    [data-theme='pastel'] .kp-command__code {
        border-end-start-radius: inherit;
        border-end-end-radius: inherit;
    }

    /* Visual timer and countdown: the timer is a round sticker with its sky pass off register, the time left plum on
       paper, the hub a pearl; a finished one wobbles round its foot and keeps its pass; the countdown is a plate with
       its pass and a strip of tape, its digits plum. */
    [data-theme='pastel'] .kp-timer-disc__face {
        border-width: 2px;
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-timer-disc {
        --kp-timer-disc-marks: var(--border-strong);
        --kp-timer-disc-ring: var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-timer-disc__hub {
        background: var(--primary);
        border-color: var(--card);
    }
    [data-theme='pastel'] .kp-timer-disc[data-kp-timer-disc-state='ended'] .kp-timer-disc__face {
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-countdown {
        --kp-countdown-ink: var(--primary);
        position: relative;
        border-color: var(--border-strong);
        border-radius: var(--kp-sig-pa-r-plate);
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-countdown::before {
        content: '';
        position: absolute;
        inset-block-start: -0.35rem;
        inset-inline-start: 1rem;
        inline-size: 3rem;
        block-size: 0.7rem;
        border-radius: 2px;
        background: var(--kp-sig-pa-tape-bg);
        rotate: -2deg;
        pointer-events: none;
    }
    [data-theme='pastel'] .kp-countdown[data-kp-countdown-state='paused'] .kp-countdown__time {
        color: var(--muted-foreground);
    }
    [data-theme='pastel'] .kp-countdown[data-kp-countdown-state='ended'] {
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-timer-disc[data-kp-timer-disc-state='ended'] .kp-timer-disc__face,
        [data-theme='pastel'] .kp-countdown[data-kp-countdown-state='ended'] {
            transform-origin: 50% 100%;
            animation: kp-sig-pastel-update-wobble var(--kp-sig-pa-wobble) ease-out 3;
        }
    }

    /* Range picker: the custom window in force is a sticker pressed on, ringed in plum; its panel is the popover's own
       plate (opaque); an invalid time takes the dashed red line. */
    [data-theme='pastel'] .kp-range__custom[aria-pressed='true'] {
        border-color: var(--primary);
        box-shadow:
            0 0 0 2px var(--primary),
            0 4px 0 1px var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-range__panel .kp-field__input[aria-invalid='true'] {
        border-style: dashed;
        box-shadow: none;
    }

    /* Compare slider: a photo stuck down in a frame with its sky pass; the divider is a strip of washi tape laid across
       it; the handle is a round sticker on its peel that lifts when pointed at; the two labels are stickers. */
    [data-theme='pastel'] .kp-compare {
        --kp-compare-line: 10px;
        --kp-compare-ink: var(--primary);
        border-color: var(--border-strong);
        border-radius: var(--kp-sig-pa-r-plate);
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }
    [data-theme='pastel'] .kp-compare__divider {
        border-inline-start-color: transparent;
        background:
            repeating-linear-gradient(0deg, var(--accent) 0 6px, transparent 6px 12px),
            var(--kp-sig-pa-tape-stripe);
    }
    [data-theme='pastel'] .kp-compare__handle {
        box-shadow: 0 3px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-compare__handle:hover {
        box-shadow: 0 5px 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-compare__handle:active {
        box-shadow: 0 0 0 var(--kp-sig-pa-peel);
    }
    [data-theme='pastel'] .kp-compare__handle:focus-visible {
        outline: 2px dashed var(--ring);
        outline-offset: 3px;
    }
    [data-theme='pastel'] .kp-compare__label {
        border: 0;
        border-radius: var(--kp-sig-pa-r-chip);
        padding-inline: 0.7rem;
        box-shadow: 0 2px 0 var(--kp-sig-pa-peel);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='pastel'] .kp-compare__handle {
            transition: box-shadow var(--fx-duration) var(--kp-sig-pa-land);
        }
        [data-theme='pastel'] .kp-compare[data-kp-compare-glide] :is(.kp-compare__pane, .kp-compare__divider) {
            transition-timing-function: var(--kp-sig-pa-land-size);
        }
    }
}

/* ── The kpadopt5 and kpadopt6 components in pastel [t56-pastel-1018] ──────────────────────────────────────────────
   What the review of the seventy-nine new sections found off in this theme, one rule per fault; each says what it was. */
@layer kp.signature {
    /* A problem alert (kp-alert.kp-problem) is a soft tint of its tone on paper, with the page's ink: the package reads it so
       (`.kp-problems > .kp-problem`). Pastel drew it on the tone's solid plate (`--kp-sig-pa-plate: var(--destructive)`) and kept
       the page's plum ink, so a critical problem was plum on a red plate. The plate is now the tone at 14 % in paper, the pass
       and the tone's edge stay. */
    [data-theme='pastel'] .kp-alert.kp-problem {
        --kp-sig-pa-plate: color-mix(in oklab, var(--kp-problem-tone, var(--muted)) 14%, var(--card));
        color: var(--foreground);
    }

    /* The request inspector's status filter is five segments (a label and its exact count each) and stood in one row wider than
       a phone: the bar stuck out 91 to 93 px past its section (kpadopt5-rows/request-inspector, 390 px). Wrapping them breaks the
       package's sliding plate, so on a phone the five share the width, with less padding, and nothing is cut. */
    @media (max-width: 30rem) {
        [data-theme='pastel'] .kp-inspector__filter {
            grid-template-columns: repeat(5, minmax(0, 1fr));
            max-inline-size: 100%;
        }

        [data-theme='pastel'] .kp-inspector__filter > .kp-segmented__item {
            padding-inline: 0.125rem;
            gap: 0.1875rem;
            min-inline-size: 0;
            font-size: 0.8125rem;
        }

        [data-theme='pastel'] .kp-inspector__filter .kp-segmented__count {
            min-inline-size: 0;
            padding-inline: 0.25rem;
            font-size: 0.6875rem;
            letter-spacing: 0;
        }
    }

    /* The code box's tools (Pretty and Raw, Wrap, Copy) stand in one nowrap row; pastel's stickers are wider than the package's
       buttons, so in a phone-wide request inspector "Copy" stuck out 36 px. The row may wrap. */
    [data-theme='pastel'] .kp-code__tools {
        flex-wrap: wrap;
    }

    /* On a phone the six segments share the chooser's width and their words wrap ("Every" over "15 s") instead of running out of
       the section; no label is cut. */
    @media (max-width: 30rem) {
        [data-theme='pastel'] .kp-refresh__segments {
            display: grid;
            grid-template-columns: repeat(6, minmax(min-content, 1fr));
            inline-size: 100%;
        }

        [data-theme='pastel'] .kp-refresh__segments > .kp-segmented__item {
            padding-inline: 0.25rem;
            min-inline-size: 0;
            white-space: normal;
            text-align: center;
        }

        [data-theme='pastel'] .kp-refresh__segments .kp-segmented__label {
            overflow: visible;
            text-overflow: clip;
            white-space: normal;
            letter-spacing: 0;
        }
    }

    /* The names left out of a group ("+4") open in a list that the package gives a soft drop shadow; pastel has no soft shadow
       anywhere (G7): the list is paper with the sky pass 6 px off register, as its menus are. */
    [data-theme='pastel'] .kp-idmark-group__list {
        border-radius: var(--kp-sig-pa-r-plate);
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }

    /* The next-times list keeps the height of three rows in every state; pastel's empty plate (a 52 px halftone disc, 1.25 rem and
       1.6 rem of padding) needed 183 px against the 134 px footprint, so Empty pushed the page down by 17 px
       (kpadopt5-time/runs-states). In this footprint the disc is 2 rem and the padding 0.5 rem. */
    [data-theme='pastel'] .kp-runs__empty {
        --kp-sig-pa-lip: 1.25rem;
        padding: 0.5rem 1rem 0.75rem;
        gap: 0.25rem;
    }

    [data-theme='pastel'] .kp-runs__empty::before {
        inline-size: 2rem;
        block-size: 2rem;
        margin: 0 auto;
    }

    [data-theme='pastel'] .kp-runs__empty-title {
        margin: 0;
    }

    /* A waiting map line (`.kp-uses__card.kp-skeleton`) is a row of pom-poms the height of one skeleton line; the package gives
       the card 4.25 rem, which drew a caterpillar 68 px tall with a 0.45 rem margin each side and made Loading 100 px taller
       than Ready (kpadopt6-media/uses-states). The node is the 3.5 rem of a ready card, as in formal, and the line stands in the middle of it. */
    [data-theme='pastel'] .kp-uses__node:has(> .kp-uses__card.kp-skeleton) {
        align-items: center;
        min-block-size: 3.5rem;
    }

    [data-theme='pastel'] .kp-uses__card.kp-skeleton {
        block-size: 0.7rem;
        min-block-size: 0;
        margin-block: 0;
    }

    /* The checklist's "nothing yet" box is the empty plate above; its failed box is the destructive alert's plate with the pass. */
    [data-theme='pastel'] .kp-checklist__empty[data-kp-checklist-failed] {
        border-color: var(--destructive);
        border-radius: var(--kp-sig-pa-r-plate);
        background: var(--destructive);
        color: var(--destructive-foreground);
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
    }

    /* Retry in the checklist's failed box is a normal button in the middle, not a strip across the box (the grid stretched it). */
    [data-theme='pastel'] .kp-checklist__empty .kp-claim__retry {
        justify-self: center;
        font-size: var(--kp-text-md, 1rem);
    }

    /* A quote card holds the height of its quote (176 px at desktop width); pastel's empty plate (a 52 px disc, 1.25 and 1.6 rem of
       padding, 168 px) plus the card's own padding made Empty 26 px taller than Ready (kpadopt6-calm/quote-states). In this
       footprint the disc is 2.25 rem and the padding smaller; the card's stage keeps the height it had. */
    [data-theme='pastel'] .kp-quote .kp-card__empty {
        --kp-sig-pa-lip: 1.25rem;
        padding: 0.75rem 1rem 1rem;
    }

    [data-theme='pastel'] .kp-quote .kp-card__empty::before {
        inline-size: 2.25rem;
        block-size: 2.25rem;
        margin-block-end: 0.4rem;
    }

    /* The rating's failed plate lies over the place of the stars (`position: absolute; inset: 0`); pastel's alert rule made every
       alert `position: relative`, so the plate stood in the flow under the hidden stars and the rating grew from 80 to 158 px
       (142 against 92 at 390; kpadopt6-fields/rating-states). */
    [data-theme='pastel'] .kp-rating__failure {
        position: absolute;
    }

    /* A waiting version badge holds a skeleton line with the 0.45 rem margins of a line in a list; inside a badge they made it
       30 px high against 23 for its version (kpadopt5-ops/version-states). */
    [data-theme='pastel'] .kp-badge > .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        margin-block: 0.26rem;
    }

    /* A waiting gallery tile has the final tile's shape (the package says so), but this theme's skeleton line gives every
       skeleton a fixed block size and margins, so the tiles collapsed to a strip and Loading drew 70 px in a 456 px footprint
       (kpadopt6-media/gallery-states). The tile is square again, as the picture it waits for. */
    [data-theme='pastel'] .kp-gallery__tile.kp-skeleton {
        block-size: auto;
        min-block-size: 0;
        margin-block: 0;
        aspect-ratio: var(--kp-gallery-ratio, 1);
    }

    /* The pom-poms of a waiting line are sized from the element they wait in (147 px beads in a tile). A waiting tile is a plain
       paper tile with the pass, as the heat cells are; the busy card over the grid is what moves. */
    [data-theme='pastel'] .kp-gallery__tile.kp-skeleton {
        border: 1px solid var(--border-strong);
        border-radius: var(--kp-sig-pa-r-plate);
        background: var(--card);
        box-shadow: calc(var(--kp-sig-pa-off) * var(--kp-sig-pa-dir)) var(--kp-sig-pa-off) 0 var(--kp-sig-pa-pass-c);
        overflow: visible;
    }

    [data-theme='pastel'] .kp-gallery__tile.kp-skeleton > .kp-pieces {
        display: none;
    }

    /* A card in a state (js/card-state.js): the note fills the stage (the plate was as high as its words, in the middle of a tall
       stage), and a failed card says it at the heading size in the middle with its Retry under it, as an empty one does
       (kpadopt4-rows/today-states, kpadopt6-calm/quote-states, kpadopt5-lists/request-inspector). */
    [data-theme='pastel'] .kp-card__state {
        align-content: stretch;
        grid-template-rows: minmax(0, 1fr);
    }

    [data-theme='pastel'] .kp-card__state > .kp-card__failure {
        box-sizing: border-box;
        block-size: 100%;
        flex-direction: column;
        justify-content: center;
        text-align: center;
    }

    [data-theme='pastel'] .kp-card__failure > .kp-alert__body {
        flex: none;
        justify-items: center;
        max-inline-size: 100%;
    }

    [data-theme='pastel'] :is(.kp-card__state-title, .kp-card__failure .kp-alert__what) {
        font-size: var(--kp-text-lg, 1.125rem);
    }

    /* The failed title is the alert's own ink (the page's ink was dark plum on the red plate). */
