            ) {
            animation: kp-progressbar-forest-breath var(--kp-sig-fo-breath) linear var(--kp-sig-fo-head) infinite;
        }

        /* Lines of a skeleton stand 400 ms apart. */
        [data-theme='forest'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block):nth-child(2) {
            animation-delay: calc(var(--kp-sig-fo-head) - 5 * var(--kp-sig-fo-stagger));
        }

        [data-theme='forest'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block):nth-child(3) {
            animation-delay: calc(var(--kp-sig-fo-head) - 10 * var(--kp-sig-fo-stagger));
        }
    }

    /* Standing still, the strip is the bar's own reduced pose: half the row. */
    @media (prefers-reduced-motion: reduce) {
        [data-theme='forest']
            :is(
                .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block),
                .kp-meter[data-kp-loading],
                .kp-kpi__meter[data-kp-loading],
                .kp-datatable__busy-panel,
                .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading],
                .kp-button[aria-busy='true'],
                .kp-card[aria-busy='true'],
                .kp-tiles[aria-busy='true'] > .kp-card,
                .kp-kpi__chart .kp-chart__state[data-kp-state='loading'],
                .kp-calendar--busy-whole > .kp-calendar__busy
            ) {
            --kp-fo-breath: 0.5;
        }
    }

    /* ── Skeleton block and circle: the treeline fills in [G9, §6; Kenny,
       2026-10-07: option 1 of research/forest-skeleton, after the stripes and
       the planted plot did not give forest vibes]. Two ridges of the same
       paper-brown rise from the foot, the far one first, then the planted tree
       line (the lines' own trees, whole trees only, the lines' pitch, margin
       and edge arithmetic) walks across start to end on the ground line. One
       clock, --kp-fo-grow, 0 to 1 on the bar's own breath (Kenny, 2026-10-09
       on research/forest-uniformity, timing: "the bar's breath
       everywhere"): it arrives in 3000 ms, stands for 600 ms and leaves in
       3000 ms as the arrival played backwards, on the bar's ease, so it
       breathes with the lines and the bar beside it. The ridges are heights in percent and the trees are a fixed
       size per shape, so it fits any block height and the circle (clipped to
       the circle) alike. Standing still it is the finished picture
       (--kp-fo-grow stays 1). The chart's loading panel and legend stubs are
       block skeletons, so they are drawn here too. ── */
    [data-theme='forest'] :is(.kp-skeleton--block, .kp-skeleton--circle) {
        --kp-fo-tree: 2.25rem;
        --kp-fo-pitch: calc(var(--kp-fo-tree) / 2);
        --kp-fo-run: calc(round(down, 100% - var(--kp-fo-pitch), 2 * var(--kp-fo-pitch)) + var(--kp-fo-pitch));
        --kp-fo-margin: calc((100% - var(--kp-fo-run)) / 2);
        --kp-fo-w: clamp(0, (var(--kp-fo-grow) - 0.12) / 0.88, 1);
        --kp-fo-edge: calc(
            var(--kp-fo-margin) + min(round(down, var(--kp-fo-w) * (var(--kp-fo-run) + var(--kp-fo-pitch)), var(--kp-fo-pitch)), var(--kp-fo-run))
        );
        --kp-fo-r1: clamp(0, var(--kp-fo-grow) / 0.45, 1);
        --kp-fo-r2: clamp(0, (var(--kp-fo-grow) - 0.1) / 0.45, 1);
        --kp-fo-ridge-far: color-mix(in oklab, var(--border-strong) 26%, var(--muted));
        --kp-fo-ridge-near: color-mix(in oklab, var(--border-strong) 52%, var(--muted));
        position: relative;
        overflow: clip;
        box-sizing: border-box;
        border: 0;
        background:
            linear-gradient(to top, var(--border-strong) 0 1px, transparent 1px),
            radial-gradient(ellipse 50% 100% at 50% 100%, var(--kp-fo-ridge-near) 0 99%, transparent 100%) 4.5rem
                calc((1 - var(--kp-fo-r2) * 0.34) / 0.66 * 100%) / 7rem 34% repeat-x,
            radial-gradient(ellipse 50% 100% at 50% 100%, var(--kp-fo-ridge-near) 0 99%, transparent 100%) -1rem
                calc((1 - var(--kp-fo-r2) * 0.46) / 0.54 * 100%) / 12rem 46% repeat-x,
            radial-gradient(ellipse 50% 100% at 50% 100%, var(--kp-fo-ridge-far) 0 99%, transparent 100%) 7rem
                calc((1 - var(--kp-fo-r1) * 0.5) / 0.5 * 100%) / 10rem 50% repeat-x,
            radial-gradient(ellipse 50% 100% at 50% 100%, var(--kp-fo-ridge-far) 0 99%, transparent 100%) 0
                calc((1 - var(--kp-fo-r1) * 0.66) / 0.34 * 100%) / 17rem 66% repeat-x,
            var(--muted);
        animation: none;
    }

    [data-theme='forest'] .kp-skeleton--block {
        border-radius: var(--kp-sig-fo-part);
    }

    [data-theme='forest'] .kp-skeleton--circle {
        --kp-fo-tree: 1.1rem;
        border-radius: 50%;
    }

    [data-theme='forest'] .kp-skeleton--block.kp-chart__source-stub {
        --kp-fo-tree: 0.8rem;
    }

    [data-theme='forest'] :is(.kp-skeleton--block, .kp-skeleton--circle)::before {
        content: none;
    }

    [data-theme='forest'] :is(.kp-skeleton--block, .kp-skeleton--circle)::after {
        content: '';
        position: absolute;
        inset: 0;
        border-radius: 0;
        pointer-events: none;
        background: var(--primary);
        mask: var(--kp-fo-trees) 50% 100% / calc(var(--kp-fo-pitch) * 7) var(--kp-fo-tree) repeat-x;
        clip-path: inset(calc(100% - var(--kp-fo-tree)) calc(100% - var(--kp-fo-edge)) 0 var(--kp-fo-margin));
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] :is(.kp-skeleton--block, .kp-skeleton--circle) {
            animation: kp-skeleton-forest-treeline var(--kp-sig-fo-breath) linear infinite;
        }
    }

    @keyframes kp-skeleton-forest-treeline {
        0% {
            --kp-fo-grow: 0;
            animation-timing-function: cubic-bezier(0.42, 0, 0.58, 1);
        }
        45.4545% {
            --kp-fo-grow: 1;
            animation-timing-function: linear;
        }
        54.5455% {
            --kp-fo-grow: 1;
            animation-timing-function: cubic-bezier(0.42, 0, 0.58, 1);
        }
        100% {
            --kp-fo-grow: 0;
        }
    }

    /* ── A live change lays a growth ring round it [G8; Kenny, 2026-10-07:
       "a growth ring is laid round what changed"]. js/update.js writes the
       new value at once and marks the element `[data-kp-updating='ring']`;
       a thin ring in the acting green is drawn round it once, clockwise from
       the top, on the growth curve in 55 % of the time, then it fades, in
       all 1000 ms (the theme's update time, themeMotion(), times 0.8). The
       value, the word, the line never move. A spark's ring is a circle
       round its last reading. A state word keeps its width-holding ::after,
       so its ring is drawn on ::before. ── */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] {
            --kp-update: ring;
        }

        /* The ring is positioned against the updated element; one that is
           already positioned (the tour's card is fixed) keeps its own. */
        [data-theme='forest'] [data-kp-updating='ring']:not(.kp-tour) {
            position: relative;
        }

        [data-theme='forest'] [data-kp-updating='ring']:not(.kp-state-word)::after,
        [data-theme='forest'] .kp-state-word[data-kp-updating='ring']::before {
            content: '';
            position: absolute;
            inset: -4px -8px;
            border: 1.5px solid var(--primary);
            border-radius: 999px;
            mask: conic-gradient(var(--foreground) var(--kp-fo-arc), transparent 0);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-forest-update-ring calc(var(--kp-update-duration, 1250ms) * 0.8) linear both;
        }

        [data-theme='forest'] [data-kp-updating='ring']:has(> svg)::after {
            inset: -12% -3% auto auto;
            inline-size: 1.5rem;
            block-size: 1.5rem;
            border-radius: 50%;
        }
    }

    @keyframes kp-sig-forest-update-ring {
        0% {
            --kp-fo-arc: 0deg;
            opacity: 1;
            animation-timing-function: var(--kp-sig-fo-grow);
        }

        55% {
            --kp-fo-arc: 360deg;
            opacity: 1;
            animation-timing-function: ease-in-out;
        }

        100% {
            --kp-fo-arc: 360deg;
            opacity: 0;
        }
    }

    /* ── The leaf corner [G6; Kenny, 2026-10-07 on research/forest-character:
       the leaf corner on every plate and every small part, replacing
       proposal-14's two radii]. One rule, one token (--kp-sig-fo-leaf): the
       top-right and bottom-left corners rounded, the other two square. A
       plate takes the token (--kp-sig-fo-plate), a small part half of it
       (--kp-sig-fo-part); the field note, the change on a tile, is a small
       part too, so the grammar has no square corner left. The instruments
       keep the routed 3 px of their wood (the meter, the bar's track), and
       what is round in a wood stays round (the radio, a ring, a dot, the
       switch's thumb). ── */
    [data-theme='forest']
        :is(
            .kp-card,
            .kp-kpi,
            .kp-alert,
            .kp-empty,
            .kp-spec,
            .kp-log,
            .kp-diff,
            .kp-media,
            .kp-dialog,
            .kp-popover,
            .kp-toast,
            .kp-tour,
            .kp-nav__menu,
            .kp-menu-button > .kp-menu,
            .kp-combobox__list,
            .kp-palette,
            .kp-shortcuts,
            .kp-datepicker__panel,
            .kp-form__summary,
            .kp-split,
            .kp-grid__tile,
            .kp-upload__zone,
            .kp-upload__file,
            .kp-reorder [data-kp-item],
            .kp-fieldset,
            .kp-datatable,
            .kp-wizard,
            .kp-datatable__busy-panel,
            .kp-calendar--busy-whole > .kp-calendar__busy,
            .kp-chart__plot,
            .kp-chart__state,
            .kp-chart__tip
        ) {
        border-radius: var(--kp-sig-fo-plate);
    }

    [data-theme='forest']
        :is(
            .kp-button,
            .kp-icon-button,
            .kp-badge,
            .kp-tag,
            .kp-field__input,
            .kp-combobox__input,
            .kp-datatable__search,
            .kp-menu__item,
            .kp-combobox__option,
            .kp-palette__option,
            .kp-nav__toggle,
            .kp-nav__search-trigger,
            .kp-skip-link,
            .kp-kpi__delta,
            .kp-kpi__link,
            .kp-chart__release,
            .kp-chart__delta[data-kp-direction],
            .kp-tooltip,
            .kp-help kbd,
            .kp-shortcuts__row kbd,
            .kp-field__check:not([type='radio']),
            .kp-nav__link--cta,
            .kp-nav__menu a,
            .kp-pagination a,
            .kp-pagination [aria-current],
            .kp-datepicker__day,
            .kp-tree [role='treeitem'],
            .kp-menu [data-kp-theme],
            .kp-colorpicker__swatch,
            .kp-chart__source,
            .kp-chart__show-all,
            .kp-reorder [data-kp-handle],
            .kp-accordion__summary,
            .kp-sidenav__link,
            .kp-sidenav__category-toggle,
            .kp-datepicker__title,
            .kp-kpi__value,
            .kp-log__level,
            .kp-mono,
            .kp-palette__keys,
            .kp-swatch,
            .kp-spec__swatch,
            .kp-datatable__sort-order
        ),
    [data-theme='forest'] .kp-card[data-kp-label]::before {
        /* The last small parts take the leaf too (Kenny, 2026-10-09 on
           research/forest-uniformity, corners: "the leaf on every small
           part"): the bar's call to action, page numbers, the days of the
           date picker, tree rows, theme options, colour swatches, legend
           keys, side navigation rows. What is round in a wood stays round
           (the radio, the switch's thumb, the tag's remove button, the
           month's logs). */
        border-radius: var(--kp-sig-fo-part);
    }

    [data-theme='forest'] .kp-switch {
        --kp-switch-radius: var(--kp-sig-fo-part);
    }

    /* ── Paper for plates, wood for instruments [G7; Kenny, 2026-10-07: the
       kit]. A plate is kraft card over the faint contour field, as the
       register draws it. What is held, a tag and a plain badge, is light
       wood: grain at 177 degrees, routed in, its words in the plain ink. A
       badge that names a state keeps the plate of its state. The wood the
       meter's gauge is made of is drawn with the meter. ── */
    [data-theme='forest'] :is(.kp-tag, .kp-badge:not([data-status], [class*='kp-badge--'])) {
        border-color: transparent;
        background-color: var(--muted);
        background-image: var(--kp-sig-fo-wood);
        box-shadow: var(--kp-sig-fo-routed);
        color: var(--foreground);
    }

    /* ── Notes are italic [G13; Kenny, 2026-10-07: type = notes]: what a
       ranger writes beside the figures, in the body face. Figures and titles
       stand upright; the mono face stays for identifiers, timestamps and log
       lines. The change on a tile is a field note: the arrows are the
       note's own (↑ and ↓). ── */
    [data-theme='forest']
        :is(.kp-kpi__delta, .kp-kpi__label, .kp-kpi__note, .kp-page-header__description, .kp-field__help, .kp-empty__body, .kp-chart__tick) {
        font-style: italic;
    }

    [data-theme='forest'] .kp-kpi__delta[data-kp-direction='up']::before {
        content: '↑\00a0';
    }

    [data-theme='forest'] .kp-kpi__delta[data-kp-direction='down']::before {
        content: '↓\00a0';
    }

    /* A menu or a popover hangs from its button: it grows down out of the button's edge,
       its far end first, like a root; placed above its button it grows up out of it (G3),
       one growth (G4). It closes as the growth reversed (js/motion.js playClose). The
       combobox's list and the date picker's panel grow down out of their field the same
       way, and the React theme menu's list out of its button (Kenny, 2026-10-09 on
       research/forest-uniformity: pairs "the list grows down out of its field", overlays
       "each grows like its family"); a list raised into the top layer closes as that
       growth reversed on js/motion.js's copy of it. */
    [data-theme='forest']
        :is(.kp-menu-button > .kp-menu, .kp-popover[popover]:not(.kp-tooltip), .kp-combobox__list, .kp-datepicker__panel, .kp-theme-menu__list) {
        --kp-sig-dur: var(--kp-sig-fo-time);
    }

    /* The list arrives as its own growth, not as the theme's leave turned
       around, which grew it up out of its own foot (F-19). */
    [data-theme='forest'] .kp-combobox__list {
        --kp-open: own;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest']
            :is(
                .kp-menu-button > .kp-menu,
                .kp-popover[popover]:not(.kp-tooltip),
                .kp-combobox__list:popover-open,
                .kp-datepicker__panel:is([data-kp-date-open], [data-kp-closing], [data-kp-reversing]):popover-open,
                .kp-theme-menu__list
