            animation: kp-sig-forest-root var(--kp-sig-dur) var(--kp-sig-fo-grow) both;
        }

        [data-theme='forest']
            :is(
                .kp-menu-button > .kp-menu[data-kp-menu-side='above'],
                .kp-combobox__list[data-kp-overlay-side='above']:popover-open,
                .kp-datepicker__panel[data-kp-overlay-side='above']:is([data-kp-date-open], [data-kp-closing], [data-kp-reversing]):popover-open
            ) {
            animation-name: kp-sig-forest-grow;
        }

        [data-theme='forest'] .kp-combobox__list > .kp-combobox__option,
        [data-theme='forest'] .kp-combobox__list > * {
            animation: none !important;
        }
    }

    /* ── The dashboard port [themes/forest/CHARACTER.md §5, Kenny's picks on
       research/character-{tiles,kpi,trend,columns,calendar,drawer}, decided
       2026-10-06; drawn on forest's grammar 2026-10-07]. Each block names its
       demo and pick; a demo's option attribute is the package's own markup
       here. Loading on these parts is the planting strip above (the tile
       grid, the trend's plot); the network graph is left alone (G16). ── */

    /* Tiles · shape 3, the herbarium sheet: the leaf corner is the plate's
       (above); a tile's title is the field-note voice, the body face in
       italic, no Georgia (G13, proposal-15). */
    [data-theme='forest'] .kp-tiles > .kp-card .kp-card__title {
        font-family: var(--theme-font-body);
        font-style: italic;
    }

    /* Tiles · hover 3, the light breaks through → the blaze: pointing at a
       sheet lays the dashed trail ring round it (G12); pointing at its Open
       link blazes the link alone (a forest ghost button, above). */
    [data-theme='forest'] .kp-tiles > .kp-card {
        outline: 2px dashed transparent;
        outline-offset: 2px;
    }

    [data-theme='forest'] .kp-tiles > .kp-card:hover:not(:has(:is(a, button, .kp-button):hover)) {
        outline-color: var(--primary);
        box-shadow: none;
    }

    /* Key figures · tone 3, the field note: a change without a tone is a note
       on the plain plate (the toned ones keep their status pair, the leaf
       corner and the italic from above); a warning or failed tile keeps the
       package's 3 px start blaze in the tone's ink (G5). */
    [data-theme='forest'] .kp-kpi__delta:not([data-kp-tone]) {
        padding-inline: 0.3em;
        background: var(--secondary);
        color: var(--secondary-foreground);
    }

    /* Key figures · live 3, the growth ring round the changed figure: the
       figure hugs its digits while the ring plays, so the ring is drawn round
       the number and not across the tile. */
    [data-theme='forest'] .kp-kpi > .kp-kpi__value[data-kp-updating='ring'] {
        justify-self: start;
        inline-size: fit-content;
    }

    /* Trend · loading 3, fireflies → the plot is planted too: the trend's
       loading panel (js/chart.js draws it as a block skeleton) is not the
       treeline here but the planting strip at the plot's foot (listed with
       the waiting surfaces above), on the tile's own ground. */
    [data-theme='forest'] .kp-kpi__chart .kp-chart__state[data-kp-state='loading'] {
        background-color: transparent;
    }

    /* Calendar · the rows and columns of the month, for the stagger of the
       arrival (reading order) and of the planting (the days of a week). */
    [data-theme='forest'] .kp-calendar__grid td:nth-child(2) {
        --kp-fo-col: 1;
    }

    [data-theme='forest'] .kp-calendar__grid td:nth-child(3) {
        --kp-fo-col: 2;
    }

    [data-theme='forest'] .kp-calendar__grid td:nth-child(4) {
        --kp-fo-col: 3;
    }

    [data-theme='forest'] .kp-calendar__grid td:nth-child(5) {
        --kp-fo-col: 4;
    }

    [data-theme='forest'] .kp-calendar__grid td:nth-child(6) {
        --kp-fo-col: 5;
    }

    [data-theme='forest'] .kp-calendar__grid td:nth-child(7) {
        --kp-fo-col: 6;
    }

    [data-theme='forest'] .kp-calendar__grid tbody tr:nth-child(2) {
        --kp-fo-row: 1;
    }

    [data-theme='forest'] .kp-calendar__grid tbody tr:nth-child(3) {
        --kp-fo-row: 2;
    }

    [data-theme='forest'] .kp-calendar__grid tbody tr:nth-child(4) {
        --kp-fo-row: 3;
    }

    [data-theme='forest'] .kp-calendar__grid tbody tr:nth-child(5) {
        --kp-fo-row: 4;
    }

    [data-theme='forest'] .kp-calendar__grid tbody tr:nth-child(6) {
        --kp-fo-row: 5;
    }

    /* Calendar · shape: leaf corner (Kenny's choice, 2026-10-10): soft organic
       leaf corner matching the theme's plate grammar, displayed in display face. */
    [data-theme='forest'] .kp-calendar__day {
        position: relative;
        isolation: isolate;
        border-width: 1px;
        border-radius: 0 var(--kp-sig-fo-leaf, 0.5rem) 0 var(--kp-sig-fo-leaf, 0.5rem);
        box-shadow: none;
        font-family: var(--theme-font-display);
    }

    [data-theme='forest'] .kp-calendar__pad {
        position: relative;
        border: 1px dashed hsl(from var(--foreground) h s l / 0.15);
        border-radius: 0 var(--kp-sig-fo-leaf, 0.5rem) 0 var(--kp-sig-fo-leaf, 0.5rem);
        font-family: var(--theme-font-display);
        box-sizing: border-box;
    }

    [data-theme='forest'] .kp-calendar__swatch {
        border-radius: var(--kp-sig-fo-part);
    }

    [data-theme='forest'] .kp-calendar__title {
        font-family: var(--theme-font-display);
        font-style: italic;
    }

    [data-theme='forest'] .kp-calendar__grid th {
        font-style: italic;
    }

    /* Calendar · tone 2, the trail map: each state is a patch of map. A kept
       night carries the trail blaze along its start edge in its own ink, a
       night with nothing done a double blaze; a night not known is a dashed
       patch with a question mark, a day to come a dotted one, a day before
       the record hatched; today is ringed in green with a map pin. */
    [data-theme='forest']
        :is(.kp-calendar__day, .kp-calendar__swatch, .kp-matrix__cell, .kp-heat__swatch--plate):is(
            [data-kp-tone='ok'],
            [data-kp-tone='warn'],
            [data-kp-tone='bad']
        ) {
        background-image: linear-gradient(var(--kp-fo-blaze) 0 0);
        background-position: left 3px center;
        background-size: 4px calc(100% - 10px);
        background-repeat: no-repeat;
    }

    [data-theme='forest'] :is(.kp-calendar__day, .kp-calendar__swatch, .kp-matrix__cell, .kp-heat__swatch--plate)[data-kp-tone='ok'] {
        --kp-fo-blaze: var(--success-foreground);
        border-color: hsl(from var(--success-foreground) h s l / 0.3);
    }

    [data-theme='forest'] :is(.kp-calendar__day, .kp-calendar__swatch, .kp-matrix__cell, .kp-heat__swatch--plate)[data-kp-tone='warn'] {
        --kp-fo-blaze: var(--warning-foreground);
        border-color: hsl(from var(--warning-foreground) h s l / 0.3);
    }

    [data-theme='forest'] :is(.kp-calendar__day, .kp-calendar__swatch, .kp-matrix__cell, .kp-heat__swatch--plate)[data-kp-tone='bad'] {
        --kp-fo-blaze: var(--destructive-foreground);
        background-image: linear-gradient(var(--kp-fo-blaze) 0 0), linear-gradient(var(--kp-fo-blaze) 0 0);
        background-position:
            left 3px center,
            left 9px center;
        background-size: 3px calc(100% - 10px);
    }

    [data-theme='forest'] .kp-calendar__day[data-kp-tone='bad'] {
        padding-inline-start: 0.8rem;
    }

    [data-theme='forest'] :is(.kp-calendar__day, .kp-calendar__swatch, .kp-matrix__cell, .kp-heat__swatch--plate)[data-kp-tone='muted'] {
        border-color: var(--border);
    }

    [data-theme='forest'] :is(.kp-calendar__day, .kp-calendar__swatch, .kp-matrix__cell, .kp-heat__swatch--plate)[data-kp-tone='none'] {
        border-style: dashed;
        border-color: var(--border-strong);
        background: var(--card);
    }

    [data-theme='forest'] .kp-calendar__day[data-kp-tone='none']::before {
        content: '?';
        position: absolute;
        z-index: -1;
        inset-block-start: 0.125rem;
        inset-inline-end: 0.25rem;
        color: var(--border-strong);
        font-size: 0.6rem;
        font-weight: 700;
        line-height: 1;
        pointer-events: none;
    }

    [data-theme='forest'] :is(.kp-calendar__day, .kp-calendar__swatch, .kp-matrix__cell, .kp-heat__swatch--plate)[data-kp-tone='future'] {
        border-style: dotted;
        border-color: var(--border-strong);
        background: transparent;
    }

    [data-theme='forest'] :is(.kp-calendar__day, .kp-calendar__swatch, .kp-matrix__cell, .kp-heat__swatch--plate)[data-kp-tone='before'] {
        border-color: transparent;
        background: repeating-linear-gradient(-45deg, hsl(from var(--border-strong) h s l / 0.3) 0 1px, transparent 1px 5px);
    }

    [data-theme='forest'] .kp-calendar__day[data-kp-today] {
        box-shadow:
            inset 0 0 0 2px var(--primary),
            inset 0 0 0 5px hsl(from var(--foreground) h s l / 0.08);
    }

    [data-theme='forest'] .kp-calendar__grid td:has(> .kp-calendar__day[data-kp-today])::after {
        content: '';
        position: absolute;
        inset: -5px -3px auto auto;
        inline-size: 12px;
        block-size: 12px;
        border-radius: 50% 50% 50% 0;
        rotate: -45deg;
        background: radial-gradient(circle, var(--card) 0 2px, transparent 2.5px), var(--chart-2);
        box-shadow: 0 0 0 1px var(--foreground);
        pointer-events: none;
    }

    /* Calendar · select 3, the pick is the person's act, so it is forest
       green (G5, proposal-13), 2 px out; the field note's brackets stay round
       the picked day's count, and a pointed day underlines its number. */
    [data-theme='forest'] td[aria-selected='true'] > .kp-calendar__day {
        z-index: 1;
        outline: 2px solid var(--primary);
        outline-offset: 2px;
    }

    [data-theme='forest'] td[aria-selected='true'] > .kp-calendar__day .kp-calendar__count::before {
        content: '[';
    }

    [data-theme='forest'] td[aria-selected='true'] > .kp-calendar__day .kp-calendar__count::after {
        content: ']';
    }

    [data-theme='forest'] .kp-calendar__day:hover .kp-calendar__num {
        text-decoration: underline 2px;
        text-underline-offset: 2px;
    }

    /* Calendar · loading 1, the falling leaf → a day has no room for a row,
       so it plants one tree on its mound in three whole stages (§6.7), the
       spinner's own drawing; the date stands faint over it. Where the package
       already puts the spinner (a tree) in a loading day, the day draws none,
       and while the whole month waits its card's planting row is the one
       picture: the days stand faint without a tree (Kenny, 2026-10-09 on
       research/forest-uniformity, loading: "one picture per waiting panel"). */
    [data-theme='forest']
        :is(.kp-calendar:not(.kp-calendar--busy-days, .kp-calendar--busy-whole), .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true']))
        .kp-calendar__day[data-kp-tone='loading'] {
        border-color: var(--border);
        background: var(--card);
        color: hsl(from var(--foreground) h s l / 0.25);
        animation: none;
    }

    [data-theme='forest'] .kp-calendar:not(.kp-calendar--busy-days, .kp-calendar--busy-whole) .kp-calendar__day[data-kp-tone='loading']::before,
    [data-theme='forest'] .kp-calendar:not(.kp-calendar--busy-days, .kp-calendar--busy-whole) .kp-calendar__day[data-kp-tone='loading']::after {
        content: '';
        position: absolute;
        z-index: -1;
        inset: 14% 36% 10%;
        background: var(--primary);
        pointer-events: none;
    }

    [data-theme='forest'] .kp-calendar:not(.kp-calendar--busy-days, .kp-calendar--busy-whole) .kp-calendar__day[data-kp-tone='loading']::before {
        opacity: 0.6;
        mask: var(--kp-fo-mound) 50% 100% / 100% 100% no-repeat;
    }

    [data-theme='forest'] .kp-calendar:not(.kp-calendar--busy-days, .kp-calendar--busy-whole) .kp-calendar__day[data-kp-tone='loading']::after {
        /* Standing still (reduced motion) it is the grown tree. */
        mask: var(--kp-fo-stages) 100% 100% / 300% 100% no-repeat;
    }

    /* Tiles · live 2 and columns · live 1, the sway → a growth ring round the
       tile or the column whose value js/update.js changed (G8): drawn once on
       the plate's own leaf, clockwise from the top; the figure never moves,
       and the ring round the value itself is not drawn twice. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest']
            :is(.kp-tiles > .kp-card, .kp-kpis[data-kp-kpis-columns] > .kp-kpi):has([data-kp-updating='ring']):not([aria-busy='true']) {
            position: relative;
        }

        [data-theme='forest']
            :is(.kp-tiles > .kp-card, .kp-kpis[data-kp-kpis-columns] > .kp-kpi):has([data-kp-updating='ring']):not([aria-busy='true'])::after {
            content: '';
            position: absolute;
            inset: -5px;
            border: 1.5px solid var(--primary);
            border-radius: 0 calc(var(--kp-sig-fo-leaf) + 5px);
            mask: conic-gradient(var(--foreground) var(--kp-fo-arc), transparent 0);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-forest-update-ring var(--kp-sig-fo-time) linear both;
        }

        [data-theme='forest']
            :is(.kp-tiles > .kp-card, .kp-kpis[data-kp-kpis-columns] > .kp-kpi)
            [data-kp-updating='ring']:not(.kp-state-word)::after,
        [data-theme='forest'] :is(.kp-tiles > .kp-card, .kp-kpis[data-kp-kpis-columns] > .kp-kpi) .kp-state-word[data-kp-updating='ring']::before {
            content: none;
        }

        /* Tiles · hover 3: the blaze is laid in contact time. */
        [data-theme='forest'] .kp-tiles > .kp-card {
            transition:
                outline-color var(--fx-duration) var(--fx-ease),
                outline-offset var(--fx-duration) var(--fx-ease);
        }

        /* Calendar · arrival: in-month days grow up out of the ground.
           Pad days (dates not part of selected month) do the exact opposite:
           they wither / sink down into the ground on kp-sig-forest-pad-wither. */
        [data-theme='forest'] .kp-calendar__grid:not([aria-busy='true']) .kp-calendar__day {
            animation: kp-sig-forest-grow var(--kp-sig-fo-time) var(--kp-sig-fo-grow)
                calc((var(--kp-fo-row, 0) * 7 + var(--kp-fo-col, 0)) * var(--kp-sig-fo-stagger) / 4) backwards;
        }

        [data-theme='forest'] .kp-calendar__grid:not([aria-busy='true']) td[data-kp-pad] > .kp-calendar__pad {
            animation: kp-sig-forest-pad-wither var(--kp-sig-fo-time) var(--kp-sig-fo-wither)
                calc((var(--kp-fo-row, 0) * 7 + var(--kp-fo-col, 0)) * var(--kp-sig-fo-stagger) / 4) both;
        }

        /* Calendar · loading 1: one tree a half loop, the days of a week
           150 ms apart. */
        [data-theme='forest'] .kp-calendar:not(.kp-calendar--busy-days, .kp-calendar--busy-whole) .kp-calendar__day[data-kp-tone='loading']::after {
            animation: kp-sig-forest-plant calc(var(--kp-sig-fo-loop) / 2) step-end calc(var(--kp-fo-col, 0) * -150ms) infinite;
        }

        /* Drawer · openclose 1, the drawer grows out of its edge (the trunk),
           far side first, clipped at the edge, one growth on the growth curve
           (G3); js/motion.js closes it as this growth reversed, in the same
           time. Mirrored on a right-to-left page. */
        [data-theme='forest'] dialog.kp-drawer {
            animation: kp-sig-forest-edge var(--kp-sig-dur) var(--kp-sig-fo-grow) backwards;
        }

        [data-theme='forest'] dialog.kp-drawer:dir(rtl) {
            animation-name: kp-sig-forest-edge-rtl;
        }
    }

    /* Growth out of an edge [G3]: what lives at the window's end edge grows
       out of it, its far side first, moved in from behind the edge and
       clipped there, so its words keep their shape. */
    @keyframes kp-sig-forest-edge {
        from {
            translate: 100% 0;
            clip-path: inset(calc(-1 * var(--kp-sig-fo-reach)) 100% calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)));
        }

        to {
            translate: 0 0;
            clip-path: inset(calc(-1 * var(--kp-sig-fo-reach)) 0 calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)));
        }
    }

    @keyframes kp-sig-forest-edge-rtl {
        from {
            translate: -100% 0;
            clip-path: inset(calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)) 100%);
        }

        to {
            translate: 0 0;
            clip-path: inset(calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)) 0);
        }
    }

    /* ── Forest, straightened [Kenny, 2026-10-09: all ten questions of
       research/forest-uniformity approved, every recommendation]. What the
       first apply did not reach, on the same grammar: the bar, the overlays
       that did not grow, the closes that were not their opens, the alarm,
       and the busy panels' one picture. themes/forest/CHARACTER.md §5,
       "Applied 2026-10-09 (uniformity)". ── */

    /* The bar · the dropdown and the mega menu grow down out of their link,
       far end first, clipped at the bar's line all the way, and close as
       that growth backwards: a transition takes the curve of the state it
       goes to, so the opening runs on the growth curve and the close on the
       curve turned around, and a close begun halfway turns round where it
       stands. Shown, it stays drawn through its close (display is held). */
    [data-theme='forest'] .kp-nav__menu {
        opacity: 1;
        translate: var(--kp-nav-menu-shift, 0) -100%;
        clip-path: inset(100% calc(-1 * var(--kp-sig-fo-reach)) 0 calc(-1 * var(--kp-sig-fo-reach)));
    }

    [data-theme='forest']
        :is(
            .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
            .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
        ) {
        translate: var(--kp-nav-menu-shift, 0) 0;
        clip-path: inset(0 calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)));
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-nav__menu {
            transition:
                translate var(--kp-sig-fo-time) var(--kp-sig-fo-wither),
                clip-path var(--kp-sig-fo-time) var(--kp-sig-fo-wither),
                display var(--kp-sig-fo-time) allow-discrete;
        }

        [data-theme='forest']
            :is(
                .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
            ) {
            transition-timing-function: var(--kp-sig-fo-grow);
        }

        @starting-style {
            [data-theme='forest']
                :is(
                    .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                    .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
                ) {
                translate: var(--kp-nav-menu-shift, 0) -100%;
                clip-path: inset(100% calc(-1 * var(--kp-sig-fo-reach)) 0 calc(-1 * var(--kp-sig-fo-reach)));
            }
        }
    }

    /* The bar collapsed on a phone: its links grow down out of the bar, far
       end first, and go back into it as that growth played backwards (the
       same frames under a second name, so the close restarts); the lists
       nested in it are the open panel's own rows and do not grow again. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='forest'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__links .kp-nav__menu {
            translate: none;
            clip-path: none;
        }

        [data-theme='forest'] .kp-nav:has(> .kp-nav__toggle) > .kp-nav__links {
            overflow: clip;
            /* One column that never wraps: under a ceiling a wrapping column
               moves its last rows into new columns, so the height grew in
               whole rows and the items jumped sideways. */
            flex-wrap: nowrap;
            max-block-size: 0;
            opacity: 0;
            transition:
                max-block-size var(--kp-sig-fo-time) var(--kp-sig-fo-wither),
                opacity var(--kp-sig-fo-time) var(--kp-sig-fo-wither);
        }

        [data-theme='forest'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
            max-block-size: var(--kp-nav-links-height, 25rem);
            opacity: 1;
            transition:
                max-block-size var(--kp-sig-fo-time) var(--kp-sig-fo-grow),
                opacity var(--kp-sig-fo-time) var(--kp-sig-fo-grow);
        }

        @starting-style {
            [data-theme='forest'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
                max-block-size: 0;
                opacity: 0;
            }
        }

        [data-theme='forest'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-closing] > .kp-nav__links {
            max-block-size: 0;
            opacity: 0;
            transition:
                max-block-size var(--kp-sig-fo-time) var(--kp-sig-fo-wither),
                opacity var(--kp-sig-fo-time) var(--kp-sig-fo-wither);
        }

        @media (prefers-reduced-motion: no-preference) {
            [data-theme='forest'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__links .kp-nav__menu {
                transition: none;
            }
        }
    }

    /* The side navigation grows out of its edge like the drawer, far side
       first, clipped at that edge, in one growth (Kenny, overlays: "each
       grows like its family"), and goes back as that growth reversed; its
       groups unfold in the same growth time as the accordion (pairs). */
    [data-theme='forest'] .kp-sidenav {
        --kp-sidenav-duration: var(--kp-sig-fo-time);
        --kp-sidenav-ease: var(--kp-sig-fo-grow);
    }

    [data-theme='forest']
        :is(.kp-sidenav:not([data-kp-sidenav-side='end']):dir(ltr), .kp-sidenav[data-kp-sidenav-side='end']:dir(rtl)):is(
            [data-kp-sidenav-mode='over'],
            [data-kp-sidenav-mode='push']
        ) {
        clip-path: inset(calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)) 100%);
    }

    [data-theme='forest']
        :is(.kp-sidenav[data-kp-sidenav-side='end']:dir(ltr), .kp-sidenav:not([data-kp-sidenav-side='end']):dir(rtl)):is(
            [data-kp-sidenav-mode='over'],
            [data-kp-sidenav-mode='push']
        ) {
        clip-path: inset(calc(-1 * var(--kp-sig-fo-reach)) 100% calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)));
    }

    [data-theme='forest']
        :is(.kp-sidenav:not([data-kp-sidenav-side='end']):dir(ltr), .kp-sidenav[data-kp-sidenav-side='end']:dir(rtl)):is(
            [data-kp-sidenav-mode='over'],
            [data-kp-sidenav-mode='push']
        )[data-kp-sidenav-open='true'] {
        clip-path: inset(calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)) 0);
    }

    [data-theme='forest']
        :is(.kp-sidenav[data-kp-sidenav-side='end']:dir(ltr), .kp-sidenav:not([data-kp-sidenav-side='end']):dir(rtl)):is(
            [data-kp-sidenav-mode='over'],
            [data-kp-sidenav-mode='push']
        )[data-kp-sidenav-open='true'] {
        clip-path: inset(calc(-1 * var(--kp-sig-fo-reach)) 0 calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)));
    }

    /* The panel slides with everything in it: its clip opens when the opening
       starts and closes when the closing ends, so no content is cut away from
       its own edge on the way (Kenny, round 5: "de content verdwijnt instant
       als het sluiten begint, de content moet mee naar links verschuiven"). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) {
            transition:
                translate var(--kp-sig-fo-time) var(--kp-sig-fo-grow),
                clip-path 0s linear,
                inline-size var(--kp-sig-fo-time) var(--kp-sig-fo-grow);
        }

        [data-theme='forest']
            .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']):is(
                [data-kp-sidenav-open='false'],
                [data-kp-sidenav-slim-collapsed]:not(
                    [data-kp-sidenav-peek='open'],
                    [data-kp-sidenav-expand-on-hover]:not([data-kp-sidenav-attached]):hover
                )
            ) {
            transition:
                translate var(--kp-sig-fo-time) var(--kp-sig-fo-wither),
                clip-path 0s linear var(--kp-sig-fo-time),
                inline-size var(--kp-sig-fo-time) var(--kp-sig-fo-wither);
        }

        /* Every backdrop comes with its plate, on the growth curve (F-25):
           the side navigation's, the dialog's and the drawer's. */
        [data-theme='forest'] .kp-sidenav__backdrop {
            animation: kp-sig-forest-fade var(--kp-sig-fo-time) var(--kp-sig-fo-grow) both;
        }

        [data-theme='forest'] .kp-sidenav__backdrop[data-kp-reversing='play'] {
            animation: kp-sig-forest-fade-back var(--kp-sig-fo-time) var(--kp-sig-fo-grow) reverse both !important;
        }

        /* The alarm's ground is transparent, but its backdrop still carries the
           fade, so js/motion.js plays the close as that fade reversed (audit
           row 19: it had fallen back to its own 1000 ms ease-in). */
        [data-theme='forest'] :is(.kp-dialog, .kp-alarm)[open]::backdrop {
            animation: kp-sig-forest-fade var(--kp-sig-fo-time, 1000ms) var(--kp-sig-fo-grow, ease-out) backwards;
        }
    }

    /* The command palette grows up out of its base like the dialog, its
       backdrop with it. Where the browser can keep a closing dialog in the
       top layer (overlay), it closes as that growth played backwards; where
       it cannot, it goes at once until js/motion.js reverses it as it does
       a .kp-dialog (research/PACKAGE_FINDINGS.md). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] dialog.kp-palette[open] {
            animation: kp-sig-forest-grow var(--kp-sig-fo-time) var(--kp-sig-fo-grow) backwards;
        }

        [data-theme='forest'] dialog.kp-palette[open]::backdrop {
            animation: kp-sig-forest-fade var(--kp-sig-fo-time, 1000ms) var(--kp-sig-fo-grow, ease-out) backwards;
        }

        /* The close is js/motion.js's, in every engine: it keeps the palette
           open while it plays the growth backwards, as it does for a dialog. */

        /* The tour's card grows up out of its own line from autumn to green
           (pairs), and js/tour.js plays that backwards when the tour ends. */
        [data-theme='forest'] .kp-tour[open]:not([data-kp-tour-stepping]) {
            animation: kp-sig-forest-arrive var(--kp-sig-fo-time) var(--kp-sig-fo-grow) backwards;
        }

        /* The page dims around the target on the growth time and curve, and the
           close takes it back on the reversed curve (css/components.css), so the
           two are mirrors. */
        [data-theme='forest'] [data-kp-tour-target] {
            /* `backwards`, not `both`: a ring held by a finished animation
               cannot be faded by the close's transition (css/components.css,
               on the withering curve), and went at once. */
            animation: kp-sig-forest-tour-ring var(--kp-sig-fo-time) var(--kp-sig-fo-grow) backwards;
            /* The dim grows by the animation, not by a transition (review round 2, Kenny 2026-10-13:
               "Bij de laatste stap is nog altijd een flash van groen dat over het scherm gaat"): a
               transition starts from the part's own shadow, and a card's is the package's
               `0 0 0 0 var(--border-strong)`, forest's green-grey, so on the step to the last card
               the dim grew out of the card in green across the whole screen. The animation starts
               from no shadow on every target, which is what the transition did on a part without a
               shadow of its own (the row, the field): those frames are unchanged. A transition
               outranks an animation, so box-shadow is out of this list; the close keeps its own
               (css/components.css, `[data-kp-reversing]`, important). */
            transition: outline-color var(--kp-sig-fo-time) var(--kp-sig-fo-grow);
        }

        /* A step walks the card to the next target on the growth time and
           curve, its shape untouched. */
        /* A step is no arrival and no news: the card keeps its shape, plays no entrance again and
           draws no ring round itself; it walks to the next target and swaps its words. */
        [data-theme='forest'] .kp-tour[data-kp-tour-stepping] {
            animation: none;
        }

        [data-theme='forest'] .kp-tour[data-kp-updating]::after {
            content: none;
            animation: none;
        }

        [data-theme='forest'] .kp-tour[data-kp-tour-stepping] {
            transition:
                left var(--kp-sig-fo-time) var(--kp-sig-fo-grow),
                top var(--kp-sig-fo-time) var(--kp-sig-fo-grow);
        }
    }

    /* The alarm · grows like the dialog; a growth ring keeps calling (Kenny,
       2026-10-09 on research/forest-uniformity, the alarm: "a growth ring
       instead of the glow pulse"). Its frame takes the plate's leaf and its
       glow gives way to a ring laid just outside the frame: drawn clockwise
       from the top on the growth curve in 550 ms, then it fades, once every
       loop (3200 ms) after the growth, for as long as the alarm waits.
       Standing still the ring stands whole. */
    [data-theme='forest'] .kp-alarm::before {
        border-radius: var(--kp-sig-fo-plate);
    }

    [data-theme='forest'] .kp-alarm::after {
        inset: calc(var(--kp-alarm-bar, 0.9rem) + 0.75rem - 7px) calc(0.75rem - 7px);
        border: 1.5px solid var(--primary);
        border-radius: 0 calc(var(--kp-sig-fo-leaf) + 7px);
        box-shadow: none;
        mask: conic-gradient(var(--foreground) var(--kp-fo-arc), transparent 0);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            animation: kp-sig-forest-ground var(--kp-sig-fo-time) var(--kp-sig-fo-grow) backwards;
        }

        [data-theme='forest'] .kp-alarm:not([data-kp-alarm-motion='still'])::before,
        [data-theme='forest'] .kp-alarm:not([data-kp-alarm-motion='still']) .kp-alarm__panel {
            animation: kp-sig-forest-grow var(--kp-sig-fo-time) var(--kp-sig-fo-grow) backwards;
        }

        [data-theme='forest'] .kp-alarm:not([data-kp-alarm-motion='still']) :is(.kp-alarm__title, .kp-alarm__detail) {
            animation: none;
        }

        [data-theme='forest'] .kp-alarm:not([data-kp-alarm-motion='still'])::after {
            animation: kp-sig-forest-alarm-ring var(--kp-sig-fo-loop) linear var(--kp-sig-fo-time) infinite both;
        }
    }

    @keyframes kp-sig-forest-ground {
        from {
            background-color: transparent;
        }
    }

    @keyframes kp-sig-forest-alarm-ring {
        0% {
            --kp-fo-arc: 0deg;
            opacity: 1;
            animation-timing-function: linear(
                0 0%,
                0.01 5%,
                0.032 10%,
                0.072 15%,
                0.133 20%,
                0.211 25%,
                0.302 30%,
                0.398 35%,
                0.493 40%,
                0.582 45%,
                0.662 50%,
                0.732 55%,
                0.791 60%,
                0.84 65%,
                0.881 70%,
                0.913 75%,
                0.939 80%,
                0.96 85%,
                0.977 90%,
                0.99 95%,
                1 100%
            );
        }

        17.1875% {
            --kp-fo-arc: 360deg;
            opacity: 1;
            animation-timing-function: ease-in-out;
        }

        31.25%,
        100% {
            --kp-fo-arc: 360deg;
            opacity: 0;
        }
    }

    /* One picture per waiting panel (Kenny, loading: "the row where it fits,
       the tree where it does not"): the busy table's panel and the busy
       month's card show the planting row at their foot and no tree; the
       spinner's tree stays where a row has no room (alone, in a day, beside
       the status line's words). The month's card keeps room for a row. */
    [data-theme='forest'] :is(.kp-datatable__busy-panel, .kp-calendar__busy) > .kp-spinner {
        display: none;
    }

    [data-theme='forest'] .kp-datatable__busy-panel {
        grid-template-columns: minmax(0, 1fr);
    }

    /* The busy table's layer arrives as its leave played backwards and leaves
       by js/motion.js leave() (`--kp-leave-state: leave`): one mechanism, so
       the layer's own animations, which a loop on the same part overrode, are
       gone. The table and its rows beneath it dim and come back on the growth time, on the
       curve of the state they go to (a transition back takes the withering
       curve), so the table under the layer is the same pair. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-datatable,
        [data-theme='forest'] .kp-datatable .kp-table tbody {
            transition: opacity var(--kp-sig-fo-time) var(--kp-sig-fo-wither);
        }

        [data-theme='forest'] .kp-datatable[aria-busy='true'],
        [data-theme='forest'] .kp-datatable[aria-busy='true'] .kp-table tbody {
            transition-timing-function: var(--kp-sig-fo-grow);
        }
    }

    [data-theme='forest'] .kp-calendar--busy-whole > .kp-calendar__busy {
        min-inline-size: min(14rem, 100%);
        min-block-size: 4rem;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: flex-start;
        padding: var(--kp-space-sm, 0.5rem);
    }

    [data-theme='forest'] .kp-calendar__busy-text {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.875rem;
        font-weight: 500;
        text-align: center;
        color: var(--foreground);
        margin-block-end: calc(var(--kp-fo-h, 1rem) + 0.35rem);
    }

    /* The busy month's card grows up out of its own line and withers back
       into it (F-33), like every arrival; the transitions run each way on
       the curve of the state they go to. */
    [data-theme='forest'] .kp-calendar--busy-whole > .kp-calendar__busy {
        translate: 0 100%;
        clip-path: inset(0 calc(-1 * var(--kp-sig-fo-reach)) 100% calc(-1 * var(--kp-sig-fo-reach)));
    }

    [data-theme='forest'] .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true']) > .kp-calendar__busy {
        translate: 0 0;
        clip-path: inset(calc(-1 * var(--kp-sig-fo-reach)) calc(-1 * var(--kp-sig-fo-reach)) -1px calc(-1 * var(--kp-sig-fo-reach)));
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-calendar--busy-whole > .kp-calendar__busy {
            transition:
                translate var(--kp-sig-fo-time) var(--kp-sig-fo-wither),
                clip-path var(--kp-sig-fo-time) var(--kp-sig-fo-wither),
                display var(--kp-sig-fo-time) allow-discrete;
        }

        [data-theme='forest'] .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true']) > .kp-calendar__busy {
            transition-timing-function: var(--kp-sig-fo-grow);
        }

        @starting-style {
            [data-theme='forest'] .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true']) > .kp-calendar__busy {
                translate: 0 100%;
                clip-path: inset(0 calc(-1 * var(--kp-sig-fo-reach)) 100% calc(-1 * var(--kp-sig-fo-reach)));
            }
        }

        /* Back to top fades in contact time and out on the curve turned
           around; it keeps the button's contact answers. */
        [data-theme='forest'] .kp-to-top {
            transition:
                opacity var(--fx-duration) var(--fx-ease),
                visibility var(--fx-duration) var(--fx-ease),
                outline-color var(--fx-duration) var(--fx-ease),
                outline-offset var(--fx-duration) var(--fx-ease),
                outline-style var(--fx-duration) allow-discrete,
                box-shadow var(--fx-duration) var(--fx-ease);
        }

        [data-theme='forest'] .kp-to-top:not([data-kp-to-top-shown]) {
            transition-timing-function: var(--kp-sig-fo-wither);
        }
    }

    /* Rows · a tree row answers as a menu entry on its own line: a branch
       holds its children inside it, so the kraft ground and the blaze are
       drawn on a layer as tall as its first line, under its words, for the
       innermost row pointed at only. */
    [data-theme='forest'] .kp-tree [role='treeitem'] {
        position: relative;
        isolation: isolate;
        padding-inline-start: calc(0.5rem + var(--kp-tree-depth, 0) * var(--kp-tree-indent, 1rem));
    }

    [data-theme='forest'] .kp-tree [role='treeitem']:hover:not([aria-selected='true']) {
        background: none;
    }

    [data-theme='forest'] .kp-tree [role='treeitem']::after {
        content: '';
        position: absolute;
        z-index: -1;
        inset: 0 0 auto;
        block-size: calc(1lh + 0.5rem);
        border-radius: var(--kp-sig-fo-part);
        outline: 2px dashed transparent;
        outline-offset: 5px;
        pointer-events: none;
    }

    [data-theme='forest'] .kp-tree [role='treeitem']:hover:not(:has([role='treeitem']:hover))::after {
        outline-color: var(--primary);
        outline-offset: -3px;
    }

    [data-theme='forest'] .kp-tree [role='treeitem']:not([aria-selected='true']):hover:not(:has([role='treeitem']:hover))::after {
        background: var(--secondary);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-tree [role='treeitem']::after {
            transition:
                outline-color var(--fx-duration) var(--fx-ease),
                outline-offset var(--fx-duration) var(--fx-ease),
                background-color var(--fx-duration) var(--fx-ease);
        }
    }

    /* ── Audit round (research/forest-applied/_audit/MISSING.md) ───────── */

    /* Row 17, press on rows: a row that answers the pointer with the blaze
       answers the press by closing it in and turning it solid (G12), as a
       button does. The offset (-3px) is the row family's hover rule above. A
       check and a switch close it to 1px, like a button. */
    [data-theme='forest']
        :where(
            .kp-menu [data-kp-theme],
            .kp-combobox__option,
            .kp-palette__option,
            .kp-accordion__summary,
            .kp-nav__menu a,
            .kp-sidenav__link,
            .kp-sidenav__category-toggle,
            .kp-table tbody tr,
            .kp-field__check,
            .kp-switch__input
        ):active:not(:disabled, [aria-disabled='true'], :focus-visible) {
        outline-style: solid;
        outline-color: var(--primary);
    }

    [data-theme='forest'] :where(.kp-field__check, .kp-switch__input):active:not(:disabled, :focus-visible) {
        outline-offset: 1px;
    }

    [data-theme='forest'] .kp-tree [role='treeitem']:active:not(:has([role='treeitem']:active))::after {
        outline-style: solid;
        outline-color: var(--primary);
        outline-offset: -3px;
    }

    /* Row 16, hover answers: a day of the month, the month's title, a
       sortable header and a tag's remove button blaze like every other part
       pointed at (G12). The picked day keeps its green ring; the remove
       button stays round (a wood's round part) and loses the red disc, since
       a person's act is green (G5). The title's grey wash goes. A header is a
       cell in a row of cells, so its ring is laid inside. */
    [data-theme='forest']
        :where(td:not([aria-selected='true']) > .kp-calendar__day, button.kp-datepicker__title, .kp-table th[data-kp-sort], .kp-tag__remove) {
        outline: 2px dashed transparent;
        outline-offset: 5px;
    }

    [data-theme='forest']
        :where(td:not([aria-selected='true']) > .kp-calendar__day, button.kp-datepicker__title, .kp-tag__remove):hover:not(
            :disabled,
            [aria-disabled='true'],
            :focus-visible
        ) {
        outline-color: var(--primary);
        outline-offset: 2px;
    }

    [data-theme='forest'] .kp-table th[data-kp-sort]:hover {
        outline-color: var(--primary);
        outline-offset: -3px;
    }

    [data-theme='forest']
        :where(td:not([aria-selected='true']) > .kp-calendar__day, button.kp-datepicker__title, .kp-tag__remove):active:not(
            :disabled,
            [aria-disabled='true'],
            :focus-visible
        ) {
        outline-style: solid;
        outline-color: var(--primary);
        outline-offset: 1px;
    }

    [data-theme='forest'] .kp-table th[data-kp-sort]:active {
        outline-style: solid;
        outline-color: var(--primary);
        outline-offset: -3px;
    }

    [data-theme='forest'] button.kp-datepicker__title:hover,
    [data-theme='forest'] .kp-tag__remove:hover {
        background: none;
        color: inherit;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-tree [role='treeitem']::after {
            transition:
                outline-color var(--fx-duration) var(--fx-ease),
                outline-offset var(--fx-duration) var(--fx-ease),
                outline-style var(--fx-duration) var(--fx-ease) allow-discrete,
                background-color var(--fx-duration) var(--fx-ease);
        }

        [data-theme='forest'] .kp-calendar__day,
        [data-theme='forest'] button.kp-datepicker__title,
        [data-theme='forest'] .kp-table th[data-kp-sort],
        [data-theme='forest'] .kp-tag__remove {
            transition:
                outline-color var(--fx-duration) var(--fx-ease),
                outline-offset var(--fx-duration) var(--fx-ease),
                outline-style var(--fx-duration) var(--fx-ease) allow-discrete,
                box-shadow var(--fx-duration) var(--fx-ease),
                background-color var(--fx-duration) var(--fx-ease),
                color var(--fx-duration) var(--fx-ease);
        }
    }

    /* Row 8, one loading picture: while the busy table's overlay plants its
       row over the rows, the status line's small tree stays out. */
    [data-theme='forest'] .kp-datatable:has(> .kp-datatable__busy-overlay) .kp-datatable__status > .kp-spinner {
        display: none;
    }

    /* Row 13, the phone bar's toggle: its tint follows aria-expanded, which the
       script flips when the close starts, not data-kp-nav-open, which stays
       until the close has played. */
    [data-theme='forest'] .kp-nav[data-kp-nav-open] > .kp-nav__toggle:not([aria-expanded='true']) {
        background: transparent;
        color: inherit;
        border-color: var(--border-strong);
    }

    /* A day of the month takes DI2's two channels (F-14), its log rings
       kept inside, today's green ring too. */
    [data-theme='forest'] .kp-calendar__day:focus-visible,
    [data-theme='forest'] td[aria-selected='true'] > .kp-calendar__day:focus-visible {
        outline: var(--focus-ring-width, 2px) solid var(--focus-ring-contrast);
        outline-offset: var(--kp-focus-ring-inner-width, 2px);
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 5px hsl(from var(--foreground) h s l / 0.08);
    }

    [data-theme='forest'] .kp-calendar__day[data-kp-today]:focus-visible {
        box-shadow:
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 2px var(--primary),
            inset 0 0 0 5px hsl(from var(--foreground) h s l / 0.08);
    }
}
/* ── End of the signature ── */

/* The code block is the layout layer's (css/layout.css sits after kp.signature, so
   its 0.5rem radius wins over the plate list above). A block of code is a plate:
   forest's leaf, 0 and the token (audit row 14). */
@layer kp.layout {
