}

/* ── Segmented control, list toolbar, key line [kpadopt-controls] ── */
@layer kp.signature {
    [data-theme='forest'] .kp-segmented {
        --kp-seg-radius: 0.9rem;
        --kp-seg-thumb: var(--primary);
        --kp-seg-thumb-ink: var(--primary-foreground);
        --kp-seg-thumb-edge: 0 0 0 0 transparent;
        --kp-seg-thumb-lift: 0 2px 0 hsl(from var(--primary) h s calc(l * 0.6));
        --kp-chip-on: var(--primary);
        --kp-chip-on-ink: var(--primary-foreground);
    }
    [data-theme='forest'] .kp-toolbar {
        --kp-toolbar-group-gap: 1.125rem;
    }
