        --kp-kbd-radius: 0.3rem;
        --kp-kbd-ground: var(--card);
        --kp-kbd-foot: 3px;
    }
    /* The chosen word sits on a leaf: two rounded corners, two nearly square. */
    [data-theme='forest'] .kp-segmented[data-kp-segmented-thumb]::before,
    [data-theme='forest'] .kp-segmented:not(.kp-segmented--chips) > .kp-segmented__item[aria-checked='true'],
    [data-theme='forest'] .kp-segmented:not(.kp-segmented--chips) > .kp-segmented__item[aria-pressed='true'],
    [data-theme='forest'] .kp-segmented--chips > .kp-segmented__item[aria-pressed='true'] {
        border-radius: 0.95rem 0.2rem 0.95rem 0.2rem;
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — forest: paper and wood. The current tab is a trail blaze: a short clay mark painted on the bar's edge that grows in slowly, the way a tree does; the paper label turns forest ink (G1, G5, G12); a count is a paper tab. */
    [data-theme='forest'] .kp-tabbar {
        background: color-mix(in srgb, var(--background) 92%, transparent);
        border-block-start-color: var(--border);
    }

    [data-theme='forest'] .kp-tabbar__tab {
        border-radius: var(--radius);
    }

    [data-theme='forest'] .kp-tabbar__tab::before {
        inset-inline: calc(50% - 0.75rem);
        inset-block-start: calc(-1 * var(--kp-tabbar-pad, 0.25rem) - 3px);
        block-size: 5px;
        border-radius: 1px 1px 3px 3px;
        background: var(--accent-foreground);
        transform-origin: 50% 0;
        scale: 1 0;
    }

    [data-theme='forest'] .kp-tabbar__tab[aria-current]:not([aria-current='false'])::before {
        scale: 1 1;
    }

    [data-theme='forest'] .kp-tabbar__tab:is(:hover, :focus-visible):not([aria-current]:not([aria-current='false']))::before {
        scale: 0.5 0.6;
        background: var(--border-strong);
    }

    [data-theme='forest'] .kp-tabbar__badge {
        border-radius: var(--kp-sig-fo-plate, var(--radius));
    }
}

/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Forest's own (themes/forest/CHARACTER.md): a tile is a kraft card with the leaf corner (G6, Kenny's pick); pointing
   is blazing, the dashed trail ring laid 2 px round the part, and a press closes the blaze in, 1 px and solid, and
   nothing moves (G12); the field-note voice is italic beside upright titles and figures (G13); a tone is a field note,
   a square tag on the status pair, its edge a short blaze (G5, G14); waiting is planting (G9): a waiting cell is the
   treeline, a count with no room for a row plants one tree in three stages; a running run is a planted row with a
   tree being planted at its growing head; the line for now is the clay trail mark. */
@layer kp.signature {
    [data-theme='forest'] .kp-actions {
        --kp-actions-gap: 0.75rem;
    }
    [data-theme='forest'] .kp-action {
        --kp-action-radius: var(--kp-sig-fo-plate);
        --kp-action-edge-hover: var(--border);
        --kp-action-ground-active: var(--card);
        --kp-action-press: 0 0;
        outline: 2px dashed transparent;
        outline-offset: 5px;
    }
    [data-theme='forest'] .kp-action__text {
        font-style: italic;
    }
    [data-theme='forest'] .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])):not(:focus-visible) {
        outline-color: var(--primary);
        outline-offset: 2px;
        box-shadow: none;
    }
    [data-theme='forest'] .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])):not(:focus-visible) {
        outline-style: solid;
        outline-color: var(--primary);
        outline-offset: 1px;
    }
    /* Destructive: the blaze on its start edge is a short painted mark in the red, the title in the red's ink. */
    [data-theme='forest'] .kp-action--destructive {
        --kp-action-tone-edge: var(--border);
        --kp-action-tone-edge-hover: var(--border);
        --kp-action-bar: 5px;
    }
    [data-theme='forest'] .kp-action--destructive::after {
        inset-block: 0.75rem auto;
        block-size: 1.1rem;
        border-radius: 0 1px 1px 0;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-action {
            transition:
                outline-color var(--fx-duration) var(--fx-ease),
                outline-offset var(--fx-duration) var(--fx-ease),
                box-shadow var(--fx-duration) var(--fx-ease);
        }
    }

    /* Status rows: kraft rows with a small part's leaf corner. A failed row's reason is a field note, a square tag on
       the red's own pair; an empty row is a dashed outline; a loading row plants its tree in the mark. */
    [data-theme='forest'] .kp-statuslist {
        --kp-statuslist-gap: 0.5rem;
    }
    [data-theme='forest'] .kp-statusrow {
        --kp-statusrow-radius: var(--kp-sig-fo-part);
    }
    [data-theme='forest'] .kp-statusrow[data-state='failed'] {
        --kp-statusrow-state-edge: var(--border-strong);
    }
    [data-theme='forest'] .kp-statusrow[data-state='failed'] .kp-statusrow__detail {
        justify-self: start;
        margin-block-start: 0.2rem;
        padding: 0 0.4em;
        border-radius: 0;
        background: var(--destructive);
        color: var(--destructive-foreground);
        font-style: italic;
    }
    [data-theme='forest'] .kp-statusrow[data-state='empty'] {
        border-style: dashed;
    }
    [data-theme='forest'] .kp-statusrow:not([data-state='failed']) .kp-statusrow__detail {
        font-style: italic;
    }

    /* Facets: rows with the small leaf corner that blaze inside the list when pointed at, on their kraft ground; the
       title is a note; counts upright. The counts on their way: each has no room for a row, so it plants one tree in
       three stages, a week's rhythm down the list. */
    [data-theme='forest'] .kp-facets {
        --kp-facet-radius: var(--kp-sig-fo-part);
    }
    [data-theme='forest'] .kp-facet {
        --kp-facet-hover: transparent;
        outline: 2px dashed transparent;
        outline-offset: -2px;
    }
    [data-theme='forest'] .kp-facet:hover:not(:focus-within) {
        outline-color: var(--primary);
    }
    [data-theme='forest'] .kp-facets__title {
        font-style: italic;
    }
    [data-theme='forest'] .kp-facets[aria-busy='true'] .kp-facet__count {
        position: relative;
        background: none;
        animation: none;
    }
    [data-theme='forest'] .kp-facets[aria-busy='true'] .kp-facet__count::after {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-end: 0;
        inline-size: 0.8em;
        background: var(--primary);
        mask: var(--kp-fo-stages) 100% 100% / 300% 100% no-repeat;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-facets[aria-busy='true'] .kp-facet__count::after {
            animation: kp-sig-forest-plant calc(var(--kp-sig-fo-loop) / 2) step-end infinite;
        }
        [data-theme='forest'] .kp-facets[aria-busy='true'] li:nth-child(2n) .kp-facet__count::after {
            animation-delay: -150ms;
        }
        [data-theme='forest'] .kp-facets[aria-busy='true'] li:nth-child(3n) .kp-facet__count::after {
            animation-delay: -300ms;
        }
        [data-theme='forest'] .kp-facet {
            transition: outline-color var(--fx-duration) var(--fx-ease);
        }
    }

    /* Heat grid and matrix: leaves on a trail, the leaf corner on every cell; pointing blazes a cell, a press closes the
       blaze in; the pick is the solid green ring and a ▾ over its night; axis and names in the note voice. Waiting, a
       cell is the treeline (the block's decided picture). */
    [data-theme='forest'] .kp-heat {
        --kp-heat-cell-radius: 0 7px;
        --kp-heat-cell-gap: 3px;
        --kp-heat-gap-y: 6px;
    }
    [data-theme='forest'] .kp-matrix {
        --kp-heat-cell-radius: 0 var(--kp-sig-fo-leaf);
        --kp-matrix-gap: 4px;
    }
    [data-theme='forest'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-hover: none;
        --kp-matrix-cell-hover: none;
    }
    [data-theme='forest'] :is(.kp-heat__cell, .kp-matrix__cell):not([data-kp-picked], [aria-pressed='true']) {
        outline: 2px dashed transparent;
        outline-offset: 4px;
    }
    [data-theme='forest'] .kp-heat__cell:hover:not(.kp-skeleton, [aria-disabled='true'], [data-kp-picked], :focus-visible),
    [data-theme='forest'] .kp-matrix__cell:hover:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton, [aria-pressed='true'], :focus-visible) {
        outline-color: var(--primary);
        outline-offset: 2px;
        z-index: 1;
    }
    [data-theme='forest'] .kp-heat__cell:active:not(.kp-skeleton, [aria-disabled='true'], :focus-visible),
    [data-theme='forest'] .kp-matrix__cell:active:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton, :focus-visible) {
        outline-style: solid;
        outline-offset: 1px;
    }
    [data-theme='forest'] .kp-heat__cell[data-kp-picked],
    [data-theme='forest'] .kp-matrix__cell[aria-pressed='true'] {
        outline: 2px solid var(--primary);
        outline-offset: 2px;
    }
    [data-theme='forest'] .kp-heat__col[data-kp-picked]::before {
        content: '▾';
        margin-inline-end: 1px;
        color: var(--primary);
    }
    [data-theme='forest'] :is(.kp-heat__col, .kp-matrix__corner, .kp-heat__legend) {
        font-style: italic;
    }
    [data-theme='forest'] :is(.kp-heat__label-button, .kp-matrix__name) {
        border-radius: var(--kp-sig-fo-part);
    }
    [data-theme='forest'] .kp-heat__label-button[aria-pressed='true'] {
        background: color-mix(in oklab, var(--primary) 16%, var(--card));
        color: var(--foreground);
        box-shadow: inset 3px 0 0 var(--primary);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] :is(.kp-heat__cell, .kp-matrix__cell) {
            transition:
                outline-color var(--fx-duration) var(--fx-ease),
                outline-offset var(--fx-duration) var(--fx-ease);
        }
    }
    [data-theme='forest'] .kp-bar-cell {
        --kp-bar-cell-gap: var(--kp-space-sm, 0.5rem);
        font-variant-numeric: tabular-nums;
    }

    /* Week agenda and run timeline: leaves, the small leaf corner on every pill and bar; pointing blazes them; the next
       run has the solid green ring; lane names and the axis in the note voice; the line for now is the clay trail mark
       with its pin. A running run is a planted row: whole trees along it and, at its growing head, a tree being
       planted, seedling to sapling to tree; no marching stripes. */
    [data-theme='forest'] .kp-week {
        --kp-week-pill-radius: var(--kp-sig-fo-part);
        --kp-week-now: var(--accent-foreground);
    }
    [data-theme='forest'] .kp-gantt {
        --kp-gantt-state-ground: var(--card);
        --kp-gantt-bar-radius: 0 0.45rem;
        --kp-gantt-now: var(--accent-foreground);
    }
    [data-theme='forest'] .kp-week__pill {
        padding-inline: 0.625rem;
    }
    [data-theme='forest'] .kp-gantt__label {
        padding-inline: 0.625rem;
    }
    [data-theme='forest'] :is(.kp-week__pill, .kp-gantt__run):is(button) {
        outline: 2px dashed transparent;
        outline-offset: 4px;
    }
    [data-theme='forest'] :is(.kp-week__pill, .kp-gantt__run):is(button):hover:not(:focus-visible) {
        outline-color: var(--primary);
        outline-offset: 2px;
        box-shadow: none;
    }
    [data-theme='forest'] .kp-week__pill[data-kp-state='next'] {
        box-shadow: 0 0 0 2px var(--primary);
    }
    [data-theme='forest'] :is(.kp-gantt__lane, .kp-gantt__tick, .kp-week__axis) {
        font-style: italic;
    }
    [data-theme='forest'] :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='running'] {
        --kp-gantt-ink: var(--foreground);
        border-color: var(--primary);
        background: linear-gradient(to top, var(--primary) 0 1.5px, transparent 1.5px), var(--muted);
        box-shadow: none;
    }
    [data-theme='forest'] .kp-gantt__run[data-kp-state='running']::before,
    [data-theme='forest'] .kp-gantt__run[data-kp-state='running']::after {
        content: '';
        position: absolute;
        inset-block: 1px 0;
        background: var(--primary);
        pointer-events: none;
    }
    [data-theme='forest'] .kp-gantt__run[data-kp-state='running']::before {
        inset-inline: 0 calc(var(--kp-gantt-bar, 1.125rem) / 2);
        mask: var(--kp-fo-trees) 0 0 / calc(var(--kp-gantt-bar, 1.125rem) / 2 * 7) 100% repeat-x;
    }
    [data-theme='forest'] .kp-gantt__run[data-kp-state='running']::after {
        inset-inline: auto 0;
        inline-size: calc(var(--kp-gantt-bar, 1.125rem) / 2);
        mask: var(--kp-fo-stages) 100% 100% / 300% 100% no-repeat;
    }
    [data-theme='forest'] .kp-gantt__run[data-kp-state='running'] .kp-gantt__label {
        display: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-gantt__run[data-kp-state='running'] {
            animation: none;
        }
        [data-theme='forest'] .kp-gantt__run[data-kp-state='running']::after {
            animation: kp-sig-forest-plant calc(var(--kp-sig-fo-loop) / 2) step-end infinite;
        }
        [data-theme='forest'] :is(.kp-week__pill, .kp-gantt__run):is(button) {
            transition:
                outline-color var(--fx-duration) var(--fx-ease),
                outline-offset var(--fx-duration) var(--fx-ease);
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='forest'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='forest'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='forest'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='forest'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='forest'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='forest'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Forest's own (themes/forest/CHARACTER.md): the separator is a twig, a green hairline with one leaf at
   its head; lying down across the phone's list the leaf sits on its start. A day on the axis is a leaf: the small leaf
   corner on its ground, pointing blazes it in the moss wash, pressed it is the green leaf with the trail's foot under it.
   A series' finished run grows from the ground in its own colour; the facet pattern is a leaf of its hue. */
@layer kp.signature {
    [data-theme='forest'] .kp-nav__sep {
        position: relative;
        border-inline-start-color: hsl(from var(--primary) h s l / 0.55);
    }
    [data-theme='forest'] .kp-nav__sep::after {
        content: '';
        position: absolute;
        inset-block-start: 1px;
        inset-inline-start: 0;
        inline-size: 6px;
        block-size: 6px;
        border-radius: 0 100%;
        background: var(--primary);
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='forest'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            border-block-start-color: hsl(from var(--primary) h s l / 0.55);
        }
        [data-theme='forest'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep::after {
            inset-block-start: -6px;
            inset-inline-start: 0;
        }
    }

    [data-theme='forest'] .kp-gantt__tick:is(button) {
        border-radius: 0 0.45rem;
        text-decoration: none;
    }
    [data-theme='forest'] .kp-gantt__tick:is(button):hover {
        background: var(--muted);
        color: var(--foreground);
    }
    [data-theme='forest'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: color-mix(in oklab, var(--primary) 16%, var(--card));
        color: var(--primary);
        box-shadow: inset 0 -2px 0 var(--primary);
    }
    [data-theme='forest'] .kp-gantt__run[data-kp-state='ok'][data-kp-series] {
        box-shadow: inset 0 -2px 0 var(--kp-gantt-series);
    }
    [data-theme='forest'] .kp-gantt__run[data-kp-state='ok'][data-kp-series]:hover {
        box-shadow:
            inset 0 -2px 0 var(--kp-gantt-series),
            0 0 0 1px var(--primary);
    }
    [data-theme='forest'] .kp-week__next:not(:has(+ .kp-week__next:not([data-kp-day-start]))) {
        border-block-end-color: hsl(from var(--primary) h s l / 0.3);
    }
    [data-theme='forest'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 0 40%;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-gantt__tick:is(button) {
            transition:
                background-color var(--fx-duration) var(--fx-ease),
                color var(--fx-duration) var(--fx-ease);
        }
    }
}

/* ── The fourth adoption round in this theme [kpadopt4]: data pieces ──
   Forest's own (themes/forest/CHARACTER.md): the ground is a map on kraft paper, what stands on it is the wood the map
   describes. A mark or a tag is light wood with its grain, routed in (G7); a plate is kraft with the leaf corner (G6);
   pointing is blazing, a dashed green ring laid 2 px round the part, a press closes it in solid, nothing moves (G12);
   what the trail marks is clay, never green (G5, G14); the field-note voice is italic beside upright titles and figures
   (G13); a live change lays a growth ring round it (G8); a trig point is a mark on a scale (G14). Every motion on the
   growth curve and under no-preference (G1, G15). */
@layer kp.signature {
    /* Identity mark: a wooden tag with the leaf corner, its grain and its routed edge in the name's own colour; a round
       one is a tree ring (a ring inside a ring); the current one in a list is ringed in solid green (the pick); the
       glyph is a clay trig mark. */
    [data-theme='forest'] .kp-idmark:not(.kp-idmark--round) {
        --kp-idmark-radius: 0 min(var(--kp-sig-fo-leaf), calc(var(--kp-idmark-s) * 0.36));
    }
    [data-theme='forest'] .kp-idmark:not(.kp-skeleton, [data-kp-idmark-empty], .kp-idmark--pattern) {
        background-image: var(--kp-sig-fo-wood);
        font-style: italic;
    }
    [data-theme='forest'] .kp-idmark--round:not(.kp-skeleton, [data-kp-idmark-empty]) {
        box-shadow:
            inset 0 0 0 2px var(--card),
            inset 0 0 0 3px hsl(from var(--kp-idmark-c) h s l / 0.7);
    }
    [data-theme='forest'] .kp-idmark--glyph::after {
        border-radius: 0;
        background: var(--accent-foreground);
    }
    [data-theme='forest'] .kp-idmark[aria-current]:not([aria-current='false']),
    [data-theme='forest'] .kp-idmark[data-kp-idmark-selected] {
        outline: 2px solid var(--primary);
        outline-offset: 2px;
        box-shadow: none;
    }
    [data-theme='forest'] .kp-idmark-group > :is(.kp-idmark, .kp-idmark-group__more) {
        box-shadow: 0 0 0 2px var(--card);
    }
    [data-theme='forest'] .kp-idmark-group__more {
        border-radius: 0 min(var(--kp-sig-fo-leaf), calc(var(--kp-idmark-s) * 0.36));
        font-style: italic;
    }

    /* Share bar: a wooden gauge, routed into the page; each part is the same wood stained in its own colour; the
       threshold is a trig point on the scale; a part pointed at is blazed with the dashed green ring and its legend row
       blazed inside; the labels are notes. */
    [data-theme='forest'] .kp-stackbar {
        --kp-stackbar-radius: 3px;
    }
    [data-theme='forest'] .kp-stackbar:not([aria-busy='true']) .kp-stackbar__bar {
        background: var(--kp-sig-fo-wood), var(--muted);
        box-shadow: var(--kp-sig-fo-routed);
    }
    [data-theme='forest'] .kp-stackbar__seg {
        background-image: var(--kp-sig-fo-wood);
        background-color: var(--kp-stackbar-colour, var(--chart-1));
    }
    [data-theme='forest'] .kp-stackbar__seg[data-kp-stackbar-hatch] {
        background-image: repeating-linear-gradient(-45deg, transparent 0 3px, var(--card) 3px 4.5px);
    }
    [data-theme='forest'] .kp-stackbar__seg[data-kp-stackbar-lit] {
        outline: 2px dashed var(--primary);
        outline-offset: 2px;
        box-shadow: inset calc(var(--kp-stackbar-gap, 2px) * -1) 0 0 var(--card);
    }
    [data-theme='forest'] .kp-stackbar__mark {
        inline-size: 2px;
        background: var(--accent-foreground);
        box-shadow: none;
    }
    [data-theme='forest'] .kp-stackbar__mark::before {
        content: '';
        position: absolute;
        inset-block-start: -0.4rem;
        inset-inline-start: 50%;
        inline-size: 0.7rem;
        block-size: 0.5rem;
        translate: -50% 0;
        background: var(--accent-foreground);
        clip-path: polygon(50% 100%, 0 0, 100% 0);
    }
    [data-theme='forest'] .kp-stackbar__item[data-kp-stackbar-lit] {
        background: transparent;
        outline: 2px dashed var(--primary);
        outline-offset: -2px;
    }
    [data-theme='forest'] .kp-stackbar__swatch {
        border-radius: 0 3px;
        background-image: var(--kp-sig-fo-wood);
        background-color: var(--kp-stackbar-colour, var(--chart-1));
    }
    [data-theme='forest'] .kp-stackbar__swatch[data-kp-stackbar-hatch] {
        background-image: repeating-linear-gradient(-45deg, transparent 0 3px, var(--card) 3px 4.5px);
    }
    [data-theme='forest'] .kp-stackbar__item[data-kp-stackbar-rest] .kp-stackbar__swatch {
        background-image: none;
    }
    [data-theme='forest'] .kp-stackbar__label {
        font-style: italic;
    }
    [data-theme='forest'] .kp-stackbar__note {
        border-radius: var(--kp-sig-fo-plate);
    }

    /* Bullet rows: the row that leads somewhere is blazed inside when pointed at (no wash, no underline); the detail is
       a note; a figure that says a tone is a field note, a square tag on the status pair. */
    [data-theme='forest'] .kp-bullets__row {
        border-radius: var(--kp-sig-fo-part);
        outline: 2px dashed transparent;
        outline-offset: -2px;
    }
    [data-theme='forest'] .kp-bullets__row:has(.kp-bullets__link:hover) {
        background: transparent;
        outline-color: var(--primary);
    }
    [data-theme='forest'] .kp-bullets__row:has(.kp-bullets__link:hover) .kp-bullets__label {
        text-decoration: none;
    }
    [data-theme='forest'] .kp-bullets__row:has(.kp-bullets__link:active) {
        outline-style: solid;
    }
    [data-theme='forest'] .kp-bullets__detail {
        font-style: italic;
    }
    [data-theme='forest'] .kp-bullets__row:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-bullets__figure {
        border-radius: 0;
        font-style: italic;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] .kp-bullets__row {
            transition: outline-color var(--fx-duration) var(--fx-ease);
        }
    }

    /* Key-value grid and form rows: the labels are notes beside upright values; a ruled line is a trail of dashes in
       clay; a row changed and not saved or one that could not be read carries a short painted blaze on its start edge
       (clay for the first, the red for the second), never a full bar. */
    [data-theme='forest'] :is(.kp-kv__row > dt, .kp-formrow__label, .kp-formrow__aside) {
        font-style: italic;
    }
    [data-theme='forest'] .kp-formrow__label {
        font-weight: 600;
    }
    [data-theme='forest'] :is(.kp-kv--lines > .kp-kv__row, .kp-formrows--lines > .kp-formrow) {
        border-block-end: 1px dashed hsl(from var(--accent-foreground) h s l / 0.5);
    }
    [data-theme='forest'] :is(.kp-kv--lines > .kp-kv__row:last-child, .kp-formrows--lines > .kp-formrow:last-child) {
        border-block-end: 0;
    }
    [data-theme='forest'] .kp-kv__row[data-kp-state='error']::before,
    [data-theme='forest'] .kp-formrow[data-kp-changed]::before,
    [data-theme='forest'] .kp-formrow[data-kp-state='error']::before {
        inset-block: 0.3em auto;
        inset-inline-start: calc(var(--kp-space-sm, 0.5rem) * -1 - 1px);
        inline-size: 4px;
        block-size: 1.15em;
        border-radius: 0 2px 2px 0;
        background: var(--accent-foreground);
    }
    [data-theme='forest'] .kp-kv__row[data-kp-state='error']::before,
    [data-theme='forest'] .kp-formrow[data-kp-state='error']::before {
        background: var(--destructive);
    }
    [data-theme='forest'] .kp-kv__row[data-kp-changed] > dt::after {
        color: var(--accent-foreground);
    }
    [data-theme='forest'] .kp-formrow__lock {
        font-style: italic;
    }

    /* Code block: a kraft plate with the leaf corner; the head is cut from the body by a trail of dashes; the line
       numbers and the foot are notes; the text itself stays plain (no texture under running text). */
    [data-theme='forest'] .kp-code {
        border-radius: var(--kp-sig-fo-plate);
    }
    [data-theme='forest'] .kp-code__head {
        border-block-end: 1px dashed hsl(from var(--accent-foreground) h s l / 0.55);
        border-start-end-radius: inherit;
    }
    [data-theme='forest'] .kp-code__foot {
        border-block-start: 1px dashed hsl(from var(--accent-foreground) h s l / 0.55);
        font-style: italic;
    }
    [data-theme='forest'] .kp-code__meta {
        font-style: italic;
    }
    [data-theme='forest'] .kp-code__body,
    [data-theme='forest'] .kp-code__note {
        border-end-start-radius: inherit;
    }
    [data-theme='forest'] .kp-code[data-kp-code-lines] .kp-code__line::before {
        font-style: italic;
    }

    /* A live number as it counts [kpadopt4, tick; Kenny, 2026-10-17: "geen fan van de cirkel rond de waarde, zoek een meer
       forest optie", then the trees, the tag and the trail round it not approved; he picked the branded digits]. The
       change is in the digits: nothing is drawn round, behind, under or after the figure. The element, its box and its
       text are untouched (no pseudo-element, no padding, no transform); the digits are branded for as long as the count
       runs (--kp-tick): stamped hot in clay with a char edge that is burned out of the wood, then cooled into the ink
       (the edge lies outside the glyph, the counters stay open). The paint is the plain ink again on the frame the count
       lands, so nothing has to be put back. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='forest'] [data-kp-tick][data-kp-tick-state='running'] {
            --kp-fo-tick-time: calc(var(--kp-tick, 600) * 1ms);
            animation:
                kp-fo-tick-stamp var(--kp-fo-tick-time) linear both,
                kp-fo-tick-cool var(--kp-fo-tick-time) linear both;
            background: none;
            -webkit-text-fill-color: color-mix(in oklab, var(--chart-2) calc(var(--kp-fo-ember) * 100%), currentColor);
            -webkit-text-stroke: calc(var(--kp-fo-grown) * 0.08em) color-mix(in oklab, var(--accent-foreground) 85%, transparent);
            paint-order: stroke fill;
            /* The package dims a busy element (layout.css, --kp-busy-opacity, 0.7): the digits are what changes here, so they
               keep their full ink. */
            --kp-busy-opacity: 1;
        }

        /* The brand lands hot in the first fifth and its char edge burns back into the wood as it cools. */
        @keyframes kp-fo-tick-stamp {
            0% {
                --kp-fo-grown: 0;
                animation-timing-function: cubic-bezier(0.2, 0.8, 0.2, 1);
            }
            18% {
                --kp-fo-grown: 1;
                animation-timing-function: var(--kp-sig-fo-wither);
            }
            100% {
                --kp-fo-grown: 0;
            }
        }

        /* How much of the treatment is left: all of it for the first half, then none by the time the count lands. */
        @keyframes kp-fo-tick-cool {
            0%,
            50% {
                --kp-fo-ember: 1;
            }
            100% {
                --kp-fo-ember: 0;
            }
        }
    }
}

/* ── Rows, cards and choices [kpadopt4]: tiles, status rows, the action list, secrets, dialogs ── */
