        [data-theme='forest'] .kp-gantt__point::before {
            transition: outline-offset var(--fx-duration) var(--fx-ease);
        }
    }

    /* A journey: the steps stand along one trail; a reached step is a solid green node joined by a solid rule, the
       ones to come are joined by a trail of dashes; the step it stands at is a node with a dashed ring laid round it
       (a blaze); a closed path ends in the red's cross and its dashes; the names are notes, the dates upright. */
    [data-theme='forest'] .kp-steplist--journey > .kp-steplist__item {
        border-inline-start: 0;
    }
    [data-theme='forest'] .kp-steplist--journey > .kp-steplist__item + .kp-steplist__item::before {
        background: repeating-linear-gradient(90deg, var(--border-strong) 0 5px, transparent 5px 9px);
    }
    [data-theme='forest'] .kp-steplist--journey > .kp-steplist__item:is([data-state='done'], [data-state='current'])::before {
        background: var(--kp-step-tone, var(--primary));
    }
    [data-theme='forest'] .kp-steplist--journey .kp-steplist__item[data-state='done']:not([data-kp-tone]) .kp-steplist__mark {
        border-color: var(--primary);
        background-color: var(--primary);
        color: var(--primary-foreground);
    }
    [data-theme='forest'] .kp-steplist--journey .kp-steplist__item[data-state='current'] .kp-steplist__mark {
        outline: 2px dashed var(--kp-step-tone, var(--primary));
