    @container kp-journey (max-width: 30rem) {
        [data-theme='forest'] .kp-steplist--journey > .kp-steplist__item:not(:last-child)::after {
            background: repeating-linear-gradient(180deg, var(--border-strong) 0 5px, transparent 5px 9px);
        }
        [data-theme='forest']
            .kp-steplist--journey
            > .kp-steplist__item:has(+ .kp-steplist__item:is([data-state='done'], [data-state='current']))::after {
            background: var(--kp-step-tone, var(--primary));
        }
    }

    /* The pipeline: a lane is a kraft plate with the leaf corner, its head a wooden tag in the stage's own stain; a card
       is a kraft card with the small leaf corner, blazed when pointed at, closed in solid when pressed; the open one has
       the solid green ring; a dimmed one is dashed; the share is a note. */
    [data-theme='forest'] .kp-pipeline__lane {
        border-radius: var(--kp-sig-fo-plate);
