    [data-theme='forest'] .kp-pipeline__head {
        border-radius: 3px;
        background: var(--kp-sig-fo-wood), color-mix(in oklab, var(--kp-pipeline-tone) 24%, var(--card));
        box-shadow: var(--kp-sig-fo-routed);
        border-color: transparent;
