        border-radius: var(--kp-sig-fo-plate);
    }
    [data-theme='forest'] .kp-pipeline__state[data-kp-state='error'] .kp-pipeline__words {
        padding: 0 0.5rem;
        border-inline-start: 0;
        background: var(--destructive);
        color: var(--destructive-foreground);
        font-style: italic;
