            animation-delay: calc(var(--kp-art-i, 0) * var(--kp-sig-fo-stagger));
        }
    }
    @keyframes kp-sig-forest-art-grow {
        from {
            scale: 1 0;
            opacity: 0;
            filter: sepia(1) saturate(0.6);
        }
        to {
            scale: 1 1;
            opacity: 1;
            filter: none;
        }
    }
}

/* ── The calm components and the seven new ones [kpadopt4] ── */
