    [data-theme='forest'] :is(.kp-card__state-title, .kp-card__failure .kp-alert__what) {
        font-size: var(--kp-text-lg, 1.125rem);
    }

    /* The failed title is the alert's own ink (the page's ink was dark plum on the red plate). */
    [data-theme='forest'] .kp-card__failure :is(.kp-card__state-title, .kp-alert__what) {
        color: inherit;
    }

    /* The card's Retry is the package's small button (28 px, 13 px text); a state's action is a normal-size one. */
    [data-theme='forest'] .kp-card__failure > .kp-card__retry.kp-button--sm {
        font-size: var(--kp-text-md, 1rem);
        padding-inline: 1rem;
    }
}

