    [data-theme='deco'] .kp-alert--success .kp-alert__label {
        color: var(--kp-sig-deco-emerald);
    }

    [data-theme='deco'] .kp-alert--info .kp-alert__label {
        color: var(--kp-sig-deco-champagne);
    }

    [data-theme='deco'] :is(.kp-alert--warning, .kp-alert--destructive) .kp-alert__label {
        /* The ruby four points lighter than --destructive (2026-10-13): the
           plain ruby read 4.37:1 on the lacquer, under WCAG 2.2 AA's 4.5:1 for
           a 600-weight label of this size; on a dark plate a step lighter is
           the step that reads. */
        color: hsl(from var(--destructive) h s calc(l + 4));
        text-decoration: underline 1px var(--primary);
        text-underline-offset: 0.3em;
