            :is(
                .kp-dialog,
                .kp-menu-button > .kp-menu,
                .kp-popover[popover],
                .kp-toast,
                .kp-tooltip,
                dialog.kp-drawer[open],
                .kp-tour[open],
                .kp-datepicker__panel,
                .kp-combobox__list,
