    }

    [data-theme='deco'] .kp-progressbar__track::before,
    [data-theme='deco'] .kp-progressbar__track::after {
        content: '';
        position: absolute;
        inset-block-start: calc(5.5px * var(--kp-sig-deco-s) + 0.5px);
        inline-size: calc(7px * var(--kp-sig-deco-s));
        block-size: calc(7px * var(--kp-sig-deco-s));
        box-sizing: border-box;
        border: 1px solid var(--kp-sig-deco-gold-lt);
        background: var(--kp-sig-deco-gem);
        translate: 0 -50%;
        rotate: 45deg;
    }

    [data-theme='deco'] .kp-progressbar__track::before {
        inset-inline-start: calc(-7.5px * var(--kp-sig-deco-s));
    }

    [data-theme='deco'] .kp-progressbar__track::after {
        inset-inline-end: calc(-7.5px * var(--kp-sig-deco-s));
    }

    [data-theme='deco'] .kp-progressbar__fill {
        inset: calc(4px * var(--kp-sig-deco-s)) 0 auto;
        block-size: calc(3px * var(--kp-sig-deco-s) + 1px);
        background:
            linear-gradient(hsl(from var(--kp-sig-deco-gold-hi) h s l / 0.7) 0 0) 0 50% / calc(var(--kp-value) * 100%) 1px no-repeat,
            var(--kp-sig-deco-share) 0 0 / calc(var(--kp-value) * 100%) 100% no-repeat;
        animation: none;
        transition: clip-path 320ms var(--kp-sig-deco-settle);
    }

    [data-theme='deco'] .kp-progressbar__head {
        inline-size: 0;
        transition: transform 320ms var(--kp-sig-deco-settle);
    }

    [data-theme='deco'] .kp-progressbar__head::before {
        content: '';
        position: absolute;
        inset-block-start: calc(5.5px * var(--kp-sig-deco-s) + 0.5px);
        inset-inline-start: 0;
        inline-size: calc(10px * var(--kp-sig-deco-s));
        block-size: calc(10px * var(--kp-sig-deco-s));
        background: var(--kp-sig-deco-gem);
        box-shadow: 0 0 0 1px var(--kp-sig-deco-lac);
        translate: -50% -50%;
        rotate: 45deg;
        filter: drop-shadow(0 0 calc(2px * var(--kp-sig-deco-s)) hsl(from var(--primary) h s l / 0.6));
    }

    [data-theme='deco'] .kp-progressbar__head::after {
        content: '';
        position: absolute;
        inset-block-start: calc(5.5px * var(--kp-sig-deco-s) + 0.5px);
        inset-inline-start: 0;
        inline-size: calc(24px * var(--kp-sig-deco-s));
        block-size: calc(24px * var(--kp-sig-deco-s));
        background: repeating-conic-gradient(from 209.4deg, var(--kp-sig-deco-gold-lt) 0 1.2deg, transparent 1.2deg 15deg);
        mask:
            conic-gradient(from 209deg, var(--foreground) 0 122deg, transparent 0),
            radial-gradient(
                circle closest-side,
                transparent 30%,
                var(--foreground) 36%,
                hsl(from var(--foreground) h s l / 0.35) 80%,
                transparent 100%
            );
        mask-composite: intersect;
        translate: -50% -50%;
    }

    /* Busy: the share's place is a glint with an afterglow between the two
       lines; the package's sweeping band and its head go. */
    [data-theme='deco'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inset: calc(5px * var(--kp-sig-deco-s)) 0 auto;
        inline-size: auto;
        block-size: calc(2px * var(--kp-sig-deco-s));
        clip-path: none;
        transform: none;
        background: linear-gradient(
            90deg,
            transparent calc(var(--kp-sig-deco-g) * 140% - 48%),
            hsl(from var(--primary) h s l / 0.3) calc(var(--kp-sig-deco-g) * 140% - 30%),
            hsl(from var(--kp-sig-deco-gold-lt) h s l / 0.85) calc(var(--kp-sig-deco-g) * 140% - 8%),
            hsl(from var(--foreground) h s 97%) calc(var(--kp-sig-deco-g) * 140% - 3%),
            transparent calc(var(--kp-sig-deco-g) * 140% - 1%)
