    }

    [data-theme='deco'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__head::before,
    [data-theme='deco'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__head::after {
        content: none;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__track {
            animation: kp-sig-deco-glint var(--kp-sig-deco-loop) linear infinite;
        }
