        background: var(--kp-sig-deco-lac);
        clip-path: none;
        translate: -50% -50%;
        rotate: 45deg;
    }

    /* ── Q5, Q14 to Q17 · the colour, the hover, the focus, the press. Every
       button, icon button and menu entry, wherever it stands (a header, a
       menu, a tile, a drawer, a tour), is deco's own: a gold hairline frame
       with ivory capitals, the one primary solid gold with lacquer ink.
       Pointing (Q15) warms the plate with gold leaf, a fine wash with a grain
       that fades in over 320 ms, the frame brightening to full gold and the
       label to champagne; leaving it fades out on the settle's inverse.
       The press (Q17) is a seal in wax: the plate sinks 1 px (an inner shadow
       at its top left, a highlight at its bottom right) and one fine gold
       ring ripples out from the centre and fades in 400 ms; release lets it
       rise. Focus (Q16) is a 3 px double gold ring and wins over both. Two
       registered numbers, --kp-sig-deco-hv (0 to 1) and --kp-sig-deco-pr, are
       turned by :hover and :active and moved by a transition each way. ── */
    [data-theme='deco'] :is(.kp-button, .kp-icon-button) {
        --kp-sig-deco-hv: 0;
        --kp-sig-deco-pr: 0;
        position: relative;
        isolation: isolate;
        overflow: hidden;
        cursor: pointer;
        -webkit-tap-highlight-color: transparent;
        border: 1px solid hsl(from var(--primary) h s l / calc(0.55 + 0.45 * var(--kp-sig-deco-hv)));
        background-color: hsl(from var(--kp-sig-deco-lac) h s calc(l - 3 * var(--kp-sig-deco-pr)) / var(--kp-sig-deco-pr));
        background-image: var(--kp-sig-deco-hair);
        background-repeat: no-repeat;
        background-position: var(--kp-sig-deco-hair-pos);
        background-size: var(--kp-sig-deco-hair-size);
        background-origin: border-box;
        background-clip: border-box;
        color: hsl(
            from var(--foreground) calc(h + 4 * var(--kp-sig-deco-hv)) calc(s + 14 * var(--kp-sig-deco-hv)) calc(l - 7 * var(--kp-sig-deco-hv))
        );
        translate: 0 calc(1px * var(--kp-sig-deco-pr));
        box-shadow:
            inset calc(1px * var(--kp-sig-deco-pr)) calc(1px * var(--kp-sig-deco-pr)) calc(3px * var(--kp-sig-deco-pr))
                hsl(from var(--kp-sig-deco-shadow) h s l / calc(0.95 * var(--kp-sig-deco-pr))),
            inset calc(-1px * var(--kp-sig-deco-pr)) calc(-1px * var(--kp-sig-deco-pr)) 0
                hsl(from var(--kp-sig-deco-gold-hi) h s l / calc(0.3 * var(--kp-sig-deco-pr)));
    }

    [data-theme='deco'] .kp-button--primary {
        border-color: var(--primary);
        background-color: hsl(from var(--primary) h s calc(l - 7 * var(--kp-sig-deco-pr)));
        background-image: linear-gradient(
            135deg,
            hsl(from var(--kp-sig-deco-gold-hi) h s l / calc(0.32 + 0.2 * var(--kp-sig-deco-hv))),
            transparent 46%,
            hsl(from var(--kp-sig-deco-gold-lo) h s l / 0.3)
        );
        color: var(--primary-foreground);
        box-shadow:
            inset calc(1px * var(--kp-sig-deco-pr)) calc(1px * var(--kp-sig-deco-pr)) calc(3px * var(--kp-sig-deco-pr))
                hsl(from var(--kp-sig-deco-gold-dk) h s l / calc(0.9 * var(--kp-sig-deco-pr))),
            inset calc(-1px * var(--kp-sig-deco-pr)) calc(-1px * var(--kp-sig-deco-pr)) 0
