    }

    [data-theme='deco'] .kp-button--destructive {
        --kp-sig-deco-arc: var(--destructive);
        --kp-sig-deco-leaf-x: linear-gradient(var(--destructive), var(--destructive));
        --kp-sig-deco-leaf-y: linear-gradient(var(--destructive), var(--destructive));
        border-color: hsl(from var(--destructive) h s l / calc(0.7 + 0.3 * var(--kp-sig-deco-hv)));
        color: var(--destructive);
    }

    [data-theme='deco'] .kp-button--ghost {
        border-color: transparent;
        background-image: none;
        color: hsl(
            from var(--muted-foreground) calc(h + 4 * var(--kp-sig-deco-hv)) calc(s + 14 * var(--kp-sig-deco-hv)) calc(l + 8 * var(--kp-sig-deco-hv))
        );
    }

    [data-theme='deco'] :is(.kp-button, .kp-icon-button):disabled {
        border-color: var(--border);
        background-image: none;
        color: var(--muted-foreground);
        cursor: not-allowed;
    }

    [data-theme='deco'] .kp-nav .kp-button--ghost,
    [data-theme='deco'] :is(.kp-toast, .kp-alert) :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
        background-image: none;
        border-color: transparent;
    }

    /* The gold leaf: a wash of gold at 9 % with a fine irregular grain
       (a few percent either way) behind the label. */
    [data-theme='deco'] :is(.kp-button, .kp-icon-button, .kp-menu__item)::before {
        content: '';
        position: absolute;
        inset: 0;
        z-index: -1;
        pointer-events: none;
        background: linear-gradient(
            135deg,
            hsl(from var(--kp-sig-deco-gold-hi) h s l / 0.13),
            hsl(from var(--primary) h s l / 0.07) 38%,
            hsl(from var(--kp-sig-deco-gold-lt) h s l / 0.12) 64%,
            hsl(from var(--primary) h s l / 0.06)
        );
        mask: var(--kp-sig-deco-grain) 0 0 / 64px 64px;
        opacity: var(--kp-sig-deco-hv);
    }

    [data-theme='deco'] .kp-button--primary::before {
        background: linear-gradient(
            135deg,
            hsl(from var(--kp-sig-deco-gold-hi) h s l / 0.5),
            transparent 45%,
            hsl(from var(--kp-sig-deco-gold-hi) h s l / 0.35)
        );
    }

    /* The seal's ring: one fine gold ring from the centre, outward and gone. */
    [data-theme='deco'] :is(.kp-button, .kp-icon-button, .kp-menu__item)::after {
        content: '';
        position: absolute;
        inset: 0;
        z-index: 3;
        pointer-events: none;
        background-image: radial-gradient(
            closest-side,
            transparent calc(100% - 3px),
            hsl(from var(--kp-sig-deco-gold-hi) h s l / 0.9) calc(100% - 1.6px),
            var(--primary) calc(100% - 0.6px),
            transparent
        );
        background-repeat: no-repeat;
        background-position: 50% 50%;
        background-size: calc(var(--kp-sig-deco-ring) * 170%) calc(var(--kp-sig-deco-ring) * 170%);
        opacity: 0;
    }

    [data-theme='deco'] .kp-button--primary::after {
        background-image: radial-gradient(
            closest-side,
            transparent calc(100% - 3px),
            hsl(from var(--kp-sig-deco-gold-hi) h s 92%) calc(100% - 1.6px),
            var(--kp-sig-deco-gold-lt) calc(100% - 0.6px),
            transparent
        );
    }

    /* A menu entry: no frame at rest; pointed at it draws its hairline round
       itself in gold, the label warms; the press seals it like a button. */
    [data-theme='deco'] .kp-menu__item {
        --kp-sig-deco-hv: 0;
        --kp-sig-deco-pr: 0;
        position: relative;
        isolation: isolate;
        overflow: clip;
        background: hsl(from var(--kp-sig-deco-lac) h s calc(l - 3 * var(--kp-sig-deco-pr)) / var(--kp-sig-deco-pr));
        color: hsl(
            from var(--foreground) calc(h + 4 * var(--kp-sig-deco-hv)) calc(s + 14 * var(--kp-sig-deco-hv)) calc(l - 7 * var(--kp-sig-deco-hv))
        );
