        box-shadow:
            inset 0 0 0 1px hsl(from var(--primary) h s l / calc(0.9 * var(--kp-sig-deco-hv))),
            inset calc(1px * var(--kp-sig-deco-pr)) calc(1px * var(--kp-sig-deco-pr)) calc(3px * var(--kp-sig-deco-pr))
