    }

    [data-theme='deco'] .kp-calendar__day[data-kp-today] {
        box-shadow:
            inset 0 0 0 2px currentColor,
            inset calc(1px * var(--kp-sig-deco-pr)) calc(1px * var(--kp-sig-deco-pr)) calc(3px * var(--kp-sig-deco-pr))
                hsl(from var(--kp-sig-deco-shadow) h s l / calc(0.95 * var(--kp-sig-deco-pr)));
    }

    /* The two turns of the numbers: pointed at on the settle, away on its
       inverse; pressed in 160 ms, let go the same. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco']
            :is(
                .kp-button,
                .kp-icon-button,
                .kp-menu__item,
                a.kp-kpi,
                .kp-action,
                .kp-kpi--toggle,
                .kp-kpi--trend:has(.kp-kpi__link),
                .kp-calendar__day
            ) {
            transition:
                --kp-sig-deco-hv var(--kp-sig-deco-hover-t) var(--kp-sig-deco-settle-out),
                --kp-sig-deco-pr var(--kp-sig-deco-press-t) var(--kp-sig-deco-settle-out),
                background-color var(--kp-sig-deco-contact) var(--kp-sig-deco-settle);
        }

        [data-theme='deco']
            :is(
                .kp-button,
                .kp-icon-button,
                .kp-menu__item,
                a.kp-kpi,
                .kp-action,
                .kp-kpi--toggle,
                .kp-kpi--trend:has(.kp-kpi__link),
                .kp-calendar__day
            ):hover:not(:disabled, [aria-disabled='true'], [aria-busy='true']) {
            transition:
                --kp-sig-deco-hv var(--kp-sig-deco-hover-t) var(--kp-sig-deco-settle),
                --kp-sig-deco-pr var(--kp-sig-deco-press-t) var(--kp-sig-deco-settle-out),
                background-color var(--kp-sig-deco-contact) var(--kp-sig-deco-settle);
        }

        [data-theme='deco']
            :is(
                .kp-button,
                .kp-icon-button,
                .kp-menu__item,
                a.kp-kpi,
                .kp-action,
                .kp-kpi--toggle,
                .kp-kpi--trend:has(.kp-kpi__link),
                .kp-calendar__day
            ):active:not(:disabled, [aria-disabled='true'], [aria-busy='true']) {
            transition:
                --kp-sig-deco-hv var(--kp-sig-deco-hover-t) var(--kp-sig-deco-settle),
                --kp-sig-deco-pr var(--kp-sig-deco-press-t) var(--kp-sig-deco-settle),
                background-color var(--kp-sig-deco-contact) var(--kp-sig-deco-settle);
        }

        /* The ring is played whole once it has started: a tap shorter than
           400 ms lifts the pointer (`:active` ends) and would cut it where it
           stood, so js/effects.js (--kp-press: hold, declared on the theme)
           marks the pressed part `data-kp-pressed` for the 400 ms as well. */
        [data-theme='deco']
            :is(.kp-button, .kp-icon-button, .kp-menu__item):is(:active, [data-kp-pressed]):not(
                :disabled,
                [aria-disabled='true'],
                [aria-busy='true']
            )::after,
        [data-theme='deco']
            :is(a.kp-kpi, .kp-action, .kp-kpi--toggle, .kp-kpi--trend:has(.kp-kpi__link), .kp-calendar__day:not([data-kp-tone='loading'])):is(
                :active,
                [data-kp-pressed]
            )::before {
            animation: kp-sig-deco-seal 400ms linear both;
        }
    }

    [data-theme='deco']
        :is(
            .kp-button,
            .kp-icon-button,
            .kp-menu__item,
            a.kp-kpi,
            .kp-action,
            .kp-kpi--toggle,
            .kp-kpi--trend:has(.kp-kpi__link),
            .kp-calendar__day
        ):hover:not(:disabled, [aria-disabled='true'], [aria-busy='true']) {
        --kp-sig-deco-hv: 1;
    }

    [data-theme='deco']
        :is(
            .kp-button,
            .kp-icon-button,
            .kp-menu__item,
            a.kp-kpi,
            .kp-action,
            .kp-kpi--toggle,
            .kp-kpi--trend:has(.kp-kpi__link),
            .kp-calendar__day
        ):active:not(:disabled, [aria-disabled='true'], [aria-busy='true']) {
        --kp-sig-deco-pr: 1;
    }

    @keyframes kp-sig-deco-seal {
        0% {
            opacity: 0.95;
            --kp-sig-deco-ring: 0.08;
            animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
        }

        100% {
            opacity: 0;
            --kp-sig-deco-ring: 1;
        }
    }

    /* Q16 · focus: a 3 px double gold ring round the focused control, outside
       its frame; it is written after the pointer's rules and stays through
       a press, so it wins when both apply. */
    [data-theme='deco']
        :is(
            .kp-button,
            .kp-icon-button,
            .kp-menu__item,
            a.kp-kpi,
            .kp-action,
            .kp-kpi--toggle,
            .kp-calendar__day,
            .kp-tab,
            .kp-nav__link,
            .kp-nav__toggle,
            .kp-footer a,
            a:not([class])
        ):focus-visible,
    [data-theme='deco'] .kp-kpi--trend:has(.kp-kpi__link:focus-visible) {
        outline: 3px double var(--primary);
        outline-offset: 3px;
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 1, while
       loading 3, how the share arrives 2, when the tone changes 3,
       the mark past the end 3]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='deco']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='deco']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='deco']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='deco']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='deco']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='deco']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='deco']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='deco']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* An arrow up: higher than the top floor. */
    [data-theme='deco'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        inset-block: -4px;
        inline-size: 0.4375rem;
        background: var(--primary);
        clip-path: polygon(50% 0, 100% 45%, 70% 45%, 70% 100%, 30% 100%, 30% 45%, 0 45%);
    }

    /* ── how the share arrives: option 2 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-deco-meter-wipe-o 900ms cubic-bezier(0.6, 0, 0.2, 1) backwards;
            transition: inline-size 900ms cubic-bezier(0.6, 0, 0.2, 1);
        }
    }

    /* ── when the tone changes: option 3 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] :is(.kp-meter, .kp-kpi__meter):not([data-kp-loading], [data-kp-tone]) {
            animation: kp-sig-deco-meter-knock-o 300ms ease-out;
        }

        [data-theme='deco'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']:not([data-kp-loading]) {
            animation: kp-sig-deco-meter-knock-w 300ms ease-out;
        }

        [data-theme='deco'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']:not([data-kp-loading]) {
            animation: kp-sig-deco-meter-knock-d 300ms ease-out;
        }
    }

    /* ── the mark past the end: option 3 ── */

    [data-theme='deco'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '▼';
    }

    [data-theme='deco'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
        rotate: 24deg;
        transform-origin: 50% 100%;
    }

    [data-theme='deco'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        rotate: -24deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-meter__mark {
            transition:
                inset-inline-start 500ms ease-in-out,
                rotate 500ms ease-in-out;
        }
    }

    @keyframes kp-sig-deco-meter-knock-d {
        0% {
            translate: 0 0;
        }

        30% {
            translate: 0 -3px;
        }

        60% {
            translate: 0 1px;
        }

        100% {
            translate: 0 0;
        }
    }

    @keyframes kp-sig-deco-meter-knock-o {
        0% {
            translate: 0 0;
        }

        30% {
            translate: 0 -3px;
        }

        60% {
            translate: 0 1px;
        }

        100% {
            translate: 0 0;
        }
    }

    @keyframes kp-sig-deco-meter-knock-w {
        0% {
            translate: 0 0;
        }

        30% {
            translate: 0 -3px;
        }

        60% {
            translate: 0 1px;
        }

        100% {
            translate: 0 0;
        }
    }

    @keyframes kp-sig-deco-meter-wipe-o {
        0% {
            clip-path: inset(0 100% 0 0);
        }

        100% {
            clip-path: inset(0);
        }
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — deco: lacquer and gold. The current tab draws a gold line along the top edge from the centre to both sides and sets a jewel on it; the double rule frames the bar; labels in spaced capitals (G2, G5, G7, G19); a count is a gold lozenge. */
    [data-theme='deco'] .kp-tabbar {
        border-block-start: 3px double var(--border-strong);
    }

    [data-theme='deco'] .kp-tabbar__tab {
        border-radius: 0;
        letter-spacing: 0.14em;
        text-transform: uppercase;
    }

    [data-theme='deco'] .kp-tabbar__tab::before {
        inset-inline: 0.25rem;
        block-size: 1px;
        background: linear-gradient(90deg, transparent, var(--primary) 20%, var(--primary) 80%, transparent);
    }

    [data-theme='deco'] .kp-tabbar__tab::after {
        content: '';
        position: absolute;
        inset-block-start: calc(-1 * var(--kp-tabbar-pad, 0.25rem) - 4px);
        inset-inline-start: calc(50% - 0.2rem);
        inline-size: 0.4rem;
        block-size: 0.4rem;
        background: var(--primary);
        rotate: 45deg;
        scale: 0;
    }

    [data-theme='deco'] .kp-tabbar__tab[aria-current]:not([aria-current='false'])::after {
        scale: 1;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-tabbar__tab::after {
            transition: scale var(--fx-duration) var(--fx-ease);
        }
    }

    [data-theme='deco'] .kp-tabbar__badge {
        border-radius: 0;
        clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%);
        min-inline-size: 1.5rem;
        padding-inline: 0.4rem;
        background: var(--primary);
        color: var(--primary-foreground);
    }
}
/* ── End of the signature ── */

/* ── Segmented control, list toolbar, key line [kpadopt-controls] ── */
@layer kp.signature {
    [data-theme='deco'] .kp-segmented {
        --kp-seg-radius: 0;
        --kp-seg-font: var(--theme-font-body);
        --kp-seg-tracking: 0.08em;
        --kp-seg-case: uppercase;
        --kp-seg-edge: var(--border-strong);
        --kp-seg-track: var(--card);
        --kp-seg-thumb: hsl(from var(--primary) h s l / 0.14);
        --kp-seg-thumb-ink: var(--primary);
        --kp-seg-thumb-edge: 0 0 0 1px var(--primary);
        --kp-seg-thumb-lift: inset 0 0 0 3px var(--card), inset 0 0 0 4px hsl(from var(--primary) h s l / 0.7);
        --kp-chip-radius: 0;
        --kp-chip-on: hsl(from var(--primary) h s l / 0.16);
        --kp-chip-on-ink: var(--primary);
        --kp-chip-on-edge: var(--primary);
    }
    [data-theme='deco'] .kp-toolbar {
        --kp-toolbar-group-gap: 1.125rem;
    }
    [data-theme='deco'] .kp-toolbar__label {
        font-family: var(--theme-font-body);
        letter-spacing: 0.18em;
    }
    [data-theme='deco'] .kp-keys {
        --kp-keys-gap: 1rem;
    }
    [data-theme='deco'] .kp-kbd {
        --kp-kbd-radius: 0;
        --kp-kbd-edge: var(--primary);
        --kp-kbd-ground: var(--card);
        --kp-kbd-foot: 1px;
        box-shadow:
            inset 0 0 0 2px var(--card),
            inset 0 0 0 3px hsl(from var(--primary) h s l / 0.5);
        padding-inline: 0.4rem;
    }
    [data-theme='deco'] .kp-segmented--chips > .kp-segmented__item[aria-pressed='true'] {
        box-shadow:
            inset 0 0 0 2px var(--background),
            inset 0 0 0 3px hsl(from var(--primary) h s l / 0.7);
    }
}

/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Deco's own (themes/deco/CHARACTER.md): a tile and a status row are plates of the lobby, blue lacquer with the chevron
   wallpaper, the four corners coved and the double gold inlay following the coves (G5, G6, G7; they join the plate
   rules above); a tile answers the pointer as a key figure that is a link does: gold leaf warms it and the hairline
   goes to full gold (G15), a press is the seal in wax, the ring rippling out (G17), focus the 3 px double gold ring
   (G16); a warning is the words in ruby over a gold rule (G8); waiting is the lift doors (G10) and, where there is no
   room for doors, the glint running between gold lines (G11); Poiret One capitals name (G18). */
@layer kp.signature {
    [data-theme='deco'] .kp-actions {
        --kp-actions-gap: 0.75rem;
    }
    [data-theme='deco'] .kp-action {
        --kp-action-radius: 0;
        --kp-action-pad: 0.875rem 1.125rem;
        --kp-action-title-font: var(--theme-font-display);
        --kp-action-title-case: uppercase;
        --kp-action-title-tracking: 0.08em;
        --kp-action-title-size: 0.9375rem;
        --kp-action-press: 0 0;
        --kp-action-shadow: none;
        --kp-action-shadow-hover: none;
        --kp-action-shadow-active: inset 1px 2px 4px hsl(from var(--kp-sig-deco-shadow, var(--background)) h s l / 0.8);
    }
    [data-theme='deco'] .kp-action__title {
        color: hsl(from var(--foreground) h s l);
    }
    [data-theme='deco']
        .kp-action:not(.kp-action--destructive):hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true']))
        > .kp-action__title {
        color: var(--kp-sig-deco-gold-hi);
    }
    [data-theme='deco'] .kp-action__meta {
        font-family: var(--theme-font-mono);
    }
    /* The destructive bar gives way to the plate's own inlay; the warning is the title in ruby over a gold rule. */
    [data-theme='deco'] .kp-action--destructive {
        --kp-action-tone-edge: hsl(from var(--primary) h s l / 0.3);
        --kp-action-tone-edge-hover: var(--primary);
    }
    [data-theme='deco'] .kp-action::after,
    [data-theme='deco'] .kp-action--destructive::after {
        inset: -1px;
        inline-size: auto;
        border-radius: 0;
        background-color: transparent;
    }
    [data-theme='deco'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) > .kp-action__title {
        justify-self: start;
        color: var(--destructive);
        text-decoration: underline 1px var(--primary);
        text-decoration-skip-ink: none;
        text-underline-offset: 0.35em;
    }
    [data-theme='deco'] .kp-action:is(:disabled, [aria-disabled='true']) {
        color: var(--muted-foreground);
    }
    [data-theme='deco'] .kp-action:is(:disabled, [aria-disabled='true']) > .kp-action__title {
        color: var(--muted-foreground);
    }

    /* Status rows: plates of the lobby with the inlay; square marks; a failed row's name in ruby over a gold rule. */
    [data-theme='deco'] .kp-statuslist {
        --kp-statusrow-mark-radius: 0;
        --kp-statuslist-gap: 0.625rem;
    }
    [data-theme='deco'] .kp-statusrow {
        --kp-statusrow-radius: 0;
        --kp-statusrow-pad: 0.625rem 0.875rem;
        column-gap: 0.875rem;
    }
    [data-theme='deco'] .kp-statusrow__label {
        letter-spacing: 0.04em;
    }
    [data-theme='deco'] .kp-statusrow[data-state='failed'] .kp-statusrow__label {
        justify-self: start;
        color: var(--destructive);
        text-decoration: underline 1px var(--primary);
        text-underline-offset: 0.35em;
    }
    [data-theme='deco'] .kp-statusrow[data-state='empty'] .kp-statusrow__label {
        color: var(--muted-foreground);
    }

    /* Facets: square rows warmed by gold leaf when pointed at; the title in very widely spaced capitals. The counts on
       their way are two gold hairlines with the glint running between them. */
    [data-theme='deco'] .kp-facets {
        --kp-facet-radius: 0;
    }
    [data-theme='deco'] .kp-facet {
        --kp-facet-hover: linear-gradient(
            135deg,
            hsl(from var(--kp-sig-deco-gold-hi) h s l / 0.13),
            hsl(from var(--primary) h s l / 0.07) 38%,
            hsl(from var(--kp-sig-deco-gold-lt) h s l / 0.12)
        );
    }
    [data-theme='deco'] .kp-facet:hover {
        box-shadow: inset 0 -1px 0 var(--primary);
    }
    [data-theme='deco'] .kp-facets__title {
        font-family: var(--theme-font-display);
        letter-spacing: 0.18em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-facets[aria-busy='true'] .kp-facet__count {
        border-radius: 0;
        background:
            linear-gradient(hsl(from var(--primary) h s l / 0.7), hsl(from var(--primary) h s l / 0.7)) 0 30% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.7), hsl(from var(--primary) h s l / 0.7)) 0 70% / 100% 1px no-repeat,
            linear-gradient(
                    90deg,
                    transparent calc(var(--kp-sig-deco-g, 0) * 140% - 48%),
                    hsl(from var(--primary) h s l / 0.3) calc(var(--kp-sig-deco-g, 0) * 140% - 30%),
                    hsl(from var(--kp-sig-deco-gold-lt) h s l / 0.85) calc(var(--kp-sig-deco-g, 0) * 140% - 8%),
                    hsl(from var(--foreground) h s 97%) calc(var(--kp-sig-deco-g, 0) * 140% - 3%),
                    transparent calc(var(--kp-sig-deco-g, 0) * 140% - 1%)
                )
                0 50% / 100% 2px no-repeat;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-facets[aria-busy='true'] .kp-facet__count {
            animation: kp-sig-deco-glint var(--kp-sig-deco-loop) linear infinite;
        }
        [data-theme='deco'] .kp-facets[aria-busy='true'] li:nth-child(2n) .kp-facet__count {
            animation-delay: calc(var(--kp-sig-deco-loop) / -12);
        }
    }

    /* Heat grid and matrix: inlaid tiles, a thin gold inlay inside each frame; pointing warms a tile with gold leaf
       and its inlay goes to full gold; a press sinks it under an inner shadow; the pick is the double gold ring;
       names and the axis in spaced capitals. */
    [data-theme='deco'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-radius: 0;
        --kp-heat-cell-ink: hsl(from var(--primary) h s l / 0.55);
        --kp-heat-cell-lift: inset 0 0 0 1px hsl(from var(--background) h s l / 0.5);
        --kp-heat-cell-hover: none;
        --kp-matrix-cell-hover: none;
    }
    [data-theme='deco'] .kp-heat {
        --kp-heat-gap-y: 6px;
    }
    [data-theme='deco'] .kp-matrix {
        --kp-matrix-gap: 4px;
    }
    [data-theme='deco'] .kp-heat__cell:hover:not(.kp-skeleton, [aria-disabled='true']),
    [data-theme='deco'] .kp-matrix__cell:hover:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
        border-color: var(--kp-sig-deco-gold-hi);
        box-shadow:
            inset 0 0 0 1px hsl(from var(--background) h s l / 0.5),
            0 0 0 1px var(--primary);
    }
    [data-theme='deco'] .kp-heat__cell:active:not(.kp-skeleton, [aria-disabled='true']),
    [data-theme='deco'] .kp-matrix__cell:active:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
        box-shadow: inset 1px 2px 4px hsl(from var(--background) h s l / 0.9);
    }
    [data-theme='deco'] .kp-heat__cell[data-kp-picked],
    [data-theme='deco'] .kp-matrix__cell[aria-pressed='true'] {
        outline: 3px double var(--primary);
        outline-offset: 2px;
    }
    [data-theme='deco'] :is(.kp-heat__label, .kp-matrix__name, .kp-heat__col, .kp-matrix__corner) {
        text-transform: uppercase;
        letter-spacing: 0.1em;
        font-size: var(--kp-text-xs, 0.75rem);
    }
    [data-theme='deco'] .kp-matrix__corner {
        letter-spacing: 0.04em;
        text-wrap: balance;
    }
    [data-theme='deco'] :is(.kp-heat__label-button, .kp-matrix__name) {
        border-radius: 0;
    }
    [data-theme='deco'] .kp-heat__label-button[aria-pressed='true'] {
        background: hsl(from var(--primary) h s l / 0.14);
        color: var(--kp-sig-deco-gold-hi);
        box-shadow: inset 0 -1px 0 var(--primary);
    }
    [data-theme='deco'] .kp-heat__sep {
        border-block-start: 3px double var(--primary);
    }
    /* A phone's timeline keeps its toolbar on one row: the range steps close in, in these spaced capitals. */
    @container kp-gantt (max-width: 22rem) {
        [data-theme='deco'] .kp-gantt__ranges {
            --kp-seg-item-pad-inline: 0.5rem;
        }
    }
    [data-theme='deco'] .kp-bar-cell {
        --kp-bar-cell-gap: var(--kp-space-sm, 0.5rem);
        font-variant-numeric: tabular-nums;
    }

    /* Week agenda and run timeline: an inlay. A pill is a double rule in the series' ink; the next run the double gold
       ring; the days and the axis in spaced capitals; the line for now is gold with a lozenge at its head. A running
       run is drawn between two gold hairlines with the glint and its afterglow running between them. */
    [data-theme='deco'] .kp-week {
        --kp-week-pill-radius: 0;
        --kp-week-now: var(--primary);
    }
    [data-theme='deco'] .kp-gantt {
        --kp-gantt-bar-radius: 0;
        --kp-gantt-now: var(--primary);
        --kp-gantt-state-ground: var(--kp-sig-deco-lac, var(--card));
    }
    [data-theme='deco'] .kp-week__pill:not([data-kp-state='reference']) {
        border-style: double;
        border-width: 3px;
        padding-inline: 0.3rem;
    }
    [data-theme='deco'] .kp-week__pill:is(button):hover,
    [data-theme='deco'] .kp-gantt__run:is(button):hover {
        border-color: var(--kp-sig-deco-gold-hi);
        box-shadow: 0 0 0 1px var(--primary);
    }
    [data-theme='deco'] .kp-week__pill[data-kp-state='next'] {
        outline: 3px double var(--primary);
        outline-offset: 2px;
        box-shadow: none;
    }
    [data-theme='deco'] .kp-week__now::before {
        border-radius: 0;
        rotate: 45deg;
        inline-size: 7px;
        block-size: 7px;
        inset-block-start: -4.5px;
        inset-inline-start: -3.5px;
    }
    [data-theme='deco'] .kp-gantt__run:not([data-kp-state='queued']) {
        border-inline-style: double;
        border-inline-width: 3px;
    }
    [data-theme='deco'] :is(.kp-week__head, .kp-gantt__tick, .kp-gantt__lane) {
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='deco'] :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='running'] {
        border-color: var(--primary);
        color: var(--foreground);
        background:
            linear-gradient(var(--primary), var(--primary)) 0 3px / 100% 1px no-repeat,
            linear-gradient(var(--primary), var(--primary)) 0 calc(100% - 3px) / 100% 1px no-repeat,
            linear-gradient(
                    90deg,
                    transparent calc(var(--kp-sig-deco-g, 1) * 140% - 48%),
                    hsl(from var(--primary) h s l / 0.35) calc(var(--kp-sig-deco-g, 1) * 140% - 30%),
                    hsl(from var(--kp-sig-deco-gold-lt) h s l / 0.85) calc(var(--kp-sig-deco-g, 1) * 140% - 8%),
                    hsl(from var(--foreground) h s 97%) calc(var(--kp-sig-deco-g, 1) * 140% - 3%),
                    transparent calc(var(--kp-sig-deco-g, 1) * 140% - 1%)
                )
                0 50% / 100% 40% no-repeat,
            var(--kp-sig-deco-lac, var(--card));
        box-shadow: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-gantt__run[data-kp-state='running'] {
            animation: kp-sig-deco-glint var(--kp-sig-deco-loop) linear infinite;
        }
        [data-theme='deco'] :is(.kp-heat__cell, .kp-matrix__cell, .kp-week__pill, .kp-gantt__run) {
            transition:
                border-color var(--kp-sig-deco-contact, 160ms) var(--fx-ease),
                box-shadow var(--kp-sig-deco-contact, 160ms) var(--fx-ease);
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='deco'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='deco'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='deco'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='deco'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='deco'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='deco'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Deco's own (themes/deco/CHARACTER.md): the separator is a gold hairline with the lozenge at its middle, the
   inlay's own mark; lying down across the phone's list the lozenge sits on the gold line. A day on the axis is ruled
   in gold under the pointer; pressed it stands on the lacquer over the inlay's double gold rule, the date in the high
   gold. A series' finished run is a double rule in its ink, as a week pill is; the upcoming list's day rule is a gold
   hairline; the facet pattern is set in a gilt frame. */
@layer kp.signature {
    [data-theme='deco'] .kp-nav__sep {
        position: relative;
        border-inline-start-color: hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='deco'] .kp-nav__sep::after {
        content: '';
        position: absolute;
        inset-block-start: calc(50% - 2.5px);
        inset-inline-start: -3px;
        inline-size: 5px;
        block-size: 5px;
        background: var(--primary);
        rotate: 45deg;
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='deco'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            border-block-start-color: hsl(from var(--primary) h s l / 0.6);
        }
        [data-theme='deco'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep::after {
            inset-block-start: -3px;
            inset-inline-start: calc(50% - 2.5px);
        }
    }

    [data-theme='deco'] .kp-gantt__tick:is(button) {
        border-radius: 0;
        text-decoration: none;
    }
    [data-theme='deco'] .kp-gantt__tick:is(button):hover {
        color: var(--kp-sig-deco-gold-hi, var(--primary));
        box-shadow: inset 0 -1px 0 var(--primary);
    }
    [data-theme='deco'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: var(--kp-sig-deco-lac, var(--card));
        color: var(--kp-sig-deco-gold-hi, var(--primary));
        box-shadow:
            inset 0 -1px 0 var(--primary),
            inset 0 -3px 0 var(--kp-sig-deco-lac, var(--card)),
            inset 0 -4px 0 var(--primary);
    }
    [data-theme='deco'] .kp-gantt__run[data-kp-state='ok'][data-kp-series] {
        box-shadow:
            inset 0 0 0 1px var(--kp-gantt-series),
            inset 0 0 0 2px var(--kp-sig-deco-lac, var(--card));
    }
    [data-theme='deco'] .kp-week__next:not(:has(+ .kp-week__next:not([data-kp-day-start]))) {
        border-block-end-color: hsl(from var(--primary) h s l / 0.4);
    }
    [data-theme='deco'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 0;
        outline: 1px solid hsl(from var(--primary) h s l / 0.75);
        outline-offset: 1px;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-gantt__tick:is(button) {
            transition:
                box-shadow var(--kp-sig-deco-contact, 160ms) var(--fx-ease),
                color var(--kp-sig-deco-contact, 160ms) var(--fx-ease);
        }
    }
}

/* ── The kpadopt4 data pieces, in this theme [kpadopt4] ──
   Deco's own (themes/deco/CHARACTER.md): the lobby after the lights go down. A small part is a plate in little, blue
   lacquer inside a double gold hairline; gold is a line and a jewel, never a fill (G5); emerald marks what is on or
   done and ruby only warns, as the figure over a gold rule (G8); pointing warms with gold leaf, the hairline goes to
   full gold and the label to champagne (G15); a mark is a lozenge, the jewel (G19); Poiret One capitals name, Josefin
   speaks and counts (G18). Everything settles on the lobby's curve (G1). */
@layer kp.signature {
    /* The identity mark: lacquer with a wash of its own colour, inside a double gold inlay; round it is a jewel, the
       double ring. The pick is the double gold ring. */
    [data-theme='deco'] .kp-idmark {
        --kp-idmark-radius: 0;
        --kp-idmark-tint: 30%;
        border: 1px solid hsl(from var(--primary) h s l / 0.75);
        background: color-mix(in oklab, var(--kp-idmark-c) var(--kp-idmark-tint), var(--kp-sig-deco-lac));
        box-shadow:
            inset 0 0 0 2px var(--kp-sig-deco-lac),
            inset 0 0 0 3px hsl(from var(--primary) h s l / 0.45);
        color: var(--kp-sig-deco-champagne);
        font-family: var(--theme-font-body);
        font-weight: 600;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        clip-path: polygon(3px 0, calc(100% - 3px) 0, 100% 3px, 100% calc(100% - 3px), calc(100% - 3px) 100%, 3px 100%, 0 calc(100% - 3px), 0 3px);
    }
    [data-theme='deco'] .kp-idmark--xs {
        box-shadow: inset 0 0 0 1px var(--kp-sig-deco-lac);
    }
    [data-theme='deco'] .kp-idmark--round {
        border-radius: 50%;
        clip-path: none;
    }
    [data-theme='deco'] .kp-idmark--pattern {
        background: color-mix(in oklab, var(--kp-idmark-c) 78%, var(--kp-sig-deco-lac));
        --kp-idmark-ink: var(--kp-sig-deco-lac);
    }
    [data-theme='deco'] .kp-idmark--glyph {
        clip-path: none;
    }
    [data-theme='deco'] .kp-idmark--glyph::after {
        z-index: 1;
        background: var(--kp-sig-deco-gold-lt);
        box-shadow: 0 0 0 1.5px var(--kp-sig-deco-lac);
        rotate: 45deg;
        scale: 0.8;
    }
    [data-theme='deco'] .kp-idmark--glyph[data-kp-idmark-glyph='circle']::after {
        rotate: none;
        scale: 0.8;
    }
    [data-theme='deco'] .kp-idmark--glyph[data-kp-idmark-glyph='triangle']::after {
        rotate: none;
        scale: 1;
        box-shadow: none;
    }
    [data-theme='deco'] .kp-idmark[data-kp-idmark-empty] {
        border-style: dashed;
        background: var(--kp-sig-deco-lac);
        box-shadow: none;
        color: var(--muted-foreground);
    }
    [data-theme='deco'] .kp-idmark[aria-current]:not([aria-current='false']),
    [data-theme='deco'] .kp-idmark[data-kp-idmark-selected] {
        clip-path: none;
        outline: 3px double var(--primary);
        outline-offset: 2px;
        box-shadow:
            inset 0 0 0 2px var(--kp-sig-deco-lac),
            inset 0 0 0 3px hsl(from var(--primary) h s l / 0.45);
    }
    [data-theme='deco'] .kp-idmark-group > .kp-idmark,
    [data-theme='deco'] .kp-idmark-group > .kp-idmark-group__more {
        clip-path: none;
        box-shadow:
            inset 0 0 0 2px var(--kp-sig-deco-lac),
            inset 0 0 0 3px hsl(from var(--primary) h s l / 0.45),
            0 0 0 2px var(--kp-sig-deco-lac);
    }
    [data-theme='deco'] .kp-idmark-group__more {
        --kp-idmark-radius: 0;
        border: 1px solid hsl(from var(--primary) h s l / 0.75);
        border-radius: 0;
        background: var(--kp-sig-deco-lac);
        color: var(--kp-sig-deco-champagne);
        font-family: var(--theme-font-body);
        font-weight: 600;
    }

    /* The share bar: the inlay doubled, two gold hairlines 3 px apart round the track, the parts flat between them set
       apart by the lacquer, the threshold a gold lozenge on its hairline, the swatches lozenges (the jewel). */
    [data-theme='deco'] .kp-stackbar {
        --kp-stackbar-radius: 0;
        --kp-stackbar-gap: 2px;
    }
    [data-theme='deco'] .kp-stackbar__title {
        font-family: var(--theme-font-display);
        font-size: 0.9375rem;
        letter-spacing: 0.16em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-stackbar__total {
        font-family: var(--theme-font-body);
        font-weight: 600;
    }
    [data-theme='deco'] .kp-stackbar__bar {
        background: var(--kp-sig-deco-shadow);
        box-shadow:
            0 0 0 1px hsl(from var(--primary) h s l / 0.8),
            0 0 0 3px var(--kp-sig-deco-lac),
            0 0 0 4px hsl(from var(--primary) h s l / 0.8);
    }
    [data-theme='deco'] .kp-stackbar__seg {
        box-shadow: inset calc(var(--kp-stackbar-gap, 2px) * -1) 0 0 var(--kp-sig-deco-shadow);
    }
    [data-theme='deco'] .kp-stackbar__seg:dir(rtl) {
        box-shadow: inset var(--kp-stackbar-gap, 2px) 0 0 var(--kp-sig-deco-shadow);
    }
    [data-theme='deco'] .kp-stackbar__seg[data-kp-stackbar-hatch],
    [data-theme='deco'] .kp-stackbar__swatch[data-kp-stackbar-hatch] {
        background-image: repeating-linear-gradient(-45deg, transparent 0 3px, var(--kp-sig-deco-lac) 3px 4.5px);
    }
    [data-theme='deco'] .kp-stackbar__seg[data-kp-stackbar-lit] {
        box-shadow:
            inset calc(var(--kp-stackbar-gap, 2px) * -1) 0 0 var(--kp-sig-deco-shadow),
            0 -1px 0 var(--kp-sig-deco-gold-hi),
            0 1px 0 var(--kp-sig-deco-gold-hi);
        filter: brightness(1.15);
    }
    [data-theme='deco'] .kp-stackbar__mark {
        inset-block: -0.5rem;
        inline-size: 1px;
        background: var(--primary);
        box-shadow: none;
    }
    [data-theme='deco'] .kp-stackbar__mark::before {
        content: '';
        position: absolute;
        inset-block-start: -0.2rem;
        inset-inline-start: -0.2rem;
        inline-size: 0.4rem;
        block-size: 0.4rem;
        rotate: 45deg;
        background: var(--kp-sig-deco-gold-lt);
        box-shadow: 0 0 0 1px var(--kp-sig-deco-lac);
    }
    [data-theme='deco'] .kp-stackbar__bar[data-kp-over]::after {
        content: '\25C6';
        color: var(--destructive);
        font-size: 0.6875rem;
    }
    [data-theme='deco'] .kp-stackbar__item {
        border-radius: 0;
    }
    [data-theme='deco'] .kp-stackbar__item[data-kp-stackbar-lit] {
        background: linear-gradient(
            135deg,
            hsl(from var(--kp-sig-deco-gold-hi) h s l / 0.13),
            hsl(from var(--primary) h s l / 0.07) 38%,
            hsl(from var(--kp-sig-deco-gold-lt) h s l / 0.12)
        );
        box-shadow: inset 0 -1px 0 var(--primary);
        color: var(--kp-sig-deco-champagne);
    }
    [data-theme='deco'] .kp-stackbar__swatch {
        inline-size: 0.5rem;
        block-size: 0.5rem;
        margin-inline: 0.125rem;
        rotate: 45deg;
        border-radius: 0;
        box-shadow:
            0 0 0 1px var(--kp-sig-deco-lac),
            0 0 0 2px hsl(from var(--primary) h s l / 0.7);
    }
    [data-theme='deco'] .kp-stackbar__item[data-kp-stackbar-rest] .kp-stackbar__swatch {
        background: var(--kp-sig-deco-lac);
        box-shadow: 0 0 0 1px hsl(from var(--primary) h s l / 0.7);
    }
    [data-theme='deco'] .kp-stackbar__label {
        letter-spacing: 0.04em;
    }
    [data-theme='deco'] .kp-stackbar__value {
        font-family: var(--theme-font-body);
        font-weight: 600;
    }
    [data-theme='deco'] .kp-stackbar__item[data-kp-stackbar-over] .kp-stackbar__value {
        color: var(--destructive);
        text-decoration: underline 1px var(--primary);
        text-underline-offset: 0.3em;
    }
    [data-theme='deco'] .kp-stackbar__note {
        border-style: solid;
        text-align: center;
        font-family: var(--theme-font-body);
    }

    /* Bullet rows: gold leaf when pointed at; a figure of a tone is the figure in ruby over a gold rule (G8). */
    [data-theme='deco'] .kp-bullets__row {
        border-radius: 0;
    }
    [data-theme='deco'] .kp-bullets__row:has(.kp-bullets__link:hover) {
        background: linear-gradient(
            135deg,
            hsl(from var(--kp-sig-deco-gold-hi) h s l / 0.13),
            hsl(from var(--primary) h s l / 0.07) 38%,
            hsl(from var(--kp-sig-deco-gold-lt) h s l / 0.12)
        );
        box-shadow: inset 0 -1px 0 var(--primary);
    }
    [data-theme='deco'] .kp-bullets__row:has(.kp-bullets__link:hover) .kp-bullets__label {
        color: var(--kp-sig-deco-champagne);
        text-decoration: none;
    }
    [data-theme='deco'] .kp-bullets__label {
        letter-spacing: 0.04em;
    }
    [data-theme='deco'] .kp-bullets__figure {
        font-family: var(--theme-font-body);
        font-weight: 600;
    }
    [data-theme='deco'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure,
    [data-theme='deco'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        background: none;
        border-radius: 0;
        color: hsl(from var(--destructive) h s calc(l + 4));
        text-decoration: underline 1px var(--primary);
        text-underline-offset: 0.3em;
    }
    [data-theme='deco'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        text-decoration-style: double;
    }
    [data-theme='deco'] .kp-bullets__note {
        text-align: center;
    }

    /* The key-value grid: the keys in spaced Josefin capitals, hairlines of gold, a changed row marked by a lozenge. */
    [data-theme='deco'] .kp-kv__row > dt {
        font-size: 0.75rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-kv__row > dd {
        font-weight: 500;
    }
    [data-theme='deco'] .kp-kv--lines > .kp-kv__row {
        border-block-end-color: hsl(from var(--primary) h s l / 0.3);
    }
    [data-theme='deco'] .kp-kv {
        --kp-glyph-changed: '\00a0\25C6';
    }
    [data-theme='deco'] .kp-kv__row[data-kp-changed] > dt::after {
        color: var(--kp-sig-deco-gold-lt);
        font-size: 0.6em;
        vertical-align: 0.15em;
    }
    [data-theme='deco'] .kp-kv__row[data-kp-state='error'] > dd {
        color: hsl(from var(--destructive) h s calc(l + 4));
        text-decoration: underline 1px var(--primary);
        text-underline-offset: 0.35em;
    }
    [data-theme='deco'] .kp-kv__row[data-kp-state='error']::before {
        content: none;
    }

    /* Form rows: the label in spaced capitals; changed and not saved, a gold lozenge stands in the gap before the row;
       an error is the same lozenge in ruby. */
    [data-theme='deco'] .kp-formrow__label {
        font-size: 0.75rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-formrow__label > small {
        letter-spacing: 0.02em;
        text-transform: none;
    }
    [data-theme='deco'] .kp-formrow[data-kp-changed]::before,
    [data-theme='deco'] .kp-formrow[data-kp-state='error']::before {
        inset-block: auto;
        inset-block-start: calc((var(--kp-control-height, 2.25rem) - 0.5rem) / 2);
        inset-inline-start: calc(var(--kp-space-sm, 0.5rem) * -1 - 0.1rem);
        inline-size: 0.4rem;
        block-size: 0.4rem;
        rotate: 45deg;
        background: var(--kp-sig-deco-gold-lt);
        box-shadow: 0 0 0 1px var(--kp-sig-deco-lac);
    }
    [data-theme='deco'] .kp-formrow--top[data-kp-changed]::before,
    [data-theme='deco'] .kp-formrow--top[data-kp-state='error']::before {
        inset-block-start: 0.5em;
    }
    [data-theme='deco'] .kp-formrow[data-kp-state='error']::before {
        background: var(--destructive);
    }
    [data-theme='deco'] .kp-formrows--lines > .kp-formrow {
        border-block-end-color: hsl(from var(--primary) h s l / 0.3);
    }
    [data-theme='deco'] .kp-formrow__lock::before {
        border-radius: 0;
    }

    /* The code block: lacquer with the coved double inlay, a double rule under its head, the keys in champagne. */
    [data-theme='deco'] .kp-code {
        --kp-code-key: var(--kp-sig-deco-champagne);
        --kp-code-bg: transparent;
    }
    [data-theme='deco'] .kp-code__head {
        border-block-end: 3px double hsl(from var(--primary) h s l / 0.7);
        padding-block: var(--kp-space-sm, 0.5rem);
    }
    [data-theme='deco'] .kp-code__title {
        font-family: var(--theme-font-display);
        letter-spacing: 0.16em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-code__meta {
        font-family: var(--theme-font-body);
        font-weight: 600;
        letter-spacing: 0.06em;
    }
    [data-theme='deco'] .kp-code__body,
    [data-theme='deco'] .kp-code__note {
        background: var(--kp-sig-deco-shadow);
        border-radius: 0;
    }
    [data-theme='deco'] .kp-code__foot {
        border-block-start-color: hsl(from var(--primary) h s l / 0.35);
        font-family: var(--theme-font-body);
    }
    [data-theme='deco'] .kp-code[data-kp-state='error'] .kp-code__note {
        color: hsl(from var(--destructive) h s calc(l + 4));
        text-decoration: underline 1px var(--primary);
        text-underline-offset: 0.35em;
    }

    /* The header line. */
    [data-theme='deco'] .kp-page-header__line > .kp-page-header__title {
        font-family: var(--theme-font-display);
        letter-spacing: var(--kp-sig-deco-title-track);
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-page-header__meta {
        font-family: var(--theme-font-body);
        letter-spacing: 0.04em;
    }

    /* A number that ticks: gilded while it runs, one flare of gold that settles into its ink when it lands (G9). */
    [data-theme='deco'] [data-kp-tick] {
        font-family: var(--theme-font-body);
        font-weight: 600;
        transition:
            color var(--kp-sig-deco-hover-t) var(--kp-sig-deco-settle),
            text-shadow var(--kp-sig-deco-hover-t) var(--kp-sig-deco-settle);
    }
    [data-theme='deco'] [data-kp-tick][data-kp-tick-state='running'] {
        color: var(--kp-sig-deco-gold-hi);
        text-shadow: 0 0 0.45em hsl(from var(--primary) h s l / 0.8);
    }
    @media (prefers-reduced-motion: reduce) {
        [data-theme='deco'] [data-kp-tick] {
            transition: none;
        }
    }
}

/* ── The uptime strip, in this theme [kpadopt4-ideas] ──
   A strip is a row of lacquer slats between gold hairlines: up is emerald (what is on), a degraded period is gold with
   its fine rules, a down one ruby with its stripes, none an empty frame in gold (G5); pointing warms the slat with gold
   leaf and its edge to full gold (G15); waiting is the glint running between two gold hairlines, the narrow place's own
   loading (G10, G11). */
@layer kp.signature {
    [data-theme='deco'] .kp-uptime {
        --kp-uptime-cell-radius: 0;
        --kp-uptime-up: var(--kp-sig-deco-emerald);
        --kp-uptime-degraded: var(--kp-sig-deco-gold-lo);
        --kp-uptime-down: var(--destructive);
    }
    [data-theme='deco'] .kp-uptime__title {
        font-family: var(--theme-font-display);
        font-size: 0.9375rem;
        letter-spacing: 0.16em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-uptime__percent {
        color: var(--kp-sig-deco-gold-hi);
        font-family: var(--theme-font-body);
        font-weight: 600;
    }
    [data-theme='deco'] .kp-uptime__summary[data-kp-tone='error'] {
        background: none;
        border-radius: 0;
        color: hsl(from var(--destructive) h s calc(l + 4));
        text-decoration: underline 1px var(--primary);
        text-underline-offset: 0.3em;
    }
    [data-theme='deco'] .kp-uptime__cell:not(.kp-skeleton) {
        border: 0;
        border-radius: 0;
        box-shadow: inset 0 0 0 1px hsl(from var(--kp-sig-deco-gold-hi) h s l / 0.35);
    }
    [data-theme='deco'] .kp-uptime__cell[data-kp-tone='none']:not(.kp-skeleton) {
        background: transparent;
        box-shadow: inset 0 0 0 1px hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='deco'] .kp-uptime__cell:is(:hover, :focus-visible, [aria-expanded='true']):not(.kp-skeleton) {
        box-shadow:
            inset 0 0 0 1px var(--kp-sig-deco-gold-hi),
            0 0 0 1px var(--primary);
        filter: brightness(1.2);
    }
    [data-theme='deco'] .kp-uptime__axis {
        font-family: var(--theme-font-body);
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-uptime__info-title {
        font-family: var(--theme-font-display);
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-uptime__swatch {
        border: 0;
        border-radius: 0;
        box-shadow: inset 0 0 0 1px hsl(from var(--kp-sig-deco-gold-hi) h s l / 0.5);
    }
    [data-theme='deco'] .kp-uptime__cell.kp-skeleton {
        visibility: hidden;
    }
    [data-theme='deco'] .kp-uptime__track:has(> .kp-skeleton) {
        background:
            linear-gradient(hsl(from var(--primary) h s l / 0.7), hsl(from var(--primary) h s l / 0.7)) 0 30% / 100% 1px no-repeat,
            linear-gradient(hsl(from var(--primary) h s l / 0.7), hsl(from var(--primary) h s l / 0.7)) 0 70% / 100% 1px no-repeat,
            linear-gradient(
                    90deg,
                    transparent calc(var(--kp-sig-deco-g, 0) * 140% - 48%),
                    hsl(from var(--primary) h s l / 0.3) calc(var(--kp-sig-deco-g, 0) * 140% - 30%),
                    hsl(from var(--kp-sig-deco-gold-lt) h s l / 0.85) calc(var(--kp-sig-deco-g, 0) * 140% - 8%),
                    hsl(from var(--foreground) h s 97%) calc(var(--kp-sig-deco-g, 0) * 140% - 3%),
                    transparent calc(var(--kp-sig-deco-g, 0) * 140% - 1%)
                )
                0 50% / 100% 2px no-repeat;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-uptime__track:has(> .kp-skeleton) {
            animation: kp-sig-deco-glint var(--kp-sig-deco-loop) linear infinite;
        }
        [data-theme='deco'] .kp-uptime__cell {
            transition:
                block-size var(--kp-sig-deco-contact) var(--kp-sig-deco-settle),
                box-shadow var(--kp-sig-deco-contact) var(--kp-sig-deco-settle),
                filter var(--kp-sig-deco-contact) var(--kp-sig-deco-settle);
        }
    }
}

/* ── Rows, checks, choices, a card's four states and the drawings, in this theme [kpadopt4-rows] ──
   A row is ruled by gold hairlines and says its state in a double edge of gold, emerald or ruby; a warning is the words
   in ruby over a gold rule (G8); the next one up is warmed by gold leaf (G15). A tile of choices is a plate of the
   lobby, its pick a hairline gone to full gold with a glow inside the inlay (G5, G7). A card's data comes up with the
   lacquer (G3). The drawings are the fan, drawn as the inlay is, from the centre out in pairs (G2, G13). */
@layer kp.signature {
    [data-theme='deco'] .kp-action-list--lead {
        --kp-action-list-bar: 3px;
        --kp-action-list-next-wash: 0%;
    }
    [data-theme='deco'] .kp-action-list--lead > li {
        border-block-end: 1px solid hsl(from var(--primary) h s l / 0.3);
        border-inline-start-style: double;
    }
    [data-theme='deco'] .kp-action-list--lead > li[data-kp-state='new'] {
        border-inline-start-color: var(--primary);
    }
    [data-theme='deco'] .kp-action-list--lead > li[data-kp-state='active'] {
        border-inline-start-color: var(--kp-sig-deco-emerald);
    }
    [data-theme='deco'] .kp-action-list--lead > li[data-kp-state='warn'],
    [data-theme='deco'] .kp-action-list--lead > li[data-kp-state='failed'] {
        border-inline-start-color: var(--destructive);
    }
    [data-theme='deco'] .kp-action-list--lead > li:is([data-kp-state='warn'], [data-kp-state='failed']) .kp-action-list__title {
        justify-self: start;
        color: hsl(from var(--destructive) h s calc(l + 4));
        text-decoration: underline 1px var(--primary);
        text-underline-offset: 0.35em;
    }
    [data-theme='deco'] .kp-action-list--lead > li[data-kp-state='next'] {
        border-inline-start-color: var(--kp-sig-deco-gold-hi);
        background: linear-gradient(
            135deg,
            hsl(from var(--kp-sig-deco-gold-hi) h s l / 0.13),
            hsl(from var(--primary) h s l / 0.07) 38%,
            hsl(from var(--kp-sig-deco-gold-lt) h s l / 0.12)
        );
        box-shadow: inset 0 -1px 0 var(--primary);
    }
    [data-theme='deco'] .kp-action-list--lead > li[data-kp-state='next'] > .kp-action-list__lead {
        color: var(--kp-sig-deco-gold-hi);
    }
    [data-theme='deco'] .kp-action-list__title {
        letter-spacing: 0.02em;
    }
    [data-theme='deco'] .kp-action-list__when > :first-child {
        font-weight: 600;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-action-list > li.kp-action-list__group {
        padding-inline-start: var(--kp-space-sm, 0.5rem);
        border-block-end: 3px double hsl(from var(--primary) h s l / 0.6);
        color: var(--kp-sig-deco-champagne);
        font-family: var(--theme-font-display);
        font-size: 0.875rem;
        letter-spacing: 0.18em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-action-list__payload {
        border: 1px solid hsl(from var(--primary) h s l / 0.5);
        border-radius: 0;
        background: var(--kp-sig-deco-shadow);
        box-shadow:
            inset 0 0 0 2px var(--kp-sig-deco-lac),
            inset 0 0 0 3px hsl(from var(--primary) h s l / 0.25);
    }
    [data-theme='deco'] .kp-action-list__more > summary {
        letter-spacing: 0.06em;
    }
    [data-theme='deco'] .kp-action-list__more > summary:hover {
        color: var(--kp-sig-deco-champagne);
    }

    /* A check with a reservation: the label in ruby over a gold rule; the mark square with its gold hairline. */
    [data-theme='deco'] .kp-statusrow[data-state='warn'] .kp-statusrow__label {
        justify-self: start;
        color: hsl(from var(--destructive) h s calc(l + 4));
        text-decoration: underline 1px var(--primary);
        text-underline-offset: 0.35em;
    }
    [data-theme='deco'] .kp-statusrow[data-state='warn'] .kp-statusrow__mark {
        border-color: var(--primary);
        background: var(--kp-sig-deco-lac);
        color: hsl(from var(--destructive) h s calc(l + 4));
    }
    [data-theme='deco'] .kp-statusrow__fix {
        letter-spacing: 0.02em;
    }

    /* Choices as tiles: the plate of the lobby, the title in spaced capitals, the pick a gold hairline gone full. */
    [data-theme='deco'] .kp-fieldset[data-kp-layout='tiles'] {
        --kp-field-tiles-gap: 0.75rem;
    }
    [data-theme='deco'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
        position: relative;
        padding: 0.875rem 1.125rem;
        border-color: hsl(from var(--primary) h s l / 0.3);
        color: var(--foreground);
    }
    [data-theme='deco'] .kp-field__option-title {
        font-size: 0.8125rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:hover:not(:has(> .kp-field__check:disabled)) {
        border-color: var(--kp-sig-deco-gold-hi);
        box-shadow: inset 0 0 1.25rem hsl(from var(--primary) h s l / 0.14);
    }
    [data-theme='deco']
        .kp-fieldset[data-kp-layout='tiles']
        > .kp-field__option:hover:not(:has(> .kp-field__check:disabled))
        .kp-field__option-title {
        color: var(--kp-sig-deco-champagne);
    }
    [data-theme='deco'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:checked) {
        border-color: var(--kp-sig-deco-gold-hi);
        background-color: color-mix(in oklab, var(--primary) 9%, var(--kp-sig-deco-lac));
        box-shadow: inset 0 0 1.5rem hsl(from var(--primary) h s l / 0.2);
    }
    [data-theme='deco'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:checked) .kp-field__option-title {
        color: var(--kp-sig-deco-champagne);
    }
    [data-theme='deco'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:disabled) {
        border-style: dashed;
        background-color: var(--muted);
        box-shadow: none;
    }
    [data-theme='deco'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:focus-visible) {
        outline: 3px double var(--primary);
        outline-offset: 3px;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
            transition:
                border-color var(--kp-sig-deco-hover-t) var(--kp-sig-deco-settle),
                box-shadow var(--kp-sig-deco-hover-t) var(--kp-sig-deco-settle),
                background-color var(--kp-sig-deco-hover-t) var(--kp-sig-deco-settle);
        }
    }

    /* A card in four data states: the title of its note in spaced capitals; the data comes up with the lacquer. */
    [data-theme='deco'] .kp-card__state-title {
        font-family: var(--theme-font-display);
        letter-spacing: var(--kp-sig-deco-title-track);
        text-transform: uppercase;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-card[data-kp-state='ready'] > .kp-card__stage > .kp-card__data {
            animation: kp-sig-deco-k4-up var(--kp-sig-deco-up-t) var(--kp-sig-deco-settle) both;
        }
    }
    @keyframes kp-sig-deco-k4-up {
        from {
            opacity: 0;
        }
        to {
            opacity: 1;
        }
    }

    /* The drawings: the lobby's fan in gold hairlines, drawn from the centre out two strokes at a time on the settle
       (G1, G2); the reduced pose is the drawing as it is. */
    [data-theme='deco'] .kp-art {
        display: block;
        --kp-art-stroke: 1.25px;
        --kp-art-rule: var(--kp-sig-deco-gold-hi);
        --kp-art-line: hsl(from var(--primary) h s l / 0.45);
        --kp-art-ink: var(--primary);
        --kp-art-red: hsl(from var(--destructive) h s calc(l + 4));
    }
    [data-theme='deco'] .kp-art > g[data-kp-art-set='fan'] {
        display: inline;
    }
    [data-theme='deco'] .kp-art path {
        stroke-linecap: butt;
        stroke-linejoin: miter;
    }
    [data-theme='deco'] .kp-art path.kp-art__ink {
        stroke-width: 1.25px;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-art path {
            stroke-dasharray: 1;
            animation: kp-sig-deco-art-draw var(--kp-sig-deco-draw-t) var(--kp-sig-deco-settle) both;
            animation-delay: calc(var(--kp-art-i, 0) * 40ms);
        }
    }
    @keyframes kp-sig-deco-art-draw {
        from {
            stroke-dashoffset: 1;
        }
        to {
            stroke-dashoffset: 0;
        }
    }
}

/* ── Flows and records, in this theme [kpadopt4-flows] ──
   A secret is a figure kept under lacquer: shown, it opens from its middle to both sides as the inlay does (G2), and
   its time runs out as a gold hairline with a lozenge at its head (G11, G19). A dialog's sections are divided by a
   gold hairline with a lozenge at its centre, the danger section is the words in ruby over a gold rule (G8, G19). A
   moment on the timeline is a jewel set in gold, a stretch a pair of hairlines. A journey is a path of gold double
   rules through emerald jewels, the step it stands at the double ring (G5, G16). The pipeline's lanes are plates of the
   lobby, a card an inlaid panel warmed by gold leaf (G7, G15). */
@layer kp.signature {
    [data-theme='deco'] .kp-secret {
        --kp-secret-drain: var(--kp-sig-deco-gold-lt);
        --kp-secret-drain-size: 1px;
    }
    [data-theme='deco'] .kp-secret__value {
        border: 1px solid hsl(from var(--primary) h s l / 0.7);
        border-radius: 0;
        background: var(--kp-sig-deco-shadow);
        box-shadow:
            inset 0 0 0 2px var(--kp-sig-deco-lac),
            inset 0 0 0 3px hsl(from var(--primary) h s l / 0.3);
        font-weight: 500;
    }
    [data-theme='deco'] .kp-secret__value.kp-masked {
        letter-spacing: 0.08em;
    }
    [data-theme='deco'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__value {
        border-color: var(--kp-sig-deco-gold-hi);
        color: var(--kp-sig-deco-champagne);
    }
    [data-theme='deco'] .kp-secret[data-kp-secret-state='disabled'] .kp-secret__value {
        border-style: dashed;
        box-shadow: none;
    }
    [data-theme='deco'] .kp-secret__line {
        font-size: 0.8125rem;
        letter-spacing: 0.04em;
    }
    [data-theme='deco'] .kp-secret__drain {
        position: relative;
        background: linear-gradient(to right, hsl(from var(--primary) h s l / 0.5), var(--kp-sig-deco-gold-hi));
        overflow: visible;
    }
    [data-theme='deco'] .kp-secret__drain::after {
        content: '';
        position: absolute;
        inset-block-start: 50%;
        inset-inline-end: 0;
        inline-size: 0.4rem;
        block-size: 0.4rem;
        translate: 50% -50%;
        rotate: 45deg;
        background: var(--kp-sig-deco-gold-lt);
        box-shadow: 0 0 0 1px var(--kp-sig-deco-lac);
    }
    [data-theme='deco'] .kp-secret[data-kp-secret-state='error'] .kp-secret__words {
        border-inline-start: 0;
        padding-inline-start: 0;
        color: hsl(from var(--destructive) h s calc(l + 4));
        text-decoration: underline 1px var(--primary);
        text-underline-offset: 0.35em;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='deco'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__text {
            display: inline-block;
            animation: kp-sig-deco-secret-open var(--kp-sig-deco-draw-t) var(--kp-sig-deco-settle) both;
        }
    }
    @keyframes kp-sig-deco-secret-open {
        from {
            clip-path: inset(0 50% 0 50%);
        }
        to {
            clip-path: inset(0);
        }
    }

    /* The dialog in sections. */
    [data-theme='deco'] .kp-dialog__section {
        position: relative;
        border-block-start-color: hsl(from var(--primary) h s l / 0.45);
        text-align: start;
    }
    [data-theme='deco'] .kp-dialog__section:not(:first-child)::before {
        content: '';
        position: absolute;
        inset-block-start: -0.2rem;
        inset-inline-start: calc(50% - 0.2rem);
        inline-size: 0.4rem;
        block-size: 0.4rem;
        rotate: 45deg;
        background: var(--kp-sig-deco-gold-lt);
        box-shadow: 0 0 0 2px var(--kp-sig-deco-lac);
    }
    [data-theme='deco'] .kp-dialog__heading {
        font-size: 0.8125rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-dialog__section--danger {
        border-inline-start: 0;
        margin-inline: calc(-1 * var(--kp-dialog-section-inset, 0.5rem));
        padding-inline: var(--kp-dialog-section-inset, 0.5rem);
    }
    [data-theme='deco'] .kp-dialog__section--danger .kp-dialog__heading {
        justify-self: start;
        color: hsl(from var(--destructive) h s calc(l + 4));
        text-decoration: underline 1px var(--primary);
        text-underline-offset: 0.35em;
    }
    [data-theme='deco'] .kp-confirm__dependents {
        border: 1px solid hsl(from var(--primary) h s l / 0.5);
        border-radius: 0;
        background: var(--kp-sig-deco-shadow);
        box-shadow:
            inset 0 0 0 2px var(--kp-sig-deco-lac),
            inset 0 0 0 3px hsl(from var(--primary) h s l / 0.25);
        text-align: start;
    }

    /* Moments and stretches on the timeline. */
    [data-theme='deco'] :is(.kp-gantt__point, .kp-gantt__mark)::before {
        box-shadow:
            0 0 0 1px var(--kp-sig-deco-lac),
            0 0 0 2px hsl(from var(--primary) h s l / 0.85);
    }
    [data-theme='deco'] :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-shape='square']::before {
        rotate: 45deg;
        scale: 0.8;
        border-radius: 0;
    }
    [data-theme='deco'] .kp-gantt__point[data-kp-planned]::before {
        background: var(--kp-sig-deco-lac);
    }
    [data-theme='deco'] .kp-gantt__point:hover::before {
        box-shadow:
            0 0 0 1px var(--kp-sig-deco-lac),
            0 0 0 2px var(--kp-sig-deco-gold-hi),
            0 0 0 4px var(--kp-sig-deco-lac),
            0 0 0 5px hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='deco'] .kp-gantt__zone,
    [data-theme='deco'] .kp-gantt__band {
        border-inline: 3px double hsl(from var(--kp-gantt-mark) h s l / 0.6);
        background: hsl(from var(--kp-gantt-mark) h s l / 0.1);
    }
    [data-theme='deco'] .kp-gantt__zone[data-kp-lane-zone] {
        border: 0;
        border-block: 1px solid var(--kp-gantt-mark);
        border-radius: 0;
        background: hsl(from var(--kp-gantt-mark) h s l / 0.35);
    }
    [data-theme='deco'] :is(.kp-gantt__zone, .kp-gantt__band)[data-kp-tone='warning'] {
        --kp-gantt-mark: hsl(from var(--destructive) h s calc(l + 4));
    }
    [data-theme='deco'] .kp-gantt__count {
        border-color: hsl(from var(--primary) h s l / 0.7);
        border-radius: 0;
        background: var(--kp-sig-deco-lac);
        font-family: var(--theme-font-body);
    }
    [data-theme='deco'] .kp-gantt__sub {
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-gantt__lane-link {
        text-decoration-color: hsl(from var(--primary) h s l / 0.7);
    }
    [data-theme='deco'] .kp-gantt__lane-link:hover {
        color: var(--kp-sig-deco-champagne);
        text-decoration-color: var(--kp-sig-deco-gold-hi);
    }

    /* The journey. */
    [data-theme='deco'] .kp-steplist--journey {
        --kp-journey-rule: 3px;
        --kp-steplist-mark: 1.5rem;
    }
    [data-theme='deco'] .kp-steplist--journey > .kp-steplist__item {
        border: 0;
        outline: 0;
        background: transparent;
    }
    [data-theme='deco'] .kp-steplist--journey .kp-steplist__title {
        font-size: 0.8125rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }
    [data-theme='deco'] .kp-steplist--journey > .kp-steplist__item:not([data-state='current']) .kp-steplist__title {
        font-weight: 500;
    }
    [data-theme='deco'] .kp-steplist--journey > .kp-steplist__item[data-state='current'] .kp-steplist__title {
        color: var(--kp-sig-deco-champagne);
        font-weight: 600;
    }
    [data-theme='deco'] .kp-steplist--journey .kp-steplist__time {
        font-family: var(--theme-font-body);
        font-weight: 500;
    }
    [data-theme='deco'] .kp-steplist--journey > .kp-steplist__item + .kp-steplist__item::before,
    [data-theme='deco'] .kp-steplist--journey > .kp-steplist__item:is([data-state='done'], [data-state='current'])::before {
        background:
            linear-gradient(
                    var(--kp-journey-line, hsl(from var(--primary) h s l / 0.35)),
