        background: var(--kp-sig-deco-shadow);
        color: var(--kp-sig-deco-champagne);
    }
    [data-theme='deco'] .kp-type-confirm__status {
        font-size: 0.8125rem;
        letter-spacing: 0.04em;
    }

    /* Command block. */
    [data-theme='deco'] .kp-command {
        --kp-command-prompt-ink: var(--kp-sig-deco-gold-lt);
