        color: var(--foreground);
        letter-spacing: var(--kp-sig-deco-title-track);
    }
    [data-theme='deco'] .kp-checklist__empty[data-kp-checklist-failed] {
        border-color: hsl(from var(--primary) h s l / 0.3);
        text-decoration: none;
    }
    /* The words of a waiting part are a brass nameplate on the doors: lacquer under them and a gold hairline round them, so the
       seams and the lozenges run behind the plate and never through a letter [t56-eye-1018]. */
    [data-theme='deco'] .kp-datatable__busy-words {
        position: relative;
        z-index: 4;
        padding: 0.2em 0.75em;
        background: var(--kp-sig-deco-lac);
