            0 0 0 4px hsl(from var(--primary) h s l / 0.5);
    }

    /* The code box's tools wrap under the title when the line is short, instead of pushing Copy past the box's edge. */
    [data-theme='deco'] .kp-code__tools {
        flex-wrap: wrap;
    }
    [data-theme='deco'] .kp-code__head {
        min-inline-size: 0;
    }
}

/* ── The whole grid loading: one pair of doors over it, not one pair in every day [t56-eye-1018] ──
