            linear-gradient(hsl(from var(--primary) h s l / 0.8), hsl(from var(--primary) h s l / 0.8)) 0 50% / 100% 1px no-repeat,
            linear-gradient(var(--primary), var(--primary)) 0 0 / 1px 100% no-repeat,
