            linear-gradient(90deg, hsl(from var(--foreground) h s l / 0.07) 1px, transparent 1px) 0 0 / 16px 16px,
            hsl(from var(--background) h s calc(l * 0.7));
    }

    /* The unopened dialog is the one js/motion.js measures for the theme's
       time (a probe it adds and takes off), and it reads a close as two thirds
       of that; so it runs one and a half openings, and the dialog that is open
       runs one, which is also its close (5 units, 800 ms: the pen traces the
       outline, the sheet is inked). */
    [data-theme='blueprint'] .kp-dialog {
        --kp-sig-dur: calc(1.5 * var(--kp-sig-bp-panel));
        border: 1px solid var(--primary);
        border-radius: 2px;
        background: var(--popover);
        box-shadow: none;
    }

    [data-theme='blueprint'] .kp-dialog[open] {
