        [data-theme='blueprint'] .kp-tooltip {
            animation: kp-sig-blueprint-callout var(--kp-sig-dur) linear backwards;
        }

        [data-theme='blueprint'] .kp-tooltip::before {
            animation: kp-sig-blueprint-leader var(--kp-sig-dur) linear backwards;
        }

        [data-theme='blueprint'] .kp-tooltip::after {
            animation: kp-sig-blueprint-node var(--kp-sig-dur) linear backwards;
        }
    }

    [data-theme='blueprint'] .kp-tooltip {
        --kp-sig-dur: var(--kp-sig-bp-tip);
        background-repeat: no-repeat;
        background-origin: border-box;
        background-image:
            linear-gradient(var(--primary), var(--primary)), linear-gradient(var(--primary), var(--primary)),
            linear-gradient(var(--primary), var(--primary)), linear-gradient(var(--primary), var(--primary));
        background-size:
            calc(clamp(0, var(--kp-bp-r), 1) * 100%) 1px,
            1px calc(clamp(0, var(--kp-bp-r) - 1, 1) * 100%),
            calc(clamp(0, var(--kp-bp-r) - 2, 1) * 100%) 1px,
            1px calc(clamp(0, var(--kp-bp-r) - 3, 1) * 100%);
