            left top,
            right top,
            right bottom,
            left bottom;
        background-color: var(--popover);
    }

    @media (prefers-reduced-motion: no-preference) {
        @keyframes kp-sig-blueprint-callout {
            0%,
            28% {
                color: transparent;
                border-color: transparent;
                background-color: transparent;
                --kp-bp-r: 0;
                animation-timing-function: var(--kp-sig-bp-feed);
            }

            43% {
                color: transparent;
                border-color: transparent;
                background-color: transparent;
                --kp-bp-r: 1;
                animation-timing-function: var(--kp-sig-bp-feed);
            }

            53% {
                --kp-bp-r: 2;
                animation-timing-function: var(--kp-sig-bp-feed);
            }

            68% {
                --kp-bp-r: 3;
                animation-timing-function: var(--kp-sig-bp-feed);
            }

            74.9% {
                color: transparent;
                border-color: transparent;
                background-color: transparent;
                --kp-bp-r: 4;
            }

            75%,
            100% {
                --kp-bp-r: 4;
            }
        }

        @keyframes kp-sig-blueprint-leader {
            0% {
                transform: scaleY(0);
                animation-timing-function: var(--kp-sig-bp-feed);
            }

            28%,
            100% {
                transform: scaleY(1);
            }
        }

        @keyframes kp-sig-blueprint-node {
            0%,
            27.9% {
                opacity: 0;
            }

            28%,
            100% {
                opacity: 1;
            }
        }
    }

    @keyframes kp-sig-blueprint-blueprint-compass {
        0% {
            opacity: 1;
            clip-path: polygon(50% 50%, 50% 0, 50% 0, 50% 0, 50% 0, 50% 0, 50% 0);
        }

        8% {
            clip-path: polygon(50% 50%, 50% 0, 100% 0, 100% 0, 100% 0, 100% 0, 100% 0);
        }

        24% {
            clip-path: polygon(50% 50%, 50% 0, 100% 0, 100% 100%, 100% 100%, 100% 100%, 100% 100%);
        }

        40% {
            clip-path: polygon(50% 50%, 50% 0, 100% 0, 100% 100%, 0 100%, 0 100%, 0 100%);
        }

        56% {
            clip-path: polygon(50% 50%, 50% 0, 100% 0, 100% 100%, 0 100%, 0 0, 0 0);
        }

        64%,
        82% {
            opacity: 1;
            clip-path: polygon(50% 50%, 50% 0, 100% 0, 100% 100%, 0 100%, 0 0, 50% 0);
        }

        100% {
            opacity: 0;
            clip-path: polygon(50% 50%, 50% 0, 100% 0, 100% 100%, 0 100%, 0 0, 50% 0);
        }
    }

    @keyframes kp-sig-blueprint-blueprint-draw {
        from {
            clip-path: inset(0 100% 0 0);
        }

        to {
            clip-path: inset(0);
        }
    }

    @keyframes kp-sig-blueprint-blueprint-mark {
        from {
            opacity: 0;
            transform: scale(0.4) rotate(-90deg);
        }

        to {
            opacity: 1;
            transform: none;
        }
    }

    /* Growing and shrinking, and leaving, this theme's way [scope-142; the
       drawing and the hatched leave Kenny picked on 2026-10-04 are replaced by
       the character of 2026-10-07 23:41, below: a part that arrives and leaves
       is read out on its own scales, a box that grows or shrinks glides on the
       plotter's feed, which is the curve the entrance js/motion.js reads it
       from]. A box that is measured anew keeps no frame round it any more: a
       closed dashed frame round what is inside is the one thing this sheet
       never draws.

       Opening is closing turned around (Kenny's pick on research/open-reverse,
       2026-10-05): js/motion.js opens the dialog as its close played
       backwards, in the close's time, and lets what arrives play its leave
       backwards. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='blueprint'] {
            --kp-open: reverse-close;
        }
    }

    /* A reader who asked for no motion gets no close of the bar's menus to wait
       for (js/components.js otherwise waits its own 300 ms). */
    @media (prefers-reduced-motion: reduce) {
        [data-theme='blueprint'] {
            --kp-nav-close-time: 0ms;
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 3, while
       loading 1, how the share arrives 1, when the tone changes 1,
       the mark past the end 3]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='blueprint']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='blueprint']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
