    }

    [data-theme='blueprint'] .kp-calendar__busy-text {
        font-size: var(--kp-text-md, 1rem);
    }
}

/* ── The acknowledge gate is flagged, not filled [G13, t56-eye-1018] ──
   A warning on the sheet is the outlined triangle in the lit amber before its title on the two axes drawn in that ink, on no
   plate: the flat brown block carried no mark of the sheet. */
@layer kp.signature {
