    [data-theme='blueprint'] .kp-skeleton.kp-toggle__bone::before,
    [data-theme='blueprint'] .kp-skeleton.kp-toggle__bone::after {
        content: none;
    }
}

/* ── graph loading · r3-bp-load-3 · Current finds the circuit (research/character-graph/decided.json, Kenny 2026-10-06 21:37) ── */
@layer kp.signature {
