        content: '';
        position: absolute;
        inset-inline-start: 0.75rem;
        inset-block-start: calc(50% - 0.3rem);
        inline-size: 0.6rem;
        block-size: 0.6rem;
        border-radius: 50%;
        background: var(--kp-sig-no-lens);
        box-shadow:
            0 0 0 2px var(--foreground),
            0 0 6px 2px hsl(from var(--kp-sig-no-led) h s l / 0.45);
