    /* js/motion.js learns the theme's time from an unopened dialog (a probe
       it adds and takes off) and closes in two thirds of it: so an unopened
       dialog is drawn over 480 ms and the open one in 320 ms (4 frames),
       which is also its close and, opening as its close reversed, its
       opening. Both in 4 bands: the probe's curve is the one motion.js folds
       a disclosure on, in the size time (320 ms), so 4 bands keep that fold
       on the 80 ms clock too. */
    [data-theme='nostromo'] .kp-dialog {
        --kp-sig-dur: calc(var(--kp-sig-no-frame) * 6);
        --kp-sig-no-n: 4;
        --kp-sig-no-tail: 1.2rem;
        --kp-sig-no-screw: radial-gradient(
            circle,
            hsl(from var(--foreground) h s l / 0.45) 0 1.5px,
            hsl(from var(--foreground) h s l / 0.2) 2px 3px,
            transparent 3.5px
        );
        background:
            var(--kp-sig-no-screw) 6px 6px / 8px 8px no-repeat,
            var(--kp-sig-no-screw) calc(100% - 6px) 6px / 8px 8px no-repeat,
            var(--kp-sig-no-screw) 6px calc(100% - 6px) / 8px 8px no-repeat,
            var(--kp-sig-no-screw) calc(100% - 6px) calc(100% - 6px) / 8px 8px no-repeat,
            var(--card);
        box-shadow:
            var(--kp-sig-no-raised),
            0 12px 28px -14px hsl(from var(--foreground) h s l / 0.5);
    }

    [data-theme='nostromo'] .kp-dialog[open] {
        --kp-sig-dur: var(--kp-sig-no-strike);
    }

    /* The beam rides the edge of what the raster has written: a bright line
       with a fading phosphor tail. At rest it is away, so the reduced pose is
       the finished dialog. A dialog in the page's flow (not a <dialog>, which
       the browser places itself) holds it. */
    [data-theme='nostromo'] .kp-dialog:not(dialog) {
        position: relative;
    }

    /* A toast, a tile and a key figure carry the same beam, but not on a
       pseudo-element: the toast's ::before is its lamp, a card's the stamp,
       and a key figure is the box its trend link's ::after stretches over.
       Theirs is one mechanism for all three, a background layer that exists
       only while the raster draws or erases them (the beam-layer keyframes
       below): at rest the part has no extra layer at all. The tail is the
       research demo's for a tile and a leaving part (research/nostromo-
       character, 1.1 rem). */
    [data-theme='nostromo'] :is(.kp-card, .kp-kpi) {
        --kp-sig-no-tail: 1.1rem;
    }

    [data-theme='nostromo'] .kp-dialog::after {
        content: '';
        position: absolute;
        z-index: 1;
        inset-inline: 0;
        inset-block-start: calc(var(--kp-sig-no-tail) * -1);
        block-size: var(--kp-sig-no-tail);
        background: var(--kp-sig-no-beam);
        opacity: 0;
        pointer-events: none;
    }

    [data-theme='nostromo'] .kp-dialog__title {
        /* The title at the package's metrics [scope-87]: Kenny chose the fixed size
           over the theme's own on 2026-10-03 (research/dialog-title). */
        font-family: var(--theme-font-display);
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    [data-theme='nostromo'] .kp-tooltip {
        --kp-sig-dur: var(--kp-sig-no-contact);
        --kp-sig-no-n: 2;
        margin-inline-start: 0.5rem;
        padding: 0.2rem 0.6rem;
        border: 0;
        border-radius: var(--kp-sig-no-tape);
        background: var(--foreground);
        color: var(--primary-foreground);
        box-shadow: 0 1px 2px hsl(from var(--foreground) h s l / 0.4);
        font-family: var(--theme-font-mono);
        font-size: 0.72rem;
        letter-spacing: 0.14em;
        text-shadow: 0 -1px 0 hsl(from var(--foreground) h s l / 0.9);
        text-transform: uppercase;
    }

    [data-theme='nostromo'] .kp-wizard__steps {
        gap: 0.5rem 1rem;
    }

    [data-theme='nostromo'] .kp-wizard__steps li {
        gap: 0.5rem;
    }

    [data-theme='nostromo'] .kp-wizard__steps li::before {
        inline-size: 1.7rem;
        block-size: 1.6rem;
        border: 1px solid var(--border-strong);
        border-radius: var(--kp-sig-no-key);
        background: var(--card);
        box-shadow: var(--kp-sig-no-raised);
        color: var(--foreground);
        font-family: var(--theme-font-mono);
    }

    [data-theme='nostromo'] .kp-wizard__steps li[data-state='done']::before {
        border-color: var(--border-strong);
        color: var(--selected);
        font-weight: 700;
    }

    [data-theme='nostromo'] .kp-wizard__steps li[data-state='current']::before {
        border-color: var(--border-strong);
        background: var(--background);
        box-shadow: var(--kp-sig-no-well);
        color: var(--foreground);
        transform: translateY(1px);
    }

    [data-theme='nostromo'] .kp-wizard__steps li[data-state='current']::after {
        content: '';
        inline-size: 0.5rem;
        block-size: 0.5rem;
        border-radius: 50%;
        background: var(--kp-sig-no-lens);
        box-shadow:
            0 0 0 2px var(--foreground),
            0 0 5px 2px hsl(from var(--kp-sig-no-led) h s l / 0.45);
    }

    [data-theme='nostromo'] .kp-empty {
        position: relative;
        padding: 2.4rem 1.25rem 1.25rem;
        border: 1px solid var(--border-strong);
        border-radius: 0.3rem;
        background: var(--card);
        box-shadow: var(--kp-sig-no-well);
        color: var(--muted-foreground);
    }

    [data-theme='nostromo'] .kp-empty::before {
        content: '';
        position: absolute;
        inset-block-start: 0.8rem;
        inset-inline: calc(50% - 3rem);
        block-size: 0.9rem;
        background: repeating-linear-gradient(to bottom, hsl(from var(--foreground) h s l / 0.3) 0 2px, transparent 2px 4.5px);
        border-radius: 1px;
    }

    /* The empty plate's ink tape names the state at heading size (DEMO_RULES 3): the stateplate's title is the same
       tape as every other empty title, so an empty area reads alike wherever the page draws it. */
    [data-theme='nostromo'] :is(.kp-empty__title, .kp-stateplate--empty .kp-stateplate__title) {
        display: inline-block;
        margin-block-end: 0.5rem;
        padding: 0.2rem 0.75rem;
        border-radius: 2px;
        background: var(--foreground);
        color: var(--primary-foreground);
        font-family: var(--theme-font-mono);
        font-size: clamp(1rem, 0.9rem + 0.4vw, 1.25rem);
        font-weight: 400;
        letter-spacing: 0.08em;
        line-height: 1.3;
        text-transform: uppercase;
    }

    [data-theme='nostromo'] .kp-empty__body {
        margin: 0;
    }

    [data-theme='nostromo'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a) {
        color: var(--primary);
        text-decoration-color: var(--kp-underline, hsl(from var(--selected) h s l / 0.28));
        text-decoration-thickness: 2px;
        text-underline-offset: 0.22em;
    }

    [data-theme='nostromo'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
        text-decoration-color: var(--selected);
        text-decoration-thickness: 3px;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='nostromo'] .kp-spinner::before {
            animation: kp-sig-nostromo-no-reel var(--kp-sig-dur) steps(20, end) infinite;
        }

        /* The radio's lens is a lamp: it switches on in one frame, never
           bouncing (G1). The tick is printed start to end in 2 frames. */
        [data-theme='nostromo'] .kp-field__check[type='radio']:checked::before {
            animation: kp-sig-nostromo-lamp-on var(--kp-sig-no-frame) steps(1, end) backwards;
        }

        [data-theme='nostromo'] .kp-field__check[type='checkbox']:checked::before {
            animation: kp-sig-nostromo-no-punch var(--kp-sig-no-contact) steps(2, end) backwards;
        }

        [data-theme='nostromo'] .kp-switch__input::before {
            transition: transform var(--kp-sig-no-contact) var(--kp-sig-no-f2);
        }

        /* The raster draws them from the top edge down, a band per frame; the
           toast's lamp is drawn with its plate (it no longer strikes on with
           a bounce of its own). Closing is this played backwards: the dialog
           by js/motion.js, the tooltip by playEntranceBackwards(), the toast
           by its leave below, which is this draw reversed. */
        [data-theme='nostromo'] :is(.kp-dialog, .kp-tooltip) {
            animation: kp-sig-nostromo-raster var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards;
        }

        [data-theme='nostromo'] .kp-dialog::after {
            animation: kp-sig-nostromo-beam var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards;
        }

        /* The toast's beam rides the same edge on the same frames, as a
           background layer (its ::before is the lamp). */
        [data-theme='nostromo'] .kp-toast {
            animation:
                kp-sig-nostromo-raster var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards,
                kp-sig-nostromo-beam-layer var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards;
        }

        /* The tour's card opens as a panel does, and the tour plays it
           backwards when it closes (js/tour.js, playEntranceBackwards()). */
        [data-theme='nostromo'] .kp-tour[open] {
            animation: kp-sig-nostromo-raster var(--kp-sig-no-strike) steps(4, end) backwards;
        }
    }

    /* The raster (the anchor, research/nostromo-anchor): the part uncovered
       from its top edge, a band per frame (the timing function's steps); its
       own shadow may show past its edge while it is drawn. */
    @keyframes kp-sig-nostromo-raster {
        from {
            clip-path: inset(calc(var(--kp-sig-no-reach) * -1) calc(var(--kp-sig-no-reach) * -1) 100% calc(var(--kp-sig-no-reach) * -1));
        }

        to {
            clip-path: inset(calc(var(--kp-sig-no-reach) * -1));
        }
    }

    /* The beam riding the edge of what is written, its tail behind it; it
       goes out on the last frame. */
    @keyframes kp-sig-nostromo-beam {
        from {
            inset-block-start: calc(var(--kp-sig-no-tail) * -1);
            opacity: 1;
        }

        90% {
            opacity: 1;
        }

        to {
            inset-block-start: calc(100% - var(--kp-sig-no-tail));
            opacity: 0;
        }
    }

    /* The same beam as a background layer, for a part whose pseudo-elements
       are taken: the image, its size and its box are set only while it
       plays, so at rest the part keeps its own background untouched. The
       layer is the tail's height, its foot on the border box's edge that
       the raster has reached: -tail at the start (above the part, unseen),
       100% at the end (its foot on the bottom edge); in between, at a share
       p of the draw, its top is p * height - tail, the dialog's ::after's
       place. It lies under the part's text and inset frames (the klaxon
       frame stays on top). */
    @keyframes kp-sig-nostromo-beam-layer {
        from {
            background-image: var(--kp-sig-no-beam);
            background-repeat: no-repeat;
            background-origin: border-box;
            background-size: 100% var(--kp-sig-no-tail);
            background-position: 0 calc(var(--kp-sig-no-tail) * -1);
        }

        to {
            background-image: var(--kp-sig-no-beam);
            background-repeat: no-repeat;
            background-origin: border-box;
            background-size: 100% var(--kp-sig-no-tail);
            background-position: 0 100%;
        }
    }

    /* The beam layer travelling back up as the raster erases: the draw's
       keyframes the other way, on the erase's timing, so frame t of the
       leave is frame (T - t) of the draw. */
    @keyframes kp-sig-nostromo-beam-layer-erase {
        from {
            background-image: var(--kp-sig-no-beam);
            background-repeat: no-repeat;
            background-origin: border-box;
            background-size: 100% var(--kp-sig-no-tail);
            background-position: 0 100%;
        }

        to {
            background-image: var(--kp-sig-no-beam);
            background-repeat: no-repeat;
            background-origin: border-box;
            background-size: 100% var(--kp-sig-no-tail);
            background-position: 0 calc(var(--kp-sig-no-tail) * -1);
        }
    }

    @keyframes kp-sig-nostromo-lamp-on {
        from {
            opacity: 0;
        }

        to {
            opacity: 1;
        }
    }

    @keyframes kp-sig-nostromo-no-reel {
        to {
            transform: rotate(360deg);
        }
    }

    @keyframes kp-sig-nostromo-no-punch {
        from {
            clip-path: inset(0 100% 0 0);
        }

        to {
            clip-path: inset(0);
        }
    }

    /* ── The waiting screen [loading "raster", Kenny 08/10/2026 00:05,
       research/nostromo-character; G10] ─────────────────────────────────
       Everything that waits is a small amber screen set into the case: dark
       glass in a moulded bezel with its scanlines, a hum band rolling down
       it in 10 steps, and its picture written row by row from the top in 12
       frames under the beam (the bright edge with its fading tail), standing
       for 6 frames and blanked for 2: 20 frames of 80 ms, 1600 ms a cycle
       (--kp-sig-no-loop). The busy progress bar keeps its LED window and
       its lamps compute instead (busy "led", above); a skeleton line is a glass with a line of phosphor being
       written, the lines a panel (4 frames) apart; a block skeleton, and so
       the time chart's plot while it loads, writes COMPUTING in its middle;
       a loading day of the month is a glass cell; the menu's loading entry
       and the data table's busy panel carry a glass along their foot. The
       spinner stays the tape reel (G11) and the network graph its blips
       (G18). Standing still (reduced motion) the picture stands written,
       never a share. Every glass is two layers on one element: ::before the
       glass (ground, bezel, scanlines and the hum band), ::after the
       picture and its beam, clipped from the top; the picture takes the
       scanlines through its mask, so the words lie under them as on the
       tube. */
    [data-theme='nostromo'] {
        /* The scanlines over the glass, 1 px every 3 px, and the same lines
           as a mask, for a picture that lies under them. */
        --kp-sig-no-scan: repeating-linear-gradient(to bottom, hsl(from var(--sidebar-background) h s l / 0.45) 0 1px, transparent 1px 3px);
        --kp-sig-no-scan-mask: repeating-linear-gradient(to bottom, hsl(from var(--foreground) h s l / 0.55) 0 1px, var(--foreground) 1px 3px);
        /* The hum band: a dim amber bar 40 % of the glass tall. */
        --kp-sig-no-hum: linear-gradient(to bottom, transparent, hsl(from var(--sidebar-primary) h s l / 0.22) 60%, transparent) 0 -66.67% / 100% 40%
            no-repeat;
    }

    /* The glass of a part that is itself the screen: its own ground. */
    [data-theme='nostromo'] .kp-skeleton:not(.kp-skeleton--circle),
    [data-theme='nostromo'] .kp-calendar__day[data-kp-tone='loading'] {
        position: relative;
        overflow: hidden;
        border: 2px solid var(--secondary);
        border-radius: var(--kp-sig-no-key);
        background: var(--sidebar-background);
        box-shadow:
            0 0 0 1px var(--border-strong),
