    :where([data-theme='nostromo']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='nostromo']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='nostromo']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='nostromo']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='nostromo']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='nostromo']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='nostromo']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── nostromo · the backlit vents ─────────────────────────────── */
    [data-theme='nostromo'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.625rem;
        --kp-sig-meter-room: 1rem;
        --kp-meter-fill: var(--accent);
        --kp-sig-meter-mo-ink: var(--primary);
        --kp-sig-meter-slots: linear-gradient(90deg, var(--foreground) 0 3px, transparent 3px) 1px 0 / 6px 100% repeat-x;
        border-radius: 2px;
        background:
            linear-gradient(90deg, var(--primary) 0 3px, transparent 3px) 1px 1px / 6px calc(100% - 2px) repeat-x,
            var(--secondary);
        box-shadow: 0 0 0 1px var(--border-strong);
    }

    /* The slots lit orange from inside, up to the share. */
    [data-theme='nostromo'] :is(.kp-meter, .kp-kpi__meter)::before {
        inset-block: 1px;
        border-radius: 0;
        background: linear-gradient(90deg, var(--kp-meter-fill-colour) 0 3px, transparent 3px) 1px 0 / 6px 100% repeat-x;
        filter: drop-shadow(0 0 2px hsl(from var(--kp-meter-fill-colour) h s l / 0.7));
    }

    /* Embossed black label tape with a ▼, on a dark line. */
    [data-theme='nostromo'] .kp-meter__mark {
        inset-block: -2px;
        border-radius: 0;
        background: var(--primary);
        box-shadow: 0 0 0 1px var(--popover);
    }

    [data-theme='nostromo'] .kp-meter__mark::before {
        content: '▼';
        position: absolute;
        inset-block-end: calc(100% + 1px);
        inset-inline-start: 50%;
        padding: 1px 2px;
        translate: -50% 0;
        border-radius: 1px;
        background: var(--primary);
        color: var(--popover);
        font: 700 0.4375rem/1 var(--theme-font-mono, monospace);
    }

    /* A cut piece of label tape reads +. */
    [data-theme='nostromo'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '+';
        inset-inline-start: calc(100% + 3px);
        inset-block-start: 50%;
        padding: 1px 5px 1px 3px;
        translate: 0 -50%;
        background: var(--primary);
        color: var(--popover);
        font: 700 0.625rem/1 var(--theme-font-mono, monospace);
        clip-path: polygon(0 0, calc(100% - 3px) 0, 100% 100%, 0 100%);
    }

    /* ── while loading: option 1 ── */

    /* A glow runs along the slots, one after another. */
    [data-theme='nostromo'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        inset-block: 1px;
        background: linear-gradient(90deg, transparent, var(--accent), transparent) 50% 0 / 30% 100% no-repeat;
        -webkit-mask: var(--kp-sig-meter-slots);
        mask: var(--kp-sig-meter-slots);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='nostromo'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            animation: kp-sig-nostromo-meter-scan 2000ms steps(16) infinite;
        }
    }

    /* ── how the share arrives: option 3, on the frame clock ──
       The share is printed start to end in 8 frames (640 ms, a print; it was
       1600 ms on cubic-bezier(0.6, 0, 0.4, 1)). The glide to a new value
       (the transition) is a live change, which Kenny has not decided yet
       (research/nostromo-character, "live" reopened): it is left as it was. */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='nostromo'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-nostromo-meter-wipe-o var(--kp-sig-no-print) steps(8, end) backwards;
            transition: inline-size 1600ms cubic-bezier(0.6, 0, 0.4, 1);
        }
    }

    /* ── when the tone changes: the klaxon (Kenny, 2026-10-07 23:18, tone
       "klaxon"; it was option 2, the relay's jolt sideways) ──
       A meter in warning or failure is framed all round in its tone's ink,
       3 px outside its moulded edge; nothing moves. */
    [data-theme='nostromo'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning'] {
        box-shadow:
            0 0 0 1px var(--border-strong),
            0 0 0 4px var(--warning);
    }

    [data-theme='nostromo'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive'] {
        box-shadow:
            0 0 0 1px var(--border-strong),
            0 0 0 4px var(--destructive);
    }

    /* ── the mark past the end: option 3 ── */

    [data-theme='nostromo'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '▼';
    }

    [data-theme='nostromo'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
        rotate: 24deg;
        transform-origin: 50% 100%;
    }

    [data-theme='nostromo'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        rotate: -24deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='nostromo'] .kp-meter__mark {
            transition:
                inset-inline-start 500ms ease-in-out,
                rotate 500ms ease-in-out;
        }
    }

    @keyframes kp-sig-nostromo-meter-scan {
        0% {
            background-position: -40% 0;
        }

        100% {
            background-position: 140% 0;
        }
    }

    @keyframes kp-sig-nostromo-meter-wipe-o {
        0% {
            clip-path: inset(0 100% 0 0);
        }

        100% {
            clip-path: inset(0);
        }
    }

    /* A menu and a popover are drawn by the raster as the toast is, the beam riding the
       edge as a background layer, 4 frames (G3); they close as the draw played backwards
       (js/motion.js playClose). */
    [data-theme='nostromo'] :is(.kp-menu-button > .kp-menu, .kp-popover[popover]:not(.kp-tooltip)) {
        --kp-sig-dur: var(--kp-sig-no-strike);
        --kp-sig-no-n: 4;
        --kp-sig-no-tail: 1.1rem;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='nostromo'] :is(.kp-menu-button > .kp-menu, .kp-popover[popover]:not(.kp-tooltip)) {
            animation:
                kp-sig-nostromo-raster var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards,
                kp-sig-nostromo-beam-layer var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards;
        }
    }

    /* ── Pairs: every close is its open reversed, and the raster on every part that opens
       [all-themes audit, 2026-10-13; docs/THEME_LESSONS.md 19-27, 31, 36-38]. What opens is drawn
       by the raster from its top edge down, a band per 80 ms frame, the beam riding the edge (G3);
       what closes or leaves is erased the same way backwards, frame for frame (G12). ── */
    [data-theme='nostromo'] {
        /* A part a script removes or hides leaves first, erased by the raster (lesson 19); what
           takes no box arrives as nothing (23); the space a leave folds shut takes the erase's own
           4 frames and starts with it (24). */
        --kp-leave-state: leave;
        --kp-arrive-unseen: skip;
        --kp-leave-fold-grow: 1;
        --kp-leave-fold-start: 0;
        /* The bar's hover dropdown and its phone panel are held on screen for the erase's 4 frames
           (js/components.js, lesson 36). */
        --kp-nav-close-time: 320ms;
        /* Four equal frames the other way round: the raster's `steps(4, end)` turned round, holding
           the pose before each jump at the frame boundary itself (cyberpunk's `--kp-cp-back`), so
           frame t of a close is frame (T - t) of its opening on the boundaries too. */
        --kp-sig-no-back4: linear(0 0%, 0.25 0.01%, 0.25 25%, 0.5 25.01%, 0.5 50%, 0.75 50.01%, 0.75 75%, 1 75.01%, 1 100%);
        /* The tour's dim and ring come in the card's 4 frames and go in the same 4 the other way
           round (lessons 11, 22). */
        --kp-tour-dim-close: 0 0 0 0 transparent;
        --kp-tour-dim-time: var(--kp-sig-no-strike);
        --kp-tour-dim-close-ease: var(--kp-sig-no-back4);
        --kp-tour-dim-close-delay: 0s;
    }

    @media (prefers-reduced-motion: reduce) {
        [data-theme='nostromo'] {
            --kp-nav-close-time: 0ms;
        }
    }

    /* A tree branch's children are kept drawn while their group glides shut (lesson 26). */
    [data-theme='nostromo'] .kp-tree [role='treeitem'][aria-expanded='false'] > [role='group'][data-kp-group-folding],
    [data-theme='nostromo'] .kp-tree [role='treeitem'][aria-expanded='false'] + [role='group'][data-kp-group-folding] {
        display: block;
    }

    /* The panels the raster draws here, with the beam's tail the popover's. */
    [data-theme='nostromo'] :is(.kp-palette, .kp-shortcuts, .kp-datepicker__panel, .kp-combobox__list, .kp-nav__menu, .kp-nav__links) {
        --kp-sig-dur: var(--kp-sig-no-strike);
        --kp-sig-no-n: 4;
        --kp-sig-no-tail: 1.1rem;
    }

    @media (prefers-reduced-motion: no-preference) {
        /* The palette and the shortcuts sheet are drawn as the dialog is; js/motion.js closes them
           as that draw played backwards (and opens them as that close turned round). */
        [data-theme='nostromo'] :is(.kp-palette, .kp-shortcuts)[open] {
            animation:
                kp-sig-nostromo-raster var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards,
                kp-sig-nostromo-beam-layer var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards;
        }

        /* The date picker's panel and the combobox's list are drawn as the popover is; js/motion.js
           playClose plays that backwards (the panel's opening mark stays on through the close,
           lesson 10). The list arrives as its own draw, not as the leave turned around. */
        [data-theme='nostromo']
            :is(.kp-combobox__list:popover-open, .kp-datepicker__panel:is([data-kp-date-open], [data-kp-closing], [data-kp-reversing]):popover-open) {
            animation:
                kp-sig-nostromo-raster var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards,
                kp-sig-nostromo-beam-layer var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards;
        }

        [data-theme='nostromo'] .kp-combobox__list {
            --kp-open: own;
        }

        /* The alarm is the bridge's screen: drawn by the raster from its top edge down with the beam
           riding the edge, 4 frames, the headline and the reason with it (the package's rise, scale
           and fades are not this theme's: G3, nothing rises or scales). js/motion.js closes it as the
           draw backwards. */
        [data-theme='nostromo'] .kp-alarm {
            --kp-sig-no-tail: 1.2rem;
        }

        [data-theme='nostromo'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            animation:
                kp-sig-nostromo-raster var(--kp-sig-no-strike) steps(4, end) backwards,
                kp-sig-nostromo-beam-layer var(--kp-sig-no-strike) steps(4, end) backwards;
        }

        [data-theme='nostromo'] .kp-alarm:not([data-kp-alarm-motion='still']) :is(.kp-alarm__panel, .kp-alarm__title, .kp-alarm__detail) {
            animation: none;
        }

        /* The side navigation (over, push) is switched on where it stands: it does not slide in
           from its edge (G2) but is drawn by the raster, 4 frames, and erased by it when it closes;
           only then does it go back off screen and out of sight. The content a push panel makes
           room in moves with the first frame of the opening and the last of the closing. */
        [data-theme='nostromo'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) {
            --kp-sig-no-tail: 1.1rem;
        }

        [data-theme='nostromo'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true'] {
            visibility: visible;
            transition:
                translate 0s linear,
                visibility 0s linear;
            animation:
                kp-sig-nostromo-raster var(--kp-sig-no-strike) steps(4, end) backwards,
                kp-sig-nostromo-beam-layer var(--kp-sig-no-strike) steps(4, end) backwards;
        }

        [data-theme='nostromo'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='false'] {
            visibility: hidden;
            transition:
                translate 0s linear var(--kp-sig-no-strike),
                visibility 0s linear var(--kp-sig-no-strike);
            animation:
                kp-sig-nostromo-erase var(--kp-sig-no-strike) steps(4, jump-start),
                kp-sig-nostromo-beam-layer-erase var(--kp-sig-no-strike) steps(4, jump-start);
        }

        [data-theme='nostromo'] .kp-sidenav__backdrop {
            animation-duration: var(--kp-sig-no-strike);
            animation-timing-function: steps(4, end);
        }

        [data-theme='nostromo'] [data-kp-sidenav-shift='open'] {
            transition:
                margin-inline-start 0s linear,
                padding-inline-start 0s linear;
        }

        [data-theme='nostromo'] [data-kp-sidenav-shift='closed'] {
            transition:
                margin-inline-start 0s linear var(--kp-sig-no-strike),
                padding-inline-start 0s linear var(--kp-sig-no-strike);
        }

        /* The tour's dim and the ring round its target come in the card's 4 equal frames. */
        [data-theme='nostromo'] [data-kp-tour-target] {
            transition:
                box-shadow var(--kp-sig-no-strike) steps(4, end),
                outline-color var(--kp-sig-no-strike) steps(4, end);
        }

        /* The busy table dims at once when its layer is drawn (layout.css, `[aria-busy]`) and comes
           back at once when the erase is over, not when it starts: the switch the opening throws
           first, the closing throws last. The package's resize transitions are restated with it. */
        [data-theme='nostromo'] .kp-datatable {
            transition:
                outline-color calc(var(--kp-resize-dur, 300ms) / 2) ease-out,
                outline-offset calc(var(--kp-resize-dur, 300ms) / 2) ease-out,
                filter calc(var(--kp-resize-dur, 300ms) / 2) ease-out,
                opacity 0s linear var(--kp-sig-no-strike);
        }

        [data-theme='nostromo'] .kp-datatable[aria-busy='true'] {
            transition:
                outline-color calc(var(--kp-resize-dur, 300ms) / 2) ease-out,
                outline-offset calc(var(--kp-resize-dur, 300ms) / 2) ease-out,
                filter calc(var(--kp-resize-dur, 300ms) / 2) ease-out,
                opacity 0s linear;
        }

        /* Its kept rows, dimmed further while it refreshes, the same way. */
        [data-theme='nostromo'] .kp-datatable .kp-table tbody {
            transition: opacity 0s linear var(--kp-sig-no-strike);
        }

        [data-theme='nostromo'] .kp-datatable[aria-busy='true'] .kp-table tbody {
            transition: opacity 0s linear;
        }

        /* The calendar's busy layers (the whole grid's card and a day's spinner) are drawn by the
           raster and erased by it (the leave above): js/calendar.js marks a layer `[data-kp-leaving]`
           while its state goes (`--kp-calendar-busy-leave: hold`), and the rules below keep it drawn
           through the erase. */
        [data-theme='nostromo'] :is(.kp-calendar__day-busy, .kp-calendar__busy) {
            --kp-calendar-busy-leave: hold;
            transition: none;
        }

        [data-theme='nostromo']
            :is(.kp-calendar--busy-days, .kp-calendar--busy-whole:not(:has(> .kp-calendar__grid[aria-busy='true'])))
            .kp-calendar__day[data-kp-tone='loading']
            > .kp-calendar__day-busy,
        [data-theme='nostromo'] .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true']) > .kp-calendar__busy {
            animation: kp-sig-nostromo-raster var(--kp-sig-no-strike) steps(4, end) backwards;
        }

        [data-theme='nostromo'] .kp-calendar__day:has(> .kp-calendar__day-busy[data-kp-leaving]) {
            position: relative;
        }

        [data-theme='nostromo'] .kp-calendar__day-busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-spinner, 0.75rem);
            position: absolute;
            inset-inline: 0;
            inset-block-end: 0.125rem;
            display: flex;
            justify-content: center;
            line-height: 0;
        }

        [data-theme='nostromo'] .kp-calendar--busy-whole > .kp-calendar__busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-busy-spinner, 2.5rem);
            z-index: 1;
            display: grid;
            place-self: center;
            place-items: center;
            padding: var(--kp-space-md, 1rem);
            border-radius: var(--radius, 0.75rem);
            background: var(--card);
            box-shadow: 0 0 0 1px var(--border);
            line-height: 0;
        }

        /* The bar's dropdown and mega menu are drawn by the raster when shown; once the pointer,
           the focus or the press is gone the panel is held for the 4 frames (`[data-kp-nav-closing]`
           on its item, js/components.js) while the raster erases it, the beam climbing back up.
           The mega menu's item is released when a transition on the panel ends: the hold below is
           that transition. The package's opacity fade is replaced: the screen does not fade. */
        [data-theme='nostromo'] .kp-nav__menu {
            --kp-sig-no-hold: 0;
            transition: --kp-sig-no-hold var(--kp-sig-no-strike) linear;
            animation:
                kp-sig-nostromo-erase var(--kp-sig-no-strike) steps(4, jump-start) forwards,
                kp-sig-nostromo-beam-layer-erase var(--kp-sig-no-strike) steps(4, jump-start) forwards;
        }

        [data-theme='nostromo']
            .kp-nav__links
            > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open])
            > .kp-nav__menu:not(.kp-nav__menu--wide) {
            display: block;
            opacity: 1;
        }

        [data-theme='nostromo']
            :is(
                .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
            ) {
            --kp-sig-no-hold: 1;
            animation:
                kp-sig-nostromo-raster var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards,
                kp-sig-nostromo-beam-layer var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards;
        }
    }

    @container kp-nav (max-width: 40rem) {
        /* Collapsed, the lists nested in the open phone panel are its own rows: they are not drawn again. */
        [data-theme='nostromo'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__links .kp-nav__menu {
            animation: none;
            transition: none;
        }

        /* The phone panel is drawn by the raster; closing, it is held (`[data-kp-nav-closing]`, for
           `--kp-nav-close-time`) while the raster erases it. */
        @media (prefers-reduced-motion: no-preference) {
            [data-theme='nostromo'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
                animation:
                    kp-sig-nostromo-raster var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards,
                    kp-sig-nostromo-beam-layer var(--kp-sig-dur) steps(var(--kp-sig-no-n), end) backwards;
            }

            [data-theme='nostromo'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-closing] > .kp-nav__links {
                animation:
                    kp-sig-nostromo-erase var(--kp-sig-no-strike) steps(4, jump-start) forwards,
                    kp-sig-nostromo-beam-layer-erase var(--kp-sig-no-strike) steps(4, jump-start) forwards;
            }
        }
    }
}
/* ── End of the signature ── */

/* The hold a bar's panel keeps while the raster erases it: js/components.js releases the mega menu's
   item when a transition on the panel ends, and this is the one it waits for. At the top level:
   Firefox does not register an @property inside a layer. */
@property --kp-sig-no-hold {
    syntax: '<number>';
    inherits: false;
    initial-value: 0;
}

/* ── Segmented control, list toolbar, key line [kpadopt-controls] ── */
@layer kp.signature {
    [data-theme='nostromo'] .kp-segmented {
        --kp-seg-radius: var(--kp-sig-no-key, 0.3rem);
        --kp-seg-font: var(--theme-font-mono);
        --kp-seg-size: 0.75rem;
        --kp-seg-tracking: 0.12em;
        --kp-seg-case: uppercase;
        --kp-seg-track: var(--secondary);
        --kp-seg-thumb: repeating-linear-gradient(0deg, hsl(from var(--primary-foreground) h s l / 0.1) 0 1px, transparent 1px 3px), var(--primary);
        --kp-seg-thumb-ink: var(--primary-foreground);
        --kp-seg-thumb-edge: 0 0 0 0 transparent;
        --kp-seg-thumb-lift: inset 0 0 0 1px hsl(from var(--primary-foreground) h s l / 0.25);
        --kp-chip-radius: var(--kp-sig-no-key, 0.3rem);
        --kp-chip-on: var(--primary);
        --kp-chip-on-ink: var(--primary-foreground);
    }
    [data-theme='nostromo'] .kp-toolbar {
        --kp-toolbar-group-gap: 1.125rem;
    }
    [data-theme='nostromo'] .kp-toolbar__label {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.18em;
    }
    [data-theme='nostromo'] .kp-keys {
        font-family: var(--theme-font-mono);
        text-transform: uppercase;
        letter-spacing: 0.08em;
    }
    [data-theme='nostromo'] .kp-kbd {
        --kp-kbd-radius: var(--kp-sig-no-key, 0.3rem);
        --kp-kbd-ground: var(--secondary);
        --kp-kbd-foot: 3px;
        font-family: var(--theme-font-mono);
        text-transform: uppercase;
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — nostromo: a ship's console. Every tab is a key with its lamp: dark when idle, lit amber when current; a press pushes the key in; the label is tape capitals; a count is a lamp-lit plate (G6, G8, G14, G15). */
    [data-theme='nostromo'] .kp-tabbar {
        gap: 0.25rem;
        border-block-start-color: var(--border-strong);
    }

    [data-theme='nostromo'] .kp-tabbar__tab {
        border: 1px solid var(--border-strong);
        border-radius: calc(var(--radius) / 2);
        background: var(--muted);
        letter-spacing: 0.1em;
        text-transform: uppercase;
        box-shadow: inset 0 1px 0 hsl(from var(--background) h s l / 0.7);
    }

    [data-theme='nostromo'] .kp-tabbar__tab::before {
        inset: 0.25rem auto auto calc(50% - 0.2rem);
        inline-size: 0.4rem;
        block-size: 0.4rem;
        border-radius: 50%;
        background: var(--border-strong);
        scale: 1 1;
    }

    [data-theme='nostromo'] .kp-tabbar__tab[aria-current]:not([aria-current='false'])::before {
        background: var(--accent);
        box-shadow: 0 0 7px 1px hsl(from var(--accent) h s l / 0.8);
    }

    [data-theme='nostromo'] .kp-tabbar__tab {
        padding-block-start: 0.5rem;
    }

    [data-theme='nostromo'] .kp-tabbar__tab:active {
        translate: 0 1px;
        box-shadow: inset 0 2px 3px hsl(from var(--foreground) h s l / 0.35);
    }

    [data-theme='nostromo'] .kp-tabbar__badge {
        border-radius: calc(var(--radius) / 3);
        background: var(--accent);
        color: var(--accent-foreground);
    }

    [data-theme='nostromo'] .kp-tabbar__tab:focus-visible {
        box-shadow:
            inset 0 1px 0 hsl(from var(--background) h s l / 0.7),
            0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring);
    }
}

/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Nostromo's own (themes/nostromo/CHARACTER.md): a tile is a switch on the console, raised beige moulding with its
   lamp before the title (G6, G7, G8): unlit at rest, lit under the hand, full when pressed, the LED with its glow on
   keyboard focus; a press pushes the key into a well and nothing moves (G14); a warning sounds the klaxon, the carrier
   framed all round in the tone (G13); label tape names, Michroma counts (G15); waiting is the lamp bank computing, the
   LED window's unordered patterns on the frame clock (G10): a heat grid's row of cells is one LED window, a count one
   short window, never a clipped word in every cell; a running run is that window lit along it. */
@layer kp.signature {
    [data-theme='nostromo'] {
        --kp-no-leds: linear-gradient(
            90deg,
            transparent 0 2.7027%,
            var(--kp-sig-no-led) 0 4.0541%,
            transparent 0 10.8108%,
            var(--kp-sig-no-led) 0 12.1622%,
            transparent 0 13.5135%,
            var(--kp-sig-no-led) 0 14.8649%,
            transparent 0 24.3243%,
            var(--kp-sig-no-led) 0 25.6757%,
            transparent 0 37.8378%,
            var(--kp-sig-no-led) 0 39.1892%,
            transparent 0 45.9459%,
            var(--kp-sig-no-led) 0 47.2973%,
            transparent 0 48.6486%,
            var(--kp-sig-no-led) 0 50%,
            transparent 0 62.1622%,
            var(--kp-sig-no-led) 0 63.5135%,
            transparent 0 72.973%,
            var(--kp-sig-no-led) 0 74.3243%,
            transparent 0 83.7838%,
            var(--kp-sig-no-led) 0 85.1351%,
            transparent 0 91.8919%,
            var(--kp-sig-no-led) 0 93.2432%,
            transparent 0
        );
    }
    [data-theme='nostromo'] .kp-actions {
        --kp-actions-gap: 0.75rem;
    }
    [data-theme='nostromo'] .kp-action {
        --kp-action-radius: var(--radius);
        --kp-action-edge: var(--border-strong);
        --kp-action-edge-hover: var(--border-strong);
        --kp-action-ground-hover: var(--popover);
        --kp-action-ground-active: color-mix(in oklab, var(--secondary) 82%, var(--foreground));
        --kp-action-shadow: var(--kp-sig-no-raised);
        --kp-action-shadow-hover: var(--kp-sig-no-raised);
        --kp-action-shadow-active: var(--kp-sig-no-well);
        --kp-action-press: 0 0;
        --kp-action-title-font: var(--theme-font-display);
        --kp-action-title-size: 0.8125rem;
        --kp-action-title-tracking: 0.04em;
        --kp-action-title-case: uppercase;
    }
    /* The lamp before the title: unlit (25 %), lit under the hand (70 %), full when pressed. */
    [data-theme='nostromo'] .kp-action__title::before {
        content: '';
        display: inline-block;
        inline-size: 0.45rem;
        block-size: 0.45rem;
        margin-inline-end: 0.5rem;
        border-radius: 50%;
        background: currentcolor;
        opacity: 0.25;
        vertical-align: 0.08em;
    }
    [data-theme='nostromo'] .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) .kp-action__title::before {
        opacity: 0.7;
    }
    [data-theme='nostromo'] .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) .kp-action__title::before {
        opacity: 1;
    }
    [data-theme='nostromo'] .kp-action:focus-visible {
        outline: none;
        box-shadow:
            0 0 0 2px var(--background),
            0 0 0 4px var(--foreground),
            var(--kp-sig-no-raised);
    }
    [data-theme='nostromo'] .kp-action:focus-visible .kp-action__title::before {
        background: var(--kp-sig-no-lens);
        box-shadow:
            0 0 0 1px var(--foreground),
            0 0 6px 1px hsl(from var(--kp-sig-no-led) h s l / 0.6);
        opacity: 1;
    }
    [data-theme='nostromo'] .kp-action__meta {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-action:is(:disabled, [aria-disabled='true']) {
        box-shadow: none;
    }
    /* Destructive: the klaxon, the plate framed all round, 3 px, in the red; its lamp in the red. */
    [data-theme='nostromo'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) {
        --kp-action-tone-edge: var(--destructive);
        --kp-action-tone-edge-hover: var(--destructive);
        --kp-action-line: 3px;
    }
    [data-theme='nostromo'] .kp-action--destructive::after {
        display: none;
    }
    [data-theme='nostromo'] .kp-action--destructive > .kp-action__title::before {
        color: var(--destructive);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='nostromo'] .kp-action__title::before {
            transition:
                opacity var(--fx-duration) steps(2, jump-end),
                background var(--fx-duration) steps(2, jump-end),
                box-shadow var(--fx-duration) steps(2, jump-end);
        }
    }

    /* Status rows: raised moulding with the key's corner, a lamp's mark; the detail on label tape. A failed row sounds
       the klaxon, framed all round in the red; a loading row carries the lamp bank computing along its foot. */
    [data-theme='nostromo'] .kp-statuslist {
        --kp-statusrow-mark-radius: 50%;
        --kp-statuslist-gap: 0.625rem;
    }
    [data-theme='nostromo'] .kp-statusrow {
        --kp-statusrow-edge: var(--border-strong);
        --kp-statusrow-radius: var(--kp-sig-no-key);
        position: relative;
        box-shadow: var(--kp-sig-no-raised);
    }
    [data-theme='nostromo'] .kp-statusrow[data-state='failed'] {
        --kp-statusrow-state-edge: var(--destructive);
        --kp-statusrow-line: 3px;
    }
    [data-theme='nostromo'] .kp-statusrow[data-state='empty'] {
        border-style: dashed;
        box-shadow: none;
    }
    [data-theme='nostromo'] .kp-statusrow__detail {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.06em;
        text-transform: uppercase;
        font-size: 0.6875rem;
    }
    [data-theme='nostromo'] .kp-statusrow[data-state='loading']::after,
    [data-theme='nostromo'] .kp-facets[aria-busy='true'] .kp-facet__count,
    [data-theme='nostromo'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton) {
        --kp-no-pitch: 5px;
        border-radius: 2px;
        background:
            var(--kp-no-leds) 0 50% / calc(var(--kp-no-pitch) * 37) calc(100% - 4px) repeat-x,
            linear-gradient(90deg, var(--sidebar-accent) 0 3px, transparent 0) 0 50% / var(--kp-no-pitch) calc(100% - 4px) repeat-x,
            var(--sidebar-background);
        box-shadow: inset 0 0 0 1px var(--border-strong);
    }
    [data-theme='nostromo'] .kp-statusrow[data-state='loading']::after {
        content: '';
        position: absolute;
        inset: auto 0.75rem 0.3rem calc(0.75rem + var(--kp-statusrow-mark, 1.25rem) + 0.625rem);
        block-size: 0.5rem;
        pointer-events: none;
    }
    [data-theme='nostromo'] .kp-facets[aria-busy='true'] .kp-facet__count {
        color: transparent;
        animation: none;
        filter: drop-shadow(0 0 2px hsl(from var(--sidebar-primary) h s l / 0.5));
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='nostromo'] .kp-statusrow[data-state='loading']::after,
        [data-theme='nostromo'] .kp-facets[aria-busy='true'] .kp-facet__count,
        [data-theme='nostromo'] .kp-heat__cells:has(> .kp-heat__cell.kp-skeleton) {
            animation: kp-sig-nostromo-bank var(--kp-sig-no-loop) steps(1, end) infinite;
        }
        [data-theme='nostromo'] .kp-facets[aria-busy='true'] li:nth-child(2n) .kp-facet__count,
        [data-theme='nostromo'] .kp-heat__row:nth-child(2n) .kp-heat__cells {
            animation-delay: calc(var(--kp-sig-no-loop) / -2.5);
        }
    }

    /* Facets: rows of keys with a lamp's wash under the hand; counts on label tape. */
    [data-theme='nostromo'] .kp-facets {
        --kp-facet-radius: var(--kp-sig-no-key);
    }
    [data-theme='nostromo'] .kp-facet {
        --kp-facet-hover: var(--popover);
    }
    [data-theme='nostromo'] :is(.kp-facet__count, .kp-facets__title) {
        font-family: var(--theme-font-mono);
    }
    [data-theme='nostromo'] .kp-facets__title {
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }

    /* Heat grid and matrix: vents lit from behind, a dark slot per cell with the tone as the light inside it; nothing
       scales; pointing lights the slot's rim; the pick is the LED tab under its night. Waiting: each row of cells is one
       LED window computing, the matrix's cells small screens. */
    [data-theme='nostromo'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-radius: 2px;
        --kp-heat-cell-gap: 3px;
        --kp-heat-cell-hover: none;
        --kp-matrix-cell-hover: none;
    }
    [data-theme='nostromo'] .kp-heat {
        --kp-heat-gap-y: 6px;
    }
    [data-theme='nostromo'] .kp-matrix {
        --kp-matrix-gap: 4px;
    }
    [data-theme='nostromo']
        .kp-heat__cell:is([data-kp-tone='ok'], [data-kp-tone='warn'], [data-kp-tone='bad'], [data-kp-tone='level']):not([data-kp-share]),
    [data-theme='nostromo'] .kp-heat__swatch:is([data-kp-tone='ok'], [data-kp-tone='warn'], [data-kp-tone='bad'], [data-kp-tone='level']) {
        background-image: radial-gradient(ellipse at 50% 50%, hsl(from var(--background) h s 100% / 0.28), transparent 70%), var(--kp-heat-pattern);
        box-shadow:
            inset 0 0 0 1px hsl(from var(--background) h s 0% / 0.6),
            0 0 4px hsl(from var(--kp-heat-fill) h s l / 0.6);
    }
    [data-theme='nostromo'] .kp-heat__cell:hover:not(.kp-skeleton, [aria-disabled='true']),
    [data-theme='nostromo'] .kp-matrix__cell:hover:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
        box-shadow:
            inset 0 0 0 1px var(--foreground),
            0 0 6px hsl(from var(--kp-sig-no-led) h s l / 0.6);
    }
    [data-theme='nostromo'] .kp-heat__cell[data-kp-picked],
    [data-theme='nostromo'] .kp-matrix__cell[aria-pressed='true'] {
        outline: 2px solid var(--foreground);
        outline-offset: 1px;
        box-shadow: 0 4px 0 -1px var(--kp-sig-no-led);
    }
    [data-theme='nostromo'] :is(.kp-heat__label, .kp-matrix__name, .kp-heat__col, .kp-matrix__corner) {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.06em;
        text-transform: uppercase;
        font-size: var(--kp-text-xs, 0.75rem);
    }
    [data-theme='nostromo'] :is(.kp-heat__label-button, .kp-matrix__name) {
        border-radius: var(--kp-sig-no-key);
    }
    [data-theme='nostromo'] .kp-heat__label-button[aria-pressed='true'] {
        background: color-mix(in oklab, var(--secondary) 82%, var(--foreground));
        box-shadow: var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-heat__cell.kp-skeleton {
        visibility: hidden;
    }
    [data-theme='nostromo'] .kp-bar-cell {
        --kp-bar-cell-gap: var(--kp-space-sm, 0.5rem);
        font-family: var(--theme-font-mono);
        font-variant-numeric: tabular-nums;
    }

    /* Week agenda and run timeline: label tape, mono capitals on a hairline frame with 2 px corners; pointing lights a
       pill's rim; the next run has the lit LED; the line for now is the LED orange. A running run is the LED window
       computing along its length. */
    [data-theme='nostromo'] .kp-week {
        --kp-week-pill-radius: var(--kp-sig-no-tape);
        --kp-week-now: var(--kp-sig-no-led);
    }
    [data-theme='nostromo'] .kp-gantt {
        --kp-gantt-bar-radius: var(--kp-sig-no-tape);
        --kp-gantt-now: var(--kp-sig-no-led);
        --kp-gantt-state-ground: var(--card);
    }
    [data-theme='nostromo'] :is(.kp-week__pill, .kp-gantt__run) {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.04em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-week__pill {
        border-color: var(--border-strong);
    }
    [data-theme='nostromo'] .kp-week__pill:is(button):hover,
    [data-theme='nostromo'] .kp-gantt__run:is(button):hover {
        box-shadow:
            inset 0 0 0 1px var(--foreground),
            0 0 5px hsl(from var(--kp-sig-no-led) h s l / 0.5);
    }
    [data-theme='nostromo'] .kp-week__pill[data-kp-state='next'] {
        box-shadow: 0 0 0 2px var(--foreground);
    }
    [data-theme='nostromo'] .kp-week__pill[data-kp-state='next'] .kp-week__time::before {
        content: '';
        display: inline-block;
        inline-size: 0.4rem;
        block-size: 0.4rem;
        margin-inline-end: 0.3rem;
        border-radius: 50%;
        background: var(--kp-sig-no-lens);
        box-shadow: 0 0 4px hsl(from var(--kp-sig-no-led) h s l / 0.7);
        vertical-align: 0.06em;
    }
    [data-theme='nostromo'] :is(.kp-week__head, .kp-gantt__tick) {
        font-family: var(--theme-font-mono);
    }
    [data-theme='nostromo'] :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='running'] {
        --kp-no-pitch: 5px;
        border-color: var(--border-strong);
        color: var(--sidebar-primary);
        background:
            var(--kp-no-leds) 0 50% / calc(var(--kp-no-pitch) * 37) calc(100% - 6px) repeat-x,
            linear-gradient(90deg, var(--sidebar-accent) 0 3px, transparent 0) 0 50% / var(--kp-no-pitch) calc(100% - 6px) repeat-x,
            var(--sidebar-background);
        box-shadow: none;
    }
    [data-theme='nostromo'] .kp-gantt__run[data-kp-state='running'] .kp-gantt__label {
        display: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='nostromo'] .kp-gantt__run[data-kp-state='running'] {
            animation: kp-sig-nostromo-bank var(--kp-sig-no-loop) steps(1, end) infinite;
        }
    }

    /* In a narrow agenda the range's title stays on one line in Michroma's wide letters; a phone's timeline keeps its
       toolbar on one row. */
    @container kp-week (max-width: 30rem) {
        [data-theme='nostromo'] .kp-week__title {
            font-size: 0.9375rem;
            white-space: nowrap;
        }
    }
    @container kp-gantt (max-width: 22rem) {
        [data-theme='nostromo'] .kp-gantt__ranges {
            --kp-seg-item-pad-inline: 0.5rem;
        }
    }

    /* The lamp bank: a new pattern every 4 frames, five unordered shifts in the loop, so no lamp walks. */
    @keyframes kp-sig-nostromo-bank {
        0% {
            background-position-x: 0, 0, 0;
        }

        20% {
            background-position-x: calc(var(--kp-no-pitch) * 14), 0, 0;
        }

        40% {
            background-position-x: calc(var(--kp-no-pitch) * 5), 0, 0;
        }

        60% {
            background-position-x: calc(var(--kp-no-pitch) * 25), 0, 0;
        }

        80%,
        100% {
            background-position-x: calc(var(--kp-no-pitch) * 11), 0, 0;
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='nostromo'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='nostromo'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='nostromo'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='nostromo'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='nostromo'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='nostromo'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Nostromo's own (themes/nostromo/CHARACTER.md): the separator is a panel seam, a dark joint with its
   light lip and one unlit lamp at its middle; lying down across the phone's list it is the same seam. A day on the axis
   lights its rim in the LED orange under the pointer; pressed it is a key sunk in its well, its lamp lit under the
   date. The upcoming list names today in the LED orange; the facet pattern is a key in its well. */
@layer kp.signature {
    [data-theme='nostromo'] .kp-nav__sep {
        position: relative;
        inline-size: 2px;
        border-inline-start: 0;
        background: linear-gradient(
            90deg,
            hsl(from var(--background) h s l / 0.35) 0 1px,
            color-mix(in oklab, currentColor 45%, transparent) 1px 2px
        );
    }
    [data-theme='nostromo'] .kp-nav__sep::after {
        content: '';
        position: absolute;
        inset-block-start: calc(50% - 2.5px);
        inset-inline-start: -1.5px;
        inline-size: 5px;
        block-size: 5px;
        border-radius: 50%;
        background: hsl(from var(--kp-sig-no-led, var(--primary)) h s l / 0.6);
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='nostromo'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            inline-size: auto;
            block-size: 2px;
            border-block-start: 0;
            background: linear-gradient(
                to bottom,
                hsl(from var(--background) h s l / 0.35) 0 1px,
                color-mix(in oklab, currentColor 45%, transparent) 1px 2px
            );
        }
        [data-theme='nostromo'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep::after {
            inset-block-start: -1.5px;
            inset-inline-start: calc(50% - 2.5px);
        }
    }

    [data-theme='nostromo'] .kp-gantt__tick:is(button) {
        border-radius: var(--kp-sig-no-key, 0.3rem);
        text-decoration: none;
    }
    [data-theme='nostromo'] .kp-gantt__tick:is(button):hover {
        color: var(--foreground);
        box-shadow: inset 0 -2px 0 var(--kp-sig-no-led, var(--primary));
    }
    [data-theme='nostromo'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background:
            radial-gradient(circle at 50% calc(100% - 3px), var(--kp-sig-no-led, var(--primary)) 0 1.5px, transparent 2px),
            hsl(from var(--foreground) h s l / 0.08);
        color: var(--foreground);
        box-shadow: var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-week__next[data-kp-today] > .kp-week__head > .kp-week__today {
        color: var(--kp-sig-no-led, var(--primary));
    }
    [data-theme='nostromo'] .kp-week__next:not(:has(+ .kp-week__next:not([data-kp-day-start]))) {
        border-block-end-color: var(--border-strong);
    }
    [data-theme='nostromo'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: var(--kp-sig-no-key, 0.3rem);
        box-shadow: var(--kp-sig-no-well);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='nostromo'] .kp-gantt__tick:is(button) {
            transition: box-shadow var(--fx-duration) steps(2, end);
        }
    }
}

/* ── The kpadopt4 components in nostromo's grammar: data pieces, empty-state drawings [kpadopt4] ──
   Nostromo's own (themes/nostromo/CHARACTER.md): the case is what you touch and the screen is what the ship reports
   (G7). A mark is a label plate (tape, 2 px, G6) with a lamp-lit pattern when it is a picture; a share bar is a lit
   window, its parts lit lenses and the free rest the unlit cells (G10's window); labels are tape, counts Michroma
   (G15); a changed reading lights its lamp (G9); a failed carrier sounds the klaxon (G13); a block of code or a command
   is a screen: amber phosphor on dark glass under scanlines, set in the plate's bezel (G7). Every drawing in an empty
   state is a vector written on such a screen, the raster's order, frame by frame (G2, G4). */
@layer kp.signature {
    [data-theme='nostromo'] {
        /* A counted figure is printed in 8 frames (G4). */
        --kp-tick: 640;
        --kp-glyph-changed: '';
        /* The vent seam under a ruled row: a line of dots, as the dividers' perforation. */
        --kp-no-seam: radial-gradient(circle, var(--border-strong) 1px, transparent 1.4px) 0 100% / 10px 3px repeat-x;
        /* A glass set into a plate: its own bezel in the case's moulding (G7). */
        --kp-no-bezel:
            0 0 0 2px var(--secondary), 0 0 0 3px var(--border-strong), inset 0 0 12px hsl(from var(--sidebar-background) h s calc(l - 10) / 0.95);
        --kp-no-phosphor: var(--sidebar-primary);
        --kp-no-cream: var(--sidebar-foreground);
        --kp-no-dim: hsl(from var(--sidebar-foreground) h s l / 0.55);
        --kp-no-glow: 0 0 4px hsl(from var(--sidebar-primary) h s l / 0.5);
    }

    /* ── The identity mark: a label plate; a pattern is a lit picture on a small screen ── */
    [data-theme='nostromo'] .kp-idmark {
        --kp-idmark-radius: var(--kp-sig-no-tape);
        box-shadow: var(--kp-sig-no-raised);
        font-family: var(--theme-font-mono);
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-idmark--xs {
        box-shadow: none;
    }
    [data-theme='nostromo'] .kp-idmark--round {
        border-radius: 50%;
    }
    [data-theme='nostromo'] .kp-idmark--pattern {
        --kp-idmark-ink: hsl(from var(--kp-idmark-c) h s calc(l + 24));
        border: 1px solid var(--secondary);
        background: var(--kp-sig-no-scan), var(--sidebar-background);
        box-shadow:
            0 0 0 1px var(--border-strong),
            inset 0 0 6px hsl(from var(--sidebar-background) h s calc(l - 10) / 0.95);
    }
    [data-theme='nostromo'] .kp-idmark--pattern .kp-idmark__pattern {
        filter: drop-shadow(0 0 1.5px hsl(from var(--kp-idmark-c) h s calc(l + 24) / 0.8));
    }
    /* The corner glyph is a lamp on the plate's corner: it takes the plate's edge, not a paper halo. */
    [data-theme='nostromo'] .kp-idmark--glyph::after {
        box-shadow: 0 0 0 1.5px var(--card);
    }
    [data-theme='nostromo'] .kp-idmark--glyph[data-kp-idmark-glyph='circle']::after {
        background: var(--kp-sig-no-lens);
    }
    [data-theme='nostromo'] .kp-idmark[data-kp-idmark-empty] {
        box-shadow: none;
    }
    /* The current mark is a key pushed in, ringed (G14). */
    [data-theme='nostromo'] .kp-idmark[aria-current]:not([aria-current='false']),
    [data-theme='nostromo'] .kp-idmark[data-kp-idmark-selected] {
        box-shadow:
            var(--kp-sig-no-well),
            0 0 0 2px var(--card),
            0 0 0 4px var(--primary);
    }
    [data-theme='nostromo'] .kp-idmark-group > .kp-idmark,
    [data-theme='nostromo'] .kp-idmark-group > .kp-idmark-group__more {
        box-shadow:
            0 0 0 2px var(--card),
            0 1px 2px hsl(from var(--foreground) h s l / 0.25);
    }
    [data-theme='nostromo'] .kp-idmark-group__more {
        --kp-idmark-radius: var(--kp-sig-no-tape);
        font-family: var(--theme-font-mono);
    }
    /* Loading: a small glass, its lamp computing in the middle; no word in a plate this small. */
    [data-theme='nostromo'] .kp-idmark.kp-skeleton {
        border: 1px solid var(--secondary);
        border-radius: var(--kp-sig-no-tape);
        box-shadow: 0 0 0 1px var(--border-strong);
    }
    [data-theme='nostromo'] .kp-idmark.kp-skeleton::after {
        content: '' / '';
        position: absolute;
        inset: 32%;
        border-radius: 50%;
        background: var(--kp-sig-no-lens);
        box-shadow: 0 0 5px hsl(from var(--kp-sig-no-led) h s l / 0.7);
        filter: none;
        -webkit-mask: none;
        mask: none;
    }

    /* ── The share bar: a lit window ── */
    [data-theme='nostromo'] .kp-stackbar {
        --kp-stackbar-radius: 0.15rem;
        --kp-stackbar-gap: 2px;
        /* The window's bezel stands 3 px past the bar: the room is the grid's gap, never a margin, so a note that keeps the
           bar's and the legend's footprint is exactly as tall. */
        row-gap: 0.5rem;
    }
    [data-theme='nostromo'] .kp-stackbar__title {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-stackbar__total {
        font-family: var(--theme-font-display);
        font-size: 0.75rem;
    }
    /* The window: the free rest is the unlit cells, a part is a run of lit lenses (its hot top, its seam a vent slot). */
    [data-theme='nostromo'] .kp-stackbar__bar {
        background: repeating-linear-gradient(90deg, var(--sidebar-accent) 0 3px, transparent 3px 5px), var(--sidebar-background);
        box-shadow:
            0 0 0 2px var(--secondary),
            0 0 0 3px var(--border-strong);
    }
    [data-theme='nostromo'] .kp-stackbar[aria-busy='true'] .kp-stackbar__bar {
        background: var(--sidebar-background);
    }
    [data-theme='nostromo'] .kp-stackbar__seg {
        box-shadow: inset calc(var(--kp-stackbar-gap, 2px) * -1) 0 0 var(--sidebar-background);
    }
    [data-theme='nostromo'] .kp-stackbar__seg:dir(rtl) {
        box-shadow: inset var(--kp-stackbar-gap, 2px) 0 0 var(--sidebar-background);
    }
    [data-theme='nostromo'] .kp-stackbar__seg::before {
        content: '';
        position: absolute;
        inset: 0 0 65% 0;
        background: hsl(from var(--kp-no-cream) h s 100% / 0.26);
        pointer-events: none;
    }
    [data-theme='nostromo'] .kp-stackbar__seg[data-kp-stackbar-lit] {
        box-shadow:
            inset calc(var(--kp-stackbar-gap, 2px) * -1) 0 0 var(--sidebar-background),
            0 0 0 2px var(--sidebar-background),
            0 0 0 3px var(--sidebar-primary),
            0 0 8px hsl(from var(--sidebar-primary) h s l / 0.6);
    }
    [data-theme='nostromo'] .kp-stackbar__bar[data-kp-stackbar-full] .kp-stackbar__seg:last-of-type {
        box-shadow: none;
    }
    [data-theme='nostromo'] .kp-stackbar__mark {
        background: var(--sidebar-primary);
        box-shadow:
            0 0 0 1px var(--sidebar-background),
            0 0 6px hsl(from var(--sidebar-primary) h s l / 0.7);
    }
    [data-theme='nostromo'] .kp-stackbar__bar[data-kp-over]::after {
        color: hsl(from var(--destructive) h s calc(l + 10));
        text-shadow: 0 0 5px hsl(from var(--destructive) h s l / 0.7);
    }
    [data-theme='nostromo'] .kp-stackbar__swatch {
        inline-size: 0.625rem;
        block-size: 0.625rem;
        border-radius: 50%;
        box-shadow:
            inset 0 1px 0 hsl(from var(--kp-no-cream) h s 100% / 0.45),
            0 0 0 1px var(--foreground);
    }
    [data-theme='nostromo'] .kp-stackbar__item[data-kp-stackbar-rest] .kp-stackbar__swatch {
        background: var(--sidebar-accent);
        box-shadow: 0 0 0 1px var(--foreground);
    }
    [data-theme='nostromo'] .kp-stackbar__item[data-kp-stackbar-lit] {
        background: var(--popover);
        box-shadow: var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-stackbar__value {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
    }
    /* A note in the bar's place is the empty state's plate; a failed read sounds the klaxon (G13). */
    [data-theme='nostromo'] .kp-stackbar__note {
        border-style: solid;
        border-color: var(--border-strong);
        border-radius: var(--kp-sig-no-key);
        background: var(--card);
        box-shadow: var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-stackbar[data-kp-state='error'] .kp-stackbar__note {
        border: 3px solid var(--destructive);
        color: var(--foreground);
    }
    [data-theme='nostromo'] .kp-stackbar__note-title {
        font-family: var(--theme-font-mono);
        font-size: 0.8rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }

    /* ── Bullet rows: the LED meter is the bar; the figure is a Michroma count, a tone a framed tape ── */
    [data-theme='nostromo'] .kp-bullets__figure {
        font-family: var(--theme-font-display);
        font-size: 0.75rem;
        font-weight: 400;
    }
    [data-theme='nostromo'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure,
    [data-theme='nostromo'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        padding-block: 0.1em;
        border-radius: var(--kp-sig-no-tape);
        box-shadow: inset 0 0 0 1px hsl(from var(--background) h s 100% / 0.25);
    }
    [data-theme='nostromo'] .kp-bullets__row {
        border-radius: var(--kp-sig-no-key);
    }
    [data-theme='nostromo'] .kp-bullets__row:has(.kp-bullets__link:hover) {
        background: var(--popover);
        box-shadow: var(--kp-sig-no-raised);
    }
    [data-theme='nostromo'] .kp-bullets__row:has(.kp-bullets__link:active) {
        background: color-mix(in oklab, var(--secondary) 82%, var(--foreground));
        box-shadow: var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-bullets__row:has(.kp-bullets__link:hover) .kp-bullets__label {
        text-decoration-color: var(--selected);
        text-decoration-thickness: 2px;
    }
    [data-theme='nostromo'] .kp-bullets__row:has(.kp-bullets__link:focus-visible) {
        box-shadow:
            0 0 0 2px var(--background),
            0 0 0 4px var(--foreground);
    }
    [data-theme='nostromo'] .kp-bullets__note-title,
    [data-theme='nostromo'] .kp-stackbar__note-title {
        margin: 0;
    }

    /* ── The key-value grid: labels on tape, a changed value lights its lamp, a failed one sounds the klaxon ── */
    [data-theme='nostromo'] .kp-kv__row > dt {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-kv--lines > .kp-kv__row {
        border-block-end: 0;
        background: var(--kp-no-seam);
    }
    [data-theme='nostromo'] .kp-kv--lines > .kp-kv__row:last-child {
        background: none;
    }
    [data-theme='nostromo'] .kp-kv__row[data-kp-changed] > dt::after {
        content: '';
        display: inline-block;
        inline-size: 0.4rem;
        block-size: 0.4rem;
        margin-inline-start: 0.5rem;
        border-radius: 50%;
        background: var(--kp-sig-no-lens);
        box-shadow: 0 0 4px hsl(from var(--kp-sig-no-led) h s l / 0.7);
        vertical-align: 0.1em;
    }
    [data-theme='nostromo'] .kp-kv__row[data-kp-state='error']::before {
        inline-size: 3px;
    }

    /* ── Form rows: the same tape labels; the changed row's lamp rule in ink, a failed row's klaxon rule ── */
    [data-theme='nostromo'] .kp-formrow__label {
        font-family: var(--theme-font-mono);
        font-size: 0.72rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
        padding-block-start: calc((var(--kp-control-height, 2.25rem) - 1.5em) / 2);
    }
    [data-theme='nostromo'] .kp-formrow__label > small {
        font-size: 0.6875rem;
        letter-spacing: 0.02em;
        text-transform: none;
    }
    [data-theme='nostromo'] .kp-formrows--lines > .kp-formrow {
        border-block-end: 0;
        background: var(--kp-no-seam);
    }
    [data-theme='nostromo'] .kp-formrows--lines > .kp-formrow:last-child {
        background: none;
    }
    [data-theme='nostromo'] .kp-formrow[data-kp-changed]::before,
    [data-theme='nostromo'] .kp-formrow[data-kp-state='error']::before {
        inline-size: 3px;
    }
    [data-theme='nostromo'] .kp-formrow__aside {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.04em;
    }
    [data-theme='nostromo'] .kp-formrow__lock::before {
        border-radius: 2px;
    }

    /* ── Code and commands are screens: amber phosphor on dark glass under scanlines, in the plate's bezel (G7, G15) ── */
    [data-theme='nostromo'] .kp-code,
    [data-theme='nostromo'] .kp-command {
        --kp-code-key: var(--kp-no-phosphor);
        --kp-command-prompt-ink: var(--kp-no-phosphor);
        border-color: var(--border-strong);
        border-radius: var(--radius);
        background: var(--card);
        box-shadow: var(--kp-sig-no-raised);
    }
    [data-theme='nostromo'] .kp-code__head,
    [data-theme='nostromo'] .kp-command__head {
        border-block-end: 0;
    }
    [data-theme='nostromo'] .kp-code__title,
    [data-theme='nostromo'] .kp-command__shell {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-code__meta {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }
    /* The glass stands in the plate's bezel: the room round it is the plate's own padding (a margin on a paragraph is
       the page's to reset), so a note and a body are the same height in every state. */
    [data-theme='nostromo'] .kp-code {
        padding: 0 0.5rem 0.5rem;
    }
    [data-theme='nostromo'] :is(.kp-code__head, .kp-code__foot) {
        margin-inline: -0.5rem;
    }
    [data-theme='nostromo'] :is(.kp-code__body, .kp-code__note) {
        margin: 0;
    }
    [data-theme='nostromo'] .kp-command__code {
        margin: 0 0.5rem 0.5rem;
    }
    [data-theme='nostromo'] :is(.kp-code__body, .kp-code__note, .kp-command__code) {
        border-radius: 0.5rem;
        background: var(--kp-sig-no-scan), var(--sidebar-background);
        box-shadow: var(--kp-no-bezel);
        color: var(--kp-no-cream);
        font-family: var(--theme-font-mono);
        text-shadow: var(--kp-no-glow);
    }
    [data-theme='nostromo'] :is(.kp-code__body, .kp-command__code) > code {
        background: none;
        color: var(--kp-no-cream);
    }
    [data-theme='nostromo'] .kp-command__code {
        padding: 0.625rem 0.875rem;
        margin-block-start: 0;
    }
    [data-theme='nostromo'] .kp-code__punct,
    [data-theme='nostromo'] .kp-code[data-kp-code-lines] .kp-code__line::before {
        color: var(--kp-no-dim);
    }
    [data-theme='nostromo'] .kp-code__note {
        color: var(--kp-no-dim);
    }
    [data-theme='nostromo'] .kp-code[data-kp-state='error'] .kp-code__note {
        color: hsl(from var(--destructive) h s calc(l + 24));
    }
    [data-theme='nostromo'] .kp-code[data-kp-state='error'] {
        box-shadow:
            var(--kp-sig-no-raised),
            inset 0 0 0 3px var(--destructive);
    }
    [data-theme='nostromo'] .kp-code__foot {
        border-block-start: 0;
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.04em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-command__where {
        border-block-start: 0;
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.04em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-command:not([data-kp-command-ready])::before {
        border-block-end: 0;
    }
    [data-theme='nostromo'] .kp-code[data-kp-code-folded] .kp-code__body {
        mask-image: linear-gradient(to bottom, black calc(100% - 2.5em), transparent);
    }

    /* ── The page header's line: its freshness reads as tape ── */
    [data-theme='nostromo'] .kp-page-header__line .kp-ago {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    /* ── Drawings in an empty state: a vector written on an amber screen [js/art.js, set "nostromo"] ── */
    [data-theme='nostromo'] [data-kp-art]::before {
        content: none;
    }
    [data-theme='nostromo'] [data-kp-art] {
        padding-block-start: 1.25rem;
    }
    [data-theme='nostromo'] [data-kp-art] > .kp-button {
        margin-block-start: 0.875rem;
    }
    [data-theme='nostromo'] .kp-art {
        --kp-art-stroke: 1.5px;
        --kp-art-rule: var(--kp-no-phosphor);
        --kp-art-line: hsl(from var(--sidebar-primary) h s l / 0.42);
        --kp-art-ink: var(--kp-no-cream);
        --kp-art-red: hsl(from var(--destructive) h s calc(l + 22));
        display: block;
        box-sizing: content-box;
        margin: 0 auto 0.875rem;
        padding: 0.5rem 0.75rem;
        border-radius: 0.5rem;
        background: var(--kp-sig-no-scan), var(--sidebar-background);
        box-shadow: var(--kp-no-bezel);
        filter: drop-shadow(0 1px 0 hsl(from var(--card) h s calc(l + 8) / 0.9));
    }
    [data-theme='nostromo'] .kp-art > g[data-kp-art-set='nostromo'] {
        display: inline;
    }
    [data-theme='nostromo'] .kp-art path {
        stroke-linecap: round;
        stroke-linejoin: round;
    }
    [data-theme='nostromo'] .kp-art path:is(.kp-art__rule, .kp-art__red) {
        filter: drop-shadow(0 0 2px currentColor);
    }
    [data-theme='nostromo'] .kp-art__rule {
        color: var(--kp-no-phosphor);
    }
    [data-theme='nostromo'] .kp-art__red {
        color: var(--kp-art-red);
    }
    @media (prefers-reduced-motion: no-preference) {
        /* The screen is struck on (the raster), then every stroke is written, a frame apart, in 4 frames each. */
        [data-theme='nostromo'] .kp-art {
            --kp-sig-no-n: 4;
            animation: kp-sig-nostromo-raster var(--kp-sig-no-strike) steps(4, end) backwards;
        }
        [data-theme='nostromo'] .kp-art path {
            stroke-dasharray: 1;
            animation: kp-sig-nostromo-art-write var(--kp-sig-no-strike) steps(4, end) both;
            animation-delay: calc(var(--kp-sig-no-strike) + var(--kp-art-i, 0) * var(--kp-sig-no-frame));
        }
    }
    @keyframes kp-sig-nostromo-art-write {
        from {
            stroke-dashoffset: 1;
        }
        to {
            stroke-dashoffset: 0;
        }
    }
}

/* ── The kpadopt4 components in nostromo's grammar: rows, tiles, check lists, card states [kpadopt4] ──
   A row of a list is a line on the console's log: its state is a lit bar along the start edge, and a row that warns or
   fails sounds the klaxon, framed all round, 3 px, in the tone (G13); a payload a row folds away is the ship's printout
   on its small screen (G7). A tile of choices is a moulded key: raised at rest, lit rim under the hand, sunk in its well
   when it is ticked (G8, G14); its title is label tape. A fix written out for a check is a readout on a screen. */
@layer kp.signature {
    [data-theme='nostromo'] .kp-action-list--lead > li {
        border-radius: var(--kp-sig-no-key);
    }
    [data-theme='nostromo'] .kp-action-list--lead > li:is([data-kp-state='warn'], [data-kp-state='failed']) {
        box-shadow: inset 0 0 0 3px var(--kp-no-tone);
    }
    [data-theme='nostromo'] .kp-action-list--lead > li[data-kp-state='warn'] {
        --kp-no-tone: var(--warning);
    }
    [data-theme='nostromo'] .kp-action-list--lead > li[data-kp-state='failed'] {
        --kp-no-tone: var(--destructive);
    }
    [data-theme='nostromo'] .kp-action-list--lead > li[data-kp-state='next'] {
        box-shadow: var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-action-list__title {
        font-size: 0.9375rem;
    }
    [data-theme='nostromo'] .kp-action-list__when {
        line-height: 1.45;
    }
    [data-theme='nostromo'] .kp-action-list__when > :first-child {
        font-family: var(--theme-font-mono);
        font-size: 0.8125rem;
        letter-spacing: 0.04em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-action-list > li.kp-action-list__group {
        padding-block-end: 0.5rem;
        background: var(--kp-no-seam);
        font-family: var(--theme-font-mono);
        letter-spacing: 0.12em;
    }
    [data-theme='nostromo'] .kp-action-list__more > summary {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-action-list__payload {
        border: 0;
        border-radius: 0.5rem;
        background: var(--kp-sig-no-scan), var(--sidebar-background);
        box-shadow: var(--kp-no-bezel);
        color: var(--kp-no-cream);
        font-family: var(--theme-font-mono);
        text-shadow: var(--kp-no-glow);
        margin: 0.5rem 0.25rem 0.25rem;
    }

    /* A check that warns: the klaxon, as a failed row's, in the warning ink. */
    [data-theme='nostromo'] .kp-statusrow[data-state='warn'] {
        --kp-statusrow-state-edge: var(--warning);
        --kp-statusrow-line: 3px;
    }
    [data-theme='nostromo'] .kp-statusrow__fix {
        box-sizing: border-box;
        inline-size: fit-content;
        max-inline-size: 100%;
        padding: 0.3rem 0.6rem;
        border-radius: var(--kp-sig-no-key);
        background: var(--kp-sig-no-scan), var(--sidebar-background);
        box-shadow: 0 0 0 1px var(--border-strong);
        color: var(--kp-no-cream);
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        text-shadow: var(--kp-no-glow);
    }
    [data-theme='nostromo'] .kp-statusrow__fix::before {
        content: '> ' / '';
        color: var(--kp-no-phosphor);
    }

    /* Choices as tiles: moulded keys; the ticked one is sunk in its well with its rim lit in ink. */
    [data-theme='nostromo'] .kp-fieldset[data-kp-layout='tiles'] {
        --kp-field-tile-radius: var(--kp-sig-no-key);
        --kp-field-tile-ground: var(--card);
        --kp-field-tile-ground-checked: color-mix(in oklab, var(--secondary) 82%, var(--foreground));
        --kp-field-tile-edge-checked: var(--foreground);
    }
    [data-theme='nostromo'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
        border-color: var(--border-strong);
        box-shadow: var(--kp-sig-no-raised);
    }
    [data-theme='nostromo'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:hover:not(:has(> .kp-field__check:disabled)) {
        border-color: var(--foreground);
        background: var(--popover);
    }
    [data-theme='nostromo'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:active:not(:has(> .kp-field__check:disabled)) {
        background: color-mix(in oklab, var(--secondary) 82%, var(--foreground));
        box-shadow: var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:checked) {
        box-shadow:
            var(--kp-sig-no-well),
            inset 0 0 0 1px var(--foreground);
    }
    [data-theme='nostromo'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:focus-visible) {
        outline: 0;
        box-shadow:
            0 0 0 2px var(--background),
            0 0 0 4px var(--foreground),
            var(--kp-sig-no-raised);
    }
    [data-theme='nostromo'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:disabled) {
        box-shadow: none;
    }
    [data-theme='nostromo'] .kp-field__option-title {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }
    /* A tiles group with nothing chosen sounds the klaxon round the whole group (G13). */
    [data-theme='nostromo'] .kp-fieldset[data-kp-layout='tiles'][aria-invalid='true'] {
        outline-width: 3px;
    }

    /* A card in four data states: the stage is a bay; its note and its failure keep the empty state's and alert's plates. */
    [data-theme='nostromo'] .kp-card__state-title {
        font-family: var(--theme-font-mono);
        font-size: clamp(1rem, 0.9rem + 0.4vw, 1.25rem);
        letter-spacing: 0.08em;
        line-height: 1.3;
        text-transform: uppercase;
    }
    /* The klaxon plate is solid red: its title keeps the plate's own ink, not the page's (dark on red was unreadable). */
    [data-theme='nostromo'] .kp-alert--destructive .kp-card__state-title {
        color: inherit;
    }
    [data-theme='nostromo'] .kp-card__state > .kp-card__empty {
        border-radius: var(--kp-sig-no-key);
    }
}

/* ── The kpadopt4 components in nostromo's grammar: pipeline, journey, moments, secret, dialog sections [kpadopt4] ──
   The pipeline is a rack: a lane a moulded plate, its head label tape with the stage's lit strip, a card a key with its
   lamp (G8): unlit at rest, lit under the hand, full when pressed, the LED orange on the open one; the board's words
   are a plate, a failed read the klaxon (G13). A journey is the LED bargraph laid between its steps: the way travelled
   lit in the step's own colour, the way to come unlit cells, a failed way alternate cells in red; the step it stands at
   is a lamp lit in its key. A moment on the timeline is a lamp, a stretch a run of lit cells (G10's window). The secret
   field is a screen: the value is written on it by the raster (G2) and the countdown is a bargraph that goes out cell by
   cell (G9, G10); a dialog's sections are divided by the vent seam and its danger section is framed all round (G13). */
@layer kp.signature {
    /* ── Pipeline ── */
    [data-theme='nostromo'] .kp-pipeline__lane {
        border-color: var(--border-strong);
        border-radius: var(--radius);
        background: var(--muted);
        box-shadow: var(--kp-sig-no-raised);
    }
    [data-theme='nostromo'] .kp-pipeline__head {
        border: 0;
        border-radius: var(--kp-sig-no-tape);
        background: var(--foreground);
        box-shadow: inset 4px 0 0 var(--kp-pipeline-tone);
        padding-inline-start: calc(var(--kp-space-sm, 0.5rem) + 4px);
        color: var(--primary-foreground);
    }
    [data-theme='nostromo'] .kp-pipeline__head:dir(rtl) {
        box-shadow: inset -4px 0 0 var(--kp-pipeline-tone);
        padding-inline-start: var(--kp-space-sm, 0.5rem);
        padding-inline-end: calc(var(--kp-space-sm, 0.5rem) + 4px);
    }
    [data-theme='nostromo'] .kp-pipeline__name {
        color: inherit;
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-pipeline__count {
        font-family: var(--theme-font-display);
        font-size: 1rem;
        font-weight: 400;
    }
    [data-theme='nostromo'] .kp-pipeline__share {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-pipeline__card {
        position: relative;
        border-color: var(--border-strong);
        border-radius: var(--kp-sig-no-key);
        box-shadow: var(--kp-sig-no-raised);
        padding-inline-end: 1.5rem;
    }
    /* The card's lamp, in its top end corner: unlit 25 %, lit under the hand 70 %, full when pressed (G8). */
    [data-theme='nostromo'] .kp-pipeline__card:not(.kp-pipeline__ghost)::after {
        content: '';
        position: absolute;
        inset-block-start: 0.4rem;
        inset-inline-end: 0.4rem;
        inline-size: 0.4rem;
        block-size: 0.4rem;
        border-radius: 50%;
        background: currentcolor;
        opacity: 0.25;
    }
    [data-theme='nostromo'] .kp-pipeline__card:hover:not(.kp-pipeline__ghost)::after {
        opacity: 0.7;
    }
    [data-theme='nostromo'] .kp-pipeline__card:active:not(.kp-pipeline__ghost)::after {
        opacity: 1;
    }
    [data-theme='nostromo'] .kp-pipeline__card:hover {
        border-color: var(--foreground);
        background: var(--popover);
    }
    [data-theme='nostromo'] .kp-pipeline__card:active {
        background: color-mix(in oklab, var(--secondary) 82%, var(--foreground));
        box-shadow: var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-pipeline__card[aria-current='true'] {
        border-color: var(--foreground);
        box-shadow: var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-pipeline__card[aria-current='true']::after {
        background: var(--kp-sig-no-lens);
        box-shadow: 0 0 5px hsl(from var(--kp-sig-no-led) h s l / 0.7);
        opacity: 1;
    }
    [data-theme='nostromo'] .kp-pipeline__card:focus-visible {
        outline: 0;
        box-shadow:
            0 0 0 2px var(--background),
            0 0 0 4px var(--foreground);
    }
    [data-theme='nostromo'] .kp-pipeline__card[data-kp-dimmed] {
        box-shadow: none;
    }
    [data-theme='nostromo'] .kp-pipeline__card[data-kp-dimmed]::after {
        opacity: 0.12;
    }
    [data-theme='nostromo'] .kp-pipeline__mark {
        border-radius: var(--kp-sig-no-tape);
        font-family: var(--theme-font-mono);
        box-shadow: inset 0 0 0 1px hsl(from var(--foreground) h s l / 0.3);
    }
    [data-theme='nostromo'] .kp-pipeline__meta {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.04em;
    }
    [data-theme='nostromo'] .kp-pipeline__none {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-pipeline__state {
        border-radius: var(--kp-sig-no-key);
        box-shadow: var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-pipeline__state[data-kp-state='error'] {
        border: 3px solid var(--destructive);
    }
    [data-theme='nostromo'] .kp-pipeline__state[data-kp-state='error'] .kp-pipeline__words {
        padding-inline-start: 0;
        border-inline-start: 0;
        text-align: center;
    }

    /* ── Journey: the LED bargraph between the steps ── */
    [data-theme='nostromo'] .kp-steplist--journey {
        --kp-journey-rule: 6px;
        --kp-no-cells: linear-gradient(90deg, var(--foreground) 0 3px, transparent 3px) 0 0 / 5px 100% repeat-x;
        --kp-no-cells-v: linear-gradient(180deg, var(--foreground) 0 3px, transparent 3px) 0 0 / 100% 5px repeat-y;
        --kp-steplist-mark-radius: var(--kp-sig-no-key);
    }
    [data-theme='nostromo'] .kp-steplist--journey > .kp-steplist__item + .kp-steplist__item::before,
    [data-theme='nostromo'] .kp-steplist--journey > .kp-steplist__item:not(:last-child)::after {
        background: var(--sidebar-accent);
        -webkit-mask: var(--kp-no-cells);
        mask: var(--kp-no-cells);
    }
    [data-theme='nostromo'] .kp-steplist--journey > .kp-steplist__item:is([data-state='done'], [data-state='current'])::before {
        background: var(--kp-step-tone, var(--kp-sig-no-led));
    }
    [data-theme='nostromo'] .kp-steplist--journey > .kp-steplist__item[data-state='failed']::before {
        background: repeating-linear-gradient(90deg, var(--destructive) 0 5px, transparent 5px 10px);
    }
    [data-theme='nostromo'] .kp-steplist--journey .kp-steplist__mark {
        box-shadow: var(--kp-sig-no-raised);
    }
    /* The step it stands at: a key sunk in its well with its lamp lit in the step's colour. */
    [data-theme='nostromo'] .kp-steplist--journey .kp-steplist__item[data-state='current'] .kp-steplist__mark {
        border-color: var(--foreground);
        background:
            radial-gradient(
                circle,
                hsl(from var(--kp-step-tone, var(--kp-sig-no-led)) h s calc(l + 22)) 0 18%,
                var(--kp-step-tone, var(--kp-sig-no-led)) 34%,
                transparent 40%
            ),
            var(--secondary);
        box-shadow: var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-steplist--journey .kp-steplist__item[data-state='done']:not([data-kp-tone]) .kp-steplist__mark {
        border-color: var(--foreground);
        background: var(--foreground);
        color: var(--primary-foreground);
    }
    [data-theme='nostromo'] .kp-steplist--journey .kp-steplist__title {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-steplist--journey .kp-steplist__time {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.04em;
    }
    @container kp-journey (max-width: 30rem) {
        [data-theme='nostromo'] .kp-steplist--journey > .kp-steplist__item:not(:last-child)::after {
            -webkit-mask: var(--kp-no-cells-v);
            mask: var(--kp-no-cells-v);
            inline-size: 6px;
        }
        [data-theme='nostromo']
            .kp-steplist--journey
            > .kp-steplist__item:has(+ .kp-steplist__item:is([data-state='done'], [data-state='current']))::after {
            background: var(--kp-step-tone, var(--kp-sig-no-led));
        }
        [data-theme='nostromo'] .kp-steplist--journey > .kp-steplist__item:has(+ .kp-steplist__item[data-state='failed'])::after {
            background: repeating-linear-gradient(180deg, var(--destructive) 0 5px, transparent 5px 10px);
        }
    }

    /* ── Moments on the timeline: lamps; stretches are runs of lit cells ── */
    [data-theme='nostromo'] :is(.kp-gantt__point, .kp-gantt__mark)::before {
        box-shadow: 0 0 4px hsl(from var(--kp-gantt-mark) h s l / 0.6);
    }
    [data-theme='nostromo'] :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-planned]::before,
    [data-theme='nostromo'] :is(.kp-gantt__point, .kp-gantt__mark)[data-kp-shape='ring']::before {
        box-shadow: none;
    }
    [data-theme='nostromo'] .kp-gantt__point:hover::before {
        box-shadow:
            0 0 0 2px var(--card),
            0 0 0 4px var(--foreground),
            0 0 8px hsl(from var(--kp-sig-no-led) h s l / 0.6);
    }
    [data-theme='nostromo'] .kp-gantt__point:active::before {
        box-shadow:
            0 0 0 2px var(--card),
            0 0 0 4px var(--foreground),
            var(--kp-sig-no-well);
    }
    [data-theme='nostromo'] .kp-gantt__count {
        border-radius: var(--kp-sig-no-tape);
        background: var(--foreground);
        border-color: var(--foreground);
        color: var(--primary-foreground);
        font-family: var(--theme-font-mono);
    }
    [data-theme='nostromo'] .kp-gantt__zone[data-kp-lane-zone] {
        border-radius: 1px;
        background: repeating-linear-gradient(90deg, hsl(from var(--kp-gantt-mark) h s l / 0.85) 0 3px, transparent 3px 5px);
    }
    [data-theme='nostromo'] :is(.kp-gantt__zone:not([data-kp-lane-zone]), .kp-gantt__band) {
        border-inline: 0;
        background: repeating-linear-gradient(90deg, hsl(from var(--kp-gantt-mark) h s l / 0.2) 0 3px, transparent 3px 6px);
    }
    [data-theme='nostromo'] .kp-gantt__zone[data-kp-tone='warning']:not([data-kp-lane-zone]) {
        box-shadow: inset 0 3px 0 var(--warning-foreground);
    }
    [data-theme='nostromo'] .kp-gantt__sub {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.04em;
    }

    /* ── Secret field: a screen; the value is written by the raster, the countdown is a bargraph going out ── */
    [data-theme='nostromo'] .kp-secret {
        --kp-secret-drain-size: 6px;
        --kp-secret-drain: var(--kp-sig-no-led);
    }
    [data-theme='nostromo'] .kp-secret__value {
        border: 0;
        border-radius: var(--kp-sig-no-key);
        background: var(--kp-sig-no-scan), var(--sidebar-background);
        box-shadow:
            0 0 0 2px var(--secondary),
            0 0 0 3px var(--border-strong),
            inset 0 0 8px hsl(from var(--sidebar-background) h s calc(l - 10) / 0.95);
        color: var(--kp-no-cream);
        text-shadow: var(--kp-no-glow);
    }
    [data-theme='nostromo'] .kp-secret__value.kp-masked {
        color: var(--kp-no-dim);
    }
    [data-theme='nostromo'] .kp-secret[data-kp-secret-state='disabled'] .kp-secret__value {
        box-shadow: 0 0 0 1px var(--border-strong);
        background: var(--muted);
        color: var(--muted-foreground);
        text-shadow: none;
    }
    [data-theme='nostromo'] .kp-secret__drain {
        background: var(--kp-secret-drain);
        -webkit-mask: linear-gradient(90deg, var(--foreground) 0 3px, transparent 3px) 0 0 / 5px 100% repeat-x;
        mask: linear-gradient(90deg, var(--foreground) 0 3px, transparent 3px) 0 0 / 5px 100% repeat-x;
        filter: drop-shadow(0 0 3px hsl(from var(--sidebar-primary) h s l / 0.55));
    }
    [data-theme='nostromo'] .kp-secret__line {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-secret[data-kp-secret-state='error'] .kp-secret__words {
        padding: 0.15rem 0.5rem;
        border: 3px solid var(--destructive);
        border-radius: var(--kp-sig-no-tape);
        letter-spacing: 0.02em;
        text-transform: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='nostromo']
            .kp-secret:not([data-kp-secret-ttl='0'], [data-kp-secret-reveal-on='hold'])[data-kp-secret-state='shown']
            .kp-secret__drain {
            animation: kp-sig-nostromo-drain var(--kp-secret-ttl, 30s) steps(48, end) forwards;
        }
        [data-theme='nostromo'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__text {
            display: inline-block;
            animation: kp-sig-nostromo-raster var(--kp-sig-no-print) steps(8, end) backwards;
        }
    }
    @keyframes kp-sig-nostromo-drain {
        from {
            clip-path: inset(-6px 0 -6px 0);
        }
        to {
            clip-path: inset(-6px 100% -6px 0);
        }
    }

    /* ── A dialog in sections: the vent seam between them, the danger section framed all round ── */
    [data-theme='nostromo'] .kp-dialog__section {
        border-block-start: 0;
    }
    [data-theme='nostromo'] .kp-dialog__section:not(:first-child) {
        background: var(--kp-no-seam);
        background-position: 0 0;
        background-size: 10px 3px;
        background-repeat: repeat-x;
        padding-block-start: calc(var(--kp-dialog-section-gap, 0.75rem) + 3px);
    }
    [data-theme='nostromo'] .kp-dialog__heading {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-dialog__section--danger {
        margin-block-start: 0.5rem;
        padding: calc(var(--kp-dialog-section-gap, 0.75rem) + 0.125rem) var(--kp-space-md, 0.75rem);
        border: 3px solid var(--destructive);
        border-radius: var(--kp-sig-no-key);
        background: none;
    }
    [data-theme='nostromo'] .kp-dialog__section--danger:first-child {
        margin-block-start: 0;
    }
    [data-theme='nostromo'] .kp-dialog__section--danger:last-child {
        padding-block-end: calc(var(--kp-dialog-section-gap, 0.75rem) + 0.125rem);
    }

    /* What still uses a thing, and what will be lost: a printout on a screen, under its tape heading. */
    [data-theme='nostromo'] .kp-confirm__dependents {
        border: 0;
        border-radius: 0.5rem;
        background: var(--kp-sig-no-scan), var(--sidebar-background);
        box-shadow: var(--kp-no-bezel);
        margin-inline: 0.25rem;
        color: var(--kp-no-cream);
        font-family: var(--theme-font-mono);
        text-shadow: var(--kp-no-glow);
    }
    [data-theme='nostromo'] .kp-confirm__dependents .kp-dialog__heading {
        color: var(--kp-no-phosphor);
    }
    [data-theme='nostromo'] .kp-type-confirm__loses {
        border: 3px solid var(--destructive);
        border-radius: var(--kp-sig-no-key);
        background: var(--card);
    }
    [data-theme='nostromo'] .kp-type-confirm__loses-title {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-type-confirm__name {
        border-radius: var(--kp-sig-no-tape);
        background: var(--foreground);
        color: var(--primary-foreground);
        letter-spacing: 0.04em;
    }
    [data-theme='nostromo'] .kp-type-confirm__status {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }
}

/* ── The kpadopt4 components in nostromo's grammar: time, cooking and comparison [kpadopt4] ──
   Everything that reads a time out is the ship's screen: the digits of a countdown, a timer's remaining time and the
   timer disc are amber phosphor on dark glass in the case's bezel (G7, G15); an ended timer sounds the klaxon, framed
   all round and never flashing (G13); the uptime strip is a lit window whose cells light by state (G10's window); the
   wheel turns in whole frames of the ship's clock and its outcome is written on the screen (G1, G4); a three-way chip
   is a switch with its lamp, lit in ink, in red for out (G8, G13); the quantity's figure is Michroma in its well and
   its unit label tape (G15); a checklist is the log with its dotted seams; cook mode's ingredients are a printout. */
@layer kp.signature {
    [data-theme='nostromo'] {
        /* The wheel's settle: the register's curve held in 45 frames of 80 ms (3.6 s). */
        --kp-wheel-ease: linear(
            0 0% 2.21%,
            0.005 2.22% 4.43%,
            0.022 4.44% 6.66%,
            0.057 6.67% 8.88%,
            0.117 8.89% 11.1%,
            0.2 11.11% 13.32%,
            0.289 13.33% 15.55%,
            0.37 15.56% 17.77%,
