    /* ── Uptime strip: a lit window ── */
    [data-theme='nostromo'] .kp-uptime {
        --kp-uptime-up: hsl(from var(--success) h s calc(l + 22));
        --kp-uptime-degraded: hsl(from var(--warning-foreground) h s calc(l + 16));
        --kp-uptime-down: hsl(from var(--destructive) h s calc(l + 14));
        --kp-uptime-cell-radius: 1px;
        row-gap: 0.5rem;
    }
    [data-theme='nostromo'] .kp-uptime__title {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-uptime__percent {
        font-family: var(--theme-font-display);
        font-size: 0.8125rem;
        font-weight: 400;
    }
    [data-theme='nostromo'] .kp-uptime__summary {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.04em;
    }
    [data-theme='nostromo'] .kp-uptime__summary[data-kp-tone='error'] {
        border-radius: var(--kp-sig-no-tape);
        text-transform: uppercase;
        letter-spacing: 0.06em;
    }
    [data-theme='nostromo'] .kp-uptime__axis {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-uptime__track {
        box-sizing: border-box;
        padding: 2px;
        border-radius: 0.15rem;
        background: var(--sidebar-background);
        box-shadow:
            0 0 0 2px var(--secondary),
            0 0 0 3px var(--border-strong);
    }
    [data-theme='nostromo'] .kp-uptime__cell {
        position: relative;
        border: 0;
    }
    [data-theme='nostromo'] .kp-uptime__cell:not([data-kp-tone]) {
        --kp-uptime-fill: var(--sidebar-accent);
    }
    [data-theme='nostromo'] .kp-uptime__cell:is([data-kp-tone='up'], [data-kp-tone='degraded'], [data-kp-tone='down']) {
        box-shadow: 0 0 4px hsl(from var(--kp-uptime-fill) h s l / 0.55);
    }
    [data-theme='nostromo'] .kp-uptime__cell:is([data-kp-tone='up'], [data-kp-tone='degraded'], [data-kp-tone='down'])::before {
        content: '';
        position: absolute;
        inset: 0 0 62% 0;
        background: hsl(from var(--kp-no-cream) h s 100% / 0.28);
        pointer-events: none;
    }
    [data-theme='nostromo'] .kp-uptime__cell[data-kp-tone='none'] {
        --kp-uptime-fill: transparent;
        box-shadow: inset 0 0 0 1px var(--sidebar-accent);
    }
    [data-theme='nostromo'] .kp-uptime__cell:is(:hover, :focus-visible, [aria-expanded='true']) {
        box-shadow:
            0 0 0 1px var(--sidebar-background),
            0 0 0 2px var(--sidebar-primary),
            0 0 8px hsl(from var(--sidebar-primary) h s l / 0.6);
    }
    [data-theme='nostromo'] .kp-uptime__cell:focus-visible,
    [data-theme='nostromo'] .kp-uptime__cell[aria-expanded='true'] {
        outline: 0;
    }
    [data-theme='nostromo'] .kp-uptime__swatch {
        border: 0;
        border-radius: 1px;
        box-shadow: 0 0 0 1px var(--foreground);
    }
    [data-theme='nostromo'] .kp-uptime__info-title {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }
    [data-theme='nostromo'] .kp-uptime__info-state {
        font-family: var(--theme-font-mono);
        font-size: 0.6875rem;
        letter-spacing: 0.08em;
        text-transform: uppercase;
    }
    /* Waiting: the track is the lamp bank, computing (G10). */
    [data-theme='nostromo'] .kp-uptime__cell.kp-skeleton {
        visibility: hidden;
    }
    [data-theme='nostromo'] .kp-uptime__track:has(> .kp-uptime__cell.kp-skeleton) {
        --kp-no-pitch: 5px;
        background:
            var(--kp-no-leds) 0 50% / calc(var(--kp-no-pitch) * 37) calc(100% - 8px) repeat-x,
            linear-gradient(90deg, var(--sidebar-accent) 0 3px, transparent 0) 0 50% / var(--kp-no-pitch) calc(100% - 8px) repeat-x,
            var(--sidebar-background);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='nostromo'] .kp-uptime__track:has(> .kp-uptime__cell.kp-skeleton) {
            animation: kp-sig-nostromo-bank var(--kp-sig-no-loop) steps(1, end) infinite;
        }
        [data-theme='nostromo'] .kp-uptime__cell {
            transition: block-size var(--fx-duration) steps(2, jump-end);
        }
