    [data-theme='dark'] .kp-spec__swatch {
        border: 1px solid var(--border);
    }

    [data-theme='dark'] .kp-spec__font {
        font-family: var(--theme-font-display);
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation and transition of this register lives here, inside
       the no-preference guard, so a reader who asked for reduced motion
       never receives one: the rest states above are what they get. */
    @media (prefers-reduced-motion: no-preference) {
        /* A headline is laid word by word: the line crosses each word from its
           start edge at one pace, 60 ms after the word before [G2, G19]. */
        [data-theme='dark'] [data-kp-reveal='headline'].is-words [data-word] {
            animation: kp-sig-dark-lay 660ms linear both;
            animation-delay: calc(var(--kp-i, 0) * var(--kp-word-stagger));
        }

        /* The redact bar: a size change, not a colour (KT8: no
           mid-transition colour can be read); the ink turns visible in
           the same instant the bar clears, staggered per redaction. */
        [data-theme='dark'] .kp-card[data-kp-reveal='emphasis'] mark::after {
            transition: transform 380ms var(--fx-ease);
        }

        [data-theme='dark'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(2)::after {
            transition-delay: var(--kp-redact-stagger);
        }

        [data-theme='dark'] .kp-card[data-kp-reveal='emphasis'] mark:nth-of-type(3)::after {
            transition-delay: calc(2 * var(--kp-redact-stagger));
        }

        [data-theme='dark'] .kp-card[data-kp-reveal='emphasis'] mark {
            transition: color 0s linear 0s;
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* Every keyframe here has its row in TIMINGS (js/effects.js). A headline's
       words are laid by the pass (kp-sig-dark-lay, below): a word's box is
       revealed from the start edge at an even pace and stops dead at the end
       (G1); nothing blurs, nothing splits into two wavelengths (G19). */
    /* Scroll-bound, not time-based: the browser scrubs this by the
       heading's own position, not a clock, so it cannot free-run and
       cannot loop — see gates/check-motion.mjs's OUT_OF_SCOPE entry. */
    @keyframes kp-ignite {
        100% {
            color: var(--primary);
            text-decoration-color: var(--border-strong);
        }
    }

    /* The rule draws itself from the leading edge [scope-16]. Scroll-bound
       like the ignite above it: the browser scrubs this by the heading's
       own position, so it cannot free-run and cannot loop. */
    @keyframes kp-draw {
        0% {
            scale: 0 1;
        }

        100% {
            scale: 1 1;
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — the row a step lighter than the page it sits on. */
    [data-theme='dark'] .kp-marquee {
        border-block: 1px solid color-mix(in srgb, var(--foreground) 18%, transparent);
        background: color-mix(in srgb, var(--card) 60%, var(--background));
        --kp-marquee: 50000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='dark'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='dark'] .kp-nav__menu--wide .kp-nav__menu-heading {
        color: var(--primary);
        border-block-end: 1px solid color-mix(in srgb, var(--foreground) 20%, transparent);
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       Quiet, the way this theme is quiet: the row you are on is a raised
       plate rather than a colour, and the accent shows only at its
       leading edge. */
    [data-theme='dark'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
        border-inline-end: 1px solid var(--border);
    }

    [data-theme='dark'] .kp-sidenav__link,
    [data-theme='dark'] .kp-sidenav__category-toggle {
        border-inline-start: 2px solid transparent;
    }

    [data-theme='dark'] .kp-sidenav__link[aria-current='page'] {
        background: var(--accent);
        color: var(--foreground);
        border-inline-start-color: var(--primary);
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       Quiet, like the rest of it. */
    [data-theme='dark'] .kp-to-top {
        border: 1px solid var(--border);
    }

    [data-theme='dark'] .kp-media {
        border: 1px solid var(--border);
    }

    [data-theme='dark'] .kp-media-figure > figcaption {
        color: var(--muted-foreground);
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='dark'] .kp-media-figure {
        color: var(--muted-foreground);
    }

    /* ── The pressed state the register had been cancelling [fix-12] ───
       `kp.register` sits after `kp.components`, and a layer beats a state:
       a register writing `.kp-button:hover { background: ... }` outranks
       the base layer's `.kp-button:active`, so pressing the button changed
       nothing. Kenny found it on Shade (dark), 2026-09-11 — "als ik gewoon
       blijf klikken op de knop zelf, dan gebeurt er precies niks" — and
       fifteen of the twenty-five registers had it.

       These restate the base layer's own pressed values, token for token.
       Nothing new is decided here; what the components layer already said
       is put back where the cascade can reach it. */

    [data-theme='dark'] .kp-button:active:not(:disabled) {
        background: var(--secondary-active);
    }

    /* Not `--primary-active` any more [scope-100]: with the hover on its own
       token (86%), that token (78%) sat 6.2 in OKLab distance from it, under
       the States block's floor of 10, so a press barely showed. Fourteen
       points under the hover ground instead. */
    [data-theme='dark'] .kp-button--primary:active:not(:disabled) {
        background: hsl(from var(--primary-hover) h s calc(l - 14));
        border-color: hsl(from var(--primary-hover) h s calc(l - 14));
    }

    [data-theme='dark'] .kp-button--destructive:active:not(:disabled) {
        background: var(--destructive-active);
        border-color: var(--destructive-active);
    }

    /* ── The ground [scope-16] ─────────────────────────────────────────
       An instrument's grid, and a pool of light under the pointer. Both
       are on the page's own texture layer, so nothing here paints over a
       control. The light is the one thing on the page that moves without
       being touched, and it moves only because a hand does. */
    [data-theme='dark'] body {
        background-image:
            radial-gradient(
                46rem 34rem at calc(var(--kp-px) * 100%) calc(var(--kp-py) * 100%),
                hsl(from var(--chart-1) h s l / 0.13),
                transparent 62%
            ),
            repeating-linear-gradient(90deg, hsl(from var(--foreground) h s l / 0.045) 0 1px, transparent 1px var(--kp-grid, 5.5rem)),
            repeating-linear-gradient(0deg, hsl(from var(--foreground) h s l / 0.045) 0 1px, transparent 1px var(--kp-grid, 5.5rem));
        background-attachment: fixed;
    }

    /* ── The panels' edge is the film itself [scope-16] ────────────────
       A gradient border, drawn by painting the panel's own ground over
       the oxide and letting only the border box show through. */
    [data-theme='dark'] .kp-card::after,
    [data-theme='dark'] .kp-dialog::before {
        border: 1px solid transparent;
        background:
            linear-gradient(var(--card), var(--card)) padding-box,
            var(--kp-iris) border-box;
    }

    /* ── The card's plate, and its halo [scope-102] ───────────────────────
       The dialog's scope-100 restructure, applied to the card for the same
       measured reason: its chamfer is a clip-path, a clip-path clips the
       element's own box-shadow, and the card could therefore cast nothing
       at all. The plate — the ground, the film edge and the cut — moves to
       the ::after; the card keeps its own border box (`border: 1px solid
       transparent`, so no box moves) and carries the halo.

       `inset: -1px` is the border's width: the containing block is the
       card's padding box, and the plate has to reach back over the 1px
       border it paints the film into. The same inset the dialog's plate
       carries, for the same reason. */
    [data-theme='dark'] .kp-card::after {
        content: '';
        position: absolute;
        inset: -1px;
        z-index: -1;
        border-radius: calc(var(--radius) * 1.5);
        pointer-events: none;
    }

    /* ── The dialog's plate under its content, the shadow outside it [scope-100]
       A clip-path clips everything the element paints, its box-shadow and
       any filter included, so a chamfered dialog lay flat on its backdrop:
       the 0 12px 28px shadow painted nothing (1406px of it came back with
       the clip removed). The chamfer, the ground and the film edge move to
       the dialog's ::before, and the dialog itself stays unclipped and casts
       the same shadow as a drop-shadow, which follows the plate's cut shape.
       The filter makes the dialog the containing block of a fixed
       descendant, so the plate is fixed to the dialog's box and does not
       scroll away with a dialog whose content scrolls; the popovers a
       dialog can hold open in the top layer, which no containing block
       reaches. The inset is the border's width, because that containing
       block is the padding box.

       Since scope-102 the shadow is the oxide halo, and a box-shadow
       rather than a drop-shadow: a modal dialog is `overflow: auto` by
       the UA stylesheet and clips its own pseudo-elements, so the
       blurred film could not be worn here at all, and the four fixed
       shadows are what the decision asks for on every one of the three
       surfaces. The filter stays, emptied to a no-op: it is what makes
       this dialog the containing block of its fixed plate, and losing it
       would let the plate scroll away. A box-shadow is painted with the
       element's own background and border, so the opaque plate on the
       ::before covers nothing of it — an outer shadow lies outside the
       border box by definition. */
    [data-theme='dark'] .kp-dialog {
        border: 1px solid transparent;
        background: transparent;
        box-shadow: var(--kp-halo);
        filter: drop-shadow(0 0 0 transparent);
    }

    [data-theme='dark'] .kp-dialog::before {
        content: '';
        position: fixed;
        inset: -1px;
        z-index: -1;
        pointer-events: none;
    }

    /* ── The small parts that carry the film [scope-16] ───────────────── */
    [data-theme='dark'] .kp-nav__marker,
    [data-theme='dark'] .kp-boot__bar i {
        background: var(--kp-iris);
    }

    [data-theme='dark'] .kp-measure__bracket {
        border-color: hsl(from var(--chart-1) h s l / 0.55);
    }

    /* ── Read-only fields [gap-11] ────────────────────────────────────── */

    /* A read-only field is a value on a record, not a box to type in. This
       register sets the field's border and ground in kp.register, which
       beats the read-only look in kp.components, so read-only painted like
       an editable field. The state is answered here, on top of the rest
       look, which stays as it was. */
    [data-theme='dark'] .kp-field__input[readonly] {
        border-style: dashed;
        background-color: var(--muted);
    }

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): quiet muted words on a rounded plate that
       fills with the accent ground when pointed at or focused. The link's
       typeface, case, spacing, shape and pointer answer are restated here,
       because the trigger is a button beside the list rather than a link in
       it. The underline a plain link carries is not: it says "this is a
       link", and the trigger is not one. */
    [data-theme='dark'] .kp-nav__search .kp-nav__search-trigger {
        padding-inline: 0.8rem;
        font-weight: 500;
        border: 0;
        border-radius: var(--radius);
        background: transparent;
        color: var(--muted-foreground);
    }

    [data-theme='dark'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='dark'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        background: var(--accent);
        color: var(--foreground);
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       The dark plate of the prototype, split in the near-white of its primary, with a hairline frame. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='dark'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--destructive) h calc(s * 0.6) 5% / 0.95);
        --kp-alarm-ink: hsl(from var(--destructive) h s max(l, 60));
        --kp-alarm-soft: hsl(from var(--destructive) h calc(s * 0.4) 86);
        --kp-alarm-split: var(--primary);
        --kp-alarm-on-ink: hsl(from var(--destructive) h s 6%);
        --kp-alarm-glow: hsl(from var(--destructive) h s max(l, 45) / 0.5);
        --kp-alarm-halo: hsl(from var(--destructive) h s max(l, 50) / 0.55);
        --kp-alarm-scan: hsl(from var(--destructive) h s max(l, 50) / 0.09);
        --kp-alarm-vignette: hsl(from var(--destructive) h s 2% / 0.7);
        --kp-alarm-frame: 1px solid;
        --kp-alarm-title-tracking: 0.02em;
    }

    [data-theme='dark'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='dark'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='dark'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='dark'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='dark'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='dark'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='dark'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    /* A submenu item's mark [Kenny, 2026-09-20]: the same dash as light, its sibling. */
    [data-theme='dark'] .kp-sidenav__submenu .kp-sidenav__link {
        --kp-sidenav-submenu-mark: '–';
    }
}

/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* dark's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/dark.css and research/signature-elements/themes/dark.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* The link signature is for links in running text; a link in a navigation,
       a menu, a breadcrumb (a nav) or the footer keeps its own component's look
       (scope-93: no link colour in a navigation). */
    [data-theme='dark'] .kp-progressbar {
        --kp-progressbar-height: calc(0.75rem * var(--kp-progressbar-scale, 1));
        --kp-ps-cut: calc(4px * var(--kp-progressbar-scale, 1));
        /* The indeterminate hatch: stripe and pitch grow with the bar. */
        --kp-ps-stripe: calc(2px * var(--kp-progressbar-scale, 1));
        --kp-ps-hatch: calc(6px * var(--kp-progressbar-scale, 1));
        /* The film along the scale. --kp-px is the pointer's share across the
           page (0.5 at rest, written by js/effects.js); it slides the film by
           up to a fifth of the scale, the way the anodised edge turns with the
           angle you look from. */
        --kp-ps-film: linear-gradient(90deg, var(--chart-1), var(--chart-2) 36%, var(--chart-3) 68%, var(--chart-4));
    }

    [data-theme='dark'] .kp-progressbar__track {
        border-radius: 0;
        background:
            linear-gradient(90deg, transparent calc(100% - 1px), var(--border-strong) 0) 0 100% / calc(100% / var(--kp-steps)) 45% repeat-x,
            var(--muted);
        box-shadow: inset 0 0 0 1px var(--border);
        clip-path: polygon(
            var(--kp-ps-cut) 0,
            100% 0,
            100% calc(100% - var(--kp-ps-cut)),
            calc(100% - var(--kp-ps-cut)) 100%,
            0 100%,
            0 var(--kp-ps-cut)
        );
    }

    [data-theme='dark'] .kp-progressbar__fill {
        inset-block: calc(2px * var(--kp-progressbar-scale, 1));
        background: var(--kp-ps-film) calc(var(--kp-px, 0.5) * 100%) 0 / 125% 100% no-repeat;
        transition: clip-path 320ms var(--kp-settle, cubic-bezier(0.22, 1, 0.36, 1));
    }

    [data-theme='dark'] .kp-progressbar__head {
        inline-size: calc(6px * var(--kp-progressbar-scale, 1));
        translate: -100% 0;
        background:
            linear-gradient(var(--primary), var(--primary)) 100% 0 / 2px 100% no-repeat,
            linear-gradient(var(--primary), var(--primary)) 0 0 / 100% 2px no-repeat,
            linear-gradient(var(--primary), var(--primary)) 0 100% / 100% 2px no-repeat;
        transition: transform 320ms var(--kp-settle, cubic-bezier(0.22, 1, 0.36, 1));
    }

    [data-theme='dark'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inset-inline: 0;
        inline-size: auto;
        clip-path: none;
        animation: none;
        -webkit-mask: repeating-linear-gradient(-45deg, var(--foreground) 0 var(--kp-ps-stripe), transparent var(--kp-ps-stripe) var(--kp-ps-hatch));
        mask: repeating-linear-gradient(-45deg, var(--foreground) 0 var(--kp-ps-stripe), transparent var(--kp-ps-stripe) var(--kp-ps-hatch));
    }

    /* ── The numbers and pictures the grammar is made of [Kenny, 2026-10-09;
       themes/dark/CHARACTER.md §1] ────────────────────────────────────────
       Dark passes a line. A pass is 660 ms at one pace (linear) and stops
       dead; the film it lays turns, and settles 220 ms after the line has
       stopped (880 ms in all, `--kp-sig-dk-time`); a loop is 2400 ms; a
       group is crossed 60 ms apart. The line is a 2 px slice of the film
       with the one glow the theme allows, 10 px of --chart-1 at 40 %. */
    [data-theme='dark'] {
        --kp-sig-dark-ease: var(--kp-settle, cubic-bezier(0.22, 1, 0.36, 1));
        --kp-sig-dark-c: 0.35rem;
        --kp-sig-dk-time: 880ms;
        --kp-sig-dk-loop: 2400ms;
        --kp-sig-dk-r: 0px;
        /* Which way the pass runs: from the start edge, so from the left on a
           left-to-right page and from the right on a right-to-left one
           [scope-143]. Five numbers say it for the mask (the edge it is laid
           from), the line (its sign, and the side of its box the 2 px sits
           on), the film behind a figure's letters and the clip of a small
           part; `:dir(rtl)` below turns them. */
        --kp-sig-dk-s: 1;
        --kp-sig-dk-from: left;
        --kp-sig-dk-end: 100%;
        --kp-sig-dk-gdir: 90deg;
        --kp-sig-dk-cut: 0 100% 0 0;
        --kp-sig-dk-cw: 0.36;
        --kp-sig-dk-line: linear-gradient(180deg, var(--chart-1), var(--chart-2), var(--chart-3), var(--chart-4));
        --kp-sig-dk-glow: drop-shadow(0 0 10px hsl(from var(--chart-1) h s l / 0.4));
        /* A solid, for a mask: only its alpha is read. */
        --kp-sig-dk-solid: linear-gradient(var(--foreground), var(--foreground));
        /* A comet: the head is the line, the tail a third of the part long,
           full film at the head and nothing at its end. */
        --kp-sig-dk-tail: linear-gradient(
            90deg,
            transparent,
            hsl(from var(--chart-4) h s l / 0.14) 38%,
            hsl(from var(--chart-3) h s l / 0.3) 60%,
            hsl(from var(--chart-2) h s l / 0.5) 80%,
            hsl(from var(--chart-1) h s l / 0.8)
        );
        --kp-sig-dark-cut: polygon(
            0 0,
            calc(100% - var(--kp-sig-dark-c)) 0,
            100% var(--kp-sig-dark-c),
            100% 100%,
            var(--kp-sig-dark-c) 100%,
            0 calc(100% - var(--kp-sig-dark-c))
        );
        /* Four corner brackets in one ink, as background layers. */
        --kp-sig-dark-bk: var(--border-strong);
        --kp-sig-dark-arm: 0.6rem;
        --kp-sig-dark-brackets:
            linear-gradient(var(--kp-sig-dark-bk), var(--kp-sig-dark-bk)) left top / var(--kp-sig-dark-arm) 1px no-repeat,
            linear-gradient(var(--kp-sig-dark-bk), var(--kp-sig-dark-bk)) left top / 1px var(--kp-sig-dark-arm) no-repeat,
            linear-gradient(var(--kp-sig-dark-bk), var(--kp-sig-dark-bk)) right top / var(--kp-sig-dark-arm) 1px no-repeat,
            linear-gradient(var(--kp-sig-dark-bk), var(--kp-sig-dark-bk)) right top / 1px var(--kp-sig-dark-arm) no-repeat,
            linear-gradient(var(--kp-sig-dark-bk), var(--kp-sig-dark-bk)) left bottom / var(--kp-sig-dark-arm) 1px no-repeat,
            linear-gradient(var(--kp-sig-dark-bk), var(--kp-sig-dark-bk)) left bottom / 1px var(--kp-sig-dark-arm) no-repeat,
            linear-gradient(var(--kp-sig-dark-bk), var(--kp-sig-dark-bk)) right bottom / var(--kp-sig-dark-arm) 1px no-repeat,
            linear-gradient(var(--kp-sig-dark-bk), var(--kp-sig-dark-bk)) right bottom / 1px var(--kp-sig-dark-arm) no-repeat;
    }

    /* A right-to-left page is passed from its right edge, the line crossing
       to the left, and the pass back is the same frames reversed as ever.
       A left-to-right island inside it turns them back. */
    [data-theme='dark']:dir(rtl),
    [data-theme='dark'] [dir]:dir(rtl) {
        --kp-sig-dk-s: -1;
        --kp-sig-dk-from: right;
        --kp-sig-dk-end: 0%;
        --kp-sig-dk-gdir: 270deg;
        --kp-sig-dk-cut: 0 0 0 100%;
    }

    [data-theme='dark'] [dir]:dir(ltr) {
        --kp-sig-dk-s: 1;
        --kp-sig-dk-from: left;
        --kp-sig-dk-end: 100%;
        --kp-sig-dk-gdir: 90deg;
        --kp-sig-dk-cut: 0 100% 0 0;
    }

    /* The film turns on a pass: every part that is laid, taken off, pressed
       or crossed writes the film on its own copy of the turn, so a turn of
       one number turns every edge that wears it (and the parts inside it,
       which inherit the number). At rest the turn is 0 and this is the
       register's film. */
    [data-theme='dark']
        :is(
            .kp-button,
            .kp-icon-button,
            .kp-dialog,
            dialog.kp-drawer,
            .kp-menu,
            .kp-popover,
            .kp-toast,
            .kp-tooltip,
            .kp-card,
            .kp-alert,
            .kp-kpi,
            .kp-combobox__list,
            .kp-datepicker__panel,
            .kp-palette,
            .kp-theme-menu__list,
            .kp-nav__menu,
            [data-kp-leaving],
            [data-kp-arriving]
        ) {
        --kp-iris: conic-gradient(
            from calc(var(--kp-px) * 1turn + var(--kp-sig-dk-turn)),
            var(--chart-1),
            var(--chart-2),
            var(--chart-3),
            var(--chart-4),
            var(--chart-1)
        );
    }

    /* ── The spinner is the spectrum bars [G12; Kenny, 2026-10-09, question
       12: "The spectrum bars"]. Five thin bars, one per film colour and a
       lime, rise and fall in turn like a spectrometer's reading, 120 ms
       apart (a twentieth of the 2400 ms loop), each cut on two opposite
       corners; a hairline stands under them. One number, --kp-sig-dk-ph (0
       to 1 over the loop, @property at the top of this file), is the loop;
       each bar's height is read from it a twentieth later than the bar
       before. Standing still the five stand at their rest heights. The
       three sizes are the package's own (--kp-spinner-size). ── */
    [data-theme='dark'] .kp-spinner {
        --kp-sig-dk-cutb: calc(var(--kp-spinner-size, 1.25rem) * 0.06);
        --kp-sig-dk-h1: calc(
            0.58 + 0.27 * sin(calc((var(--kp-sig-dk-ph) - 0 * 0.05) * 720deg)) + 0.15 * sin(calc((var(--kp-sig-dk-ph) - 0 * 0.05) * 1080deg))
        );
        --kp-sig-dk-h2: calc(
            0.58 + 0.27 * sin(calc((var(--kp-sig-dk-ph) - 1 * 0.05) * 720deg)) + 0.15 * sin(calc((var(--kp-sig-dk-ph) - 1 * 0.05) * 1080deg))
        );
        --kp-sig-dk-h3: calc(
            0.58 + 0.27 * sin(calc((var(--kp-sig-dk-ph) - 2 * 0.05) * 720deg)) + 0.15 * sin(calc((var(--kp-sig-dk-ph) - 2 * 0.05) * 1080deg))
        );
        --kp-sig-dk-h4: calc(
            0.58 + 0.27 * sin(calc((var(--kp-sig-dk-ph) - 3 * 0.05) * 720deg)) + 0.15 * sin(calc((var(--kp-sig-dk-ph) - 3 * 0.05) * 1080deg))
        );
        --kp-sig-dk-h5: calc(
            0.58 + 0.27 * sin(calc((var(--kp-sig-dk-ph) - 4 * 0.05) * 720deg)) + 0.15 * sin(calc((var(--kp-sig-dk-ph) - 4 * 0.05) * 1080deg))
        );
        position: relative;
        border: 0;
        border-radius: 0;
        -webkit-mask: none;
        mask: none;
        animation: none;
        background-color: transparent;
        background-image:
            linear-gradient(var(--border-strong), var(--border-strong)),
            linear-gradient(
                225deg,
                transparent 0 calc(var(--kp-sig-dk-cutb) * 0.7071),
                var(--chart-1) 0 calc(100% - var(--kp-sig-dk-cutb) * 0.7071),
                transparent 0
            ),
            linear-gradient(
                225deg,
                transparent 0 calc(var(--kp-sig-dk-cutb) * 0.7071),
                var(--chart-2) 0 calc(100% - var(--kp-sig-dk-cutb) * 0.7071),
                transparent 0
            ),
            linear-gradient(
                225deg,
                transparent 0 calc(var(--kp-sig-dk-cutb) * 0.7071),
                var(--chart-3) 0 calc(100% - var(--kp-sig-dk-cutb) * 0.7071),
                transparent 0
            ),
            linear-gradient(
                225deg,
                transparent 0 calc(var(--kp-sig-dk-cutb) * 0.7071),
                var(--chart-4) 0 calc(100% - var(--kp-sig-dk-cutb) * 0.7071),
                transparent 0
            ),
            linear-gradient(
                225deg,
                transparent 0 calc(var(--kp-sig-dk-cutb) * 0.7071),
                hsl(from var(--chart-4) h s calc(l + 12)) 0 calc(100% - var(--kp-sig-dk-cutb) * 0.7071),
                transparent 0
            );
        background-repeat: no-repeat;
        background-size:
            100% 1px,
            12% calc(100% * var(--kp-sig-dk-h1)),
            12% calc(100% * var(--kp-sig-dk-h2)),
            12% calc(100% * var(--kp-sig-dk-h3)),
            12% calc(100% * var(--kp-sig-dk-h4)),
            12% calc(100% * var(--kp-sig-dk-h5));
        background-position:
            0 100%,
            9.09% 100%,
            29.5% 100%,
            50% 100%,
            70.45% 100%,
            90.9% 100%;
    }

    /* ── Loading is a comet [G10; Kenny, 2026-10-09, question 10: "A comet
       with a film tail"]. On every waiting surface the line is the head of a
       tail a third of the part long, full film at the head and nothing at
       its end; it crosses from start to end in the first three quarters of
       the loop (1800 ms of 2400) and lays nothing, the slot stays dark behind
       the tail, then the loop comes round. It fills the whole element and
       takes its shape (a chamfered skeleton line is cut, a panel is swept
       whole). The picture is the element's own ::before, laid over what is
       waiting; a button has its brackets on ::before, so its comet is
       painted on its own ground. The surfaces are the package's own: the
       skeleton lines, blocks and circles (the key figures' and the
       columns' skeleton lines are skeleton lines), the busy table's panel,
       the loading menu entry, the busy button and card, the busy calendar
       and its days, the loading chart, the busy tile grid, the loading
       meter. One keyframe moves two background layers (the 2 px head and the
       tail) from just before the start to just past the end; the comet's
       width is --kp-sig-dk-cw. ── */
    [data-theme='dark']
        :where(
            .kp-skeleton,
            .kp-datatable__busy-panel,
            .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading],
            .kp-card[aria-busy='true'],
            .kp-tiles[aria-busy='true'] > .kp-card,
            .kp-chart__state[data-kp-state='loading'],
            .kp-calendar--busy-whole > .kp-calendar__busy,
            .kp-calendar:not(.kp-calendar--busy-days, .kp-calendar--busy-whole) .kp-calendar__day[data-kp-tone='loading']
        ) {
        position: relative;
        animation: none;
    }

    [data-theme='dark']
        :where(
            .kp-skeleton,
            .kp-datatable__busy-panel,
            .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading],
            .kp-card[aria-busy='true'],
            .kp-tiles[aria-busy='true'] > .kp-card,
            .kp-chart__state[data-kp-state='loading'],
            .kp-calendar--busy-whole > .kp-calendar__busy,
            .kp-calendar:not(.kp-calendar--busy-days, .kp-calendar--busy-whole) .kp-calendar__day[data-kp-tone='loading']
        )::before {
        content: '';
        position: absolute;
        inset: 0;
        z-index: 1;
        border-radius: inherit;
        opacity: 1;
        pointer-events: none;
        background-image: var(--kp-sig-dk-line), var(--kp-sig-dk-tail);
        background-repeat: no-repeat;
        background-size:
            2px 100%,
            calc(var(--kp-sig-dk-cw) * 100%) 100%;
        background-position:
            calc(50% * (1 + var(--kp-sig-dk-cw)) - 1px) 0,
            50% 0;
    }

    /* A chart's plot and a menu entry stand on the page's own ground. */
    [data-theme='dark'] .kp-chart__state[data-kp-state='loading'] {
        background-color: transparent;
    }

    /* The skeleton line is a slot: the accent plate, a hairline of film at its
       foot, the chamfer; its sibling lines are crossed 120 ms apart. */
    [data-theme='dark'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        position: relative;
        block-size: 0.9rem;
        border-radius: 0;
        background:
            linear-gradient(var(--accent), var(--accent)) top / 100% calc(100% - 1px) no-repeat,
            var(--kp-iris);
        clip-path: var(--kp-sig-dark-cut);
        animation: none;
    }

    [data-theme='dark'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) + .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        margin-block-start: 0.6rem;
    }

    [data-theme='dark'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::after {
        content: none;
    }

    /* The block and the circle are slots of the accent plate too. */
    [data-theme='dark'] :is(.kp-skeleton--block, .kp-skeleton--circle) {
        overflow: clip;
        background: var(--accent);
    }

    [data-theme='dark'] .kp-skeleton--block {
        border-radius: 0;
        clip-path: var(--kp-sig-dark-cut);
    }

    /* A busy button wears its comet on its own ground (its brackets are the
       ::before and ::after). */
    [data-theme='dark'] .kp-button[aria-busy='true'][aria-busy='true'] {
        background-image: var(--kp-sig-dk-line), var(--kp-sig-dk-tail);
        background-repeat: no-repeat;
        background-size:
            2px 100%,
            calc(var(--kp-sig-dk-cw) * 100%) 100%;
        background-position:
            calc(50% * (1 + var(--kp-sig-dk-cw)) - 1px) 0,
            50% 0;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark']
            :where(
                .kp-skeleton,
                .kp-datatable__busy-panel,
                .kp-menu[aria-busy='true'] .kp-menu__item[data-kp-loading],
                .kp-card[aria-busy='true'],
                .kp-tiles[aria-busy='true'] > .kp-card,
                .kp-chart__state[data-kp-state='loading'],
                .kp-calendar--busy-whole > .kp-calendar__busy,
                .kp-calendar:not(.kp-calendar--busy-days, .kp-calendar--busy-whole) .kp-calendar__day[data-kp-tone='loading']
            )::before {
            animation: kp-sig-dark-comet var(--kp-sig-dk-loop) linear infinite;
        }

        [data-theme='dark'] .kp-button[aria-busy='true'][aria-busy='true'] {
            animation: kp-sig-dark-comet var(--kp-sig-dk-loop) linear infinite;
        }

        /* A part's place in a row staggers its comet by 120 ms, so a row of
           skeleton lines or days reads as one pass. */
        [data-theme='dark'] .kp-skeleton:nth-child(2)::before {
            animation-delay: calc(120ms - var(--kp-sig-dk-loop));
        }

        [data-theme='dark'] .kp-skeleton:nth-child(3)::before {
            animation-delay: calc(240ms - var(--kp-sig-dk-loop));
        }

        [data-theme='dark'] .kp-spinner {
            animation: kp-sig-dark-bars var(--kp-sig-dk-loop) linear infinite;
        }

        /* The busy bar: no share is known, so the line runs the empty track
           [G11; Kenny, 2026-10-09, question 11: "The line runs the track"]:
           a short stretch of film (28 % of the track) crosses from the start
           to the end, laying a tail that dims behind the line, 2400 ms, and
           again. With a share known the fill is laid to the share, as round
           one drew it. */
        [data-theme='dark'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
            --kp-sig-dk-cw: 0.28;
            -webkit-mask: none;
            mask: none;
            background-color: transparent;
            background-image: var(--kp-sig-dk-line), var(--kp-sig-dk-tail);
            background-repeat: no-repeat;
            background-size:
                2px 100%,
                calc(var(--kp-sig-dk-cw) * 100%) 100%;
            background-position:
                calc(50% * (1 + var(--kp-sig-dk-cw)) - 1px) 0,
                50% 0;
            animation: kp-sig-dark-comet var(--kp-sig-dk-loop) linear infinite;
        }

        /* A tick and a radio's dot are laid by the pass, in the contact time. */
        [data-theme='dark'] .kp-field__check:checked::before {
            animation: kp-sig-dark-lay var(--fx-duration) linear both;
        }

        [data-theme='dark'] .kp-switch__input::before {
            transition: transform var(--fx-duration) var(--kp-sig-dark-ease);
        }
    }

    [data-theme='dark'] .kp-switch {
        --kp-switch-radius: 0;
        --kp-switch-thumb-radius: 0;
    }

    [data-theme='dark'] .kp-switch__input {
        --kp-sig-dark-bk: var(--muted-foreground);
        --kp-sig-dark-arm: 0.4rem;
        border: 1px solid var(--border-strong);
        background: var(--kp-sig-dark-brackets), var(--card);
    }

    [data-theme='dark'] .kp-switch__input::before {
        background: var(--muted-foreground);
        clip-path: polygon(0 0, calc(100% - 4px) 0, 100% 4px, 100% 100%, 4px 100%, 0 calc(100% - 4px));
    }

    [data-theme='dark'] .kp-switch__input:checked {
        border-color: var(--primary);
        background:
            linear-gradient(var(--card), var(--card)) top / 100% calc(100% - 2px) no-repeat,
            var(--kp-iris);
    }

    [data-theme='dark'] .kp-switch__input:checked::before {
        inset-inline-start: var(--kp-switch-inset, 0.125rem);
        background: var(--primary);
        transform: translateX(calc(var(--kp-switch-width, 2.5rem) - var(--kp-switch-height, 1.5rem)));
    }

    [data-theme='dark'] .kp-field__check {
        appearance: none;
        display: inline-grid;
        place-items: center;
        inline-size: 1.15rem;
        block-size: 1.15rem;
        margin: 0;
        border: 1px solid var(--border-strong);
        border-radius: 0.1rem;
        background: var(--card);
    }

    [data-theme='dark'] .kp-field__check::before,
    [data-theme='dark'] .kp-field__check::after {
        grid-area: 1 / 1;
    }

    [data-theme='dark'] .kp-field__check[type='checkbox']:checked {
        border-color: var(--primary);
        background:
            linear-gradient(var(--primary), var(--primary)) top / 100% calc(100% - 2px) no-repeat,
            var(--kp-iris);
    }

    [data-theme='dark'] .kp-field__check[type='checkbox']:checked::before {
        content: '';
        inline-size: 0.6rem;
        block-size: 0.3rem;
        border-radius: 0;
        background: none;
        border-inline-start: 2px solid var(--primary-foreground);
        border-block-end: 2px solid var(--primary-foreground);
        transform: translateY(-1px) rotate(-45deg);
    }

    [data-theme='dark'] .kp-field__check[type='radio'] {
        border-radius: 50%;
    }

    [data-theme='dark'] .kp-field__check[type='radio']:checked {
        border-color: var(--primary);
        background: var(--card);
    }

    [data-theme='dark'] .kp-field__check[type='radio']:checked::before {
        content: '';
        inline-size: 0.5rem;
        block-size: 0.5rem;
        border-radius: 50%;
        background: var(--primary);
    }

    [data-theme='dark'] .kp-toast {
        position: relative;
    }

    [data-theme='dark'] .kp-toast:not([class*='kp-toast--']) {
        border: 1px solid transparent;
        background:
            linear-gradient(var(--card), var(--card)) padding-box,
            var(--kp-iris) border-box;
    }

    [data-theme='dark'] .kp-tooltip {
        margin-inline-start: 0.5rem;
        padding: 0.3rem 0.75rem;
        border: 1px solid transparent;
        border-radius: 0;
        background:
            linear-gradient(var(--card), var(--card)) padding-box,
            var(--kp-iris) border-box;
        box-shadow: none;
        font-size: 0.8125rem;
        letter-spacing: 0.02em;
        clip-path: polygon(0 0, calc(100% - 0.45rem) 0, 100% 0.45rem, 100% 100%, 0.45rem 100%, 0 calc(100% - 0.45rem));
    }

    [data-theme='dark'] .kp-wizard__steps {
        gap: 0.5rem 0.9rem;
    }

    [data-theme='dark'] .kp-wizard__steps li {
        gap: 0.5rem;
        padding: 0.3rem 0.6rem 0.3rem 0.3rem;
    }

    [data-theme='dark'] .kp-wizard__steps li::before {
        inline-size: 1.6rem;
        block-size: 1.6rem;
        border: 0;
        border-radius: 0;
        background: var(--card);
        box-shadow: inset 0 0 0 1px var(--border-strong);
        clip-path: polygon(0 0, calc(100% - 5px) 0, 100% 5px, 100% 100%, 5px 100%, 0 calc(100% - 5px));
        color: var(--muted-foreground);
    }

    [data-theme='dark'] .kp-wizard__steps li[data-state='done'] {
        color: var(--foreground);
    }

    [data-theme='dark'] .kp-wizard__steps li[data-state='done']::before {
        background: var(--kp-iris);
        box-shadow: none;
        color: var(--background);
        font-weight: 700;
    }

    [data-theme='dark'] .kp-wizard__steps li[data-state='current'] {
        --kp-sig-dark-bk: var(--primary);
        --kp-sig-dark-arm: 0.45rem;
        background: var(--kp-sig-dark-brackets);
    }

    [data-theme='dark'] .kp-wizard__steps li[data-state='current']::before {
        background: var(--primary);
        box-shadow: none;
        color: var(--primary-foreground);
    }

    [data-theme='dark'] .kp-empty {
        --kp-sig-dark-arm: 1rem;
        position: relative;
        padding: 1.5rem 1.5rem 2.25rem;
        border: 0;
        border-radius: 0;
        background:
            var(--kp-sig-dark-brackets), repeating-linear-gradient(to right, hsl(from var(--foreground) h s l / 0.04) 0 1px, transparent 1px 1.25rem),
            repeating-linear-gradient(to bottom, hsl(from var(--foreground) h s l / 0.04) 0 1px, transparent 1px 1.25rem);
    }

    [data-theme='dark'] .kp-empty::after {
        content: '';
        position: absolute;
        inset-block-end: 1.1rem;
        inset-inline: 30%;
        block-size: 1px;
        background: var(--kp-iris);
    }

    [data-theme='dark'] .kp-empty__title {
        letter-spacing: 0.02em;
    }

    [data-theme='dark'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a) {
        text-decoration-thickness: 1px;
        text-decoration-color: hsl(from var(--foreground) h s l / 0.5);
        text-underline-offset: 0.25em;
        -webkit-box-decoration-break: clone;
        box-decoration-break: clone;
    }

    [data-theme='dark'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
        padding-block-end: 1px;
        background: var(--kp-iris) left bottom / 100% 2px no-repeat;
        text-decoration-color: transparent;
    }

    @media (forced-colors: active) {
        [data-theme='dark'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
            text-decoration-color: currentColor;
        }
    }

    /* ── Pointing, the keyboard and the press: one manner for every control
       [G14, G15, G17; Kenny, 2026-10-09, questions 14, 15 and 17]. A button
       in a header, a menu, a drawer, a tile or a tour hovers, focuses and
       presses exactly like dark's own bracketed button; a menu entry like
       the button; a link by its underline taking the film (above). The line
       rests at the start: a 2 px slice of the film with its glow stands at
       the control's start edge and the brackets close one step (the
       register's own, above). The keyboard's ring is DI2's two channels
       inside the cut, and it wins over the pointer when both apply. A press
       is a pass: on contact the line crosses the face (220 ms) and the film
       edge turns a quarter (+90 degrees) and settles; the brackets close; the
       release turns it back. Nothing moves. ── */
    [data-theme='dark'] :is(.kp-button, .kp-icon-button, .kp-menu__item) {
        background-image: var(--kp-sig-dk-line);
        background-repeat: no-repeat;
        background-position: 0 0;
        background-size: 0 100%;
    }

    [data-theme='dark'] :is(.kp-button, .kp-icon-button, .kp-menu__item):hover:not(:disabled, [aria-disabled='true']) {
        background-size: 2px 100%;
    }

    [data-theme='dark'] :is(.kp-button, .kp-icon-button, .kp-menu__item):hover:not(:disabled, [aria-disabled='true'], :focus-visible) {
        box-shadow: inset 7px 0 9px -6px hsl(from var(--chart-1) h s l / 0.4);
    }

    /* The film's edge on a link tile or a filter tile: the line at the start. */
    [data-theme='dark'] :is(a.kp-kpi, .kp-kpi--toggle)::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 2px;
        background: var(--kp-sig-dk-line);
        box-shadow: 0 0 9px hsl(from var(--chart-1) h s l / 0.4);
        opacity: 0;
        pointer-events: none;
    }

    [data-theme='dark'] :is(a.kp-kpi, .kp-kpi--toggle):hover::before {
        opacity: 1;
    }

    [data-theme='dark'] :is(a.kp-kpi, .kp-kpi--toggle):is(:focus-visible) {
        outline: none;
        box-shadow:
            inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 calc(var(--kp-focus-ring-inner-width, 2px) + 2px) var(--focus-ring-contrast);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] :is(.kp-button, .kp-icon-button, .kp-menu__item) {
            transition:
                background-color var(--fx-duration) var(--fx-ease),
                border-color var(--fx-duration) var(--fx-ease),
                color var(--fx-duration) var(--fx-ease),
                box-shadow var(--fx-duration) var(--fx-ease),
                background-size var(--fx-duration) var(--fx-ease),
                --kp-sig-dk-turn var(--fx-duration) cubic-bezier(0.64, 0, 0.78, 0);
        }

        [data-theme='dark'] :is(a.kp-kpi, .kp-kpi--toggle)::before {
            transition: opacity var(--fx-duration) var(--fx-ease);
        }

        /* On contact: the edge turns a quarter on the settle, the ground and the
           line answer at once; the line crosses the face in the contact time. */
        [data-theme='dark'] :is(.kp-button, .kp-icon-button, .kp-menu__item):active:not(:disabled) {
            --kp-sig-dk-turn: 90deg;
            background-size: 2px 100%;
            transition:
                background-color 0s,
                border-color 0s,
                color 0s,
                box-shadow 0s,
                background-size 0s,
                --kp-sig-dk-turn var(--fx-duration) var(--fx-ease);
            animation: kp-sig-dark-tap var(--fx-duration) linear both;
        }
    }

    /* ── A live update is one pass over the figure [G9; Kenny, 2026-10-09,
       question 9: "One pass over the figure"]. js/update.js writes the new
       value at once and marks the element `[data-kp-updating='pass']`; the
       line crosses the changed figure once from its start (the theme's update
       time, 660 ms), the letters behind it take the film and settle back to
       ink once it has gone by; the figure never moves, flares or jolts and
       the box keeps its space. Applies to the key figure, the state word, the
       trend, the strip column and the tile alike. A state word keeps its
       width-holding ::after, so its line is drawn on ::before; a spark (an
       svg) has no letters, its line crosses the parent's box. Two numbers, how
       far the line has come (--kp-sig-dk-at) and how much ink lies over the
       film (--kp-sig-dk-ink), are @property at the top of this file. ── */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] {
            --kp-update: pass;
        }

        [data-theme='dark'] [data-kp-updating='pass'] {
            position: relative;
            --kp-sig-dk-ink-colour: var(--foreground);
        }

        [data-theme='dark'] .kp-kpi > .kp-kpi__value[data-kp-updating='pass'] {
            justify-self: start;
            inline-size: fit-content;
        }

        [data-theme='dark'] [data-kp-updating='pass']:not(:has(> svg)) {
            background:
                linear-gradient(var(--kp-sig-dk-gdir), transparent var(--kp-sig-dk-at), var(--kp-sig-dk-ink-colour) var(--kp-sig-dk-at)),
                linear-gradient(
                    hsl(from var(--kp-sig-dk-ink-colour) h s l / var(--kp-sig-dk-ink)),
                    hsl(from var(--kp-sig-dk-ink-colour) h s l / var(--kp-sig-dk-ink))
                ),
                var(--kp-iris);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            animation: kp-sig-dark-figure var(--kp-update-duration, 660ms) linear both;
        }

        [data-theme='dark'] [data-kp-updating='pass']:not(.kp-state-word)::after,
        [data-theme='dark'] .kp-state-word[data-kp-updating='pass']::before {
            content: '';
            position: absolute;
            inset: -2px -4px;
            z-index: 1;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-live var(--kp-update-duration, 660ms) linear both;
        }
    }

    /* ── The opening is a pass [G3, G13; Kenny, 2026-10-09, question 3:
       "Swept in from its own left edge, left to right"]. A dialog, a menu, a
       popover, a combobox list, a date picker, a palette, a toast, a tooltip
       and a drawer open the same way: the line starts at the left edge of the
       element that opens (never at its button) and crosses only that
       element's own box at one pace, laying the panel behind it, the film
       edge turning; it stops dead at the end and the turn settles 220 ms
       later (880 ms in all). The close is the pass back, right to left,
       taking the panel off behind it: js/motion.js plays this entrance
       backwards (`--kp-open: reverse-close`), frame t of the close being
       frame (T - t) of the open. The panel is revealed by a mask of three
       layers (the box, and the reach of its halo on either side, which come
       with the line's first and last 4 %), so the halo and the cut follow
       what is laid instead of being cut square. The line is the panel's
       ::after; the film turn is one number on the panel (the film's own
       @property, kp-sig-dark-film). ── */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark']
            :is(.kp-dialog, .kp-menu, .kp-popover, .kp-toast, .kp-combobox__list, .kp-datepicker__panel, .kp-palette, .kp-theme-menu__list) {
            --kp-sig-dk-r: var(--kp-halo-reach, 2.5rem);
        }

        [data-theme='dark']
            :is(
                .kp-dialog,
                dialog.kp-drawer,
                .kp-menu,
                .kp-popover,
                .kp-tooltip,
                .kp-toast,
                .kp-combobox__list,
                .kp-datepicker__panel,
                .kp-palette,
                .kp-theme-menu__list
            ) {
            animation:
                kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards,
                kp-sig-dark-film var(--kp-sig-dk-time) linear backwards;
        }

        [data-theme='dark']
            :is(
                .kp-dialog,
                dialog.kp-drawer,
                .kp-menu,
                .kp-popover,
                .kp-tooltip,
                .kp-toast,
                .kp-combobox__list,
                .kp-datepicker__panel,
                .kp-palette,
                .kp-theme-menu__list,
                .kp-nav__menu
            )::after {
            content: '';
            position: absolute;
            inset: 0;
            z-index: 3;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            clip-path: none;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear backwards;
        }

        /* A menu inside a popover is not swept twice: the popover is. */
        [data-theme='dark'] .kp-popover :is(.kp-menu, .kp-popover) {
            animation: none;
        }

        [data-theme='dark'] .kp-popover :is(.kp-menu, .kp-popover)::after {
            content: none;
        }

        /* The drawer comes in from its own left edge too, over its own height
           and width: it casts no halo, so there is no reach. */
        [data-theme='dark'] dialog.kp-drawer {
            --kp-sig-dk-r: 0px;
        }

        /* A dialog's backdrop is not swept; js/motion.js fades it with the
           dialog. */

        /* The nav dropdown opens by hovering or focusing its item, with no script
           in between: the same pass, and the close is the pass back. While it
           closes the item keeps the panel on screen for the whole pass back
           (`display` is a discrete transition), and the closed style plays the
           entrance reversed. */
        @container kp-nav (width > 40rem) {
            [data-theme='dark'] .kp-nav__menu {
                --kp-sig-dk-r: var(--kp-halo-reach, 2.5rem);
                opacity: 1;
                transition: display var(--kp-sig-dk-time) allow-discrete;
                animation:
                    kp-sig-dark-sweep var(--kp-sig-dk-time) linear reverse forwards,
                    kp-sig-dark-film var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark'] .kp-nav__menu::after {
                animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark'] .kp-nav__links > li:hover > .kp-nav__menu,
            [data-theme='dark'] .kp-nav__links > li:focus-within > .kp-nav__menu,
            [data-theme='dark'] .kp-nav__links > li[data-kp-nav-menu-open] > .kp-nav__menu {
                animation:
                    kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards,
                    kp-sig-dark-film var(--kp-sig-dk-time) linear backwards;
            }

            [data-theme='dark'] .kp-nav__links > li:hover > .kp-nav__menu::after,
            [data-theme='dark'] .kp-nav__links > li:focus-within > .kp-nav__menu::after,
            [data-theme='dark'] .kp-nav__links > li[data-kp-nav-menu-open] > .kp-nav__menu::after {
                animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear backwards;
            }
        }

        /* The tooltip's halo is none: its reach is none. */
        [data-theme='dark'] .kp-tooltip {
            --kp-sig-dk-r: 0px;
        }
    }

    @container kp-nav (max-width: 40rem) {
        [data-theme='dark'] .kp-nav__menu::after {
            content: none;
        }
    }

    /* The mask is only ever on while the pass plays: both ends of the keyframe
       are the finished pose, so a still part carries no mask. The panel is the
       box (layer one, which the line sweeps) and the reach of its halo on the
       left (layer two, laid in the first 4 % of the pass) and on the right
       (layer three, laid in the last 4 %). Written out once, 0 to 75 % of the
       880 ms is the pass of 660 ms (G4); the rest holds while the turn
       settles. */
    @keyframes kp-sig-dark-sweep {
        0% {
            mask-image: var(--kp-sig-dk-solid), var(--kp-sig-dk-solid), var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-origin: border-box;
            mask-clip: no-clip;
            mask-composite: add;
            mask-position:
                var(--kp-sig-dk-from) 0 top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(-1 * var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(100% + var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r));
            mask-size:
                0px calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        3% {
            mask-size:
                4% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        72% {
            mask-size:
                96% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        75%,
        100% {
            mask-image: var(--kp-sig-dk-solid), var(--kp-sig-dk-solid), var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-origin: border-box;
            mask-clip: no-clip;
            mask-composite: add;
            mask-position:
                var(--kp-sig-dk-from) 0 top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(-1 * var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(100% + var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r));
            mask-size:
                100% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r));
        }
    }

    /* The line crosses the panel's own box and goes in and out at its ends. */
    @keyframes kp-sig-dark-pass-line {
        0% {
            translate: calc(-100% * var(--kp-sig-dk-s)) 0;
            opacity: 0;
        }

        3% {
            translate: calc(-96% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        69% {
            translate: calc(-8% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        75%,
        100% {
            translate: 0 0;
            opacity: 0;
        }
    }

    /* The film's turn, laid with the pass: the colour runs round the edge as
       the line crosses (345 degrees at the pace of the line) and settles the
       last 15 degrees on --kp-settle in the 220 ms after the line has stopped,
       cyan at the top. */
    @keyframes kp-sig-dark-film {
        0% {
            --kp-sig-dk-turn: 0deg;
            animation-timing-function: linear;
        }

        75% {
            --kp-sig-dk-turn: 345deg;
            animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
        }

        100% {
            --kp-sig-dk-turn: 360deg;
        }
    }

    /* The figure takes the film through its letters while the line crosses it
       and settles back to ink once it has gone by. */
    @keyframes kp-sig-dark-figure {
        0% {
            --kp-sig-dk-at: 0%;
            --kp-sig-dk-ink: 0;
            animation-timing-function: linear;
        }

        75% {
            --kp-sig-dk-at: 100%;
            --kp-sig-dk-ink: 0;
            animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
        }

        100% {
            --kp-sig-dk-at: 100%;
            --kp-sig-dk-ink: 1;
        }
    }

    /* A live pass: the line goes in at the start and out at the end of the
       update's own time. */
    @keyframes kp-sig-dark-pass-live {
        0% {
            translate: calc(-100% * var(--kp-sig-dk-s)) 0;
            opacity: 0;
        }

        4% {
            translate: calc(-96% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        92% {
            translate: calc(-8% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        100% {
            translate: 0 0;
            opacity: 0;
        }
    }

    /* The pass of a small part or of a word: its box, from the start edge, at
       one pace, stopping dead. */
    @keyframes kp-sig-dark-lay {
        from {
            clip-path: inset(var(--kp-sig-dk-cut));
        }

        to {
            clip-path: inset(0);
        }
    }

    /* A comet crosses a waiting surface. The head (the 2 px line) and the tail
       (a third of the part, or the share the property --kp-sig-dk-cw says)
       are two background layers moved together from just before the start to
       just past the end in three quarters of the loop; the last quarter the
       slot is dark. A percentage position is a share of the box less the
       layer, so the head sits at (1 + cw) of the box less its own width and
       the tail at 1 / (1 - cw). */
    @keyframes kp-sig-dark-comet {
        0% {
            background-position:
                calc(0% - 2px) 0,
                calc(-100% * var(--kp-sig-dk-cw) / (1 - var(--kp-sig-dk-cw))) 0;
        }

        75%,
        100% {
            background-position:
                calc(100% * (1 + var(--kp-sig-dk-cw)) - 2px) 0,
                calc(100% / (1 - var(--kp-sig-dk-cw))) 0;
        }
    }

    /* The spinner's loop: one number, 0 to 1. */
    @keyframes kp-sig-dark-bars {
        from {
            --kp-sig-dk-ph: 0;
        }

        to {
            --kp-sig-dk-ph: 1;
        }
    }

    /* A press: the line crosses the face and stops at its end. */
    @keyframes kp-sig-dark-tap {
        from {
            background-position: 0 0;
        }

        to {
            background-position: 100% 0;
        }
    }

    /* Growing and shrinking, this theme's way [scope-142; Kenny, 2026-10-09:
       the darkroom is retired]. js/motion.js marks a gliding box
       `[data-kp-resizing]` and what arrives in it `[data-kp-arriving]`. The
       box keeps the line's glow while it changes; what arrives is laid by the
       pass (below), and nothing develops from a pale print. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] [data-kp-resizing] {
            filter: var(--kp-sig-dk-glow);
        }
    }

    /* Leaving, this theme's way [G13; Kenny, 2026-10-09, question 13: "The
       pass lays, the pass back takes off"]. js/motion.js marks what leaves
       `[data-kp-leaving]`, closes its space during the exit, and in a row of
       leaves starts the next one a tenth into this one. The line crosses back
       from the end and the part goes dark behind it, the film taken with it:
       the opening played backwards, in the same time. Opening is closing
       turned around (Kenny's pick on research/open-reverse, 2026-10-05): what
       arrives plays this leave backwards (js/motion.js), so it is laid from
       the start by the pass and the turn settles to cyan at the top, and
       frame t of the arrival is frame (T - t) of the leave. The line is
       drawn on the parts that can carry a pseudo-element: the alert, the key
       figure and the card (on ::before, its ::after being the plate); a row
       or any other part is taken off by the mask and the film alone. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] {
            --kp-open: reverse-close;
            /* A part a script removes or hides (the busy table's layer, a file
               row, an empty state, a re-shown alert) is taken off by the pass
               back first, as the pass lays it (js/motion.js leavesState(),
               lessons 19, 23, 24); what takes no box arrives as nothing; the
               space a leave folds shut takes the pass's own time and starts
               with it. */
            --kp-leave-state: leave;
            --kp-arrive-unseen: skip;
            --kp-leave-fold-grow: 1;
            --kp-leave-fold-start: 0;
        }

        [data-theme='dark'] :is(.kp-card, .kp-alert, .kp-kpi) {
            --kp-sig-dk-r: var(--kp-halo-reach, 2.5rem);
        }

        [data-theme='dark'] .kp-kpi {
            --kp-sig-dk-r: 0px;
        }

        /* The leave plays the pass's frames under their second names (the
           `-back` keyframes at the end of this layer), so a part whose
           entrance is the pass itself (a toast) starts its leave afresh
           instead of turning the finished entrance round in place (lesson 10;
           all-themes pass, 2026-10-13). The attribute is named twice: the
           entrance rule above names `dialog.kp-drawer` in its list, which
           outranks a single attribute, so a leaving toast kept its entrance
           and had no leave of its own to turn round into its arrival. */
        [data-theme='dark'] [data-kp-leaving][data-kp-leaving] {
            --kp-leave-stagger: 0.1;
            animation:
                kp-sig-dark-sweep-back var(--kp-sig-dk-time) linear reverse forwards,
                kp-sig-dark-film-back var(--kp-sig-dk-time) linear reverse forwards;
        }

        [data-theme='dark'] [data-kp-leaving]:is(.kp-alert, .kp-kpi, .kp-card:not([data-kp-label])) {
            position: relative;
        }

        [data-theme='dark'] [data-kp-leaving]:is(.kp-alert, .kp-kpi)::after,
        [data-theme='dark'] [data-kp-leaving].kp-card:not([data-kp-label])::before {
            content: '';
            position: absolute;
            inset: 0;
            z-index: 3;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-line-back var(--kp-sig-dk-time) linear reverse forwards;
        }
    }

    /* ── A key figure is a panel, and a warning is the film gone coral [G6,
       G7, G8; Kenny, 2026-10-09, questions 6, 7 and 8]. A tile that stands on
       its own is cut on the same two corners as the card, with the film along
       its edge; the plate stays near-black. A warning or a failure takes the
       tone's colour along the whole film edge (the warning ink for a warning,
       coral for a failure) and its change is set in that ink; there is no
       lamp, no tinted plate and no lit number. A destructive menu entry has
       a coral edge at its start and coral ink; a warning or failed alert is
       the same, with its label in the tone. The strip's columns keep the
       package's shared frames. ── */
    [data-theme='dark'] .kp-kpi:not(.kp-kpis[data-kp-kpis-columns] > .kp-kpi) {
        --kp-sig-dk-tone: transparent;
        position: relative;
        border-color: transparent;
        background:
            linear-gradient(var(--card), var(--card)) padding-box,
            var(--kp-iris) border-box;
        clip-path: polygon(
            0 0,
            calc(100% - var(--kp-chamfer-panel)) 0,
            100% var(--kp-chamfer-panel),
            100% 100%,
            var(--kp-chamfer-panel) 100%,
            0 calc(100% - var(--kp-chamfer-panel))
        );
    }

    [data-theme='dark'] .kp-kpi[data-kp-tone='warning'] {
        --kp-sig-dk-tone: var(--warning-foreground);
    }

    [data-theme='dark'] .kp-kpi[data-kp-tone='destructive'] {
        --kp-sig-dk-tone: var(--destructive);
    }

    [data-theme='dark'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) {
        box-shadow: none;
        --kp-sig-dk-ink-colour: var(--kp-sig-dk-tone);
    }

    [data-theme='dark'] .kp-kpi:not(.kp-kpis[data-kp-kpis-columns] > .kp-kpi):is([data-kp-tone='warning'], [data-kp-tone='destructive']) {
        border-color: transparent;
        background:
            linear-gradient(var(--card), var(--card)) padding-box,
            linear-gradient(var(--kp-sig-dk-tone), var(--kp-sig-dk-tone)) border-box;
    }

    [data-theme='dark'] .kp-kpi:is([data-kp-tone='warning'], [data-kp-tone='destructive']) .kp-kpi__value {
        padding-inline: 0;
        background: transparent;
        color: var(--kp-sig-dk-tone);
    }

    [data-theme='dark'] .kp-kpi[data-kp-tone='destructive']:where(.kp-kpis[data-kp-kpis-columns] > .kp-kpi) {
        border-color: var(--destructive);
    }

    [data-theme='dark'] .kp-kpi[data-kp-tone='warning']:where(.kp-kpis[data-kp-kpis-columns] > .kp-kpi) {
        border-color: var(--warning-foreground);
    }

    [data-theme='dark'] .kp-alert:is(.kp-alert--warning, .kp-alert--destructive) {
        background: var(--card);
        color: var(--foreground);
        border: 1px solid var(--kp-sig-dk-tone);
    }

    [data-theme='dark'] .kp-alert--warning {
        --kp-sig-dk-tone: var(--warning-foreground);
    }

    [data-theme='dark'] .kp-alert--destructive {
        --kp-sig-dk-tone: var(--destructive);
    }

    [data-theme='dark'] .kp-alert:is(.kp-alert--warning, .kp-alert--destructive) .kp-alert__label {
        color: var(--kp-sig-dk-tone);
    }

    [data-theme='dark'] .kp-menu__item--destructive {
        color: var(--destructive);
        box-shadow: inset 2px 0 0 var(--destructive);
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, rounds 3 and 4, 2026-10-05: shape 1, while
       loading 2 (round 4), how the share arrives 3 (round 4), when the tone
       changes 3, the mark past the end 3]. The package's own markup
       and states (setMeter(), js/kpi.js): the track on the meter, the share on
       ::before, the sign past the end or the loading picture on ::after, the
       mark `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise.
       Redrawn on the grammar [Kenny, 2026-10-09]: loading is the comet, the
       share is laid by the pass, a tone is the film gone coral. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='dark']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='dark']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='dark']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='dark']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='dark']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='dark']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='dark']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='dark']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 1 ── */

    /* ── dark · the machined channel ──────────────────────────────── */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.5rem;
        --kp-sig-meter-room: 0.625rem;
        --kp-sig-meter-cut: 3px;
        --kp-sig-meter-halo: var(--kp-meter-halo, var(--card));
        border-radius: 0;
        background:
            linear-gradient(
                    135deg,
                    var(--kp-sig-meter-halo) 0 calc(50% - 0.7px),
                    var(--border-strong) calc(50% - 0.7px) calc(50% + 0.7px),
                    transparent 0
                )
                0 0 / var(--kp-sig-meter-cut) var(--kp-sig-meter-cut) no-repeat,
            linear-gradient(
                    -45deg,
                    var(--kp-sig-meter-halo) 0 calc(50% - 0.7px),
                    var(--border-strong) calc(50% - 0.7px) calc(50% + 0.7px),
                    transparent 0
                )
                100% 100% / var(--kp-sig-meter-cut) var(--kp-sig-meter-cut) no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) var(--kp-sig-meter-cut) 0 / calc(100% - var(--kp-sig-meter-cut)) 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 100% / calc(100% - var(--kp-sig-meter-cut)) 1px no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 0 var(--kp-sig-meter-cut) / 1px calc(100% - var(--kp-sig-meter-cut)) no-repeat,
            linear-gradient(var(--border-strong), var(--border-strong)) 100% 0 / 1px calc(100% - var(--kp-sig-meter-cut)) no-repeat,
            var(--muted);
    }

    /* Bright machined metal, the oxide film along its top edge laid along
       the whole scale. */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)::before {
        inset: 1px;
        inline-size: calc(clamp(0, var(--kp-value, 0), 1) * (100% - 2px));
        border-radius: 0;
        background:
            var(--kp-sig-dk-meter-film, linear-gradient(90deg, var(--chart-1), var(--chart-2), var(--chart-3), var(--chart-4))) 0 0 /
                calc(100% / clamp(0.01, var(--kp-value, 0), 1)) 2px no-repeat,
            var(--kp-meter-fill-colour);
        clip-path: polygon(
            calc(var(--kp-sig-meter-cut) - 1px) 0,
            100% 0,
            100% calc(100% - var(--kp-sig-meter-cut) + 1px),
            calc(100% - var(--kp-sig-meter-cut) + 1px) 100%,
            0 100%,
            0 calc(var(--kp-sig-meter-cut) - 1px)
        );
    }

    /* A V milled into the edge, a dark cut through the metal. */
    [data-theme='dark'] .kp-meter__mark {
        inset-block: -1px;
        border-radius: 0;
        background: var(--background);
        box-shadow:
            1px 0 0 var(--primary),
            -1px 0 0 var(--primary);
    }

    [data-theme='dark'] .kp-meter__mark::before {
        content: '';
        position: absolute;
        inset-block-end: 100%;
        inset-inline-start: 50%;
        inline-size: 8px;
        block-size: 5px;
        translate: -50% 0;
        background: var(--primary);
        clip-path: polygon(0 0, 100% 0, 50% 100%);
    }

    /* The part runs out of the channel with a chamfered tip. */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        inset-inline-start: calc(100% + 2px);
        inset-block: 1px;
        inline-size: 0.4375rem;
        background:
            linear-gradient(90deg, var(--chart-4), var(--chart-1)) 0 0 / 100% 2px no-repeat,
            var(--kp-meter-fill-colour);
        clip-path: polygon(0 0, calc(100% - 3px) 0, 100% 50%, calc(100% - 3px) 100%, 0 100%);
    }

    /* ── while loading: option 2 ── */

    /* Loading is the comet, as everywhere [G10]: the 2 px line and its tail a
       third of the channel long cross it from start to end and lay nothing.
       The picture is the channel's own ::after, laid over the whole channel. */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        all: unset;
        content: '';
        position: absolute;
        inset: 1px;
        pointer-events: none;
        background-image: var(--kp-sig-dk-line), var(--kp-sig-dk-tail);
        background-repeat: no-repeat;
        background-size:
            2px 100%,
            calc(var(--kp-sig-dk-cw) * 100%) 100%;
        background-position:
            calc(50% * (1 + var(--kp-sig-dk-cw)) - 1px) 0,
            50% 0;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            animation: kp-sig-dark-comet var(--kp-sig-dk-loop) linear infinite;
        }
    }

    /* ── how the share arrives: the pass ── */

    /* The share is laid by the line from the start of the channel, 660 ms at
       one pace; a new share moves to its size in the contact time on the
       theme's curve. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-dark-meter-lay 660ms linear backwards;
            transition: inline-size var(--fx-duration) var(--fx-ease);
        }
    }

    /* ── when the tone changes: the film goes coral ── */

    /* A warning or a failure takes the tone's colour along the whole length of
       the share's film edge; the channel does not swell [G8]. */
    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning'] {
        --kp-sig-dk-meter-film: linear-gradient(var(--warning-foreground), var(--warning-foreground));
    }

    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive'] {
        --kp-sig-dk-meter-film: linear-gradient(var(--destructive), var(--destructive));
    }

    /* ── the mark past the end: option 3 ── */

    [data-theme='dark'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '▸';
    }

    [data-theme='dark'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
        rotate: 24deg;
        transform-origin: 50% 100%;
    }

    [data-theme='dark'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        rotate: -24deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-meter__mark {
            transition:
                inset-inline-start var(--fx-duration) var(--fx-ease),
                rotate var(--fx-duration) var(--fx-ease);
        }
    }

    @keyframes kp-sig-dark-meter-lay {
        from {
            mask-image: var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-size: 0px 100%;
        }

        to {
            mask-image: var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-size: 100% 100%;
        }
    }

    /* ── Every part that opens is laid by the pass and taken off by the pass
       back [G3, G13; lesson 38; all-themes pass, 2026-10-13]. The tour's card,
       its dim and ring, the calendar's busy layers and the bar's three
       closings take the pass the dialog and the menus already use (880 ms,
       the line at one pace); each close is the opening played backwards. The
       `-back` keyframes below are the same frames under a second name, so a
       close starts afresh instead of taking over the finished opening of the
       same name (lesson 10). ── */
    @media (prefers-reduced-motion: no-preference) {
        /* The tour's card is swept in where it stands as the dialog is (it had
           the package's 160 ms fade); js/motion.js playEntranceBackwards()
           turns it and its line round when the tour ends. A step is no
           arrival: the card plays no entrance again. */
        [data-theme='dark'] .kp-tour {
            --kp-sig-dk-r: var(--kp-halo-reach, 2.5rem);
        }

        [data-theme='dark'] .kp-tour[open]:not([data-kp-tour-stepping]) {
            animation:
                kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards,
                kp-sig-dark-film var(--kp-sig-dk-time) linear backwards;
        }

        [data-theme='dark'] .kp-tour[open]:not([data-kp-tour-stepping])::after {
            content: '';
            position: absolute;
            inset: 0;
            z-index: 3;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear backwards;
        }

        /* The page dims round the target and the ring comes in over the card's
           own pass, at its one pace (it was the package's 350 and 250 ms
           ease); css/components.css takes both back in the same time, the dim
           shrinking into the target as it grew out of it (lessons 11, 21,
           22). */
        [data-theme='dark'] {
            --kp-tour-dim-close: 0 0 0 0 transparent;
            --kp-tour-dim-time: var(--kp-sig-dk-time);
            --kp-tour-dim-close-ease: linear;
        }

        [data-theme='dark'] [data-kp-tour-target] {
            transition:
                box-shadow var(--kp-sig-dk-time) linear,
                outline-color var(--kp-sig-dk-time) linear;
        }

        /* The ring comes in only round a live tour's target (a frozen example
           on a page is no opening). */
        [data-theme='dark']:has(dialog.kp-tour[open]) [data-kp-tour-target] {
            animation: kp-sig-dark-tour-ring var(--kp-sig-dk-time) linear backwards;
        }

        @keyframes kp-sig-dark-tour-ring {
            from {
                outline-color: transparent;
            }
        }

        /* The calendar's busy layers are laid by the pass as anything that
           arrives and taken off by the pass back as anything that leaves:
           js/calendar.js marks a layer `[data-kp-leaving]` while its state goes
           (`--kp-calendar-busy-leave: hold`), and the rules below keep it drawn
           through the leave. */
        [data-theme='dark'] :is(.kp-calendar__day-busy, .kp-calendar__busy) {
            --kp-calendar-busy-leave: hold;
            transition: none;
        }

        [data-theme='dark']
            :is(.kp-calendar--busy-days, .kp-calendar--busy-whole:not(:has(> .kp-calendar__grid[aria-busy='true'])))
            .kp-calendar__day[data-kp-tone='loading']
            > .kp-calendar__day-busy:not([data-kp-leaving]),
        [data-theme='dark'] .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true']) > .kp-calendar__busy:not([data-kp-leaving]) {
            animation:
                kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards,
                kp-sig-dark-film var(--kp-sig-dk-time) linear backwards;
        }

        [data-theme='dark'] .kp-calendar__day:has(> .kp-calendar__day-busy[data-kp-leaving]) {
            position: relative;
        }

        [data-theme='dark'] .kp-calendar__day-busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-spinner, 0.75rem);
            position: absolute;
            inset-inline: 0;
            inset-block-end: 0.125rem;
            display: flex;
            justify-content: center;
            line-height: 0;
        }

        [data-theme='dark'] .kp-calendar--busy-whole > .kp-calendar__busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-busy-spinner, 2.5rem);
            z-index: 1;
            display: grid;
            place-self: center;
            place-items: center;
            padding: var(--kp-space-md, 1rem);
            border-radius: var(--radius, 0.5rem);
            background: var(--card);
            box-shadow: 0 0 0 1px var(--border);
            line-height: 0;
        }

        /* The busy table's rows dim and come back over the busy layer's own
           pass, at its one pace, so the table under the layer is part of the
           same pair (they changed at once). Two dims stand while a table is
           busy: its rows' (`--kp-datatable-busy-opacity`) and the whole
           table's (css/layout.css, `--kp-busy-opacity` on `[aria-busy]`); the
           whole table's was the one left in one frame, measured at the open's
           first frame (round 2, 2026-10-13: the wrapper at 0.7 at 1 ms). */
        [data-theme='dark'] .kp-datatable,
        [data-theme='dark'] .kp-datatable .kp-table tbody {
            transition: opacity var(--kp-sig-dk-time) linear;
        }

        /* The bar [Kenny via the coordinator, 2026-10-12: the navbar's opening
           and closing are in scope]. The dropdown and the mega menu were
           already swept in from the bar (G3) but closed at once in Firefox;
           the phone bar's panel opened with no pass of its own. Each now takes
           the pass back to close. Firefox does not hold `display`: the hover
           dropdown and the phone panel are held by the script for
           `--kp-nav-close-time`, the pass; the mega menu by a transition on
           --kp-sig-dk-hold (js/components.js settleClosing). */
        [data-theme='dark'] .kp-nav {
            --kp-nav-close-time: 880ms;
        }

        @container kp-nav (width > 40rem) {
            [data-theme='dark']
                .kp-nav__links
                > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open])
                > .kp-nav__menu:not(.kp-nav__menu--wide) {
                display: block;
                opacity: 1;
                animation:
                    kp-sig-dark-sweep-back var(--kp-sig-dk-time) linear reverse forwards,
                    kp-sig-dark-film-back var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark']
                .kp-nav__links
                > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open])
                > .kp-nav__menu:not(.kp-nav__menu--wide)::after {
                animation: kp-sig-dark-pass-line-back var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark'] .kp-nav__menu--wide {
                --kp-sig-dk-hold: 0;
                transition:
                    display var(--kp-sig-dk-time) allow-discrete,
                    --kp-sig-dk-hold var(--kp-sig-dk-time) linear;
            }

            [data-theme='dark']
                .kp-nav__links
                > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
                > .kp-nav__menu--wide {
                --kp-sig-dk-hold: 1;
            }

            [data-theme='dark']
                .kp-nav__links
                > li[data-kp-nav-closing]:not([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
                > .kp-nav__menu--wide {
                animation:
                    kp-sig-dark-sweep-back var(--kp-sig-dk-time) linear reverse forwards,
                    kp-sig-dark-film-back var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark']
                .kp-nav__links
                > li[data-kp-nav-closing]:not([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
                > .kp-nav__menu--wide::after {
                animation: kp-sig-dark-pass-line-back var(--kp-sig-dk-time) linear reverse forwards;
            }
        }

        /* The phone bar's panel is swept in under the bar from its start edge,
           its line crossing it, and taken off by the pass back. */
        @container kp-nav (max-width: 40rem) {
            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle) > .kp-nav__links {
                --kp-sig-dk-r: 0px;
                position: relative;
            }

            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
                animation:
                    kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards,
                    kp-sig-dark-film var(--kp-sig-dk-time) linear backwards;
            }

            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links::after {
                content: '';
                position: absolute;
                inset: 0;
                z-index: 3;
                background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
                filter: var(--kp-sig-dk-glow);
                opacity: 0;
                pointer-events: none;
                animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear backwards;
            }

            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-closing] > .kp-nav__links {
                animation:
                    kp-sig-dark-sweep-back var(--kp-sig-dk-time) linear reverse forwards,
                    kp-sig-dark-film-back var(--kp-sig-dk-time) linear reverse forwards;
            }

            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-closing] > .kp-nav__links::after {
                content: '';
                position: absolute;
                inset: 0;
                z-index: 3;
                background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
                filter: var(--kp-sig-dk-glow);
                opacity: 0;
                pointer-events: none;
                animation: kp-sig-dark-pass-line-back var(--kp-sig-dk-time) linear reverse forwards;
            }

            /* The panel is swept as one: its nested list is not swept again. */
            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) .kp-nav__links .kp-nav__menu {
                animation: none;
            }

            [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) .kp-nav__links .kp-nav__menu::after {
                content: none;
            }
        }
    }

    /* A reader who asked for no motion gets no close to wait for. */
    @media (prefers-reduced-motion: reduce) {
        [data-theme='dark'] .kp-nav {
            --kp-nav-close-time: 0ms;
        }
    }

    @keyframes kp-sig-dark-sweep-back {
        0% {
            mask-image: var(--kp-sig-dk-solid), var(--kp-sig-dk-solid), var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-origin: border-box;
            mask-clip: no-clip;
            mask-composite: add;
            mask-position:
                var(--kp-sig-dk-from) 0 top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(-1 * var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(100% + var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r));
            mask-size:
                0px calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        3% {
            mask-size:
                4% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        72% {
            mask-size:
                96% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                0px calc(100% + 2 * var(--kp-sig-dk-r));
        }

        75%,
        100% {
            mask-image: var(--kp-sig-dk-solid), var(--kp-sig-dk-solid), var(--kp-sig-dk-solid);
            mask-repeat: no-repeat;
            mask-origin: border-box;
            mask-clip: no-clip;
            mask-composite: add;
            mask-position:
                var(--kp-sig-dk-from) 0 top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(-1 * var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-from) calc(100% + var(--kp-sig-dk-r)) top calc(-1 * var(--kp-sig-dk-r));
            mask-size:
                100% calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r)),
                var(--kp-sig-dk-r) calc(100% + 2 * var(--kp-sig-dk-r));
        }
    }

    @keyframes kp-sig-dark-film-back {
        0% {
            --kp-sig-dk-turn: 0deg;
            animation-timing-function: linear;
        }

        75% {
            --kp-sig-dk-turn: 345deg;
            animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
        }

        100% {
            --kp-sig-dk-turn: 360deg;
        }
    }

    @keyframes kp-sig-dark-pass-line-back {
        0% {
            translate: calc(-100% * var(--kp-sig-dk-s)) 0;
            opacity: 0;
        }

        3% {
            translate: calc(-96% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        69% {
            translate: calc(-8% * var(--kp-sig-dk-s)) 0;
            opacity: 1;
        }

        75%,
        100% {
            translate: 0 0;
            opacity: 0;
        }
    }

    /* ── The alarm is a dialog: it is swept in where it stands (G3), review round 2 ──
       Kenny, 2026-10-13: "Dat gaat niet open/close met de animatie van Dark". The alarm ran the
       package's entrance (the plate faded in, the panel rose and scaled, the headline shrank into
       place, the reason faded after it), which js/motion.js only turned around. Now the alarm's
       own box, the whole screen, is laid by the dialog's pass: the line crosses it from its start
       edge at one pace and the plate, its frame, its glow, the panel and the words are laid behind
       it; the close is the pass back (js/motion.js plays this entrance backwards in the dialog's
       close time, `--kp-open: reverse-close`). The plate casts no halo, so the reach is none. The
       line is the vignette layer's ::after, the plate's own ::after being its breathing glow. The
       film's turn is left out: the alarm draws no film edge. The held-open frame in the
       catalogue (`[data-kp-alarm-inline]`, never `[open]`) stays still. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            --kp-sig-dk-r: 0px;
            animation: kp-sig-dark-sweep var(--kp-sig-dk-time) linear backwards;
        }

        [data-theme='dark'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) :is(.kp-alarm__panel, .kp-alarm__title, .kp-alarm__detail) {
            animation: none;
        }

        [data-theme='dark'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) .kp-alarm__scan::after {
            content: '';
            inset: 0;
            z-index: 3;
            block-size: auto;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-line var(--kp-sig-dk-time) linear backwards;
        }
    }

    /* ── The side navigation is swept in as the dialog is (G3, G13), review round 3 ──
       Kenny, 2026-10-13 22:12: "Niet de open/close animatie van dit thema". The panel that comes
       over the page or pushes it (and the window-edge panel of research/sidenav-edge) slid in on
       the package's 220 ms translate. It no longer slides: it stands where it opens, and the line
       crosses it from its start edge at one pace (660 ms, linear), laying the panel behind it, as
       the dialog's pass does; the close is the pass back, right to left, taking it off, frame for
       frame the opening backwards (880 ms both ways, `--kp-sig-dk-time`; the close plays the
       `-back` copies of the frames reversed, so it starts as an animation of its own). It casts no
       halo, so the reach is none; it draws no film edge, so there is no film turn (as the alarm).
       Shut, it stays in place and is hidden from the close's last frame. The content a push panel
       moves (and the edge tab) travels with the line: in the 660 ms of the pass and back in the
       last 660 ms of the close, at the line's one pace. js/sidenav.js copies the panel's
       `translate` timing to it; the panel's own translate never changes, so that timing is only
       the clock, written over the whole 880 ms with a held stretch (`linear()`, 660 / 880 = 75 %)
       so the move and the pass stay one pair. A backdrop, where a page asks for one, comes and
       goes over the same 880 ms at one pace. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) {
            --kp-sig-dk-r: 0px;
            translate: 0 0;
            visibility: hidden;
            animation: kp-sig-dark-sweep-back 880ms linear reverse forwards;
            transition:
                translate 880ms linear(0, 0 25%, 1),
                visibility 0s linear 880ms,
                inline-size var(--kp-sidenav-duration, var(--fx-duration)) var(--kp-sidenav-ease-back, var(--fx-ease));
        }

        [data-theme='dark'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true'] {
            visibility: visible;
            animation: kp-sig-dark-sweep 880ms linear backwards;
            transition:
                translate 880ms linear(0, 1 75%, 1),
                visibility 0s linear,
                inline-size var(--kp-sidenav-duration, var(--fx-duration)) var(--kp-sidenav-ease, var(--fx-ease));
        }

        [data-theme='dark'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])::after {
            content: '';
            position: absolute;
            inset: 0;
            z-index: 3;
            background: var(--kp-sig-dk-line) var(--kp-sig-dk-end) 0 / 2px 100% no-repeat;
            filter: var(--kp-sig-dk-glow);
            opacity: 0;
            pointer-events: none;
            animation: kp-sig-dark-pass-line-back 880ms linear reverse forwards;
        }

        [data-theme='dark'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true']::after {
            animation: kp-sig-dark-pass-line 880ms linear backwards;
        }

        [data-theme='dark'] .kp-sidenav__backdrop {
            animation: kp-sidenav-backdrop 880ms linear both;
        }
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — dark: near-black with a film on the edge. The current tab is a film line laid along the top edge by one pass from the start, a chamfered wash under it (G6, G7, G13); a count is chamfered, never rounded. */
    [data-theme='dark'] .kp-tabbar {
        box-shadow: 0 -1px 0 hsl(from var(--fx-signal) h s l / 0.22);
    }

    [data-theme='dark'] .kp-tabbar__tab {
        border-radius: 0;
        isolation: isolate;
    }

    [data-theme='dark'] .kp-tabbar__tab::before {
        inset-inline: 0;
        block-size: 1px;
        background: linear-gradient(90deg, transparent, var(--fx-signal) 18%, var(--fx-signal) 82%, transparent);
        transform-origin: 0 50%;
    }

    [data-theme='dark'] .kp-tabbar__tab:dir(rtl)::before {
        transform-origin: 100% 50%;
    }

    [data-theme='dark'] .kp-tabbar__tab::after {
        content: '';
        position: absolute;
        inset: 0;
        z-index: -1;
        background: linear-gradient(180deg, hsl(from var(--fx-signal) h s l / 0.14), transparent 70%);
        clip-path: polygon(var(--fx-notch) 0, 100% 0, 100% 100%, 0 100%, 0 var(--fx-notch));
        opacity: 0;
    }

    [data-theme='dark'] .kp-tabbar__tab[aria-current]:not([aria-current='false'])::after {
        opacity: 1;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-tabbar__tab::after {
            transition: opacity var(--fx-duration) var(--fx-ease);
        }
    }

    [data-theme='dark'] .kp-tabbar__badge {
        border-radius: 0;
        clip-path: polygon(3px 0, 100% 0, 100% calc(100% - 3px), calc(100% - 3px) 100%, 0 100%, 0 3px);
    }
}
/* ── End of the signature ── */

/* ── Segmented control, list toolbar, key line [kpadopt-controls] ── */
@layer kp.signature {
    [data-theme='dark'] .kp-segmented {
        --kp-seg-radius: 0;
        --kp-seg-pad: 3px;
        --kp-seg-size: 0.75rem;
