        --kp-chip-on: var(--accent);
        --kp-chip-on-ink: var(--primary);
        --kp-chip-on-edge: var(--primary);
    }
    [data-theme='dark'] .kp-toolbar {
        --kp-toolbar-group-gap: 1.125rem;
    }
    [data-theme='dark'] .kp-toolbar__label {
        letter-spacing: 0.1em;
    }
    [data-theme='dark'] .kp-keys {
