/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Dark's own (themes/dark/CHARACTER.md): a near-black plate with the film along the edge that matters, cut on two
   opposite corners, never rounded (G6, G7); pointing rests the line at the start edge (G15); a press turns the film a
   quarter while the line crosses the face (G17); a warning or failure is the film gone coral along its whole edge (G8);
   what waits is swept by the comet, the line with its film tail (G10); what runs is the line running its track (G11);
   readings in the ticker mono (G18). */
@layer kp.signature {
    [data-theme='dark'] .kp-actions {
        --kp-actions-gap: 0.625rem;
    }
    /* The tile: the near-black card inside the film, the control's chamfer. Its ring is DI2's two channels inside the
       cut, so the cut never takes a piece of it. */
    [data-theme='dark'] .kp-action {
        --kp-action-radius: 0;
        --kp-action-edge: transparent;
        --kp-action-edge-hover: transparent;
        --kp-action-press: 0 0;
        --kp-iris: conic-gradient(
            from calc(var(--kp-px, 0) * 1turn + var(--kp-sig-dk-turn)),
            var(--chart-1),
            var(--chart-2),
            var(--chart-3),
            var(--chart-4),
            var(--chart-1)
        );
        --kp-sig-dk-plate: var(--card);
        --kp-action-title-weight: 600;
        background:
            linear-gradient(var(--kp-sig-dk-plate), var(--kp-sig-dk-plate)) padding-box,
            var(--kp-iris) border-box;
        clip-path: var(--kp-sig-dark-cut);
    }
    [data-theme='dark'] .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        --kp-sig-dk-turn: 90deg;
        --kp-sig-dk-plate: var(--accent);
        background:
            linear-gradient(var(--kp-sig-dk-plate), var(--kp-sig-dk-plate)) padding-box,
            var(--kp-iris) border-box;
    }
    [data-theme='dark'] .kp-action:is(:disabled, [aria-disabled='true']) {
        background:
            linear-gradient(var(--muted), var(--muted)) padding-box,
            linear-gradient(var(--border), var(--border)) border-box;
    }
    /* The line rests at the start: a 2 px slice of the film with its one glow. */
    [data-theme='dark'] .kp-action::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 2px;
        background: var(--kp-sig-dk-line);
        box-shadow: 0 0 9px hsl(from var(--chart-1) h s l / 0.4);
        opacity: 0;
        pointer-events: none;
    }
    [data-theme='dark'] .kp-action:is(:hover, :active):not(:is(:disabled, [aria-disabled='true'], [aria-busy='true']))::before {
        opacity: 1;
    }
    [data-theme='dark'] .kp-action:focus-visible {
        outline: none;
        box-shadow:
            inset 0 0 0 var(--kp-focus-ring-inner-width, 2px) var(--focus-ring),
            inset 0 0 0 calc(var(--kp-focus-ring-inner-width, 2px) + 2px) var(--focus-ring-contrast);
    }
    /* Destructive: the film gone coral along the whole edge and the title in coral; no side bar. */
    [data-theme='dark'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) {
        --kp-iris: linear-gradient(var(--destructive), var(--destructive));
    }
    [data-theme='dark'] .kp-action--destructive::after {
        display: none;
    }
    [data-theme='dark'] .kp-action--destructive > .kp-action__title {
        color: var(--destructive);
    }
    [data-theme='dark'] .kp-action--destructive:is(:disabled, [aria-disabled='true']) > .kp-action__title {
        color: inherit;
    }
    [data-theme='dark'] .kp-action__meta {
        font-family: var(--theme-font-mono);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-action {
            transition: --kp-sig-dk-turn var(--fx-duration) cubic-bezier(0.64, 0, 0.78, 0);
        }
        [data-theme='dark'] .kp-action::before {
            transition: opacity var(--fx-duration) linear;
        }
        [data-theme='dark'] .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
            transition: --kp-sig-dk-turn var(--fx-duration) var(--kp-sig-dark-ease);
        }
    }

    /* Status rows: machined rows on the control's cut, square marks, the reading in the ticker mono. A failed row is
       the film gone coral; a loading row is a waiting surface, so the comet crosses it. */
    [data-theme='dark'] .kp-statuslist {
        --kp-statusrow-mark-radius: 0;
    }
    [data-theme='dark'] .kp-statusrow {
        --kp-statusrow-edge: var(--border-strong);
        --kp-statusrow-radius: 0;
        position: relative;
        clip-path: var(--kp-sig-dark-cut);
    }
    [data-theme='dark'] .kp-statusrow[data-state='failed'] {
        --kp-statusrow-state-edge: var(--destructive);
    }
    [data-theme='dark'] .kp-statusrow__detail {
        font-family: var(--theme-font-mono);
    }
    [data-theme='dark'] .kp-statusrow[data-state='loading']::before {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
        background-image: var(--kp-sig-dk-line), var(--kp-sig-dk-tail);
        background-repeat: no-repeat;
        background-size:
            2px 100%,
            calc(var(--kp-sig-dk-cw) * 100%) 100%;
        background-position:
            calc(50% * (1 + var(--kp-sig-dk-cw)) - 1px) 0,
            50% 0;
        opacity: 0.55;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-statusrow[data-state='loading']::before {
            animation: kp-sig-dark-comet var(--kp-sig-dk-loop) linear infinite;
        }
    }

    /* Facets: square rows; pointing rests the line at the row's start, as on a menu entry; counts are readings. The
       counts on their way are slots the comet crosses. */
    [data-theme='dark'] .kp-facets {
        --kp-facet-radius: 0;
    }
    [data-theme='dark'] .kp-facet {
        --kp-facet-hover: var(--accent);
        background-image: var(--kp-sig-dk-line);
        background-repeat: no-repeat;
        background-position: 0 0;
        background-size: 0 100%;
    }
    [data-theme='dark'] .kp-facet:hover {
        background-size: 2px 100%;
    }
    [data-theme='dark'] :is(.kp-facet__count, .kp-facets__title) {
        font-family: var(--theme-font-mono);
    }
    [data-theme='dark'] .kp-facets[aria-busy='true'] .kp-facet__count {
        border-radius: 0;
        background-color: var(--accent);
        background-image: var(--kp-sig-dk-line), var(--kp-sig-dk-tail);
        background-repeat: no-repeat;
        background-size:
            2px 100%,
            calc(var(--kp-sig-dk-cw) * 100%) 100%;
        background-position:
            calc(50% * (1 + var(--kp-sig-dk-cw)) - 1px) 0,
            50% 0;
        clip-path: var(--kp-sig-dark-cut);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-facet {
            transition:
                background-color var(--fx-duration) linear,
                background-size var(--fx-duration) linear;
        }
        [data-theme='dark'] .kp-facets[aria-busy='true'] .kp-facet__count {
            animation: kp-sig-dark-comet var(--kp-sig-dk-loop) linear infinite;
        }
    }

    /* Heat grid and matrix: square instrument cells with a lighter top edge where the tool left the surface;
       pointing rests the line on the cell's start edge (nothing grows); the pin is the film's cyan with its glow. */
    [data-theme='dark'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-radius: 0;
        --kp-heat-cell-lift: inset 0 1px 0 hsl(from var(--foreground) h s l / 0.16);
        --kp-heat-cell-hover: none;
        --kp-matrix-cell-hover: none;
    }
    [data-theme='dark'] .kp-heat {
        --kp-heat-gap-y: 6px;
    }
    [data-theme='dark'] .kp-matrix {
        --kp-matrix-gap: 4px;
    }
    [data-theme='dark'] .kp-heat__cell:hover:not(.kp-skeleton, [aria-disabled='true']),
    [data-theme='dark'] .kp-matrix__cell:hover:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
        box-shadow:
            inset 2px 0 0 var(--chart-1),
            inset 7px 0 9px -6px hsl(from var(--chart-1) h s l / 0.5);
    }
    [data-theme='dark'] .kp-heat__cell[data-kp-picked],
    [data-theme='dark'] .kp-matrix__cell[aria-pressed='true'] {
        outline: 2px solid var(--chart-1);
        outline-offset: 1px;
        box-shadow: 0 0 10px hsl(from var(--chart-1) h s l / 0.4);
    }
    [data-theme='dark'] :is(.kp-heat__label-button, .kp-matrix__name) {
        border-radius: 0;
    }
    [data-theme='dark'] .kp-heat__label-button[aria-pressed='true'] {
        background: var(--accent);
        color: var(--foreground);
        box-shadow: inset 2px 0 0 var(--chart-1);
    }
    [data-theme='dark'] :is(.kp-heat__col, .kp-matrix__col) {
        font-family: var(--theme-font-mono);
    }
    [data-theme='dark'] .kp-bar-cell {
        --kp-bar-cell-gap: var(--kp-space-sm, 0.5rem);
        font-family: var(--theme-font-mono);
        font-variant-numeric: tabular-nums;
    }

    /* Week agenda and run timeline: square slots with a lighter top edge where the tool left the surface and the
       series' ink on the start edge; the line for now is the film's 2 px cyan with its one glow; day names and the
       axis are microlabels in the ticker mono. A running run is the line running its track: a near-black slot in the
       film, crossed by the comet, again and again; no marching stripes. */
    [data-theme='dark'] .kp-week {
        --kp-week-pill-radius: 0;
        --kp-week-now: var(--chart-1);
    }
    [data-theme='dark'] .kp-gantt {
        --kp-gantt-state-ground: var(--card);
        --kp-gantt-bar-radius: 0;
        --kp-gantt-now: var(--chart-1);
    }
    [data-theme='dark'] :is(.kp-week__pill, .kp-gantt__run) {
        border-block-start-color: color-mix(in oklab, var(--kp-week-ink, var(--kp-gantt-fill, var(--foreground))) 55%, var(--foreground));
    }
    [data-theme='dark'] .kp-week__pill {
        border-inline-start: 2px solid var(--kp-week-ink);
    }
    [data-theme='dark'] .kp-week__pill:is(button):hover {
        box-shadow: inset 7px 0 9px -6px hsl(from var(--chart-1) h s l / 0.5);
        border-inline-start-color: var(--chart-1);
    }
    [data-theme='dark'] .kp-week__pill[data-kp-state='next'] {
        box-shadow:
            0 0 0 1px var(--chart-1),
            0 0 10px hsl(from var(--chart-1) h s l / 0.4);
    }
    [data-theme='dark'] :is(.kp-week__now, .kp-gantt__now) {
        filter: drop-shadow(0 0 5px hsl(from var(--chart-1) h s l / 0.6));
    }
    [data-theme='dark'] .kp-week__now::before {
        border-radius: 0;
        inline-size: 2px;
        block-size: 10px;
        inset-block-start: -6px;
        inset-inline-start: 0;
    }
    [data-theme='dark'] :is(.kp-week__head, .kp-week__axis, .kp-gantt__tick, .kp-week__time) {
        font-family: var(--theme-font-mono);
    }
    [data-theme='dark'] .kp-week__head {
        letter-spacing: 0.1em;
    }
    [data-theme='dark'] .kp-gantt__run:is(button):hover {
        box-shadow:
            inset 2px 0 0 var(--chart-1),
            0 0 0 1px var(--foreground);
    }
    [data-theme='dark'] .kp-gantt__run[data-kp-state='running'] {
        --kp-sig-dk-cw: 0.5;
        border-color: transparent;
        background:
            var(--kp-sig-dk-line) no-repeat,
            var(--kp-sig-dk-tail) no-repeat,
            linear-gradient(var(--accent), var(--accent)) padding-box,
            linear-gradient(90deg, var(--chart-1), var(--chart-2), var(--chart-3), var(--chart-4)) border-box;
        background-size:
            2px 100%,
            calc(var(--kp-sig-dk-cw) * 100%) 100%,
            auto,
            auto;
        background-position:
            calc(50% * (1 + var(--kp-sig-dk-cw)) - 1px) 0,
            50% 0,
            0 0,
            0 0;
        color: var(--foreground);
        box-shadow: inset -2px 0 0 var(--chart-1);
    }
    [data-theme='dark'] .kp-gantt__swatch[data-kp-state='running'] {
        background: var(--accent);
        border-color: var(--chart-1);
        box-shadow: inset 2px 0 0 var(--chart-1);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-gantt__run[data-kp-state='running'] {
            animation: kp-sig-dark-run var(--kp-sig-dk-loop) linear infinite;
        }
        [data-theme='dark'] .kp-facet:hover,
        [data-theme='dark'] .kp-week__pill {
            transition: box-shadow var(--fx-duration) linear;
        }
    }
    /* The comet over a bar whose own two grounds stay put: the head and the tail move, the plate and the film do not. */
    @keyframes kp-sig-dark-run {
        0% {
            background-position:
                calc(0% - 2px) 0,
                calc(-100% * var(--kp-sig-dk-cw) / (1 - var(--kp-sig-dk-cw))) 0,
                0 0,
                0 0;
        }

        75%,
        100% {
            background-position:
                calc(100% * (1 + var(--kp-sig-dk-cw)) - 2px) 0,
                calc(100% / (1 - var(--kp-sig-dk-cw))) 0,
                0 0,
                0 0;
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='dark'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='dark'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='dark'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='dark'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='dark'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='dark'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Dark's own (themes/dark/CHARACTER.md): the separator is the instrument's scale stood upright, a hairline
   fading at both ends with one lit tick at its middle in the chart cyan; lying down in the phone's list the tick stands
   on it. A day on the axis is a slot: pointing lights its edge, pressed it is the lit plate (the accent) with the edge
   and its glow, as a pointed tile is. A series' finished run carries the 2 px leading edge in its ink, as a week pill
   does. The facet pattern is a square on a machined rim. */
@layer kp.signature {
    [data-theme='dark'] .kp-nav__sep {
        position: relative;
        inline-size: 1px;
        border-inline-start: 0;
        background: linear-gradient(to bottom, transparent, var(--border-strong) 25%, var(--border-strong) 75%, transparent);
    }
    [data-theme='dark'] .kp-nav__sep::after {
        content: '';
        position: absolute;
        inset-block-start: calc(50% - 1px);
        inset-inline-start: -2px;
        inline-size: 5px;
        block-size: 2px;
        background: var(--chart-1);
        box-shadow: 0 0 6px hsl(from var(--chart-1) h s l / 0.6);
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            inline-size: auto;
            block-size: 1px;
            border-block-start: 0;
            background: linear-gradient(90deg, transparent, var(--border-strong) 12%, var(--border-strong) 88%, transparent);
        }
        [data-theme='dark'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep::after {
            inset-block-start: -2px;
            inset-inline-start: calc(50% - 1px);
            inline-size: 2px;
            block-size: 5px;
        }
    }

    [data-theme='dark'] .kp-gantt__tick:is(button) {
        border-radius: 0;
        text-decoration: none;
    }
    [data-theme='dark'] .kp-gantt__tick:is(button):hover {
        color: var(--foreground);
        box-shadow: inset 0 -2px 0 var(--chart-1);
    }
    [data-theme='dark'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: var(--accent);
        color: var(--foreground);
        box-shadow:
            inset 0 -2px 0 var(--chart-1),
            inset 0 -9px 9px -7px hsl(from var(--chart-1) h s l / 0.55);
    }
    [data-theme='dark'] .kp-gantt__run[data-kp-state='ok'][data-kp-series] {
        box-shadow: inset 2px 0 0 var(--kp-gantt-series);
    }
    [data-theme='dark'] .kp-gantt__run[data-kp-state='ok'][data-kp-series]:hover {
        box-shadow:
            inset 2px 0 0 var(--kp-gantt-series),
            0 0 0 1px var(--foreground);
    }
    [data-theme='dark'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 0;
        box-shadow: inset 0 0 0 1px hsl(from var(--foreground) h s l / 0.2);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-gantt__tick:is(button) {
            transition: box-shadow var(--fx-duration) linear;
        }
    }
}

/* ── The kpadopt4 components in dark's own grammar [kpadopt4] ──
   Dark is a spectral instrument (themes/dark/CHARACTER.md): a near-black plate with the film along the edge that matters,
   cut on two opposite corners and never rounded (G6, G7); the spectral line is the only light, and it passes: a part that
   is drawn is laid by the line left to right at one pace, 660 ms linear (G1, G2, G13); pointing rests the line at the start
   edge of the part (G15); a press turns the film a quarter (G17); a warning or failure is the film gone coral along its
   edge and nothing else (G8); what waits is crossed by the comet (G10), what runs is the line running its track (G11);
   readings and identifiers are in the ticker mono, words in Archivo (G18). The loading of every data area is the shared
   busy card and the comet the register already lays; nothing here fades, scales or blinks. */
@layer kp.signature {
    [data-theme='dark'] {
        --kp-dk4-c: 0.3rem;
        --kp-dk4-cut: polygon(0 0, calc(100% - var(--kp-dk4-c)) 0, 100% var(--kp-dk4-c), 100% 100%, var(--kp-dk4-c) 100%, 0 calc(100% - var(--kp-dk4-c)));
        --kp-dk4-cut-4: polygon(
            var(--kp-dk4-c) 0,
            calc(100% - var(--kp-dk4-c)) 0,
            100% var(--kp-dk4-c),
            100% calc(100% - var(--kp-dk4-c)),
            calc(100% - var(--kp-dk4-c)) 100%,
            var(--kp-dk4-c) 100%,
            0 calc(100% - var(--kp-dk4-c)),
            0 var(--kp-dk4-c)
        );
        --kp-dk4-film: linear-gradient(90deg, var(--chart-1), var(--chart-2) 36%, var(--chart-3) 68%, var(--chart-4));
        --kp-dk4-rest: 0 0 9px hsl(from var(--chart-1) h s l / 0.4);
        --kp-art-rule: var(--chart-1);
        --kp-art-line: var(--border-strong);
        --kp-art-ink: var(--muted-foreground);
        --kp-art-stroke: 1.5px;
    }

    /* ── Identity mark: a plate of the name's own colour, its edge the film in that colour, cut on two corners ── */
    [data-theme='dark'] .kp-idmark {
        --kp-idmark-radius: 0;
        --kp-idmark-tint: 22%;
        font-family: var(--theme-font-mono);
        font-weight: 600;
        letter-spacing: 0;
        clip-path: var(--kp-dk4-cut);
    }
    [data-theme='dark'] .kp-idmark--round {
        border-radius: 0;
        clip-path: var(--kp-dk4-cut-4);
    }
    [data-theme='dark'] .kp-idmark--glyph {
        clip-path: polygon(0 -30%, 130% -30%, 130% 100%, var(--kp-dk4-c) 100%, 0 calc(100% - var(--kp-dk4-c)));
    }
    [data-theme='dark'] .kp-idmark--glyph::after {
        box-shadow: none;
        border-radius: 0;
    }
    [data-theme='dark'] .kp-idmark--glyph[data-kp-idmark-glyph='circle']::after {
        border-radius: 0;
    }
    [data-theme='dark'] .kp-idmark[aria-current]:not([aria-current='false']),
    [data-theme='dark'] .kp-idmark[data-kp-idmark-selected] {
        box-shadow: none;
        clip-path: none;
        outline: 2px solid var(--primary);
        outline-offset: 2px;
    }
    [data-theme='dark'] .kp-idmark-group > .kp-idmark {
        box-shadow: none;
    }
    [data-theme='dark'] .kp-idmark-group__more {
        border-radius: 0;
        font-family: var(--theme-font-mono);
    }

    /* ── Share bar: the track is the machined channel (the progress bar's cut and ticks), the parts are laid by the line,
       the part pointed at takes the line at its start edge ── */
    [data-theme='dark'] .kp-stackbar {
        --kp-stackbar-radius: 0;
        --kp-stackbar-gap: 2px;
    }
    [data-theme='dark'] .kp-stackbar__title {
        font-weight: 600;
    }
    [data-theme='dark'] .kp-stackbar__total,
    [data-theme='dark'] .kp-stackbar__value {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
    }
    [data-theme='dark'] .kp-stackbar__bar {
        background:
            linear-gradient(90deg, transparent calc(100% - 1px), var(--border-strong) 0) 0 100% / 10% 45% repeat-x,
            var(--muted);
        box-shadow: inset 0 0 0 1px var(--border);
        clip-path: polygon(0.25rem 0, 100% 0, 100% calc(100% - 0.25rem), calc(100% - 0.25rem) 100%, 0 100%, 0 0.25rem);
    }
    [data-theme='dark'] .kp-stackbar__seg {
        border-radius: 0;
        box-shadow: inset calc(var(--kp-stackbar-gap, 2px) * -1) 0 0 var(--card);
        outline: 0;
    }
    [data-theme='dark'] .kp-stackbar__seg:dir(rtl) {
        box-shadow: inset var(--kp-stackbar-gap, 2px) 0 0 var(--card);
    }
    [data-theme='dark'] .kp-stackbar__seg::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 2px;
        background: var(--kp-sig-dk-line);
        box-shadow: var(--kp-dk4-rest);
        opacity: 0;
        pointer-events: none;
    }
    [data-theme='dark'] .kp-stackbar__seg[data-kp-stackbar-lit] {
        box-shadow: inset calc(var(--kp-stackbar-gap, 2px) * -1) 0 0 var(--card);
        filter: brightness(1.15);
    }
    [data-theme='dark'] .kp-stackbar__seg[data-kp-stackbar-lit]::before {
        opacity: 1;
    }
    [data-theme='dark'] .kp-stackbar__bar[data-kp-stackbar-full] .kp-stackbar__seg:last-of-type {
        box-shadow: none;
    }
    [data-theme='dark'] .kp-stackbar__mark {
        inset-block: -1px;
        background: var(--primary);
        box-shadow: 0 0 6px hsl(from var(--chart-1) h s l / 0.5);
    }
    [data-theme='dark'] .kp-stackbar__swatch {
        border-radius: 0;
    }
    [data-theme='dark'] .kp-stackbar__item[data-kp-stackbar-lit] {
        box-shadow: inset 2px 0 0 var(--chart-1);
    }
    [data-theme='dark'] .kp-stackbar__note {
        clip-path: var(--kp-dk4-cut);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-stackbar:not([aria-busy='true']) .kp-stackbar__bar > .kp-stackbar__seg {
            animation: kp-sig-dark-lay 660ms linear backwards;
        }
    }

    /* ── Bullet rows: the meter is dark's own; the figure is a reading, a tone is the film gone coral on its edge ── */
    [data-theme='dark'] .kp-bullets__figure {
        font-family: var(--theme-font-mono);
        font-size: 0.8125rem;
        border-radius: 0;
    }
    [data-theme='dark'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure,
    [data-theme='dark'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        background: transparent;
        padding-inline: 0.5em 0;
        box-shadow: inset 2px 0 0 currentColor;
    }
    [data-theme='dark'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure {
        color: var(--warning-foreground);
    }
    [data-theme='dark'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        color: var(--destructive);
    }
    [data-theme='dark'] .kp-bullets__row {
        position: relative;
    }
    [data-theme='dark'] .kp-bullets__row:has(.kp-bullets__link:is(:hover, :focus-visible))::before {
        content: '';
        position: absolute;
        inset-block: 2px;
        inset-inline-start: -0.5rem;
        inline-size: 2px;
        background: var(--kp-sig-dk-line);
        box-shadow: var(--kp-dk4-rest);
    }
    [data-theme='dark'] .kp-bullets__note {
        clip-path: var(--kp-dk4-cut);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-bullets:not([aria-busy='true']) .kp-bullets__row {
            animation: kp-sig-dark-lay 660ms linear backwards;
        }
        [data-theme='dark'] .kp-bullets:not([aria-busy='true']) .kp-bullets__row:nth-child(2) {
            animation-delay: 60ms;
        }
        [data-theme='dark'] .kp-bullets:not([aria-busy='true']) .kp-bullets__row:nth-child(3) {
            animation-delay: 120ms;
        }
        [data-theme='dark'] .kp-bullets:not([aria-busy='true']) .kp-bullets__row:nth-child(n + 4) {
            animation-delay: 180ms;
        }
    }

    /* ── Key-value grid and form rows: labels are microlabels, the values readings in the ticker mono where they are
       identifiers; a changed row carries the line at its start; a failed row is the film gone coral ── */
    [data-theme='dark'] .kp-kv__row > dt,
    [data-theme='dark'] .kp-formrow__label > small {
        font-size: 0.75rem;
        letter-spacing: 0.04em;
    }
    [data-theme='dark'] .kp-kv__row[data-kp-state='error']::before {
        background: var(--destructive);
        box-shadow: 0 0 8px hsl(from var(--destructive) h s l / 0.4);
    }
    [data-theme='dark'] .kp-kv__row[data-kp-changed] > dt::after {
        color: var(--chart-1);
    }
    [data-theme='dark'] .kp-formrow[data-kp-state='error']::before {
        background: var(--destructive);
        box-shadow: 0 0 8px hsl(from var(--destructive) h s l / 0.4);
    }
    [data-theme='dark'] .kp-formrows--lines > .kp-formrow,
    [data-theme='dark'] .kp-kv--lines > .kp-kv__row {
        border-image: linear-gradient(90deg, var(--border-strong) 0 90%, transparent) 1;
    }

    /* ── Code block: a panel with the film along its head, brackets on the title, the gutter in the ticker mono ── */
    [data-theme='dark'] .kp-code {
        --kp-code-bg: var(--muted);
        clip-path: var(--kp-dk4-cut);
        border-radius: 0;
    }
    [data-theme='dark'] .kp-code__head {
        position: relative;
        border-image: var(--kp-dk4-film) 1;
        border-block-end-width: 1px;
        border-block-end-style: solid;
    }
    [data-theme='dark'] .kp-code__title::before {
        content: '[ ';
        color: var(--chart-1);
    }
    [data-theme='dark'] .kp-code__title::after {
        content: ' ]';
        color: var(--chart-1);
    }
    [data-theme='dark'] .kp-code__title,
    [data-theme='dark'] .kp-code__meta {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
    }
    [data-theme='dark'] .kp-code[data-kp-state='error'] .kp-code__note {
        box-shadow: inset 2px 0 0 var(--destructive);
    }

    /* ── Page header line: the badge and freshness sit in the ticker mono ── */
    [data-theme='dark'] .kp-page-header__meta {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
    }

    /* ── A number that ticks: one pass over the figure; the letters take the film as the line crosses ── */
    [data-theme='dark'] [data-kp-tick] {
        font-family: var(--theme-font-mono);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] [data-kp-tick][data-kp-tick-state='running'] {
            background: var(--kp-dk4-film) 0 0 / 200% 100% no-repeat;
            background-clip: text;
            -webkit-background-clip: text;
            color: transparent;
            animation: kp-dk4-tick 660ms linear both;
        }
    }
    @keyframes kp-dk4-tick {
        from {
            background-position: 100% 0;
        }
        to {
            background-position: 0 0;
        }
    }
}
/* ── end the kpadopt4 data pieces ── */

/* ── The kpadopt4 rows, records and flows in dark's own grammar [kpadopt4] ──
   Rows rest the line at their start edge and are laid by the pass 60 ms apart (G2, G15); a state is the film gone to the
   tone's colour along the edge (G8); a plate that stands alone is cut on two corners (G6); a drawing for an empty state is
   the instrument's screen, laid by one pass left to right (G13, G19). */
@layer kp.signature {
    /* ── Rows with a lead (inbox, backlog, files, appointments) ── */
    [data-theme='dark'] .kp-action-list--lead {
        --kp-action-list-bar: 2px;
        --kp-action-list-next-wash: 0%;
    }
    [data-theme='dark'] .kp-action-list--lead > li {
        position: relative;
    }
    [data-theme='dark'] .kp-action-list--lead > li[data-kp-state='new'],
    [data-theme='dark'] .kp-action-list--lead > li[data-kp-state='next'] {
        border-image: var(--kp-sig-dk-line) 1;
    }
    [data-theme='dark'] .kp-action-list--lead > li[data-kp-state='warn'],
    [data-theme='dark'] .kp-action-list--lead > li[data-kp-state='failed'] {
        box-shadow: inset 2px 0 0 transparent;
    }
    [data-theme='dark'] .kp-action-list--lead > li[data-kp-state='failed'] {
        border-image: linear-gradient(var(--destructive), var(--destructive)) 1;
    }
    [data-theme='dark'] .kp-action-list--lead > li[data-kp-state='warn'] {
        border-image: linear-gradient(var(--warning-foreground), var(--warning-foreground)) 1;
    }
    [data-theme='dark'] .kp-action-list--lead > li[data-kp-state='active'] {
        border-image: linear-gradient(var(--chart-1), var(--chart-1)) 1;
    }
    [data-theme='dark'] .kp-action-list--lead > li:is(:hover, :focus-within)::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: -2px;
        inline-size: 2px;
        background: var(--kp-sig-dk-line);
        box-shadow: var(--kp-dk4-rest);
        pointer-events: none;
    }
    [data-theme='dark'] .kp-action-list--lead > li[data-kp-state='next'] > .kp-action-list__lead {
        color: var(--chart-1);
    }
    [data-theme='dark'] .kp-action-list__when,
    [data-theme='dark'] .kp-action-list__meta,
    [data-theme='dark'] .kp-action-list__payload {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
    }
    [data-theme='dark'] .kp-action-list__payload {
        border-radius: 0;
        clip-path: var(--kp-dk4-cut);
    }
    [data-theme='dark'] .kp-action-list > li.kp-action-list__group > :is(h2, h3, h4, h5, h6) {
        font-family: var(--theme-font-mono);
        letter-spacing: 0.04em;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-action-list--lead > li {
            animation: kp-sig-dark-lay 660ms linear backwards;
        }
        [data-theme='dark'] .kp-action-list--lead > li:nth-child(2) {
            animation-delay: 60ms;
        }
        [data-theme='dark'] .kp-action-list--lead > li:nth-child(3) {
            animation-delay: 120ms;
        }
        [data-theme='dark'] .kp-action-list--lead > li:nth-child(4) {
            animation-delay: 180ms;
        }
        [data-theme='dark'] .kp-action-list--lead > li:nth-child(n + 5) {
            animation-delay: 240ms;
        }
    }

    /* ── Status rows: the fix is a line of its own in the tone's film ── */
    [data-theme='dark'] .kp-statusrow__fix {
        padding-inline-start: 0.5rem;
        box-shadow: inset 2px 0 0 var(--kp-statusrow-state-edge, var(--border-strong));
    }
    [data-theme='dark'] .kp-statusrow[data-state='warn'] {
        --kp-statusrow-state-edge: var(--warning-foreground);
        --kp-statusrow-radius: 0;
        clip-path: var(--kp-dk4-cut);
    }

    /* ── Choices as tiles: a slot with the line resting at its start when pointed at; checked it takes the film
       along its whole edge and the accent plate ── */
    [data-theme='dark'] .kp-fieldset[data-kp-layout='tiles'] {
        --kp-field-tile-radius: 0;
        --kp-field-tile-ground-checked: var(--accent);
    }
    [data-theme='dark'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
        position: relative;
        clip-path: var(--kp-dk4-cut);
        border-color: var(--border);
    }
    [data-theme='dark'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 2px;
        background: var(--kp-sig-dk-line);
        box-shadow: var(--kp-dk4-rest);
        opacity: 0;
        pointer-events: none;
    }
    [data-theme='dark'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:is(:hover, :has(> .kp-field__check:checked)):not(:has(> .kp-field__check:disabled))::before {
        opacity: 1;
    }
    [data-theme='dark'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:hover:not(:has(> .kp-field__check:disabled)) {
        border-color: var(--border-strong);
    }
    [data-theme='dark'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:checked) {
        border-color: transparent;
        box-shadow: none;
        background:
            linear-gradient(var(--accent), var(--accent)) padding-box,
            var(--kp-iris, var(--kp-sig-dk-line)) border-box;
    }
    [data-theme='dark'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:focus-visible) {
        clip-path: none;
        outline-offset: -2px;
    }
    [data-theme='dark'] .kp-field__option-hint {
        font-family: var(--theme-font-body);
    }

    /* ── A card in four data states: the stage is laid by the pass when it fills; empty and failed keep the footprint ── */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-card[data-kp-state='ready'] > .kp-card__stage > .kp-card__data {
            animation: kp-sig-dark-lay 660ms linear backwards;
        }
    }
    [data-theme='dark'] .kp-card__failure {
        clip-path: var(--kp-dk4-cut);
    }

    /* ── Drawings for an empty state: the spectrum, the instrument's screen. Laid by one pass, 660 ms, left to right
       at one pace, then still. ── */
    [data-theme='dark'] .kp-art {
        display: block;
    }
    [data-theme='dark'] .kp-art > g[data-kp-art-set='spectrum'] {
        display: inline;
    }
    [data-theme='dark'] .kp-art path {
        stroke-linecap: butt;
        stroke-linejoin: miter;
    }
    [data-theme='dark'] .kp-art__rule {
        filter: drop-shadow(0 0 4px hsl(from var(--chart-1) h s l / 0.4));
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-art {
            animation: kp-sig-dark-lay 660ms linear backwards;
            --kp-sig-dk-cut: 0 100% 0 0;
        }
    }

    /* ── The pipeline: a lane is a slot with its stage's film on the head; a card rests the line at its start; the
       chosen card takes the film along its edge ── */
    [data-theme='dark'] .kp-pipeline__lane {
        border-radius: 0;
        clip-path: var(--kp-dk4-cut);
    }
    [data-theme='dark'] .kp-pipeline__head {
        border-radius: 0;
        border-color: transparent;
        background:
            linear-gradient(color-mix(in oklab, var(--kp-pipeline-tone) 16%, var(--card)), color-mix(in oklab, var(--kp-pipeline-tone) 16%, var(--card))) padding-box,
            linear-gradient(var(--kp-pipeline-tone), var(--kp-pipeline-tone)) border-box;
    }
    [data-theme='dark'] .kp-pipeline__head::before,
    [data-theme='dark'] .kp-pipeline__head::after {
        font-family: var(--theme-font-mono);
        color: var(--kp-pipeline-tone);
    }
    [data-theme='dark'] .kp-pipeline__name {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.04em;
    }
    [data-theme='dark'] .kp-pipeline__count,
    [data-theme='dark'] .kp-pipeline__share,
    [data-theme='dark'] .kp-pipeline__sub,
    [data-theme='dark'] .kp-pipeline__meta {
        font-family: var(--theme-font-mono);
    }
    [data-theme='dark'] .kp-pipeline__card {
        position: relative;
        border-radius: 0;
        clip-path: var(--kp-dk4-cut);
    }
    [data-theme='dark'] .kp-pipeline__card::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 2px;
        background: var(--kp-sig-dk-line);
        box-shadow: var(--kp-dk4-rest);
        opacity: 0;
        pointer-events: none;
    }
    [data-theme='dark'] .kp-pipeline__card:hover::before,
    [data-theme='dark'] .kp-pipeline__card[aria-current='true']::before {
        opacity: 1;
    }
    [data-theme='dark'] .kp-pipeline__card[aria-current='true'] {
        outline: 0;
        background:
            linear-gradient(var(--accent), var(--accent)) padding-box,
            var(--kp-iris, var(--kp-sig-dk-line)) border-box;
        border-color: transparent;
    }
    [data-theme='dark'] .kp-pipeline__mark {
        border-radius: 0;
    }
    [data-theme='dark'] .kp-pipeline__state {
        clip-path: var(--kp-dk4-cut);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-pipeline:not([aria-busy='true']) .kp-pipeline__lane {
            animation: kp-sig-dark-lay 660ms linear backwards;
        }
        [data-theme='dark'] .kp-pipeline:not([aria-busy='true']) .kp-pipeline__lane:nth-child(2) {
            animation-delay: 60ms;
        }
        [data-theme='dark'] .kp-pipeline:not([aria-busy='true']) .kp-pipeline__lane:nth-child(3) {
            animation-delay: 120ms;
        }
        [data-theme='dark'] .kp-pipeline:not([aria-busy='true']) .kp-pipeline__lane:nth-child(n + 4) {
            animation-delay: 180ms;
        }
    }

    /* ── The journey: one path, the line laid between the steps reached in the film, the mark a slot, the current step
       a mark with the film turning on its edge ── */
    [data-theme='dark'] .kp-steplist--journey {
        --kp-journey-rule: 2px;
    }
    [data-theme='dark'] .kp-steplist--journey .kp-steplist__mark {
        border-radius: 0;
        clip-path: var(--kp-dk4-cut-4);
    }
    [data-theme='dark'] .kp-steplist--journey > .kp-steplist__item:is([data-state='done'], [data-state='current'])::before {
        background: linear-gradient(90deg, var(--kp-step-tone, var(--chart-1)), var(--kp-step-tone, var(--chart-2)));
        box-shadow: var(--kp-dk4-rest);
    }
    [data-theme='dark'] .kp-steplist--journey > .kp-steplist__item + .kp-steplist__item:not([data-state='done'], [data-state='current'])::before {
        background: repeating-linear-gradient(90deg, var(--border-strong) 0 1px, transparent 1px 6px);
    }
    [data-theme='dark'] .kp-steplist--journey .kp-steplist__time {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
    }
    [data-theme='dark'] .kp-steplist__item[data-state='current'] .kp-steplist__mark {
        box-shadow: 0 0 0 1px var(--chart-1), var(--kp-dk4-rest);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-steplist--journey > .kp-steplist__item::before {
            animation: kp-sig-dark-lay 660ms linear backwards;
        }
    }

    /* ── Moments on the run timeline and the dated line: a mark is a slot, pointing rests the line on it, a zone is a
       band of film at 12 % with its start edge drawn ── */
    [data-theme='dark'] .kp-gantt__point:hover::before,
    [data-theme='dark'] .kp-gantt__point:focus-visible::before {
        box-shadow: var(--kp-dk4-rest);
    }
    [data-theme='dark'] .kp-gantt__count {
        font-family: var(--theme-font-mono);
        border-radius: 0;
    }
    [data-theme='dark'] .kp-gantt__zone {
        border-inline-start: 1px solid var(--border-strong);
    }
    [data-theme='dark'] .kp-gantt__mark {
        box-shadow: var(--kp-dk4-rest);
    }
    [data-theme='dark'] .kp-gantt--line .kp-gantt__track {
        border-radius: 0;
    }
}
/* ── end the kpadopt4 rows and flows ── */

/* ── The kpadopt4 secrets, time, cooking and commands in dark's own grammar [kpadopt4] ──
   A secret is a slot with a readout; the line that runs a countdown is the line running its track (G11); a clock is the
   film turning, the share left laid on a ticked face (G5, G19); a timer that ends is the film gone coral along its edge,
   the plate stays near-black (G8); a step, a pick, a figure is laid by the pass (G13); words are Archivo, readings the
   ticker mono (G18). Nothing blinks, nothing breathes. */
@layer kp.signature {
    /* ── Secret field ── */
    [data-theme='dark'] .kp-secret__value {
        border-radius: 0;
        border-color: var(--border-strong);
        background: var(--muted);
        clip-path: var(--kp-dk4-cut);
        font-family: var(--theme-font-mono);
    }
    [data-theme='dark'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__value {
        border-color: transparent;
        background:
            linear-gradient(var(--muted), var(--muted)) padding-box,
            var(--kp-iris, var(--kp-sig-dk-line)) border-box;
    }
    [data-theme='dark'] .kp-secret {
        --kp-secret-drain: var(--kp-dk4-film);
    }
    [data-theme='dark'] .kp-secret__drain {
        background: var(--kp-dk4-film);
        box-shadow: var(--kp-dk4-rest);
    }
    [data-theme='dark'] .kp-secret__line {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
    }
    [data-theme='dark'] .kp-secret[data-kp-secret-state='error'] .kp-secret__words {
        box-shadow: inset 2px 0 0 var(--destructive);
        padding-inline-start: 0.5rem;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__text {
            display: inline-block;
            animation: kp-sig-dark-lay 660ms linear backwards;
        }
    }

    /* ── Dialog in sections, confirmation, typed confirmation ── */
    [data-theme='dark'] .kp-dialog__heading {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.04em;
    }
    [data-theme='dark'] .kp-dialog__heading::before {
        content: '[ ';
        color: var(--chart-1);
    }
    [data-theme='dark'] .kp-dialog__heading::after {
        content: ' ]';
        color: var(--chart-1);
    }
    [data-theme='dark'] .kp-dialog__section:not(:first-child) {
        border-block-start-color: transparent;
        border-image: linear-gradient(90deg, var(--chart-1) 0 1.5rem, var(--border) 1.5rem) 1;
        border-block-start-width: 1px;
        border-block-start-style: solid;
    }
    [data-theme='dark'] .kp-dialog__section--danger {
        border-inline-start: 2px solid var(--destructive);
        border-image: none;
        box-shadow: -2px 0 8px -4px hsl(from var(--destructive) h s l / 0.5);
    }
    [data-theme='dark'] .kp-confirm__dependents,
    [data-theme='dark'] .kp-type-confirm__loses {
        border-radius: 0;
        clip-path: var(--kp-dk4-cut);
    }
    [data-theme='dark'] .kp-type-confirm__loses {
        border-inline-start-width: 2px;
    }
    [data-theme='dark'] .kp-type-confirm__name {
        border-radius: 0;
        font-family: var(--theme-font-mono);
        box-shadow: inset 0 -1px 0 var(--chart-1);
    }
    [data-theme='dark'] .kp-type-confirm__list,
    [data-theme='dark'] .kp-type-confirm__input {
        font-family: var(--theme-font-mono);
    }
    [data-theme='dark'] .kp-type-confirm[data-kp-matched] .kp-type-confirm__input {
        box-shadow: inset 0 -2px 0 var(--chart-1);
    }
    [data-theme='dark'] .kp-type-confirm__status {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
    }

    /* ── Segmented tri-state chips: the chip takes the film when it is in, the coral edge and a struck word when out ── */
    [data-theme='dark'] .kp-segmented--chips > .kp-segmented__item[data-kp-segmented-tri='include'] {
        border-color: transparent;
        background:
            linear-gradient(var(--accent), var(--accent)) padding-box,
            var(--kp-dk4-film) border-box;
    }
    [data-theme='dark'] .kp-segmented--chips > .kp-segmented__item[data-kp-segmented-tri='exclude'] {
        border-color: var(--destructive);
        box-shadow: inset 2px 0 0 var(--destructive);
    }
    [data-theme='dark'] .kp-segmented__mark {
        border-radius: 0;
    }
    [data-theme='dark'] .kp-segmented__summary {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
    }

    /* ── Quantity: a slot between two dark buttons; the reading in the ticker mono, the line under it when focused ── */
    [data-theme='dark'] .kp-quantity__field {
        border-radius: 0;
        clip-path: var(--kp-dk4-cut);
    }
    [data-theme='dark'] .kp-quantity__input,
    [data-theme='dark'] .kp-quantity__unit {
        font-family: var(--theme-font-mono);
    }
    [data-theme='dark'] .kp-quantity__field:has(.kp-quantity__input:focus-visible) {
        clip-path: none;
    }

    /* ── Checklist: a row rests the line at its start; a ticked item is the film struck through it ── */
    [data-theme='dark'] .kp-checklist__row {
        position: relative;
        border-radius: 0;
    }
    [data-theme='dark'] .kp-checklist__row:hover::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 2px;
        background: var(--kp-sig-dk-line);
        box-shadow: var(--kp-dk4-rest);
        pointer-events: none;
    }
    [data-theme='dark'] .kp-checklist__title,
    [data-theme='dark'] .kp-checklist__count,
    [data-theme='dark'] .kp-checklist__status {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.04em;
    }
    [data-theme='dark'] .kp-checklist__item[data-kp-checklist-checked] .kp-checklist__label {
        text-decoration-color: var(--chart-1);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-checklist__item {
            animation: kp-sig-dark-lay 660ms linear backwards;
        }
    }

    /* ── Kitchen timers: a slot with the film on its edge; a timer that has ended is the coral film, never a lit plate ── */
    [data-theme='dark'] .kp-timer {
        --kp-timer-font: var(--theme-font-mono);
        border-radius: 0;
        clip-path: var(--kp-dk4-cut);
    }
    [data-theme='dark'] .kp-timer[data-kp-timer-state='done'] {
        --kp-timer-done-ground: var(--card);
        --kp-timer-done-ink: var(--card-foreground);
        --kp-timer-done-edge: var(--destructive);
        box-shadow: inset 2px 0 0 var(--destructive);
    }
    [data-theme='dark'] .kp-timer[data-kp-timer-state='done'] .kp-timer__state {
        color: var(--destructive);
    }
    [data-theme='dark'] .kp-timer__time,
    [data-theme='dark'] .kp-timer__state {
        font-family: var(--theme-font-mono);
    }

    /* ── Cook mode: the step is laid by the pass when it changes; the ingredients are a panel with the film at its start ── */
    [data-theme='dark'] .kp-focus-steps__count,
    [data-theme='dark'] .kp-focus-steps__amount {
        font-family: var(--theme-font-mono);
    }
    [data-theme='dark'] .kp-focus-steps__needs {
        border-radius: 0;
        clip-path: var(--kp-dk4-cut);
        box-shadow: inset 2px 0 0 var(--chart-1);
    }
    [data-theme='dark'] .kp-focus-steps__needs-title {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.04em;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='dark'] .kp-focus-steps__step {
            animation: kp-sig-dark-lay 660ms linear backwards;
        }
    }

    /* ── Wheel: the rim is the film, the pointer a 2 px line with its glow, the pick settles on dark's own settle ── */
    [data-theme='dark'] .kp-wheel {
        --kp-wheel-ease: var(--kp-settle, cubic-bezier(0.22, 1, 0.36, 1));
        --kp-wheel-pointer: var(--chart-1);
        --kp-wheel-tint: 24%;
    }
    [data-theme='dark'] .kp-wheel__segment {
        stroke: var(--background);
        stroke-width: 0.8;
    }
    /* The hub carries none of the button's plates, frames or labels on its pseudo-elements: a round disc stays round
       [cook-1017; Kenny 2026-10-17: no square frame round the spin hub in any theme]. */
    [data-theme='dark'] .kp-wheel__spin.kp-button::before,
    [data-theme='dark'] .kp-wheel__spin.kp-button::after {
        content: none !important;
    }
    [data-theme='dark'] .kp-wheel__rim {
        stroke: var(--chart-1);
        stroke-width: 1;
    }
    [data-theme='dark'] .kp-wheel__pointer {
        stroke: none;
        filter: drop-shadow(0 0 4px hsl(from var(--chart-1) h s l / 0.6));
    }
    [data-theme='dark'] .kp-wheel__label {
        font-family: var(--theme-font-mono);
