    [data-theme='formal'] .kp-field__check {
        --kp-sig-dur: var(--fx-duration);
        appearance: none;
        display: inline-grid;
        place-content: center;
        inline-size: 1.15rem;
        block-size: 1.15rem;
        margin: 0;
        border: 1px solid var(--border-strong);
        border-radius: 0;
        background: var(--background);
