    [data-theme='formal'] .kp-field__check[type='checkbox']:checked {
        border-color: var(--primary);
        background: var(--primary);
    }

    [data-theme='formal'] .kp-field__check[type='checkbox']:checked::before {
        content: '';
        inline-size: 0.62rem;
        block-size: 0.32rem;
