/* A clock with nothing drawn on it: the bar's mega menu is held on screen
   until a transition on its panel has played (js/components.js); this is
   that transition, the length of the panel's close. */
@property --kp-sig-solstice-hold {
    syntax: '<number>';
    inherits: false;
    initial-value: 0;
}

@layer kp.register {
    /* @kp-soft/themes — css/solstice-register.css
   The solstice register, 5.0.0 [S48, S49]: warm dark, no neon. The
   approved concept demo ("Low Sun", 2026-09-08) is the reference for
   every value here; its own header comment names the two measured
   sources (a display-serif recipe and a colour triad) and the hazards it
   refuses. `themes/solstice/anatomy.md` is the idea in words; this file
   is the idea in rules.

   The character is an hour of the day, not a filter: charcoal warmed by
   a trace of red, amber leading, rust following, a serif for display
   because warmth reads better with a little contrast in the letterforms,
   and the softest radius in the set because sharp corners fight the
   warmth. Nothing here is a bevel, a scanline or a grid — DI9's texture
   answer is "no texture, no register" (anatomy.md), and there is none.

   Colour discipline (DI9): nothing here names a colour; every value is
   var(--token) or a relative colour of one. Two knobs are new for this
   theme and shared by nothing else: --kp-cal-* (the calibration wipe)
   and --kp-redact-* (the dossier's redaction lift) — both one-shot,
   both monotonic, both inside the no-preference guard at the bottom of
   this file, so DI5 counts zero opposing changes for either. */

    [data-theme='solstice'] {
        /* The configuration surface [AR43], the demo's own values as
       defaults. */
        --kp-reveal-threshold: 0.6;
        --kp-reveal-stagger: 260ms;
        --kp-classified-delay: 1500ms;
        --kp-cal-duration: 520ms;
        --kp-cal-stagger: 110ms;
        --kp-rule-duration: 480ms;
        --kp-rule-delay: 260ms;
        --kp-redact-duration: 320ms;
        --kp-redact-stagger: 110ms;
        /* The reveals this theme performs [S45]: js/effects.js reads
       these and leaves a theme that declares none at rest. */
        --kp-reveal-headline: calibrate;
        --kp-reveal-emphasis: redact;
        --kp-reveal-rule: draw;
        /* No arrival: the demo's script wires the dropdown, the dossier
       and the wipe dialog only — nothing counts up on first paint
       (anatomy.md, "what it deliberately does not do"). */

        /* The calibration wipe's three bands, in the demo's own order:
       primary, accent, foreground — the same triad the swatches show. A
       relative colour is not needed here; each band names a token
       directly, which is the DI9-preferred form when a plain token IS
       the value. */
        --kp-cal-bands: linear-gradient(90deg, var(--primary) 0% 33.333%, var(--accent) 33.333% 66.666%, var(--foreground) 66.666% 100%);
        /* A translucent version of the ground itself, standing in for the
       demo's literal near-black shadow (DI9: no colour of the page's
       own is available here, so the page's own darkest surface is). */
        --kp-shadow-soft: hsl(from var(--background) h s l / 0.45);
        --kp-shadow-deep: hsl(from var(--background) h s l / 0.55);
        --kp-shadow-hair: hsl(from var(--background) h s l / 0.3);
        /* A part a script removes or hides (the busy table's layer, a file
           row, a tree's children, a re-shown alert) leaves first, as it
           arrives: js/motion.js leavesState() (lessons 19, 37). What takes no
           box arrives as nothing (lesson 23). The space a leave folds shut
           takes the leave's own time and starts with it, so arriving and
           leaving are one picture of one length (lesson 24). */
        --kp-leave-state: leave;
        --kp-arrive-unseen: skip;
        --kp-leave-fold-grow: 1;
        --kp-leave-fold-start: 0;
    }

    /* ── Type ──────────────────────────────────────────────────────────── */

    [data-theme='solstice'] h1,
    [data-theme='solstice'] h2,
    [data-theme='solstice'] h3 {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }

    [data-theme='solstice'] .microlabel {
        font-family: var(--theme-font-mono);
        font-weight: 600;
        font-size: 0.75rem;
        line-height: 1.2;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    /* ── The hooks [S45]: the headline, the mark, the rule, the divider ── */

    /* The headline: the calibration wipe. Three flat bands in the demo's
       triad sit over the text with mix-blend-mode: difference and slide
       away to their own right edge; the text itself is solid var(--fg)
       underneath from first paint, so a page without the module — or a
       theme answering quietly — simply shows the headline (anatomy: the
       hazard note on Moranta's blend mode, confined here to a one-shot
       decorative overlay, never to anything that must stay legible after
       it settles). */
    [data-theme='solstice'] [data-kp-reveal='headline'] {
        position: relative;
        display: inline-block;
        overflow: hidden;
        max-width: 100%;
    }

    [data-theme='solstice'] [data-kp-reveal='headline']::after {
        content: '';
        position: absolute;
        inset: 0;
        background-image: var(--kp-cal-bands);
        mix-blend-mode: difference;
        pointer-events: none;
        opacity: 0;
    }

    [data-theme='solstice'][data-kp-effects] [data-kp-reveal='headline']:not(.is-deciphered)::after {
        opacity: 1;
    }

    /* The rule: a plain scaleX(0→1) draw, left to right, when the heading
       enters the viewport — the demo's own mechanism, unornamented. */
    [data-theme='solstice'] [data-kp-reveal='rule']::after {
        content: '';
        display: block;
        block-size: 3px;
        margin-block-start: 0.6rem;
        background: var(--primary);
        transform-origin: left center;
        transform: scaleX(1);
    }

    [data-theme='solstice'][data-kp-effects] [data-kp-reveal='rule']:not(.is-in)::after {
        transform: scaleX(0);
    }

    /* The lede's mark: the base layer's warning plate already matches the
       demo (background var(--warning), color var(--warning-foreground));
       this only adds the demo's own corner and box-decoration. */
    [data-theme='solstice'] mark {
        border-radius: 3px;
        box-decoration-break: clone;
        -webkit-box-decoration-break: clone;
    }

    /* The divider: the demo's horizon seam, without the SVG the shared
       markup has no room for (an empty [data-kp-divider] div — S49
       finding, recorded in anatomy.md). A hairline plus one accent peak
       carries the idea: a low sun just above or just below the line. */
    [data-theme='solstice'] [data-kp-divider] {
        display: block;
        block-size: 28px;
        background:
            conic-gradient(from 225deg at 50% 100%, transparent 0deg 45deg, var(--accent) 45deg 90deg, transparent 90deg 135deg) center / 46px 22px
                no-repeat,
            linear-gradient(var(--border), var(--border)) center / 100% 1px no-repeat;
    }

    [data-theme='solstice'] [data-kp-divider='alt'] {
        background:
            conic-gradient(from 45deg at 50% 0%, transparent 0deg 45deg, var(--primary) 45deg 90deg, transparent 90deg 135deg) center / 46px 22px
                no-repeat,
            linear-gradient(var(--border), var(--border)) center / 100% 1px no-repeat;
    }

    /* ── The hero ─────────────────────────────────────────────────────── */

    [data-theme='solstice'] [data-kp-surface='hero'] {
        padding-block: clamp(3rem, 8vw, 6rem) clamp(2.5rem, 6vw, 4rem);
    }

    [data-theme='solstice'] [data-kp-surface='hero'] h1 {
        letter-spacing: -0.04em;
    }

    /* ── Nav: chrome, no bevel — a warm strip over the app ─────────────── */

    [data-theme='solstice'] .kp-nav-wrap {
        background: var(--card);
        border-bottom: 1px solid var(--border);
    }

    [data-theme='solstice'] .kp-nav {
        gap: 0.75rem 1.5rem;
    }

    [data-theme='solstice'] .kp-nav__brand {
        font-family: var(--theme-font-display);
        font-weight: 400;
        font-size: 1.35rem;
        letter-spacing: -0.01em;
    }

    [data-theme='solstice'] .kp-nav__link {
        color: var(--muted-foreground);
    }

    [data-theme='solstice'] .kp-nav__link:hover {
        color: var(--primary);
        background: none;
    }

    [data-theme='solstice'] .kp-nav__link--lang {
        text-transform: uppercase;
        letter-spacing: 0.06em;
    }

    /* The dropdown caret: one glyph, drawn by content, never a word
       [KT5] — the demo's own ⌄, not a borrowed arrow. */
    [data-theme='solstice'] .kp-nav__link[aria-haspopup]::after {
        content: ' ⌄';
        font-size: 0.7em;
        opacity: 0.8;
    }

    /* The dropdown (KT14): the demo's popover, opened and read before
       this register was called done. */
    [data-theme='solstice'] .kp-nav__menu {
        background: var(--popover);
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        padding: 0.4rem;
        box-shadow: 0 12px 28px var(--kp-shadow-soft);
    }

    /* Collapsed, the dropdown is a list in the flow, not a panel [gap-12]:
       the rule above dresses the floating panel in kp.register, which
       beats the reset in kp.components, so the reset is restated here. */
    @container kp-nav (max-width: 40rem) {
        [data-theme='solstice'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open] .kp-nav__menu {
            min-width: 0;
            padding-inline-start: var(--kp-nav-menu-indent, 1rem);
            border: 0;
            background: transparent;
            box-shadow: none;
        }
    }

    [data-theme='solstice'] .kp-nav__menu a {
        border-radius: calc(var(--radius) - 3px);
        padding-inline: 0.6rem;
    }

    [data-theme='solstice'] .kp-nav__menu a:hover,
    [data-theme='solstice'] .kp-nav__menu a:focus-visible {
        background: var(--muted);
        color: var(--primary);
    }

    /* Room between the words and the plate's edge (Kenny, 2026-09-15,
       page-effects#nav-cta, cta-plates "Gelijktrekken" [scope-93]): the
       link had 0px inline padding, so the plate ended at the first and
       last letter. The same 16px as formal's plate. */
    [data-theme='solstice'] .kp-nav__link--cta {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--radius);
        font-weight: 600;
        padding-inline: var(--kp-space-lg, 1rem);
    }

    [data-theme='solstice'] .kp-nav__link--cta:hover {
        background: hsl(from var(--primary) h s calc(l + 8));
        color: var(--primary-foreground);
    }

    /* ── Buttons: no bevel, one soft accent highlight [S49, A7] ────────── */

    [data-theme='solstice'] .kp-button,
    [data-theme='solstice'] .kp-icon-button {
        border-radius: var(--radius);
        font-weight: 600;
    }

    /* On an alert the close button sits on the alert's own plate, in the
       alert's ink, the way it does on a toast [fix-95]. */
    [data-theme='solstice'] .kp-alert .kp-icon-button {
        background: transparent;
        border-color: transparent;
        color: inherit;
    }

    /* Pointing and pressing are not painted here: every pressable part
       answers to the same two numbers, drawn once in the signature layer
       (the sun climbs its arc under the pointer, the sun swells inside a
       press), so no variant has a hover face of its own. Rest only. */
    [data-theme='solstice'] .kp-button--ghost {
        border-color: var(--border-strong);
    }

    [data-theme='solstice'] .kp-button--destructive {
        background: transparent;
        color: var(--destructive);
        border-color: var(--destructive);
    }

    /* The demo's answer to "mirror" [S49, A7]: a thin calibration-bar
       highlight riding the top and bottom inset edges, echoing the
       headline's fg/ink pair — this theme carries no gradients
       (anatomy.md), so this is a highlight, not a flip. One rule for every
       mirror button: a second, identical rule for the primary mirror was
       merged into it [scope-100], since nothing in this layer gives the
       primary button a box-shadow of its own to beat. */
    [data-theme='solstice'] .kp-button--mirror {
        box-shadow:
            inset 0 2px 0 hsl(from var(--foreground) h s l / 0.35),
            inset 0 -2px 0 hsl(from var(--primary-foreground) h s l / 0.25);
    }

    /* Focus is a halo [Kenny's pick on research/solstice-character, 2026-10-07]:
       a 3 px double rust ring standing 3 px off the part, in place of the
       global two-channel ring (DI2). One rule for every focusable part; the
       mirror button keeps its highlight untouched by it. */
    [data-theme='solstice'] :focus-visible {
        outline: 3px double var(--accent);
        outline-offset: 3px;
        box-shadow: none;
    }

    [data-theme='solstice'] .kp-button--mirror:focus-visible {
        box-shadow:
            inset 0 2px 0 hsl(from var(--foreground) h s l / 0.35),
            inset 0 -2px 0 hsl(from var(--primary-foreground) h s l / 0.25);
    }

    /* ── Fields: wells with the softest radius in the set ──────────────── */

    [data-theme='solstice'] .kp-field__label {
        font-weight: 600;
    }

    [data-theme='solstice'] .kp-field__required {
        font-weight: 600;
        font-size: 0.625rem;
        text-transform: uppercase;
        letter-spacing: 0.08em;
        color: var(--muted-foreground);
    }

    [data-theme='solstice'] .kp-field__input {
        border-radius: calc(var(--radius) - 2px);
        border-color: var(--border-strong);
    }

    /* Invalid wins over this register's own field border [gap-11]: the rule
       above sets the border in kp.register, which beats
       .kp-field--invalid in kp.components, so an invalid field painted
       exactly like a valid one. */
    [data-theme='solstice'] .kp-field--invalid .kp-field__input {
        border-color: var(--destructive);
    }

    [data-theme='solstice'] .kp-field__help {
        color: var(--muted-foreground);
    }

    [data-theme='solstice'] .kp-field__error {
        color: var(--destructive);
    }

    [data-theme='solstice'] .kp-fieldset {
        border: 1px solid var(--border);
        border-radius: var(--radius);
    }

    /* The switch [gap-11]: the pill, on the page's ground with the inputs' edge. */
    [data-theme='solstice'] .kp-switch {
        --kp-switch-radius: var(--kp-radius-pill, 999px);
    }

    [data-theme='solstice'] .kp-switch__input:not(:checked) {
        background: var(--background);
        border-color: var(--border-strong);
    }

    [data-theme='solstice'] .kp-form__summary {
        border: 1px solid var(--border-strong);
        border-radius: var(--radius);
        background: var(--card);
    }

    /* ── Cards, windows and containers ─────────────────────────────────── */

    [data-theme='solstice'] .kp-card {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-card__title {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }

    /* The dossier: the stamp rides a slight rotation the way a printed
       tag would sit on a folder, and the redactions are the mark hook's
       own emphasis reveal, styled below. */
    [data-theme='solstice'] .kp-card[data-kp-label]::before {
        content: attr(data-kp-label);
        rotate: -2deg;
        background: var(--accent);
        color: var(--accent-foreground);
        font-weight: 700;
        font-size: 0.6875rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        border-radius: 4px;
        padding: 0.35rem 0.6rem;
    }

    [data-theme='solstice'] .kp-card[data-kp-open]::before {
        content: attr(data-kp-label-open);
    }

    /* The redactions: three marks inside the dossier, covered by a bar in
       the theme's own boundary colour until the trigger opens the file,
       then lifted one after another, right to left — the demo's own
       clip-path direction. The bar is the phrase's own background, 1px
       inside its padding and cloned onto every line the phrase takes, so a
       phrase that wraps is covered line by line [fix-33, scope-93]; a bar
       on an absolutely positioned ::after covered none of it. A background
       paints under the words rather than over them, and the bar is not the
       words' colour, so the words wear no ink while the bar is there and
       take it back once their bar has gone. */
    [data-theme='solstice'] .kp-card[data-kp-reveal='emphasis'] mark {
        position: relative;
        background: linear-gradient(var(--border-strong), var(--border-strong)) 1px center / calc(100% - 2px) calc(100% - 2px) no-repeat;
        color: transparent;
        padding: 0.05em 0.15em;
        font-weight: 400;
        border-radius: 3px;
        box-decoration-break: clone;
        -webkit-box-decoration-break: clone;
    }

    [data-theme='solstice'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared {
        background-size: 0% calc(100% - 2px);
        color: var(--card-foreground);
    }

    /* Windows: a plain popover panel with the demo's soft drop shadow —
       no bevel, no ramp; the softest radius in the set doing the work
       DI9's "no texture" leaves it to do. */
    [data-theme='solstice'] .kp-dialog,
    [data-theme='solstice'] .kp-popover,
    [data-theme='solstice'] .kp-menu,
    [data-theme='solstice'] .kp-toast,
    [data-theme='solstice'] .kp-tooltip,
    [data-theme='solstice'] .kp-confirm,
    [data-theme='solstice'] .kp-datepicker__panel,
    [data-theme='solstice'] .kp-combobox__list,
    [data-theme='solstice'] .kp-palette,
    [data-theme='solstice'] .kp-theme-menu__list {
        box-shadow: 0 24px 56px var(--kp-shadow-deep);
    }

    /* The wrapper round the theme picker's icon button is not a card: only its
       dropdown list is. */
    [data-theme='solstice'] .kp-theme-menu {
        background: none;
        border: 0;
        box-shadow: none;
    }

    /* Severity toasts [scope-60]. The plain toast above is repainted here in
       a later layer than kp.components, which swallowed every variant's
       plate; each is restated on the alert's token pair, as the severity
       badge wears it. */
    [data-theme='solstice'] .kp-toast--success {
        background: var(--success);
        color: var(--success-foreground);
        border-color: var(--success);
    }

    [data-theme='solstice'] .kp-toast--info {
        background: var(--info);
        color: var(--info-foreground);
        border-color: var(--info);
    }

    [data-theme='solstice'] .kp-toast--warning {
        background: var(--warning);
        color: var(--warning-foreground);
        border-color: var(--warning);
    }

    [data-theme='solstice'] .kp-toast--destructive,
    [data-theme='solstice'] .kp-toast--error {
        background: var(--destructive);
        color: var(--destructive-foreground);
        border-color: var(--destructive);
    }

    [data-theme='solstice']
        :is(.kp-toast--success, .kp-toast--info, .kp-toast--warning, .kp-toast--destructive, .kp-toast--error)
        :is(.kp-button--ghost, .kp-icon-button) {
        color: inherit;
    }

    [data-theme='solstice'] .kp-toasts {
        gap: var(--kp-space-sm);
    }

    [data-theme='solstice'] .kp-alert {
        border-radius: var(--radius);
    }

    /* A failed area is the red sky (G13, the busy failure decided as r2-so-failure-1): the dark card plate, the wash rising
       from its foot, the foot edge and a 1 px ring in the red, the words in the lifted red ink. The package's flat
       `--destructive` fill (a salmon block over the whole component) is no part of solstice's light, so EVERY destructive
       alert is the red sky, whichever part draws it (stateplate, runs, dated, card, transfer, rating) [t56-eye-1018]. */
    [data-theme='solstice'] .kp-alert--destructive {
        background:
            linear-gradient(to top, hsl(from var(--destructive) h s l / 0.3), transparent 75%),
            var(--card);
        color: var(--foreground);
        border-color: hsl(from var(--destructive) h s l / 0.55);
        box-shadow: inset 0 -2px 0 hsl(from var(--destructive) h s 50%);
    }

    [data-theme='solstice'] .kp-alert--destructive:is(.kp-stateplate, .kp-runs__failure, .kp-dated__failure, .kp-transfer__failure) :is(.kp-stateplate__title, strong),
    [data-theme='solstice'] .kp-alert--destructive.kp-rating__failure .kp-rating__failure-text {
        color: hsl(from var(--destructive) h s 68%);
    }

    /* The failure sentence is set in the display serif at heading size, like the stateplate's, whichever part draws it. */
    [data-theme='solstice'] .kp-alert--destructive:is(.kp-runs__failure, .kp-dated__failure, .kp-transfer__failure) strong {
        font-family: var(--theme-font-display);
        font-weight: 400;
        font-size: calc(var(--kp-stateplate-text, clamp(1.125rem, 1rem + 0.6vw, 1.5rem)) * 1.15);
        line-height: 1.25;
    }

    [data-theme='solstice'] .kp-grid {
        gap: var(--kp-space-lg);
    }

    [data-theme='solstice'] .kp-grid__tile {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-split {
        gap: 1px;
    }

    [data-theme='solstice'] .kp-split__pane {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-split__separator {
        background: var(--border);
    }

    /* ── Footer ───────────────────────────────────────────────────────── */

    [data-theme='solstice'] .kp-footer {
        border-top: 1px solid var(--border);
    }

    [data-theme='solstice'] .kp-footer h4 {
        font-weight: 600;
        letter-spacing: 0.06em;
        text-transform: uppercase;
    }

    [data-theme='solstice'] .kp-footer a {
        color: var(--muted-foreground);
        text-decoration: none;
    }

    [data-theme='solstice'] .kp-footer a:hover {
        color: var(--primary);
    }

    /* ── Badges, tags, status ───────────────────────────────────────────── */

    [data-theme='solstice'] .kp-badge,
    [data-theme='solstice'] .kp-tag {
        border-radius: var(--radius);
        font-weight: 600;
    }

    [data-theme='solstice'] .kp-health {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-health__dot {
        border-radius: 50%;
    }

    [data-theme='solstice'] .kp-skeleton {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-spinner {
        border-color: var(--border);
        border-top-color: var(--primary);
    }

    [data-theme='solstice'] .kp-empty__title {
        font-weight: 400;
    }

    [data-theme='solstice'] .kp-error {
        color: var(--destructive);
    }

    /* ── Text shapes: identifiers in the mono face, unornamented ───────── */

    [data-theme='solstice'] .kp-id,
    [data-theme='solstice'] .kp-url,
    [data-theme='solstice'] .kp-numeric,
    [data-theme='solstice'] .kp-timestamp,
    [data-theme='solstice'] .kp-masked,
    [data-theme='solstice'] .kp-copyable,
    [data-theme='solstice'] .kp-truncate,
    [data-theme='solstice'] .kp-cell-break,
    [data-theme='solstice'] .kp-cell-truncate {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-copyable__button {
        border-radius: calc(var(--radius) - 3px);
    }

    /* The copy button's two states win over this register's own button
       rules [gap-12]: those paint in kp.register, which beats the states
       in kp.components, so copied lost its success plate and a refused
       copy looked idle. Restated token for token. */
    [data-theme='solstice'] .kp-copyable .kp-copyable__button[data-kp-copied] {
        border-color: var(--success);
        color: var(--success-foreground);
        background: var(--success);
    }

    [data-theme='solstice'] .kp-copyable .kp-copyable__button[data-kp-copy-failed] {
        border-color: var(--destructive);
        border-style: dashed;
        color: var(--destructive);
    }

    /* ── Data: table, datatable, diff, timeline, tree, reorder ─────────── */

    [data-theme='solstice'] .kp-table {
        border-collapse: separate;
        border-spacing: 0;
    }

    [data-theme='solstice'] .kp-table th {
        color: var(--muted-foreground);
        font-weight: 600;
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='solstice'] .kp-table td {
        border-bottom: 1px solid var(--border);
    }

    [data-theme='solstice'] .kp-datatable {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-datatable__sort[aria-sort] {
        color: var(--primary);
    }

    [data-theme='solstice'] .kp-diff {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-diff__line,
    [data-theme='solstice'] .kp-diff__hunk {
        font-family: var(--theme-font-mono);
    }

    /* The step list is a row of embers: a finished step keeps a warm halo. */
    [data-theme='solstice'] .kp-steplist {
        --kp-steplist-gap: 0.5rem;
    }

    [data-theme='solstice'] .kp-steplist__item[data-state='done'] .kp-steplist__mark {
        box-shadow: 0 0 0 3px hsl(from var(--success) h s l / 0.25);
    }

    [data-theme='solstice'] .kp-timeline {
        border-inline-start: 2px solid var(--border);
    }

    [data-theme='solstice'] .kp-timeline__marker {
        background: var(--primary);
    }

    [data-theme='solstice'] .kp-timeline__when {
        color: var(--muted-foreground);
        font-family: var(--theme-font-mono);
    }

    /* A branch's children glide open and shut (js/motion.js glideGroup(),
       lesson 26): shutting, the group is kept drawn until the glide is over. */
    [data-theme='solstice'] .kp-tree [role='treeitem'][aria-expanded='false'] > [role='group'][data-kp-group-folding],
    [data-theme='solstice'] .kp-tree [role='treeitem'][aria-expanded='false'] + [role='group'][data-kp-group-folding] {
        display: block;
    }

    [data-theme='solstice'] .kp-tree {
        font-family: var(--theme-font-mono);
    }

    /* The accordion [gap-12]: the warm primary its selected tab wears. */
    [data-theme='solstice'] .kp-accordion__summary::marker {
        color: var(--primary);
    }

    [data-theme='solstice'] .kp-accordion__item[open] > .kp-accordion__summary {
        color: var(--primary);
    }

    [data-theme='solstice'] .kp-reorder {
        border-radius: var(--radius);
    }

    /* ── Navigation and steps ───────────────────────────────────────────── */

    [data-theme='solstice'] .kp-tab[aria-selected='true'] {
        color: var(--primary);
    }

    [data-theme='solstice'] .kp-tabs__list {
        border-bottom: 1px solid var(--border-strong);
    }

    [data-theme='solstice'] .kp-breadcrumb,
    [data-theme='solstice'] .kp-pagination {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-pagination [aria-current] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-wizard {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-wizard__steps {
        font-family: var(--theme-font-mono);
    }

    /* ── Pickers and palettes ────────────────────────────────────────────── */

    [data-theme='solstice'] .kp-datepicker__day[aria-selected='true'] {
        background: var(--primary);
        color: var(--primary-foreground);
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-datepicker__weekday,
    [data-theme='solstice'] .kp-datepicker__title {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-colorpicker__swatch {
        border-radius: calc(var(--radius) - 3px);
    }

    [data-theme='solstice'] .kp-colorpicker__value {
        font-family: var(--theme-font-mono);
    }

    [data-theme='solstice'] .kp-shortcuts__row kbd {
        font-family: var(--theme-font-mono);
        border: 1px solid var(--border-strong);
        border-radius: calc(var(--radius) - 3px);
        background: var(--card);
        padding: 0 0.4em;
    }

    [data-theme='solstice'] .kp-shortcuts__group-label,
    [data-theme='solstice'] .kp-palette__group-label {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }

    [data-theme='solstice'] .kp-theme-menu__status,
    [data-theme='solstice'] .kp-palette__status,
    [data-theme='solstice'] .kp-combobox__status {
        color: var(--muted-foreground);
        font-family: var(--theme-font-mono);
    }

    /* ── The roots the rules above reach only by their parts ───────────── */

    [data-theme='solstice'] .kp-field {
        gap: calc(var(--kp-space-xs) * 1.6);
    }

    [data-theme='solstice'] .kp-form {
        gap: calc(var(--kp-space-lg) * 1.1);
    }

    [data-theme='solstice'] .kp-combobox,
    [data-theme='solstice'] .kp-datepicker,
    [data-theme='solstice'] .kp-colorpicker,
    [data-theme='solstice'] .kp-shortcuts,
    [data-theme='solstice'] .kp-tabs {
        border-radius: var(--radius);
    }

    /* ── The demo's own pieces [S46] ─────────────────────────────────────── */

    /* The vertical margin note: static on narrow screens, rotated into
       the hero's left margin from 960px, the demo's own breakpoint. */
    [data-theme='solstice'] .kp-side-note {
        font-family: var(--theme-font-mono);
        font-size: 0.75rem;
        letter-spacing: 0.14em;
        text-transform: uppercase;
        color: var(--muted-foreground);
    }

    @media (min-width: 60rem) {
        [data-theme='solstice'] .kp-side-note {
            position: absolute;
            inset-block-start: 6rem;
            inset-inline-start: clamp(0.5rem, 2vw, 1.5rem);
            writing-mode: vertical-rl;
            transform: rotate(180deg);
            max-width: none;
        }

        /* The note's containing block is its own hero (Kenny, 2026-09-16,
           register-faults [scope-100]): nothing positioned the hero, so
           outside the catalogue's stage the note was placed against the
           page — at y=24 while its hero stood thousands of pixels lower. */
        [data-theme='solstice'] [data-kp-surface='hero']:has(> .kp-side-note) {
            position: relative;
        }
    }

    /* Laurels: a bold lead-in and a rust hairline either side, the way a
       printed spec sheet sets its own tick marks. */
    [data-theme='solstice'] .kp-laurels {
        text-transform: uppercase;
        letter-spacing: 0.12em;
        font-size: 0.6875rem;
        color: var(--muted-foreground);
    }

    [data-theme='solstice'] .kp-laurels li {
        position: relative;
        padding-inline: 0.85rem;
    }

    [data-theme='solstice'] .kp-laurels li::before,
    [data-theme='solstice'] .kp-laurels li::after {
        content: '';
        position: absolute;
        inset-block: 0.15rem;
        inline-size: 1px;
        background: var(--accent);
    }

    [data-theme='solstice'] .kp-laurels li::before {
        inset-inline-start: 0;
    }

    [data-theme='solstice'] .kp-laurels li::after {
        inset-inline-end: 0;
    }

    [data-theme='solstice'] .kp-laurels b {
        color: var(--foreground);
        font-weight: 700;
    }

    /* The platforms line: the names in the full ink and a heavier weight
       over the line's muted ink, spaced by the package's own gap — no tick
       or mark before a name [scope-100: this comment used to promise a
       rust tick the rules never drew]. */
    [data-theme='solstice'] .kp-platforms {
        font-weight: 500;
        color: var(--muted-foreground);
    }

    [data-theme='solstice'] .kp-platforms span {
        color: var(--foreground);
        font-weight: 600;
    }

    /* The spec sheet: the plain card the demo shows — no ramp, no chrome. */
    [data-theme='solstice'] .kp-spec {
        border-radius: var(--radius);
    }

    /* The log wears what this register already decided for its other data
 * surface, `.kp-spec` — the same ground, the same edge, the same face
 * [gap-14]. A new component that invents a look of its own is a
 * twenty-third decision nobody made. */
    [data-theme='solstice'] .kp-log {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-spec__swatch {
        border-radius: 5px;
    }

    [data-theme='solstice'] .kp-spec__font[data-font='display'] {
        font-family: var(--theme-font-display);
        font-weight: 400;
    }

    /* ── Motion, guarded [DI7] ────────────────────────────────────────── */

    /* Every animation of this register lives here, inside the
       no-preference guard, so a reader who asked for reduced motion never
       receives one: the rest states above (headline solid, rule drawn,
       redaction covered) are what they get. The durations are literal
       because check-motion.mjs computes DI5's rate from them; the
       matching --kp-* knobs above are what a consumer can retune
       [AR43]. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] [data-kp-reveal='headline'].is-calibrating::after {
            animation: kp-cal-slide calc(var(--kp-cal-duration) + 2 * var(--kp-cal-stagger)) var(--fx-ease) 1 forwards;
        }

        [data-theme='solstice'] [data-kp-reveal='rule'].is-in::after {
            animation: kp-cal-rule var(--kp-rule-duration) var(--fx-ease) var(--kp-rule-delay) 1 both;
        }

        [data-theme='solstice'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared {
            animation: kp-cal-redact var(--kp-redact-duration) var(--fx-ease) 1 both;
            transition: color 0s linear var(--kp-redact-duration);
        }

        [data-theme='solstice'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared:nth-of-type(2) {
            animation-delay: var(--kp-redact-stagger);
            transition-delay: calc(var(--kp-redact-duration) + var(--kp-redact-stagger));
        }

        [data-theme='solstice'] .kp-card[data-kp-reveal='emphasis'] mark.is-cleared:nth-of-type(3) {
            animation-delay: calc(2 * var(--kp-redact-stagger));
            transition-delay: calc(var(--kp-redact-duration) + 2 * var(--kp-redact-stagger));
        }
    }

    /* ── Motion [DI5, DI7] ────────────────────────────────────────────── */

    /* One monotonic wipe, never opposed: the three bands recede together
       on a single timeline (js/effects.js adds is-calibrating for the
       whole 740ms span; the demo's own three independently-staggered
       transforms are approximated here as one clip-path sweep, left to
       right, at the theme's own ease — the same triad, the same total
       time, a different mechanism [S49 finding, recorded in
       anatomy.md]). */
    @keyframes kp-cal-slide {
        0% {
            clip-path: inset(0 0 0 0);
        }

        100% {
            clip-path: inset(0 0 0 100%);
        }
    }

    /* The rule: scaleX(0→1), one direction, one step. */
    @keyframes kp-cal-rule {
        from {
            transform: scaleX(0);
        }

        to {
            transform: scaleX(1);
        }
    }

    /* The redaction: the bar lifts right to left, the demo's own
       direction (`clip-path: inset(0 100% 0 0)` at rest-cleared). */
    @keyframes kp-cal-redact {
        from {
            background-size: calc(100% - 2px) calc(100% - 2px);
        }

        to {
            background-size: 0% calc(100% - 2px);
        }
    }
    /* The band [M1, M4]: Kenny picked this theme's own version over the
       shared one on 2026-09-08 — amber between two translucent amber rules. */
    [data-theme='solstice'] .kp-marquee {
        color: var(--primary);
        border-block: 1px solid color-mix(in srgb, var(--primary) 35%, transparent);
        font-family: var(--theme-font-mono);
        --kp-marquee: 44000ms;
    }

    /* The menu's caption [M3]: the same choice, for the line a consumer
       may put above a dropdown's items. */
    /* A mega menu's group headings speak in the caption's voice [scope-48]. */
    [data-theme='solstice'] .kp-nav__menu[data-kp-menu-label]::before,
    [data-theme='solstice'] .kp-nav__menu--wide .kp-nav__menu-heading {
        color: var(--primary);
        font-family: var(--theme-font-mono);
        border-block-end: 1px solid color-mix(in srgb, var(--primary) 40%, transparent);
    }

    /* ── The side navigation [feat-nav-3] ────────────────────────────
       Kenny called this one too sober. The theme is a low sun, so the
       column carries the light it already has: the row you are on is warm
       at its leading edge and cools across, which is the one gradient
       this theme is allowed. */
    [data-theme='solstice'] .kp-sidenav {
        --kp-sidenav-surface: var(--card);
        --kp-sidenav-gap: 0.2rem;
        border-inline-end: 1px solid var(--border);
    }

    [data-theme='solstice'] .kp-sidenav__link,
    [data-theme='solstice'] .kp-sidenav__category-toggle {
        border-radius: var(--radius);
    }

    [data-theme='solstice'] .kp-sidenav__link[aria-current='page'] {
        color: var(--foreground);
        background: linear-gradient(to right, hsl(from var(--primary) h s l / 0.35), transparent 85%);
        box-shadow: inset 0.18rem 0 0 var(--primary);
    }

    /* ── Back to top, and a picture [feat-page-1, feat-media-1] ──────
       Less sober, as Kenny asked: the low sun catches the top edge of
       both, and the caption keeps the warm accent. */
    [data-theme='solstice'] .kp-to-top {
        box-shadow: inset 0 1px 0 hsl(from var(--primary) h s l / 0.5);
    }

    [data-theme='solstice'] .kp-media {
        border: 1px solid var(--border);
        box-shadow: inset 0 2px 0 hsl(from var(--primary) h s l / 0.45);
    }

    [data-theme='solstice'] .kp-media-figure > figcaption {
        color: var(--primary);
    }

    /* The figure carries the caption's voice, so the decision sits with
       the picture rather than with the words under it. */
    [data-theme='solstice'] .kp-media-figure {
        color: var(--primary);
    }

    /* ── The low sun, pointed at and pressed [Kenny, 2026-10-07] ───────
       Replaces the rake of scope-12 and the pressed faces restated for
       fix-12: both are drawn in the signature layer below, on one pair of
       numbers (see "Pointing and pressing"). Nothing in this layer paints a
       hover or a pressed ground, so nothing here cancels the press. */

    /* ── The palette's trigger in the bar [scope-48, scope-80] ─────────── */

    /* In the voice of this register's own nav links (Kenny, 2026-09-14,
       search-voice "Per thema"): words at the bar's own size in the muted
       ink, taking the primary ink when pointed at. The link's typeface,
       case, spacing, shape and pointer answer are restated here, because the
       trigger is a button beside the list rather than a link in it. The
       underline a plain link carries is not: it says "this is a link", and
       the trigger is not one. */
    [data-theme='solstice'] .kp-nav__search .kp-nav__search-trigger {
        padding-inline: 0;
        border: 0;
        border-radius: 0;
        background: none;
        color: var(--muted-foreground);
    }

    [data-theme='solstice'] .kp-nav__search .kp-nav__search-trigger:hover,
    [data-theme='solstice'] .kp-nav__search .kp-nav__search-trigger:focus-visible {
        color: var(--primary);
    }

    /* ── The alarm [scope-94] ──────────────────────────────────────────────
       The last light: a warm near-black plate, the headline in its red, amber bars and an amber glow. Every colour is one of this theme's tokens. The
       button keeps this register's shape and takes the alarm's paint, on
       selectors long enough to outrank this register's own button states;
       the dialog takes no focus ring, because in the auto mode the whole
       screen is what has focus. */
    [data-theme='solstice'] .kp-alarm {
        --kp-alarm-ground: hsl(from var(--background) h s 5% / 0.95);
        --kp-alarm-ink: hsl(from var(--destructive) h s max(l, 62));
        --kp-alarm-soft: var(--foreground);
        --kp-alarm-split: var(--primary);
        --kp-alarm-on-ink: hsl(from var(--background) h s 5%);
        --kp-alarm-glow: hsl(from var(--primary) h s l / 0.3);
        --kp-alarm-halo: hsl(from var(--destructive) h s 50 / 0.45);
        --kp-alarm-scan: hsl(from var(--destructive) h s l / 0);
        --kp-alarm-vignette: hsl(from var(--background) h s 2% / 0.8);
        --kp-alarm-stripe: var(--primary);
        --kp-alarm-frame: 1px solid;
    }

    [data-theme='solstice'] .kp-alarm:focus-visible {
        outline: none;
    }

    [data-theme='solstice'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack,
    [data-theme='solstice'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:hover:not(:disabled),
    [data-theme='solstice'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:active:not(:disabled) {
        border-color: var(--kp-alarm-ink);
        background: var(--kp-alarm-ink);
        color: var(--kp-alarm-on-ink);
        text-shadow: none;
    }

    [data-theme='solstice'] .kp-alarm .kp-button.kp-alarm__ack.kp-alarm__ack:is(:hover, :focus-visible):not(:disabled):not(:active) {
        background: var(--kp-alarm-on-ink);
        color: var(--kp-alarm-ink);
    }

    [data-theme='solstice'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep,
    [data-theme='solstice'] .kp-alarm .kp-button.kp-alarm__keep.kp-alarm__keep:is(:hover, :focus-visible):not(:disabled) {
        border-color: currentColor;
        background: transparent;
        color: inherit;
        text-shadow: none;
    }

    /* A submenu item's mark [Kenny, 2026-09-20]: a dotted circle, a low sun. */
    [data-theme='solstice'] .kp-sidenav__submenu .kp-sidenav__link {
        --kp-sidenav-submenu-mark: '◌';
    }
}

/* ── Signature [scope-140] ─────────────────────────────────────────────── */
/* solstice's approved signature (Kenny, 2026-10-03, three review rounds): the
   progress bar and the ten elements (spinner, skeleton, switch, check and
   radio, toast, dialog, tooltip, wizard steps, empty state, link hover),
   ported once from research/progress-signature/themes/solstice.css and research/signature-elements/themes/solstice.css
   and maintained here from now on. In kp.signature, which css/themes.css
   orders after kp.register, so it draws over the register exactly as the
   approved demos did, whatever the weight of a register selector. */
@layer kp.signature {
    /* The link signature is for links in running text; a link in a navigation,
       a menu, a breadcrumb (a nav) or the footer keeps its own component's look
       (scope-93: no link colour in a navigation). */
    /* A shadow or outline the signature draws on a focusable control yields to
       the theme's focus ring while the control has focus (DI2). */
    [data-theme='solstice'] .kp-progressbar {
        --kp-progressbar-height: calc(0.875rem * var(--kp-progressbar-scale, 1));
        --kp-ps-head: calc(0.875rem * var(--kp-progressbar-scale, 1));
        --kp-ps-inset: calc(2px * var(--kp-progressbar-scale, 1));
        --kp-ps-dash: calc(6px * var(--kp-progressbar-scale, 1));
        --kp-ps-dash-pitch: calc(12px * var(--kp-progressbar-scale, 1));
        --kp-ps-gold: color-mix(in oklab, var(--primary) 55%, var(--foreground));
    }

    [data-theme='solstice'] .kp-progressbar__track {
        border-radius: var(--radius);
        background:
            linear-gradient(color-mix(in srgb, var(--border-strong) 45%, transparent), color-mix(in srgb, var(--border-strong) 45%, transparent))
                center / 100% 1px no-repeat,
            var(--muted);
    }

    [data-theme='solstice'] .kp-progressbar__fill {
        inset-block: var(--kp-ps-inset);
        border-radius: var(--radius);
        background: linear-gradient(90deg, var(--accent), var(--primary) 62%, var(--kp-ps-gold));
        clip-path: inset(0 calc((1 - var(--kp-value)) * 100% + var(--kp-value) * var(--kp-ps-head) / 2) 0 0 round 0 var(--radius) var(--radius) 0);
        transition: clip-path var(--fx-duration) var(--fx-ease);
    }

    [data-theme='solstice'] .kp-progressbar__head {
        inline-size: var(--kp-ps-head);
        border-radius: 50%;
        background: radial-gradient(circle closest-side, var(--kp-ps-gold) calc(100% - 2.5px), var(--card) calc(100% - 2px));
        transform: translateX(calc(var(--kp-value) * (100cqi - var(--kp-ps-head))));
        transition: transform var(--fx-duration) var(--fx-ease);
    }

    [data-theme='solstice'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
        inset-block: 0;
        inline-size: 32%;
        border-radius: 0;
        background: linear-gradient(
                90deg,
                transparent,
                color-mix(in srgb, var(--accent) 70%, transparent) 55%,
                var(--primary) calc(100% - var(--kp-ps-head) / 2),
                transparent 0
            )
            center / 100% calc(100% - 2 * var(--kp-ps-inset)) no-repeat;
        animation: kp-progressbar-solstice-arc 2400ms var(--fx-ease) infinite;
    }

    [data-theme='solstice'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill::after {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-end: 0;
        inline-size: var(--kp-ps-head);
        border-radius: 50%;
        background: radial-gradient(circle closest-side, var(--kp-ps-gold) calc(100% - 2.5px), var(--card) calc(100% - 2px));
    }

    @media (prefers-reduced-motion: reduce) {
        [data-theme='solstice'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill {
            inset-inline: 0;
            inline-size: auto;
            animation: none;
            transform: none;
            background: repeating-linear-gradient(90deg, var(--accent) 0 var(--kp-ps-dash), transparent var(--kp-ps-dash) var(--kp-ps-dash-pitch))
                center / 100% calc(3px * var(--kp-progressbar-scale, 1)) no-repeat;
        }

        [data-theme='solstice'] .kp-progressbar[data-kp-indeterminate] .kp-progressbar__fill::after {
            inset-inline-end: auto;
            inset-inline-start: calc(50% - var(--kp-ps-head) / 2);
            box-shadow: 0 0 0 calc(4px * var(--kp-progressbar-scale, 1)) var(--muted);
        }
    }

    [data-theme='solstice'] .kp-spinner {
        --kp-sig-dur: 2400ms;
        /* The arc and the sun scale with the spinner (0.5 rem and 0.4 rem at the default 1.25 rem), so the sun of a busy
           card's 2.5 rem spinner is not a 6 px dot on a 30 px line [t56-eye-1018]. */
        --kp-sig-so-r: calc(var(--kp-spinner-size, 1.25rem) * 0.4);
        position: relative;
        overflow: hidden;
        border: 0;
        border-radius: 0;
        /* Nothing below the horizon is drawn. */
        clip-path: inset(0 0 calc(20% - 2px) 0);
        /* The horizon, and the faint arc the sun travels. */
        background:
            linear-gradient(var(--border-strong), var(--border-strong)) 50% 80% / 100% 1.5px no-repeat,
            radial-gradient(
                circle var(--kp-sig-so-r) at 50% 80%,
                transparent calc(100% - 1px),
                hsl(from var(--primary) h s l / 0.3) calc(100% - 1px) 100%,
                transparent 100%
            );
        animation: none;
    }

    [data-theme='solstice'] .kp-spinner::after {
        content: '';
        position: absolute;
        inset-inline-start: calc(50% - var(--kp-sig-so-r) * 0.4);
        inset-block-start: calc(80% - var(--kp-sig-so-r) * 0.4);
        inline-size: calc(var(--kp-sig-so-r) * 0.8);
        block-size: calc(var(--kp-sig-so-r) * 0.8);
        border-radius: 50%;
        background: var(--primary);
        box-shadow: 0 0 0 2px hsl(from var(--primary) h s l / 0.25);
        transform: translateY(calc(var(--kp-sig-so-r) * -1));
    }

    [data-theme='solstice'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        --kp-sig-dur: 3600ms;
        position: relative;
        overflow: hidden;
        block-size: 0.9rem;
        border-radius: 999px;
        background: var(--muted);
        animation: none;
    }

    [data-theme='solstice']
        .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)
        + .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block) {
        margin-block-start: 0.65rem;
    }

    [data-theme='solstice'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::after {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 60%;
        background: radial-gradient(ellipse closest-side, hsl(from var(--primary) h s l / 0.32), transparent);
        transform: translateX(-100%);
    }

    [data-theme='solstice'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::before {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 0.9rem;
        border-radius: inherit;
        background: hsl(from var(--accent) h s l / 0.55);
    }

    [data-theme='solstice'] .kp-switch__input {
        border-color: var(--border-strong);
        background: var(--background);
    }

    [data-theme='solstice'] .kp-switch__input::before {
        background: var(--muted-foreground);
        box-shadow: inset -4px -1px 0 0 hsl(from var(--background) h s l / 0.85);
    }

    [data-theme='solstice'] .kp-switch__input:checked {
        border-color: var(--primary);
        background: linear-gradient(90deg, var(--accent), var(--primary));
    }

    [data-theme='solstice'] .kp-switch__input:checked::before {
        inset-inline-start: var(--kp-switch-inset, 0.125rem);
