    }

    [data-theme='solstice'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a) {
        text-decoration-thickness: 1.5px;
        text-decoration-color: var(--accent);
        text-underline-offset: 0.24em;
    }

    [data-theme='solstice'] a:not([class], :is(nav, [role='navigation'], [role='menu'], [role='menubar'], .kp-nav, .kp-sidenav, .kp-footer) a):hover {
        color: var(--primary);
        text-decoration-color: var(--primary);
        text-decoration-thickness: 2px;
        text-shadow: 0 0 14px hsl(from var(--primary) h s l / 0.35);
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-spinner::after {
            animation: kp-sig-solstice-solstice-arc var(--kp-sig-dur) linear infinite;
        }

        [data-theme='solstice'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block)::after {
            animation: kp-sig-solstice-solstice-light var(--kp-sig-dur) ease-in-out infinite;
        }

        [data-theme='solstice'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block):nth-child(2)::after {
            animation-delay: 240ms;
        }

        [data-theme='solstice'] .kp-skeleton:not(.kp-skeleton--circle, .kp-skeleton--block):nth-child(3)::after {
            animation-delay: 480ms;
        }

        [data-theme='solstice'] .kp-switch__input::before {
            transition: transform 360ms var(--fx-ease);
        }

        [data-theme='solstice'] .kp-field__check:checked::before {
            animation: kp-sig-solstice-solstice-warm var(--kp-sig-dur) var(--fx-ease) both;
        }

        /* G3 · what opens is kindled (decided 2026-10-07, research/solstice-character,
           "opening": "dome"; built 2026-10-13): the toast, the dialog (and the drawer, a
           dialog too) and the tooltip open as a dome of first light growing from the middle
           of their foot, overbright and cooling, 2 units (480 ms) on G1's coming curve; the
           close is the same frames backwards (js/motion.js), the dome sinking into the foot.
           The dialog that is not yet open runs one and a half times as long, so the close
           js/motion.js reads off it (two thirds) is the opening's own 480 ms. */
        [data-theme='solstice'] .kp-toast {
            animation: kp-sig-solstice-kindled var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) backwards;
        }

        [data-theme='solstice'] .kp-dialog {
            animation: kp-sig-solstice-kindled calc(var(--kp-sig-solstice-open) * 1.5) var(--kp-sig-solstice-come) backwards;
        }

        [data-theme='solstice'] .kp-dialog[open] {
            animation-duration: var(--kp-sig-solstice-open);
        }

        [data-theme='solstice'] .kp-tooltip {
            animation: kp-sig-solstice-kindled var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) backwards;
        }

        /* A toast leaves as its kindling played backwards (G3: closing is the dome sinking
           back into the foot), under the same name, so js/motion.js lets it arrive as that
           leave turned round: one picture, mirrored. The class is doubled to outweigh the
           theme's general leave on `[data-kp-leaving]`. */
        [data-theme='solstice'] .kp-toast.kp-toast[data-kp-leaving] {
            animation: kp-sig-solstice-kindled var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) reverse forwards;
        }
    }

    /* G3's dome: from nothing at the middle of the foot to past every corner (at rest the
       ellipse holds the whole panel and its glow), overbright and warm, cooling to its own
       colour. No timing function inside: the animation's curve (G1) plays it, and played
       backwards it is the same frames in reverse. */
    @keyframes kp-sig-solstice-kindled {
        from {
            clip-path: ellipse(0 0 at 50% 100%);
            filter: brightness(1.35) saturate(1.3);
        }

        to {
            clip-path: ellipse(150% 150% at 50% 100%);
            filter: brightness(1) saturate(1);
        }
    }

    @keyframes kp-sig-solstice-solstice-arc {
        0% {
            opacity: 0;
            transform: rotate(-100deg) translateY(calc(var(--kp-sig-so-r) * -1));
        }

        10%,
        80% {
            opacity: 1;
        }

        90%,
        100% {
            opacity: 0;
            transform: rotate(100deg) translateY(calc(var(--kp-sig-so-r) * -1));
        }
    }

    @keyframes kp-sig-solstice-solstice-light {
        from {
            transform: translateX(-100%);
        }

        to {
            transform: translateX(270%);
        }
    }

    @keyframes kp-sig-solstice-solstice-warm {
        from {
            opacity: 0;
            transform: scale(0.6);
        }

        to {
            opacity: 1;
        }
    }

    @keyframes kp-sig-solstice-solstice-rise {
        from {
            transform: translateY(14px);
            clip-path: inset(-30px -30px 100% -30px);
        }

        to {
            transform: none;
            clip-path: inset(-30px -30px 0 -30px);
        }
    }

    @keyframes kp-sig-solstice-solstice-dawn {
        from {
            opacity: 0;
            transform: translateY(18px);
        }

        to {
            opacity: 1;
            transform: none;
        }
    }

    @keyframes kp-sig-solstice-solstice-ember {
        from {
            opacity: 0;
            transform: scale(0.94);
        }

        to {
            opacity: 1;
            transform: none;
        }
    }

    @keyframes kp-progressbar-solstice-arc {
        from {
            transform: translateX(-100%);
        }
        to {
            transform: translateX(315%);
        }
    }

    /* Growing and shrinking, this theme's way [scope-142; approved by Kenny
       on research/size-motion, 2026-10-04]. js/motion.js marks a gliding box
       `[data-kp-resizing]` and what arrives in it `[data-kp-arriving]`. */
    @media (prefers-reduced-motion: no-preference) {
        /* ── solstice: dawn. A warm light rises under the box as it grows, and
           new content rises into it, still bright from the sun. ─────────── */
        [data-theme='solstice'] [data-kp-resizing] {
            filter: drop-shadow(0 10px 18px hsl(from var(--primary) h s l / 0.45));
        }

        [data-theme='solstice'] [data-kp-arriving] {
            animation: kp-sig-solstice-size-rise 480ms cubic-bezier(0.2, 0, 0, 1) backwards;
        }

        @keyframes kp-sig-solstice-size-rise {
            from {
                opacity: 0;
                transform: translateY(10px);
                filter: brightness(1.5) saturate(1.4);
            }
        }
    }

    /* Leaving, this theme's way [scope-142; picked by Kenny on research/size-motion,
       2026-10-04]. js/motion.js marks what leaves `[data-kp-leaving]`, closes its space during
       the exit, and in a row of leaves starts the next one halfway through this one. */
    @media (prefers-reduced-motion: no-preference) {
        /* ── solstice: the morning mist: it lifts, brightens and thins away ── */
        /* Opening is closing turned around (Kenny's pick on research/open-reverse,
           2026-10-05): js/motion.js opens the dialog as its close played backwards,
           in the close's time, and lets what arrives play this leave backwards. */
        [data-theme='solstice'] {
            --kp-open: reverse-close;
        }

        [data-theme='solstice'] [data-kp-leaving] {
            animation: kp-sig-solstice-leave 540ms ease-in forwards;
        }

        @keyframes kp-sig-solstice-leave {
            to {
                transform: translateY(-14px);
                filter: brightness(1.4) blur(3px);
                opacity: 0;
            }
        }
    }

    /* Waiting surfaces that come and go with a state, this theme's way (all-themes,
       2026-10-13): the morning mist above, played backwards to arrive. */
    @media (prefers-reduced-motion: no-preference) {
        /* The mist under a second name, for a part whose arrival and leave are
           both CSS: the browser restarts an animation only when its name changes. */
        @keyframes kp-sig-solstice-leave-back {
            to {
                transform: translateY(-14px);
                filter: brightness(1.4) blur(3px);
                opacity: 0;
            }
        }

        /* The calendar's busy layers (the whole grid's card and a day's sun) come
           out of the mist and go into it, 540 ms; they came in by the package's
           240 ms fade and went at once. js/calendar.js marks a layer
           `[data-kp-leaving]` while its state goes (`--kp-calendar-busy-leave:
           hold`, lesson 37), the general leave above plays on it, and the rules
           below keep it drawn and placed through it. */
        [data-theme='solstice'] :is(.kp-calendar__day-busy, .kp-calendar__busy) {
            --kp-calendar-busy-leave: hold;
            transition: none;
        }

        [data-theme='solstice']
            :is(.kp-calendar--busy-days, .kp-calendar--busy-whole:not(:has(> .kp-calendar__grid[aria-busy='true'])))
            .kp-calendar__day[data-kp-tone='loading']
            > .kp-calendar__day-busy,
        [data-theme='solstice'] .kp-calendar--busy-whole:has(> .kp-calendar__grid[aria-busy='true']) > .kp-calendar__busy {
            animation: kp-sig-solstice-leave-back 540ms ease-in reverse backwards;
        }

        [data-theme='solstice'] .kp-calendar__day:has(> .kp-calendar__day-busy[data-kp-leaving]) {
            position: relative;
        }

        [data-theme='solstice'] .kp-calendar__day-busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-spinner, 0.75rem);
            position: absolute;
            inset-inline: 0;
            inset-block-end: 0.125rem;
            display: flex;
            justify-content: center;
            line-height: 0;
        }

        [data-theme='solstice'] .kp-calendar--busy-whole > .kp-calendar__busy[data-kp-leaving] {
            --kp-spinner-size: var(--kp-calendar-busy-spinner, 2.5rem);
            z-index: 1;
            display: grid;
            place-self: center;
            place-items: center;
            padding: var(--kp-space-md, 1rem);
            border-radius: var(--radius, 0.5rem);
            background: var(--card);
            box-shadow: 0 0 0 1px var(--border);
            line-height: 0;
        }

        /* A refreshing table and the rows it keeps dim with its busy layer, in
           the layer's 540 ms, and brighten with its leave: the dims
           (css/layout.css `--kp-busy-opacity`, the rows'
           `--kp-datatable-busy-opacity`) switched in one frame while the layer
           came and went over 540 ms. One keyframe set: forwards on the mist's
           arrival curve, backwards on its leave (the reversed `ease-out` is the
           leave's `ease-in`). */
        [data-theme='solstice'] .kp-datatable {
            --kp-ss-dim: var(--kp-busy-opacity, 0.7);
        }

        [data-theme='solstice'] .kp-datatable .kp-table tbody {
            --kp-ss-dim: var(--kp-datatable-busy-opacity, 0.55);
        }

        [data-theme='solstice'] :is(.kp-datatable[aria-busy='true'], .kp-datatable[aria-busy='true'] .kp-table tbody) {
            animation: kp-sig-solstice-busy-dim 540ms ease-out backwards;
        }

        [data-theme='solstice']
            :is(
                .kp-datatable:not([aria-busy='true']):has(> .kp-datatable__busy-overlay[data-kp-leaving]),
                .kp-datatable:not([aria-busy='true']):has(> .kp-datatable__busy-overlay[data-kp-leaving]) .kp-table tbody
            ) {
            animation: kp-sig-solstice-busy-dim-back 540ms ease-out reverse backwards;
        }

        @keyframes kp-sig-solstice-busy-dim {
            from {
                opacity: 1;
            }

            to {
                opacity: var(--kp-ss-dim);
            }
        }

        @keyframes kp-sig-solstice-busy-dim-back {
            from {
                opacity: 1;
            }

            to {
                opacity: var(--kp-ss-dim);
            }
        }

        /* The side navigation's backdrop dims in the panel's own time (the
           register's 240 ms), not the package's literal 220 ms, so the two are
           one picture (lesson 31 checked: no clip cuts the content). */
        [data-theme='solstice'] .kp-sidenav__backdrop {
            animation-duration: 240ms;
        }
    }

    /* ── The meter with a mark, this theme's way [picked by Kenny on
       research/character-meter, round 3, 2026-10-05: shape 3, while
       loading 2, how the share arrives 2, when the tone changes 2,
       the mark past the end 2]. The package's own markup and states
       (setMeter(), js/kpi.js): the track on the meter, the share on ::before,
       the sign past the end or the loading picture on ::after, the mark
       `.kp-meter__mark`. Every animation and transition under
       prefers-reduced-motion: no-preference; still frames otherwise. ── */

    /* The shared part: room past the end, loading without the pulse, the mark
       centred on its width, the package's signs cleared for the shape's own.
       Under :where() so each picked rule below wins as it did in the demo. */
    :where([data-theme='solstice']) :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-room: 0.625rem;
        box-sizing: border-box;
    }

    :where([data-theme='solstice']) .kp-meter--inline {
        margin-inline-end: calc(var(--kp-space-xs, 0.25rem) + var(--kp-sig-meter-room));
    }

    /* Each character draws its own loading picture instead of the pulse. */
    :where([data-theme='solstice']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        overflow: clip;
        animation: none;
    }

    :where([data-theme='solstice']) :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
    }

    /* The mark is centred on its share, whatever its width. */
    :where([data-theme='solstice']) .kp-meter__mark {
        --kp-sig-meter-mw: 2px;
        box-sizing: border-box;
        inline-size: var(--kp-sig-meter-mw);
        inset-inline-start: calc(clamp(0, var(--kp-mark, 0), 1) * 100% - var(--kp-sig-meter-mw) / 2);
    }

    :where([data-theme='solstice']) .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - 0.75rem);
    }

    /* The sign past the end, cleared of the package's ▸ for each character
       to draw its own. */
    :where([data-theme='solstice']) :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '';
        position: absolute;
        inset: auto;
        translate: none;
        color: inherit;
        font-size: 0.75rem;
        line-height: 1;
        text-shadow: none;
        white-space: nowrap;
        pointer-events: none;
    }

    /* A mark past the end keeps the package's sign inside the bar's end, in
       each character's own glyph and ink. */
    :where([data-theme='solstice']) .kp-meter__mark[data-kp-over]::after {
        content: var(--kp-sig-meter-mo-sign, '▸');
        color: var(--kp-sig-meter-mo-ink, var(--foreground));
        font-family: var(--kp-sig-meter-mo-font, inherit);
        text-shadow:
            0 0 1px var(--kp-sig-meter-mo-halo, var(--card)),
            0 0 2px var(--kp-sig-meter-mo-halo, var(--card));
    }

    /* ── shape: option 3 ── */

    /* ── solstice · 3 · the horizon ── */
    [data-theme='solstice'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-meter-height: 0.5rem;
        --kp-sig-meter-room: 0.875rem;
        border-radius: 0;
        background: linear-gradient(to bottom, var(--muted), color-mix(in oklab, var(--muted) 70%, var(--primary)));
        box-shadow: inset 0 -1px 0 var(--border-strong);
    }

    /* The lit land: a warm edge where the low sun touches it. */
    [data-theme='solstice'] :is(.kp-meter, .kp-kpi__meter)::before {
        border-radius: 0;
        background:
            linear-gradient(to bottom, hsl(from var(--fx-signal, var(--warning)) h s l / 0.6) 0 1px, transparent 1px), var(--kp-meter-fill-colour);
    }

    /* The sun on a stalk. */
    [data-theme='solstice'] .kp-meter__mark {
        inset-block: -3px -2px;
        background: var(--foreground);
        box-shadow: 0 0 0 1px var(--card);
    }

    [data-theme='solstice'] .kp-meter__mark::before {
        content: '';
        position: absolute;
        inset-block-end: 100%;
        inset-inline-start: 50%;
        inline-size: 7px;
        block-size: 7px;
        translate: -50% 0;
        border-radius: 50%;
        background: var(--warning);
        box-shadow: 0 0 0 1px var(--foreground);
    }

    [data-theme='solstice'] :is(.kp-meter, .kp-kpi__meter)[data-kp-over]::after {
        content: '✳';
        inset-inline-start: calc(100% + 1px);
        inset-block-start: 50%;
        translate: 0 -55%;
        color: var(--kp-meter-fill-colour);
        font-size: 0.75rem;
    }

    /* ── while loading: option 2 ── */

    [data-theme='solstice'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading] {
        animation: none;
    }

    [data-theme='solstice'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
        all: unset;
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
        background: radial-gradient(circle, var(--primary) 3px, transparent 3.5px) 50% 50% / 10px 100% no-repeat;
        --kp-sig-meter-l0: 0% 50%;
        --kp-sig-meter-l1: 100% 50%;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] :is(.kp-meter, .kp-kpi__meter)[data-kp-loading]::after {
            animation: kp-sig-solstice-meter-pos 4000ms ease-in-out infinite alternate;
        }
    }

    /* ── how the share arrives: option 2 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] :is(.kp-meter, .kp-kpi__meter)::before {
            animation: kp-sig-solstice-meter-grow-o 1400ms ease-in-out backwards;
            transition: inline-size 1400ms ease-in-out;
            transform-origin: 0 50%;
        }
    }

    /* ── when the tone changes: option 2 ── */

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] :is(.kp-meter, .kp-kpi__meter):not([data-kp-loading], [data-kp-tone]) {
            animation: kp-sig-solstice-meter-bump-o 500ms ease-in-out;
        }

        [data-theme='solstice'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='warning']:not([data-kp-loading]) {
            animation: kp-sig-solstice-meter-bump-w 500ms ease-in-out;
        }

        [data-theme='solstice'] :is(.kp-meter, .kp-kpi__meter)[data-kp-tone='destructive']:not([data-kp-loading]) {
            animation: kp-sig-solstice-meter-bump-d 500ms ease-in-out;
        }
    }

    /* ── the mark past the end: option 2 ── */

    [data-theme='solstice'] :is(.kp-meter, .kp-kpi__meter) {
        --kp-sig-meter-mo-sign: '›';
    }

    [data-theme='solstice'] .kp-meter__mark[data-kp-over] {
        inset-inline-start: calc(100% - var(--kp-sig-meter-mw) - 1px);
        rotate: 24deg;
        transform-origin: 50% 100%;
    }

    [data-theme='solstice'] .kp-meter__mark[data-kp-over]::after {
        inset-inline-start: calc(100% + 3px);
        rotate: -24deg;
    }

    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-meter__mark {
            transition:
                inset-inline-start 900ms ease-in-out,
                rotate 900ms ease-in-out;
        }
    }

    @keyframes kp-sig-solstice-meter-bump-d {
        0% {
            scale: 1;
        }

        40% {
            scale: 1.04 1.3;
        }

        100% {
            scale: 1;
        }
    }

    @keyframes kp-sig-solstice-meter-bump-o {
        0% {
            scale: 1;
        }

        40% {
            scale: 1.04 1.3;
        }

        100% {
            scale: 1;
        }
    }

    @keyframes kp-sig-solstice-meter-bump-w {
        0% {
            scale: 1;
        }

        40% {
            scale: 1.04 1.3;
        }

        100% {
            scale: 1;
        }
    }

    @keyframes kp-sig-solstice-meter-grow-o {
        0% {
            scale: 0 1;
        }

        100% {
            scale: 1 1;
        }
    }

    @keyframes kp-sig-solstice-meter-pos {
        0% {
            background-position: var(--kp-sig-meter-l0);
        }

        100% {
            background-position: var(--kp-sig-meter-l1);
        }
    }

    /* ── Pointing and pressing [Kenny, 2026-10-07, research/solstice-character] ──
       Pointing at something: the sun climbs its arc under it. Pressing:
       the sun swells inside it. One grammar for every part that can be
       pointed at or pressed: buttons (secondary, primary, ghost,
       destructive, mirror, icon), menu items, calendar days, key figures
       that are links or toggles, chart legend keys. Each answers to two
       numbers, --kp-sig-solstice-point (0 to 1 under the real pointer) and
       --kp-sig-solstice-press (0 to 1 while held), which run 240 ms on the
       curve that is its own mirror (a sine in and out), so a part is
       half-way and nine tenths of the way at the same moment going and
       coming (t50 120 ms, t90 200 ms, the way back is the way there).
       Every layer is a function of those numbers: nothing is switched, so
       nothing can stop half-way. The pointer draws on the part's ::before
       (the sun) and ::after (the lit foot); the press draws on the part's
       own background-image (the swell, the foot edge, the half-way ground),
       so the two never hide each other. The part keeps its own ground and
       ink at rest and in a hover: the register paints no hover face. The
       alarm keeps the plate and paint of its own screen [scope-94]. */

    [data-theme='solstice'] {
        --kp-sig-solstice-touch: cubic-bezier(0.37, 0, 0.63, 1);
        --kp-sig-solstice-contact: 240ms;
        /* G3 and G1: opening a panel takes 2 units, on the sine's last quarter (what comes). */
        --kp-sig-solstice-open: 480ms;
        --kp-sig-solstice-come: cubic-bezier(0.61, 1, 0.88, 1);
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ) {
        /* How far the sun stands above the foot line at noon: a small part
           keeps it under its words. */
        --kp-sig-solstice-rise: 0.4rem;
        --kp-sig-solstice-sun: var(--primary);
        --kp-sig-solstice-cream: hsl(from var(--foreground) h s 97%);
        /* A part is a plate for its own light, clipped to its own corners. */
        contain: paint;
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(.kp-button--sm, .kp-chart__source, .kp-chart__show-all, .kp-icon-button) {
        --kp-sig-solstice-rise: 0.28rem;
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(a.kp-kpi, .kp-kpi--toggle) {
        --kp-sig-solstice-rise: 0.9rem;
    }

    /* On an amber face the sun is the same amber lifted to 90 %: amber on
       amber is not seen, and a dark glow would darken the ground under the
       dark words. */
    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(.kp-button--primary) {
        --kp-sig-solstice-sun: hsl(from var(--primary) h s 90%);
        --kp-sig-solstice-warm: 0.6;
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(.kp-button--destructive) {
        --kp-sig-solstice-held: hsl(from var(--destructive) h s l / 0.4);
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(.kp-button--primary) {
        --kp-sig-solstice-held: var(--primary-active);
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(.kp-button:not(.kp-button--primary, .kp-button--destructive, .kp-button--ghost)) {
        --kp-sig-solstice-held: var(--secondary-active);
        --kp-sig-solstice-ink: var(--secondary-foreground);
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(
            .kp-button--ghost,
            .kp-icon-button,
            .kp-menu__item,
            .kp-calendar__day,
            a.kp-kpi,
            .kp-kpi--toggle,
            .kp-chart__source,
            .kp-chart__show-all
        ) {
        --kp-sig-solstice-held: var(--muted);
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(.kp-chart__source, .kp-chart__show-all) {
        --kp-sig-solstice-ink: var(--muted-foreground);
    }

    /* The two numbers: 1 under the real pointer, 1 while held. A disabled
       part answers to neither. */
    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):hover:not(:disabled, [aria-disabled='true']) {
        --kp-sig-solstice-point: 1;
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):active:not(:disabled, [aria-disabled='true']) {
        --kp-sig-solstice-press: 1;
    }

    /* The sun climbs its arc: x is 1 - cos and y is sin of a quarter turn,
       so it rises along a circle's edge from the start side to the middle
       and stands above the foot line at the end. */
    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        )::before {
        content: '';
        position: absolute;
        z-index: -1;
        inset-inline-start: calc(6% + (1 - cos(var(--kp-sig-solstice-point) * 90deg)) * 44%);
        inset-block-end: calc(-0.8rem + sin(var(--kp-sig-solstice-point) * 90deg) * var(--kp-sig-solstice-rise));
        inline-size: 0.8rem;
        block-size: 0.8rem;
        margin-inline-start: -0.4rem;
        border-radius: 50%;
        background: var(--kp-sig-solstice-sun);
        box-shadow: 0 0 0.5rem 0.1rem hsl(from var(--kp-sig-solstice-sun) h s l / 0.55);
        opacity: min(1, calc(var(--kp-sig-solstice-point) * 6));
        pointer-events: none;
    }

    /* A dome of warm light grows round the sun and the foot edge lights. */
    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        )::after {
        content: '';
        position: absolute;
        z-index: -1;
        inset: 0;
        border-radius: inherit;
        background:
            linear-gradient(var(--kp-sig-solstice-sun), var(--kp-sig-solstice-sun)) 0 100% / 100% 2px no-repeat,
            radial-gradient(
                ellipse 80% 130% at calc(6% + (1 - cos(var(--kp-sig-solstice-point) * 90deg)) * 44%) 100%,
                hsl(from var(--kp-sig-solstice-sun) h s l / 0.36),
                hsl(from var(--kp-sig-solstice-sun) h s l / 0.12) 55%,
                transparent 80%
            ),
            linear-gradient(hsl(from var(--kp-sig-solstice-sun) h s l / 0.06), hsl(from var(--kp-sig-solstice-sun) h s l / 0.06));
        opacity: min(1, calc(var(--kp-sig-solstice-point) * 2));
        pointer-events: none;
    }

    /* The sun swells inside it: a half-sun grows from the middle of the foot
       and fills the part, the foot edge lights hot and the ground goes
       half-way to its held face (the whole way was a pale flash on the amber
       one), all on the same number. A warm lift, not a flash: on the amber
       face the lifted sun is paler than the face, so it is held lower. */
    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ) {
        background-image:
            linear-gradient(
                hsl(from var(--kp-sig-solstice-sun) h s l / calc(var(--kp-sig-solstice-press) * 0.6)),
                hsl(from var(--kp-sig-solstice-sun) h s l / calc(var(--kp-sig-solstice-press) * 0.6))
            ),
            radial-gradient(
                ellipse 70% 105% at 50% 100%,
                hsl(from var(--kp-sig-solstice-sun) h s l / calc(0.16 * var(--kp-sig-solstice-warm, 1) * min(1, var(--kp-sig-solstice-press) * 3))),
                hsl(from var(--kp-sig-solstice-sun) h s l / calc(0.055 * var(--kp-sig-solstice-warm, 1) * min(1, var(--kp-sig-solstice-press) * 3)))
                    42%,
                transparent 72%
            ),
            linear-gradient(
                hsl(from var(--kp-sig-solstice-held, var(--muted)) h s l / calc(var(--kp-sig-solstice-press) * 0.5 * alpha)),
                hsl(from var(--kp-sig-solstice-held, var(--muted)) h s l / calc(var(--kp-sig-solstice-press) * 0.5 * alpha))
            );
        background-position:
            0 100%,
            50% 100%,
            0 0;
        background-size:
            100% 2px,
            calc((0.08 + 1.1 * var(--kp-sig-solstice-press)) * 100%) calc((0.08 + 1.1 * var(--kp-sig-solstice-press)) * 100%),
            100% 100%;
        background-repeat: no-repeat;
    }

    /* The words of a pressed part lift to cream on the same number as the
       light: the tint is amber and the plain ink fell to 3.9 to 4.5:1 there.
       A part whose ink is a pair with its face (the primary and destructive
       buttons, a toned day) keeps it. A dusk-dark halo under the words keeps
       them clear of the brightest part of the light. */
    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):not(.kp-button--primary, .kp-button--destructive, [data-kp-tone]) {
        color: color-mix(
            in oklch,
            var(--kp-sig-solstice-ink, currentColor) calc((1 - var(--kp-sig-solstice-press)) * 100%),
            var(--kp-sig-solstice-cream)
        );
        text-shadow: 0 0 0.45rem hsl(from var(--background) h s l / calc(var(--kp-sig-solstice-press) * 0.85));
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(a.kp-kpi, .kp-kpi--toggle):not([data-kp-tone])
        .kp-kpi__label {
        color: color-mix(in oklch, var(--muted-foreground) calc((1 - var(--kp-sig-solstice-press)) * 100%), var(--kp-sig-solstice-cream));
    }

    /* The grounds the base layer changes under a pointer or a finger go back
       to the part's rest: the register's pointing is the sun, not a face. A
       part keeps its rest border, its rest ground and does not lift. */
    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(:hover, :active):not(:disabled, [aria-disabled='true']) {
        translate: none;
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ).kp-button:is(:hover, :active):not(:disabled) {
        background-color: var(--secondary);
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ).kp-button--primary:is(:hover, :active):not(:disabled) {
        background-color: var(--primary);
        border-color: var(--primary);
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(.kp-button--ghost, .kp-icon-button, .kp-menu__item):is(:hover, :active):not(:disabled, [aria-disabled='true']) {
        background-color: transparent;
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ).kp-button--destructive:is(:hover, :active):not(:disabled) {
        background-color: transparent;
        border-color: var(--destructive);
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(a.kp-kpi, .kp-kpi--toggle):hover:not([aria-pressed='true']) {
        border-color: var(--border);
    }

    [data-theme='solstice']
        :is(.kp-button, .kp-icon-button, .kp-menu__item, .kp-calendar__day, a.kp-kpi, .kp-kpi--toggle, .kp-chart__source, .kp-chart__show-all):not(
            .kp-alarm *
        ):is(.kp-chart__source, .kp-chart__show-all):hover:not(:focus-visible, [aria-pressed='true']) {
        border-color: transparent;
        color: var(--muted-foreground);
    }

    @media (prefers-reduced-motion: no-preference) {
        /* The way back is the way there, per frame: one curve that is its
           own mirror for both directions. */
        [data-theme='solstice']
            :is(
                .kp-button,
                .kp-icon-button,
                .kp-menu__item,
                .kp-calendar__day,
                a.kp-kpi,
                .kp-kpi--toggle,
                .kp-chart__source,
                .kp-chart__show-all
            ):not(.kp-alarm *) {
            transition:
                --kp-sig-solstice-point var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch),
                --kp-sig-solstice-press var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch);
        }
    }

    /* A menu and a popover are kindled (G3, the dome above); they close as it played
       backwards (js/motion.js playClose, the ghost of a hidden popover). */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] :is(.kp-menu-button > .kp-menu, .kp-popover[popover]:not(.kp-tooltip)) {
            animation: kp-sig-solstice-kindled var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) backwards;
        }
    }

    /* The rest of what opens takes the theme's own entrance [all-themes, 2026-10-13, lesson 38:
       these opened by the package's bare fade, or by nothing].
       Every one of them is kindled, G3's dome (480 ms on G1's coming curve), so every part
       that opens in solstice opens one way (coordinator, 2026-10-13; G3 does not name these
       parts, the dome is borrowed for them).
       - The command palette and the tour's card are dialogs: js/motion.js plays the dome
         backwards to close the palette and js/tour.js to end the tour. A tour step is no
         arrival: the card walks, its shape kept.
       - The combobox's list and the date picker's panel are lists that float over the page:
         the dome, played backwards as they close (the ghost of a hidden
         popover, js/motion.js; the date picker's playClose(), whose name stays the same on the
         union of its opening mark and the closing marks, lesson 10).
       - The page's dim round the tour's target and its ring come in on the card's time and
         curve and go back on the curve turned round (css/components.css reads the tokens). */
    @media (prefers-reduced-motion: no-preference) {
        /* The command palette is kindled (G3's dome, as the dialog it is; Kenny,
           2026-10-13: the dawn was "not the right animation for this theme"). js/motion.js
           plays it in the dialog's close time (480 ms) and backwards to close it. */
        [data-theme='solstice'] .kp-palette {
            animation: kp-sig-solstice-kindled var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) backwards;
        }

        [data-theme='solstice'] .kp-tour[open]:not([data-kp-tour-stepping]) {
            animation: kp-sig-solstice-kindled var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) backwards;
        }

        [data-theme='solstice'] .kp-tour[data-kp-tour-stepping] {
            animation: none;
        }

        [data-theme='solstice'] {
            --kp-tour-dim-close: 0 0 0 0 transparent;
            --kp-tour-dim-time: var(--kp-sig-solstice-open);
            /* G1's going curve: the coming curve turned round. */
            --kp-tour-dim-close-ease: cubic-bezier(0.12, 0, 0.39, 0);
        }

        /* `backwards`, not `both`: a ring a finished animation holds cannot be taken back by
           the close's transition (lesson 21). */
        [data-theme='solstice'] [data-kp-tour-target] {
            animation: kp-sig-solstice-tour-ring var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) backwards;
            transition:
                box-shadow var(--kp-sig-solstice-open) var(--kp-sig-solstice-come),
                outline-color var(--kp-sig-solstice-open) var(--kp-sig-solstice-come);
        }

        @keyframes kp-sig-solstice-tour-ring {
            from {
                outline-color: transparent;
            }
        }

        [data-theme='solstice']
            :is(.kp-combobox__list:popover-open, .kp-datepicker__panel:is([data-kp-date-open], [data-kp-closing], [data-kp-reversing]):popover-open) {
            animation: kp-sig-solstice-kindled var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) backwards;
        }

        /* The bar's dropdown and mega menu are the header's menu (G3): they are kindled as a
           menu is and go as that played backwards (the same keyframes under a second name, so
           the browser restarts them). Once the pointer or the focus has left a dropdown,
           js/components.js marks its item `[data-kp-nav-closing]` for `--kp-nav-close-time`
           (Firefox does not hold `display`, lesson 36) and the rule below keeps it drawn; the
           mega menu's item is held until a transition on the panel has played, which is the
           `--kp-sig-solstice-hold` below. It replaces the package's opacity fade. */
        [data-theme='solstice'] {
            --kp-nav-close-time: var(--kp-sig-solstice-open);
        }

        [data-theme='solstice'] .kp-nav__menu {
            --kp-sig-solstice-hold: 0;
            transition: --kp-sig-solstice-hold var(--kp-sig-solstice-open) linear;
        }

        [data-theme='solstice']
            :is(
                .kp-nav__links > li:is(:hover, :focus-within, [data-kp-nav-menu-open]) > .kp-nav__menu:not(.kp-nav__menu--wide),
                .kp-nav__links > li:is([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true'])) > .kp-nav__menu--wide
            ) {
            --kp-sig-solstice-hold: 1;
            animation: kp-sig-solstice-kindled var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) backwards;
        }

        [data-theme='solstice']
            .kp-nav__links
            > li[data-kp-nav-closing]:not(:hover, :focus-within, [data-kp-nav-menu-open])
            > .kp-nav__menu:not(.kp-nav__menu--wide) {
            display: block;
            opacity: 1;
            animation: kp-sig-solstice-kindled-back var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) reverse forwards;
        }

        [data-theme='solstice']
            .kp-nav__links
            > li[data-kp-nav-closing]:not([data-kp-nav-menu-open], :has(> [data-kp-nav-disclosure][aria-expanded='true']))
            > .kp-nav__menu--wide {
            animation: kp-sig-solstice-kindled-back var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) reverse forwards;
        }

        /* On a phone the bar's menu is its list of links under the toggle: it is kindled as
           the menu is and goes as that played backwards, in the same 480 ms (js/components.js
           keeps it open `--kp-nav-close-time` while `[data-kp-nav-closing]`). The lists nested
           in it are its own rows and play nothing of their own. */
        @container kp-nav (max-width: 40rem) {
            [data-theme='solstice'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-open]:not([data-kp-nav-closing]) > .kp-nav__links {
                animation: kp-sig-solstice-kindled var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) backwards;
            }

            [data-theme='solstice'] .kp-nav:has(> .kp-nav__toggle)[data-kp-nav-closing] > .kp-nav__links {
                animation: kp-sig-solstice-kindled-back var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) reverse forwards;
            }

            [data-theme='solstice'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) .kp-nav__links > li > .kp-nav__menu {
                animation: none;
                transition: none;
            }
        }

        /* G3's dome under a second name, played in reverse for a close that must start as
           an animation of its own (the bar's panels). */
        @keyframes kp-sig-solstice-kindled-back {
            from {
                clip-path: ellipse(0 0 at 50% 100%);
                filter: brightness(1.35) saturate(1.3);
            }

            to {
                clip-path: ellipse(150% 150% at 50% 100%);
                filter: brightness(1) saturate(1);
            }
        }
    }

    /* A reader who asked for no motion gets no close of the bar's menus to wait for. */
    @media (prefers-reduced-motion: reduce) {
        [data-theme='solstice'] {
            --kp-nav-close-time: 0ms;
        }
    }

    /* Review round 3 (Kenny, 2026-10-13: "sidenav: Niet de open/close animatie van dit thema",
       "alarm: Niet de open/close animatie van dit thema"). The side navigation and the alarm are
       kindled as the dialog is [G3]: a dome of first light grows from the middle of the foot,
       overbright and warm, cooling to its colour, 2 units (480 ms) on the coming curve; closing is the
       dome sinking back into the foot, the same frames backwards.

       The side navigation (over, push) no longer slides in from its edge (G2, G3: nothing slides in
       from a side, the panel never moves): it is kindled where it opens. Closing plays the dome
       backwards under its second name (`kp-sig-solstice-kindled-back`, lesson 44); only then is the
       panel hidden (`visibility` waits the 480 ms). The content a push panel moves glides in the same
       two units, on the coming curve to make room and on the going curve (the same curve played
       back, G1) to give it back; js/sidenav.js copies this `translate` timing onto it. The panel's
       `translate` never changes: the transition is only its clock. */
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push']) {
            translate: 0 0;
            /* Shut, off the screen once the dome has sunk: the transform waits the open time
               and `translate` stays the clock js/sidenav.js reads. */
            transform: translateX(var(--kp-sidenav-away, -100%));
            visibility: hidden;
            transition:
                translate var(--kp-sig-solstice-open) cubic-bezier(0.12, 0, 0.39, 0),
                visibility 0s linear var(--kp-sig-solstice-open),
                transform 0s linear var(--kp-sig-solstice-open);
            animation: kp-sig-solstice-kindled-back var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) reverse both;
        }

        [data-theme='solstice'] .kp-sidenav:is([data-kp-sidenav-mode='over'], [data-kp-sidenav-mode='push'])[data-kp-sidenav-open='true'] {
            transform: none;
            visibility: visible;
            transition:
                translate var(--kp-sig-solstice-open) var(--kp-sig-solstice-come),
                visibility 0s linear,
                transform 0s;
            animation: kp-sig-solstice-kindled var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) backwards;
        }

        /* Its backdrop (where a page keeps one) dims in the same two units on the coming curve. */
        [data-theme='solstice'] .kp-sidenav__backdrop {
            animation-duration: var(--kp-sig-solstice-open);
            animation-timing-function: var(--kp-sig-solstice-come);
        }

        /* The alarm is a dialog the size of the screen: the whole screen is kindled from the middle of
           its foot, as the dialog; js/motion.js keeps this entrance and plays it backwards to close
           it. The package's fade, rise and scale are not this theme's (G3: never moves, never scales). */
        [data-theme='solstice'] .kp-alarm[open]:not([data-kp-alarm-motion='still']) {
            animation: kp-sig-solstice-kindled var(--kp-sig-solstice-open) var(--kp-sig-solstice-come) backwards;
        }

        [data-theme='solstice'] .kp-alarm:not([data-kp-alarm-motion='still']) :is(.kp-alarm__panel, .kp-alarm__title, .kp-alarm__detail) {
            animation: none;
        }
    }
}

@layer kp.register {
    /* Bottom tab bar [kpadopt-nav] — solstice: a lit horizon. The current tab has the sun raised under it: warm light comes up from the foot of the tab, never down from the top; labels in the serif, sentence case (G2, G8, G15). */
    [data-theme='solstice'] .kp-tabbar {
        background: linear-gradient(0deg, hsl(from var(--primary) h s l / 0.07), var(--card) 70%);
    }

    [data-theme='solstice'] .kp-tabbar__tab {
        isolation: isolate;
        font-family: var(--theme-font-display);
        font-size: calc(var(--kp-tabbar-size, var(--kp-text-xs, 0.75rem)) * 1.1);
    }

    [data-theme='solstice'] .kp-tabbar__tab::before {
        inset: 0;
        block-size: auto;
        z-index: -1;
        border-radius: inherit;
        background: radial-gradient(ellipse 80% 90% at 50% 100%, hsl(from var(--primary) h s l / 0.38), transparent 72%);
        transform-origin: 50% 100%;
        scale: 1 0;
    }

    [data-theme='solstice'] .kp-tabbar__tab[aria-current]:not([aria-current='false'])::before {
        scale: 1 1;
    }

    [data-theme='solstice'] .kp-tabbar__tab:is(:hover, :focus-visible):not([aria-current]:not([aria-current='false']))::before {
        scale: 1 0.5;
    }

    [data-theme='solstice'] .kp-tabbar__tab:active::before {
        filter: brightness(1.25);
    }

    [data-theme='solstice'] .kp-tabbar__badge {
        border-radius: 999px;
        box-shadow: 0 0 10px hsl(from var(--primary) h s l / 0.5);
    }
}
/* ── End of the signature ── */

/* ── Segmented control, list toolbar, key line [kpadopt-controls] ── */
@layer kp.signature {
    [data-theme='solstice'] .kp-segmented {
        --kp-seg-radius: 0.75rem;
        --kp-seg-thumb: linear-gradient(135deg, var(--primary), var(--accent));
        --kp-seg-thumb-ink: var(--background);
        --kp-seg-thumb-edge: 0 0 0 0 transparent;
        --kp-seg-thumb-lift: 0 0 18px hsl(from var(--primary) h s l / 0.45);
        --kp-chip-on: var(--primary);
        --kp-chip-on-ink: var(--background);
    }
    [data-theme='solstice'] .kp-toolbar {
        --kp-toolbar-group-gap: 1.125rem;
    }
    [data-theme='solstice'] .kp-toolbar__label {
        letter-spacing: 0.08em;
    }
    [data-theme='solstice'] .kp-keys {
        --kp-keys-gap: 1rem;
    }
    [data-theme='solstice'] .kp-kbd {
        --kp-kbd-radius: 0.4rem;
        --kp-kbd-ground: var(--secondary);
        --kp-kbd-foot: 2px;
    }
    [data-theme='solstice'] .kp-segmented--chips > .kp-segmented__item[aria-pressed='true'] {
        box-shadow: 0 0 14px hsl(from var(--primary) h s l / 0.4);
    }
    /* A pressed toggle is the sun lit, as a pressed chip of the segmented set is: the amber plate in the dark ink, never the
       cream face with cream words [t56-eye-1018]. */
    [data-theme='solstice'] .kp-button[data-kp-toggle][aria-pressed='true'],
    [data-theme='solstice'] .kp-button[data-kp-toggle][data-kp-look='chip'][aria-pressed='true'] {
        --kp-toggle-on: var(--primary);
        --kp-toggle-on-ink: var(--background);
        background: var(--primary);
        border-color: var(--primary);
        color: var(--background);
        box-shadow: 0 0 14px hsl(from var(--primary) h s l / 0.4);
    }
}

/* ── The dashboard parts: action tiles, status rows, the facet list, the heat grid, the matrix, the bar in a cell, the
   week agenda and the run timeline [kpadopt2] ──
   Solstice's own (themes/solstice/CHARACTER.md): a tile is the charcoal plate lit from below, a rust wash rising from
   its foot and the foot edge catching the light (G7); pointing raises the sun under it, the key figure's own sun
   climbing its arc from the foot with the dome of light round it (G8), and a press is the ember blown on, the sun
   swelling inside it; nothing moves (G14); a failure reddens the sky (G13); waiting is the low sun's light crossing the
   waiting part start to end (G10, the register's skeleton light); a running run sees the sun rise and set at its head;
   the serif speaks in sentence case (G15). Everything on the sine. */
@layer kp.signature {
    [data-theme='solstice'] .kp-actions {
        --kp-actions-gap: 0.75rem;
    }
    [data-theme='solstice'] .kp-action {
        --kp-action-edge: var(--border);
        --kp-action-edge-hover: var(--border);
        --kp-action-press: 0 0;
        --kp-action-title-font: var(--theme-font-display, var(--theme-font-serif, inherit));
        --kp-action-title-weight: 400;
        --kp-action-title-size: 1.0625rem;
        --kp-sig-solstice-rise: 0.4rem;
        --kp-sig-solstice-sun: var(--primary);
        --kp-sig-solstice-held: var(--muted);
        --kp-so-sky: var(--accent);
        --kp-so-foot: hsl(from var(--primary) h s l / 0.55);
        contain: paint;
        background-color: var(--card);
        background-image:
            linear-gradient(
                hsl(from var(--kp-sig-solstice-sun) h s l / calc(var(--kp-sig-solstice-press) * 0.6)),
                hsl(from var(--kp-sig-solstice-sun) h s l / calc(var(--kp-sig-solstice-press) * 0.6))
            ),
            radial-gradient(
                ellipse 70% 105% at 50% 100%,
                hsl(from var(--kp-sig-solstice-sun) h s l / calc(0.16 * min(1, var(--kp-sig-solstice-press) * 3))),
                hsl(from var(--kp-sig-solstice-sun) h s l / calc(0.055 * min(1, var(--kp-sig-solstice-press) * 3))) 42%,
                transparent 72%
            ),
            linear-gradient(var(--kp-so-foot), var(--kp-so-foot)), linear-gradient(to top, hsl(from var(--kp-so-sky) h s l / 0.22), transparent);
        background-position:
            0 100%,
            50% 100%,
            0 100%,
            0 100%;
        background-size:
            100% 2px,
            calc((0.08 + 1.1 * var(--kp-sig-solstice-press)) * 100%) calc((0.08 + 1.1 * var(--kp-sig-solstice-press)) * 100%),
            100% 1px,
            100% 40%;
        background-repeat: no-repeat;
    }
    [data-theme='solstice'] .kp-action:hover:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        --kp-sig-solstice-point: 1;
    }
    [data-theme='solstice'] .kp-action:active:not(:is(:disabled, [aria-disabled='true'], [aria-busy='true'])) {
        --kp-sig-solstice-press: 1;
    }
    /* The sun climbs its arc from the foot; a dome of warm light grows round it and the foot edge lights. */
    [data-theme='solstice'] .kp-action::before {
        content: '';
        position: absolute;
        z-index: -1;
        inset-inline-start: calc(6% + (1 - cos(var(--kp-sig-solstice-point) * 90deg)) * 44%);
        inset-block-end: calc(-0.8rem + sin(var(--kp-sig-solstice-point) * 90deg) * var(--kp-sig-solstice-rise));
        inline-size: 0.8rem;
        block-size: 0.8rem;
        margin-inline-start: -0.4rem;
        border-radius: 50%;
        background: var(--kp-sig-solstice-sun);
        box-shadow: 0 0 0.5rem 0.1rem hsl(from var(--kp-sig-solstice-sun) h s l / 0.55);
        opacity: min(1, calc(var(--kp-sig-solstice-point) * 6));
        pointer-events: none;
    }
    [data-theme='solstice'] .kp-action::after,
    [data-theme='solstice'] .kp-action--destructive::after {
        content: '';
        position: absolute;
        z-index: -1;
        inset: 0;
        inline-size: auto;
        border-radius: inherit;
        background:
            linear-gradient(var(--kp-sig-solstice-sun), var(--kp-sig-solstice-sun)) 0 100% / 100% 2px no-repeat,
            radial-gradient(
                ellipse 80% 130% at calc(6% + (1 - cos(var(--kp-sig-solstice-point) * 90deg)) * 44%) 100%,
                hsl(from var(--kp-sig-solstice-sun) h s l / 0.36),
                hsl(from var(--kp-sig-solstice-sun) h s l / 0.12) 55%,
                transparent 80%
            );
        opacity: min(1, calc(var(--kp-sig-solstice-point) * 2));
        pointer-events: none;
    }
    [data-theme='solstice'] .kp-action > :not(.kp-action__state) {
        position: relative;
    }
    [data-theme='solstice'] .kp-action:not(:is(.kp-action--destructive, :disabled, [aria-disabled='true'])) {
        color: color-mix(
            in oklch,
            var(--card-foreground) calc((1 - var(--kp-sig-solstice-press)) * 100%),
            var(--kp-sig-solstice-cream, var(--foreground))
        );
    }
    [data-theme='solstice'] .kp-action:is(:disabled, [aria-disabled='true']) {
        --kp-so-sky: transparent;
        --kp-so-foot: var(--border);
        background-color: var(--muted);
    }
    /* Destructive: the sky reddens; the wash and the foot in the red, the title in the red lifted to read, the sun red. */
    [data-theme='solstice'] .kp-action--destructive:not(:is(:disabled, [aria-disabled='true'])) {
        --kp-action-tone-edge: var(--border);
        --kp-action-tone-edge-hover: var(--border);
        --kp-so-sky: var(--destructive);
        --kp-so-foot: var(--destructive);
        --kp-sig-solstice-sun: var(--destructive);
    }
    [data-theme='solstice'] .kp-action--destructive > .kp-action__title {
        color: hsl(from var(--destructive) h s 68%);
    }
    [data-theme='solstice'] .kp-action--destructive:is(:disabled, [aria-disabled='true']) > .kp-action__title {
        color: inherit;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-action {
            transition:
                --kp-sig-solstice-point var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch),
                --kp-sig-solstice-press var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch);
        }
    }

    /* Status rows: plates lit from below, fainter; the detail in the serif's sentence case. A failed row's sky reddens;
       a loading row watches the low sun cross along its foot. */
    [data-theme='solstice'] .kp-statuslist {
        --kp-statuslist-gap: 0.5rem;
    }
    [data-theme='solstice'] .kp-statusrow {
        --kp-statusrow-radius: var(--radius);
        --kp-statusrow-edge: var(--border);
        --kp-so-sky: var(--accent);
        --kp-so-foot: hsl(from var(--primary) h s l / 0.45);
        position: relative;
        overflow: clip;
        background:
            linear-gradient(var(--kp-so-foot), var(--kp-so-foot)) 0 100% / 100% 1px no-repeat,
            linear-gradient(to top, hsl(from var(--kp-so-sky) h s l / 0.14), transparent) 0 100% / 100% 45% no-repeat,
            var(--card);
    }
    [data-theme='solstice'] .kp-statusrow[data-state='failed'] {
        --kp-statusrow-state-edge: var(--border);
        --kp-so-sky: var(--destructive);
        --kp-so-foot: var(--destructive);
    }
    [data-theme='solstice'] .kp-statusrow[data-state='failed'] .kp-statusrow__detail {
        color: hsl(from var(--destructive) h s 68%);
    }
    [data-theme='solstice'] .kp-statusrow[data-state='empty'] {
        --kp-so-sky: transparent;
        --kp-so-foot: var(--border);
        border-style: dashed;
    }
    [data-theme='solstice'] .kp-statusrow[data-state='loading']::after {
        content: '';
        position: absolute;
        inset-block: auto 0;
        inset-inline-start: 0;
        inline-size: 37%;
        block-size: 1.2rem;
        background: radial-gradient(circle at 50% 100%, var(--primary) 0 0.28rem, hsl(from var(--primary) h s l / 0.35) 0.3rem, transparent 0.9rem);
        transform: translateX(-100%);
        pointer-events: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-statusrow[data-state='loading']::after {
            animation: kp-sig-solstice-solstice-light 3600ms linear infinite;
        }
    }
    @media (prefers-reduced-motion: reduce) {
        [data-theme='solstice'] .kp-statusrow[data-state='loading']::after {
            transform: translateX(85%);
        }
    }

    /* Facets: softly rounded rows; pointing lights the row's foot in amber. The counts on their way are the skeleton's
       muted pills, the low light crossing them. */
    [data-theme='solstice'] .kp-facets {
        --kp-facet-radius: calc(var(--radius) * 0.8);
    }
    [data-theme='solstice'] .kp-facet {
        --kp-facet-hover: linear-gradient(to top, hsl(from var(--accent) h s l / 0.2), transparent 70%);
    }
    [data-theme='solstice'] .kp-facet:hover {
        background:
            linear-gradient(var(--primary), var(--primary)) 0 100% / 100% 2px no-repeat,
            linear-gradient(to top, hsl(from var(--accent) h s l / 0.2), transparent 70%);
    }
    [data-theme='solstice'] .kp-facets[aria-busy='true'] .kp-facet__count {
        position: relative;
        overflow: hidden;
        border-radius: 999px;
        background: var(--muted);
        animation: none;
    }
    [data-theme='solstice'] .kp-facets[aria-busy='true'] .kp-facet__count::after {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 60%;
        background: radial-gradient(ellipse closest-side, hsl(from var(--primary) h s l / 0.45), transparent);
        transform: translateX(-100%);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-facets[aria-busy='true'] .kp-facet__count::after {
            animation: kp-sig-solstice-solstice-light 3600ms ease-in-out infinite;
        }
        [data-theme='solstice'] .kp-facets[aria-busy='true'] li:nth-child(2n) .kp-facet__count::after {
            animation-delay: 240ms;
        }
    }

    /* Heat grid and matrix: each cell a hillside lit from its foot; pointing lights the foot in full amber, nothing
       moves; the pick is the halo. Waiting: the cells stand as the skeleton's muted ground, and the low light crosses
       each row (the matrix as one surface). */
    [data-theme='solstice'] :is(.kp-heat, .kp-matrix) {
        --kp-heat-cell-radius: 5px;
        --kp-heat-cell-hover: none;
        --kp-matrix-cell-hover: none;
    }
    [data-theme='solstice'] .kp-heat {
        --kp-heat-gap-y: 6px;
    }
    [data-theme='solstice'] .kp-matrix {
        --kp-heat-cell-radius: calc(var(--radius) * 0.8);
        --kp-matrix-gap: 4px;
    }
    [data-theme='solstice']
        .kp-heat__cell:is([data-kp-tone='ok'], [data-kp-tone='warn'], [data-kp-tone='bad'], [data-kp-tone='level']):not([data-kp-share]),
    [data-theme='solstice'] .kp-heat__swatch:is([data-kp-tone='ok'], [data-kp-tone='warn'], [data-kp-tone='bad'], [data-kp-tone='level']) {
        background-image: linear-gradient(to top, hsl(from var(--primary) h s 85% / 0.55) 0 18%, transparent 18%), var(--kp-heat-pattern);
    }
    [data-theme='solstice'] .kp-heat__cell:hover:not(.kp-skeleton, [aria-disabled='true']),
    [data-theme='solstice'] .kp-matrix__cell:hover:not([data-kp-inert], [aria-disabled='true'], .kp-skeleton) {
        box-shadow:
            inset 0 -2px 0 var(--primary),
            0 0.35rem 0.6rem -0.35rem hsl(from var(--primary) h s l / 0.7);
    }
    [data-theme='solstice'] .kp-heat__cell[data-kp-picked],
    [data-theme='solstice'] .kp-matrix__cell[aria-pressed='true'] {
        outline: 2px solid var(--primary);
        outline-offset: 2px;
        box-shadow: 0 0 0.6rem hsl(from var(--primary) h s l / 0.45);
    }
    [data-theme='solstice'] :is(.kp-heat__label, .kp-matrix__name) {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.9375rem;
    }
    [data-theme='solstice'] .kp-heat__label-button[aria-pressed='true'] {
        background: linear-gradient(to top, hsl(from var(--primary) h s l / 0.3), transparent);
        color: var(--foreground);
        box-shadow: inset 0 -2px 0 var(--primary);
    }
    [data-theme='solstice'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        background: var(--muted);
        animation: none;
    }
    [data-theme='solstice'] :is(.kp-heat__cells:has(> .kp-skeleton), .kp-matrix:has(.kp-matrix__cell.kp-skeleton)) {
        position: relative;
        overflow: clip;
    }
    [data-theme='solstice'] :is(.kp-heat__cells:has(> .kp-skeleton), .kp-matrix:has(.kp-matrix__cell.kp-skeleton))::after {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 37%;
        background: radial-gradient(ellipse closest-side, hsl(from var(--primary) h s l / 0.32), transparent);
        transform: translateX(-100%);
        pointer-events: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] :is(.kp-heat__cells:has(> .kp-skeleton), .kp-matrix:has(.kp-matrix__cell.kp-skeleton))::after {
            animation: kp-sig-solstice-solstice-light 3600ms ease-in-out infinite;
        }
        [data-theme='solstice'] .kp-heat__row:nth-child(2n) .kp-heat__cells::after {
            animation-delay: 240ms;
        }
        [data-theme='solstice'] :is(.kp-heat__cell, .kp-matrix__cell) {
            transition: box-shadow var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch);
        }
    }
    [data-theme='solstice'] .kp-bar-cell {
        --kp-bar-cell-gap: var(--kp-space-sm, 0.5rem);
        font-variant-numeric: tabular-nums;
    }

    /* Week agenda and run timeline: pills lit from their foot in the series' light; pointing lights the foot in amber;
       the next run wears the halo; the line for now is the low sun's amber with the sun at its head. A running run
       watches the sun rise and set at its growing head, on its own short horizon, no marching stripes. */
    [data-theme='solstice'] .kp-week {
        --kp-week-pill-radius: calc(var(--radius) * 0.8);
        --kp-week-now: var(--primary);
    }
    [data-theme='solstice'] .kp-gantt {
        --kp-gantt-bar-radius: calc(var(--radius) * 0.8);
        --kp-gantt-now: var(--primary);
        --kp-gantt-state-ground: var(--card);
    }
    [data-theme='solstice'] .kp-week__pill:not([data-kp-state='off'], [data-kp-state='skipped'], [data-kp-state='reference']) {
        background-image: linear-gradient(to top, hsl(from var(--kp-week-ink) h s l / 0.3), transparent 80%);
        box-shadow: inset 0 -1px 0 hsl(from var(--kp-week-ink) h s l / 0.8);
    }
    [data-theme='solstice'] .kp-week__pill:is(button):hover,
    [data-theme='solstice'] .kp-gantt__run:is(button):hover {
        box-shadow:
            inset 0 -2px 0 var(--primary),
            0 0.3rem 0.5rem -0.3rem hsl(from var(--primary) h s l / 0.7);
    }
    [data-theme='solstice'] .kp-week__pill[data-kp-state='next'] {
        box-shadow:
            0 0 0 2px var(--primary),
            0 0 0.6rem hsl(from var(--primary) h s l / 0.45);
    }
    [data-theme='solstice'] .kp-week__now::before,
    [data-theme='solstice'] .kp-gantt__now::before {
        content: '';
        position: absolute;
        inline-size: 9px;
        block-size: 9px;
        border-radius: 50%;
        background: var(--primary);
        box-shadow: 0 0 0.4rem 0.1rem hsl(from var(--primary) h s l / 0.55);
    }
    [data-theme='solstice'] .kp-week__now::before {
        inset-inline-start: -4.5px;
        inset-block-start: -5.5px;
    }
    [data-theme='solstice'] .kp-gantt__now::before {
        inset-block-start: 0;
        inset-inline-start: -5.5px;
    }
    [data-theme='solstice'] :is(.kp-week__head, .kp-gantt__lane) {
        font-family: var(--theme-font-display, inherit);
    }
    [data-theme='solstice'] .kp-week__head {
        letter-spacing: 0.01em;
        text-transform: none;
        font-size: 0.875rem;
    }
    [data-theme='solstice'] :is(.kp-gantt__run, .kp-gantt__swatch)[data-kp-state='running'] {
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.5), hsl(from var(--accent) h s l / 0.12));
        border-color: hsl(from var(--primary) h s l / 0.7);
        color: var(--foreground);
        box-shadow: inset 0 -1px 0 var(--primary);
    }
    [data-theme='solstice'] .kp-gantt__run[data-kp-state='running']::after {
        content: '';
        position: absolute;
        inset-block-end: 1px;
        inset-inline-end: 2px;
        inline-size: min(0.65rem, 60%);
        aspect-ratio: 1;
        border-radius: 50%;
        background: var(--primary);
        box-shadow: 0 0 0.4rem hsl(from var(--primary) h s l / 0.7);
        pointer-events: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-gantt__run[data-kp-state='running'] {
            animation: none;
        }
        [data-theme='solstice'] .kp-gantt__run[data-kp-state='running']::after {
            animation: kp-sig-solstice-solstice-dawn 1200ms var(--kp-sig-solstice-come) infinite alternate;
        }
        [data-theme='solstice'] :is(.kp-week__pill, .kp-gantt__run) {
            transition: box-shadow var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch);
        }
    }
}

/* ── The dashboard parts: what the package leaves to a register [kpadopt2-repairs] ──
   Formal keeps these parts exactly as Kenny approved them; this theme takes the three repairs the review asks for: a
   loading heat grid or matrix row as tall as its ready row (no skeleton gap between cells), an empty or failed run
   timeline with a lane-sized space for its sentence (never over the legend), the sentence as wide as its words on the
   theme's ground (never through a rule or a ghost bar), and an axis label near the end edge standing before its rule. */
@layer kp.signature {
    [data-theme='solstice'] :is(.kp-heat__cell, .kp-matrix__cell).kp-skeleton {
        margin-block: 0;
    }
    [data-theme='solstice'] .kp-gantt {
        --kp-gantt-tick-flip: 1;
    }
    [data-theme='solstice'] .kp-gantt:is([data-kp-state='empty'], [data-kp-state='error']) .kp-gantt__body:not(:has(.kp-gantt__lane)) {
        min-block-size: 5.25rem;
    }
    [data-theme='solstice'] .kp-gantt__state {
        box-sizing: border-box;
        display: block;
        inline-size: fit-content;
        max-inline-size: calc(100% - 2 * var(--kp-space-md, 0.75rem));
        block-size: fit-content;
        margin: auto;
        padding: var(--kp-space-xs, 0.25rem) var(--kp-space-sm, 0.5rem);
        border-radius: var(--kp-radius-sm, calc(var(--radius, 0.5rem) / 2));
        background: var(--kp-gantt-state-ground, transparent);
    }
    /* The matrix's corner key breaks as two balanced lines when it has to, never leaving an arrow alone. */
    [data-theme='solstice'] .kp-matrix__corner {
        text-wrap: balance;
    }
    /* A ghost bar stands where its run would, as in formal: absolute in its track, so a second ghost of one track never
       drops under the first and out of the timeline onto the legend. */
    [data-theme='solstice'] .kp-gantt__ghost .kp-gantt__run.kp-skeleton {
        position: absolute;
    }
}

/* ── The six opt-in options of the dashboard adoption, round 3, in this theme [kpadopt3] ──
   The nav bar's separator, the timeline's day buttons and series runs, the week agenda's upcoming list on a phone and
   the facet swatch's identity pattern (the choice-filter value and the heat grid's End are behaviour only).
   Solstice's own (themes/solstice/CHARACTER.md): the separator is the divider's horizon with its peak
   of low sun, stood upright, the amber point leaning into the next group; lying down across the phone's list the peak
   rises from the middle of the line. A day on the axis flares from its foot under the pointer; pressed it wears the
   halo, the primary's light rising from the horizon under it. A series' finished run is lit from its foot in its own
   light; the facet pattern is a soft lantern of its hue, lit from below. */
@layer kp.signature {
    [data-theme='solstice'] .kp-nav__sep {
        position: relative;
        border-inline-start-color: var(--border);
    }
    [data-theme='solstice'] .kp-nav__sep::after {
        content: '';
        position: absolute;
        inset-block-start: calc(50% - 4px);
        inset-inline-start: 0;
        inline-size: 5px;
        block-size: 8px;
        background: var(--accent);
        clip-path: polygon(0 0, 100% 50%, 0 100%);
    }
    @container kp-nav (max-width: 40rem) {
        [data-theme='solstice'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep {
            border-block-start-color: var(--border);
        }
        [data-theme='solstice'] .kp-nav:has(> .kp-nav__toggle):is([data-kp-nav-open], [data-kp-nav-closing]) > .kp-nav__links > .kp-nav__sep::after {
            inset-block-start: -5px;
            inset-inline-start: calc(50% - 4px);
            inline-size: 8px;
            block-size: 5px;
            clip-path: polygon(50% 0, 100% 100%, 0 100%);
        }
    }

    [data-theme='solstice'] .kp-gantt__tick:is(button) {
        border-radius: calc(var(--radius) * 0.8) calc(var(--radius) * 0.8) 0 0;
        text-decoration: none;
    }
    [data-theme='solstice'] .kp-gantt__tick:is(button):hover {
        background: radial-gradient(ellipse 70% 90% at 50% 100%, hsl(from var(--accent) h s l / 0.35), transparent 70%);
        color: var(--foreground);
    }
    [data-theme='solstice'] .kp-gantt__tick:is(button)[aria-pressed='true'] {
        background: radial-gradient(ellipse 85% 120% at 50% 100%, hsl(from var(--primary) h s l / 0.45), hsl(from var(--primary) h s l / 0.1) 75%);
        color: var(--foreground);
        box-shadow: inset 0 -2px 0 var(--primary);
    }
    [data-theme='solstice'] .kp-gantt__run[data-kp-state='ok'][data-kp-series] {
        box-shadow:
            inset 0 -2px 0 var(--kp-gantt-series),
            inset 0 -8px 8px -6px hsl(from var(--kp-gantt-series) h s l / 0.55);
    }
    [data-theme='solstice'] .kp-gantt__run[data-kp-state='ok'][data-kp-series]:hover {
        box-shadow:
            inset 0 -2px 0 var(--accent),
            inset 0 -8px 8px -6px hsl(from var(--accent) h s l / 0.55);
    }
    [data-theme='solstice'] .kp-facet__swatch[data-kp-facet-pattern] {
        border-radius: 35%;
        box-shadow: 0 2px 4px -1px hsl(from var(--kp-facet-swatch-colour, var(--primary)) h s l / 0.6);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-gantt__tick:is(button) {
            transition: box-shadow var(--kp-sig-solstice-contact, var(--fx-duration)) var(--kp-sig-solstice-touch, var(--fx-ease));
        }
    }
}

/* ── The kpadopt4 data pieces, in this theme [kpadopt4] ──
   Solstice's own (themes/solstice/CHARACTER.md): a part is lit from its foot, the sun is the only body that travels and
   the only mark of a threshold or a pick, a pick is the halo (G16), a warning reddens the sky and keeps its words in the
   tone's ink (G13), the serif speaks in sentence case (G15), a new number comes up into the light and cools (G3, G9). */
@layer kp.signature {
    /* The identity mark: a lantern, its ground lit from the foot in its own colour, its letters in the serif; round it is
       the sun. The pick is the halo: a ring held off the plate by a ring of the card and a glow. */
    [data-theme='solstice'] .kp-idmark {
        --kp-idmark-radius: min(var(--radius), calc(var(--kp-idmark-s) * 0.3));
        --kp-idmark-tint: 10%;
        background:
            linear-gradient(to top, color-mix(in oklab, var(--kp-idmark-c) 34%, transparent), transparent 62%),
            color-mix(in oklab, var(--kp-idmark-c) var(--kp-idmark-tint), var(--card));
        box-shadow: inset 0 -1px 0 color-mix(in oklab, var(--kp-idmark-c) 80%, transparent);
        font-family: var(--theme-font-display, inherit);
        font-size: calc(var(--kp-idmark-s) * 0.46);
        font-weight: 400;
        letter-spacing: 0;
    }
    [data-theme='solstice'] .kp-idmark--round {
        box-shadow:
            inset 0 -1px 0 color-mix(in oklab, var(--kp-idmark-c) 80%, transparent),
            0 0 0.5rem -0.1rem color-mix(in oklab, var(--kp-idmark-c) 55%, transparent);
    }
    [data-theme='solstice'] .kp-idmark--pattern {
        background: var(--kp-idmark-c);
        box-shadow: inset 0 -0.4em 0.5em -0.3em hsl(from var(--foreground) h s l / 0.35);
    }
    [data-theme='solstice'] .kp-idmark--glyph::after {
        box-shadow:
            0 0 0 1.5px var(--card),
            0 0 0.35rem color-mix(in oklab, var(--kp-idmark-c) 70%, transparent);
    }
    [data-theme='solstice'] .kp-idmark[aria-current]:not([aria-current='false']),
    [data-theme='solstice'] .kp-idmark[data-kp-idmark-selected] {
        box-shadow:
            0 0 0 3px var(--card),
            0 0 0 5px var(--primary),
            0 0 0.9rem 0.2rem hsl(from var(--primary) h s l / 0.4);
    }
    [data-theme='solstice'] .kp-idmark[data-kp-idmark-empty] {
        background: linear-gradient(to top, hsl(from var(--border-strong) h s l / 0.3), transparent 60%), var(--muted);
        box-shadow: none;
    }
    [data-theme='solstice'] .kp-idmark-group > .kp-idmark,
    [data-theme='solstice'] .kp-idmark-group > .kp-idmark-group__more {
        box-shadow: 0 0 0 2px var(--card);
    }
    [data-theme='solstice'] .kp-idmark-group__more {
        border-radius: min(var(--radius), calc(var(--kp-idmark-s) * 0.3));
        font-family: var(--theme-font-display, inherit);
    }

    /* The share bar: a horizon, each part lit at its foot, the threshold the sun on its stalk (the meter's mark), the sum
       past the whole a ✳ past the end. The legend row under the pointer takes the lit foot. */
    [data-theme='solstice'] .kp-stackbar {
        --kp-stackbar-radius: calc(var(--radius) * 0.4);
    }
    [data-theme='solstice'] .kp-stackbar__title {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.0625rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-stackbar__bar {
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.25), var(--muted) 70%);
        box-shadow: inset 0 -1px 0 var(--border-strong);
    }
    [data-theme='solstice'] .kp-stackbar__seg {
        background-image: linear-gradient(to top, hsl(from var(--foreground) h s l / 0.3), transparent 55%);
        background-color: var(--kp-stackbar-colour, var(--chart-1));
    }
    [data-theme='solstice'] .kp-stackbar__seg[data-kp-stackbar-hatch] {
        background-image:
            repeating-linear-gradient(-45deg, transparent 0 3px, var(--card) 3px 4.5px),
            linear-gradient(to top, hsl(from var(--foreground) h s l / 0.3), transparent 55%);
    }
    [data-theme='solstice'] .kp-stackbar__seg[data-kp-stackbar-lit] {
        box-shadow:
            inset calc(var(--kp-stackbar-gap, 2px) * -1) 0 0 var(--card),
            0 0 0 2px var(--card),
            0 0 0 4px var(--primary),
            0 0.4rem 0.7rem -0.3rem hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='solstice'] .kp-stackbar__mark {
        inset-block: -0.2rem;
        inline-size: 1px;
        background: var(--foreground);
        box-shadow: none;
    }
    [data-theme='solstice'] .kp-stackbar__mark::before {
        content: '';
        position: absolute;
        inset-block-start: -0.3rem;
        inset-inline-start: -0.2rem;
        inline-size: 0.4rem;
        aspect-ratio: 1;
        border-radius: 50%;
        background: var(--primary);
        box-shadow: 0 0 0.4rem hsl(from var(--primary) h s l / 0.7);
    }
    [data-theme='solstice'] .kp-stackbar__bar[data-kp-over]::after {
        content: '\2733';
        color: hsl(from var(--destructive) h s 68%);
    }
    [data-theme='solstice'] .kp-stackbar__item[data-kp-stackbar-lit] {
        background:
            linear-gradient(var(--primary), var(--primary)) 0 100% / 100% 2px no-repeat,
            linear-gradient(to top, hsl(from var(--accent) h s l / 0.28), transparent 85%);
    }
    [data-theme='solstice'] .kp-stackbar__swatch {
        border-radius: 50%;
        background-image: linear-gradient(to top, hsl(from var(--foreground) h s l / 0.3), transparent 55%);
    }
    [data-theme='solstice'] .kp-stackbar__item[data-kp-stackbar-rest] .kp-stackbar__swatch {
        background-image: none;
    }
    [data-theme='solstice'] .kp-stackbar__label {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.9375rem;
    }
    [data-theme='solstice'] .kp-stackbar__item[data-kp-stackbar-over] .kp-stackbar__value {
        color: hsl(from var(--destructive) h s 68%);
    }
    /* Not read, or failed: the empty state's own footprint, the sky over it dim; a failure reddens it. */
    [data-theme='solstice'] .kp-stackbar__note {
        border-style: solid;
        border-color: var(--border);
        background:
            linear-gradient(var(--kp-so-foot, var(--border)), var(--kp-so-foot, var(--border))) 0 100% / 100% 1px no-repeat,
            linear-gradient(to top, hsl(from var(--kp-so-sky, var(--accent)) h s l / 0.14), transparent 55%);
        font-family: var(--theme-font-display, inherit);
        font-size: 1rem;
    }
    [data-theme='solstice'] .kp-stackbar[data-kp-state='error'] .kp-stackbar__note,
    [data-theme='solstice'] .kp-bullets[data-kp-state='error'] .kp-bullets__note {
        --kp-so-sky: var(--destructive);
        --kp-so-foot: var(--destructive);
    }

    /* Bullet rows: the row under the pointer has the sun risen under it; the figure's tone is the sky, never a plate: a
       warning is its light in its ink, a failure the red lifted to read, each on a faint wash of its own foot. */
    [data-theme='solstice'] .kp-bullets__row {
        border-radius: calc(var(--radius) * 0.8);
    }
    [data-theme='solstice'] .kp-bullets__row:has(.kp-bullets__link:hover) {
        background:
            linear-gradient(var(--primary), var(--primary)) 0 100% / 100% 2px no-repeat,
            linear-gradient(to top, hsl(from var(--accent) h s l / 0.26), transparent 80%);
    }
    [data-theme='solstice'] .kp-bullets__row:has(.kp-bullets__link:hover) .kp-bullets__label {
        text-decoration: none;
    }
    [data-theme='solstice'] .kp-bullets__label {
        font-family: var(--theme-font-display, inherit);
        font-size: 1rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-bullets__wait--what > .kp-bullets__wait:first-child,
    [data-theme='solstice'] .kp-bullets__wait--figure {
        font-size: 1rem;
    }
    [data-theme='solstice'] .kp-bullets__figure {
        font-family: var(--theme-font-display, inherit);
        font-size: 1rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure,
    [data-theme='solstice'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        border-radius: calc(var(--radius) * 0.5);
        box-shadow: inset 0 -1px 0 currentColor;
    }
    [data-theme='solstice'] .kp-bullets__row[data-kp-tone='warning'] .kp-bullets__figure {
        background: linear-gradient(to top, hsl(from var(--warning) h s l / 0.5), hsl(from var(--warning) h s l / 0.12));
        color: var(--warning-foreground);
    }
    [data-theme='solstice'] .kp-bullets__row[data-kp-tone='destructive'] .kp-bullets__figure {
        background: linear-gradient(to top, hsl(from var(--destructive) h s l / 0.45), hsl(from var(--destructive) h s l / 0.1));
        color: hsl(from var(--destructive) h s 72%);
    }

    /* The key-value grid: the keys in the serif, a row lit at its foot only where it fails or changed. */
    [data-theme='solstice'] .kp-kv {
        font-size: 0.9375rem;
    }
    [data-theme='solstice'] .kp-kv__row {
        align-items: start;
    }
    [data-theme='solstice'] .kp-kv__row > dt {
        font-family: var(--theme-font-display, inherit);
    }
    [data-theme='solstice'] .kp-kv--lines > .kp-kv__row {
        border-block-end-color: var(--border);
    }
    [data-theme='solstice'] .kp-kv {
        --kp-glyph-changed: '\00a0\25CF';
    }
    [data-theme='solstice'] .kp-kv__row[data-kp-changed] > dt::after {
        text-shadow: 0 0 0.45em hsl(from var(--primary) h s l / 0.9);
    }
    [data-theme='solstice'] .kp-kv__row[data-kp-state='error'] {
        background: linear-gradient(to top, hsl(from var(--destructive) h s l / 0.16), transparent 70%);
        box-shadow: inset 0 -1px 0 var(--destructive);
    }
    [data-theme='solstice'] .kp-kv__row[data-kp-state='error']::before {
        content: none;
    }

    /* Form rows: the label in the serif; changed and not saved, the sun stands on the row's start edge, lit from its
       foot (an unsaved row is a thing the day has touched); an error reddens the same edge. */
    [data-theme='solstice'] .kp-formrow__label {
        font-family: var(--theme-font-display, inherit);
        font-size: 1rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-formrow[data-kp-changed]::before,
    [data-theme='solstice'] .kp-formrow[data-kp-state='error']::before {
        inline-size: 3px;
        border-radius: 3px;
        background: linear-gradient(to top, var(--primary), hsl(from var(--primary) h s l / 0.15));
        box-shadow: 0 0 0.5rem hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='solstice'] .kp-formrow[data-kp-state='error']::before {
        background: linear-gradient(to top, var(--destructive), hsl(from var(--destructive) h s l / 0.15));
        box-shadow: 0 0 0.5rem hsl(from var(--destructive) h s l / 0.5);
    }
    [data-theme='solstice'] .kp-formrows--lines > .kp-formrow {
        border-block-end-color: var(--border);
    }

    /* The code block: a plate lit from below, its head warmed, its keys in amber (the sun acts), a failure's note reddened. */
    [data-theme='solstice'] .kp-code {
        background: var(--kp-code-bg, var(--card));
        box-shadow: inset 0 -1px 0 hsl(from var(--primary) h s l / 0.45);
    }
    [data-theme='solstice'] .kp-code__head {
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.14), transparent);
    }
    [data-theme='solstice'] .kp-code__title {
        font-family: var(--theme-font-display, inherit);
        font-size: 1rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-code__body,
    [data-theme='solstice'] .kp-code__note {
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.1), transparent 45%), var(--muted);
    }
    [data-theme='solstice'] .kp-code[data-kp-state='error'] .kp-code__note {
        background: linear-gradient(to top, hsl(from var(--destructive) h s l / 0.2), transparent 70%), var(--muted);
        box-shadow: inset 0 -1px 0 var(--destructive);
    }

    /* The header line: the title in the serif; the freshness a quiet line. */
    [data-theme='solstice'] .kp-page-header__line > .kp-page-header__title {
        font-family: var(--theme-font-display, inherit);
        font-weight: 400;
    }

    /* A number that ticks: while it runs it stands overbright in the first light and cools into its ink when it lands
       (G3, G9); it never swells or jumps. */
    [data-theme='solstice'] [data-kp-tick] {
        transition:
            color calc(var(--kp-sig-solstice-contact) * 3) var(--kp-sig-solstice-touch),
            text-shadow calc(var(--kp-sig-solstice-contact) * 3) var(--kp-sig-solstice-touch);
    }
    [data-theme='solstice'] [data-kp-tick][data-kp-tick-state='running'] {
        color: hsl(from var(--primary) h s 80%);
        text-shadow: 0 0 0.6em hsl(from var(--primary) h s l / 0.7);
    }
    @media (prefers-reduced-motion: reduce) {
        [data-theme='solstice'] [data-kp-tick] {
            transition: none;
        }
    }
}

/* ── The uptime strip, in this theme [kpadopt4-ideas] ──
   A strip of days is a hillside lit from its foot: each cell keeps its tone's fill and its pattern (a state is never
   colour alone) and takes the low light at its foot; pointing raises the sun under a cell (G8), the room above the strip
   already makes it taller; waiting is the low sun's light crossing the strip start to end (G10). */
@layer kp.signature {
    [data-theme='solstice'] .kp-uptime {
        --kp-uptime-cell-radius: 2px;
    }
    [data-theme='solstice'] .kp-uptime__title {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.0625rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-uptime__percent {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.0625rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-uptime__cell:not([data-kp-tone='none'], .kp-skeleton) {
        background-image: linear-gradient(to top, hsl(from var(--foreground) h s l / 0.3), transparent 45%), var(--kp-uptime-pattern);
        box-shadow: inset 0 -1px 0 hsl(from var(--foreground) h s l / 0.35);
    }
    [data-theme='solstice'] .kp-uptime__cell:is(:hover, :focus-visible, [aria-expanded='true']):not(.kp-skeleton) {
        box-shadow:
            inset 0 -2px 0 var(--primary),
            0 0.3rem 0.5rem -0.25rem hsl(from var(--primary) h s l / 0.7);
    }
    [data-theme='solstice'] .kp-uptime__summary[data-kp-tone='error'] {
        background: linear-gradient(to top, hsl(from var(--destructive) h s l / 0.3), hsl(from var(--destructive) h s l / 0.08));
        box-shadow: inset 0 -1px 0 var(--destructive);
        color: hsl(from var(--destructive) h s 72%);
    }
    [data-theme='solstice'] .kp-uptime__axis {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.8125rem;
    }
    [data-theme='solstice'] .kp-uptime__info-title {
        font-family: var(--theme-font-display, inherit);
        font-size: 1rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-uptime__swatch {
        border-radius: 2px;
    }
    [data-theme='solstice'] .kp-uptime .kp-uptime__cell.kp-skeleton {
        background: var(--muted);
        animation: none;
    }
    [data-theme='solstice'] .kp-uptime__track:has(> .kp-skeleton) {
        position: relative;
    }
    [data-theme='solstice'] .kp-uptime__track:has(> .kp-skeleton)::after {
        content: '';
        position: absolute;
        inset-block: 0;
        inset-inline-start: 0;
        inline-size: 37%;
        background: radial-gradient(ellipse closest-side, hsl(from var(--primary) h s l / 0.32), transparent);
        transform: translateX(-100%);
        pointer-events: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-uptime__track:has(> .kp-skeleton)::after {
            animation: kp-sig-solstice-solstice-light 3600ms ease-in-out infinite;
        }
        [data-theme='solstice'] .kp-uptime__cell {
            transition:
                block-size var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch),
                box-shadow var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch);
        }
    }
    @media (prefers-reduced-motion: reduce) {
        [data-theme='solstice'] .kp-uptime__track:has(> .kp-skeleton)::after {
            transform: translateX(85%);
        }
    }
}

/* ── Rows, checks, choices, a card's four states and the drawings, in this theme [kpadopt4-rows] ──
   A row is a plate lit from its foot: its state is the light on its start edge (new: the sun's amber, in flight: its
   cooler light, a warning the ochre sky, a failure the red one, the next one up the sun risen under it); what is done
   goes quiet by ink, not by opacity (G13, G7, G15). A tile of choices is a plate whose pick is the halo and whose
   pointer raises the sun (G8, G16). Waiting is the busy card in the theme's own spinner, the sun on its arc (G10). */
@layer kp.signature {
    [data-theme='solstice'] .kp-action-list--lead > li {
        --kp-so-edge: transparent;
        --kp-so-sky: transparent;
        --kp-action-list-bar: 3px;
        border-inline-start-color: var(--kp-so-edge);
        border-start-start-radius: 2px;
        border-end-start-radius: 2px;
        background: linear-gradient(to top, hsl(from var(--kp-so-sky) h s l / 0.16), transparent 70%);
    }
    [data-theme='solstice'] .kp-action-list--lead > li[data-kp-state='new'] {
        --kp-so-edge: var(--primary);
        --kp-so-sky: var(--accent);
    }
    [data-theme='solstice'] .kp-action-list--lead > li[data-kp-state='active'] {
        --kp-so-edge: var(--info-foreground);
        --kp-so-sky: var(--info-foreground);
    }
    [data-theme='solstice'] .kp-action-list--lead > li[data-kp-state='warn'] {
        --kp-so-edge: hsl(from var(--warning) h s 50%);
        --kp-so-sky: hsl(from var(--warning) h s 50%);
    }
    [data-theme='solstice'] .kp-action-list--lead > li[data-kp-state='failed'] {
        --kp-so-edge: var(--destructive);
        --kp-so-sky: var(--destructive);
    }
    [data-theme='solstice'] .kp-action-list--lead > li[data-kp-state='next'] {
        --kp-so-edge: var(--primary);
        --kp-so-sky: var(--primary);
        background:
            linear-gradient(var(--primary), var(--primary)) 0 100% / 100% 2px no-repeat,
            linear-gradient(to top, hsl(from var(--primary) h s l / 0.26), transparent 85%);
    }
    [data-theme='solstice'] .kp-action-list--lead > li:is([data-kp-state='done'], [data-kp-state='past']) {
        background: none;
    }
    [data-theme='solstice'] .kp-action-list--lead > li[data-kp-state='next'] > .kp-action-list__lead {
        color: var(--primary);
        text-shadow: 0 0 0.6em hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='solstice'] .kp-action-list__title {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.0625rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-action-list--lead > li:is([data-kp-state='done'], [data-kp-state='past']) .kp-action-list__title {
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-action-list__when > :first-child {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.0625rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-action-list > li.kp-action-list__group {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.9375rem;
        font-weight: 400;
        letter-spacing: 0.01em;
        text-transform: none;
    }
    [data-theme='solstice'] .kp-action-list__payload {
        border-radius: calc(var(--radius) * 0.6);
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.12), transparent 50%), var(--muted);
    }
    [data-theme='solstice'] [data-kp-row-keys] > li:focus-visible {
        box-shadow: inset 0 -2px 0 var(--primary);
    }

    /* A check with a reservation: the sky ochre, the mark lit in the warning ink; the fix is a sentence in the serif. */
    [data-theme='solstice'] .kp-statusrow[data-state='warn'] {
        --kp-so-sky: hsl(from var(--warning) h s 50%);
        --kp-so-foot: hsl(from var(--warning) h s 50%);
        --kp-statusrow-state-edge: var(--border);
    }
    [data-theme='solstice'] .kp-statusrow[data-state='warn'] .kp-statusrow__detail {
        color: var(--warning-foreground);
    }
    [data-theme='solstice'] .kp-statusrow[data-state='warn'] .kp-statusrow__mark {
        background: linear-gradient(to top, hsl(from var(--warning) h s l / 0.7), hsl(from var(--warning) h s l / 0.25));
        box-shadow: 0 0 0.5rem hsl(from var(--warning) h s 50% / 0.45);
    }
    [data-theme='solstice'] .kp-statusrow__fix {
        font-family: var(--theme-font-display, inherit);
        font-size: 1rem;
    }

    /* Choices as tiles. */
    [data-theme='solstice'] .kp-fieldset[data-kp-layout='tiles'] {
        --kp-field-tile-radius: var(--radius);
    }
    [data-theme='solstice'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
        position: relative;
        border-color: var(--border-strong);
        background:
            linear-gradient(hsl(from var(--primary) h s l / 0.5), hsl(from var(--primary) h s l / 0.5)) 0 100% / 100% 1px no-repeat,
            linear-gradient(to top, hsl(from var(--accent) h s l / 0.18), transparent 45%),
            var(--card);
    }
    [data-theme='solstice'] .kp-field__option-title {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.0625rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:hover:not(:has(> .kp-field__check:disabled)) {
        border-color: var(--border-strong);
        background:
            linear-gradient(var(--primary), var(--primary)) 0 100% / 100% 2px no-repeat,
            linear-gradient(to top, hsl(from var(--primary) h s l / 0.3), transparent 75%),
            var(--card);
    }
    [data-theme='solstice'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:checked) {
        border-color: var(--border-strong);
        background:
            linear-gradient(var(--primary), var(--primary)) 0 100% / 100% 2px no-repeat,
            linear-gradient(to top, hsl(from var(--primary) h s l / 0.34), transparent 85%),
            var(--card);
        box-shadow:
            0 0 0 2px var(--card),
            0 0 0 4px var(--primary),
            0 0 0.9rem 0.1rem hsl(from var(--primary) h s l / 0.35);
    }
    [data-theme='solstice'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option:has(> .kp-field__check:disabled) {
        background: var(--muted);
        box-shadow: none;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-fieldset[data-kp-layout='tiles'] > .kp-field__option {
            transition:
                background-color var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch),
                box-shadow var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch);
        }
    }

    /* A card in four data states: the title of its note in the serif; a failure reddens the card's own sky; the data
       that returns rises into its place (G9). */
    [data-theme='solstice'] .kp-card__state-title {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.25rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-card[data-kp-state='error'] > .kp-card__stage > .kp-card__state .kp-card__failure {
        background:
            linear-gradient(var(--destructive), var(--destructive)) 0 100% / 100% 1px no-repeat,
            linear-gradient(to top, hsl(from var(--destructive) h s l / 0.2), transparent 70%);
        /* On the card's dark sky the package's destructive-foreground (a dark red) left "why" unreadable. */
        color: var(--foreground);
    }
    [data-theme='solstice'] .kp-card[data-kp-state='error'] > .kp-card__stage > .kp-card__state .kp-card__state-title {
        color: hsl(from var(--destructive) h s 68%);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-card[data-kp-state='ready'] > .kp-card__stage > .kp-card__data {
            animation: kp-sig-solstice-solstice-dawn calc(var(--kp-sig-solstice-contact) * 3) var(--kp-sig-solstice-come) both;
        }
    }

    /* The drawings: the low sun's set, drawn up from the horizon, each stroke along its own length on the sine, the sun
       first (G1, G2). The empty state's own small sun gives way to the drawing. */
    [data-theme='solstice'] .kp-empty[data-kp-art]::before {
        display: none;
    }
    [data-theme='solstice'] .kp-art {
        display: block;
        --kp-art-stroke: 1.75px;
        --kp-art-rule: var(--primary);
        --kp-art-line: var(--border-strong);
        --kp-art-ink: var(--muted-foreground);
        --kp-art-red: hsl(from var(--destructive) h s 62%);
    }
    [data-theme='solstice'] .kp-art > g[data-kp-art-set='lowsun'] {
        display: inline;
    }
    [data-theme='solstice'] .kp-art path {
        stroke-linecap: round;
        stroke-linejoin: round;
    }
    [data-theme='solstice'] .kp-art path.kp-art__rule {
        filter: drop-shadow(0 0 3px hsl(from var(--primary) h s l / 0.55));
    }
    [data-theme='solstice'] .kp-art path.kp-art__red {
        filter: drop-shadow(0 0 3px hsl(from var(--destructive) h s l / 0.5));
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-art path {
            stroke-dasharray: 1;
            animation: kp-sig-solstice-art-rise calc(var(--kp-sig-solstice-contact) * 3) var(--kp-sig-solstice-come) both;
            animation-delay: calc(var(--kp-art-i, 0) * var(--kp-sig-solstice-contact) * 0.375);
        }
    }
    @keyframes kp-sig-solstice-art-rise {
        from {
            stroke-dashoffset: 1;
            opacity: 0;
        }
        20% {
            opacity: 1;
        }
        to {
            stroke-dashoffset: 0;
            opacity: 1;
        }
    }
}

/* ── Flows and records, in this theme [kpadopt4-flows] ──
   A secret is a figure the day keeps under a cover: its time running out is the sun's own travel, a rule with the sun at
   its head that sets at the end (G10, G16); a value shown rises into its line (G9). A dialog's sections are divided by
   the horizon with its one rust peak, and the danger section reddens its own sky (G13). A moment on the timeline is a
   small sun, a stretch a lit hillside; a journey is the sun's path, the step it stands at the sun risen (G16); the
   pipeline's lanes and cards are plates lit from their foot, pointing raises the sun under a card (G7, G8). */
@layer kp.signature {
    [data-theme='solstice'] .kp-secret {
        --kp-secret-drain: linear-gradient(to right, var(--accent), var(--primary));
        --kp-secret-drain-size: 3px;
    }
    [data-theme='solstice'] .kp-secret__value {
        border-radius: calc(var(--radius) * 0.7);
        border-color: var(--border-strong);
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.16), transparent 60%), var(--muted);
        box-shadow: inset 0 -1px 0 hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='solstice'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__value {
        box-shadow: inset 0 -2px 0 var(--primary);
    }
    [data-theme='solstice'] .kp-secret[data-kp-secret-state='disabled'] .kp-secret__value {
        background: transparent;
        box-shadow: none;
    }
    [data-theme='solstice'] .kp-secret__drain {
        position: relative;
        border-radius: 2px;
        background: var(--kp-secret-drain);
        overflow: visible;
    }
    [data-theme='solstice'] .kp-secret__drain::after {
        content: '';
        position: absolute;
        inset-block-start: 50%;
        inset-inline-end: 0;
        inline-size: 0.5rem;
        aspect-ratio: 1;
        translate: 50% -50%;
        border-radius: 50%;
        background: var(--primary);
        box-shadow: 0 0 0.45rem 0.1rem hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='solstice'] .kp-secret__line {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.9375rem;
    }
    [data-theme='solstice'] .kp-secret[data-kp-secret-state='error'] .kp-secret__words {
        border-inline-start: 0;
        padding-inline: var(--kp-space-sm, 0.5rem);
        border-radius: calc(var(--radius) * 0.5);
        background: linear-gradient(to top, hsl(from var(--destructive) h s l / 0.24), transparent 90%);
        box-shadow: inset 0 -1px 0 var(--destructive);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-secret[data-kp-secret-state='shown'] .kp-secret__text {
            display: inline-block;
            animation: kp-sig-solstice-secret-rise calc(var(--kp-sig-solstice-contact) * 3) var(--kp-sig-solstice-come) both;
        }
    }
    @keyframes kp-sig-solstice-secret-rise {
        from {
            transform: translateY(0.6em);
            clip-path: inset(-0.2em -0.2em 100% -0.2em);
        }
        to {
            transform: none;
            clip-path: inset(-0.2em -0.2em -0.2em -0.2em);
        }
    }

    /* The dialog in sections. */
    [data-theme='solstice'] .kp-dialog__title {
        font-family: var(--theme-font-display, inherit);
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-dialog__section {
        position: relative;
    }
    [data-theme='solstice'] .kp-dialog__section:not(:first-child)::before {
        content: '';
        position: absolute;
        inset-block-start: -1px;
        inset-inline-start: 50%;
        inline-size: 2.5rem;
        block-size: 3px;
        translate: -50% 0;
        background: radial-gradient(ellipse 50% 100% at 50% 0, var(--accent), transparent 70%);
        pointer-events: none;
    }
    [data-theme='solstice'] .kp-dialog__heading {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.125rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-dialog__section--danger {
        border-inline-start: 0;
        padding-inline: var(--kp-space-md, 0.75rem);
        border-radius: calc(var(--radius) * 0.6);
        background: linear-gradient(to top, hsl(from var(--destructive) h s l / 0.2), transparent 80%);
        box-shadow: inset 0 -2px 0 var(--destructive);
    }
    [data-theme='solstice'] .kp-dialog__section--danger:not(:first-child)::before {
        background: radial-gradient(ellipse 50% 100% at 50% 0, var(--destructive), transparent 70%);
    }
    [data-theme='solstice'] .kp-dialog__section--danger .kp-dialog__heading {
        color: hsl(from var(--destructive) h s 72%);
    }
    [data-theme='solstice'] .kp-confirm__dependents {
        border-radius: calc(var(--radius) * 0.7);
        border-color: var(--border-strong);
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.16), transparent 70%), var(--muted);
        box-shadow: inset 0 -1px 0 hsl(from var(--primary) h s l / 0.5);
    }

    /* Moments and stretches on the timeline. */
    [data-theme='solstice'] .kp-gantt {
        --kp-gantt-mark-size: 0.75rem;
    }
    [data-theme='solstice'] :is(.kp-gantt__point, .kp-gantt__mark)::before {
        box-shadow: 0 0 0.45rem hsl(from var(--kp-gantt-mark) h s l / 0.55);
    }
    [data-theme='solstice'] .kp-gantt__point[data-kp-planned]::before {
        box-shadow: none;
    }
    [data-theme='solstice'] .kp-gantt__point:hover::before {
        box-shadow:
            0 0 0 2px var(--card),
            0 0 0 4px var(--primary),
            0 0 0.7rem hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='solstice'] .kp-gantt__zone,
    [data-theme='solstice'] .kp-gantt__band {
        border-inline-style: solid;
        border-inline-color: hsl(from var(--kp-gantt-mark) h s l / 0.5);
        background: linear-gradient(to top, hsl(from var(--kp-gantt-mark) h s l / 0.3), hsl(from var(--kp-gantt-mark) h s l / 0.06));
    }
    [data-theme='solstice'] .kp-gantt__zone[data-kp-lane-zone] {
        border-radius: 3px;
        background: linear-gradient(to top, var(--kp-gantt-mark), hsl(from var(--kp-gantt-mark) h s l / 0.35));
    }
    [data-theme='solstice'] :is(.kp-gantt__zone, .kp-gantt__band)[data-kp-tone='warning'] {
        --kp-gantt-mark: hsl(from var(--warning) h s 50%);
    }
    [data-theme='solstice'] .kp-gantt__count {
        border-radius: calc(var(--radius) * 0.5);
        font-family: var(--theme-font-display, inherit);
        font-size: 0.75rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-gantt__sub {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.8125rem;
    }
    [data-theme='solstice'] .kp-gantt__lane-link {
        text-decoration-color: var(--accent);
        text-decoration-thickness: 1.5px;
    }
    [data-theme='solstice'] .kp-gantt__lane-link:hover {
        text-decoration-color: var(--primary);
        text-decoration-thickness: 2px;
    }

    /* The journey: the sun's path. */
    [data-theme='solstice'] .kp-steplist--journey {
        --kp-journey-rule: 2px;
    }
    [data-theme='solstice'] .kp-steplist--journey > .kp-steplist__item {
        border: 0;
        background: transparent;
    }
    [data-theme='solstice'] .kp-steplist--journey .kp-steplist__title {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.0625rem;
    }
    [data-theme='solstice'] .kp-steplist--journey > .kp-steplist__item + .kp-steplist__item::before {
        background: var(--border-strong);
    }
    [data-theme='solstice'] .kp-steplist--journey > .kp-steplist__item:is([data-state='done'], [data-state='current'])::before {
        background: linear-gradient(to right, var(--accent), var(--kp-step-tone, var(--primary)));
    }
    [data-theme='solstice'] .kp-steplist--journey > .kp-steplist__item[data-state='current'] .kp-steplist__title {
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-steplist--journey .kp-steplist__item[data-state='done']:not([data-kp-tone]) .kp-steplist__mark {
        border-color: var(--primary);
        background: var(--primary);
        color: var(--primary-foreground);
    }
    [data-theme='solstice'] .kp-steplist--journey .kp-steplist__item[data-state='current'] .kp-steplist__mark {
        border-color: var(--kp-step-tone, var(--primary));
        background: var(--kp-step-tone, var(--primary));
        box-shadow:
            0 0 0 4px var(--card),
            0 0 0 5px hsl(from var(--kp-step-tone, var(--primary)) h s l / 0.6),
            0 0 0.9rem 0.2rem hsl(from var(--kp-step-tone, var(--primary)) h s l / 0.45);
    }
    [data-theme='solstice'] .kp-steplist--journey .kp-steplist__item[data-state='failed'] .kp-steplist__mark {
        box-shadow: 0 0 0.6rem hsl(from var(--destructive) h s l / 0.5);
    }
    @container kp-journey (max-width: 30rem) {
        [data-theme='solstice'] .kp-steplist--journey > .kp-steplist__item:not(:last-child)::after {
            background: var(--border-strong);
        }
        [data-theme='solstice']
            .kp-steplist--journey
            > .kp-steplist__item:has(+ .kp-steplist__item:is([data-state='done'], [data-state='current']))::after {
            background: linear-gradient(to bottom, var(--accent), var(--kp-step-tone, var(--primary)));
        }
        [data-theme='solstice'] .kp-steplist--journey > .kp-steplist__item:has(+ .kp-steplist__item[data-state='failed'])::after {
            background: repeating-linear-gradient(180deg, var(--destructive) 0 0.25rem, transparent 0.25rem 0.4375rem);
        }
    }

    /* The pipeline. */
    [data-theme='solstice'] .kp-pipeline__lane {
        border-color: var(--border-strong);
        background:
            linear-gradient(var(--kp-pipeline-tone), var(--kp-pipeline-tone)) 0 100% / 100% 1px no-repeat,
            linear-gradient(to top, hsl(from var(--kp-pipeline-tone) h s l / 0.16), transparent 40%),
            var(--card);
    }
    [data-theme='solstice'] .kp-pipeline__head {
        border-color: transparent;
        border-radius: calc(var(--radius) * 0.7);
        background:
            linear-gradient(var(--kp-pipeline-tone), var(--kp-pipeline-tone)) 0 100% / 100% 2px no-repeat,
            linear-gradient(to top, hsl(from var(--kp-pipeline-tone) h s l / 0.34), hsl(from var(--kp-pipeline-tone) h s l / 0.08));
    }
    [data-theme='solstice'] .kp-pipeline__name {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.0625rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-pipeline__count {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.375rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-pipeline__share {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.8125rem;
    }
    [data-theme='solstice'] .kp-pipeline__card {
        border-radius: calc(var(--radius) * 0.7);
        border-color: var(--border);
        background:
            linear-gradient(hsl(from var(--primary) h s l / 0.4), hsl(from var(--primary) h s l / 0.4)) 0 100% / 100% 1px no-repeat,
            linear-gradient(to top, hsl(from var(--accent) h s l / 0.14), transparent 55%),
            var(--card);
    }
    [data-theme='solstice'] .kp-pipeline__card:hover {
        border-color: var(--border);
        background:
            linear-gradient(var(--primary), var(--primary)) 0 100% / 100% 2px no-repeat,
            linear-gradient(to top, hsl(from var(--primary) h s l / 0.3), transparent 80%),
            var(--card);
    }
    [data-theme='solstice'] .kp-pipeline__card:active {
        box-shadow: inset 0 0 0.5rem hsl(from var(--primary) h s l / 0.4);
    }
    [data-theme='solstice'] .kp-pipeline__card[aria-current='true'] {
        border-color: var(--border);
        box-shadow:
            0 0 0 2px var(--card),
            0 0 0 4px var(--primary),
            0 0 0.8rem hsl(from var(--primary) h s l / 0.35);
    }
    [data-theme='solstice'] .kp-pipeline__card[data-kp-dimmed] {
        background: none;
    }
    [data-theme='solstice'] .kp-pipeline__title {
        font-family: var(--theme-font-display, inherit);
        font-size: 1rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-pipeline__mark {
        border-radius: 50%;
        background: linear-gradient(
            to top,
            hsl(from var(--kp-pipeline-tone, var(--muted-foreground)) h s l / 0.55),
            hsl(from var(--kp-pipeline-tone, var(--muted-foreground)) h s l / 0.15)
        );
        box-shadow: 0 0 0.5rem hsl(from var(--kp-pipeline-tone, var(--muted-foreground)) h s l / 0.4);
        font-family: var(--theme-font-display, inherit);
        font-size: 0.8125rem;
        font-weight: 400;
        text-transform: none;
    }
    [data-theme='solstice'] .kp-pipeline__state {
        border-color: var(--border-strong);
        background:
            linear-gradient(var(--kp-so-foot, var(--primary)), var(--kp-so-foot, var(--primary))) 0 100% / 100% 1px no-repeat,
            linear-gradient(to top, hsl(from var(--kp-so-sky, var(--accent)) h s l / 0.2), transparent 70%),
            var(--card);
    }
    [data-theme='solstice'] .kp-pipeline__state[data-kp-state='error'] {
        --kp-so-sky: var(--destructive);
        --kp-so-foot: var(--destructive);
    }
    [data-theme='solstice'] .kp-pipeline__state[data-kp-state='error'] .kp-pipeline__words {
        border-inline-start: 0;
        padding-inline-start: 0;
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-pipeline__card {
            transition:
                background-color var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch),
                box-shadow var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch);
        }
    }
}

/* ── The ideas, in this theme [kpadopt4-ideas] ──
   A time left is the sun's own day: the disc's sector is the sun still above the horizon, its hub a small sun, and when
   the time is out the last light comes once, overbright, and cools (G3, G10, G16, never a breath that goes on). A command
   is the terminal lit from its foot, the prompt the sun's amber. The compare slider's divider is the horizon and its
   handle the sun on it (G16). A typed confirmation's loss list reddens its own sky (G13). The range's custom pick is the
   halo (G16). */
@layer kp.signature {
    /* Typed confirmation. */
    [data-theme='solstice'] .kp-type-confirm__loses {
        border-inline-start-width: 1px;
        border-radius: calc(var(--radius) * 0.7);
        border-color: var(--border-strong);
        background:
            linear-gradient(var(--destructive), var(--destructive)) 0 100% / 100% 2px no-repeat,
            linear-gradient(to top, hsl(from var(--destructive) h s l / 0.22), transparent 85%),
            var(--muted);
    }
    [data-theme='solstice'] .kp-type-confirm__loses-title {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.0625rem;
        font-weight: 400;
        color: hsl(from var(--destructive) h s 72%);
    }
    [data-theme='solstice'] .kp-type-confirm__name {
        background: linear-gradient(to top, hsl(from var(--primary) h s l / 0.3), transparent 80%), var(--muted);
        box-shadow: inset 0 -1px 0 var(--primary);
        font-weight: 500;
    }
    [data-theme='solstice'] .kp-type-confirm[data-kp-matched] .kp-type-confirm__input {
        box-shadow: inset 0 -2px 0 var(--primary);
    }

    /* Command block. */
    [data-theme='solstice'] .kp-command {
        --kp-command-prompt-ink: var(--primary);
        border-color: var(--border-strong);
        border-radius: var(--radius);
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.12), transparent 50%), var(--card);
        box-shadow: inset 0 -1px 0 hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='solstice'] .kp-command__head {
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.14), transparent);
    }
    [data-theme='solstice'] .kp-command__shell {
        font-weight: 500;
    }
    [data-theme='solstice'] .kp-command__code {
        background: var(--muted);
    }
    [data-theme='solstice'] .kp-command__where {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.875rem;
    }

    /* Visual timer and countdown. */
    [data-theme='solstice'] .kp-timer-disc {
        --kp-timer-disc-fill: var(--primary);
        --kp-timer-disc-marks: var(--border-strong);
        --kp-timer-disc-ring: hsl(from var(--primary) h s l / 0.35);
    }
    [data-theme='solstice'] .kp-timer-disc__face {
        border-color: var(--border-strong);
        background: radial-gradient(ellipse 80% 55% at 50% 100%, hsl(from var(--accent) h s l / 0.3), transparent 75%), var(--card);
    }
    [data-theme='solstice'] .kp-timer-disc__sector {
        filter: drop-shadow(0 0 0.5rem hsl(from var(--primary) h s l / 0.45));
    }
    [data-theme='solstice'] .kp-timer-disc__hub {
        inset: 45%;
        border-color: var(--card);
        background: var(--primary);
        box-shadow: 0 0 0.6rem 0.1rem hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='solstice'] .kp-timer-disc[data-kp-timer-disc-state='ended'] .kp-timer-disc__face {
        box-shadow:
            0 0 0 4px var(--card),
            0 0 0 6px var(--primary),
            0 0 1.4rem 0.2rem hsl(from var(--primary) h s l / 0.4);
    }
    [data-theme='solstice'] :is(.kp-timer-disc__caption, .kp-countdown__name) {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.125rem;
        font-weight: 400;
    }
    [data-theme='solstice'] :is(.kp-timer-disc__status, .kp-countdown__status) {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.9375rem;
    }
    [data-theme='solstice'] .kp-countdown {
        --kp-countdown-ring: hsl(from var(--primary) h s l / 0.35);
        border-color: var(--border-strong);
        background:
            linear-gradient(hsl(from var(--primary) h s l / 0.5), hsl(from var(--primary) h s l / 0.5)) 0 100% / 100% 1px no-repeat,
            linear-gradient(to top, hsl(from var(--accent) h s l / 0.2), transparent 55%),
            var(--card);
    }
    [data-theme='solstice'] .kp-countdown__time {
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-countdown[data-kp-countdown-state='ended'] {
        box-shadow:
            0 0 0 2px var(--card),
            0 0 0 4px var(--primary),
            0 0 1.2rem 0.1rem hsl(from var(--primary) h s l / 0.4);
    }
    [data-theme='solstice'] .kp-countdown[data-kp-countdown-state='ended'] .kp-countdown__time {
        color: var(--primary);
        text-shadow: 0 0 0.5em hsl(from var(--primary) h s l / 0.5);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-timer-disc[data-kp-timer-disc-state='ended'] .kp-timer-disc__face,
        [data-theme='solstice'] .kp-countdown[data-kp-countdown-state='ended'] {
            animation: kp-sig-solstice-last-light calc(var(--kp-sig-solstice-contact) * 3) var(--kp-sig-solstice-touch) 1;
        }
    }
    @keyframes kp-sig-solstice-last-light {
        from {
            filter: brightness(1.45) saturate(1.3);
        }
        to {
            filter: brightness(1) saturate(1);
        }
    }

    /* Range picker. */
    [data-theme='solstice'] .kp-range__custom[aria-pressed='true'] {
        border-color: var(--primary);
        box-shadow:
            0 0 0 2px var(--card),
            0 0 0 4px var(--primary),
            0 0 0.8rem hsl(from var(--primary) h s l / 0.35);
    }
    [data-theme='solstice'] .kp-range__label {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.9375rem;
    }
    [data-theme='solstice'] .kp-range__title {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.125rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-range__panel .kp-field__input[aria-invalid='true'] {
        box-shadow: inset 0 -2px 0 var(--destructive);
    }

    /* Compare slider: the divider is the horizon, the handle the sun standing on it. */
    [data-theme='solstice'] .kp-compare {
        --kp-compare-ink: var(--primary);
        border-color: var(--border-strong);
        box-shadow: inset 0 -1px 0 hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='solstice'] .kp-compare__divider {
        border-inline-start-color: var(--primary);
        box-shadow: 0 0 0.6rem hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='solstice'] .kp-compare__handle {
        border-color: var(--card);
        background: var(--primary);
        color: var(--primary-foreground);
        box-shadow:
            0 0 0 2px hsl(from var(--primary) h s l / 0.5),
            0 0 1rem 0.15rem hsl(from var(--primary) h s l / 0.5);
    }
    [data-theme='solstice'] .kp-compare__handle:focus-visible {
        box-shadow:
            0 0 0 2px hsl(from var(--primary) h s l / 0.5),
            0 0 1.2rem 0.3rem hsl(from var(--primary) h s l / 0.6);
    }
    [data-theme='solstice'] .kp-compare__label {
        border-color: var(--border-strong);
        border-radius: calc(var(--radius) * 0.6);
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.25), transparent), var(--card);
        font-family: var(--theme-font-display, inherit);
        font-size: 0.875rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-compare__failed {
        background: linear-gradient(to top, hsl(from var(--destructive) h s l / 0.2), transparent 70%), var(--muted);
        box-shadow: inset 0 -2px 0 var(--destructive);
    }
}

/* ── The recipe components, in this theme [kpadopt4-recipes] ──
   Everything here is the low sun's: a chip included is the sun, excluded the moon (G16); a row pointed at has the sun
   risen under it; a step comes up into the light (G9); the timer that has run out is the sky reddened; the wheel is a
   day turning, its pointer a sun, the hub the sun it turns round, and it settles on the sine (G1). */
@layer kp.signature {
    /* Three-way chips. */
    [data-theme='solstice'] .kp-segmented[data-kp-segmented='tri'] {
        --kp-glyph-check: '\2600\FE0E';
        --kp-glyph-cross: '\263E\FE0E';
        --kp-tri-out-edge: hsl(from var(--destructive) h s 62%);
        --kp-tri-mark-radius: 50%;
    }
    [data-theme='solstice'] .kp-segmented__mark {
        font-family: var(--theme-font-display, inherit);
        border-width: 1px;
    }
    [data-theme='solstice'] .kp-segmented--chips > .kp-segmented__item[data-kp-segmented-tri='include'] {
        box-shadow: 0 0 14px hsl(from var(--primary) h s l / 0.4);
    }
    [data-theme='solstice'] .kp-segmented--chips > .kp-segmented__item[data-kp-segmented-tri='exclude'] {
        background: linear-gradient(to top, hsl(from var(--destructive) h s l / 0.25), transparent 85%), var(--kp-chip-ground, var(--card));
        box-shadow: inset 0 -2px 0 var(--kp-tri-out-edge);
    }
    [data-theme='solstice'] .kp-segmented__item[data-kp-segmented-tri='exclude'] > .kp-segmented__mark {
        background: transparent;
        border-color: var(--kp-tri-out-edge);
        color: var(--kp-tri-out-edge);
    }
    [data-theme='solstice'] .kp-segmented__item[data-kp-segmented-tri='include'] > .kp-segmented__mark::before {
        color: var(--kp-chip-on-ink, var(--background));
    }
    [data-theme='solstice'] .kp-segmented__summary {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.9375rem;
    }
    @media (hover: hover) {
        [data-theme='solstice'] .kp-segmented--chips:not([aria-disabled='true']) > .kp-segmented__item[data-kp-segmented-tri]:hover {
            box-shadow:
                inset 0 -2px 0 var(--primary),
                0 0.3rem 0.5rem -0.3rem hsl(from var(--primary) h s l / 0.7);
        }
    }

    /* Quantity. */
    [data-theme='solstice'] .kp-quantity__field {
        border-color: var(--border-strong);
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.14), transparent 55%), var(--background);
        box-shadow: inset 0 -1px 0 hsl(from var(--primary) h s l / 0.45);
    }
    [data-theme='solstice'] .kp-quantity__field:has(.kp-quantity__input:focus-visible) {
        box-shadow: inset 0 -2px 0 var(--primary);
    }
    [data-theme='solstice'] .kp-quantity__field:has(.kp-quantity__input[aria-invalid='true']) {
        box-shadow: inset 0 -2px 0 var(--destructive);
    }
    [data-theme='solstice'] .kp-quantity__input {
        font-family: var(--theme-font-display, inherit);
        font-weight: 400;
        font-size: calc(var(--kp-quantity-size, 1rem) * 1.15);
    }
    [data-theme='solstice'] .kp-quantity__unit {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.9375rem;
    }

    /* Checklist. */
    [data-theme='solstice'] .kp-checklist__status {
        font-family: var(--theme-font-display, inherit);
        font-size: 0.9375rem;
    }
    [data-theme='solstice'] .kp-checklist__head {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.1875rem;
        font-weight: 400;
    }
    [data-theme='solstice'] .kp-checklist__group[data-kp-checklist-done] .kp-checklist__count::before {
        content: '\2600\FE0E\00a0';
        color: var(--primary);
    }
    [data-theme='solstice'] .kp-checklist__label {
        font-family: var(--theme-font-display, inherit);
        font-size: 1.0625rem;
    }
    [data-theme='solstice'] .kp-checklist__row {
        border-radius: calc(var(--radius) * 0.6);
    }
    [data-theme='solstice'] .kp-checklist__row:hover {
        background:
            linear-gradient(var(--primary), var(--primary)) 0 100% / 100% 2px no-repeat,
            linear-gradient(to top, hsl(from var(--accent) h s l / 0.3), transparent 85%);
    }
    [data-theme='solstice'] .kp-checklist__item[data-kp-checklist-checked] .kp-checklist__label {
        text-decoration-color: var(--accent);
    }
    [data-theme='solstice'] .kp-checklist__empty {
        border-radius: var(--radius);
        border-color: var(--border-strong);
        background: linear-gradient(to top, hsl(from var(--accent) h s l / 0.12), transparent 60%);
        font-family: var(--theme-font-display, inherit);
    }
    [data-theme='solstice'] .kp-checklist__empty[data-kp-checklist-failed] {
        border-style: solid;
        border-color: var(--border-strong);
        background:
            linear-gradient(var(--destructive), var(--destructive)) 0 100% / 100% 2px no-repeat,
            linear-gradient(to top, hsl(from var(--destructive) h s l / 0.22), transparent 80%);
    }
    @media (prefers-reduced-motion: no-preference) {
        [data-theme='solstice'] .kp-checklist__row {
            transition: background-color var(--kp-sig-solstice-contact) var(--kp-sig-solstice-touch);
        }
    }

    /* Timers. */
    [data-theme='solstice'] .kp-timer {
        border-color: var(--border-strong);
        background:
            linear-gradient(hsl(from var(--primary) h s l / 0.5), hsl(from var(--primary) h s l / 0.5)) 0 100% / 100% 1px no-repeat,
            linear-gradient(to top, hsl(from var(--accent) h s l / 0.2), transparent 55%),
            var(--card);
    }
    [data-theme='solstice'] .kp-timer__name {
